INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 1, '1. በአላህ ስም እጅግ በጣም ሩህሩህ በጣም አዛኝ በሆነው (እጀምራለሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 2, '2. ምስጋና ሁሉ ለዓለማቱ ጌታ ለአሏህ ይገባው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 3, '3. እጅግ በጣም ሩህሩህ በጣም አዛኝ ለሆነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 4, '4. የፍርዱ ቀን ባለቤት ለሆነው (ለአላህ ብቻ ይገባው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 5, '5. (ሙስሊሞች ሆይ! ጌታችሁን) አንተን ብቻ እንገዛለን:: ካንተም ብቻ እርዳታን እንለምናለን (በሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 6, '6. ቀጥተኛውን መንገድ ምራን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (1, 7, '7. የእነዚያን ለእነርሱ በጎ የዋልክላቸውን፤ በእነርሱ ላይ ያልተቆጣህባቸውንና ያልተሳሳቱትንም ሰዎች መንገድ (ምራን በሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 1, '1. አሊፍ ፤ ላም፤ ሚም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 2, '2. ይህ መጽሐፍ (ቁርኣን) (ከአላህ የተወረደ ለመሆኑ) ምንም ጥርጥር የለበትም:: አላህን ለሚፈሩም ሁሉ መመሪያ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 3, '3. ለእነዚያ በሩቁ ነገር ለሚያምኑት፤ ሶላትንም ደንቡን ጠብቀው ለሚሰግዱት፤ ከሰጠናቸዉ ሲሳይም ለሚለግሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 4, '4. ለእነዚያም ወደ አንተ በተወረደው መጽሐፍና ካንተ በፊትም በተወረዱት መጽሐፍት ሁሉ ለሚያምኑ፤ በመጨረሻው ቀን መኖርም ለሚያረጋግጡ ሰዎች ሁሉ (መመሪያ ነው)፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 5, '5. እነዚያ (የተጠቀሱትን ባህሪያት የሚላበሱ ሰዎች ሁሉ) በጌታቸው መመሪያ ላይ በትክክል የሚጓዙ ናቸው:: ፍላጎታቸውን ያገኙትም እነርሱ ብቻ ናቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ (በአላህ ፤ በአንተ መልዕክተኛነትና በአላህ አናቅጽ) የካዱት ሰዎች ብታስጠነቅቃቸዉም ባታስጠነቅቃቸዉም ለእነርሱ ሁሉም እኩል ነው:: (ምንም ለውጥ አያመጣም) አያምኑምና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 7, '7. አላህ እነዚያ እውነትን እያወቁ የካዱ ሰዎችን በልቦቻቸው እና በመስሚያቸው ላይ አትሞባቸዋል:: በዓይኖቻቸው ላይም መሸፈኛ አለ:: ለእነርሱም በጀሀነም ውስጥ ከባድ ቅጣት አለባቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 8, '8. ከሰዎች መካከል ለይስሙላ «በአላህና በመጨረሻው ቀን አምነናል» የሚሉ ክፍሎች አሉ:: እነርሱ ግን (የሚዋሹ እንጂ) ትክክለኛ አማኞች አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 9, '9. አላህንና እነዚያን በትክክል በአላህ ያመኑትን ሰዎች ያታልላሉ:: ነገር ግን በዚህ ተግባራቸው ነፍሶቻቸውን እንጂ ሌላን ማንንም አያታልሉም:: እነርሱ ግን ይህ መሆኑን በትክክል አያውቁም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 10, '10. በልቦቻቸው ውስጥ (የንፍቅና) በሽታ ሰርጿል:: አላህም ሌላን በሽታ ጨመረባቸው:: ለእነርሱም ይዋሹ በነበሩበት ምክንያት አሳማሚ ቅጣት አለባቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 11, '11. በምድር ላይ ሁከትን አትፍጠሩ በተባሉ ጊዜ እኛ እኮ አስተካካዮች ነን ይላሉ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 12, '12. (ሙስሊሞች ሆይ!) አስተውሉ:: አጥፊዎች እነርሱ ብቻ ናቸው:: ግን እነርሱ ይህንን አይገነዘቡም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 13, '13, «ሰዎቹ እንዳመኑት ሁሉ እናንተም እመኑ» በተባሉ ጊዜ «ቂሎቹ እንዳመኑት እናምናለንን?» ይላሉ። (ሙስሊሞች ሆይ!) አስተዉሉ። ቂሎቹ እነርሱ ብቻ ናቸው:: እነርሱ ግን ይህንን አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 14, '14. ከእነዚያ በአላህ በትክክል ካመኑት ሰዎች ጋር በተገናኙ ጊዜ «እኛም (ልክ እንደ እናንተው) አምነናል» ይላሉ። ወደ ሰይጣኖቻቸው ባገለሉ ጊዜ ደግሞ «እኛ እኮ ከእናንተ ጋር ነን፤ እኛ በእነርሱ ተሳላቂዎች ብቻ ነን» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 15, '15. አላህ በእነርሱ ይሳለቅባቸዋል:: በአመጻቸዉም ውስጥ የሚዋልሉ ሲሆኑ ያቆያቸዋል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 16, '16. እነዚህ እነዚያ ስህተትን በቅንነት የገዙ (የለወጡ) ሰዎች ናቸው:: እናም ንግዳቸው ትርፋማ አይደለም:: ቅኑን መንገድም አልተከተሉም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 17, '17. የእነርሱ ንፍቅና ምሳሌ ልክ እንደዚያ እሳትን እንዳነደደና ከዚያ በዙሪያው ያለውን ሁሉ ባበራችለት ጊዜ አላህ ብርሃናቸውን እንደወሰደባቸው እና በጨለማዎች ውስጥ የማያዩ ሆነው እንደተዋቸው ብጤ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 18, '18. እነርሱ (ሓቅን የማይሰሙ) ደንቆሮዎች፤ (ሓቅን የማይናገሩ) ዲዳዎች፤ (ሓቅን የማያዩ) እውሮች ናቸው:: ስለዚህ እነርሱ (ከስህተት) አይመለሱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 19, '19. ወይም (ምሳሌያቸው) ከሰማይ እንደወረደ ዝናብ (ባለቤቶች) ነው:: በእርሱ (በደመናው) ውስጥ ጨለማዎች፤ ነጎድጓድና ብልጭታ ያሉበት ሲሆን ከመብረቆቹ ሊመጣ ከሚችል ጥቃት ሞትን በመፍራት ጣቶቻቸውን በጆሮዎቻቸው ውስጥ እንደሚያደርጉ ሰዎች ቢጤ ነው:: አላህ ከሓዲያንን (በእውቀቱ) ከባቢ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 20, '20 ብልጭታው ዓይኖቻቸውን ሊነጥቅ ይቀርባል:: ለእነርሱ ባበራላቸው ቁጥር በውስጡ ይሄዳሉ:: በእነርሱም ላይ ባጨለመባቸው ጊዜ ደግሞ ይቆማሉ:: አላህ በፈለገ ኖሮ መስሚያዎቻቸውንና ማያዎቻቸውን ይወስድባቸው ነበር:: አላህ በነገሮች ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 21, '21. እናንተ ሰዎች ሆይ! ያን እናንተንና እነዚያን ከናንተ በፊት የነበሩትን የፈጠረውን ጌታችሁን (አላህን) በብቸኝነት ተገዙት:: ቅጣትን ልትጠነቀቁ ዘንድ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 22, '22. እርሱ (አላህ) ያ ለእናንተ ምድርን ምንጣፍ፤ ሰማይን ጣራ ያደረገ ጌታ ነው::ከሰማይ ዳመና ውሃን ያወረደና ከዚያ በውሃው ከፍሬዎች ሁሉ ለእናንተ ሲሳይን ያወጣላችሁ ነው:: እናም (ብቸኛ ፈጣሪነቱን) የምታውቁ ስትሆኑ ለአላህ (በአምልኮ) አጋሮችን አታድርጉ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 23, '23. (እናንተ ሰዎች ሆይ!) በአገልጋያችን (በሙሐመድ) ላይ ባወረድነው (ቁርኣን) በመጠራጠር ላይ ከሆናችሁም ከእርሱ ጋር ሊወዳደር የሚችል አንድ ምዕራፍ እንኳን እስቲ አምጡ:: እውነተኞች እንደሆናችሁ ከአላህ ሌላ ረዳቶቻችሁንም ሁሉ ጥሩ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 24, '24. (ይህንን) ባትሰሩ ግን በርግጥም አትሰሩትምና (አትፈጽሙትምና) ከዚያች መቀጣጠያዋ ሰዎችና ድንጋዮች ከሆነው ከገሀነም እሳት ራሳችሁን ጠብቁ:: ለከሓዲያን ሁሉ ተደግሳለችና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ በትክክል በአላህ ያመኑትንና መልካም ተግባራትን የሰሩትን ሰዎች ከስሮቻቸው ወንዞች የሚፈሱባቸው ገነቶች ያሏቸው መሆኑን አብስራቸው:: በእርሷም ፍራፍሬ በተለገሱ ቁጥር (ፍሬዎቿ ስለሚመሳሰሉ) «ይህማ ያ ከአሁን በፊት የተመገብነው ነው።» ይላሉ:: (እርሱ ተመሳሳይ ሆኖ ይሰጣቸዋል) ለእነርሱም በውስጧ ንጹህ ሚስቶች አሏቸው:: እነርሱም በውስጧ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 26, '26. አላህ ማንኛውንም ነገር ትንኝም ትሁን ከሷም በላይ የሆነን ነገር ምሳሌ ከማድረግ አያፍርም። እነዚያማ ያመኑት ምሳሌው ከጌታቸው የተነገረ እውነት መሆኑን ያውቃሉ:: እነዚያ የካዱ ግን «አላህ በዚህ አባባል ምንን ምሳሌ ፈልጎበት ነው?» ይላሉ:: አላህ በምሳሌው ብዙዎችን ያሳስታል:: በእርሱም ብዙዎችን ያቀናል:: በእርሱም አመጸኞችን እንጂ ሌላን አያሳስትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 27, '27. እነዚያ የአላህን ቃል ኪዳን ከጠበቀ በኃላ የሚያፈርሱ፤ እንዲቀጠልም አላህ ያዘዘውን ነገር የሚቆርጡ፤ በምድር ላይ ሁከት የሚፈጥሩ ከሳሪዎች እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 28, '28. (እናንተ ከሓዲያን ሆይ!) ሙታን የነበራችሁትን ሕያው ያደረጋችሁ፤ ከዚያም የሚገድላችሁ፤ ከዚያም ሕያው የሚያደርጋችሁና ከዚያም ወደ እርሱ የምትመለሱ ስትሆኑ እንዴት በአላህ ትክዳላችሁ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 29, '29. አላህ ያ በምድር ውስጥ ያለውን ሁሉ ለእናንተ ጥቅም ሲል የፈጠረ ጌታ ነው:: ከዚያም ወደ ሰማይ አሰበና ሰባት ሰማያት አደረጋቸው:: እርሱ ሁሉን ነገር አዋቂ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ለመላዕክት «እኔ በምድር ላይ (ምትክ) ወኪል ላደርግ ነው።» ባለ ጊዜ (የሆነውን ለህዝቦችህ አስታውስ)። «እኛ ከማመስገን ጋር የምናጠራህ፤ የምናሞግስህ ስንሆን በምድር ውስጥ የሚያጠፉትንና ደሞችንም የሚያፈሱትን ታደርጋለህን?» አሉ:: አላህም «እኔ እናንተ የማታውቁትን ነገር ሁሉ አውቃለሁ» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 31, '31. ለአደምም ስሞችን ሁሉ አስተማረው:: ከዚያም በመላዕክት ላይ (ተሰያሚዎቹን) አቀረባቸው። «እውነተኞች ከሆናችሁ የእነዚህን ተሰያሚዎች መጠሪያ ንገሩኝ?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 32, '32. እነርሱም «ጥራት ይገባህ አንተ ካስተማርከን ነገር በስተቀር እኛ ምንም እውቀት የለንም:: አንተ ብቸኛው ጥበበኛና አዋቂው ነህና›› አሉ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 33, '33. አላህም «አደም ሆይ! ስሞቻቸውን ንገራቸው።» አለው። ከዚያም ስሞቻቸውን በነገራቸው ጊዜ «እኔ የሰማያትንና የምድርን ሩቅ ምስጢር አውቃለሁ። የምትገልጹትንና ያንንም ትደብቁት የነበራችሁትን ሁሉ አውቃለሁ አላልኳችሁምን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 34, '34. (መልዕክተኛችን ሙሐመድ ሆይ!) መላዕክትን «ለአደም ስገዱ» ባልን ጊዜ የሆነውን አስታውስ። ከዲያብሎስ በቀር መላዕክት ሁሉም ወዲያውኑ ሰገዱ። እርሱማ እምቢ አለ። ኮራም። ከከሓዲያንም ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 35, '35. «አደም ሆይ! አንተና ሚስትህ በገነት ውስጥ ተቀመጡ:: በእርሷም ዉስጥ በፈለጋችሁት ስፍራ በሰፊው ተመገቡ:: ግን ከበደለኞች ትሆናላችሁና ይህችን ዛፍ አትቅረቡ።» አልናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 36, '36. ሰይጣንም ከእርሷ አሳሳታቸው። ከነበሩበትም ገነት አወጣቸው። «ከፊላችሁ ለከፊሉ ጠላት ሲሆን ሁላችሁም (ወደ ምድር) ውረዱ። ለእናንተም በምድር ላይ እስከተወሰነ ጊዜ ድረስ መርጊያና መጠቀሚያ አላችሁ።» አልናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 37, '37. ከዚያም አደም ከጌታው የመታረቂያ ቃል ተማረ:: ጌታዉም ተማጽኖውን ተቀበለው:: አላህ ጸጸትን ተቀባይና አዛኝ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 38, '38. «ሁላችሁም (አደም፣ ሐዋና ሰይጣን) በአንድ ሆናችሁ ከገነት ወደ (ምድር) ውረዱ አልናቸውም። ከዚያም ከእኔ የሆነ መመሪያ ቢመጣላችሁ መመሪያዬን የተከተሉ በእነርሱ ላይ ስጋትም ትካዜም የለባቸውም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 39, '39. «እነዚያም በመልዕክተኞቻችን የካዱና በራዕያችን ያስተባበሉ ሁሉ ግን እነርሱ በውስጧ ዘውታሪዎች ሲሆኑ የእሳት (ገሀነም) ጓዶች ናቸው።» (አልናቸው።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 40, '40. እናንተ የኢስራኢል ልጆች ሆይ! ያችን በእናንተ ላይ የለገስኳትን ጸጋዬን አስታውሱ:: ቃል ኪዳኔንም ሙሉ:: እኔም ቃልኪዳናችሁን እሞላላችኋለሁና። እኔንም ብቻ ፍሩኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 41, '41. (እናንተ የኢስራኢል ልጆች ሆይ!) ከናንተ ጋር ያለውን መጽሐፍ እውቅና የሚሰጥ ሆኖ ባወረድኩት (ቁርኣን) እመኑ:: በእርሱም የመጀመሪያ ከሓዲያን አትሁኑ:: በአንቃጾቼ ጥቂት ገንዘብ አትለውጡ:: እኔንም ብቻ ፍሩኝ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 42, '42. እውነቱን ከውሸት ጋር አትቀላቅሉ:: እናንተም የምታውቁ ስትሆኑ እውነትን አትደብቁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 43, '43. ሶላትን ደንቡን ጠብቃችሁ ስገዱ:: ዘካንም ለተገቢው አካል ስጡ:: ለጌታችሁም ከአጎንባሾች ጋር አጎንብሱ:: (ከሰጋጆች ጋር ስገዱ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 44, '44. እናንተ መጽሐፍን የምታነቡ ሆናችሁና ሰዎችን በበጎ ስራ እያዘዛችሁ ራሳችሁን በመልካም ምግባር ከማነጽ ትዘነጋላችሁን? አታስተውሉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 45, '45.በመታገስና በሶላትም ተረዱ፡፡ እርሷ (ሶላት) በፈሪዎች ላይ እንጂ በሌላው ላይ በእርግጥ ከባድ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 46, '46. እነዚያ ከጌታቸው ጋር እንደሚገናኙና ወደ እርሱ ተመላሾች መሆናቸውን የሚያረጋግጡ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 47, '50. የእስራኤል ልጆች ሆይ! ያችን በናንተ ላይ የለገስኳትን ጸጋዬንና እኔም በዓለማት ላይ ያበለጥኳችሁ (አባቶቻችሁን በጊዜያቸው ከነበሩት ዓለማት ያበለጥኩዋቸው) መኾኔን አስታውሱ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 48, '48. ማንኛዋም ነፍስ ከሌላዋ ነፍስ ምንንም የማትመነዳበትን፤ ከእርሷም ምልጃን የማይቀበሉባትን፤ ከእርሷም ቤዛ የማይያዝባትንና እነርሱም በየትኛዉም አካል የማይረዱበትን ቀን ቅጣት ፍሩ (ተጠንቀቁ)፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 49, '49. ከፈርዖን ቤተሰቦች (ከጎሳዎቹ) ብርቱን ቅጣት የሚያቀምሷችሁ፤ ወንዶች ልጆቻችሁን የሚያርዱና ሴቶቻችሁን የሚተዉ ሲሆኑ ከእነርሱ ባዳንናችሁ ጊዜ (የሆነውን ታሪክ አስታውሱ)። ያ ክስተት ከጌታችሁ ለእናንተ ታላቅ ፈተና ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 50, '50. (እናንተ የኢስራኢል ልጆች ሆይ!) በእናንተ ምክንያት ባህሩን በከፈልን ጊዜ የሆነውን ታሪክም አስታውሱ:: ወዲያውኑም አዳንናችሁ:: የፈርዖንንም ቤተሰቦች ዓይናችሁ እያየ አሰመጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳ የአርባ ሌሊትን ቀጠሮ ከእኛ በወሰደበት ጊዜ (የሆነውን ታሪክ ለህዝቦችህ አስታውስ):: ከዚያም ከእርሱ (መሄድ) በኋላ እናንተ ራሳችሁን በዳዩች ስትሆኑ ወይፈንን አምላክ አደረጋችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 52, '52. (ቢሆንም) ከዚያ በኋላ ታመሰግኑ ዘንድ ለእናንተ ምህረትን አደርግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 53, '53. (እናንተ የኢስራኢል ልጆች ሆይ! ወደ ትክክለኛው መንገድ) ትመሩ ዘንድ ለሙሳ እውነትንና ውሸትን የሚለይን መጽሐፍ በሰጠነው ጊዜ (የዋልንላችሁን ውለታ አስታውሱ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 54, '54. (የኢስራኢል ልጆች ሆይ!) ሙሳ ለሕዝቦቹ (እንዲህ) ባለም ጊዜ የዋልነውን ውለታ አስታውሱ፡- «ሕዝቦቼ ሆይ! እናንተ ወይፈንን አምላክ በማድረጋችሁ ነፍሶቻችሁን በደላችሁ:: በመሆኑም ወደ ፈጣሪያችሁ ተመለሱ:: ከመካከላችሁ ወንጀለኛ ወገኖቻችሁን ግደሉ:: ይሃችሁ ድርጊት በፈጣሪያችሁ ዘንድ ለእንናተ በላጭ ነው። በእናንተም ላይ ምህረቱን አወረደ:: እነሆ እርሱ (አላህ) ጸጸትን ተቀባይ ምህረተኛ አዛኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 55, '55. (የኢስራኢል ልጆች ሆይ!) «ሙሳ ሆይ! አላህን በይፋ እስከምናይ ድረስ ለአንተ በፍጹም አናምንልህም።» ባላችሁ ጊዜ (የሆነውን ታሪክ አስታውሱ)። እናንተም በዓይናችሁ እየተመለከታችሁ መብረቅ መታችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 56, '56. ከዚያም ታመሰግኑ ዘንድ ከሞታችሁ በኋላ አስነሳናችሁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 57, '57. (የኢስራኢል ልጆች ሆይ!) በናንተ ላይ ዳመናን አጠለልን:: እንደ ነጭ ማር ያለ «መንን» እና ድርጭትን ለምግብነት አወረድን:: «ከሰጠናችሁም ጣፋጮችን።» ብሉ አልን:: እኛን አልበደሉንም:: ነፍሶቻቸውን ግን ይበድሉ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 58, '58. (የኢስራኢል ልጆች ሆይ!) «ወደዚህች ከተማ ግቡ። ከእርሷም ከፈለጋችሁት ስፍራ የፈለጋችሁት መልኩ ተመገቡ:: በሩንም አጎንበሳችሁ ግቡ:: ‹ጥያቄያችንም የኃጢአቶቻችን መሰረዝ ነው።› በሉ:: ኃጢአቶቻችሁን እንምራለን ለበጎ ሰሪዎችም ምንዳ እንጨምርላቸዋለን።» ባልን ጊዜ የሆነውን አስታውሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 59, '59. እነዚያም እራሳቸውን የበደሉት እነርሱ ከተባሉት ሌላን ቃል ለወጡ። በነዚያም በበደሉት ላይ ያመጹ በመሆናቸው ምክንያት መቅሰፍትን ከሰማይ አወረድንባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 60, '60. (የኢስራኢል ልጆች ሆይ!) ሙሳ ለሕዝቦቹ የመጠጥ ውሃን በፈለገ ጊዜ የሆነውን ታሪክ አስታውሱ:: «ድንጋዩን በዘንግህ ምታው።» አልነው:: መታዉም ከእርሱም አስራ ሁለት ምንጮች ፈለቁ (ፈነዱ)፤ ሰዎቹ ሁሉ በትክክል መጠጫቸውን አወቁ:: «ከአላህ ሲሳይ ብሉ፤ ጠጡም፤ አመጸኞችም ሆናችሁ በምድር ላይ አታበላሹ።» (አልናቸው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 61, '61. (የኢስራኢል ልጆች ሆይ!) «ሙሳ ሆይ! በአንድ ዓይነት ምግብ ላይ በፍጹም አንታገስም:: ስለዚህ ጌታህ ከእነዚያ ምድር ከምታበቅላቸው ከቅጠላ ቅጠሏ፤ ከዱባዋ፤ ከስንዴዋ፤ ከምስሯና ከሽንኩርቷ ያወጣልን ዘንድ ለምንልን።» (ባላችሁም ጊዜ የሆነውን ታሪክ አስታውሱ):: ሙሳም «ያንን ዝቅተኛ የሆነውን በዚያ ከፍተኛና በላጭ በሆነው ነገር ልትተኩ ትፈልጋላችሁን? ወደ ከተማ ውረዱ:: የጠየቃችሁትን ነገር ታገኛላችሁና።» አላቸው። ውርደትና ድህነት ተጣለባቸው:: በአላህም ቁጣ ተመለሱ:: ይህ እነርሱ በአላህ ተዐምራት ይክዱና ነብያትንም ያለ አግባብ ይገድሉ ስለነበሩ፤ በኃጢአትም ላይ በመዘፈቃቸውና እንዲሁም ወሰንን የሚያልፉ በመሆናቸው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 62, '62. እነዚያ በአላህ ያመኑ፣ እነዚያ አይሁዳውያን፣ ክርስቲያኖችና ሳቢያኖችም ሁሉ ከእነርሱ መካከል በአላህና በመጨረሻው ቀን ያመኑና መልካምን ስራ የሰሩ ሁሉ በእነርሱ ላይ (ምንም ይደርስብናል ብለው) ፍርሀት የለባቸዉም። (ምንም ነገር ያመልጠናል ብለው) አያዝኑምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 63, '63. (የኢስራኢል ልጆች ሆይ!) ከበላያችሁ የጡርን ተራራ ያነሳን ሆነን « (ከእሳት ቅጣት) ትጠበቁ ዘንድ የሰጠናችሁን በርትታችሁ ያዙ:: በውስጡ ያለውን ነገር አስታውሱ።» ብለን የጠበቀ ቃል ኪዳናችሁን በያዝንበት ጊዜ የሆነውን ታሪክ (ልብ በሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 64, '64. ከዚያም ከዚህ በኋላ ቃልኪዳኑን ተዋችሁ:: በእናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ በትክክል ከጠፊ ህዝቦች በሆናችሁ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 65, '65. እነዚያም ከናንተ መካከል በቅዳሜ ቀን አሳን በማጥመድ ወሰን ያለፉትንና ለእነርሱም «ወራዳዎች ዝንጆሮዎች ሁኑ።» ያልናቸውን ሕዝቦች ታሪክ በእርግጥ አወቃችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 66, '66. የመንደሯን ሰዎች ቅጣትም ለእነዚያ በጊዜያቸው ለነበሩትና ለእነዚያም ከበኋላቸው ለሚመጡት ሕዝቦች መቀጣጫ ለፈራሂያንም (ትምህርት) አደረግናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 67, '67. (የኢስራኢል ልጆች ሆይ!) ሙሳ ለህዝቦቹ «አላህ ላም እንድታርዱ ያዛችኋል» ባለም ጊዜ (የሆነውን ታሪክ አስታውሱ)። እነርሱም ለሙሳ «መሳለቂያ ታደርገናለህን?» አሉት። እሱም «ከተሳላቂዎች ከመሆን በአላህ እጠበቃለሁ» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 68, '68. እነርሱም «እስቲ ጌታህን ጠይቅልን:: እርሷ ምን እንደሆነች (እድሜዋን) ያብራራልን ዘንድ» አሉ:: እርሱም «‹እርሷ በውልም ያላረጀች ጥጃም ያልሆነች በዚህ መካከል ልከኛ የሆነች ጊደር ናት።› ይላችኋል። የታዘዛችሁትንም ስሩ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 69, '69. እነርሱም “እስቲ ጌታህን እንደገና ጠይቅልን:: መልኳ ምን እንደሚመስል ይገልጽልን ዘንድ” አሉ:: እርሱም “መልኳ ደማቅ ተመልካቾችን የምታስደስት ዳልቻ ላም ናት ይላችኋል” አላቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 70, '70. ጌታህን ጠይቅልን :: እርሷ ምን እንደሆነች ይግለጽልን:: ምክንያቱም ላሞቹ በሙሉ በእኛ ላይ ተመሳሰሉብን:: እኛም አላህ የሻ እንደሆነ በእርግጥ (ትክክለኛውን አቅጣጫ የምንይዝ) ተመሪዎች ነን” አሉ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 71, '71. እርሱም: «‹እርሷ ያልተገራች ምድርን በማረስ የማታስነሳ፤ እርሻንም የማታጠጣ፤ ከነውር ሁሉ ነፃ የሆነች፤ ጸያፍ ምልክት የሌለባት ናት።› ይላችኋል አላቸው።» እነርሱም «አሁን ገና በትክክል መጣህ።» አሉ:: ከዚያ ትዕዛዙን ላለመፈጸም የቀረቡ ሆነው ላሟን አረዷት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 72, '72. (የኢስራኢል ልጆች ሆይ!) ነፍስ በገደላችሁና በእርሷም ጉዳይ በተከራከራችሁ ጊዜ የሆነውን ታሪክ አስታውሱ:: አላህ ያን በውስጣችሁ ትደብቁት የነበራችሁትን ሚስጢር ሁሉ ገላጭ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 73, '73. (የሙቱን በድን) «በታረደችው ላም ከፊል አካል ምቱት አልን »:: (እናም መቱትና ተነሳ:: የገደለው ማን እንደሆነ ነገራቸውና እንደገና ሞተ::) ሰዎች ሆይ! ልክ እንደዚሁ ትገነዘቡና ታውቁ ዘንድ ሙታንን ህያው በማድረግ ተዓምራቶቹን ያሳያችኋል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 74, '74. ከዚያም ልቦቻቸው ከዚህ (ትዕይንት) በኋላ ደረቁ:: እርሷም በድርቅና እንደ አለት ድንጋዩች ወይም ከእርሱ ይበልጥ የበረቱ ናቸው:: ምክንያቱም ከድንጋዩች መካከል ጅረቶች (ወንዞች) የሚፈሱበት፤ ከእነርሱም የሚሰነጥቅና ከእርሱ ውሃ ምንጭ የሚወጣው፤ ከእነርሱም አላህን ከመፍራቱ የተነሳ ወደ ታች የሚወርድ አለና:: አላህ ከምትሰሩት ነገር ሁሉ ከአንዱም ዘንጊ አይደለም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 75, '75. ከ(አይሁድ) መካከል የአላህን ቃል የሚሰሙና ከዚያም እውነቱን ከተረዱ በኋላ ሆን ብለው እነርሱ እያወቁ የሚለውጡት ቡድኖች እያሉ ለእናንተ ማመናቸውን ትከጅላላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 76, '76. እነዚያም ያመኑትን ሙስሊሞችን ባገኙ ጊዜ “እኛም እንደናንተው አምነናል” ይላሉ:: እርስ በርሳቸው ብቻ በተገናኙ ጊዜ ግን “አላህ በእናንተ ላይ የገለጸላችሁን ነገር በጌታችሁ ዘንድ እርሱን መረጃ እንዲያቀርቡባችሁ ትነግሯቸዋላችሁን? አታስተውሉምን?” ይባባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 77, '77. አላህ የሚደብቁትንም ሆነ የሚገልጹትን ነገር ሁሉ የሚያውቅ ጌታ መሆኑን አያውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 78, '78. ከእነርሱም መካከል መጽሐፍን የማያውቁ መሃይማን አሉ:: ግን ከንቱ ምኞቶችን ይመኛሉ:: እነርሱም መጠራጠርን እንጂ ትክክለኛ እውቀት የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 79, '79. እነዚያ መጽሐፍን በእጆቻቸው ለሚጽፉና ከዚያ በእርሱ ጥቂት ዋጋን ሊገዙበት ብለው: «ይህ ከአላህ ዘንድ የወረደ ነው» ለሚሉ ሁሉ ወዮላቸው። እነርሱ ከዚያ እጆቻቸው ከፃፉት ወንጀል ወዮላቸው:: እነርሱ ከዚያ ከሚሰሩት ኃጢአት ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 80, '80. (አይሁዶች) “የገሀነም እሳት ለተቆጠሩ ውስን ቀናት ብቻ እንጂ ፈጽሞ አትነካንም” አሉ። (መልዕክተኛችን ሙሐመድ ሆይ!) “በዚህ ጉዳይ ከአላህ ዘንድ ቃል ኪዳን ይዛችኋልን? ይህ ከሆነ አላህም ኪዳኑን አያፈርስም:: ወይስ በአላህ ላይ የማታውቁትን ትናገራላችሁን?” በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 81, '81. እንዴታ እነዚያ መጥፎን ተግባር የሰሩና በኃጢአትም የተከበቡ ሁሉ በእርግጥ የእሳት ጓዶች ናቸው:: እነርሱም በውስጧ ለዘላለም ዘውታሪዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 82, '82. እነዚያም ያመኑና በጎ ስራዎችን የሰሩ ሁሉ የገነት ጓዶች ናቸው። እነርሱም በውስጧ ለዘላለም ዘውታሪዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 83, '83. (የኢስራኢል-ልጆችን) “አላህን እንጂ ሌላን አታምልኩ:: ለወላጆችም በጎን ስራ ስሩ:: ለዝምድና ባለቤቶች፤ ለየቲሞችና ለሚስኪኖችም በጎን ዋሉ:: ለሰዎችም ሁሉ መልካምን ብቻ ተናገሩ :: ሶላትን ደንቡን ጠብቃች ስገዱ:: ዘካን ለተገቢው ስጡ” በማለት ጥብቅ ቃልኪዳን በያዝንባቸው ጊዜ (የሆነውን አስታውሱ):: ከዚያም ከእናንተ ጥቂቶቹ ሲቀሩ ሸሻችሁ:: እናንተ (ቃልኪዳንንም) የምትተው ናችሁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 84, '84. (የኢስራኢል ልጆች ሆይ!) የሕዝቦቻችሁን ደም አታፍስሱ:: ወገኖቻችሁን ከመኖሪያ አገሮቻቸው አታስወጡ በማለት የጠበቀ ቃልኪዳናችሁን በያዝንባችሁ ጊዜ (የሆነውን) አስታውሱ:: ከዚያም በቃል ኪዳኑ ትክክለኛነት አጸናችሁ::እናንተም በዚሁም ትመሰክራላችሁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 85, '85. ከዚያም ቃል ኪዳናችሁን በማፍረስ የምትገድሉ፤ ከናንተም መካከል የሆኑ ሕዝቦችን በኃጢአትና በመበደል ላይ በመተባበር ከአገሮቻቸው የምታስወጡ እናንተው ራሳችሁ ናችሁ:: ምርኮኞች ሆነው ወደ እናንተ ሲመጡም ቤዛ ትሆኗቸዋላችሁ:: እነርሱን ከመኖሪያ ክልላቸው ማባረሩ በእናንተ ላይ የተከለከለ ነው:: በመጽሐፉ በከፊሉ አምናችሁ በሌላው ትክዳላችሁን? ከእናንተ መካከል ይህንን ጸያፍ ተግባር የሚሰራ ሰው ሁሉ ቅጣቱ በቅርቢቱ ሕይወት ውርደት አንጂ ሌላ አይደለም:: በትንሳኤ ቀንም ወደ ብርቱ ቅጣት ይመለሳሉ። አላህ ከምትሰሩት ሁሉ ዘንጊ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 86, '86. እነዚያ ቅርቢቱን ሕይወት በመጨረሻይቱ ዓለም የለወጡ ናቸው። ከእነርሱ ላይም ቅጣቱ ምንጊዜም አይቀለልላቸዉም:: እርዳታም ከማንም አያገኙም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 87, '87. ለሙሳ መጽሐፍን በእርግጥ ሰጠነው:: ከርሱ በኋላም ሌሎች መልዕክተኞችን ልከናል:: የመርየምን ልጅ ዒሳንም ግልጽ ተዐምራትን ሰጠነው:: ቅዱስ መንፈስ (ጅብሪል) በሚባለው መላአክ አበረታነው:: ነፍሶቻችሁ በማትወደው ነገር መልዕክተኛው በመጣላችሁ ቁጥር እነርሱን ከመከተል ይልቅ በትዕቢት ከፊሉን አስተባበላችሁ:: ከፊሉን ደግሞ ትገድላላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 88, '88. “ልቦቻችን ድፍኖች ናቸው” አሉ:: (እውነታው ግን ይህ አይደለም)። አላህ በክህደታቸው ምክንያት ረገማቸው። በመሆኑም ጥቂትን እንጂ አያምኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 89, '89. ከእነርሱ ጋር ያለውን መጽሐፍ አረጋጋጭ የሆነ መጽሐፍ ከአላህ ዘንድ በመጣላቸው ጊዜ ከመምጣቱ በፊት በእነዚያ በካዱት ላይ ይረዱበት የነበሩ ሲሆኑ ያ ቀድሞውኑ ያውቁት የነበረ ነገር በመጣላቸው ጊዜ በእርሱ ካዱ:: እናም የአላህ እርግማን በካሐዲያን ላይ ይሁን፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 90, '90. ነፍሶቻቸውን የሸጡበት (የለወጡበት) ነገር ከፋ! ይኸዉም አላህ ከባሮቹ በሚሻው ሰው ላይ ችሮታውን ማውረዱን በመመቅኘት አላህ ባወረደው ነገር መካዳቸው ነው:: እናም የአላህን ቁጣ በተደጋጋሚ አትርፈዋል:: ለካሐዲያንም አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 91, '91. «አላህ ባወረደው እመኑ» በተባሉ ጊዜ «በእኛ ላይ በተወረደው መጽሐፍ ብቻ እናምናለን» ይላሉ:: ከእርሱ ኋላ የመጣው ቁርኣን ምንም እንኳን ከእነርሱ ጋር ላለው መጽሐፍ አረጋጋጭና ትክክለኛ የሆነ ቢሆንም ይክዳሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «ትክክለኛ አማኞች ከሆናችሁ ከአሁን በፊት የአላህን ነብያትን ለምን ገደላችሁ?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 92, '92. ሙሳ በግልጽ መረጃ ታጅቦ ወደ እናንተ መጥቶ ነበር:: ግን እርሱ በሌለበት ወይፈንን አምላክ አደረጋችሁ:: አጥፊዎች ነበራችሁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 93, '93. የጡርን ጋራ ከበላያችሁ በማንሳት (በተውራት ሕግ እንደትሰሩ) ቃል ኪዳናችሁን በያዝን ጊዜ (የሆነውን አስታውሱ):: «የሰጠናችሁን በጽናት ያዙ:: ያልነውንም ስሙ።» አልን:: «ሰማን ግን አመጽን» አሉ:: የወይፈኑም ውዴታ በክህደታቸው ምክንያት በልቦቻቸው ውስጥ ገብቷል:: «ትክክለኛ አማኞች እንደሆናችሁ እምነታችሁ የሚያዛችሁ ነገር የከፋ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 94, '94. (መልዕክተኛችን ሙሐመድ ሆይ! ለአይሁድ) «የመጨረሻይቱ አገር ገነት በአላህ ዘንድ ከሌሎች በተለየ ለእናንተ ብቻ በመሆኗ እውነተኞች ከሆናችሁ እስቲ ሞትን ተመኙ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 95, '95. እጆቻቸው (ባሳለፉት) በሰሩት ወንጀል ምክንያት ሞትን ምንጊዜም ፈጽሞ አይመኙትም:: አላህ በዳዩችን አዋቂ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 96, '96. (መልዕክተኛችን ሙሐመድ ሆይ!) አይሁድ ሁሉ እና ከእነዚያ ጣኦትን በአላህ ካጋሩት ይበልጥ በሕይወት ላይ የሚጓጉ ሆነው በእርግጥ ታገኛቸዋለህ:: ለአንዳቸውም አንድ ሺህ ዓመት ዕድሜ ቢሰጥ ይወዳል:: እርሱም (ዕድሜ መሰጠቱ) ከቅጣት የሚያድነው አይደለም:: አላህም የሚሰሩትን ሁሉ ተመልካች ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 97, '97. (መልዕክተኛችን ሙሐመድ ሆይ!) ለመልዐኩ ጅብሪል ጠላት የሆነ (ግልጽ ከሃዲ ነው)። ከርሱ በፊት የወረዱ መጽሐፍትን የሚያረጋግጥ ለአማኞች መሪና ብስራት ነጋሪ ሲሆን በአላህ ፈቃድ በልብህ ላይ ያወረደው መሆኑን ንገራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 98, '98. ለአላህና ለመላዕክቱ፤ እንዲሁም ለመልዕክተኞቹ፤ ለጅብሪልና ለሚካኢልም ጠላት የሆነ ሁሉ ግልጽ ከሐዲ ነው:: አላህ ደግሞ ለከሓዲያን ሁሉ ጠላት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 99, '99. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ አንተ ግልጽ የሆኑ (አናቅጽን) መመሪያዎችን በእርግጥ አውርደናል:: በእነርሱም አመጸኞች እንጂ ሌላ አይክድም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 100, '100. ቃልኪዳን በገቡ ቁጥር ከእነርሱ መካከል ከፊሉ ቃል ኪዳኑን ይጥለዋልን? (ያፈርሰዋልን?):: ይልቁንም አብዛኞቻቸው አያምኑም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 101, '101. ከእነርሱ ጋር ያለን መጽሐፍ የሚያረጋግጥ መልዕክተኛ ከአላህ ዘንድ ተልኮ በመጣ ጊዜ ከእነዚያው መጽሐፍት ከተሰጣቸው ወገኖች ከፊሎቹ ምንም እንደማያውቁ ሆነው የአላህን መጽሐፍ ወደ ኋላቸው ወረወሩት (ጣሉት)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 102, '102. (የአላህን መጽሐፍ አንቀበልም ያሉ አይሁዶች) ሰይጣናት በሱለይማን ዘመነ መንግስት የሚያነቡትን ድግምት ተከተሉ:: ሱለይማን ጌታውን አልካደም::( ድግምተኛ አልነበረም::) ሰይጣናት ግን ሰዎችን ድግምትን የሚያስተምሩ ሲሆኑ በጌታቸው ካዱ:: በባቢሎን (በባቢል) በሁለቱ መላዕክት በሀሩትና በማሩት ላይ የተወረደውን ተከተሉ:: (ሀሩትና ማሩት) ግን «እኛ ለእናንተ መፍፈተኛዎች ነንና በጌታህ አትካድ» እስከሚሉ ድረስ አንድንም አያስተምሩም ነበር:: ከእነርሱም በባልና በሚስቱ መካከል የሚለዩበትን ነገር ይማራሉ:: እነርሱም በአላህ ፈቃድ ካልሆነ በስተቀር አንድንም በርሱ አይጎዱም:: (ድግምት የሚማሩ ሁሉ) የሚጎዳቸውንና ቅንጣት የማይጠቅማቸውን ትምህርት ይማራሉ:: የገዛው በመጨረሻይቱ አገር ምንም ዕድል የሌለው መሆኑን በእርግጥ ተገንዝበዋል:: ነፍሶቻቸውን የሸጡበት ዋጋ ምንኛ ከፋ:: የሚያውቁ በሆኑ ኑሮ (ይህን ተግባር ባልተገበሩት ነበር::)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 103, '103. በአላህ ባመኑና የከለከለውን በተጠነቀቁ ኖሮ (መልካምን በተመነዱ ነበር):: የሚያውቁ ቢሆኑ ከአላህ ዘንድ የሚገኘው ምንዳ (ነፍሶቻቸውን ከሚሸጡበት) በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 104, '104. (እናንተያመናችሁ ሆይ!) ለነብዩ "ራዒና" አትበሉ:: “ኡንዙርና” (ተመልከተን) በሉ:: የምትባሉትንም ስሙ:: ለካሃዲያንም ሁሉ አሳማሚ ቅጣት ተዘጋጅቶላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 105, '105. እነዚያ ከመጽሐፍ ባለቤቶችም ሆነ ከአጋሪዎች በአላህ የካዱት በእናንተ ላይ ከጌታችሁ የሆነ መልካም ነገር መውረዱን አይወዱም:: አላህም በችሮታው (በነብይነት) የሚፈልገውን ሰው ይመርጣል:: አላህም የታላቅ ችሮታ ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 106, '106. (መልዕክተኛችን ሙሐመድ ሆይ!) ከቁርኣን አናቅጽ መካከል አንዱን እንኳን ብንሽር ወይም እርሱን ብናስረሳህ ከእርሱ የሚበልጥ ወይም ተመሳሳዩን እናመጣለን:: አላህ በሁሉም ነገር ላይ ቻይ መሆኑን አላወቅክምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 107, '107. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ የሰማያትና የምድር ንግስና ለእርሱ ብቻ መሆኑን እና ለእናንተም ከአላህ ሌላ ወዳጅም ሆነ ረዳት እንደሌላችሁ አላወቅክምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 108, '108. (ሰዎች ሆይ!) ከአሁን በፊት (ነብዩ) ሙሳ እንደተጠየቀው ዓይነት መልዕክተኛችሁን (ሙሐመድን) ልትጠይቁ ትፈልጋላችሁን? በእምነት ክህደትን የሚለውጥ ሁሉ በእርግጥ ትክክለኛውን መንገድ ስቷል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 109, '109. ከመጽሐፍ ባለቤቶች መካከል ብዙዎቹ እውነቱ ከተገለጸላቸው በኋላ ከነፍሶቻቸው በሆነው ምቀኝነት በመገፋፋት ከእምነታችሁ በኋላ ከሓዲያን ሊያደርጓችሁ ተመኙ:: እናም አላህ ትዕዛዙን እስከሚያመጣ ድረስ ይቅርታ አድርጉ:: እለፏቸዉም:: አላህ በሁሉ ነገር ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 110, '110. (እናንተ ያመናችሁ ሆይ!) ሶላትን አስተካክላችሁ ስገዱ:: ዘካንም ለተገቢዎች ስጡ:: ለነፍሶቻችሁም የምታስቀድሙትን በጎ ስራ በአላህ ዘንድ ታገኙታላችሁ:: አላህ የምትሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 111, '111. «ገነትን አይሁድ ወይም ክርስቲያኖች የሆነ እንጂ ሌላ አይገባትም።» አሉ:: «ይህች ከንቱ ምኞታቸው ናት:: (መልዕክተኛችን ሙሐመድ ሆይ!) እውነተኞች እንደሆናችሁ እስቲ ማስረጃችሁን አምጡ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 112, '112. ጉዳዩ እንደመሰላቸው አይደለም:: ይልቁንም በጎ ሰሪ ሆኖ ፊቱን ለአላህ የሰጠ ሁሉ ለእርሱ በጌታው ዘንድ ምንዳ አለው:: በእነርሱ ላይ ስጋትም የለባቸዉም። አይተክዙምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 113, '113. እነርሱ መጽሐፉን የሚያነቡ ሲሆን አይሁድ «ክርስቲያኖች በምንም ላይ አይደሉም።» አሉ:: ክርስቲያኖችም «አይሁዶች በምንም ላይ አይደሉም።» አሉ። እንደዚሁ እነዚያ የማያውቁት አጋሪዎችም የነሱን ተመሳሳይ ንግግር ተናገሩ:: አላህ በዚያ ይለያዩበት በነበሩት ነገር ላይ ሁሉ በትንሳኤ ቀን በመካከላቸው ይፈርዳል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 114, '114. የአላህን መስጊዶች በውስጣቸው ስሙ እንዳይወሳበት ከከለከለና መስጊዶችንም ለማበላሸት ከጣረ ይበልጥ ድንበር አላፊ (አጥፊ) ማን ነው? እነዚያ በፍርሃት ተውጠው እንጂ ወደ መስጊዶች ሊገቡ አይገባቸዉም። ለነርሱም በቅርቢቱ ዓለም ውርደት አለባቸው:: በመጨረሻይቱ ሀገርም ታላቅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 115, '115. ምስራቁም ምዕራቡም የአላህ ብቻ ነው:: በአላህ ትእዛዝ (ፊቶቻችሁን) ለሶላት ወደ የትም አቅጣጫ ብታዞሩ የአላህ ፊት እዚያ ዘንድ ነው:: አላህ በእርግጥ ችሮታው ሰፊና ሁሉን አዋቂ ነዉና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 116, '116. አላህ «ልጅ አለው።» አሉ:: ከሚሉት ጥራት ተገባው:: ይልቁንም በሰማይና በምድር ያለው ሁሉ የእርሱ ነው:: ሁሉም ለእርሱ ታዛዦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 117, '117. ሰማያትንና ምድርን ያለብጤ ፈጣሪ ነው:: ማንንም ነገር ማስገኘት በፈለገ ጊዜ ለእርሱ የሚለው ‹‹ሁን›› ብቻ ነው:: ወዲያዉም እንዳለው ይሆናል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 118, '118. እነዚያ የማያውቁት «(አንተ መልዕክተኛ ስለመሆንህ) አላህ ለምን አያናግረንም? ወይም (ለእውነተኛነትህ) ተዓምር አይመጣልንም ኖሯልን? አሉ:: እነዚያ ከእነርሱ በፊት የነበሩትም ልክ እንደዚሁ ንግግራቸው ብጤ ብለዋል:: ልቦቻቸው በክህደት ተመሳሰሉ:: ለሚያረጋግጡ ህዝቦች ሁሉ አናቅጽን በእርግጥ አብራርተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 119, '119. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ አብሳሪና አስጠንቃቂ አድርገን በእውነት ላክንህ:: ከእሳት ጓዶችም ሁኔታ አትጠየቅም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 120, '120. (መልዕክተኛችን ሙሐመድ ሆይ!) አይሁድም ሆኑ ክርስቲያኖች የየራሳቸውን ሀይማኖትን እስከምትከተል ድረስ ፈጽሞ አይደሰቱብህም:: «ትክክለኛው መንገድ በእርግጥ የአላህ አመራር ነው።» በላቸው። ትክክለኛው እውቀት ከመጣልህ በኋላ ዝንባሌያቸውን ብትከተል አንተን ከአላህ የሚከላከልልህ ወዳጅም ሆነ ረዳት የለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 121, '121. እነዚያ መጽሐፉን የሰጠናቸው ሰዎች ተገቢ ንባቡን ያነቡታል:: በእርሱም ያምናሉ:: እነዚያ በእርሱ የሚክዱ ግን ከሳሪዎች እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 122, '122. እናንተ የኢስራኢል ልጆች ሆይ! እኔ ያ በእናንተ ላይ የለገስኳችሁን ጸጋዎቼንና (በዘመናችሁ ከነበሩት) የዓለማት ሕዝቦች በላይ ያበለጥኳችሁ መሆኔን አስታውሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 123, '123. አንዲት (አማኝ) ነፍስ ለሌላ (ከሓዲ) ነፍስ ምንንም የማትጠቅምበትን፤ ከእርሷም ቤዛ የማይወሰድበትን፤ ምልጃም ለእርሷ የማትፈይድበትን፤ እነርሱም ከየትም በኩል የማይረዱበትን ቀን ተጠንቀቁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 124, '124. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢብራሂምን ጌታው በትዕዛዛት በፈተነውና በፈጸማቸውም ጊዜ (የነበረውን ታሪክ አስታውስ):: «እኔ የሰው ዘር መሪ አድርጌሀላሁ።» አለው:: ኢብራሂምም «ከዘሮቼም አድርግ?» ሲል ጠየቀ:: አላህም «ኢብራሂም ሆይ! ቃል ኪዳኔ ለግፈኛ አጥፊዎች ተፈፃሚ አይሆንም እንጂ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 125, '125. (መልዕክተኛችን ሙሐመድ ሆይ!) ቤቱንም (ከዕባን) ለሰዎች መሰባሰቢያና የሰላም ማዕከል ባደረግን ጊዜ የነበረውን ታሪክ አሰታውስ:: (እናንተ ያመናችሁ ሆይ!) ከኢብራሂም መቆሚያ መስገጃን አድርጉ:: ወደ ኢብራሂምና ወደ ኢስማዒልም ቤቴን ለዘዋሪዎቹና ለተቀማጮቹም ለአጎንባሾች ሰጋጆቹም አጥሩ ስንል ቃል ኪዳን ያዝን፡፡ {1}', '(1) ቤቱን የምለው ከእባን ነው የምያመለክተው');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 126, '126. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢብራሂም «ጌታዬ ሆይ! ይህንን ሀገር (መካን) ሰላማዊ ሀገር አድርገው:: ከኗሪዉም መካከል በአላህና በመጨረሻው ቀን ያመነውን ክፍል ከፍራፍሬዎች ሲሳይ ስጠው።» ባለ ጊዜ (የነበረውን ታሪክ አስታውስ):: አላህም «የካደውንም በጥቂቱ እንዲጎናጸፍ አደርገዋለሁ:: ከዚያ ወደ እሳት ቅጣት እዳርገዋለሁ:: ይህም እጅግ አስከፊ መመለሻ ነው።» አለ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 127, '127. ኢብራሂምና ኢስማዒልም (እንደሚከተለው) በማለት እየለመኑ የካዕባን ህንፃ (መሰረቶች ግንባታ) ባሳደጉ ጊዜ (የነበረውን ታሪክ አስታውስ): «ጌታችን ሆይ! ከእኛ ተቀበለን:: አንተ ሰሚና አዋቂ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 128, '128. «ጌታችን ሆይ! ላንተው ፍጹም ታዛዦችም አድርገን:: ከዘሮቻችንም ላንተ ፍጹም ታዛዦች ሕዝቦችን አስነሳ:: አምልኳዊ ክንውኖቻችንንም አሳውቀን:: ንሰሀችንን ተቀበለን:: ጸጸትን ተቀባይና ሩህሩህ አንተ ብቻ ነህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 129, '129. «ጌታችን ሆይ! በውስጣቸው ከእነርሱ የሆነን መልዕክተኛ፤ በእነርሱ ላይ አናቅጽህን የሚያነብላቸው፤ መጽሐፍንና ጥበብንም የሚያስተምራቸውንም ከክህደት የሚያጠራቸውንም ላክላቸው:: አሸናፊዉና ጥበበኛው አንተ ብቻ ነህና።» የሚሉም ሲሆኑ (ከዕባን ገነቡ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 130, '130. ከኢብራሂምም እምነት ሞኝ ካልሆነ በስተቀር የሚያፈገፍግ ማን ነው? በቅርቢቱም ዓለም በእርግጥ (ለተልዕኳችን) መረጥነው:: በመጨረሻይቱ ዓለምም እርሱ ከመልካሞቹ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 131, '131. ጌታው ለእርሱ «ፍጹም ታዛዥ ሁን።» ባለው ጊዜ «ለዓለማቱ ጌታ ታዛዥ ሆኛለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 132, '132. ኢብራሂምም ልጆቹን በተመሳሳይ አዘዘ:: የዕቁብም እንደዚሁ በዚሁ ጉዳይ ልጆቹን አዘዘ:: (እንዲህም አለ) «ልጆቼ ሆይ! አላህ ለእናንተ ሀይማኖትን መረጠ:: ስለዚህ እናንተ ሙስሊሞች ሆናችሁ እንጂ እንዳትሞቱ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 133, '133. የዕቆብም ለጣዕረ ሞት በተዳረገበት ጊዜና ለልጆቹ «ከእኔ በኋላ ምንን ትገዛላችሁ?» ባለ ጊዜ ነበራችሁን? እነርሱም «አንድ የሆነውን አምላክህንና የአባቶችህን የኢብራሂምን፤ የኢስማዒልንና የኢስሃቅንም አምላክ እንገዛለን:: እኛም ለእርሱ ፍጹም ታዛዦች ሆነን እናመልከዋለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 134, '134. እነኝህ (ከላይ የተወሱት ህዝቦች) በእርግጥ ያለፉ ሕዝቦች ናቸው:: ለእነርሱም የስራቸው ምንዳ አላቸው:: ለእናንተም የስራችሁ (ምንዳ) አላችሁ:: እነርሱ ይሰሩት በነበረው ፈጽሞ አትጠየቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 135, '135. (መልዕክተኛችን ሙሐመድ ሆይ!) አይሁድና ክርስቲያኖች በየበኩላቸው “አይሁድ ወይም ክርስቲያን ሁኑ ቅንን መንገድ ትመራላችሁና” አሉ:: “አይደለም ይልቁንም የኢብራሂምን ሀይማኖት ቀጥተኛ ሲሆን እንከተላለን፣ ኢብራሂምም ከአጋሪዎችም አልነበረም” በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 136, '136. (እናንተ ያመናችሁ ሆይ!) «በአላህና ወደ እኛ በተወረደው ቁርኣን ወደ ኢብራሂምም፣ ወደ ኢስማዒልም፣ ወደ ኢስሀቅም፣ ወደ የዕቁብና ወደ ነገዶችም በተወረደው መለኮታዊ መልዕክት ሁሉ በዚያም ሙሳና ዒሳ በተሰጡት፤ በዚያም ነብያት ሁሉ ከጌታቸው በተለገሱት ከእነርሱ አንዱን ከሌላው የማንለይ ስንሆን አመንን:: እኛም (ለአላህ) ፍጹም ታዛዦች ነን።» በሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 137, '137. (እናንተ ያመናችሁ ሆይ!) እናንተ ባመናችሁበት መልኩ ካመኑ በእርግጥ በትክክለኛው ጎዳና ላይ ናቸው:: ከእርሱ ካፈነገጡ ግን እነርሱ በጭቅጭቅ ውስጥ ብቻ ናቸው:: የእነርሱንም ተንኮል አላህ ይበቃሀል:: እርሱም ሁሉን ሰሚና ሁሉንም አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 138, '138. የአላህን የተፈጥሮ መንከር (እምነት) ያዙ:: በመንከርም ከአላህ ይበልጥ ያማረ ማነው? (ማንም የለም):: እኛም ለእርሱ ብቻ ተገዢዎች ነን (በሉ)፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 139, '139. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ጌታችንና ጌታችሁ ሲሆን ለእኛም ስራችን ያለን ስንሆን ለእናንተም ስራችሁ ያላችሁ ስትሆኑ እኛም ስራችንን ለእርሱ ብቻ አጥሪዎች ሆነን ሳለን በአላህ (ሀይማኖት) ትከራከሩናላችሁን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 140, '140. ወይስ «ኢብራሂምም፣ ኢስማዒልም፣ ኢስሐቅም፣ ያዕቆብም፣ እንዲሁም ነገዶቹም አይሁድ ወይም ክርስቲያኖች ነበሩ» ትላላችሁን? (መልዕክተኛችን ሙሐመድ ሆይ!) “እናንተ ናችሁ የምታውቁት? ወይንስ አላህ?” በላቸው:: እርሱ ዘንድ ከአላህ የሆነችን ምስክርነት ከደበቀ ይበልጥ አጥፊ ማነው? አላህ የምትፈጽሙትን ሁሉ ዘንጊ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 141, '141. እነዚህ ያለፉ ሕዝቦች ናቸው:: ለእነርሱ የሰሩት አላቸው:: ለእናንተም የሰራችሁት አላችሁ:: እነርሱ ይሰሩት ከነበሩት ሁሉ አትጠየቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 142, '142. ቂል የህብረተሰብ ክፍሎች «ከዚያች ከነበሩባት ቂብላቸው (አቅጣጫቻቸው) ምን አዞራቸው?» ይላሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «ምስራቁም ምዕራቡም የአላህ ነው:: የሻውንም ወደ ቀጥተኛው መንገድ ይመራል።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 143, '143. እንደዚሁም (እንደመራናችሁ) ሁሉ በሰዎች ላይ መስካሪዎች ልትሆኑና መልዕክተኛዉም (ሙሐመድ) በእናንተ ላይ መስካሪ ይሆን ዘንድ መካከለኞች (ምርጥ) ማህበረሰብ (ህዝቦች) አደረግናችሁ:: ያችንም በእርሷ ላይ የነበርክባትን አቅጣጫ መልዕክተኛውን የሚከተለውን ሰው ወደ ክህደት ከሚመለሰው ሰው ልናውቅ (ልንለይ) (ልንገልጽ) እንጂ ቂብላን አላደረግናትም:: እርሷም በዚያ አላህ በመራቸው ሰዎች ላይ በስተቀር በእርግጥ ከባድ ናት:: አላህም እምነታችሁን (ስግደታችሁን) የሚያጠፋ አይደለም:: አላህም ለሰዎች በጣም ሩህሩህና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 144, '144. የፊትህን ወደ ሰማይ ማንጋጠጥክን በእርግጥ ተመልክተናል:: እናም ወደ ምትወዳት (ከዕባ) ቂብላ እናዞርሃለን:: ስለዚህ ፊትህን ወደ ተከበረው መስጊድ ወደ ካዕባ አቅጣጫ አዙር:: (ሙስሊሞች ሆይ!) የትም ስፍራ ብትሆኑ ስትሰግዱ ፊቶቻችሁን ወደ ካዕባ አቅጣጫ አዙሩ:: እነዚያ መጽሐፉን የተሰጡት እርሱ ከጌታቸው ሲሆን እውነት መሆኑን ያውቃሉ:: አላህ ከሚሰሩት ስራ ዘንጊ አይደለም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 145, '145.(መልዕክተኛችን ሙሐመድ ሆይ!) ለእነዚያ መጽሐፍን ለተሰጡት ሕዝቦች የምትችለውን ያህል ተዓምር (መረጃ) ሁሉ ብታቀርብላቸው እንኳ ቂብላህን አይከተሉም:: አንተም ቂብላቸውን ተከታይ አይደለህም:: ከፊላቸዉም የከፊሉን ቂብላ አይከተሉም:: ከእውቀትም (ራእይ) ከመጣልህ በኋላ ዝንባሌያቸውን ብትከተል ያን ጊዜ አንተ ከአጥፊዎች ትሆናለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 146, '146. እነዚያ መጽሐፍን የሰጠናቸው ሰዎች ወንዶች ልጆቻቸውን እንደሚያውቁ ሁሉ (ሙሐመድን) ያውቁታል:: ከእነርሱም የተለዩ ክፍሎች እነርሱ የሚያውቁ ሲሆኑ እውነቱን በእርግጥ ይደብቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 147, '147. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ከጌታህ የሆነ እውነት ነው:: እናም ከተጠራጣሪዎችም አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 148, '148. ለሁሉም ለስግደት ፊታቸዉን የሚያዞሩባት አቅጣጫ አላቸው:: ወደ መልካም ስራዎችም ተሽቀዳደሙ:: የትም ስፍራ ብትሆኑ አላህ ሁላችሁንም ያመጣችኋል:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 149, '149. (መልዕክተኛችን ሙሐመድ ሆይ!) ከየትም ለጉዞ ከወጣህበት ስፍራ ሁነህ ፊትህን ወደ ተከበረው መስጊድ አቅጣጫ አዙር:: እርሱም ከጌታህ የሆነ እርግጠኛ እውነት ነው:: አላህም ከምትሰሩት ስራ ሁሉ ዘንጊ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 150, '150.ከየትም ከወጣህበት ስፍራ ፊትህን ወደ ተከለለው መስጊድ አግጣጫ አዙር፡፡ በየትም ስፍራ ብትኾኑ ለሰዎቹ እነዚያ ከነሱ የበደሉት ሲቀሩ (ሃይማኖታችንን ይክዳሉ ቂብላችንን ይከተላሉ በማለት) በናንተ ላይ መከራከሪያ እንዳይኖራቸው ፊቶቻችሁን ወደ አግጣጫው አዙሩ፡፡ አትፍሩዋቸውም፤ ፍሩኝም፤ (በዚህም ያዘዝኳችሁ መከራከሪያ እንዳይኖራቸው) በናንተም ላይ ጸጋየን እንድሞላላችሁና (ወደ እውነትም) እንድትመሩ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 151, '151. ከመካከላችሁ ከናንተ የሆነን በእናንተ ላይ አናቅጻችንን የሚያነብላችሁ እና የሚያጠራችሁ መጽሐፉንና ጥበብንም የሚያስተምራችሁ ታውቁት ያልነበራችሁትንም ነገር የሚያሳውቃችሁን መልእክተኛ እንደላክን ሁሉ ጸጋን ሞላንላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 152, '152. አስታውሱኝ አስታውሳችኋለሁና:: አመስግኑኝ አትካዱኝም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 153, '153. እናንተ ያመናችሁ ሆይ! በመታገስና በሶላት ታጋዙ (ጥንካሬን ፈልጉ):: አላህም ከታጋሾች ጋር ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 154, '154. በአላህ መንገድ (ለሀይማኖቱ) የሚገደሉትን «ሙታን ናቸው።» አትበሉ:: በእውነቱ ሕያው ናቸውና:: እናንተ ግን አትገነዘቡትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 155, '155. ከፍርሀትና ከርሀብም ከሀብት፣ ከሕይወትና ከአዝመራ በመቀነስም በእርግጥ እንሞክራችኋለን:: (መልዕክተኛችን ሙሐመድ ሆይ!) ታጋሾችንም (በገነት) አብስር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 156, '156. እነዚያ መከራ በነካቸቻው ጊዜ «እኛ ለአላህ ነን። እኛም ወደ እርሱ ተመላሾች ነን።» የሚሉትን አብስር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 157, '157. እነዚያ በእነርሱ ላይ ከጌታቸው የሆኑ ምህረቶችና ችሮታም አሉ:: እነርሱም ወደ ቀናው መንገድ እውነት ተመሪዎቹ እነርሱው ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 158, '158. የሶፋና የመርዋ (ጋራዎች) የአላህን ትዕዛዝ ከመፈጸሚያ ጉልህ ቦታዎች (ምልክቶች) ናቸው:: ካዕባን በሐጅ ወይም በዑምራ ስራ ምክኒያት የጎበኘ ሁሉ በሁለቱ ጋራዎች መካከል በመመላለሱ ምንም ኃጢአት የለበትም:: መልካምንም ስራ በፈቃደኝነት የሰራ (ሁሉ አላህ ይመነዳዋል):: አላህ አመሰጋኝና ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 159, '159. እነዚያ (ስለነብዩ ሙሐመድና ሌሎችም) ከአናቅጽና ቅን መመሪያዎች ያወረድነውን ለሰዎች በመጽሐፍ ከገለጽነው በኋላ የሚደብቁትን ሁሉ አላህ ይረግማቸዋል:: ረጋሚዎችም ሁሉ ይረግሟቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 160, '160. እነዚያ የተጸጸቱ፤ (ያበላሹትን) ያስተካከሉና (የደበቁትንም) የገለጹ ሲቀሩ:: የእነርሱን ጸጸትንማ እቀበላለሁ:: እኔም ጸጸትን ተቀባይ አዛኝ ነኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 161, '161. እነዚያ በአላህ የካዱና በክህደታቸው ላይ እያሉ የሞቱ ሰዎች በእነርሱ ላይ የአላህ፤ የመላዕክትና የመላው የሰው ዘር ሁሉ እርግማን አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 162, '162. በእርግማን ውስጥም ሁልጊዜ ዘውታሪዎች ይሆናሉ:: ቅጣቱ ከእነርሱ አይቃለልም። ጊዜም አይሰጡም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 163, '163. (ሰዎች ሆይ!) አምላካችሁ አንድ አምላክ ብቻ ነው:: ከእርሱም ሌላ (ትክክለኛ) አምላክ የለም:: እርሱም እጅግ በጣም ሩህሩህና በጣም አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 164, '164. የሰማያትና የምድር አፈጣጠር፤ የሌሊትና ቀንም መፈራረቅ (መተካካት)፤ ያችም ሰዎችን የሚጠቅም ነገር (ተጭና) በባህር ላይ የምትንሳፈፈው መርከብ፤ አላህም ከሰማይ ባወረደው ውሃና በእርሱም ምድርን ከሞተች በኋላ ሕያው በማድረጉ በእርሷም ውስጥ ከተንቀሳቃሽ ሁሉ በመበተኑ፤ ንፋሶችንም በየአቅጣጫው የሚያገላብጥ መሆኑ እንዲሁም በሰማይና በምድር በሚነዳው ዳመና ለሚያውቁ ሕዝቦች በእርግጥ አያሌ ተዐምራት አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 165, '165. ከሰዎች መካከል ከአላህ ሌላ ባላንጣዎችን/ ጣዖታትን/ አላህን እንደሚወዱ የሚወዷቸው ሆነው የሚይዙ አሉ። እነዚያ ያመኑት ግን አላህን ከምንም በላይ ይወዳሉ:: እነዚያም የበደሉት ሰዎች ቅጣትን በትንሳኤ ቀን ባዩ ጊዜ ሀይል ሁሉ ለአላህ ብቻ መሆኑንና አላህም ቅጣቱ ብርቱ እንደሆነ ይገነዘባሉ:: በዚህች ዐለም ቢያውቁ ኖሮ (ባላንጣዎችን በመያዛቸው በተጸጸቱ ነበር)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 166, '166. (ይህም የሚሆነው) እነዚያ አስከታዮች ተከታዮቻቸውን በካዱበትና የሲዖልን ቅጣት ባዩ ጊዜ፤ በእነርሱም መካከል የግንኙነት መስመሮች ሁሉ በሚበጠስበት ጊዜ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 167, '167. እነዚያም የተከተሉት «ለእኛ (ወደ ቅርቢቱ ዓለም) አንዲት ጊዜ መመለስ በኖረችንና ከእኛ እንደተጥራሩ ከእነርሱ በተጥራራን እንመኛለን» ይላሉ፡፡ እንደዚሁ አላህ ሥራዎቻቸውን በነርሱ ላይ ጸጸቶች አድርጎ ያሳያቸዋል፡፡ እነርሱም ከእሳት ወጪዎች አይደሉም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 168, '168. እናንት ሰዎች ሆይ! በምድር ካለው ነገር የተፈቀደና ጣፋጭ የሆነን ምግብ ብሉ:: የሰይጣንንም ዱካዎች (እርምጃዎች) አትከተሉ:: እርሱ ለእናንተ ግልጽ ጠላት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 169, '169. እርሱ የሚያዛችሁ በኃጢአትና በጸያፍ ነገርና በአላህ ላይ የማታውቁትን እንድትናገሩ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 170, '170. ለእነርሱም «አላህ ያወረደውን ተከተሉ በተባሉ ጊዜ የለም አባቶቻችንን በእርሱ ላይ ያገኘንበትን ነገር ብቻ እንከተላለን» ይላሉ:: አባቶቻቸው ምንም የማያውቁና ወደ እውነት የማይመሩም ቢሆኑ ይከተሏቸዋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 171, '171. የእነዚያም በአላህ የካዱት ምሳሌ ልክ እንደዚያ ድምጽንና ጥሪን እንጂ ሌላን በማይሰማ እንሰሳ ላይ እንደሚጮህ (እረኛ) ብጤ ነው:: እነርሱ (እውነትን የማይሰሙ) ደንቆሮዎች፤ (ሐቅን የማይናገሩ) ዲዳዎች፤ (ትክክለኛውን መንገድ የማያዩ) እውሮች ናቸው:: ምንንም ነገር የሚገነዘቡ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 172, '172. እናንተ ያመናችሁ ሆይ! ከሰጠናችሁ ሲሳዮች መካከል ጥሩውን ተመገቡ:: አላህንም በብቸኝነት የምታመልኩት ከሆናችሁ እሱኑ ብቻ አመስግኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 173, '173. (አላህ) በእናንተ ላይ እርም ያደረገባችሁ በክትን፣ ደምን፣ የአሳማ ስጋንና ከአላህ ሌላ በሆነ ስም የታረደን ስጋ ብቻ ነው:: ተገዶ ችግሩን ለማስወገድ ያክል ብቻ ሽፍታና ወሰን አላፊ ሳይሆን (ቢመገብ) በእርሱ ላይ ምንም ሀጢአት የለበትም:: አላህ መሐሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 174, '174. እነዚያ አላህ ካወረደው መጽሐፍ (የትኛውንም ክፍል) የሚደብቁ፤ በሱ (በደበቁትም) ጥቂትን ዋጋ የሚለውጡ፤ በሆዶቻቸው ውስጥ እሳትን እንጂ አይበሉም:: አላህም በትንሳኤ ቀን አያናግራቸዉም:: ከኃጢአትም አያጠራቸዉምም:: ለእነርሱም አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 175, '175. እነዚህ እነዚያ ስህተትን በቅንነት ቅጣትንም በምህረት የለወጡ ናቸው:: በእሳት ላይ ምን ታጋሽ አደረጋቸው?!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 176, '176. ይህም አላህ መጽሐፍን በእውነት ያወረደ በመሆኑና (በእርሱም በመካዳቸው ነው):: እነዚያም በመጽሐፉ የተለያዩት ከእውነት በራቀ ውዝግብ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 177, '177. መልካምነት ፊቶቻችሁን ወደ ምስራቅና ምዕራብ አቅጣጫ ማዞራችሁ አይደለም። መልካምነት በአላህ፣ በመጨረሻው ቀን፣ በመላዕክት፣ በመጸሐፍት በነብያት ያመነ፤ ገንዘብንም ምንም ያህል የነዋይ (ገንዘብ) ፍቅር ቢኖረዉም ለዝምድና ባለቤቶች፣ ለየቲሞች፣ ለሚስኪኖች፣ ለመንገደኞች፣ ለለማኞች፣ ባሪያዎችን ነፃ ለማውጣት የሰጠ፤ ሶላትን ደንቡን ጠብቆ የሰገደና ዘካንም ያወጣ ነው:: እንዲሁም ቃልኪዳን በገቡ ጊዜም ቃልኪዳናቸውን የሚሞሉ በችግር፣ በበሽታና በፍልሚያ ጊዜ ታጋሾች ናቸው። እነዚህ እነዚያ እውነትን የያዙ መሆናቸውን በተግባር አረጋግጠዋል:: አላህን የሚፈሩም ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 178, '178. እናንተ ያመናችሁ ሆይ! ግድያን በተመለከተ አጸፋዊ እርምጃ በእናንተ ላይ ተደንግጓል:: (እርሱም) ነፃ ሰውን በነፃ መግደል፤ ባሪያን በባሪያ መግደል፤ ሴትን በሴት መግደል::(ነው) ከሟች ወንድሙ ደም ትንሽ ነገር እንኳን ምህረት የተደረገለት ሰው በመሃሪው የሟች ወገን ላይ ካሳውን በመልካም መከታተል ሲኖርበት ምህረት የተደረገለት ገዳይም የነፍስ ዋጋውን ለእርሱ በመልካም አኳኋን መክፈል አለበት:: ይህ ከጌታችሁ የሆነ ማቃለልና እዝነት ነው:: ከዚህም በኋላ ህግን የተላለፈ ሰው እርሱ አሳማሚ ቅጣት ይጸናበታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 179, '179. እናንተ ባለ አእምሮዎች ሆይ! በአጸፋዊ እርምጃ ህግ ሕይወትን ትጎናጸፋላችሁ:: ይህም ግድያን ከመፈጸም ልትጠነቀቁ ዘንድ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 180, '180. በማንኛዉም ላይ ሞት በመጣበት ጊዜና ቀሪ ሀብት ያለው እንደሆነ ለወላጆችና ለቅርብ ዘመዶች በአግባቡ መናዘዝ በእናንተ ላይ ተደንግጓል:: ይህ አላህን በሚፈሩ ላይ መፈጸም ያለበት ግዴታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 181, '181. (ኑዛዜውን) ከሰማው በኋላ የለወጠው ኃጢአቱ በእነዚያ በሚለውጡት ላይ ብቻ ነው:: አላህም ሁሉን ሰሚ ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 182, '182. ከተናዛዥም በኩል (ከእውነት) መዘንበልን ወይም (ከሲሶ የመጨመር) ኃጢአትን የፈራ (ያወቀ) ከዚያም በመካከላቸው ያስታረቀ በእርሱ ላይ ምንም ኃጢአት የለበትም:: አላህ በጣም መሀሪና በጣም አዛኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 183, '183. እናንተ ያመናችሁ ሆይ! ፆም በእነዚያ ከናንተ በፊት በነበሩት (ሕዝቦች) ላይ ግዴታነቱ እንደተፃፈ ሁሉ በእናንተም ላይ ተደነገገ:: ልትጠነቀቁ ይከጀላልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 184, '184. ውስን ቀናትን ጹሙ። ከናንተም ውስጥ በሽተኛ ወይም በጉዞ ላይ የሆነ ሰው ባልፆማቸው ቀናት ልክ ተመሳሳይ ቁጥር ያላቸውን ቀናት መፆም አለበት:: እነዚያ ለመፆም ከአቅም በላይ ችግር የገጠማቸው ሰዎች ደግሞ አፍጥረው ለየቀኑ እንድ ድሃን የአንድ ጊዜ ምግብ ማብላት ይኖርባቸዋል:: ከዚህ በላይ ቤዛን በመጨመር መልካምንም ስራ የፈቀደ ሰው (እርሱ ፈቅዶ መጨመሩ ለራሱ) በላጭ ተግባር ነው:: ግና በመንገድ ላይ ሆናችሁ መፆማቸሁ ለእናንተ የበለጠ ነው:: የምታውቁ ብትሆኑ ትመርጡታላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 185, '185. (ያ እንድትጾሙት የተደነገገላችሁ ወር) በእርሱ ዉስጥ ለሰዎች መሪ ሐቅን መንገድና እውነትን ከዉሸት የሚለየው ገላጭ ቁርአን የተወረደበት የረመዷን ወር ነው:: ከናንተ መካከል ወሩን ያገኘ ሁሉ ይጹመው:: በሽተኛ ወይም በጉዞ ላይ የሆነ ሰው ካፈጠረ ከሌሎች ቀናት ባልፆማቸው ቀናት ቁጥሮች ልክ መፆም አለበት:: አላህ ሁልጊዜም ለእናንተ ገሩን ነገር ይሻል እንጂ በእናንተ ላይ ጫናን መፍጠርን አይሻምና ነው። ለፆም የተወሰኑትን ቀናት ልትሞሉና አላህን ቅንኑ መንገድ ስለመራችሁ ልታከብሩትና ልታመሰግኑት ዘንድ (ይህን ደነገገላችሁ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 186, '186. (መልዕክተኛችን ሙሐመድ ሆይ!) ባሮቼ ስለ እኔ በጠየቁህ ጊዜ እኔ ቅርብ ነኝ:: የለማኝን ጸሎትም በለመነኝ ጊዜ እቀበለዋለሁ:: ስለዚህ ወደ ቀናው መንገድ ይመሩ ዘንድ ለእኔ ብቻ ይታዘዙ:: በእኔም ብቻ ይመኑ። (በላቸው።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 187, '187. (ሙስሊሞች ሆይ!) በፆም ሌሊት ከሚስቶቻችሁ ጋር የግብረ ስጋ ግንኙነት ተፈቀደላችሁ:: እነርሱ ለእናንተ ልብሶች ናቸው:: እናንተም ለእነርሱ ልብሶች ናችሁና:: አላህ በዚህ ረገድ ነፍሶቻችሁን በማታለል ላይ መሆናችሁን ያውቃል::በእናንተም ላይ ተመለሰላችሁ፡፡ ከእናንተም ይቅርታ አደረገ፡፡ አሁን ተገናኙዋቸው፡፡ አላህም ለናንተ የጻፈላችሁን ነገር (ልጅን) ፈልጉ፡፡ ነጩ የንጋት ገመድ ከጥቁሩ የሌሊት ገመድ ለእናንተ እስከሚገለጽላችሁ ድረስ ብሉ:: ጠጡም:: ከዚያም ፆምን እስከ ሌሊቱ ድረስ ሙሉ:: እናንተ በመስጊዶች ተቀማጮች ኢዕቲካፍ ላይ ስትሆኑ ግን ሚስቶቻችሁን አትገናኙዋቸው:: ይህች የአላህ ህግጋት ናትና ለመተላለፍ አትቅረቧት:: ልክ እንደዚሁ አላህ አናቅጽን ለሰዎች ያብራራል:: እነርሱ የተከለከሉትን ሊጠነቀቁ ይከጅላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 188, '188. ገንዘቦቻችሁንም በመካከላችሁ በከንቱ (ያለ አግባብ) አትብሉ፡፡ እናንተም የምታውቁ ስትኾኑ ከሰዎች ገንዘቦች ከፊልን በኃጢኣት ትበሉ ዘንድ ወደ ዳኞች አትጣሏት፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 189, '189. (መልዕክተኛችን ሙሐመድ ሆይ!) ስለለጋ ጨረቃ መለዋወጥ ይጠይቁሃል። «ይህ ክስተት ሰዎች ጊዜን ለመለካት የሚጠቀሙበትና የሐጅንም ወቅት ለማወቅ የሚረዳ ምልክት ነው:: መልካም ስራ ቤቶችን ከጀርባዎቻቸው መግባታችሁ አይደለም:: ይልቁንም የመልካም ስራ ባለቤት አላህን የሚፈራው ነው:: ቤቶችንም በፊት በሮቻቸው በኩል ግቡ:: አላህንም ፍሩ ከጀሀነም ቅጣት ልትድኑ ዘንድ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 190, '190. (ትክክለኛ አማኞች ሆይ!) እነዚያን የሚጋደሏችሁን ከሓዲያን በአላህ መንገድ ተጋደሉ:: ነገር ግን ድንበር አትለፉ :: አላህ ድንበር አላፊዎችን አይወድምና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 191, '191. ባገኛችኃቸዉም ስፍራ ሁሉ ግደሏቸው:: ካስወጧችሁም ስፍራ አስወጧቸው:: ፈተና (ሁክት) ከመግደል የከፋ ነውና:: በተከበረው መስጊድም ዘንድ በእርሱ ውስጥ እስከሚጋደሏችሁ ድረስ በእርሱ ውስጥ አትጋደሏቸው:: ከተጋደሏችሁ ግን ግደሏቸው:: የከሓዲያን ቅጣት ልክ እንደዚህ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 192, '192. ከውጊያ ከታቀቡ ግን አላህ መሀሪና አዛኝ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 193, '193. (እናንተ ያመናችሁ ሆይ!) ፈተና (ሁከት) እስኪወገድና ሃይማኖት ለአላህ ብቻ እስኪሆን ድረስ ተጋደሏቸው:: ከታቀቡ ግን የሀይል እርምጃ ድንበርን ባለፉ ላይ እንጂ (በሰላማዊ ላይ) አይጸናም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 194, '194. (እናንተ ያመናችሁ ሆይ!) የተከበረው ወር በተከበረው ወር አንፃር ነው::ክብሮችም ሁሉ ተመሳሳዮች ናቸው፡፡ (ፍትሃዊ አጸፋዊ እርምጃ የተከበረን ህግ በጣሱ ላይ ተደንግጓል):: ወሰን ያለፈባችሁን በእናንተ ወሰን ባለፈው ቢጤ ወሰን ያለፈውን ያህል በእርሱም ላይ ወሰን እለፉበት:: አላህንም ፍሩ:: አላህ እርሱን ከሚፈሩት ጋር መሆኑንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 195, '195. (እናንተ ያመናችሁ ሆይ!) በአላህ መንገድ ላይ ለግሱ:: ራሳችሁንም በገዛ እጃችሁ ለጥፋት አትዳርጉ:: በበጎ ስራም ላይ ጽኑ:: አላህ በጎ ሰሪዎችን ሁሉ ይወዳልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 196, '196. ሐጅንና ዑምራን ለአላህ ብቻ ብላችሁ በትክክል ፈጽሙ:: ከጀመራችሁ በኋላ ብትታጉዱም ከመስዋአት የቻላችሁትን መሰዋት አለባችሁ:: መስዋእቱ ከመታረጃው ስፍራ እስኪደርስ ድረስም ራሶቻችሁን አትላጩ:: ከናንተም ውስጥ በሐጅ ላይ ሁኖ የታመመ ወይም በራስ ቅሉ ላይ ጉዳት የደረሰበት ሰው ቢላጭ ከመፆም ወይም መስዋዕትን ቤዛ መስጠት አለበት:: ጸጥታም ባገኛችሁ ጊዜ እስከ ሐጅ መፈጸሚያ ቀን ድረስ በዑምራ አስቀድሞ በመፈጸም የተገላገለ ሰው ከመስዋእቱ የተገራውን (የቻለዉን) መሰዋት አለበት:: ያላገኘም ሰው ሶስትን ቀናት በሐጅ (ወራት) ላይ ሰባትንም ቀናት ደግሞ በተመለሳችሁ ጊዜ መፆም አለበት:: እነዚህ ሙሉ አስር (ቀናት) ናቸው:: ይህም (ህግ) ቤተሰቦቹ ከቅዱሱ መስጊድ አቅራቢያ ላልሆኑ ነው:: አላህንም ፍሩ። አላህ ቅጣተ ብርቱ መሆኑንም እወቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 197, '197. ሐጅ የሚፈጸመው በተወሰኑ የታወቁ ወራት ነው:: እናም በእነርሱ ውስጥ ሐጅን ለመስራት ግዴታ የገባ ሰው በሐጅ ክንውን ውስጥ እያለ ሴትን መገናኘት፤ በአላህ ላይ ማመጽና ክርክር አያደርግም:: (ሙስሊሞች ሆይ!)የምትሰሩትን ሁሉ አላህ ያውቀዋል። ስንቅም ያዙ:: ከስንቅ ሁሉ በላጩ አላህን መፍራት ነው:: የአእምሮ ባለቤቶች ሆይ! እኔን ብቻ ፍሩኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 198, '198. በሐጅ ጊዜ (በስራ) ከጌታችሁ ችሮታን በመፈለጋችሁ በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: ከአረፋት በተንቀሳቀሳችሁም ጊዜ መሸዐረል ሀራም ዘንድ ስትደርሱ አላህን አውሱ:: ወደ ቀናው የኢስላም መንገድ ስለመራችሁም አውሱት:: ቀደም ሲል በእርግጥ ከተሳሳቾች ነበራችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 199, '199. ከዚያ ሰዎች ከተንቀሳቀሱበት ስፍራ ተንቀሳቀሱ :: የአላህንም ምህረት ለምኑ:: አላህ በእጅጉ መሀሪና አዛኝ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 200, '200. የሐጅ ስራዎቻችሁን በፈጸማችሁ ጊዜ አባቶቻችሁን እንደምታወሱ ወይም ከእርሱም ይበልጥ በበረታ አላህን አውሱ:: ከሰዎችም መካከል፡- «ጌታችን ሆይ! በምድረ ዓለም መልካም እድልን ስጠን።» የሚል ሰው አለ:: ለእርሱ በመጨረሻይቱ ዓለም ምንም ድርሻ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 201, '201. ከእነርሱም መካከል «ጌታችን ሆይ! በምድር ዓለም ደግን ነገር (ጸጋን) በመጨረሻይቱ ሀገርም ደግን ነገር (ገነትን) ስጠን:: ከእሳትም ቅጣት ጠብቀን።» የሚሉ አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 202, '202. እነዚያ ከሰሩት በጎ ስራ ድርሻ አላቸው:: አላህም ምርመራው ፈጣን ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 203, '203. (ሙስሊሞች ሆይ!) በእነዚያ በተወሰኑ ቀናት ውስጥ አላህን አውሱ:: በሁለት ቀናት ውስጥ ለመሄድ የተቻኮለ ሰው በእርሱ ላይ ኃጢአት የለበትም:: የቆየም ሰው ኃጢአት የለበትም:: ይህም (ምህረት) አላህን ለፈራ ሰው ሁሉ ነው:: አላህንም ፍሩ:: እናንተ ወደ እርሱ የምትሰበሰቡ መሆናችሁንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 204, '204. ከሰዎችም መካከል እርሱ ክርክረ ብርቱ ሲሆን በቅርቢቱ ሕይወት ንግግሩ የሚያስደስትህ (የሚደንቅህ) ፤ በልቡ ውስጥ በሚያጠነጥነውም አላህን የሚያስመሰክር ሰው አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 205, '205. (ካንተ) በዞረ ጊዜ በውስጧ ሊያበላሽና አዝመራንና እንሰሳዎችን ሊያጠፋ በምድር ላይ ይሮጣል:: አላህም ጥፋትን አይወድም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 206, '206. ለእርሱ “አላህን ፍራ” በተባለም ጊዜ ትዕቢት (በኃጢአት ስራ ላይ) ይገፋፋዋል። ገሀነምም ለእሱ በቂው ናት:: እርሷም በእርግጥ የከፋች ምንጣፍ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 207, '207. ከሰዎችም ውስጥ የአላህን ውዴታ ለመፈለግ ሲል ነፍሱን የሚሸጥም ሰው አለ:: አላህም ለባሮቹ በጣም ሩህሩህ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 208, '208. እናንተ ያመናችሁ ሆይ! ሁላችሁም ወደ አላህ መንገድ እስልምና ጠቅልላችሁ ግቡ:: የሰይጣንን እርምጃዎችም አትከተሉ፤ እርሱም ለእናንተ ግልጽ ጠላት ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 209, '209. ግልጽ ማስረጃዎች ከመጡላችሁ በኋላ እውነትን ከመቀበል ብታፈገፍጉ አላህ ሁሉን አሸናፊና ጥበበኛ መሆኑን እወቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 210, '210. አላህ በዳመና ጥላዎች ዉሥጥ ሆኖ እና መላዕክቱ ከያቅጣጫው ወደ እነርሱ እንዲመጡና ጉዳዩ እንዲወሰን እንጂ ሌላ ምንን ይጠባበቃሉ:: ነገሮች ሁሉ ወደ አላህ ብቻ ይመለሳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 211, '211. (መልዕክተኛችን ሙሐመድ ሆይ!) የኢስራኢል ልጆችን ምን ያህል ግልጽ ተዐምር እንደሰጣናቸው ጠይቃቸው:: የአላህን ጸጋ ከመጣለት በኋላ ለሚለውጥ (ሰው አላህ ይቀጠዋል) አላህ ቅጣተ ብርቱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 212, '212. ለእነዚያ ለካዱት ባመኑት የሚሳለቁ ሲሆኑ ቅርቢቱ ሕይወት ተሸለመችላቸው:: እነዚያ አላህን የሚፈሩት በትንሳኤ ቀን ከበላያቸው ናቸው:: አላህም ለፈለገው ገጸ በረከቱን ያለገደብ ይሰጣልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 213, '213. ሰዎች ሁሉ (አላህን አንድ በማድረግ) አንድ ሕዝብ ነበሩ:: (ከዚያም ተለያዩ):: ከዚያም አላህ ነብያትን ለመልካም ሰዎች በገነት አብሳሪዎችና ለመጥፎ ሰዎች ደግሞ ከእሳት አስጠንቃቂዎች አድርጎ ላከ:: ከነሱ ጋርም ከሰዎቹ መካከል በዚያ እነርሱ በተለያዩበት ነገር ይፈርድ ዘንድ መጽሐፍትን በእውነት አወረደ:: በእርሱ ግልጽ አስረጂዎች ከመጡላቸው በኋላ በመካከላቸው በተፈጠረው ምቀኝነት ሰበብ እነዚያው መጽሐፍትን የተሰጡት ሰዎች እንጂ አልተለያዩበትም:: አላህ እነዚያን በአላህ ያመኑትን ሰዎች በእነርሱ የተለያዩበትን እውነታ ይገነዘቡ ዘንድ በፈቃዱ መራቸው:: አላህ የሚሻውን ወደ ቀጥተኛው መንገድ ይመራል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 214, '214. (እናንተ ያመናችሁ ሆይ!) በእውነቱ የእነዚያ ከበፊታችሁ ያለፉት አማኞችን ያጋጠመ መከራ የመሰለ ሳይመጣባችሁ ገነትን ልትገቡ ታስባላችሁን? መልዕክተኛውና እነዚያ ከእርሱ ጋር ያመኑት «የአላህ እርዳታ መቼ ነው?» እስከሚሉ ድረስ መከራና ጉዳት ደረሰባቸው:: ተርበደበዱም። (ሙስሊሞች ሆይ! ) አስተውሉ! የአላህ እርዳታ በእርግጥ ቅርብ ነው (አልናቸው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 215, '215. (መልዕክተኛችን ሙሐመድ ሆይ!) ምንን እንደሚለግሱ ይጠይቁሃል። «ከየትኛዉም ሀብት የምትለግሱት ለወላጆች፣ ለቅርብ ዘመዶች፣ ለየቲሞች፣ ለድሆችና ለመንገደኞች (ሊሆን ይገባል።) ከበጎ ነገርም ማንኛውንም ብትሰሩ አላህ እርሱን አዋቂ ነው።»በላቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 216, '216. (እናንተ ያመናችሁ ሆይ!) ከሓዲያንን መጋደል በእናንተ ዘንድ የሚጠላ ቢሆንም በእናንተ ላይ በግዴታነት ተደነገገ:: አንድ ነገር ለእናንተ ጥሩ ቢሆንም ምናልባት ትጠሉት ይሆናል:: አንድንም ነገር እርሱ ለእናንተ መጥፎ ሆኖ እያለ ትወዱት ይሆናል:: አላህም የሚሻላችሁን ያውቃል:: እናንተ ግን አታውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 217, '217. (መልዕክተኛችን ሙሐመድ ሆይ!) በተከበረው ወር ስለመጋደል ይጠይቁሃል። «በእነርሱ ውስጥ መጋደል ትልቅ ኃጢአት ነው:: ግን ከአላህ መንገድ ሰዎችን መከልከል፤ በእርሱም መካድ፤ ከተከበረው መስጊድ ማገድ፤ ባለቤቶቹንም ከእርሱ ማፈናቀል አላህ ዘንድ ይበልጥ የተለቀ ወንጀል ነው:: ፈተናም (በአላህ ማጋራትም) ከመግደል ይበልጥ ከባድ ነው» በላቸው። ከሓዲያን ቢችሉ ከሃይማኖታችሁ እስኪመልሷችሁ ድረስ የሚዋጓችሁ ከመሆን አይቦዝኑም:: ከናንተ ውስጥ ከሀይማኖቱ የሚመለስና እርሱ ከሃዲ ሆኖ የሚሞት ሁሉ እነዚያ በቅርቢቱ ሀገርም ሆነ በመጨረሻይቱ ሀገር በጎ ስራቸው ተበላሸች:: እነዚህ የእሳት ጓዶች ናቸው:: በእርሷም ውስጥ ለዘላለም ይዝወትራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 218, '218. እነዚያ ያመኑና ከሀገራቸው የተሰደዱ፤ በአላህ መንገድ ላይም የተጋደሉ፤ እነዚያ የአላህን እዝነት ይከጅላሉ:: አላህም እጅግ መሀሪና አዛኝ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 219, '219. (መልዕክተኛችን ሙሐመድ ሆይ!) አዕምሮን ስለሚያሰክር መጠጥና ስለ ቁማር ይጠይቁሃል:: «በሁለቱም ትልቅ ኃጢአትነትና ለሰዎችም ጥቅም አለባቸው:: ኃጢአታቸው ግን ከጥቅማቸው በጣም የገዘፈ ነው።» በላቸው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ምንን እንደሚመጸውቱም (መጠኑን) ይጠይቁሀል:: «የተረፋችሁን መጽውቱ።» በላቸው:: እንደዚሁ ታስተነትኑ ዘንድ አላህ ለናንተ አንቀጾችን ይገልጽላችኋል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 220, '220. በዱኒያም በአኼራም ታስተነትኑ ዘንድ ይገልፅላችኃል። (መልዕክተኛችን ሙሐመድ ሆይ!) ስለየቲሞችም ይጠይቁሀል:: «የእነርሱን ሁኔታ ማሻሻል በላጭ ነው:: የእነርሱ ጉዳይ ከናንተ ጋር ብትቀላቅሉም ወንድሞቻችሁ ናቸው:: አላህም አጥፊውን ከአልሚው ለይቶ ያውቃል:: አላህም በፈለገ ኖሮ መፈናፈኛ ያሳጣችሁ (ባስቸገራችሁ) ነበር:: አላህ በሁሉም ነገር አሸናፊና ጥበበኛ ነው በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 221, '221. (ሙስሊሞች ሆይ!) አጋሪዎችን ሴቶችን በአላህ እስከሚያምኑ ድረስ አታግቧቸው:: አጋሪይቱ ነፃ ሴት ምንም ብትስባችሁ እንኳ ያመነችው ባሪያ ሴት በእርግጥ ለእናንተ በላጭ ናት:: ለአጋሪዎቹ እስከሚያምኑ ድረስ አትዳሩላቸው:: ከአጋሪ ወንድ ምንም ቢስባችሁ አማኝ ባሪያዎች ለእናንተ በላጭ ናቸው:: እነዚያ አጋሪዎች ወደ እሳት ይጠራሉ:: አላህ ደግሞ ወደ ገነትና ወደ ምህረት ይጠራል:: ህግጋቱንም ለሰዎች ሊገሰጹ ዘንድ ይገልፅላቸዋል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 222, '222. (መልዕክተኛችን ሙሐመድ ሆይ!) ስለ ሴቶች የወር አበባ ይጠይቁሃል:: «እርሱ ጎጂ (አጸያፊ) ነው። እናም ሚስቶቻችሁን በወር አበባቸው ጊዜ ራቁዋቸው፤ ደሙ ቆሞ ንጹህ እስከሚሆኑ ድረስ ለግንኙነት በፍጹም አትቅረቧቸው:: ንጹህ በሆኑ ጊዜም አላህ ባዘዛችሁ ቦታ ተገናኟቸው:: አላህ ከኃጢአት ተመላሾችንና ንጽህናን የሚጠብቁትን ይወዳልና።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 223, '223. ሚስቶቻችሁ ለእናንተ እርሻ ናቸው:: እናም እርሻዎቻችሁን በፈለጋችሁት ሁኔታ ግንኙነት ፈጽሙ:: ለነፍሶቻችሁ መልካም ስራን አስቀድሙ:: አላህንም ፍሩ:: እናንተም ከእርሱ ጋር የምትገናኙ መሆናችሁን እውቁ:: (መልዕክተኛችን ሙሐመድ ሆይ!) አማኞችንም በገነት አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 224, '224. (ሙስሊሞች ሆይ!) በአላህ ስም የፈጸማችሁት መሀላ በጎ ከመዋል አላህን ከመፍራትም ወይም በሰዎች መካከል እርቀ ሰላም ከማውረድ ግርዶ አታድርጉ:: አላህ ሁሉን ሰሚና ሁሉንም አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 225, '225. ያለ አስተውሎት በምትፈጽሙት መሐላዎቻችሁ አላህ አይቀጣችሁም:: ግን ልቦቻችሁ በጽኑ ባሰቡበት መሐላዎቻችሁ ይይዛችኋል:: አላህ በጣም መሀሪ፤ ታጋሽ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 226, '226. እነዚያ ሚስቶቻቸውን ላለመገናኘት የሚምሉ ወንዶች ሁሉ ለማሰላሰያ ጊዜ አራት ወራት አላቸው:: እናም መሀላቸውን ቢያጥፉና ቢመለሱ አላህ መሀሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 227, '227. ፍችን ለመፈጸም ጽኑ ውሳኔ ላይ ከደረሱ ደግሞ (ይፋቱ):: አላህም ሁሉን ሰሚ ሁሉንም አዋቂ ነዉና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 228, '228. የተፈቱ ሴቶችም በራሳቸው ሶስትን የወር አበባ ይጠብቁ። በአላህና በመጨረሻው ቀን የሚያምኑ ከሆኑ አላህ በማህጸኖቻቸው ውስጥ የፈጠረውን ጽንስ ሊደብቁ አይፈቀድላቸዉም:: ባሎቻቸዉም እርቅን ከፈለጉ በእነዚህ ወራት ውስጥ የመመለስ መብታቸው ቅድሚያ ነው:: ለሴቶች ግዳጅ እንዳለባቸው ሁሉ ፍትሀዊ መብትም አላቸው:: ይሁንና ወንዶች (የበለጠ ሀላፊነትን ስለሚሸከሙ) ብልጫ አላቸው። (ተጥሎባቸዋል):: አላህ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 229, '229. የመመለስ እድል የሚሰጠው ፍቺ ሁለት ጊዜ ብቻ ነው:: ከዚያም በመልካም መያዝ ወይም በበጎ አኳኋን ማሰናበት ነው:: (ባሎች ሆይ!) የአላህን ህግጋት ያለማክበር ስጋት ካልኖረባቸው በስተቀር ከሰጣችኋቸው ነገር ምንንም ልትወስዱ ለእናንተ አይፈቀድላችሁም:: የአላህን ሕግጋት አለመጠበቃቸውን ብትገነዘቡ ነፃ ለማውጣት በምትፈጽመው ነገር በሁለቱም ላይ ኃጢአት የለባቸዉም:: እኒህ የአላህ ሕግጋት ናቸው:: አትተላለፏቸው:: እነዚያ እነርሱ የአላህን ሕግጋት የሚተላለፉ ሁሉ (በደለኞች) አጥፊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 230, '230. ከዚያም ለሶስተኛ ጊዜ ከፈታት በኋላ ሌላን ባል እስካላገባች (ከዚያም እስካልተፈታች ወይም እስካልሞተባት) ድረስ ለእርሱ አትፈቀደለትም:: ሁለተኛው ባል ከፈታት የአላህን ሕግጋት እንደሚጠብቁ ተስፋ ካደረጉ በመማለሳቸው በሁለቱም ላይ ኃጢኣት የለባቸውም:: እነኚህ የአላህ ሕግጋት ናቸው:: ለሚያውቁ ሕዝቦች ሁሉ ያብራራላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 231, '231. (ሙስሊሞች ሆይ!) ሚስቶቻችሁን በፈታችሁ እና የኢዳ ጊዜያቸውን ለማገባደድ በቀረቡ ጊዜ በመልካም መልሷቸው:: ወይም በመልካም ሁኔታ ያለ አንድ ጉዳት አሰናብቷቸው:: ለመጉዳትም ወሰን ታልፉባቸው ዘንድ አትያዟቸው:: ይህን የሚሰራም ነፍሱን በእርግጥ በደለ:: የአላህን አናቅጽ ማላገጫ አታድርጉ:: አላህ በእናንተ ላይ የዋለውን ጸጋ፤ በእርሱ ሊገስፃችሁም ያወረደውን መጽሐፍ (ቁርኣንን) እና ጥበብንም (ሱናን) አስታውሱ:: አላህንም ፍሩ:: አላህ በሁሉ ነገር ላይ አዋቂ መሆኑንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 232, '232. ሚስቶቻችሁን በፈታችሁ እና የኢዳ ጊዜያቸውን በጨረሱ ጊዜ ጥንዶቹ በመካከላቸው ሕጋዊና ፍትሀዊ የጋራ ስምምነት ላይ ከደረሱ ባሎቻቸውን ከማግባት አታስተጓጉሏቸው:: ይህ ከናንተ መካከል በአላህና በመጨረሻ ቀን የሚያምን ሁሉ ይገሰጽበታል:: ይህ ለእናንተ በላጭና አጥሪ ነው:: አላህ ያውቃል:: እናንተ ግን አታውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 233, '233. እናቶች ልጆቻቸውን ሁለት ሙሉ ዓመታትን ያጠባሉ:: ይህም ማጥባትን የተሟላ ለማድረግ ለፈለገ ሰው ነው:: በአባት ላይ ምግባቸውንና ልብሳቸውን የማቅረብ ግዴታ አለበት:: ማንም ነፍስ ከችሎታዋ በላይ አትገደድምና:: እናት በልጇ ምክኒያት ጉዳት እንዲደርስባት አይደረግም:: አባትም በልጁ ምክንያት እንዲንገላታ መሆን የለበትም:: በወራሽም ላይ የዚሁ ተመሳሳይ ሀላፊነት አለበት:: ወላጆቹ በመልካም ፈቃድ ልጁን ከጡት መነጠል (ማስጣል) ቢፈልጉ በሁለቱም መማከር በሁለቱም ላይ ኃጢአት የለባቸዉም:: ለልጆቻችሁ አጥቢዎችን ብትቀጥሩ ተስፋ የሰጣችሁትን ክፍያ በአግባቡ እስከሰጣችሁ ድረስ በማስጠባታችሁ በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: አላህን ፍሩ:: አላህ የምትሰሩትን ነገር ሁሉ ተመልካች መሆኑን እወቁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 234, '234. (ወንዶች ሆይ!) እነዚያ ከናንተ ውስጥ የሚሞቱና ሚስቶችን የሚተው ሚስቶቻቸው በራሳቸው አራት ወር ከአስር ቀናትን ከጋብቻ ይታገሱ:: ጊዜያቸውንም በጨረሱ ጊዜ በራሳቸው ተነሳሽነት በሚፈጽሙት ሕጋዊ ተግባር በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: አላህ የምትሰሩትን ነገር ሁሉ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 235, '235. (ወንዶች ሆይ!) ባሎቻቸው የሞቱባቸውን ሴቶች የጋብቻ (አሽሙር) ፍንጭ በመስጠታችሁ ወይም እንዲህ ዓይነቱን ሀሳብ በውስጣችሁ በማሰባችሁ ምክንያት በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: አላህ እናንተ በእርግጥ እንዲህ ዓይነቱን ሀሳብ እንደምታስተናግዱ ቀድሞውኑ ያውቃል:: ስለዚህ (አሽሙር) ፍንጭ መስጠትንና ማሰብን ፈቀደላችሁ:: ግና በሕግ የታወቀን ጨዋ ንግግር የምትነጋገሩ ካልሆናችሁ በስተቀር የተፃፈው የኢዳ ጊዜው እስከሚደርስ ድረስ ለትዳር እንደምትፈልጓቸው በሚስጥር ቃል አትግቡላቸው:: ጋብቻን ለመዋዋልም ቁርጥ ሀሳብ አታድርጉ:: አላህ በነፍሶቻችሁ ውስጥ ያለውን ሁሉን ጠንቅቆ የሚያውቅ መሆኑን እወቁ:: ተጠንቀቁም፤ አላህ መሀሪና ታጋሽ መሆኑንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 236, '236. (ባሎች ሆይ!) ሴቶችን ግንኙነት ከማድረግ በፊት ወይም ለእነርሱ መህርን ሳትወስኑላቸው ብትፈቷቸው በእናንተ ላይ ኃጢአት የለባችሁም:: ነገር ግን ሀብታምም ደሃም እንደየአቅማቸው ይካሷቸው:: ይህ አቅምን መሰረት ያደረገ ካሳ በቅን ሰዎች ላይ የተደነገገ ህግ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 237, '237. (ባሎች ሆይ!) ለሚስቶቻችሁ መህርን የወሰናችሁላቸው ስትሆኑ ሳትገናኟቸው በፊት ብትፈቷቸው ራሳቸው ይቅር ካላሉ ወይም ያ የጋብቻ ውል በእጁ የሆነ ባል ካላግራራ በስተቀር ከወሰናችሁት ግማሹን መስጠት ግድ ሆኖባችኋል:: ሁላችሁም ይቅር መባባላችሁ ወደ አላህ ፍራቻ በጣም የቀረበ ነው:: አንዱ ለሌላው በጎ መዋልን አይዘንጋ:: አላህም የምትሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 238, '238. (ሙስሊሞች ሆይ!) ሶላቶችን በተለይ መካከለኛይቱን ሶላት ወቅታቸውንና ስርዓታቸውን ጠብቃችሁ ስገዱ:: በሙሉ ታዛዥነትም ለአላህ ቁሙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 239, '239. (ሙስሊሞች ሆይ!) የደህንነት ስጋት ሲኖር በእግር እየሄዳችሁም ሆነ ተሳፍራች ስገዱ:: ሰላም ሲሰፍን በተለመደው ሥርዓት (ስገዱ።) ታውቁት ያልነበራችሁትን እንዳሳወቃችሁ ሁሉ አላህን በአግባቡ አውሱ (ስገዱ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 240, '240. (እናንተ ያመናችሁ ሆይ!) እነዚያ ከናንተ ውስጥ ሚስቶችን ትተው የሚሞቱ ሁሉ ለሚስቶቻቸው ከየቤቶቻቸው የማይወጡ ሆነው ሳለ ዓመት ድረስ ወጫቸው እንዲሸፈን መናዘዝ ይኖርባቸዋል:: ሚስቶች በፈቃዳቸው ከቤት ቢወጡ ግን ደንብ ጠብቀውና ኃላፊነትን ወስደው በሰሩት ጉዳይ ላይ በሟች ዘመዶች ላይ ምንም ኃጢአት የለባችሁም:: አላህ ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 241, '241. ለተፈቱ ሴቶች ሁሉ በፈችው ባል ችሎታ መጠን ዳረጎት (የገንዘብ ድጎማ) ይሰጣቸዋል:: ይህ አላህን በሚፈሩ ሰዎች ሁሉ ላይ ተደንግጓል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 242, '242. ልክ እንደዚሁ አላህ አናቅጽን ታውቁ ዘንድ ለእናንተ ያብራራላችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 243, '243. (መልዕክተኛችን ሙሐመድ ሆይ!) ብዙ ሺህ ሆነው ሞትን በመፍራት ከሀገሮቻቸው የወጡ ሰዎችን ታሪክ አላየህምን (አላወክምን?) አላህ ለእነርሱ «ሙቱ» አላቸው:: ሞቱም:: ከዚያ እንደገና ነፍስ ዘራባቸው:: አላህም ለሰዎች እጅግ ቸር ነው:: ይሁንና አብዛሀኞቹ ሰዎች አያመሰግኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 244, '244. (ሙስሊሞች ሆይ!) በአላህ መንገድ ላይ ተጋደሉ:: አላህ ሁሉን ሰሚ ሁሉንም አዋቂ መሆኑንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 245, '245. ለአላህ መልካም ብድርን የሚያበድርና አላህም ብዙ እጥፍ ድርብ አድርጎ እንዲከፍለው የሚሻ ማን ነው? አላህ ለፈለገው ሰው ሲሳዩን ያጠብበታል፤ ለፈለገው ደግሞ ያሰፋለታልም:: ወደ እርሱ ብቻ ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 246, '246. (መልዕክተኛችን ሙሐመድ ሆይ!) ከኢስራኢል ልጆች ከሙሳ ዘመን በኋላ ወደ ነበሩት የቤተ-ኢስራኢል ቅምጥሎች ተልኮላቸው ለነበረው ለነብያቸው «ለእኛ ንጉስን ሹምልን እና በአላህ መንገድ እንዋጋ።» ባሉ ጊዜ የሆነውን አላየህምን? እሱም «መዋጋት ቢፃፍባችሁ አትዋጉ ይሆናል።» አላቸው:: እነርሱም «ከአገሮቻችንና ከልጆቻችን ተባረን ሳለ በአላህ መንገድ የማንዋጋበት ምን ምክንያት አለን?» አሉ:: በእነርሱ ላይ መዋጋት በተፃፈባቸው ጊዜ ግን ከእነርሱ ጥቂቶች ሲቀሩ ከመዋጋት አፈገፈጉ:: አላህ አጥፊዎችን ሁሉ በሚገባ ያውቃቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 247, '247. ነብያቸው ‹‹አላህ ጧሉትን ንጉስ አድርጎ በእርግጥ ላከላችሁ›› አላቸው:: እነርሱም፡- «ሰፊ ሀብትም ያልተሰጠ እኛም ከእርሱ ይልቅ ለንግስና ተገቢዎች ስንሆን እርሱ በእኛ ላይ እንዴት ይነግሣል?» አሉ:: ነብያቸዉም፡- «አላህ በእናንተ ላይ መረጠው እውቀትና የሰውነት ጥንካሬም አጎናጽፎታል:: አላህ ንግስናውን ለሚሻለት ሰው ይሰጣል:: አላህ ችሮታው ሰፊና አዋቂ ነው።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 248, '248. በተጨማሪም ነብያቸው እንዲህ አላቸው:: «የንግስናው ምልክት መላእክት የሚሸከሙት ሳጥን ወደ እናንተ ይመጣል:: በውስጡ ለናንተ እርጋታን የሚፈጥርና የሙሳ እና የሀሩን ቤተሰብ የተውት ቅርስም ይገኝበታል:: በዚህም ውስጥ ትክክለኛ አማኞች ከሆናችሁ ከባድ ተዐምር አለላችሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 249, '249. ጧሉትም በሰራዊቱ ታጅቦ በመጣ ጊዜ ‹‹አላህ በወንዝ ውሃ ይፈትናችኃል:: እናም ከእርሱ የጠጣ ሰው ሁሉ ከእኔ አይደለም:: እሱን ያልቀመሰው ሰው ግን በእጁ አንድ እፍኝ ያህል የዘገነ ሰው ብቻ ሲቀር እርሱ ከእኔ ነው›› አለ:: ከእነርሱም መካከል ጥቂቶች ሲቀሩ ከእርሱ ጠጡ:: እርሱና እነዚያ ከእርሱ ጋር ያመኑት ወንዙን ባለፉት ጊዜ፡- «ጃሉትን (ጎልያድን) እና ሰራዊቱን ለመዋጋት በቂ ችሎታና ጥንካሬ የለንም።» አሉት:: እነዚያ ከአላህ ጋር እንደሚገናኙ የሚያረጋግጡትም «ጥቂት ቡድን በአላህ ፈቃድ ብዙውን ቡድን ያሸነፈበት አጋጣሚ ብዙ ነው:: አላህ ከታጋሾች ጋር ነውና።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 250, '250. ለጃሉትና ለሰራዊቱ በተሰለፉም ጊዜ፡- «ጌታችን ሆይ! ትግስትን ለግሰን:: እግሮቻችንን አጽናልን:: በከሓዲያን ሕዝቦችም ላይ እርዳን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 251, '251. እናም በአላህ ፈቃድ ድል መቷቸው:: ነብዩ ዳውድም ጃሉትን ገደለ:: ለዳውድ ንግሥናን፤ ጥበብን እና ነብይነትን አላህ ሰጣቸው:: ከሚሻው ነገር ሁሉ አሳወቀው:: አላህ ሰዎችን ከፊላቸውን በከፊሉ መመለሱ (መከላከሉ) ባልነበረ ኖሮ ምድር በጠቅላላ በተበላሸች ነበር:: ግን አላህ በዓለማት ላይ የችሮታ ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 252, '252. እነዚህ አናቅጽ በእውነት ባንተ ላይ የምናነባቸው ሲሆኑ የአላህ አናቅጽ ናቸው:: አንተም በእርግጥ ከመልዕክተኞቹ መካከል አንዱ ነህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 253, '253. እነዚያን መልዕክተኞች ከፊላቸውን በከፊሉ ላይ አበለጥን:: ከእነርሱ መካከልም አላህ ያነጋገረው አለ:: ከፊሎቻቸውንም በደረጃ ከሌሎች ከፍ አድርጓል:: የመርየምን ልጅ ዒሳንም ግልጽ ተዐምራት ሰጠነው:: በቅዱስ መንፈስም (በመላኩ ጂብሪል) አበረታነው:: አላህ በፈለገ ኖሮ እነዚያ ከእነርሱ በኋላ የነበሩት መረጃው ከመጣላቸው በኋላ እርስ በእርሳቸው ባልተዋጉ ነበር:: ግን ተለያዩ:: በመሆኑም ከመሀከላቸው ትክክለኛ አማኝ ክፍል አለ:: ከመሀከላቸዉም ከሃዲ አለ:: አላህ በፈለገ ኖሮ እርስ በእርሳቸው ባልተዋጉ ነበር:: አላህ ግን የሚሻውን ሁሉ ይሰራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 254, '254. እናንተ ያመናችሁ ሆይ! ያ ንግድ፤ ወዳጅነትም ሆነ ምልጃ የሌለበት ቀን ከመምጣቱ በፊት ከሰጠናችሁ ሲሳይ ለግሱ:: በዳዮች ማለት ከሓዲያን ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 255, '255. አላህ ከእርሱ በስተቀር ሌላ ትክክለኛ አምላክ የለም:: አላህ ምንግዜም ሕያው፤ በራሱ የተብቃቃ ነው:: ማንጎላጀትም ሆነ እንቅልፍ አትይዘዉም:: በሰማያት ውስጥና በምድር ውስጥ ያለው ሁሉ የእርሱ ብቻ ነው:: ያ እርሱ ዘንድ በፍቃዱ ቢሆን እንጂ የሚያማልድ ማን ነው? (ከፍጡራን) ሁሉ በፊታቸው ያለውንና ከኋላቸው ያለውን ሁሉ ጠንቅቆ ያውቃል:: በሻው ነገር እንጂ ከእውቀቱ (ፍጡራን) በምንም ነገር አያካብቡም:: መንበሩ የሰማያትንና የምድርን ስፋት ይበልጣል:: ጥበቃቸዉም አያቅተዉም:: እርሱ የሁሉ የበላይና ታላቅ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 256, '256. በሃይማኖት ማስገደድ የለም:: ቅኑ መንገድ ከጠማማው መንገድ በእርግጥ ተገለጠ:: በጣኦት (ባዕድ አምልኮ) የሚክድና በአላህ የሚያምን ሰው ሁሉ የማትበጠስ ጠንካራ ገመድን ጨብጧል:: አላህ ሁሉን ሰሚ ሁሉንም አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 257, '257. አላህ የአማኞች ወዳጅ ነው:: ከድቅድቅ ጨለማ ወደ ብርሃን ያወጣቸዋል:: እነዚያ አላህን የካዱት ግን ረዳቶቻቸው ጣኦታት ናቸው:: ከብርሃን ወደ ጨለማ ይመሯቸዋል:: እነዚያ የእሳት ጓዶች ናቸው:: እነርሱ በውስጧ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 258, '258. (መልዕክተኛችን ሙሐመድ ሆይ!) ያንን አላህ ንግስናን ስለ ሰጠውና በጌታው ጉዳይ በኢብራሂም ላይ ክርክር ስለ ከፈተው ሰው (ታሪክ) መረጃ አላየህምን? ኢብራሂም፡-‹‹ጌታዬ ያ የፈለገውን ሕያው የሚያደርግና የፈለገውን የሚገድል ነው›› ሲለው «እኔም የፈለኩትን ህያው አደርጋለሁ፤ የፈለኩትን እገድላለሁ» አለ:: ኢብራሂምም፡- «አላህ ጸሐይን በምስራቅ በኩል ያወጣል:: እስኪ አንተ ከምዕራብ በኩል አምጣት» አለው:: ያም የካደ ሰው ዋለለ (መልስ አጣ):: አላህ ግፈኛ ሕዝቦችን ሁሉ አይመራምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 259, '259. (መልዕክተኛችን ሙሐመድ ሆይ!) ወይም ያንን ሙሉ በሙሉ በፈራረሰች ከተማ ያለፈውን ሰው ተሞክሮ አላገናዘብክምን? ‹‹ይህችን ከተማ ከሞተች በኃላ አላህ እንዴት ሕያው ያደርጋታል? አለ:: ከዚያ አላህ ገደለውና መቶ ዓመትን አቆየው:: ከዚያ አስነሳው «ምን ያህል ቆየህ?» አለው:: «አንድ ቀን ወይም የቀንን ከፊል ቆይቻለሁ» አለ:: «ይልቁንም መቶ ዓመት ነው የቆየኸው:: ወደ ምግብህና ወደ መጠጥህም ተመልከት:: አንዱም አልተለወጠም:: ወደ አህያህም ተመልከት:: ለሰው ልጅም ተዐምር ልናደርግህ ዘንድ ይህንን ሰራን፤ ወደ አጽሞቿም እንዴት እንደምናስነሳት ከዚያ ስጋን እንዴት እንደምናለብሳት ተመልከት።» አለው:: ለእርሱም ማስረጃ በገለጸለት ጊዜ ‹‹አላህ በነገሩ ሁሉ ላይ ቻይ መሆኑን አውቃለሁ›› አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 260, '260. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢብራሂም «ጌታዬ ሆይ! ሙታንን እንዴት ሕያው እንደምታደርግ እስቲ አሳየኝ» ባለ ጊዜ የሆነውን ታሪክ አስታውስ:: አላህ፡- «አላመንክምን?» አለው:: ኢብራሂምም «በፍጹም (አይደለም) አምኛለሁ:: ግን ልቤ ሙሉ በሙሉ እንዲረጋጋ ነው።» አለው:: አላህም፡- «አራት ወፎችን ያዝና ወደ አንተ ሰብስባቸው:: ከዚያ ቆራርጣቸው:: ከዚያም በየኮረብታው ሁሉ ላይ ከእነርሱ ቁራጭ ቁራጭ አካላቸውን አስቀምጥ:: ከዚያም ጥራቸው በፍጥነት ወደ አንተ ይመጣሉ:: አላህ አሸናፊና ጥበበኛ መሆኑን እወቅ።» አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 261, '261. እነዚያ ገንዘቦቻቸውን በአላህ መንገድ የሚለግሱ ሰዎች ልግስና ምሳሌ በየዘለላው ሁሉ መቶ ቅንጣት ያለባቸውን ሰባት ዘለላዎች እንዳበቀለች አንዲት ፍሬ ምሳሌ ነው:: አላህ ለሚሻው ሁሉ አባዝቶ ይለግሳል:: አላህ ችሮታው ሰፊና አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 262, '262. እነዚያ ገንዘቦቻቸውን በአላህ መንገድ የሚለግሱ ከዚያ በሰጡት ነገር መመፃደቅና ማስከፋት የማያስከትሉ ሁሉ ለእነርሱ በጌታቸው ዘንድ ምንዳቸው አለላቸው:: በእነርሱም ላይ ስጋትም የለባቸዉም። አይተክዙምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 263, '263. መልካም ንግግርና ይቅር ባይነት ብቻ ማስከፋት ከሚከተለው ምጽዋት በላጭ ነው:: አላህ በራሱ ተብቃቂና ታጋሽ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 264, '264. እናንተ ያመናችሁ ሆይ! እንደ እነዚያ ገንዘብን ለሰዎች ለማሳየት ሲል እንደሚሰጠውና በአላህና በመጨረሻው ቀን እንደማያምነው ሰው ምጽዋቶቻችሁን በመመፃደቅና ተረጂውን በማስከፋት አታበላሹ:: የዚህ አይነቱም ድርጊት ምሳሌው በላዩ ላይ አፈር እንዳረፈበት ለስላሳ ድንጋይ ሲሆን እሱም ሀይለኛ ዝናብ አግኝቶት እንደተራቆተ ብጤ ነው:: እነኝህ አይነት ሰዎች ከሰሩት ነገር በምኑም ሊጠቀሙ አይችሉም:: አላህ ከሓዲያን ሕዝቦችን በፍጹም ወደ ቀናው መንገድ አይመራምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 265, '265. የእነዚያ የአላህን ውዴታ ለመፈለግና ከነፍሶቻቸው እምነትን ለማረጋገጥ ብለው ገንዘቦቻቸውን የሚለግሱት ምሳሌያቸው በተስተካከለች ከፍተኛ ቦታ ላይ እንዳለች አትክልት ሲሆን ይህች አትክልት ከፍተኛ ዝናብ አግኝታ እጥፍ ድርብ ምርት እንደሰጠች ከፍተኛ ዝናብ ባታገኝ እንኳን ካፊያ ብቻ እንደሚበቃት የአትክልት አይነት ይመስላል:: አላህ የምትሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 266, '266. ከናንተ አንዳችሁ ሁሉን ዓይነት ምርት የምትሰጥ ከስሯ ወንዞች የምፈሱባት የዘንባባዎችና የወይኖች የአትክልት ቦታ ልትኖረው እርጅናም ሊነካውና በእነርሱም ደካሞች ረዳት የለሽ ህፃናት ያሉት ሲሆኑ በውስጡ እሳት ያለበት ውርጭ ምርቱ ላይ አደጋ ሊያደርስበት እና ልትቃጠልበት ይወዳልን? ልክ እንደዚሁ አላህ አናቅጽን ለእናንተ ያብራራል:: ልታስተነትኑ ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 267, '267. እናንተ ያመናችሁ ሆይ! ካፈራችሁትና ከዚያ ለእናንተ ከምድር ካወጣንላችሁ ከመልካሙ ለግሱ:: መጥፎውንም ለመስጠት አታስቡ:: እርሱን ለራሳችሁ አይኖቻችሁን ጨፍናችሁ እንጂ የማትወስዱት ስትሆኑ ከእርሱ (ከመጥፎ) ትሰጣላችሁን? አላህ ተብቃቂና ምስጉን መሆኑን እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 268, '268. ሰይጣን እንዳትለግሱ በድህነት ያስፈራራችኋል:: በመጥፎም ያዛችኋል:: አላህ ከእርሱ የሆነን ምህረትና ችሮታን ሊያጎናጽፋችሁ ተስፋ ሰጥቷችኋል:: አላህ ችሮታው ሰፊና ሁሉን አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 269, '269. አላህ ለሚሻው ሰው ጥበብን ይሰጣል:: ጥበብንም የሚስ-ሰጥ ሰው ሁሉ ብዙ መልካም ነገርን በእርግጥ ተሰጥቷል:: የአዕምሮ ባለቤቶች እንጂ ሌላው አይገሰጽም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 270, '270. ከምጽዋት ማንኛውንም የለገሳችሁትን ወይም ከስለት የተሳላችሁትን አላህ ጠንቅቆ ያውቀዋል:: ለበዳዮች (ግፈኞች) ሁሉ ምንም አይነት ረዳቶች የሏቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 271, '271. ምጽዋቶችን ብትገልጹ እርሷ ምንኛ መልካም ተግባር ናት:: ብትደብቋትና ለድሆች ብትሰጧት እርሱ ለእናንተ በላጭ ነው:: ከኃጢአቶቻችሁ ከእናንተ ያብሳል:: አላህ በምትሰሩት ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 272, '272. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱን ማቅናት ባንተ ላይ ግዴታ የለብህም:: አላህ ግን የሚሻውን ሰው ያቀናል:: የምትለግሱት ገንዘብ ሁሉ ምንዳው ለነፍሶቻችሁ ብቻ ነው:: የአላህን ውዴታውን በመፈለግ እንጂ ምንንም አትለግሱ:: ከገንዘብም የምትለግሱት ሁሉ ምንዳው ወደ እናንተ ይሞላል:: እናንተም ቅንጣት ያህል አትበደሉም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 273, '273. (ምጽዋት የምትሰጡት ዘካና ልገሳ) ለእነዚያ በአላህ መንገድ በግል ሕይወታቸው ከመንቀሳቀስ (ለታገዱት) ፋታ ላጡ ድሆች ነው:: መሬት ውስጥ መጓዝ (ልመና) አይችሉም:: ከቁጥብነታቸው የተነሳ ውስጣቸውን የማያውቅ ሰው ሁሉ ሀብታሞች ናቸው ብሎ ይገምታቸዋል:: በምልክታቸው ታውቃቸዋለህ:: ሰዎችን በችክታ አይለምኑም:: ከገንዘብም የምትለግሱትን ሁሉ አላህ ሁሉን አዋቂ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 274, '274. እነዚያ ገንዘቦቻቸውን በሌሊትና በቀን በድብቅም ሆነ በግልጽ የሚለግሱ ሰዎች ሁሉ ለእነርሱ በጌታቸው ዘንድ ዋጋቸው ይስ-ሰጣቸዋል:: በእነርሱም ላይ ምንም ይደርስብናል ብለው ፍርሀት የለባቸዉም:: ምንም ነገር ያመልጠናል ብለው አያዝኑም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 275, '275. እነዚያ አራጣን የሚበሉ ሁሉ ያ ሰይጣን ሰፍኖበት ራሱን የሚስት ሰው ከአውድቅቱ እንደሚነሳ አይነት ሁነው እንጂ ከመቃብራቸው አይነሱም:: ይህም የሆነው እነርሱ መሸጥ ልክ እንደ አራጣ ነው በማለታቸው ነው:: አላህ ግን መሸጥን ፈቅዷል:: አራጣን እርም አድርጓል:: ከጌታው ግሳጼ የመጣለት እና ከዚያ የተከለከለ ሰው ሁሉ ከዚህ አዋጅ በፊት ያካበተውን እንደያዘ መቆየት ይችላል:: የወደፊት እጣፈንታው ወደ አላህ ነው:: አራጣን ወደ መብላት የተመለሱ ሰዎች እነዚያ የእሳት ጓዶች ናቸው:: እነርሱ በውስጧ ዘወታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 276, '276. አላህ የአራጣን ገንዘብ ያከስማል (በረከቱን ያጠፋል):: መልካም ልገሳዎችን ያፋፋል:: አላህም ኃጢአተኛንና ከሓዲን ሁሉ አይወድምና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 277, '277. እነዚያ ያመኑና መልካም ስራዎችንም የሰሩ፤ ሶላትን አስተካክለው የሰገዱና ዘካንም የሰጡ እነርሱ በጌታቸው ዘንድ ምንዳቸው አላቸው፤ በእነርሱም ላይ ምንም ይደርስብናል ብለው ፍርሀት የለባቸዉም:: ምንም ነገር ያመልጠናል ብለው አያዝኑምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 278, '278. እናንተ ያመናችሁ ሆይ! አላህን ፍሩ:: ከአራጣም የቀረውን አትውሰዱ:: ትክክለኛ አማኞች ከሆናችሁ (ተጠንቀቁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 279, '279. የታዘዛችሁትን ባትሰሩ ከአላህና ከመልዕክተኛ ጦርነት ታውጆባችኋል:: ከወለዳዊ ድርጊታችሁ ብትታቀቡ ግን አንጡራ ገንዘባችሁ ለእናንተው እንደተጠበቀ ነው:: ሌሎችን አትበድሉም አትበደሉምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 280, '280. የድህነት ባለቤት ባለዕዳ ሰው ቢኖር ገንዘብ እስኪያገኝ ድረስ ማቆየት ነው:: (የእፎይታ ጊዜ ይሰጠው) ስጡት:: እዳውን በበጎ አድራጊነት ሙሉ በሙሉ ብትሰርዙለትም ለእናንተ በላጭ ነው። የምታውቁ ብትሆኑ (ትሰሩታላችሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 281, '281. ያን ወደ አላህ የምትመለሱበትን ቀን ፍሩ:: ሁሉም ነፍስ ያኔ ከሰራቸው አኳያ ዋጋዋን ታገኛለች:: በዚያ ዕለት (በሱ ዉስጥ) ተበዳይ ወገኖች ፈጽሞ አይኖሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 282, '282. እናንተ ያመናችሁ ሆይ! እስከተወሰነ ጊዜ ድረስ በእዳ በተዋዋላችሁ ጊዜ ፃፉት:: ጸሐፊዉም በመካከላችሁ በትክከል ይፃፍ:: ጸሐፊም አላህ ልክ እንዳሳወቀው መፃፍን ለመፃፍ እንቢ አይበል:: ይፃፍም:: ያም በእርሱ ላይ እዳ ያለበት ሰው በቃሉ ያለበትን እዳ ያስጽፍ:: ጌታውን አላህን ይፍራ:: ካለበት እዳ ምንም አያጉድል:: ያም በእርሱ ላይ እዳው ያለበት የአእምሮም ሆነ የአካል መታወክ ካለበት ወይም በቃሉ ማስፃፍን የማይችል ከሆነ ወኪሉ በትክክል ያስጽፍለት:: ከወንዶቻችሁ ሁለትን ምስክሮች አስመስክሩ:: ሁለትም ወንዶች በስፍራው ካልተገኙ ግን ለምስክርነት በቂ የሆነ አንድ ወንድና አንደኛዋ ስትረሳ አንደኛይቱ ሌላዋን ታስታውሳት ዘንድ ሁለት ሴቶች ይመስክሩ:: ምስክሮችም በተጠሩ ጌዜ ከመመስከር እንቢ አይበሉ:: (እዳው) ትንሽ ወይም ትልቅ ቢሆንም እስከጊዜው ድረስ ከመፃፍ አትሰልቹ:: ይህ አላህ ዘንድ በጣም ትክክል ለምስክርነቱም ተዐማኒነት የሚያጎናጽፍ ጥርጣሬንም ለማስወገድ በጣም የተመቸ አሰራር ነው:: በመካከላችሁ እጅ በእጅ በምትለዋወጡት ንግድ ላይ ግን ባትጽፏት በእናንተ ላይ ኃጢአት የለባችሁም:: በተሻሻጣቸሁ ጊዜ አስመስክሩ:: ጸሐፊም ሆነ ምስክር ባለጉዳዩ ጉዳት ሊያደርስባቸው አይገባም:: ይህንን ብትሰሩ በእናንተ በኩል የሚመጣ አመጽ ነው:: አላህን ፍሩ:: አላህ ያሳውቃችኋል:: አላህ ሁሉንም ነገር አዋቂ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 283, '283. በጉዞ ላይ ብትሆኑና ጸሐፊ ባታገኙ በእጅ የተጨበጡ መተማመኛዎችን ያዙ:: ከፊላችሁ ከፊሉን ቢያምን ያ የታመነው ሰው አደራውን በትክክል ያድርስ:: አላህንም ጌታውን ይፍራ:: ምስክርነትንም አትደብቁ። ምስክርነትን የሚደብቃት ልበ ኃጢአተኛ ነው:: አላህ የምትሰሩትን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 284, '284. በሰማያት ውስጥና በምድር ውስጥ ያለ ሁሉ የአላህ ብቻ ነው:: በነፍሶቻችሁ ውስጥ ያለውን ብትገልጹት ወይም ብትደብቁት አላህ በእርሱ ይቆጣጠራችኋል የሚሻውን ሰው ይምራል:: የሚሻውንም ሰው ይቀጣል:: አላህ በሁሉ ነገር ላይ ቻይ ነውና:: ይተሳሰባችኋል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 285, '285. መልዕክተኛው (ሙሐመድ) ከጌታው ወደ እርሱ በተወረደለት (ቁርኣን) አምኗል:: አማኞችም እንደዚሁ አመኑ:: ሁሉም በአላህ፣ በመልዕክቱ፣ በመጽሐፉትና በመልዕክተኞቹ «ከእነርሱ በአንዱም መካከል አንለይም (አንክድም)» የሚሉ ሲሆኑ አመኑ:: «የአላህን ትዕዛዛትንም ሰማን ታዘዝንም። ጌታችን ሆይ! ምህረትህን እንሻለን :: የሁሉም መመለሻ ወደ አንተው ብቻ ነው። አሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (2, 286, '286. አላህ የትኛዋንም ነፍስ ከችሎታዋ በላይ አያስገድዳትም:: ነፍስ ሁሉ ለሰራችው መልካም ስራ ሁሉ ተገቢው ምንዳ አላት:: በእርሷም ላይ ባፈራችው (ኃጢአት) ተገቢው ቅጣት አለባት:: (ሙስሊሞች) «ጌታችን ሆይ! ብንረሳ ወይም ብንሳሳት (አትቅጣን):: ጌታችን ሆይ! ከባድ ሸክምን ከእኛ በፊት በነበሩት ህዝቦች ላይ እንደጫንከው ሁሉ በእኛ ላይ አትጫንብን:: ጌታችን ሆይ! ለእኛ ችሎታ የሌለንን ነገር አታሸክመን:: ለእኛም ይቅርታ አድርግልን:: ለእኛም ምህረትን አድርግልን:: እዘንልንም:: ረዳታችን አንተ ብቻ ነህና:: በከሓዲ ሕዝቦች ላይም ድልን አጎናጽፈን።» (በሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 1, '1. አሊፍ፤ ላም፤ ሚም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 2, '2. አላህ ከእርሱ ሌላ ትክክለኛ አምላክ የለም:: አላህ ህያው፤ በራሱ የተብቃቃና የሁሉ ነገር አስተናባሪ (የፍጡራን ተንከባካቢ) ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ቁርኣንን ከእርሱ በፊት ያሉትን መጽሐፍት የሚያረጋግጥ ሲሆን ባንተ ላይ ከፋፍሎ በእውነት አወረደው። ከቁርኣን በፊትም ለሰዎች መሪ አድርጎ ተውራትንና ኢንጅልን አውርዷል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 4, '4. ከቁርኣን በፊትም ለሰዎች መሪ አድርጎ ተውራትንና ኢንጅልን አውርዷል። (በእውነትና በውሸት መካከል መለያ የሆነውን) ፉርቃንንም አወረደ። እነዚያ በአላህ አናቅጽ የካዱ ሁሉ ብርቱ ቅጣት አለባቸው። አላህ ሁሉን አሸናፊ፤ አስተባባዮችን ተበቃይም ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 5, '5. አላህ በምድርም ሆነ በሰማይ ምንም ነገር አይሸሸግበትም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 6, '6. በማህጸኖች ውስጥ እንደፈለገው አድርጎ የሚቀርፃችሁ እርሱው ነው። ከእርሱ ከአሸናፊዉና ከጥበበኛው ጌታ በስተቀር ሌላ ትክክለኛ አምላክ በፍጹም የለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ያ ባንተ ላይ መጽሐፍን-(ቁርኣንን) ያወረደ ነው:: ከመጽሐፉም ውስጥ ግልጽ የሆኑ አናቅጽ አሉ:: እነርሱም የመጽሐፉ መሰረቶች ናቸው። ሌሎች ደግሞ አሻሚ ትርጉም ያላቸው አሉ:: እነዚያ በልቦቻቸው ውስጥ ጥመት ያለባቸው ሌሎችን ለማሳሳት በማሰብና ትርጉሙን በሻቸው ለመለወጥ ሲሉ አሻሚ ትርጉም (ተመሳሳይነት) ያሏቸውን አናቅጽ ብቻ ይከታተላሉ። ትክክለኛ ትርጉማቸውን አላህ ብቻ እንጂ ሌላ ማንም አያውቀዉም:: እነዚያ በእውቀት የጠለቁት ግን «በእርሱ አምነናል። ሁሉም ከጌታችን ዘንድ ነው።» ይላሉ። የአእምሮ ባለቤቶች እንጂ አይገሰጽም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 8, '8. (እነርሱም የሚሉ ናቸው:) «ጌታችን ሆይ! ቅኑን መንገድ ከመራኸን በኋላ ልቦቻችንን ወደ መጥፎ አታዘንብልብን:: ካንተ ዘንድ የሆነን ችሮታ ስጠን:: አንተ በጣም ለጋስ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 9, '9. «ጌታችን ሆይ! አንተ በዚያ ለመምጣቱ ጥርጥር በሌለበት ቀን ሰውን ሁሉ ሰብሳቢ ነህ:: ምን ጊዜም አላህ ቀጠሮን አያፈርስምና»::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 10, '10. እነዚያ የካዱትን ገንዘቦቻቸውና ልጆቻቸው ከአላህ (ቅጣት) አያስጥሏቸዉም። እነዚያም እነርሱ የእሳት ማገዶዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 11, '11. ምሳሊያቸው ልክ እንደ ፈርዖን ቤተሰቦችና እንደነዚያ ከበፊታቸዉም እንደነበሩት ሕዝቦች ልማድ ነው:: በአናቅጻችን አስተባበሉ:: እናም አላህ በኃጢአቶቻቸው ቀጣቸው:: አላህ ቅጣተ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 12, '12. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነዚያ በአላህ ለካዱ ሰዎች «በቅርብ ጊዜ ትሸነፋላችሁ:: ከዚያም በገሀነም ትሰበሰባላችሁ:: ምንጣፊቱም (ገሀነም) ምን ትከፋ!» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 13, '13. በእነዚያ (የበድር) ቀን በተጋጠሙት ሁለት ቡድኖች ለእናንተ ብዙ ተዓምራት አሉ:: አንደኛዋ ቡድን በአላህ መንገድ ትጋደላለች:: ሌላይቱ ቡድን ደግሞ ከሓዲ ናት። በዓይን አስተያየት እጥፋቸው ሆነው ያዩዋቸዋል (በቁጥር የነርሱ እጥፍ ሁነው በአይናቸው ተመለከቷቸው)። አላህ በእርዳታው የሚሻውን ሁሉ ያበረታልና። በዚህ ውስጥ ለማስተዋል ባለቤቶች ሁሉ በእርግጥ መገሰጫ አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 14, '14. ከሴቶች፣ ከወንዶች ልጆች፣ ከወርቅ፣ ከብር፣ ከተከማቹ ገንዘቦች፣ ከተሰማሩ ፈረሶች፣ ከግመል ከከብትና ከፍየል፣ ከአዝመራም የሆኑ ፍላጎቶችን መውደድ ለሰዎች ተሸለመላቸው (ሰዎች ዘንድ የተወደዱ ተደረገላቸው)። ይህ ሁሉ የቅርቢቱ ሕይወት መጠቃቀሚያ ብቻ ነው:: አላህ ግን እርሱ ዘንድ መልካም የሆነ መመለሻ (ገነት) አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከዚህ ከተዋበላችሁ ጉዳይ የሚበልጥን ልንገራችሁን? እርሱም ለእነዚያ አላህን ለሚፈሩ ሁሉ በጌታቸው ዘንድ በስራቸው ወንዞች የሚፈሱባቸው ገነቶች በውስጧ ሁልጊዜ ነዋሪዎች ሲሆኑ ንጹህ ሚስቶችና ከአላህ የሆነ ውዴታም አለላቸው:: አላህም ባርያዎቹን ተመልካች ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 16, '16. (እነርሱም) እነዚያ «ጌታችን ሆይ! እኛ ባንተ አመንን። ኃጢአቶቻችንን ማርልን። የእሳትን ቅጣት ጠብቀን።» የሚሉ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 17, '17. እነርሱም ታጋሾች፤ እውነተኞች፤ ታዛዦች፤ ለጋሾችና በሌሊት መጨረሻዎች ሰዓታት ላይ አላህን ምህረት የሚለምኑ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 18, '18. አላህ (በማስተካከል) ቀጥ ያለ ሲሆን ከእርሱ በስተቀር ሌላ ትክክለኛ አምላክ የሌለ መሆኑን መሰከረ። መላዕክትና የእውቀት ባለቤቶችም መሰከሩ። ከእርሱ በስተቀር ሌላ አምላክ የለም:: እርሱ ሁሉን አሸናፊውና ጥበበኛው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 19, '19. አላህ ዘንድ የተወደደው ሀይማኖት ኢስላም ብቻ ነው:: እነዚያ መጽሐፉን የተሰጡ ሰዎች በመካከላቸው ባለው ምቀኝነት እውቀቱ ከመጣላቸው በኋላ እንጂ አልተለያዩም:: በአላህ አናቅጽ ለሚክድ ሁሉ አላህ ምርመራው ፈጣን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢከራከሩህም «ፊቴን ለአላህ ብቻ ሰጠሁ። የተከተሉኝም እንደዚሁ ለአላህ ብቻ ሰጡ።» በላቸው:: ለእነዚያም መጽሐፉን ለተሰጡ ሰዎችና ለመሃይማኑ (ዐረቦች)፡- «ሰለማችሁን?» በላቸው:: ቢሰልሙም በእርግጥ ወደቀናው መንገድ ተመሩ:: እምቢ ቢሉ ግን ባንተ ላይ ያለብህ መልዕክትን ማድረስ ብቻ ነው:: አላህ ባሮቹን ተመልካች ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ በአላህ አናቅጽ የሚክዱ፤ ነብያትንም ያለ አግባብ የሚገድሉ፤ ከሰዎችም ውስጥ እነዚያን በትክክለኛነት የሚያዙትን የሚገድሉ በአሳማሚ ቅጣት አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 22, '22. እነዚያ በቅርቢቱም ሆን በመጨረሻይቱ ዓለም ስራዎቻቸው የተበላሹ ናቸው:: ለእነርሱም ምንም ረዳቶች የሏቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 23, '23. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ ከመጽሐፍ (ትምህርት) ድረሻን ወደ ተሰጡት ሰዎች አላየህምን? ወደ አላህ መጽሐፍ በመካከላቸው ይፈርድ ዘንድ ይጠራሉ:: ከዚያ ከእነርሱ ገሚሶቹ (ከፊሎቹ) እውነቱን ወደ ጎን የተው ሆነው ይሸሻሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 24, '24. ይህም እነርሱ «የገሀነም እሳት የተቆጠሩ ቀናትን ብቻ እንጂ አትነካንም።» በማለታቸው ነው:: በሀይማኖታቸዉም ይቀጣጥፉት የነበሩት ነገር አታለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 25, '25. በእርሱ መምጣት ጥርጥር የሌለበት በሆነው ቀን በሰበሰብናቸውና ነፍስ ሁሉ የሰራችውን ስራ በተሞላች ጊዜ እንዴት ይሆናሉ? እነርሱም ቅንጣትንም አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 26, '26. (መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) በል: «የንግስና ባለቤት የሆንከው አላህ ሆይ! ለምትሻው ሰው ንግስናን ትሰጣለህ:: ከምትሻዉም ሰው ንግስናን ትገፋለህ:: የምትሻውንም ሰው ታልቃለህ:: የምትሻውንም ሰው ደግሞ ታዋርዳለህ:: መልካም ነገር ሁሉ በእጅህ ብቻ ነው:: አንተ በነገሩ ሁሉ ላይ ቻይ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 27, '27. «ሌሊቱን በቀን ውስጥ ታስገባለህ:: ቀኑንም በሌሊት ውስጥ ታስገባለህ:: ሕያውንም ከሙት ታወጣለህ:: ሙታንንም ከሕያው ታወጣለህ፤ ለምትሻውም ሁሉ መጠን የለሽ ሲሳይ ትሰጣለህ።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 28, '28. አማኞች ከሓዲያንን ከአማኞች ሌላ ረዳቶች አድርገው አይያዙ። ይህንን የሚሰራ ከአላህ ሀይማኖት በምንም ውስጥ አይደለም:: ከእነርሱ መጠበቅን ብትጠበቁ እንጂ:: አላህ ከእርሱው ያስጠነቅቃችኋል:: መመለሻም ወደ አላህ ብቻ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) «በልቦቻችሁ ውስጥ ያለውን ሁሉ ብትደብቁት ወይም ብትገልጹት አላህ ያውቀዋል:: በሰማያት ውስጥ ያለውንና በምድር ውስጥ ያለውን ሁሉ ያውቃል:: አላህም በነገሩ ሁሉ ላይ ቻይ ነው።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ያን ነፍስ ሁሉ ከመልካም ነገር የሰራችውን የቀረበ ሆኖ የምታገኝበትን ቀን (አስታውስ):: ከመጥፎም የሰራችው በእርሷና በኃጢአቱ መካከል በጣም የሰፋ ርቀት ቢኖር ትመኛለች:: አላህ እራሱን ያስጠነቅቃችኋል:: አላህ ለባሮቹ ሩህሩህ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 31, '31. (መልዕክተኛችን ሙሐመድ ሆይ!)፡- «አላህን የምትወዱ እንደሆናችሁ እኔን ተከተሉኝ:: አላህም ይወዳችኋል፤ ኃጢአቶቻችሁንም ለእናንተ ይምራልና:: አላህ መሀሪና አዛኝ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 32, '32. (መልዕክተኛችን ሙሐመድ ሆይ!)፡- «አላህንና መልዕክተኛውን ታዘዙ። ብሸሹም አላህ ከሓዲያንን አይወድም» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 33, '33. አላህ (ነብዩ) አደምን፣(ነብዩ) ኑህን፣(የነብዩ) ኢብራሂምን ቤተሰብ እና የዒምራንን ቤተሰብ ከአለማት አበለጣቸው (መረጣቸው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 34, '34. እኒህን ቤተሰቦች ከፊሉ ከከፊሉ የሆነ ዝርያ አድርጎ መረጣቸው። አላህ ሁሉን ሰሚና ሁሉንም አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 35, '35. (መልዕክተኛችን ሙሐመድ ሆይ!) የዒምራን ባለቤት (ሀና) «ጌታዬ ሆይ! በሆዴ ውስጥ ያለውን ጽንስ ከሥራ ነፃ የተደረገ ሲሆን ላንተ አገልግሎት ይውል ዘንድ ተሳልኩ:: እናም ተቀበለኝ:: አንተ ሰሚና አዋቂ ነህና።» ባለች ጊዜ የሆነውን አስታውሱ በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 36, '36. በወለደቻትም ጊዜ፡- «ጌታዬ ሆይ! ሴት ሆና ወለድኳት።» አለች። አላህ የወለደችውን ምንነት አዋቂ ነው:: የተመኘችው ወንድ እንደ ወለደቻት ሴት የሚሆን አልነበረም:: «መርየምም ብዬ ስም አወጣሁላት:: እኔም እርሷንና ዝርያዋን ከተረገመው ሰይጣን ተንኮል ባንተ እጠብቃቸዋለሁ።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 37, '37. ጌታዋም በመልካም አቀባበል ተቀበላት:: በመልካም አስተዳደግም አፋፋት:: ከዚያም ዘከርያ አሳደጋት:: ዘከርያም ወደ ምኩራቧ በሷ ላይ በገባ ቁጥርም እርሷ ዘንድ ሲሳይን አገኘ:: «መርየም ሆይ! ይህ ለአንቺ ከየት ነው የሚመጣልሽ?» አላት። «እርሱ የሚመጣልኝ ከአላህ ዘንድ ነው:: አላህ እኮ ለሚሻው ሁሉ ሲሳዩን ያለ ሂሳብ ይሰጣል።» አለችው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 38, '38. እዚያ ዘንድም ዘከርያ ጌታውን እንደዚህ በማለት ለመነ: «ጌታዬ ሆይ! ካንተ ዘንድ መልካም ዘርን ለእኔ ስጠኝ:: አንተ ጸሎትን ሰሚ ነህና» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 39, '39. እርሱም በዱዓ ማድረጊያ ክፍል ቆሞ ዱዓ ሲያደርግ መላዕክት:- «አላህ በየህያ: ከአላህ በሆነ ቃል የሚያረጋግጥ፣ በላጭ፣ ከሴት ጋር የማይገናኝ ድንግልና ከደጋጎቹም አንዱ ሲሆን ያበስርሃል።» በማለት መላዕክት ጠሩት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 40, '40. ዘከርያም «ጌታዬ ሆይ! እኔ እርጅና የደረሰብኝ ሚስቴም መካን ስትሆን እንዴት ልጅ ይኖረኛል?» አለ። መልአኩም: «ልክ እንደዚሁ ነው። አላህ የሚሻውን ነገር ሁሉ ይሰራልና።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 41, '41. ዘከርያም «ጌታዬ ሆይ! ለእዚህ ነገር ምልክትን አድርግልኝ።» አለ:: «ምልክትህ ሶስት ቀን በጥቅሻ እንጂ ሰዎችን አለማናገርህ ነው:: በዚያ ጊዜ ጌታህን በብዙ አውሳ:: በማታና በጠዋትም አወድሰው።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) መላእክትም ባሉ ጊዜ: «መርየም ሆይ! አላህ በእርግጥ መረጠሸ:: ከነውሮች ሁሉ አጸዳሸ:: ከዓለማት ሴቶችም መካከል መረጠሸ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 43, '43. «መርየም ሆይ! ለጌታሽ ታዘዢ:: ስገጂም:: ከአጎንባሾች ጋርም ሁነሽ አጎንብሺ።» (ያለበትን ታሪክ ለህዝቦችህ አውሳ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 44, '44.(መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ታሪክ ወደ አንተ ከምናወርደው ከሩቅ ወሬ ነው:: መርየምን ማን እንደሚያሳድግ ብዕሮቻቸውን ለዕጣ በጣሉ ጊዜ አንተ እነርሱ ዘንድ አልነበርክም:: በሚከራከሩም ጊዜ እነርሱ ዘንድ አልነበርክም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) መላዕክትም «መርየም ሆይ! አላህ ከእርሱ በሆነው ቃል የሚፈጠር ስሙ አል መሲህ ዒሳ የመርየም ልጅ በሚባል፤ በዚህ ዓለምም ሆነ በመጨረሻው ዓለም የተከበረና ከባለሟሎቹ አንዱ በሆነ ልጅ ያበስርሻል። (ባላት ጊዜ እዚያ ቦታ አልነበርክም) ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 46, '46. «እርሱም ገና በህፃንነቱ ካደገም በኋላ ሰዎችን ያነጋግራል:: ከመልካሞቹም አንዱ ነው።» (አላት)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 47, '47. እርሷም «ጌታዬ ሆይ! ማንም ሰው በትዳርም ሆነ በዝሙት ሳይነካኝ እንዴት ልጅ ይኖረኛል?» አለች:: መልአኩ ጅብሪልም አላት: «እነደዚሁ ነው። አላህ የሚሻውን ሁሉ ይፈጥራል። የአንድን ነገር መሆን በፈለገ ጊዜ የሚለው ‹ሁን› ብቻ ነው። ወዲያውኑም ያ ነገር ይሆናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 48, '48. «ጽሕፈትንና ጥበብን፤ ተውራትንና ኢንጂልንም ያስተምረዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 49, '49.«ወደ ኢስራኢል ልጆችም መልዕክተኛ ያደርገዋል። ይላልም: ›, ‹እኔ ከጌታዬ ዘንድ በተዐምር መጣሁላችሁ:: እኔ ለእናንተ ከጭቃ የወፍ ቅርጽ አይነት እፈጥራለሁ:: በእርሱም እተነፍስበታለሁ:: ከዚያም በአላህ ፈቃድ ወፍ ይሆናል:: እውር ሆኖ የተወለደንም ለምጸኛንም በአላህ ፈቃድ አድናለሁ:: ሙታንንም በአላህ ፍቃድ አስነሳለሁ:: የምትበሉትንና በየቤቶቻችሁ የምታደልቡትን ሁሉ እነግራችኋለሁ:: (መረጃዎችን አገናዝባችሁ) የምታምኑ እንደሆናችሁ ለእናንተ በዚህ ውስጥ ግልጽ ተዐምር አለበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 50, '50.«‹ከእኔ በፊት የነበረውን ተውራትን ያረጋገጥኩ ስሆን ያንም በእናንተ ላይ እርም የተደረገውን ነገር ከፊሉን ለእናንተ እፈቅድ ዘንድ መጣሁላችሁ:: ከጌታችሁም በሆነ ተዐምር መጣሁላችሁ:: አላህን ፍሩ:: እኔንም ታዘዙኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 51, '51.«‹አላህ ጌታዬ የእናንተም ጌታችሁ ነው:: ስለዚህ በብቸኝነት ተገዙት:: ይህ ቀጥተኛው መንገድ ነው።› ይላቸዋል»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 52, '52. ዒሳ ከእነርሱ ክህደት በተሰማው ጊዜ፡- «ወደ አላህ የእኔ ረዳቶች የሚሆኑ እነማን ናቸው?» አለ:: ሀዋርያትም አሉ፡- «ዒሳ ሆይ! እኛ የአላህ ረዳቶች ነን:: በአላህ አምነናል:: ትክክለኛና ታዛዦች መሆናችንን መስክር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 53, '53. («ጌታችን ሆይ! ባወረድከው አምነን መልዕክተኛውን ተከትለናል::( እኛንም ባንተ ብቸኛ አምላክነት በነብያት መልዕክተኛነት) ከመስካሪዎች ጋራ መዝግበን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 54, '54.አይሁድም በዒሳ ላይ አደሙ:: አላህ ግን አድማቸውን አከሸፈባቸው። አላህ የአድመኞችን ሴራ በማክሸፍ ከሁሉ የበለጠ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 55, '55. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ባለ ጊዜ (አስታውስ)፡- «ዒሳ ሆይ! እኔ ወሳጅህና ከምድር ወደ እኔ አንሽህ ነኝ:: ከነዚያም በእኔ ከካዱ ሰዎች (ተንኮል) አጥሪህ ነኝ። እነዚያ የተከተሉህንም እስከ ትንሳኤ ቀን ድረስ ከነዚያ ከካዱት በላይ አድራጊ ነኝ:: ከዚያ የሁላችሁም መመለሻችሁ ወደ እኔ ነው:: ያን ትለያዩበት በነበራችሁበት ነገርም በመካከላችሁ እፈርዳለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 56, '56.«እነዚያማ የካዱትን በቅርቢቱ ዓለምም ሆነ በመጨረሻይቱ ዓለም ብርቱ ቅጣትን እቀጣቸዋለሁ:: ለእነርሱም ምንም ረዳቶች የሏቸዉም»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 57, '57. እነዚያማ አምነው መልካም ስራዎችን የሰሩትን አላህ ምንዳቸውን ይሞላላቸዋል:: አላህም በዳዮችን አይወድምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 58, '58.(መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ተዓምራትና ጥበብን ከያዘው ተግሳጽ በአንተ ላይ የምናነበው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 59, '59. አላህ ዘንድ የዒሳ (ያለ አባት መፈጠሩ) ምሳሌው ልክ እንደ (ያለ አባትና ያለ እናት እንደተፈጠሩት አባታችን) አደም ቢጤ ነው:: አላህ ከአፈር ፈጠረውና ከዚያም «ሁን» አለው። ከዚያ ሰው ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 60, '60.(መልዕክተኛችን ሙሐመድ ሆይ!) እውነታው ከጌታህ ዘንድ የመጣልህ እውነት ነው። እናም ከተጠራጣሪዎች አትሁን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 61, '61.(መልዕክተኛችን ሙሐመድ ሆይ!) እውቀት ከመጣልህ በኋላ በእርሱ (በዒሳ) የተከራከሩህን «ኑ ልጆቻችንንና ልጆቻችሁን፣ ሴቶቻችንንና (ሚስቶቻችንና) ሴቶቻችሁን (ሚስቶቻችሁን)፣ ነፍሶቻችንንና ነፍሶቻችሁን እንጥራና ከዚያ አላህን እንለምን:: የአላህንም ቁጣ በውሸታሞች ላይ እናድርግ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 62, '62.(መልዕክተኛችን ሙሐመድ ሆይ!) ይህ እውነተኛው ታሪክ ነው:: ትክክለኛ አምላክም ከአላህ በስተቀር የለም። አላህም አሸናፊውና ጥበበኛው አምላክ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 63, '63. (ከማመን) እምቢ ቢሉም (አጥፊዎቹ እነርሱ ናቸው።) አላህ አጥፊዎቹን (ከደህናዎቹ) ለይቶ አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 64, '64.(መልዕክተኛችን ሙሐመድ ሆይ!) «የመጽሐፉ ባለቤቶች ሆይ! በእኛና በእናንተ መካከል ትክክል ወደ ሆነችው ቃል ኑ። (እርሷም) ‹አላህን ብቻ እንጂ ሌላን ላንገዛ፤ በእርሱም ምንንም ላናጋራ፤ ከፊላችንም ከፊሉን ከአላህ ሌላ አማልክት አድርጎ ላይዝ› ነው።» በላቸው። (ሙስሊሞች ሆይ!) እምቢ ካሉም «እኛ ሙስሊሞች መሆናችንን መስክሩ።» በሏቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 65, '65. እናንተ የመጽሐፉ ባለቤቶች ሆይ! በኢብራሂም (ዙሪያ) ለምን ትከራከራላችሁ? ተውራትና ኢንጂል ከእርሱ በኋላ እንጂ አልተወረዱ። ልብ አትሉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 66, '66 እናንተ እነዚያ እውቀት ባላችሁ ነገር የተከራከራችሁ ናችሁ፡፡ ታዲያ እውቀት በሌላቸሁ ነገር ላይ ለምን ትከራከራላችሁ? አላህ ሁሉን ነገር ያውቃል። እናንተ ግን አታውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 67, '67. ኢብራሂም አይሁድም ሆነ ክርስቲያን አልነበረም:: ግን በቀጥተኛው ሃይማኖት ቀጥ ያለ ሙስሊም ነበር:: ከአጋሪዎችም አልነበረም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 68, '68.በኢብራሂም ይበልጥ ተገቢዎቹ እነዚያ የተከተሉት፤ ይህ ነብይ (ነብዩ ሙሐመድ) እና እነዚያ ያመኑት ብቻ ናቸው፡፡ አላህ የአማኞች ወዳጅ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 69, '69. (ሙስሊሞች ሆይ!) ከመጽሐፉ ባለቤቶች የተወሰኑት ነፍሶቻቸውን እንጂ የማያሳስቱ ሲሆኑ እናንተን ሊያሳስቷችሁ ተመኙ:: እራሳቸውን እንጂ ማንንም አያሳሳስቱም፡፡ እነርሱ ግን ይህንን እውነታ አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 70, '70. እናንተ የመጽሐፍ ባለቤቶች ሆይ! እናንተ የምታውቁ ስትሆኑ በአላህ አናቅጽ ለምን ትክዳላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 71, '71. እናንተ የመጽሐፉ ባለቤቶች ሆይ! እውነትን ከውሸት ጋር ለምን ትቀላቅላላችሁ? እውነቱንም የምታውቁ ስትሆኑ ለምን ትደብቃላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 72, '72. ከመጽሐፉ ባለቤቶች የሆኑ ቡድኖችም በዚያ ባመኑት ላይ በተወረደው ቁርኣን «በቀኑ መጀመሪያ ላይ እመኑበትና በቀኑ መጨረሻ ላይ ካዱ። እነርሱ ሊመለሱ ይከጀላልና።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 73, '73. (አሉም) «ሃይማኖታችሁን ለተከተለ እንጂ አትመኑም።» (መልዕክተኛችን ሙሐመድ ሆይ!) «ትክክለኛው መመሪያ የአላህ መመሪያ ብቻ ነው። እናንተ ያገኛችሁትን እድል እንዳያገኙ ወይም በእርሱ ከጌታችሁ ፊት እንዳይሞግቷችሁ በመፍራት ነውን?» በላቸው። (መልዕክተኛችን ሙሐመድ ሆይ!) «ችሮታ በአላህ እጅ ብቻ ነው። ለሚፈልገውም ይሰጠዋል። አላህም ችሮታው ሰፊና ሁሉን አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 74, '74. በችሮታው የሚሻውን ይመርጣል:: አላህ የታላቅ ችሮታ ባለቤት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 75, '75. ከመጽሐፉ ባለቤቶች መካከል በብዙ ገንዘብ ላይ ብታምነው ቅንጣት ሳያጎድል የሚመልስልህ አለ:: ከእነርሱም መካከል በአንድ ዲናር እንኳን ብታምነው ሁል ጊዜም እሱ ላይ የምትጠባበቅ ካልሆንክ በስተቀር የማይመልስልህም አለ:: ይህ «በመሀይማን ህዝቦች ላይ በምናደርገው በደል በእኛ ላይ የምንጠየቅበት መንገድ የለብንም።» ስለሚሉና እነርሱም እያወቁ በአላህ ላይ ውሸትን ስለሚናገሩ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 76, '76 ጉዳዩ እነርሱ እንዳሉት አይደለም (ተጠያቂነት አለባቸው)። ያ በቃል ኪዳኑ የሞላና የተጠነቀቀን ሁሉ አላህ ጥንቁቆችን ይወዳል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 77, '77. እነዚያ በአላህ ቃል ኪዳንና በመሀላዎቻቸው ጥቂትን ዋጋን የሚለውጡ ሁሉ በመጨረሻይቱ ዓለም ምንም እድል የላቸዉም:: በትንሳኤም ቀን አላህ አያነጋግራቸዉም:: ወደ እነርሱም አይመለከትም:: አያጸዳቸዉምም:: ከቶውንም ለእነርሱ አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 78, '78. ከእነርሱም መካከል ከመጽሐፉ ያልሆነን ነገር ከመጽሐፉ አካል መሆኑን እንድታስቡ በመጽሐፉ ምላሶቻቸውን የሚያጣምሙም አሉ:: እርሱ ከአላህ ዘንድ ያልመጣ (ያልወረደ) ሲሆን «ከአላህ ዘንድ የመጣ (የወረደ) ነው።» ይላሉ። የሚያውቁ ሲሆኑ በአላህ ላይ ውሸትን ይናገራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 79, '79. ለማንም ሰው አላህ መጽሐፍን፣ ጥበብንና ነብይነትን ሰጥቶት ከዚያ ለሰዎች «ከአላህ ሌላ ለእኔ ባሮች ሁኑ።» ሊል አይገባዉም:: ይልቁንም «መጽሐፉን የምታስተምሩና የምታጠኑ በነበራችሁበት በእውቀታችሁ ለራሳችሁ ተግባሪዎች ሁኑ።» ይላቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 80, '80. መላዕክትንና ነብያትንም አማልክት አድርጋችሁ እንድትይዙ ሊያዛችሁ አይገባም:: (እናንተ) ሙስሊሞች ከሆናችሁ በኋላ በክህደት ያዛችኋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 81, '81. (መልዕክተኛችን ሙሐመድ ሆይ!) «መጽሐፍንና ጥበብን ሰጥቻችሁ ከዚያ ከናንተ ጋር ላለው መጽሀፍ የሚያረጋግጥ መልዕክተኛ ቢመጣላችሁ በእርሱ እንድታምኑበት እንድትረዱትም።» ሲል አላህ የነቢያትን ቃል ኪዳን በያዘ ጊዜ (የነበረውን ክስተት ለህዝቦችህ አስታውስ)። «አረጋገጣችሁን? በዚህስ ላይ ቃል ኪዳኔን ያዛችሁን?» አላቸው። እነርሱም «አዎ አረጋገጥን» አሉ። «እንግዲያውስ መስክሩ:: እኔም ከናንተ ጋር ከመስካሪዎቹ ነኝ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 82, '82. እናም ከዚህ በኋላ የሸሹ አመጸኞቹ እነርሱ ብቻ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 83, '83. በሰማያትና በምድር ያሉ ሁሉ በውድም ሆነ በግድ ለእርሱ የታዘዙና ወደ እርሱ የሚመለሱ ሲሆኑ (ከሓዲያን) ከአላህ ሃይማኖት ሌላን ይፈልጋሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 84, '84. (መልዕክተኛችን ሙሐመድ ሆይ!) «በአላህ አምነናል በእኛም ላይ በተወረደው በቁርኣን (በነብዩ) ኢብራሂም፣ (በነብዩ) ኢስማኢል፣ (በነብዩ) ኢስሀቅ፣ (በነብዩ) የዕቆብና በነገዶች ላይ በተወረደው፣ ለነብዩ ሙሳ ለነብዩ ዒሳና ለነብያትም ሁሉ ከጌታቸው በተሰጠው ሁሉ አምነናል:: በእነርሱ መካከል አንድንም አንለይም:: እኛ ለእርሱ ብቻ ታዛዦች ነን።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 85, '85. ከኢስላም ሌላ ሃይማኖትን የሚፈልግ ሁሉ ፈጽሞ ከእርሱ ተቀባይነት የለዉም:: እርሱም በመጨረሻይቱ ዓለም ከከሳሪዎቹ አንዱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 86, '86. ከእምነታቸውና መልዕክተኛዉም እውነት መሆኑን ከመሰከሩ፤ የተብራሩ አናቅጽም ከመጡላቸው በኋላ የካዱ ሕዝቦችን አላህ እንዴት ያቀናል? አላህ በዳዮችን ሕዝቦች አያቀናምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 87, '87. እነዚያን መሰሎች ቅጣታቸው የአላህ፣ የመላዕክትና የሰዎች ሁሉ እርግማን በእነርሱ ላይ መውረዱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 88, '88. በውስጧ ዘወታሪዎች ሲሆኑ ቅጣቱም ከእነርሱ ላይ አይቃለልላቸዉም:: ጊዜም አይሰጡም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 89, '89. እነዚያ ከዚያ በኋላ ንስሀ የገቡና ስራቸውን ያሳመሩ ሁሉ ሲቀሩ፤ (አላህ እነዚህንማ ይምራቸዋል።) አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 90, '90. እነዚያ ከእምነታቸው በኋላ የካዱና ከዚያ ክህደትን በክህደት ላይ የጨመሩ ንሰሃቸው ፈጽሞ ተቀባይነት የለዉም:: የተሳሳቱ ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 91, '91. እነዚያ የካዱና በክህደታቸው ላይ እንዳሉ የሞቱ፤ ከእነርሱ አንዳቸው ምድርን የሞላ ወርቅ ቤዛ ቢያቀርብም እንኳ ፈጽሞ ተቀባይነት አያገኝም:: እነዚያ ለእነርሱ የሚያሰቃይ ቅጣት አለባቸው:: ለእነርሱም (ከዚህ ቅጣት) የሚያድኗቸው ምንም ረዳቶች የሏቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 92, '92. (ሙስሊሞች ሆይ!) ከምትወዱት ነገር እስከምትለግሱ ድረስ የበጎ ስራን ዋጋ (ገነትን) አታገኙም:: ከምንም ነገር ብትለግሱም አላህ ያውቀዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 93, '93. (መልዕክተኛችን ሙሐመድ ሆይ!) ተውራት ከመውረዱ በፊት ኢስራኢል በራሱ ላይ እርም ካደረገው ነገር በስተቀር ምግብ ሁሉ ለኢስራኢል ልጆች የተፈቀደ ነበር። «እውነተኞች ከሆናችሁ እስኪ ተውራትን አምጡና አንብቡት።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 94, '94. ከዚህ በኋላ በአላህ ላይ ውሸትን የቀጣጠፉ ሰዎች እነዚያ እነርሱ ብቻ በዳዮች (በደለኞች) ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 95, '95. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ እውነትን ተናገረ። (ትክክለኛ የኢብራሂም ወዳጆች ከሆናችሁ) የኢብራሂምንም መንገድ ቀጥተኛ ሲሆን ተከተሉ። ከአጋሪዎችም አልነበረም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 96, '96. ለሰዎች (ማምለኪያ ይሆን ዘንድ በመሬት ላይ) በመጀመሪያ የተሰራው ቤት ብሩክና ለዓለማት ሁሉ መመሪያ ሲሆን ያ በበካህ (በመካ) ያለው ቤት (ካዕባ) ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 97, '97. በውስጡ ግልጽ የሆኑ ተዐምራት አሉበት:: የኢብራሂምም መቆሚያ (የነበረው በዉስጡ አለ::) ወደ እርሱ የገባም ሁሉ ሰላም ይሆናል። በሰዎች ላይ ወደ እርሱ የመሄድን ጣጣ በቻለ ሁሉ ግዴታቸው ሲሆን ቤቱን ሊጎብኙት ለአላህ መብት አለው። በአላህ የካደ (ግን እራሱን እንጂ ማንንም አይጎዳም።) አላህ ከዓለማት ሁሉ የተብቃቃ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 98, '98.(መልዕክተኛችን ሙሐመድ ሆይ!) «የመጽሐፉ ሰዎች ሆይ! አላህ በምትሰሩት ሁሉ ላይ አዋቂ ሲሆን በአላህ ተዐምራቱ ለምን ትክዳላችሁ?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 99, '99. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ የመጽሐፉ ሰዎች ሆይ! እናንተ መስካሪዎች ሆናችሁ ከአላህ መንገድ መጥመሟን የምትፈልጉ ስትሆኑ ያመነን ሰው ለምን ትከለክላላችሁ? አላህም ከምትሰሩት ነገር ላይ ሁሉ ዘንጊ አይደለም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 100, '100. እናንተ ያመናችሁ ሆይ! ከእነዚያ መጽሐፍትን ከተሰጡ መካከል ከፊሎቹን ብትታዘዙ ከእምነታችሁ በኋላ ወደ ክህደት ይመልሷችኋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 101, '101. የአላህ አናቅጽ በእናንተ ላይ እየተነበቡና መልዕክተኛዉም በመካከላችሁ እያለ እንዴት ትክዳላችሁ? በአላህ የሚጠበቅ ሰው ሁሉ ወደ ቀጥተኛው መንገድ በእርግጥ ተመራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 102, '102. እናንተ ያመናችሁ ሆይ! አላህን ትክክለኛውን ፍራቻ ፍሩት። እናንተም ሙስሊሞች ሆናችሁ እንጂ አትሙቱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 103, '103. (እናንተ ያመናችሁ ሆይ!) የአላህን ጠንካራ የእምነት ገመድም ሁላችሁም ያዙ:: አትለያዩም። ጠበኞች በነበራችሁ ጊዜ በእናንተ ላይ የዋለውን የአላህን ጸጋም አስታውሱ:: ይሀውም በልቦቻችሁ መካከል አስማማ በጸጋዉም ወንድማማቾች ሆናችሁ:: በእሳት ጉድጓድ አፋፍ ላይ የነበራችሁ ስትሆኑ ከእርሷም አዳናችሁ:: ወደ ቀጥተኛው መንገድ ትመሩ ዘንድ አላህ ለእናንተ አናቅጽን እንደዚሁ ያብራራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 104, '104. (እናንተ ያመናችሁ ሆይ!) ከናንተ መካከል ወደ በጎ ነገር የሚጠሩና በመልካም ስራ የሚያዙ፤ ከክፉ ነገርም የሚከለክሉ ቡድኖች ይኑሩ:: እነዚያ ከእሳት የሚድኑ እነርሱው ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 105, '105. (እናንተ ያመናችሁ ሆይ!) እንደነዚያ ግልጽ ተዐምራት ከመጣላቸው በኋላ እንደተለያዩትና እንደተጨቃጨቁት የመጽሐፉ ባለቤት ሰዎች አትሁኑ:: እነዚያም ለነርሱ ታላቅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 106, '106.ያን ፊቶች የሚያበሩበትና ፊቶች የሚጠቁሩበትን የትንሳኤን ቀን አስታውሱ። እነዚያ ፊቶቻቸው የጠቆሩት ወገኖች «ከእምነታችሁ በኋላ ካዳችሁን? እግዲያዉስ ትክዱ የነበራችሁትን ነገር ቅጣቱን ቅመሱ።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 107, '107. እነዚያ ፊቶቻቸው ያበሩት ወገኖች ደግሞ በአላህ ችሮታ ገነት ውስጥ ናቸው:: እነርሱ በውስጧ ዘወታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 108, '108. እነኚህ ባንተ ላይ በእውነት የምናነባቸው የአላህ አናቅጽ ናቸው:: አላህም ለዓለማት በደልን የሚሻ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 109, '109. በሰማያትና በምድር ውስጥ ያለ ሁሉ የአላህ ነው:: ነገሮች ሁሉ ወደ አላህ ይመለሳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 110, '110. (ሙስሊሞች ሆይ!) ለሰው ልጆች ከተገለፁት ሕዝቦች ሁሉ በላጭ ሆናችሁ:: ይኸዉም በመልካም ነገር ታዛላችሁ:: ከመጥፎም ነገር ትከለክላላችሁ:: በአላህም አንድነት ታምናላችሁና ነው:: የመጽሐፉ ሰዎችም ልክ እንደናንተው ባመኑ ኑሮ ለእነርሱ የተሻለ በሆነ ነበር። ከእነርሱ መካከል ትክክለኛ አማኞችም አሉ:: አብዛሀኞቻቸው ግን አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 111, '111 (ሙስሊሞች ሆይ!) ማስከፋትን እንጂ ፈጽሞ አይጎዷችሁም:: ቢዋጓችሁም ጀርባዎችን ያዞሩላችኋል (ይሸሻሉ)። ከዚያም በምንም ረዳት አያገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 112, '112. በየተገኙበት ስፍራ ከአላህ በሆነ ቃልኪዳን ወይም ከሰዎች በሆነ ቃል ኪዳን የተጠበቁ ካልሆኑ በስተቀር በእነርሱ ላይ ውርደት ተጽፎባቸዋል። ከአላህ በሆነ ቁጣ ተመለሱ። ድህነትም በእነርሱ ላይ ተፅፎባቸዋል። ይህ የሆነውም በአላህ ተዐምራት (አናቅጽ) ይክዱ፤ ነቢያትንም ያላ አግባብ ይገድሉ ስለነበሩ ነው:: ይህም የሆነው በማመፃቸውና ወሰንን ይተላለፉ ስለነበሩ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 113, '113. የመጽሐፉ ባለቤቶች ሁሉ እኩል አይደሉም:: ከመጽሐፉ ባለቤቶች መካከል ቀጥ ያሉና በሌሊት ሰዓቶች እየሰገዱ የአላህን አናቅጽ የሚያነቡ ሕዝቦችም አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 114, '114. በአላህና በመጨረሻዉም ቀን ያምናሉ:: በጽድቅም ነገር ያዛሉ:: ከመጥፎ ነገርም ይከለክላሉ:: ለበጎ ስራዎችም ይጣደፋሉ:: እነርሱ ከደጋግ ሰዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 115, '115. ከበጎ የሚሰሩትን አይካዱም። (ውድቅ አይደረግባቸዉም::) አላህ ጥንቁቆቹን ሁሉ አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 116, '116. እነዚያ በአላህ የካዱት ገንዘቦቻቸውና ልጆቻቸው ከአላህ ቅጣት ምንንም አያድኗቸዉም:: እነዚያም የእሳት ጓዶች ናቸው:: እነርሱም በእርሷ ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 117, '117. በዚህች በቅርቢቱ ሕይወት የሚለግሱት ነገር ምሳሌው በውስጧ ውርጭ ያለባት ነፋስ ነፍሶቻቸውን የበደሉን ሕዝቦች አዝመራ እንደነካችና እንዳጠፋች ብጤ ነው። አላህም አልበደላቸዉም። ግን እነርሱ ነፍሶቻቸውን በእራሳቸው የሚበድሉ ናቸው እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 118, '118. እናንተ ያመናችሁ ሆይ! ሚስጥረኛን (የልብ ወዳጅ) ከእናንተ ሌላ ከሆኑት አታድርጉ። የእናንተን ጉዳይ ከማበላሸት አይቦዝኑላችሁምና። ጉዳታችሁን ይወዳሉና (ይመኛሉ)። ለእናንተ ያላቸው ጥላቻ ከአፎቻቸው ላይ እንኳ ተገለጸ:: በልቦቻቸው የሚደብቁት ደግሞ ከዚህ ይበልጥ የከፋ ነው:: ልብ የምታደርጉ እንደሆናችሁ ለእናንተ ማብራሪያዎችን በእርግጥ ገለጽን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 119, '119. እናንተ ትወዷቸዋላችሁ:: እነርሱ ግን በፍጹም አይወዷችሁም:: እናንተ በሁሉም መጽሐፍት ታምናላችሁ:: እነርሱ ግን ባገኟችሁ ጊዜ «አምነናል» ይላሉ:: ከናንተ ባገለሉ ጊዜ ግን ከቁጭታቸው የተነሳ በእናንተ ላይ ዐጥቆቻቸውን (ጣቶቻቸውን) ይነክሳሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «በቁጭታችሁ ሙቱ። አላህ ልቦች የቋጠሩትን ሁሉ አዋቂ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 120, '120. ደግ ነገር ብታገኙ ይከፋቸዋል:: መጥፎ ነገር ቢደርስባችሁ ግን በሷ ይደሰታሉ:: ከታገሳችሁና አላህን ከፈራችሁ ተንኮላቸው ምንም አይጎዳችሁም:: አላህ ለሚሰሩት ሁሉ በዕውቀቱ ከባቢ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 121, '121. (መልዕክተኛችን ሙሐመድ ሆይ!) አማኞችን ለውጊያ ስፍራዎች የምታዘጋጅ ሆነህ ከቤተሰብህ በጧት በወጣህ ጊዜ የሆነውን አስታውስ:: አላህ ሁሉን ሰሚ ሁሉንም አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 122, '122. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ረዳታቸው ሲሆን ከእናንተ መካከል ሁለት ቡድኖች (ወገኖች) ለመፍራት ባሰቡ ጊዜ የሆነውን አስታውስ:: በአላህ ላይ ብቻ አማኞች ይመኩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 123, '123. (እናንተ ያመናችሁ ሆይ!) በበድር ዘመቻ ዕለት እናንተ ጥቂቶች ሆናችሁ ሳለ አላህ በእርግጥ ረዳችሁ:: አላህን ታመሰግኑ ዘንድ ፍሩት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 124, '124. (መልዕክተኛችን ሙሐመድ ሆይ!) ለአማኞች (እንዲህ) በምትል ጊዜ የሆነውን አስታውስ: «ጌታችሁ በሶስት ሺ መላዕክት የተወረዱ ሲሆኑ ቢረዳችሁ አይበቃችሁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 125, '125. «አዎን! ብትታገሱና ብትጠነቀቁ አሁኑኑ በፍጥነት ጠላቶቻችሁ ቢመጡባችሁም ጌታችሁ ምልክት ባላቸው አምስት ሺህ መላዕክት ይረዳችኋል።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 126, '126. አላህ ለእናንተ ብስራትና ልቦቻችሁ በእርሱ እንዲረኩ እንጂ እርዳታውን ለምንም አላደረገዉም:: ድልም አሸናፊና ጥበበኛ ከሆነው ከአላህ ዘንድ ብቻ እንጂ ከሌላ ከማንም የሚገኝ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 127, '127. (ድልን ያጎናፀፋችሁ) ከእነዚያ ከካዱት ከፊልን ሊቆርጥ (ሊያጠፋ) ወይም ሊያዋርዳቸውና ያፈሩ ሁነው እንዲመለሱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 128, '128. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱ ራሳቸውን በዳዮች ናቸውና አላህ በእነርሱ ላይ ከፈለገም ይቅርታ ቢያደርግ ወይም በጥፋታቸው ቢቀጣቸውም ላንተ በነገሩ ላይ ምንም የለህም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 129, '129. በሰማያትና በምድር ውስጥ ያለውም ሁሉ የአላህ ብቻ ነው:: ለፈለገው ሰው ይምራል:: የሚፈለገውን ሰው ይቀጣል:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 130, '130. እናንተ ያመናችሁ ሆይ! አራጣን የተነባበሩ እጥፎች ሲሆኑ አትብሉ:: ከገሀነም እሳት ትድኑም ዘንድ (አራጣን በመተው) አላህን ፍሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 131, '131. ያችን ለከሓዲያን የተደገሰችውን የገሀነም እሳት ተጠንቀቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 132, '132.(እናንተ ያመናችሁ ሆይ!) ይታዘንላችሁም ዘንድ አላህንና መልዕክተኛውን ታዘዙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 133, '133. ወደ ጌታችሁ ምህረትና ስፋቷ ሰባቱ ሰማያትንና ምድርን ያክል ወደ ሆነችው ገነት አላህን ለሚፈሩ የተዘጋጀች ስትሆን ተቻኮሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 134, '134. ለእነዚያ በድሎትም ሆነ በችግር ጊዜ ለሚለግሱት፤ ቁጭትንም ገቺዎች፤ ለሰዎችም ይቅርታ አድራጊዎች ለሆኑት፤ አላህ በጎ ሰሪዎችን ሁሉ ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 135, '135. ለእነዚያም መጥፎ ስራን በሰሩ ወይም ነፍሶቻቸውን በበደሉ ጊዜ አላህን የሚያስታውሱና ለኃጢአቶቻቸው ምህረትን የሚለምኑ ለሆኑት ተደግሳለች:: ከአላህ ሌላ ኃጢአቶችን የሚምር ማን ነው? (አንድም የለም::) በስህተት በሰሩት ላይ እነርሱ የሚያውቁ ሲሆኑ የማይዘወትሩ ለሆኑት ሁሉ ተደግሳለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 136, '136. እነዚያ ምንዳቸው ከጌታቸው ምህረትና በውስጣቸው ዘውታሪዎች ሲሆኑ በስሮቻቸው ወንዞች የሚፈሱባቸው ገነቶችም ናቸው:: የመልካም ሰሪዎች ሁሉ ምንዳ የሆነችው ገነት ምንኛ አማረች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 137, '137. (እናንተ ያመናችሁ ሆይ!) ከእናንተ በፊት በእርግጥ ብዙ አልፈዋል። በምድር ላይ ሂዱና ያስተባባዮች ፍፃሜ እንዴት እንደነበረ ተመልከቱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 138, '138. ይህ ቁርኣን ለሰዎች ሁሉ ማብራርያ፤ ለጥንቁቆችም መመሪያና ገሳጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 139, '139. (እናንተ ያመናችሁ ሆይ!) እናንተ የበላዮች ናችሁና ትክክለኛ አማኞች እንደሆናችሁ አትድከሙ (አትስነፉ)። አትዘኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 140, '140. አማኞች ሆይ! የመቁስል ጉዳት ቢያገኛችሁ ሌሎች ህዝቦችም መሰሉ የመቁሰል ጉዳት አግኝቷቸዋል። እንዲሁ ቀናትን በሰዎች መካከል እናፈራርቃቸዋለን:: አላህ እነዚያን በትክክል በሱ ያመኑትን ሊለይና ከእናንተም መካከል ሰማዕታትን ሊመርጥ እንዲህ አይነት ቀናት እንዲፈራረቁ ያደርጋል:: አላህም በዳዮችን ሁሉ አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 141, '141. አላህ እነዚያን በትክክል በእርሱ ያመኑትን ከኃጢአት ሊያጸዳና ከሓዲያንንም ሊያጠፋ ይህንን አደረገ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 142, '142. (እናንተ ያመናችሁ ሆይ!) አላህ ከናንተ መካከል እነዚያን የታገሉትንና ታጋሾችን ሳይለይ ገነትን የምትገቡ መሰላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 143, '143. በጦርነት ላይ መሞትን ሳታገኙት በፊት የምትመኙት ነበራችሁ:: እናንተም በአይናችሁ የምትመለከቱ ስትሆኑ በእርግጥ አያችሁት። (ታዲያ ለምን ሸሻችሁት?)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 144, '144. (መልዕክተኛችን) ሙሐመድ ከበፊቱ ብዙ መልዕክተኞች እንዳለፉት የሆነ መልዕክተኛ እንጂ አይደለም:: ታዲያ እሱ ቢሞት ወይ ቢገደል ወደ ኋላችሁ ትገለበጣላችሁን? ወደ ኋላው የሚቀለበስም አላህን ምንም አይጎዳም:: አላህ አመስጋኞቹን ተገቢዉን ይመነዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 145, '145. ማንኛዋም ነፍስ በተወሰነላት ጊዜ በአላህ ፈቃድ ቢሆን እንጂ አትሞትም። የቅርቢቱን ዓለም ምንዳ የሚፈልግን ሁሉ ከእርሷ እንሰጠዋለን:: የመጨረሻይቱን ዓለም ምንዳ የሚፈልግንም ከእርሷ እንሰጠዋለን:: አመስጋኞችንም በእርግጥ ተገቢውን እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 146, '146. ከነብያት ሊቃውንት ከእነሱ ጋር ሆነው የተዋጉ ብዙ አሉ። እናም በአላህ መንገድ ለሚደርስባቸው ነገር ምንም አልፈሩም:: አልደከሙም:: ለጠላት አልተዋረዱም:: አላህም ትዕግስተኞቹን ይወዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 147, '147. ንግግራቸዉም «ጌታችን ሆይ! ኃጢአቶቻችንንና በነገራችን ሁሉ ወሰን ማለፋችንን ማርልን። ጫማዎቻችንንም አደላድል:: በከሓዲያን ሕዝቦች ላይም እርዳን።» ማለታቸው እንጂ ሌላ አልነበረም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 148, '148. አላህ የቅርቢቱን ዓለም ምንዳና የመጨረሻይቱን መልካም ምንዳ ሰጣቸው:: አላህ በጎ አድራጊዎችን ሁሉ ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 149, '149. እናንተ ያመናችሁ ሆይ! እነዚያን በአላህ የካዱትን ብትታዘዙ ወደ ኋላችሁ ይመልሷችኋል። ከከሳሪዎቹም ትሆናላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 150, '150. ይልቁን አላህ ብቻ ረዳታችሁ ነው:: እርሱ ከረዳቶች ሁሉ በላጭ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 151, '151. በእነዚያ በካዱት ልቦች ውስጥ አላህ በእሱ አስረጂ ያላወረደበትን ነገር በአላህ በማጋራታቸው ምክንያት ፍርሃትን እንጥላለን:: መኖሪያቸዉም የገሀነም እሳት ናት:: የበዳዮች መኖሪያ የሆነችው ገሀነምም መኖሪያነቷ ምን ትከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 152, '152. በእርግጥ አላህ በፈቃዱ ጠላቶቻችሁን በምትጨፈጭፏቸው ጊዜ ቃልኪዳንን በእርግጥ አረጋገጠላችሁ:: የምትወዱትንም ነገር ካሳያችሁ በኋላ በፈራችሁ፣ በትዕዛዙም በተጨቃጨቃችሁና ባመፃችሁም ጊዜ (ግን እርዳታውን ከለከላችሁ):: ከናንተ ውስጥ ቅርቢቱን ዓለም የሚሻ አለ:: ከናንተም ውስጥ የመጨርሻይቱን ዓለም የሚሻ አለ:: ከዚያም ሊሞክራችሁ ከእነርሱ አዞራችሁ:: በእርግጥም ለእናንተ ይቅርታ አደረገላችሁ:: አላህ ሁልጊዜም በአማኞች ላይ የችሮታ ባለቤት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 153, '153. (የመልዕክተኛችን ሙሐመድ ባልደረቦች ሆይ!) መልዕክተኛው ከኋላችሁ ሁኖ እየጠራችሁ የማትዞሩ ሆናችሁ በርቀት በምትሸሹ ጊዜ የሆነውን አስታውሱ:: ባመለጣችሁ እድልና በደረሰባችሁም ነገር አለማዘንን ሊያስተምራችሁ በሀሳብ ላይ ሀሳብን አደረሰባችሁ:: አላህ በምትሰሩት ነገር ሁሉ ውሰጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 154, '154. ከዚያም ከጭንቅ በኋላ ጸጥታን ከናንተ ከፊሎችን የሚሸፍንን እንቅልፍ በእናንተ ላይ አወረደ:: ከፊሎችንም ነፍሶቻቸው በእርግጥ አሳሰቧቸው:: እውነት ያልሆነውን የመሀይምነትን መጠራጠር በአላህ ላይ ይጠራጠራሉ:: «በነገሩ ላይ ምንም የመወሰን መብት አለን? (የለንም።») ይላሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «የመወሰን መብት ሁሉ የአላህ ብቻ ነው።» በላቸው:: ላንተ ግልጽ የማያደርጉትን በልቦቻቸው ውስጥ ይደብቃሉ:: «የመወሰን መብት ቢኖረን ኖሮ በዚህ ቦታ ላይ ባልተገደልን ነበር» ይላሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «በቤታችሁ ውስጥ በሆናችሁም ኖሮ እነዚያ በእነርሱ ላይ መገደል የተጸፈባቸው ወደየመውደቂያቸው በወጡ ነበር።» በላቸው:: አላህ ፍርዱን ሊፈጽምና በደረቶቻችሁም ውስጥ ያለውን ሊፈትን በልቦቻችሁም ውስጥ ያለውን ነገር ሊገልጽ ይህንን ሰራ:: አላህ በደረቶች ውስጥ ያለውን ሁሉ ነገር ሳይቀር አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 155, '155.(የመልዕክተኛችን ባልደረቦች ሆይ!) እነዚያ ሁለቱ ቡድኖች በተገናኙ ቀን ከናንተ የሸሹትን ሰዎች በዚያ በሰሩት ከፊል ምክንያት ያሳሳታቸው ሰይጣን ነው:: አላህ ከእነርሱ በእርግጥ ይቅር ብሏል:: አላህ መሀሪና ለቅጣት የማይቸኩል ታጋሽ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 156, '156. (እናንተ ያመናችሁ ሆይ!) እነደነዚያ በአላህ እንደካዱትና ስለ ወንድሞቻቸው በምድር ላይ በተጓዙና ወይም ዘማቾች በሆኑ ጊዜ እኛ ዘንድ በነበሩ ኖሮ ባልሞቱ ባልተገደሉም ነበር እንደሚሉት ሰዎች አትሁኑ:: አላህ በልቦቻቸው ውስጥ ጸጸት ያደርግባቸው ዘንድ ይህንን አሉ:: አላህ የፈለገውን ሕያው ያደርጋል:: የፈለገውን ይገድላልም:: አላህ የምትሰሩትን ነገር ሁሉ ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 157, '157. (እናንተ ያመናችሁ ሆይ!) በአላህ መንገድ ላይ ስትዋጉ ብትገደሉ ወይም ብትሞቱ ከአላህ የሆነው ምህረትና እዝነት እነርሱ ከሚሰበስቡት ሀብት ሁሉ የእናንተ ምንዳ በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 158, '158. በጂሃድ ብትሞቱ ወይም ብትገደሉ ወደ አላህ ብቻ ትሰበሰባላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 159, '159. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ ችሮታ ለዘብክላቸው:: አመለ መጥፎና ልበ ደረቅ በሆንክ ኖሮ ከአጠገብህ በተበተኑ ነበር:: ከእነርሱም ጥፋት ይቅር በል:: ለእነርሱም ከአላህ ምህረትን ለምንላቸው:: በሁሉም ነገር ላይ አማክራቸው:: ከዚያ ቁርጥ ሀሳብ ባደረገክ ጊዜ በአላህ ላይ ብቻ ተመካ:: አላህ በእርሱ ላይ ብቻ ተመኪዎችን ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 160, '160. (ሙስሊሞች ሆይ!) አላህ ከረዳችሁ እናንተን የሚያሸንፍ የለም:: እርሱ ካዋረዳቸሁ ደግሞ ከእርሱ ማዋረድ በኋላ የሚረዳችሁ ያ ማን ነው? አማኞች በአላህ ላይ ብቻ ይመኩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 161, '161. የምርኮን ገንዘብ መደበቅ ከነብይ የሚሆን አይደለም። የምርኮን ገንዘብ የሚደብቅም በትንሳኤ ቀን የደበቀውን ነገር ተሸክሞ ይመጣል:: ከዚያ ነፍስ ሁሉ የስራዋን ዋጋ ትመነዳለች:: እነርሱም አይበደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 162, '162. የአላህን ውዴታ የተከተለ ሁሉ የአላህን ቁጣ እንዳተረፈና መኖሪያውም ገሀነም እንደሆነው ነውን? ገሀነም ማረፊያነቱ እጅግ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 163, '163. ሁሉም በአላህ ዘንድ ባለ ልዩ ልዩ ደረጃዎች ናቸው:: አላህ የሚሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 164, '164. አላህ በአማኞች ላይ ከመካከላቸው የሆነን፤ በእነርሱም ላይ አናቅጽን የሚያነብ፤ ከርክሰት የሚያጠራቸው፤ መጽሐፍንና ጥበብንም የሚያስተምራቸውን መልዕክተኛ በላከላቸው ጊዜ በእርግጥ ለገሰላቸው:: እነርሱም ከዚያ በፊት ግልጽ ስህተት ውስጥ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 165, '165. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ ያደረሳችሁትን ጥቃት ግማሽ በአገኛችሁ (በደረሰባችሁ) ጊዜ ይህ ከየት ነው የመጣብን አላችሁን? እርሱ ከነፍሶቻችሁ ዘንድ ነው:: አላህም በነገሩ ሁሉ ላይ ቻይ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 166, '166. (የመልዕክተኛችን ባልደረቦች ሆይ!) ያ ሁለት ቡድኖች በተጋጠሙ ቀን የደረሰባችሁ በአላህ ፈቃድ ብቻ ነው:: የአማኞችን አቋም ሊፈትንና ማንነታቸውን ሊገልጽ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 167, '167. እነዚያንም የነፈቁትንና «ኑ በአላህ መንገድ ተጋደሉ ወይም ተከላከሉ።» የተባሉትን ሊገልጽ ነው ይህን ያደረገው። አስመሳዮቹም «ውጊያን ብናውቅ ኖሮ በተከተልናችሁ ነበር።» አሉ:: እነርሱም ያን ጊዜ ከእምነት ይልቅ ወደ ክህደት የቀረቡ ናቸው:: በልቦቻቸው የሌለውን በአፎቻቸው ይናገራሉ። አላህም የሚደብቁትን ሁሉ አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 168, '168. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚህ ከትግል ወደ ኋላ የቀሩ ሲሆኑ ለወንድሞቻቸው «እኛን በታዘዙን ኖሮ ባልተገደሉ ነበር።» ያሉ ናቸው:: «እውነተኞችም ከሆናችሁ እስቲ ከነፍሶቻችሁ ላይ ሞትን ገፍትሩ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 169, '169. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያንም በአላህ መንገድ የተገደሉትን ሰማዕታት ሙታን አድርገህ አትገምታቸው:: በእርግጥ እነርሱ ጌታቸው ዘንድ ሕያው ናቸውና:: ከጌታቸው ዘንድም ሲሳይ ይለገሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 170, '170. አላህ ከችሮታው በሰጣቸው ነገር ተደሳቾች (ሲሆኑ ይመገባሉ):: በእነዚያም ከኋላቸው ገና ባልተከተሏቸውም (ባልሞቱትም እንደነርሱው ከተሰው) በእነርሱ ላይ ስጋትም ትካዜም የሌለባቸው ለመሆናቸው ይደሰታሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 171, '171. በአላህ ጸጋ፤ ችሮታና የአማኞችን ምንዳ የማያጠፋ በመሆኑም ይደሰታሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 172, '172. እነዚያን የመቁሰል አደጋ ከደረሰባቸው በኋላ ለአላህና ለመልዕክተኛው የታዘዙት ከእነርሱ መካከል በጎ ተግባርን ለሰሩና አላህንም ለፈሩት ሁሉ ታላቅ ምንዳ አለላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 173, '173. እነዚያም ሰዎች ለእነርሱ «ጠላቶች ለእናንተ ጦርን እንደገና አከማችተዋልና ፍሯቸው።» ያሏቸውና ይህም በእምነት ላይ እምነትን የጨመረላቸው ቃላቸዉም «በቂያችን አላህ ነው፤ እርሱም ምን ያምር መጠጊያ ነው!» ያሉ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 174, '174. ከዚያም የአላህን ጸጋና ችሮታ ይዘው ምንም ክፉ ነገር ሳይነካቸው በሰላም ተመለሱ:: የአላህን ውዴታም ተከተሉ:: አላህም የታላቅ ችሮታ ባለቤት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 175, '175. ይህ የሚያስፈራራችሁ ሰይጣን ብቻ ነው። ወዳጆቹን ያስፈራራችኋል። (አማኞች ሆይ!) የሰይጣንን ወዳጆችን አትፍሯቸው:: ትክክለኛ አማኞች ከሆናችሁም እኔን ብቻ ፍሩኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 176, '176. (መልዕክተኛችን ሙሐመድ ሆይ!) የእነዚያ ወደ ክህደት የሚቻኮሉ ሰዎች አድራጎት (ተግባር) አያሳዝንህ:: እነርሱ ፈጽሞ አላህን በምንም አይጎዱትምና:: አላህ በመጨረሻይቱ ዓለም ለእነርሱ እድልን ላያደርግ ይሻልና:: ለእነርሱም ታላቅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 177, '177. እነዚያ ክህደትን በእምነት የለወጡ ክፍሎች ሁሉ አላህን በምንም ነገር ፈጽሞ አይጎዱትም:: ለእነርሱም አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 178, '178. እነዚያ በአላህ የካዱ ሰዎች ሁሉ እነርሱን ማዘግየታችንን ለነፍሶቻችን ደግ ነገር ነው ብለው አያስቡ:: እነርሱን የምናዘገያቸው ኃጢአትን እንዲጨምሩ ብቻ ነውና:: ለእነርሱም አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 179, '179. (እናንተ ያመናችሁ ሆይ!) አላህ መጥፎውን ከመልካሙ እስከሚለይ ድረስ አማኞችን እናንተ ባላችሁበት ሁኔታ ላይ የሚተዋቸው አይደለም:: አላህም ሩቁን ነገር የሚያሳውቃችሁ አይደለም:: ግን አላህ ከመልዕክተኞቹ የሚሻውን ይመርጣል:: እናም በአላህና በመልዕክተኞቹም እመኑ:: ብታምኑና ብትጠነቀቁ ለእናንተ ታላቅ ምንዳ አለላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 180, '180. እነዚያ አላህ ከችሮታው ከሰጣቸው ገንዘብ የሚነፍጉ ሰዎች ንፉግነት ደግ ተግባር አይምሰላቸው:: ይልቁንም እርሱ ለእነርሱ መጥፎ ባህሪ ነው:: ያንን በእርሱ የነፈጉበት ገንዘብ በትንሳኤ ቀን (እባብ ሆኖ) በአንገታቸው ይጠለቃሉ:: የሰማያትና የምድር ውርስ ለአላህ ብቻ ነው:: አላህ በምትሰሩት ነገር ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 181, '181. አላህ የእነዚያን «አላህ ድሃ ነው እኛ ግን ከበርቴዎች ነን።» ያሉትን ሰዎች ቃል በእርግጥ ሰማ:: ያንን ያሉትንና ነብያትን ያለ ህግ መግደላቸውንም በእርግጥ እንጽፋለን:: «የማቃጠልንም ስቃይ ቅመሱ።» እንላቸዋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 182, '182. ያ ስቃይ እጃችሁ ባሳለፉት ስራና አላህም ለባሮቹ በዳይ ባለመሆኑ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 183, '183. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ይህን ቃል የተናገሩት: «ለማንኛዉም መልዕክተኛ እሳት የምትበላው ቁርባን እስከሚያመጣልን ድረስ በሱ እንዳናምን አላህ ወደ እኛ አዝዟል።» ያሉ ናቸው:: «ብዙ መልዕክተኞች ከእኔ በፊት በግልጽ ተዓምራትና በዚያ ባላችሁት ቁርባን በእርግጥ መጥተውላችኋል:: እውነተኞች ከሆናችሁ ታዲያ ለምን ገደላቸኃቸው?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 184, '184. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢያስተባብሉህም ካንተ በፊትም በግልጽ ተዐምራት፣ በጽሁፎች፣ በብሩህ መጽሐፍም የመጡ መልዕክተኞችም በእርግጥ (በእነርሱ መሰሎች) ተስተባብለዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 185, '185. ነፍስ ሁሉ ሞትን በእርግጥ ቀማሽ ናት:: ምንዳዎቻችሁንም የምትሞሉት በትንሳኤ ቀን ብቻ ነው:: ከእሳት እንዲርቅ ተደርጎ ገነት እንዲገባ የተደረገም በእርግጥ ምኞቱን አገኘ:: የቅርቢቱ ሕይወት ማታለያ እንጂ ሌላ አይደለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 186, '186. (እናንተ ያመናችሁ ሆይ!) በገንዘቦቻችሁና በነፍሶቻችሁ ትፈተናላችሁ:: ከእነዚያ ከናንተ በፊት መጽሐፍን ከተሰጡትም ከእነዚያ በአላህ ካጋሩትም ቡድኖች ብዙ መጥፎ ነገሮችን ትሰማላችሁ:: ብትታገሱና ብትጠነቀቁ (በጣም ጥሩ ነው።) ይህ ተግባር ከታላላቅ ነገሮች አንዱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 187, '187. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ የእነዚያ መጽሐፍን የተሰጡትን ለሰዎች በእርግጥ «ልታብራሩት እንጂ ላትደብቁት» በማለት የያዘባቸውን ቃል ኪዳን አስታውስ:: እናም በጀርባዎቻቸው በኋላ ወረወሩት:: በእርሱም ጥቂትን ዋጋ ገዙበት:: የሚገዙትም ነገር ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 188, '188. እነዚያን በሰሩት ነገር የሚደሰቱና ባልሰሩትም መመስገንን የሚወዱ ሰዎችን ከቅጣት በመዳን ላይ ናቸው ብለህ አታስባቸው:: ለእነርሱ አሳማሚ ቅጣት አለባቸውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 189, '189. የሰማያትና የምድር ንግስና ለአላህ ብቻ ነው:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 190, '190. በሰማያትና በምድር መፈጠር፤ በሌሊትና በቀንም መተካካት ለባለ አእምሮዎች ሁሉ ታላላቅ ምልክቶች አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 191, '191. እነርሱም እነዚያ ቆመው ተቀምጠዉም በጎኖቻቸው ተጋድመዉም አላህን የሚያወሱ በሰማያትና በምድር አፈጣጠርም የሚያስተነትኑና (እንዲህም) የሚሉ ናቸው: «ጌታችን ሆይ! ይህን በከንቱ አልፈጠርከዉም ጥራት ይገባህ:: ከእሳትም ቅጣት ጠብቀን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 192, '192. «ጌታችን ሆይ! አንተ እሳት የምታስገባው ሰው ሁሉ በእርግጥ አዋረድከው:: ለበደለኞች ምንም ረዳቶች የሏቸዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 193, '193. «ጌታችን ሆይ! እኛ በጌታችሁ እመኑ በማለት ወደ እምነት የሚጠራን ጠሪ ሰማንና ወዲያዉኑ አመንም::ጌታችን ሆይ! ኃጢአቶቻችንንም ማርልን ክፉ ስራዎቻችንንም አብስልን:: ከንጹሆች ሰዎች ጋርም ግደለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 194, '194. «ጌታችን ሆይ! በመልዕክተኞቹ አማካኝነት የሰጠኸንን፤ የገባህልንን የተስፋ ቃል ስጠን:: በትንሳኤ ቀንም አታዋርደን:: (አታሳፍረን::) አንተ ቀጠሮን አታፈርስምና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 195, '195. እናም ጌታቸው «እኔ ከናንተ ውስጥ የወንድንም ሆነ የሴትን መልካም ስራ ወሮታ አላጠፋም:: ከፊላችሁ የከፊሉ አካል ነው።» በማለት ልመናቸውን ተቀበላቸው:: እነዚያ ለዲን ሲሉ የተሰደዱ፣ ከአገሮቻቸዉም በግፍ የተባረሩ፣ በመንገዴም (ሁከት የደረሰባቸው)፣ የተጠቁ፣ የተጋደሉ እና የተገደሉም ክፉ ስራዎቻቸውን አብስላቸዋለሁ:: በስሮቻቸዉም ወንዞች የሚፈሰባቸውን ገነቶች አስገባቸዋለሁ:: እነርሱም ከአላህ ዘንድ የሆነን ከፍተኛ ምንዳ ይመነዳሉ:: አላህ እርሱ ዘንድ መልካም ምንዳ አለና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 196, '196. (መልዕክተኛችን ሙሐመድ ሆይ!) የእነዚያ በአላህ የካዱ ሰዎች በየአገሮች መንፈላሰስ አያታልህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 197, '197. አነስተኛ ጥቅም ነው። ከዚያ መኖሪያቸው ገሀነም ናት:: ገሀነም ደግሞ ማረፊያነቷ ምን ትከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 198, '198. እነዚያ ጌታቸውን የፈሩት ግን ከስሮቻቸው ወንዞች የሚፈሱባቸው ገነቶች በውስጧ ዘወታሪዎች ሲሆኑ አላህ ዘንድ የተሰጡ መስተንግዶዎች አሏቸው:: አላህ ዘንድ ያለውም ምንዳ ለበጎ ሰሪዎች ሁሉ በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 199, '199. ከመጽሐፉ ባለቤቶች መካከል አላህን ፈሪዎችና በአላህ አናቅጽም ጥቂትን ዋጋ የማይለውጡ ሲሆኑ በአላህና በዚያ ወደ እናንተ በተወረደው ቁርኣን በዚያም ወደ እነርሱ በተወረዱት ልዩ ልዩ መጽሐፍት የሚያምኑ ሰዎች አሉ:: እነዚያ ለእነርሱ በጌታቸው ዘንድ ተገቢው ምንዳቸው አለላቸው አላህ ምርመራው ፈጣን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (3, 200, '200. እናንተ ያመናችሁ ሆይ! ከእሳት ቅጣት ትድኑ ዘንድ ታገሱ፣ ተበራቱም፣ በጦር ኬላ ላይ ሆናችሁም ሶላትን ተጠባበቁ:: አላህንም በትክክል ፍሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 1, '1. እናንተ ሰዎች ሆይ! ያንን ከአንዲት ነፍስ (ከአደም) የፈጠራችሁን፤ ከእርሷም መቀናጆዋን (ሀዋን) የፈጠረውንና ከሁለቱም ብዙ ወንዶችንና ብዙ ሴቶችን የበተነውን ጌታችሁን (አላህን) ፍሩ:: ያንንም በእርሱ የምትጠያየቁበትን አላህን (ከሚያስቆጡ) ተግባራትና ዝምድናዎችን (ከመቁረጥ) ተጠንቀቁ:: አላህ በእናንተ ላይ ተጠባባቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 2, '(እናንተ ኑዛዜ ተቀባዮች ሆይ! ) ለየቲሞች ገንዘቦቻቸውን ስጡ:: (ከመሀከሉም) መጥፎውንም በመልካሙ አትለውጡ:: ገንዘቦቻቸውን ወደ ገንዘቦቻችሁ (በመቀላቀል) አትብሉ:: እርሱ ትልቅ ኃጢአት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 3, '3. (እናንተ ሙስሊም ወንዶች ሆይ) በናንተ ስር ያሉት ሴት የቲሞችን በማግባታችሁ አለማስተካከላችሁን ብትፈሩ ከሴቶች መካከል ለእናንተ የመረጣችሁትን (ደስ ያሏችሁን) ሁለት ሁለት ሶስት ሶስትና አራት አራት አግቡ:: በሚስቶች መካከል አለማስተካከላችሁን ብትፈሩ ግን አንዲትን ሴት ብቻ ወይም ንብረታችሁ የሆኑት ሴት ባሪያዎችን ብቻ (በሚስትነት) ያዙ:: ይህም (ሴትን ልጅ) እንዳትበድሉ በጣም የቀረበ ተግባር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 4, '4. ለሴቶች መህሮቻቸውን ደስተኞች ሆናችሁ ስጧቸው። ለእናንተ ከእርሱ የተወሰነን ነገር ራሳቸው ቢለግሱላችሁ ግን በእርካታና በምቾት ሆናችሁ ብሉት (ተጠቀሙበት)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 5, '5. (ኃላፊዎች ሆይ!) ያን አላህ ለእናንተ መቋቋሚያ (መጠቃቀሚያ) ያደረገላችሁን ገንዘባችሁን (የያዛችሁላቸውን) ለቂሎች (ለአዕምሮ ደካሞች) አትስጧቸው:: ከእርሷም መግቧቸው:: ከእርሷ አልብሷቸዉም:: ለእነርሱም መልካምን ንግግር ተናገሯቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 6, '6. (ሙስሊሞች ሆይ!) የቲሞችን ለጋብቻ እስከደረሱ ድረስ ፈትኗቸው:: ከእነርሱም ብልህነትን ብታውቁ ገንዘቦቻቸውን ስጧቸው:: በማባከንና ማደጋቸውን በመሽቀዳደም ገንዘቦቻቸውን አትብሉባቸው:: (ከአሳዳጊዎቹ መካከል) ሀብታም የሆነ ሰው ከገንዘቦቻቸው (ቅንጣት ያህል እንኳን ከመቅረብ) ይከልከል:: ደሃ የሆነ ሰዉም ቢሆን ለድካሙ ብቻ በአግባቡ ይብላ:: ገንዘቦቻቸውን ወደ እነርሱ በሰጣችሁም ጊዜ በእነርሱ ላይ አስመስክሩ:: በተጠባባቂነትም አላህ በቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 7, '7. ለወንዶች ወላጆችና የቅርብ ዘመዶች ሲሞቱ ከተውት (ጥሪት ገንዘብ የውርስ) ድርሻ አላቸው:: ለሴቶችም ወላጆችና የቅርብ ዘመዶች ከተውት ከእርሱ ይነስም ይብዛም (የውርስ) ድርሻ አላቸው:: ለሁሉም የተወሰነ ድርሻ ተደንግጓል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 8, '8. የውርስ ክፍፍልን (ወራሽ ያልሆኑ) የዝምድና ባለቤቶች፤ የቲሞችና ሚስኪኖች በተገኙበት ጊዜ ከእርሱ ለግሱላቸው:: መልካምንም ንግግር ተናገሯቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 9, '9. እነዚያ ከኋላቸው ደካማ ዝርያዎችን ቢተው ኖሮ በእነርሱ ላይ ምን ይደርስባቸው ይሆን ብለው የሚሰጉ ሰዎች ሁሉ (በየቲሞችም ላይ) ይህንኑ ይፍሩ:: አላህንም ይፍሩ:: ትክክለኛንም ቃል ይናገሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 10, '10. እነዚያ የየቲሞችን ገንዘቦች በግፍ የሚበሉ ሁሉ በሆዶቻቸው ውስጥ የሚበሉት እሳትን ብቻ ነው:: የገሀንም እሳትንም በእርግጥ ይገባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 11, '11. (ሰዎች ሆይ) አላህ በልጆቻችሁ ውርስ (በሚከተለው መልኩ) ያዛችኋል:: ለወንዱ የሁለት ሴቶች ድርሻ ያህል አለው:: (ሁለት ወይም) ከሁለት በላይ የሆኑ ሴቶች ልጆች ብቻ ወራሽ ቢሆኑ ለእነርሱ (ሟቹ) ከተወው (ሀብት) ከሶስት ሁለት እጁ ያገኛሉ (አላቸው):: አንዲት ሴት ወራሽ ብትሆን ደግሞ ለእርሷ የሀብቱ ግማሽ አላት:: ለሟቹ ልጅ ካለው ለአባቱና ለእናቱ ከሁለቱ ለእያንዳንዱ ከስድስት አንድ አላቸው:: ለእርሱ ልጅ ባይኖረውና ወላጆቹ ብቻ ቢወርሱት ለእናቱ ሲሶው አላት:: ለእርሱም ወንድሞችና እህቶች ቢኖሩት ለእናቱ ከስድስት አንድ አላት:: (ይህም ውርስ) የሚከፋፈለው ከተናዘዘው ኑዛዜ ወይም ከእዳው ክፍያ በኋላ ነው:: አባቶቻችሁና ልጆቻችሁ ለእናንተ በመጥቀም ማንኛቸው ይበልጥ ቅርብ እንደሆኑ አታውቁም:: ይህም ከአላህ የተደነገገ ነው:: አላህ ሁሉን አዋቂና ጥበበኛ ነዉና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 12, '12. ለእናንተም ሚስቶቻችሁ ከተውት ንብረት ለእነርሱ ልጅ ካልኖራቸው ግማሹ አላችሁ:: ለእነርሱም ልጅ ቢኖራቸው ከተውት ሀብት ከአራት አንድ አላችሁ :: (ይህም) በእርሷ ከሚናዘዙባት ኑዛዜ ወይም ከእዳ ክፍያ በኋላ ነው:: ለእናንተም ልጅ ከሌላችሁ ከተዋችሁት ንብረት ለእነርሱ (ለሚስቶቻችሁ) አንድ አራተኛ አላቸው። ለእናንተም ልጅ ባይኖራችሁ ከተዋችሁት ንብረት ለእነርሱ (ለሚስቶቻችሁ) ከስምንት አንድ አላቸው:: (ይህም) ከምትናዘዙበት ኑዛዜ ወይም ከእዳ ክፍያ በኋላ ነው:: ወላጆችም ልጅም የሌለውና የጎን ወራሾች የሚወርሱት ወንድ ወይም ሴት ቢገኝ ለእርሱም (ለሟቹ) ከእናቱ በኩል ብቻ የሆኑ ወንድም ወይም እህት ቢኖሩት ከሁለቱ ለእያንደንዳቸው ከስድስት አንድ አላቸው:: ከአንድ የበዙ ቢሆኑ ደግሞ በሲሶው ላይ ተጋሪዎች ናቸው:: ይህም ወራሾቹን የማይጎዳ ሆኖ ከእርሷ ከሚናዘዙባት ኑዛዜ ወይም ከእዳ በኋላ ነው:: ከአላህም የሆነን ኑዛዜ ያዛችኋል:: አላህ ሁሉን አዋቂና ቻይ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 13, '13. እነዚህ የአላህ ውሳኔዎች ናቸው:: አላህንና መልዕክተኛውን የሚታዘዙ ሰዎች ሁሉ ከስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲሆኑ ያስገባቸዋል። ይህም ትልቅ እድል ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 14, '14. በአላህና በመልዕክተኛው ላይ የሚያምጽ ወሰኖችንም የሚተላለፍ ሁሉ በውስጧ ዘውታሪ ሲሆን ወደ ገሀነም እሳት ያስገባዋል:: ለእርሱም አዋራጅ ቅጣት አለበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 15, '15. እነዚያ ከሴቶቻችሁ መካከል ዝሙትን የሚሰሩ በእነርሱ ላይ ከናንተ የሆነን አራት ታማኝ ወንዶችን አስመስክሩባቸው:: ከመሰከሩባቸዉም ሞት እስከሚደርስባቸው ወይም አላህ ለእነርሱ ሌላ መንገድን እስከሚያደርግ ድረስ በቤቶች ውስጥ ያዟቸው(እሰሯቸው::)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 16, '16. እነዚያ ከእናንተ ውስጥ ዝሙትን የሚሰሩትን አሰቃዩዋቸው (በሚገባ ቅጧቸው):: ቢጸጸቱና ስራቸውን ቢያሳምሩ ግን እነርሱን ተዋቸው (አታሰቃዩዋቸው።) አላህ ጸጸትን ተቀባይና አዛኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 17, '17. ጸጸትን መቀበል ከአላህ በኩል ለእነዚያ ኃጢአትን በስህተት ለሚሰሩና ከዚያም ወዲያውኑ ለሚጸጸቱ ነው:: እነዚያንማ አላህ ከእነርሱ ጸጸትን ይቀበላል:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና፣', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 18, '18. ጸጸትን መቀበል ለእነዚያ ኃጢአቶችን ለሚሰሩና ልክ ሞት በመጣባቸው ጊዜ «አሁን ተጸጸትኩ።» ለሚሉና ለእነዚያም ከሓዲያን ሆነው ለሚሞቱ አይደለም:: ለእነርሱማ አሳማሚን ቅጣት አዘጋጅተናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 19, '19. እናንተ ያመናችሁ ሆይ! ሴቶችን ያስገደዳችሁ ሆናችሁ ልትወርሱና ግልጽ የሆነ መጥፎ ስራ ካልሰሩ በስተቀር ከሰጣችኋቸው ከፊሉን ልትወስዱባቸውና ልታጉላሏዋቸው አይፈቀድላችሁም:: በመልካም ተኗኗሯቸው:: ብትጠሏቸዉም እንኳን ታገሱ:: አንድ ነገር ብትጠሉትም አላህ በእርሱ ዉስጥ ብዙ ደግ ነገሮችን ሊያደርግላችሁ ይችላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 20, '20. (ባሎች ሆይ!) በሚስት ቦታ ሌላ ሚስትን ለመለወጥ ብትፈልጉ (ለምትፈታው ሴት ቀደም ሲል) ብዙን ገንዘብ የሰጣችኋት እንደሆነ ከእርሷ ምንንም አትውሰዱባት:: በመበደልና ግልጽ በሆነ ኃጢአት ትወስዱታላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 21, '21. ከፊላችሁ ወደ ከፊሉ የደረሰ ሲሆንና ከናንተ ላይም (ሴቶች) የጠበቀ ቃል ኪዳንን የያዙባችሁ ሲሆኑ እንዴት ትወስዱታላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 22, '22. (ወንዶች ሆይ!) ከሴቶች መካከል አባቶቻችሁ ያገቧቸውን አታግቡ። ያለፈው ሲቀር። እርሱ መጥፎና የተጠላ ስራ ነውና። መንገድነቱም ከፋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 23, '23. (ወንዶች ሆይ!) እናቶቻችሁ፤ ሴት ልጆቻችሁ፤ እህቶቻችሁ፤ አክስቶቻችሁ (የአባቶቻችሁ እህቶች)፣ አክስቶቻችሁ (የእናቶቻችሁ እህቶች)፤ የወንድም ሴት ልጆች፤ የእህት ሴት ልጆች፤ እነዚያም ያጠቧችሁ የጡት እናቶቻችሁ፤ የጡት እህቶቻችሁ፤ የሚስቶቻችሁ እናቶች፤ እነዚያም ከጉያዎቻችሁ ያሉት የእነዚያ ግብረ ስጋ ግንኙነት የፈጸማችሁባቸው ሚስቶቻችሁ ሴት ልጆች ልታገቧቸው በእናንተ ላይ እርም ተደረጉባችሁ:: ግብረ ስጋ ግንኙነት ያልፈጸማችሁባቸው የሚስቶቻችሁ ሴት ልጆቻቸውን ብታገቡ ግን በእናንተ ላይ ኃጢአት የለባችሁም:: የእነዚያ ከጀርባዎቻችሁ የሆኑት ወንዶች ልጆቻችሁ ሚስቶችም ሁለት እህትማማቾችን በአንድ መሰብሰብም እንደዚሁ እርም ነው:: ከዚህ በፊት ያለፈው ሲቀር:: እርሱንስ ተምራችኋል:: አላህ መሀሪና አዛኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 24, '24. ባል ያገቡ ሴቶችም በጦርነት እጆቻችሁ በምርኮ የያዟቸው ሲቀሩ (በእናንተ ላይ እርም ናቸው):: ይህን ህግ አላህ በእናንተ ላይ ደነገገ:: ከነዚህ ከተከለከሉት ሌላ ጥብቆች ሆናችሁና ዝሙተኞች ሳትሆኑ በገንዘባችሁ ጋብቻን ልትፈለጉ ለእናንተ ተፈቀደ:: እናም ከእነርሱም መገናኘት የተጠቀማችሁባቸውን ሴቶች መህሮቻቸውን ልትሰጧቸው ግዴታ ነው:: ከመወሰን በኋላ በተዋደዳችሁበት ነገር በእናንተ ላይ ኃጢአት የለም:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 25, '25. (ወንዶች ሆይ!) ከናንተ መካከል ጥብቆች ምዕመናትን ለማግባት ሀብትን ያልቻለ ሰው እጆቻችሁ ንብረት ካደረጓቸው ከምዕመናት መካከል ወጣቶቻችሁን አገልጋዬች የመረጠውን ያግባ:: አላህ የውስጥ እምነታችሁን ምንነት አዋቂ ነውና:: ከፊላችሁ ከከፊሉ የተራባ ነው:: ባሮችንም ቢሆን እንደዚሁ በአሳዳሪዎቻቸው ፈቃድ ብቻ አግቧቸው:: መህሮቻቸውንም በመልካም መንገድ ስጧቸው:: ጥብቆች ሆነው ዝሙተኛ ያልሆኑ የስርቆሽ ወዳጅንም ያልያዙ እንደሆኑ አግቧቸው:: በማግባት በተጠበቁም ጊዜ መጥፎን ስራ ቢሰሩ በእነርሱ ላይ የተደነገገው ቅጣት በነፃዎቹ ላይ ከተደነገገው ቅጣት ግማሹ ቅጣት አለባቸው:: ያ ከናንተ መካከል ዝሙትን ለፈራ ብቻ ነው:: መታገሳችሁ የተሻለ ነው:: አላህ መሀሪና አዛኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 26, '26. (አማኞች ሆይ!) አላህ የሃይማኖታችሁን ህግጋት ሊያብራራላችሁ፤ ከናንተ በፊትም የነበሩትን ነብያት ፈለጎች ሊመራችሁ፤ በእናንተም ላይ ጸጸትን ሊቀበል ይሻል:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 27, '27. አላህ በእናንተ ላይ ጸጸትን ሊቀበል ይሻል:: እነዚያ ፍላጎታቸውን የሚከተሉ ግን ከእውነት ትልቅን መዘንበል እንድትዘነበሉ ይፈልጋሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 28, '28. አላህ ከናንተ ሊያቃልልላችሁ ይሻል። ሰው ደካማ ሆኖ የተፈጠረ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 29, '29. እናንተ ያመናችሁ ሆይ! ገንዘቦቻችሁን በመካከላችሁ ያለ አግባብ አትብሉ:: በእናንተ መካከል በመስማማት የሆነችውን ንግድ ካልሆነች በስተቀር (እሷን ግን ብሉ) :: ነፍሶቻችሁን በራሳችሁ አትግደሉ። አላህ ለእናንተ አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 30, '30. ወሰን በማለፍ እና በመበደል ይህን የሰራ ሁሉ እሳት እናስገባዋለን:: ይህም በአላህ ላይ ገር ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 31, '31. ትክክለኛ አማኞች ሆይ! ከተከለከላችሁት ወንጀሎች መካክል ታላላቆችን ብትርቁ ትናንሽ ኃጢአቶቻችሁን እናብስላችኋለን:: የተከበረውንም መግቢያ (ገነት) እናስገባችኋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 32, '32. አላህ ከፊላችሁን በከፊሉ ያበለጠበትን ጸጋ አትመኙ:: ለወንዶችም ከሰሩት ስራ እድል አለላቸው:: ለሴቶችም ከሰሩት ስራ እንዲሁ እድል አለላቸው:: አላህን ከችሮታው ለምኑት:: አላህ በሁሉ ነገር አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 33, '33. ለሁላችሁም ወላጆችና የቅርብ ዘመዶች ከተውት ሀብት ወራሾችን አድርገናል:: እነዚያንም (ለመረዳዳትና ለመዋረስ) በመሐላዎቻችሁ የተዋዋላችኋቸውን (ከስድስት አንድ) ድርሻቸውን ስጧቸው:: አላህ በነገሩ ሁሉ አዋቂ (መስካሪ) ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 34, '34. ወንዶች ለሴቶች ቋሚና የበላይ አስተዳዳሪዎች ናቸው:: አላህ ከፊላቸውን በከፊሉ ላይ በማብለጡና ወንዶች ከገንዘቦቻቸው ለሴቶች በመስጠታቸው ምክኒያት ነው:: መልካሞቹ ሴቶች ማለት ለባሎቻቸው ታዛዦች፤ አላህ ባስጠበቀው ነገር ከባሎቻቸው ሩቅ የሆነውን ጠባቂዎች ናቸው:: እነዚያን ማመፃቸውን የምትፈሩትን ሴቶች መጀመሪያ ገስጿቸው:: ከዚያም በመኝታቸው ተለዩዋቸው:: ከዚያም (በአካሎቻቸው ላይ ሳካ ሳታደርሱ) ምቷቸው:: ከታዘዟችሁ ለመጨቆን ስትሉ በእነርሱ ላይ መንገድን አትፈልጉ:: አላህ የሁሉም በላይና ታላቅ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 35, '35. በመካከላቸውም ጭቅጭቅ መኖሩን ብትፈሩ (ብታውቁ) ከቤተሰቡና ከቤተሰቦቿ የተውጣጡ የቤተ ዘመድ ጉባኤ አዋቅሩ:: ሁለቱም እርቅን ቢሹ አላህ በመካከላቸው ያስማማቸዋል:: አላህ ግልጽንም ሆነ ውስጥንም አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 36, '36. አላህን ተገዙ:: በእርሱ ምንንም አታጋሩ። ለወላጆች፣ ለቅርብ ዝምድና ባለቤቶች፣ ለየቲሞች፣ ለምስኪኖች፣ ለቅርብ ጎረቤት፣ ለሩቅ ጎረቤት፣ ለጎን ባልደረባ፣ ለመንገደኛ፣ እጆቻችሁ ንብረት ላደረጓቸው ባሮች መልካምን ስሩ። አላህ ኩራተኞችንና ጉረኞችን አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 37, '37. እነዚያ የሚሰስቱ ንፉጎችና ሰዎችንም በመሰሰት (በንፍግና) የሚያዝዙ አላህ ከችሮታው የሰጣቸውን ጸጋ የሚደብቁ ብርቱን ቅጣት ይቀጣቸዋል። ለከሓዲያንም አዋራጅን ቅጣት አዘጋጅተናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 38, '38. እነዚያ ለሰዎች ይዩልን ሲሉ ገንዘቦቻቸውን የሚሰጡ በአላህ እና በመጨረሻው ቀን የማያምኑ ይቀጣሉ:: ሰይጣንም የእሱ ጓደኛው የሆነለት ሁሉ ጓደኛነቱ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 39, '39. በአላህና በመጨረሻው ቀን ባመኑና አላህ ከሰጣቸዉም ሲሳይ በለገሱ ኖሮ በእነርሱ ላይ ምን ጉዳት ነበረ? አላህ በእነርሱ ሁኔታ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 40, '40. አላህ የብናኝን ክብደት ያህል እንኳን አይበድልም:: መልካም ስራ ብትሆንም ይደራርባታል:: ከእርሱም ዘንድ ታላቅን ምንዳ ይሰጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሕዝቦች ሁሉ መስካሪን ባመጣንና አንተንም በእነዚህ (ባንተ ህዝቦች) ላይ መስካሪ አድርገን በምናመጣህ ጊዜ የከሓዲያን ሁኔታ እንዴት ይሆን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 42, '42. በዚያ ቀን እነዚያ በአላህ የካዱ ሰዎችና መልዕክተኛውን ያልታዘዙት ምድር በእነርሱ ላይ ብትደፋባቸው ይመኛሉ:: ከአላህም ወሬን አይደብቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 43, '43. (እናንተ ያመናችሁ ሆይ!) የምትሉትን ነገር ለይታችሁ አስከምታውቁ ድረስ የሰከራችሁ ሆናችሁ ወደ ሶላት አትቅረቡ:: ጀናባ ስትሆኑም መንገድን አላፊዎች ካልሆናችሁ በስተቀር ሙሉ አካላታችሁን እስከምትታጥቡ ድረስ መስጊድን አትቅረቡ:: በሽተኞች ወይም በጉዞ ላይ ብትሆኑ ወይም ከናንተ አንዱ ከአይነ ምድር ቢጸዳዳ ወይም ከሴቶች ጋር ብትነካኩና ( የግብረስጋ ግንኙነት ብትፈጽሙና) ውሃን ባታገኙ ንጹህ የሆነን የምድር ገጽ (አፈርን) አብሱ:: ከዚያ ፊቶቻችሁንና እጆቻችሁን በእርሱ አብሱ:: አላህ ይቅር ባይና መሀሪ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ ከመጽሐፉ የእውቀት ድርሻን ወደ ተሰጡት ክፍሎች አላየህም? ጥመትን በቅንነት ይገዛሉ:: መንገድንም እንድትሳሳቱ ይፈልጋሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 45, '45. (ትክክለኛ አማኞች ሆይ!) አላህ ጠላቶቻችሁን ከናንተ በበለጠ አዋቂ ነው:: ጠባቂነትም በአላህ በቃ:: ረዳትነትም በአላህ በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 46, '46. ከእነዚያ ከአይሁዳውያን መካከል ንግግሮችን ከስፍራዎቹ የሚያጣምሙ አሉ። «ንግግርክን ሰማንና ትእዛዝክን አመጽን፤ የማትሰማም ስትሆን እስቲ ስማ።» ይላሉ:: በምላሶቻቸዉም ለማጣመምና ሃይማኖትንም ለመዝለፍ በማሰብ "ራዒና" ይላሉ:: እነርሱም «ሰማንና ታዘዝን፤ ስማን ተመልከተንም።» ባሉ ኖሮ ለእነርሱም መልካምና ትክክለኛ በሆነ ነበር:: ግን በክህደታቸው ምክንያት አላህ ረገማቸው:: ከእነርሱም መካከል ጥቂቶች እንጂ አያምኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 47, '47. እናንተ መጽሐፉ የተሰጣችሁ ሰዎች ሆይ! ፊቶችን ሳናዞርና በጀርባዎች ላይ ሳንመልሳቸው ወይም የሠንበትን ባለቤቶች እንደረገምን ሳንረግማችሁ በፊት ከናንተ ጋር ያለውን የሚያረጋግጥ ሆኖ በአወረድነው ቁርኣን እመኑ:: የአላህም ትዕዛዝ ተፈፃሚ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 48, '48. አላህ በእርሱ ማጋራትን ፈጽሞ አይምርም:: ከዚህ በታች (ውጭ) ያለውን ኃጢአት ግን ለሚሻው ሁሉ ይምራል:: በአላህ የሚያጋራ ሁሉ ታላቅን ኃጢአት በእርግጥ ቀጠፈ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 49, '49. ወደ እነዚያ ነፍሶቻቸውን ወደ ሚያጠሩት (ሚያወድሱት) አላየህምን? ይልቁንም አላህ ነው የሚፈልገውን የሚያጠራው። በተምር ፍሬ ስንጥቅ ላይ ያለችን ክር መሳይ ያህልም ቢሆን አይበደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ ላይ ውሸትን እንዴት እንደሚቀጥፉ ተመልከት። ግልጽ ወንጀል በርሱ በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ ከመጽሐፉ ድርሻን ወደ ተሰጡት አላየህምን? በድግምትና በጣዖት ያምናሉ። ለእነዚያ በአላህ ለካዱትም እነርሱ በሃይማኖት ከእነዚያ በሙሐመድ ካመኑት ይበልጥ ቀና እንደሆኑ ይናገራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ አላህ የረገማቸው ናቸው:: አላህ የረገመውን ደግሞ ለርሱ ፈጽሞ ረዳት አታገኝለትም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 53, '53. በእውነቱ ለእነርሱ ከንግስናው ፈንታ አላቸውን? ያን ጊዜማ ለሰዎች በተምር ፍሬ ላይ ያለችውን ነጥብ ያህል እንኳን አይሰጡም ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 54, '54. ይልቁንም ለሰዎች አላህ ከችሮታው በሰጣቸው ነገር ላይ ይመቀኛሉን? ለኢብራሂምም ቤተሰቦች መጽሐፍንና ጥበብን በእርግጥ ሰጠን:: ታላቅንም ንግስናን ሰጠናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 55, '55. ከነሱም (ከአይሁድ) መካከል በነብዩ ሙሐመድ ያመነ አለ:: ከእነርሱም ከዚህ እምነት ያፈገፈገ አለ። አቃጣይነት በገሀነም በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 56, '56. እነዚያን በተዐምራታችን የካዱትን ሁሉ በእርግጥ እሳትን እናስገባቸዋለን:: ስቃይን እንዲቀምሱም ቆዳዎቻቸው በተቃጠሉ ቁጥር ሌሎችን ቆዳዎች እንለውጥላቸዋለን:: አላህ ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 57, '57. እነዚያ በአላህ አንድነት ያመኑና መልካም ስራዎችን የሰሩ ከስራቸው ወንዞች የሚፈሱባቸውን ገነቶች ዘላለም በውስጣቸው ዘወታሪዎች ሲሆኑ በእርግጥ እናስገባቸዋለን:: ለእነርሱ በውስጧ ንጹህ ሚስቶችም አሏቸው:: የምታስጠልልን ጥላም እናስገባቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 58, '58. አላህ አደራዎችን ወደ የባለቤቶቻቸው እንድታደርሱና በሰዎች መካከል በፈረዳችሁ ጊዜም በትክክል እንድትፈርዱ ያዛችኋል:: አላህ በእርሱ የሚገስፃችሁ ነገር ምን ያምር ነው! አላህ ሁሉን ሰሚ እና ሁሉን ተመልካች ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 59, '59. እናንተ ያመናችሁ ሆይ! አላህን ታዘዙ:: መልዕክተኛውን እና ከመካከላችሁም የስልጣን ባለቤቶችን ታዘዙ:: በማንኛዉም ነገር ብትከራከሩም በአላህና በመጨረሻው ቀን የምታምኑ ከሆናችሁ የተከራከራችሁበትን ነገር ወደ አላህና ወደ መልዕክተኛው መልሱት:: ይህ የተሻለ እና መጨረሻዉም ያማረ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 60, '60. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ «ባንተ ላይ በተወረደውና ካንተ በፊትም በተወረደው አምነናል።» ወደ ሚሉት አላየህምን? በእርሱ እንዲክዱ በእርግጥ የታዘዙ ሲሆኑ ወደ ጣኦት መፋረድን ይፈልጋሉ:: ሰይጣንም ከእውነት የራቀን መሳሳት ሊያሳስታቸው ይፈልጋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 61, '61. ለእነርሱም፡- «አላህ ወደ አወረደው ቁርኣንና ወደ መልዕክተኛው ኑ።» በተባሉ ጊዜ አስመሳዮችን ካንተ በሀይል ሲሸሹ ታያቸዋለህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 62, '62. እጆቻቸዉም ባስቀደሙት ጥፋት ምክንያት መከራ በደረሰባቸውና ከዚያ «ደግን ሀሳብና ማስማማትን እንጂ ሌላን አልፈለግንም።» በማለት በአላህ የሚምሉ ሆነው ወደ አንተ በመጡ ጊዜ እንዴት ይሆናል?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 63, '63. እነዚያ አላህ በልቦቻቸው ውስጥ ያለውን ሁሉ የሚያውቅባቸው ናቸው:: ከእነርሱ ራስህን አግልል:: ገስፃቸዉም:: ለእነርሱም በነፍሶቻቸው ውስጥ ጠልቆ የሚገባ ጠንካራ ቃል ተናገራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 64, '64. (መልዕክተኛችን ሙሐመድ ሆይ!) ማንንም መልዕክተኛ በአላህ ፈቃድ ሊታዘዙት እንጂ አልላክንም:: እነርሱም ነፍሶቻቸውን በበደሉ ጊዜ ወደ አንተ መጥተው አላህን ምህረት በለመኑና መልዕክተኛዉም ለእነርሱ ምህረትን በለመነላቸው ኖሮ አላህን ጸጸትን ተቀባይና አዛኝ ሆኖ ባገኙት ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) ጉዳዩ እነርሱ እንዳሉት አይደለም:: በጌታህ እምላለሁ በመካከላቸው በተከራከሩበት ፍርድ የሚያስፈርዱህ ሆነው ከዚያ ከፈረድከው ነገር በነፍሶቻቸው ውስጥ ጭንቀትን እስከማያገኙና ፍጹም መታዘዝንም እስከሚታዘዙ ድረስ አማኝ አይሆኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 66, '66. እኛም በእነርሱ ላይ፡- «ነፍሶቻችሁን ግደሉ» ወይም «ከአገሮቻችሁ ውጡ» ማለትን በፃፍን ኖሮ ከእነርሱ ጥቂቶቹ እንጂ ባልሰሩት (ባልተገበሩት) ነበር። የሚገሰጹበትን ነገር በተገበሩት ኖሮ ለእነርሱ መልካምና በእምነታቸው ላይ ለመርጋትም በጣም የበረታ በሆነ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 67, '67. ያን ጊዜ ደግሞ ከእኛ ዘንድ ታላቅን ምንዳ በሰጠናቸው ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 68, '68. ቀጥተኛውንም መንገድ በእርግጥ በመራናቸው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 69, '69. አላህንና መልዕክተኛውን የሚታዘዝ ሁሉ ከእነዚያ አላህ በእነርሱ ላይ ፀጋውን ከዋለላቸው ከነብያት፤ ከፃድቃን፤ ከሰማዕታትና ከመልካሞቹ ጋር ይሆናሉ። የእነዚያም ጓደኝነት አማረ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 70, '70. ይህ ችሮታ ከአላህ የተለገሰ ነው:: አዋቂነትም በአላህ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 71, '71. እናንተ ያመናችሁ ሆይ! ጥንቃቄያችሁን ያዙ:: ክፍልፍልም ወይም በአንድ ሆናችሁ ለዘመቻ ውጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 72, '72. ከናንተ ውስጥ በእርግጥ ከዘመቻ ወደ ኋላ የሚንጓደድ (የሚጎተት) ሰው አለ:: አደጋም ካገኛችሁ «ከእነርሱ ጋር ተሳታፊ ባለመሆኔ አላህ በእኔ ላይ በእርግጥ ጸጋውን ዋለልኝ።» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 73, '73. ከአላህ የሆነ ችሮታ ካገኛችሁ ደግሞ በእናንተና በእርሱ መካከል ፍቅር አንዳልነበረ ሁኖ «ታላቅ እድል አገኝ ዘንድ ምን ነው ከእነርሱ ጋር በሆንኩ?» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 74, '74. እናም እነዚያ ቅርቧን ህይወት በመጨረሻይቱ ሕይወት የሚለውጡ (የሚገዙ) በአላህ መንገድ ይጋደሉ:: በአላህ መንገድ የሚጋደልና ከዚያ የሚገደል ወይም የሚያሸንፍ ሁሉ ታላቅ ምንዳን በእርግጥ እንሰጠዋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 75, '75. (አማኞች ሆይ!) በአላህ መንገድና ከወንዶች፣ ከሴቶችና ከልጆችም የሆኑትን እነዚያን፡- «ጌታችን ሆይ! ከዚህች ባለቤቶቿ በዳይ ከሆኑባት ከተማ አውጣን፤ ካንተም ዘንድ ለእኛ አሳዳሪን አድርግልን፤ ካንተ ዘንድም ለእኛ ረዳትን አድርግልን።» የሚሉትን ደካሞች ሰዎች ለማዳን የማትዋጉት ለምንድ ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 76, '76. እነዚያ ያመኑት በአላህ መንገድ ይዋጋሉ:: እነዚያ በአላህ የካዱት ደግሞ በጣኦት መንገድ ይዋጋሉ:: እናም (እናንተ ያመናችሁ ሆይ!) የሰይጣን ቡድኖችን ተፋለሙ:: የሰይጣን ተንኮል ደካማ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 77, '77. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ ለእነርሱ፡- «እጆቻችሁን ከመጋደል ሰብስቡ፤ ሶላትን ደንቡን ጠብቃችሁ ስገዱ፤ ግዴታ ምጽዋትን ስጡ።» ወደ ተባሉት አላየህምን? በእነርሱ ላይ መጋደል ግዴታ በሆነባቸው ጊዜ ደግሞ ከእነርሱ መካከል ከፊሎቹ ወዲያውኑ ሰዎችን ልክ አላህን እንደሚፈሩ ወይም የበለጠ ይፈራሉ:: «ጌታችን ሆይ! በእኛ ላይ መጋደልን ለምን ደነገግህ? እስከ ቅርብ ጊዜ ድረስ አታቆየንም ኖሯልን?» ይላሉ:: «የቅርቢቱ ሕይወት ጥቅም አነስተኛ ነው:: የመጨረሻይቱ ዓለም ጥቅም ግን አላህን ለሚፈራ ሁሉ በላጭ ነው። በተምር ፍሬ ውስጥ ያለችን ክር መሰል ያህል እንኳ አትበደሉም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 78, '78. የትም ስፍራ ብትሆኑ ሞት ያገኛችኋል:: በጠነከሩ ህንፃዎች ውስጥም ብትደብቁ እንኳን:: ደግ ነገር ካገኛቸው «ይህ ከአላህ ዘንድ የመጣ ነው።» ይላሉ:: መከራ ካገኛቸው ግን «ይህ ካንተ ዘንድ የመጣ ነው።» ይላሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «ሁሉም (ደጉም ክፉዉም) ከአላህ ዘንድ የመጣ ነው።» በላቸው:: እነዚህ ሰዎች ንግግርን ሊረዱ የማይቀርቡት ለምንድን ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 79, '79. (የሰው ልጅ ሆይ!) ደግ ነገር የሚያገኝህ ከአላህ ችሮታ ነው:: የሚደርስብህ መከራ ግን ከራስህ ጥፋት የተነሳ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ለሰዎች ሁሉ መልዕክተኛ አድርገን ላክንህ:: መስካሪነትም በአላህ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 80, '80. መልዕክተኛውን የሚታዘዝ ሁሉ በእርግጥ አላህን ታዘዘ:: ከትዕዛዝም የሸሸው ጉዳዩ አያሳስብህ:: በእነርሱ ላይ ጠባቂ አድርገን አላክንህምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 81, '81. አጠገብህ ሲሆኑ የአንተ ታዛዥ ነን ይላሉ:: ካንተ ዘንድ በወጡ ጊዜ ከእነርሱ ከፊሎቹ ከዚያ በአጠገብህ ከሚሉት ሌላን በልቦቻቸው ያሳድራሉ:: አላህ በልቦቻቸው የሚያሳድሩትን ነገር ሁሉ ይጽፋል:: ስለዚህ ተዋቸውና በአላህ ላይ ብቻ ተመካ:: መመኪያነት አላህ ብቻ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 82, '82. ቁርኣንን አያስተነትኑምን? ከአላህ ሌላ ዘንድ የመጣ በነበረ ኖሮ በውስጡ ብዙ መለያየትን ባገኙ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 83, '83. ሰላምን ወይም ስጋትን የሚመለከት ወሬ በመጣላቸው ጊዜ እርሱን ያሰራጫሉ (ያጋንናሉ)። ወደ መልዕክተኛውና ከእነርሱ መካከል የጉዳይ ባለቤቶች ወደ ሆኑት አዋቂዎቹ በመለሱት ኖሮ እነዚያ ከእነርሱ መካከል ነገሩን በትክክል የሚረዱት ክፍሎች ባወቁት ነበር:: በእናንተ ላይ የአላህን ችሮታና እዝነቱ ባልነበረ ኖሮ ከጥቂቶቹ በስተቀር ሰይጣንን በተከተላችሁ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 84, '84. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ መንገድ ተዋጋ:: ራስህን እንጂ ሌላን አትገደድም:: አማኞችንም በአላህ መንገድ ላይ በመዋጋት ላይ አደፋፍራቸው:: አላህ የእነዚያን የካዱትን ሰዎች ኃይል ሊከለክል ይከጀላል:: አላህ በሃይል በመያዙ የበረታና ቅጣቱም የጠነከረ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 85, '85. መልካም መታደግን የሚታደግ (ሽምግልናን የሚሸመግል) ሰው ሁሉ ለራሱ ከእርሷ እድል ይኖረዋል:: መጥፎ መታደግንም የሚታደግ ሰው ለእርሱ ከእርሷ ድርሻ ይኖረዋል:: አላህ በነገሩ ሁሉ ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 86, '86.(እናንተ ያመናችሁ ሆይ!) ሰላምታ በቀረበላችሁ ጊዜ ከእርሷ ይበልጥ ባማረ ሰላምታን መልሱ። ወይም እርሷኑ ራሷን መልሷት። አላህ በነገሩ ሁሉ ላይ ተቆጣጣሪ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 87, '87. አላህ ከእርሱ በስተቀር ትክክለኛ አምላከ የለም:: ወደ ትንሳኤ ቀን በእርሱ ጥርጥር የሌለበት ሲሆን በእርግጥ ይሰበስባችኋል:: በንግግርም ከአላህ ይበልጥ እውነተኛ ማን ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 88, '88.(አማኞች ሆይ) አላህ በስራዎቻቸው ምክንያት ወደ ክህደት የመለሳቸው ሲሆኑ በሙናፊቆች ጉዳይ እናንተ ለሁለት ቡድን የተከፈላችሁት ምን ሆናችሁ ነው? አላህ ያጠመመውን ሰው ልታቀኑ ታስባላችሁን? (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ያጠመመውን ሰው ለእርሱ መንገድ ፈጽሞ አታገኝለትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 89, '89. (አማኞች ሆይ) በአላህ እንደ ካዱ ሁሉ እናንተም እንድትክዱና ከእነርሱ ጋር እኩል እንድትሆኑ ተመኙ:: በአላህ መንገድ እስከሚሰደዱ ድረስ ከእነርሱ መካከል ወዳጆችን አትያዙ:: ከእምነት ካፈገፈጉም ማርኳቸው:: ባገኛችኋቸው ስፍራ ሁሉ ግደሏቸው:: ከእነርሱም ወዳጅንና ረዳትን አትያዙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 90, '90. እነዚያ በእናተና በእነርሱ መካከል ቃል ኪዳን ወዳላቸው ህዝቦች የሚጠጉ፤ ወይም እናንተን ለመጋደልም ይሁን ወገኖቻቸውን ለመጋደል ልቦቻቸው የተጨነቁ ሆነው ወደ እናንተ የመጡ ሲቀሩ እነዚያንማ አትጋደሏቸው:: አላህ በፈለገ ኖሮ በእናንተ ላይ ሀይል በሰጣቸውና በተዋጓችሁ ነበር:: ቢተዋችሁ ባይዋጓችሁ ወደ እናንተ የእርቅን ሀሳብ ቢያቀርቡ አላህ ለእናንተ በእነርሱ ላይ የመዋጋት መንገድን አላደረገም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 91, '91. ከናንተም ሆነ ከወገኖቻቸው ለመዳን የሚፈልጉ ሌሎች ቡድኖችም ታገኛላችሁ:: ወደ እውከት እንዲመለሱ በተጠሩ ቁጥር በእርሷ ውስጥ ይዘፈቃሉ:: ባይተዋችሁና እርቅን ካላቀረቡላችሁ እጆቻቸውንም ባይሰበስቡ ባገኛችኋቸው ስፍራ ሁሉ ማርኳቸው:: ግደሏቸዉም:: እነዚያን ለእናንተ በእነርሱ ላይ ግልጽ ማስረጃን አድርገንላችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 92, '92. አማኝ በስህተት ካልሆነ በስተቀር አማኝን መግደል አይገባዉም:: አማኝን በስህተት የገደለም አማኝ ባሪያን ነፃ ማውጣትና ምህረት ካላደረጉለት በስተቀር ለቤተሰቦቹ የምትሰጥ ጉማ መክፈል አለበት:: ተገዳዩ ምዕመን ሆኖ ለእናንተ ጠላት ከሆኑ ህዝቦች ዘንድ ቢሆንም አማኝን ባሪያ ነፃ ማውጣት አለበት:: ተገዳዩ በእናንተ እና በእነርሱ መካከል ቃል ኪዳን ካላቸዉም ህዝቦች ጋር ቢሆን ለቤተሰቦቹ የምትሰጥ ጉማና አማኝን ባሪያ ነፃ ማውጣት አለበት:: ይህንን ያላገኘም በተከታታይ ሁለት ወሮችን መፆም አለበት:: ከአላህ የሆነ ጸጸት (ለመቀበል ደነገገላችሁ::) አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 93, '93. አማኝን አስቦ የሚገድል ቅጣቱ በውስጧ ዘወታሪ ሲሆን ገሀነም ናት:: አላህ በእርሱ ላይ ተቆጣ:: ረገመዉም:: ለእርሱ ከባድ ቅጣትን አዘጋጀቶለታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 94, '94. እናንተ ያመናችሁ ሆይ! በአላህ መንገድ ለመዋጋት በተጓዛችሁ ጊዜ አረጋግጡ:: ሰላምታን ወደ እናንተ ላቀረበ ሰው የቅርቢቱን ሕይወት ጥቅም የምትፈልጉ ሆናችሁ «ትክክለኛ አማኝ አይደለህም።» አትበሉት:: አላህ ዘንድ ብዙ ምርኮዎች አሉና:: እናንተም ከዚህ በፊት ልክ እንደዚሁ ነበራችሁ:: አላህ በእናንተ ላይ ለገሰ:: ስለዚህም አረጋግጡ:: አላህ በምትሰሩት ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 95, '95. ከአማኞች የጉዳት ባለቤት ከሆኑት በስተቀር ተቀማጮቹ እና በአላህ መንገድ በገንዘቦቻቸውም በነፍሶቻቸውም የሚታገሉት አይስተካከሉም:: በገንዘቦቻቸውም በነፍሶቻቸውም የሚታገሉትን አላህ በተቀማጮቹ ላይ በደረጃ አበለጠ:: ለሁሉም አላህ መልካሚቱን (ገነት) ተስፋ ሰጠ (ቃል ኪዳን ገባ):: ታጋዮቹንም በተቀማጮቹ ላይ አላህ በታላቅ ምንዳ አበለጠ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 96, '96. ከእርሱ ዘንድ በሆኑ ደረጃዎች አበለጠ:: ምህረትንም አደረገ:: እዝነትንም አዘነላቸው:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 97, '97. እነዚያ ለእምነት ሲሉ ባለመሰደድ ነፍሶቻቸውን በዳዮች ሆነው መላዕክት የገደሏቸው መላዕክት ለእነርሱ «በምን ነገር ላይ ነበራችሁ?» ይሏቸዋል። «በምድር ውስጥ ደካሞች ነበርን።» ይላሉ:: «የአላህ ምድር ትሰደዱባት ዘንድ ሰፊ አልነበረችምን?» ይሏቸዋል። እነዚያም መኖሪያቸው ገሀነም ናት:: ገሀነምም መመለሻነቷ ከፋች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 98, '98. ከወንዶችና ከሴቶች ከህፃኖችም ሲሆኑ ከሀገራቸው ለመውጣት መላን የማይችሉና መንገድንም የማይመሩ ደካሞች ባለመሰደዳቸው ግን ምንም ቅጣት የለባቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 99, '99. እነዚያ አላህ ከእነርሱ ይቅርታ ሊያደርግ ይሻል:: አላህም ይቅር ባይና መሀሪ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 100, '100. በአላህ መንገድ የሚሰደድ ሁሉ በምድር ውስጥ ብዙ መሰደጃንና ምቾትን ያገኛል:: ወደ አላህና ወደ መልዕክተኛው ስደተኛ ሆኖ ከቤቱ የሚወጣና ከዚያ በመንገድ ላይ ሞት የሚያገኘው ምንዳው በእርግጥ በአላህ ዘንድ ተረጋገጠ:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 101, '101.(አማኞች) በምድር ላይ በተጓዛችሁ ጊዜ እነዚያ የካዱት ሊያውኳችሁ እንደሆነ ብትፈሩ ከሶላቶች መካከል ከፊሎችን (ባለ አራት አራት ረካአ የሆኑትን ቁጥራቸውን ወደ ሁለት ሁለት በመቀነስ) ብታሳጥሩ በእናንተ ላይ ኃጢአት የለም። ከሓዲያን ለእናንተ በእርግጥ ግልጽ ጠላቶች ናቸውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 102, '102.(መልዕክተኛችን ሙሐመድ ሆይ) በጦርነት ላይ በመካከላቸው በሆንክና ሶላትን ለእነርሱ ባሰገድካቸው ጊዜ ከእነርሱ አንዱ ቡድን ካንተ ጋር ይቁም:: መሳሪያዎቻቸውንም ይያዙ:: ሱጁድ ባደረጉ ጊዜ ከበስተኋላችሁ ይሁኑ:: ከዚያም እነዚያ ቡድኖች ወደ ግንባር ይሂዱና ያልሰገዱት ሌሎች ቡድኖች ይምጡ :: ከዚያም ካንተ ጋር ይስገዱ:: ጥንቃቄያቸውንና መሳሪያዎቻቸውንም ይያዙ:: እነዚያ በአላህ የካዱት ከትጥቅና ስንቃችሁ ብትዘናጉና በአንድ ጊዜ ቢወሯችሁ ይመኛሉ:: ዝናብ አውኳችሁ ወይም በሽተኛ ሆናችሁ ትጥቃችሁን ብታስቀምጡ በእናንተ ላይ ኃጢአት የለባችሁም:: ጥንቃቄ አድርጉ:: አላህ ለካሐዲያን ሁሉ አዋራጅን ቅጣት አዘጋጀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 103, '103. ሶላትንም በፈጸማችሁ (በጨረሳችሁ) ጊዜ ቆማችሁ፣ ተቀምጣችሁና በጎኖቻችሁም ተጋድማችሁ አላህን አውሱ:: በተረጋጋችሁ ጊዜ ግን ሶላትን ደንቧን አሟልታችሁ ስገዱ:: ሶላት በአማኞች ላይ በጊዜያት የተወሰነች ግዴታ ናትና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 104, '104.ሰዎቹንም ከመፈለግ አትስነፉ:: ስትቆስሉ የምትታመሙ ብትሆኑም እናንተ እንደምትታመሙ ሁሉ እነርሱም ይታመማሉ:: እናንተ ግን እነርሱ የማይከጅሉትን ከአላህ ትከጅላላችሁ:: አላህም ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 105, '105. (መልዕክተኛችን ሙሐመድ ሆይ!) በሰዎች መካከል አላህ ባሳወቀህ ልትፈርድ ወደ አንተ መጽሐፉን በእውነት አወረድን:: እናም ለከዳተኞች ተከራካሪ አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 106, '106. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህን ምህረት ለምነው:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 107, '107. ለእነዚያ ነፍሶቻቸውን ስለሚያታልሉት ሰዎች አትከራከር:: አላህ ከዳተኛንና ኃጢአተኛን ሰው አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 108, '108. ከሰው ይደበቃሉ:: አላህ በዕውቀቱ ከእነርሱ ጋር ሲሆን ከንግግር የማይወደውን ነገር በልቦቻቸው በሚያሳድሩ ጊዜ ከእርሱ አይደበቁም:: አላህ በሚሰሩት ሁሉ በእውቀቱ ከባቢ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 109, '109. እነሆ እናንተ እነዚያ በቅርቢቱ ሕይወት ውስጥ ከእነርሱ ተከራከራችሁ:: በትንሳኤ ቀን አላህን ስለ እነርሱ የሚከራከርላቸው ማን ነው? ወይስ ለእነርሱ ሀላፊ የሚሆን ማን ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 110, '110. መጥፎ ነገር የሚሰራ ወይም ነፍሱን የሚበድልና ከዚያም ተጸጽቶ አላህን ምህረት የሚለምን ሁሉ አላህን መሀሪና አዛኝ ሆኖ ያገኘዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 111, '111. ኃጢአት የሚሰራም የሚሰራው ጥፋት ጉዳቱ በራሱ ላይ ብቻ ነው:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 112, '112. ኃጢአትን ወይም ወንጀልን የሚሰራና ከዚያም በእርሱ ንጹህን የሚሰድብ ቅጥፈትንና ግልጽ ኃጢአትን በቁርጥ ተሸከመ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 113, '113. (መልዕክተኛችን ሙሐመድ ሆይ!) የአላህ ችሮታና እዝነቱ ባንተ ላይ ባልነበረ ኖሮ ከእነርሱ የሆነ ቡድኖች ሊያሳስቱህ ባሰቡ ነበር:: ነፍሶቻቸውን እንጂ ሌላ አያሳስቱም:: በምንም አይጎዱህም:: አላህ ባንተ ላይ መጽሐፍንና ጥበብን አወረደ:: የማታውቀውን ሁሉ አስተማረህ:: የአላህ ችሮታ ባንተ ላይ ታላቅ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 114, '114. ከውይይቶቻቸው መካከል በምጽዋት ወይም በበጎ ስራ ወይም በሰዎች መካከል በማስታረቅ ከሚያዙ ሰዎች ውይይት በስተቀር በብዙው ውይይት ውስጥ ደግ ነገር የለበትም:: ይህንንም የተባለውን የአላህን ውዴታ በመፈለግ ለሚሰራ ሁሉ ታላቅ ምንዳን እንሰጠዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 115, '115. ቅኑ መንገድ ለእርሱ ከተገለጸት በኋላ መልዕክተኛውን የሚቃረንና ከምዕመናኖቹ መንገድ ሌላ የሆነን የሚከተል ሁሉ በመረጠው ጥመት ላይ እንተወዋለን። ወደ ገሀነምም እናስገባዋለን:: መመለሻይቱም ገሀነም ከፋች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 116, '116. አላህ በእርሱ ማጋራትን ፈጽሞ አይምርም:: ከሽርክ በታች (ሌላ) ያለውን ጥፋት ግን ለሚሻው ይምራል:: በአላህ የሚያጋራም ከእውነት የራቀን መሳሳት በእርግጥ ተሳሳተ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 117, '117. ከእርሱ ሌላ እንስት ጣኦታትን እንጂ አይገዙም:: አመጸኞች ሰይጣንንም እንጂ ሌላን አይገዙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 118, '118. አላህም የረገመውን (እንዲህ) ያለውንም ሰይጣን እንጂ አይከተሉም: «ከባሮችህ የተወሰነን ድርሻ በእርግጥ እይዛለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 119, '119. «በእርግጥ አጠማቸዋለሁ:: ከንቱን ምኞትም አስመኛቸዋለሁ:: አዛቸዉምና የእንስሶችን ጀሮዎች ይተለትላሉ:: አዛቸዉምና የአላህን ፍጥረት ይለውጣሉ።» (ያለውን ይከተላሉ።) ከአላህ ሌላ ሰይጣንን ረዳት አድርጎ የሚይዝ ግልጽ ኪሳራን በእርግጥ ከሰረ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 120, '120. የማይፈጽመውን ከንቱ ተስፋ ይሰጣቸዋል:: ያስመኛቸዋልም:: ሰይጣን ለማታለል እንጂ ቃል አይገባላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 121, '121. እነዚያ የመጨረሻ መኖሪያቸው ገሀነም ናት:: ከእርሷም መሸሻን አያገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 122, '122. እነዚያ በአላህ ያመኑትና በጎ ስራዎችን የሰሩ ሁሉ በስራቸው ወንዞች የሚፈሱባቸውን ገነቶች ዘላለም በውስጣቸው ዘወታሪዎች ሲሆኑ እናስገባቸዋለን:: አላህ እውነተኛን ተስፋ ሰጣቸው:: በንግግርም ከአላህ ይበልጥ እውነተኛ ማን ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 123, '123. ነገሩ በምኞታችሁና በመጽሐፉ ሰዎች ምኞት አይደለም:: መጥፎን የሚሰራ ሁሉ በእርሱ ይመነዳል:: ለእርሱም ከአላህ ሌላ ጠባቂን ረዳትንም አያገኝም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 124, '124. ከወንድ ወይም ከሴት አማኝ ሆነው ከበጎ ስራዎች አንድንም ነገር የሚሰሩ ገነት ይገባሉ:: በተምር ፍሬ ላይ ያለችን ነጥብ ያክል እንኳን አይበደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 125, '125. መልካም ሰሪ ሆኖ ፊቱን ለአላህ ከሰጠና የኢብራሂምን መንገድ ቀጥተኛ ሲሆን ከተከተለ ሰው ይበልጥ ሃይማኖቱ ያማረ ማን አለ? አላህ ኢብራሂምን ፍጹም ወዳጅ አድርጎ ያዘው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 126, '126. በሰማያትና በምድር ያለው ነገር ሁሉ የአላህ ነው:: አላህ በነገሩ ሁሉ በእውቀት ከባቢ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 127, '127. (መልዕክተኛችን ሙሐመድ ሆይ) ስለ ሴቶች ጉዳይ ይጠይቁሃል። «አላህ ስለነሱ ይነግራችኋል:: ያም በመጽሐፍ ውስጥ በእናንተ ላይ የሚነበበው ሲሆን በእነዚያ ከውርስ የተደነገገላቸውን ድርሻ በማትሰጧቸው ሴቶችና ልታገቧቸው በማትፈልጉት የቲሞች ሴቶች ይህንን እንዳታደርጉ፤ ህፃናት ለሆኑትም ደካሞች መብታቸውን እንድትሰጡ፤ ለየቲሞች በትክክል እንድትቆሙ ይነገራችኋል።» በላቸው:: ከበጎም ስራ የሆነን ማንኛውንም ስራ ብትሰሩ አላህ እርሱን አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 128, '128. ሴት ልጅ ከባሏ ጥላቻን ወይም ከእርሷ ፊቱን ማዞሩን ብታውቅ እና ከዚያ በመካከላቸው እንደገና ቢስማሙ በሁለቱ ላይ ኃጢአት የለባቸዉም:: መታረቅ መልካም ነውና:: ነፍሶች ሁሉ ንፍገት ተጣለባቸው:: (ባሎች ሆይ!) መልካም ነገር ብትሰሩና ብትጠነቀቁ ግን አላህ በምትሰሩት ነገር ሁሉ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 129, '129. (ባሎች ሆይ! ) በሁለትና ከዚያ በላይ በሆኑ ሴቶች መካከል ምንም እንኳን ብትጓጉ በፍቅር ለማስተካከል አትችሉም። ሆኖም እንደተንጠለጠለች (ገመድ) አድርጋችሁ ትተዋት ዘንድ ወደምትወዷት ሴት ሙሉ መዘንበልን አትንዘንበሉ:: ብታበጁና ብትጠነቀቁ አላህ መሀሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 130, '130. ባልና ሚስት በመሀከላቸው በተፈጠረው ችግር ቢለያዩ አላህ ሁሉንም በችሮታው ያብቃቃቸዋል:: አላህ ችሮታው ሰፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 131, '131. በሰማያትና በምድር ያለው ሁሉ የአላህ ነው:: እነዚያንም ከበፊታችሁ መጽሐፍ የተሰጡትን እናንተንም አላህን ፍሩ በማለት በእርግጥ አዘዝን:: ብትክዱም በሰማያትና በምድር ያለው ሁሉ የአላህ ነው አትጎዱትም:: አላህ በራሱ ተብቃቂና ምስጉን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 132, '132. በሰማያትና በምድር ያለው ሁሉ የአላህ ብቻ ነው:: መመኪያነትም በአላህ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 133, '133. (እናንተ ሰዎች ሆይ!) አላህ ቢሻ ያስወግዳችሁና ሌሎችን በቦታችሁ ላይ ይተካል:: አላህም በዚህ ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 134, '134. የቅርቢቱን አለም ምንዳ የሚፈልግ ሁሉ አላህ ዘንድ የቅርቢቱና የመጨረሻይቱ ምንዳ አለ:: አላህ ሁሉን ሰሚ እና ሁሉን ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 135, '135. እናንተ ያመናችሁ ሆይ! በነፍሶቻችሁ ወይም በወላጆችና በቅርብ ዘመዶች ላይ ቢሆንም እንኳ በትክክል ለፍትህ ቋሚዎች ለአላህ መስካሪዎች ሁኑ:: ሀብታም ወይም ድሃ ቢሆንም አላህ ከእነርሱ ለእናንተ ይበልጥ ተገቢ ነው:: እንዳታዳሉም ዝንባሌን አትከተሉ:: ምስክርን ብታጣምሙ ወይም መመስከርን ብትተው አላህ በምትሰሩት ነገር ላይ ሁሉ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 136, '136. እናንተ ያመናችሁ ሆይ! በአላህና በመልዕክተኛው በዚያ በመልዕክተኛው ላይ ባወረደው መጽሐፍም ከዚያ በፊትም ባወረደው መጽሐፍ እመኑ:: በአላህ፣ በመላዕክቱ፣ በመጽሐፍቱ፣ በመልዕክተኞቹና በመጨረሻውም ቀን የካደ ሁሉ ከእውነት የራቀን መሳሳት በእርግጥ ተሳሳተ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 137, '137. እነዚያ ያመኑና ከዚያም የካዱ ከዚያም ያመኑ ከዚያም የካዱ ከዚያም ክህደትን የጨመሩ አላህ ለእነርሱ የሚምራቸውና ቅኑን መንገድም የሚመራቸው አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 138, '138. አስመሳዮችን ለእነርሱ አሳማሚ ቅጣት ያላቸው መሆኑን አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 139, '139. እነዚያ ከአማኞች ሌላ ከሓዲያንን ወዳጆች አድርገው የሚይዙ ሰዎች እነርሱ ዘንድ ልቅናን ይፈልጋሉን? ልቅና ሁሉ ለአላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 140, '140. በእናንተ ላይ በመጽሐፉ ውስጥ የአላህን አናቅጽ በእርሷ ሲካድባት በእርሷም ሲላገጥባት በሰማችሁ ጊዜ በሌላ ወሬ ውስጥ እስከሚገቡ ድረስ ከእነርሱ ጋር አትቀመጡ ማለትን በእርግጥ አወረደ:: እናንተ ያን ጊዜ ቢጤያቸው ናችሁና:: አላህ አስመሳዮችንም ከሓዲያንንም በገሀነም ውስጥ ሰብሳቢ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 141, '141. እነዚያ (አስመሳዮች) በእናንተ ላይ የጊዜ መዘዋወርን የሚጠባበቁ ናቸው:: ለእናንተም ከአላህ የሆነ አሸናፊነት ሲኖራችሁ «ከናንተ ጋር አልነበርንምን?» ይላሉ:: ለከሓዲያን እድል ሲኖር ደግሞ «ከአሁን በፊት እኛ በእናንተ ላይ አልተሾምንባችሁምና (አልተውናችሁምን?) ከአማኞች አደጋስ አልከለከልናችሁምን?» ይላሉ:: አላህ በትንሳኤ ቀን በመካከላችሁ ይፈርዳል:: አላህ ለከሓዲያን በአማኞች ላይ መንገድን በፍጹም አያደርግም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 142, '142. አስመሳዮች አላህን ያታልላሉ:: እርሱም አታላያቸው ነው:: ወደ ሶላትም በቆሙ ጊዜ ታካቾችና ሰዎችን የሚያሳዩ ሆነው ይቆማሉ:: አላህንም ጥቂትን እንጂ አያወሱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 143, '143. በዚህ መካከል ወላዋዮች ሆነው ይታያሉ:: ወደ እነዚህም ወደ እነዚያም አይደሉም:: አላህም ያሳሳተውን ለእርሱ የቅንነት መንገድን በፍጹም አታገኝለትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 144, '144. እናንተ ያመናችሁ ሆይ! ከአማኞች ሌላ ከሓዲያንን ወዳጆች አድርጋችሁ አትያዙ:: ለአላህ በእናንተ ላይ ግልጽ ማስረጃዎችን ልታደርጉ ትፈልጋላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 145, '(መልዕክተኛችን ሙሐመድ ሆይ!) አስመሳዮች በእርግጥ ከእሳት በታችኛዋ አዘቅት ውስጥ ናቸው:: እናም ለእነርሱ ረዳትን አታገኝላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 146, '146. እነዚያ የተመለሱና ስራቸውን ያሳመሩ በአላህ የተጠበቁ ሃይማኖታቸውንም ለአላህ ፍጹም ያደረጉት ሲቀሩ:: እነዚያስ ከአማኞች ጋር ናቸው:: ለአማኞችም አላህ ታላቅን ምንዳ በእርግጥ ይሰጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 147, '147. ብታመሰግኑና ብታምኑ አላህ እናንተን በመቅጣት ምን ያደርጋል? አላህም ወረታን መላሽ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 148, '148. አላህ በክፉ ንግግር መጮህን ከተበደለ ሰው ጩኸት በስተቀር አይወድም:: አላህ ሁሉን ሰሚ እና ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 149, '149. ደግ ነገርን ብትገልጹ ወይም ብትደብቁት ወይም ከመጥፎ ነገር (በደል) ይቅርታ ብታደርጉ አላህ ይቅር ባይ እና ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 150, '150. እነዚያ በአላህና በመልዕክተኞቹ የሚክዱ፤ በአላህና በመልዕክተኞቹም መካከል መለየትን የሚፈልጉና «በከፊሉ እናምናለን በከፊሉ ደግሞ እንክዳለን» የሚሉ ሁሉ በዚህ መካከል መንገድን ሊይዙ የሚፈልጉ፣', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 151, '151. በእውነቱ እነዚያ ከሓዲያን እነርሱው ናቸው:: ለከሓዲያንም አዋራጅን ቅጣት አዘጋጅተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 152, '152. እነዚያ በአላህና በመልዕክተኞቹ ያመኑ፤ ከእነርሱም መካከል በአንዱም ያልለዩ ሰዎች እነዚያ ምንዳዎቻቸው በእርግጥ ይሰጣቸዋል:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 153, '153. (መልዕክተኛችን ሙሐመድ ሆይ!) የመጽሐፉ ባለቤቶች እነርሱ ላይ ከሰማይ መጽሐፍን እንድታወርድ ይጠይቁሃል:: ከዚህም የከበደን ጥያቄ ከዚህ በፊት ሙሳን በእርግጥ ጠይቀዋል:: «አላህን በግልጽ አሳየን።» ብለዋል:: በበደላቸዉም ምክንያት መብረቅ ያዘቻቸው:: ከዚያም ተዓምራት ከመጡላቸው በኋላ ወይፈኑን አምላክ አድረገው ያዙ:: ከዚያ ያንን ይቅር አልን:: ሙሳንም ግልጽ ስልጣን ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 154, '154. በቃል ኪዳናቸው ምክንያት የጡር ተራራን ከበላያቸው አነሳን:: ለእነርሱም «ደጃፍን ስትገቡ አጎንብሳችሁ ግቡ።» አልን:: ለእነርሱም «በሰንበት ቀን ትዕዛዝን አትተላለፉ።» አልን:: ከእነርሱም ከባድን ቃል ኪዳን ያዝን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 155, '155. ቃል ኪዳናቸውን በማፍረሳቸው፤ በአላህ አናቅጽ በመካዳቸው፤ ነብያትን ያለ አግባብ በመግደላቸውና «ልቦቻችን ሽፍን ናቸው።» በማለታቸውም ምክንያት ረገምናቸው:: በእውነቱ በክህደታቸው ምክንያት አላህ በእርሷ ላይ አተመ:: ስለዚህ ጥቂትን እንጂ አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 156, '156. በመካዳቸዉም በመርየም ላይ ከባድ ቅጥፈትን በመናገራቸው ምክንያት ረገምናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 157, '157. «እኛ የአላህ መልዕክተኛ የመርየም ልጅ አል መሲህ ዒሳን ገደልን።» በማለታቸውም ረገምናቸው:: አልገደሉትም:: አልሰቀሉትምም:: ግን የተገደለው ሰው ለእነርሱ በዒሳ ተመሰለባቸው:: እነዚያ በእርሱ ጉዳይ የተለያዩት በእርሱ መገደል በመጠራጠር ውስጥ ናቸው:: ጥርጣሬን ከመከተል በስተቀር በእርሱ ነገር ምንም እርግጠኛ እውቀት የላቸዉም:: በእርግጥም አልገደሉትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 158, '158. ይልቁንስ አላህ ወደ እርሱ አነሳው:: አላህም አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 159, '159. ከመጽሐፉ ባለቤቶች መካከልም ከነብዩ ዒሳ ሞት በፊት በነብዩ ዒሳ በእርግጥ በትክክል የሚያምን እንጂ አንድም የለም:: በትንሳኤ ቀንም ዒሳ በእነርሱ ላይ መስካሪ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 160, '160. ከእነዚያ ከአይሁዳውያን መካከል በፈጸሙት በደልና ሰዎችን ከአላህ መንገድ በብዙ በመከላከላቸው ምክንያት ለእነርሱ ተፈቅደው የነበሩ ጣፋጮች ምግቦችን እርም አደረግንባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 161, '161. ከእርሱ በቁርጥ የተከለከሉ ሲሆኑ አራጣን በመያዛቸውና የሰዎችን ገንዘቦች ያለ አግባቡ በመብላታቸዉም ምክንያት የተፈቀደላቸውን እርም አደረግንባቸው:: ከእነርሱም መካከከል ለከሓዲያን አሳማሚ ቅጣት አዘጋጀን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 162, '162. (መልዕክተኛችን ሙሐመድ ሆይ!) ግን ከእነርሱ ውስጥ በእውቀት የጠለቁት ክፍሎችና ትክክለኛ ምዕመናኖቹ ባንተ ላይ በተወረደውና ካንተ በፊት በተወረደው መጽሐፍ ያምናሉ። ሶላትንም ደንቡን ጠብቀው ሰጋጆቹ፣ ዘካንም ሰጪዎቹ በአላህና በመጨረሻው ቀንም ትክክለኛ አማኞቹን እነዚያ ታላቅ ምንዳን በእርግጥ እንሰጣቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 163, '163. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ ወደ ኑህና ከእርሱ በኋላ ወደ ነበሩት ነብያት መልዕክታችንን እንዳወረድን ሁሉ ወደ አንተም ቁርኣንን አወረድን:: ወደ ነብዩ ኢብራሂም፤ ወደ ነብዩ ኢስማኢልም፤ ወደ ነብዩ ኢስሃቅም፤ ወደ ነብዩ የዕቆብም፤ ወደ ነገዶችም፤ ወደ ነብዩ ዒሳም፤ ወደ ነብዩ አዩብም፤ ወደ ነብዩ ዩኑስም፤ ወደ ነብዩ ሃሩንና ወደ ነብዩ ሱለይማን አወረድን:: ለነብዩ ዳውድም ዘቡርን ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 164, '164. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዚህም በፊት በአንተ ላይ በእርግጥ የተረክናቸውን መልዕክተኞች ባንተ ላይም ያልተረክናቸውንም መልዕክተኞች እንደላክን ሁሉ አንተን ላክንህ:: አላህ ነብዩ ሙሳንም ማነጋገርን አነጋገረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 165, '165. ከመልዕክተኞች በኋላ ለሰዎች በአላህ ላይ ምንም አስረጂ እንዳይኖራቸው አብሳሪዎችና አስፈራሪዎች አድርገን መልዕክተኞችን ላክን:: አላህ ሁሉን አሸናፊ፤ ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 166, '166. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ግን ባንተ ላይ ባወረደው ቁርኣን ይመሰክራል:: በእውቀቱ አወረደው:: መላዕክቱም ይመሰክራሉ:: መስካሪነትም በአላህ ብቻ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 167, '167. እነዚያ በአላህ የካዱና ከአላህ መንገድም ሰዎችን ያገዱ ሰዎች ከእውነት የራቀን መሳሳት በእርግጥ ተሳሳቱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 168, '168. እነዚያ የካዱና የበደሉ አላህ የሚምራቸውና ቅን መንገድን የሚመራቸው አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 169, '169. ግን በውስጧ ለዘልዓለም ዘወታሪዎች ሲሆኑ የገሀነምን መንገድ ይመራቸዋል:: ይህም በአላህ ላይ ገር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 170, '170. እናንተ ሰዎች ሆይ! መልዕክተኛው እውነትን ከጌታችሁ አመጣላችሁ:: እናም ባመጣው እመኑ ለእናንተ የተሻለ ይሆናል:: በአላህ ብትክዱም እሱን (ቅንጣት) አትጎዱትም:: በሰማያትና በምድር ያለው ሁሉ የአላህ ነውና:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 171, '171. እናንተ የመጽሐፉ ባለቤቶች ሆይ! በሃይማኖታችሁ ወሰንን አትለፉ:: በአላህም ላይ እውነትን እንጂ አትናገሩ:: የመርየም ልጅ አል መሲህ ዒሳ የአላህ መልዕክተኛ ወደ መርየም የጣላት የሁን ቃሉና ከእርሱ የሆነ መንፈስ ብቻ ነው:: በአላህና በመላዕክተኞቹ እመኑ:: «አማልዕክት ሶስት ናቸው።» አትበሉ:: ተከልከሉ:: ለእናንተ የተሻለ ይሆናልና:: አላህ አንድ አምላክ ብቻ ነው:: ለእርሱም ልጅ ያለው ከመሆን የጠራ ነው:: በሰማያትና በምድር ያለው ሁሉ የእርሱ ብቻ ነው:: መመኪያነትም በአላህ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 172, '172. አል መሲህ ለአላህ ባሪያ ከመሆን ፈጽሞ አይጸየፍም:: ቀራቢዎች የሆኑ መላዕክትም እንዲሁ ለአላህ ባሪያ ከመሆን ፈጽሞ አይጸየፉም:: ወደ አላህ እርሱን ከመገዛት የሚጸየፉና የሚኮሩ ሁሉ አላህ ሁሉንም ወደ እርሱ በእርግጥ ይሰበስባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 173, '173. እነዚያ በአላህ ያመኑና መልካም ተግባራትን የሰሩትን ምንዳዎቻቸውን ይሞላላቸዋል:: ከችሮታዉም ይጨምርላቸዋል:: እነዚያን የተጸየፉትና የኮሩትን ግን አሳማሚውን ቅጣት ይቀጣቸዋል:: ከአላህ ሌላ ለእነርሱ ዘመድና ረዳት አያገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 174, '174. እናንተ ሰዎች ሆይ! ከጌታችሁ ዘንድ በእርግጥም አስረጅ መጣላችሁ:: ወደ እናንተም ገላጭ የሆነን ብርሃንን (ቁርኣንን) አወረድን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 175, '175. እነዚያማ በአላህ ያመኑና በእርሱ የተጠበቁ ሰዎች ከእርሱ በሆነው እዝነትና ችሮታ ውስጥ እርግጥ ያስገባቸዋል:: ወደ እርሱም ቀጥተኛ መንገድን ይመራቸዋልም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (4, 176, '176. (መልዕክተኛችን ሙሐመድ ሆይ!) ይጠይቁሃል: «ወላጆችና ልጅ ሳይኖረው በሚወረስ ሟች ሰው ጉዳይ አላህ ይነግራችኋል።» በላቸው፡፡ ልጅ የሌለው ሰው ቢሞትና ለእርሱ እህት ብትኖረው ለእርሷ ከተወው ንብረት ግማሽ አላት፡፡ እርሱም ለእርሷ ልጅ የሌላት እንደሆነች በሙሉ ይወርሳታል፡፡ ሁለት እህቶች ወይም ከሁለት በላይ ቢሆኑ ግን ከተወው ንብረት ከሶስት ሁለት እጅ አላቸው ፡፡ ወንድሞችና እህቶች ወንዶችና ሴቶች ቢሆኑ ደግሞ ለወንድ የሁለት ሴቶች ድርሻ ያህል አለው ፡፡ አላህ እንዳትሳሳቱ ህግጋትን ለእናንተ ያብራራል ፡፡ አላህ በነገሩ ሁሉ አዋቂ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 1, '1. እናንተ ያመናችሁ ሆይ! ቃልኪዳኖቻችሁን ሙሉ:: በእናንተ ላይ የሚነበበው ብቻ ሲቀር የግመል፤ የከብት፤ የበግና የፍየል እንስሳት ተፈቅዶላችኋል:: በሐጅ ስራ ላይ ሆናችሁ አውሬ ማደንን እንደ ተፈቀደ ሳትቆጥሩ የሚበሉት የዱር እንስሳትም ተፈቅደውላችኋል:: አላህ የሚፈልገውን ሁሉ ነገር ይፈርዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 2, '2. እናንተ ያመናችሁ ሆይ! አላህ ምልክቶች ይሆኑ ዘንድ የከለከላቸውን ነገሮች የተፈቀዱ አታድርጉ። የተከበረውንም ወር በውስጡ ጦርነትን በማካሄድ አትድፈሩት:: ወደ መካ የሚነዱትን የመስዋዕት እንስሳትና የሚታበቱባቸውን ገመዶች፤ ከጌታቸው ችሮታንና ውዴታን ፈልገው ወደ ተከበረው ቤት አሳቢዎችንም በክፉ አትንኳቸው:: የሐጅን ስራ ፈጽማችሁ ባጠናቀቃችሁ ጊዜ የዱር አውሬዎችን እንደልባችሁ አድኑ:: ከተከበረው መስጊድ ስለከለከሏችሁ ሰዎችን መጥላታችሁ በእነርሱ ላይ ወሰንን እንድታልፉና ፍትህን እንድታዛቡ አይገፋፉችሁ:: በበጎ ተግባርና አላህን በመፍራት እርስ በእርስ ተባበሩ:: ኃጢአትና ወሰንን በማለፍ ግን አትተባበሩ:: አላህን በትክክል ፍሩ:: አላህ ቅጣተ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 3, '3. (ስዎች ሆይ!) በክት፤ ደም፤ የአሳማ ስጋ፤ ሲታረድ ከአላህ ስም ሌላ የተወሳበት እንሰሳ፤ ታንቃ የሞተች፤ ተደብድባ የተገደለች፤ ተንከባላ የሞተች፤ በቀንድ ተወግታ የሞተችና አውሬ የበላት ከእነዚህ በሕይወት ላይ እያሉ ደርሳችሁ ያረዳችሁት ብቻ ሲቀር ለጣዖታት የታረደና በአዝላም እድልን መፈለጋችሁ በእናንተ ላይ እርም ተደረገ:: እነዚህ ከላይ የተዘረዘሩትን መፈጸም አላህን ማመጽ ነው:: ዛሬ እነዚያ በአላህ የካዱት ከሀይማኖታችሁ ተስፋ ቆረጡ:: ስለዚህ አትፍሩዋቸው:: ይልቁን እኔን ብቻ ፍሩኝ:: ዛሬ ሃይማኖታችሁን ሞላሁላችሁ:: ጸጋየንም በእናንተ ላይ ፈጸምኩ:: ለእናንተም በሃይማኖትነት ኢስላምን ወደድኩላችሁ:: በርሀብ ወቅት ወደ ኃጢአት ያዘነበለ ሳይሆን እርም የሆኑትን ነገሮች ለመብላት የተገደደ ሰው ሁሉ ለሕይወቱ ማቆያ ያህል ቢበላ ምንም ችግር የለበትም:: አላህ መሀሪና አዛኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 4, '4.(መልዕክተኛችን ሙሐመድ ሆይ! ሙስሊሞች ) ምን ምን እንደተፈቀደላቸው ይጠይቁሃል:: «ለእናንተ መልካሞች ሁሉ እና እነዚያም አላህ ካሳወቃችሁ አሰልጣኞች ሆናችሁ ያስተማራችኋቸው አዳኞች ውሾች ያደኑት ሁሉ ተፈቀደላችሁ።» በላቸው:: አላህ ካስተማራችሁ እውቀት ታስተምሯቸዋላችሁ:: ከያዙላችሁ ነገር ብሉ:: የአላህንም ስምም አውሱበት:: አላህን ፍሩ:: አላህ ምርመራው ፈጣን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 5, '5. (አማኞች ሆይ!) ዛሬ መልካም ነገሮች ለእናንተ ተፈቀዱ:: የእነዚያ መጽሐፍን የተሰጡ ሰዎች ምግብም (እርድ) ለእናንተ የተፈቀደ ነው:: ምግባችሁም ለእነርሱ የተፈቀደ ነው:: ከምዕመናት ሴቶችም ጥብቆቹ፤ ከእነዚያ ከናንተ በፊት መጽሐፍን ከተሰጡ ህዝቦች ሴቶችም መካከል ጥብቆቹ፤ ዝሙተኞችና የሚስጥር ወዳጅ ያዢዎች ሳትሆኑ መህሮቻቸውን በሰጣችኋቸው ጊዜ ልታገቧቸው የተፈቀዱ ናቸው:: በአላህ ካመነ በኋላ ከእምነቱ ወደ ክህደት የሚመለስ ሁሉ በእርግጥ ስራው ተበላሸ:: በመጨረሻም ቀን ከከሳሪዎች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 6, '6. እናንተ ያመናችሁ ሆይ! ወደ ሶላት ለመግባት ባሰባችሁ ጊዜ ፊቶቻችሁንና እጆቻችሁን እስከ ክርኖቻችሁ ድረስ እጠቡ:: ራሶቻችሁንም በውሃ አብሱ:: እግሮቻችሁን እስከ ቁርጭምጭሚቶች እጠቡ:: ጀናባ ከሆናችሁ ሙሉ ገላችሁን ታጠቡ:: በሽተኞች ወይም በጉዞ ላይ ብትሆኑ ወይም ከናንተ አንዳችሁ ከዓይነ ምድር ቢወጣ ወይም ሴቶችን ብትነኩና (የግብረ ስጋ ግንኙነት ብትፈጽሙና) ውሃን ባታገኙ በንጹህ የምድር አፈር ተይሙም አድርጉ:: ከዚያም ከእርሱ ፊታችሁንና እጆቻችሁን አብሱ:: አላህ በእናንተ ላይ ምንንም ችግር ሊያደርግ አይሻምና:: ይልቁንም አላህን ታመሰግኑት ዘንድ ሊያጠራችሁና ጸጋውን በእናንተ ላይ ሊሞላ ይፈልጋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 7, '7. በእናንተ ላይ የለገሰውን የአላህን ጸጋና ያንንም «ሰምተናል ታዘናልም» ባላችሁ ጊዜ ያጠበቀባችሁን ቃል ኪዳኑን አስታውሱ:: አላህንም ፍሩ:: አላህ በልቦች ውስጥ ያለውን ሁሉ አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 8, '8. እናንተ ያመናችሁ ሆይ! ለአላህ የቆማችሁ ቀጥተኞች በትክክል መስካሪዎች ሁኑ:: ሕዝቦችንም መጥላታችሁ ላለማስተካከል አይገፋፋችሁ ፍትሀዊ ሁኑ:: ማስተካከል ለአላህ ፍራቻ በጣም የቀረበ ነው:: አላህን ፍሩ:: አላህ የምትሰሩትን ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 9, '9. እነዚያ በአላህ ያመኑና በጎ ስራዎችን የሰሩ ሁሉ (አላህ ገነትን ቃል ገባላቸው::) ለእነርሱ ምህረትና ታላቅ ምንዳ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 10, '10. እነዚያ በአላህ የካዱና በአናቅጻችን ያስተባበሉ ሁሉ የእሳት ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 11, '11. እናንተ ያመናችሁ ሆይ! ሕዝቦች እጆቻቸውን ለጥቃት ወደ እናንተ ሊዘረጉ ባሰቡና እጆቻቸውን ከናንተ ላይ በከለከለላችሁ ጊዜ ለእናንተ የዋለላችሁን ጸጋ አስታውሱ:: አላህንም ፍሩ። አማኞች በአላህ ላይ ብቻ ይመኩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 12, '12. አላህ የኢስራኢል ልጆችን የጠበቀ ቃል ኪዳን በእርግጥ ያዘባቸው:: ከእነርሱም መካከል አስራ ሁለት አለቆችን አስነሳን:: አላህም አላቸው፡- «ከእናንተ ጋር ነኝ። ሶላትን ደንቡን ጠብቃችሁ ብትሰግዱ፤ ግዴታ ምጽዋትንም በትክክል ብትሰጡ፤ በመልዕክተኞቼም በሙሉ ብታምኑና በሚያደርጉት ትግል ብትረዷቸው፤ ለአላህ መልካም ብድርን ብታበድሩ ኃጢአቶቻችሁንም አብስላችኋለሁ:: ከስሮቻቸው ወንዞች የሚፈሱባቸው ገነቶችም በእርግጥ አስገባችኋለሁ:: ከዚህ በኋላ ከናንተ መካከል በአላህ የካደ ግን ከቀጥተኛው መንገድ ተሳሳተ::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 13, '13. ቃል ኪዳናቸውን በማፍረሳቸው ረገምናቸው:: ልቦቻቸውንም ደረቆች አደረግን:: ቃላትን ከቦታዎቻቸው ይለውጣሉ:: ከታዘዙትም ነገር ከፊሉን ተው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም ጥቂቶቹ ሲቀሩ ክዳትን ከማየት አትወገድም:: ለእነርሱ ይቅርታ አድርግ:: እለፋቸዉም:: አላህ መልካም ሰሪዎችን ሁሉ ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 14, '14. ከእነዚያም «እኛ ክርስቲያኖች ነን» ካሉት ክፍሎች መካከል የጠበቀ ቃል ኪዳናቸውን ያዝን:: ሆኖም ከታዘዙበት ነገር ከፊሉን ተው:: ስለዚህም እስከ ትንሳኤ ቀን ድረስ በመካከላቸው ጠብንና ጥላቻን ጣልንባቸው:: አላህም ይሰሩት የነበሩትን ሁሉ ይነግራቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 15, '15. እናንተ የመጽሐፍ ባለቤቶች ሆይ! ከመጽሐፉ መካከል ትሸሽጉት ከነበራችሁት ነገር ብዙውን ለእናንተ የሚገልጽ ብዙውንም የሚተው ሲሆን መልዕክተኛችን ሙሐመድ መጣላችሁ:: ከአላህ ዘንድም ብርሃንና ገላጭ የሆነ መጽሐፍ መጣላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 16, '16. አላህ ውዴታውን የተከተሉትን ሁሉ የሰላምን መንገዶች በእርሱ ይመራበታል:: በፈቃዱም ከጨለማዎች ወደ ብርሃን ያወጣቸዋል:: ወደ ቀጥተኛዉም መንገድ ይመራቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ «አላህ ማለት የመርየም ልጅ አልመሲህ ነው።» ያሉ ሰዎች ሁሉ በእርግጥ በአላህ ካዱ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ የመርየምን ልጅ አልመሲህንና እናቱን እንደዚሁም በምድር ያለን ፍጡር ሁሉ ለማጥፋት ቢሻ ከአላህ ማዳን የሚችል ማን ነው? የሰማያትና የምድር የመካከላቸዉም ንግስና የአላህ ብቻ ነው:: የሚፈልገውን ይፈጥራል:: አላህ በሁሉም ነገር ላይ ቻይ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 18, '18. አይሁድና ክርስቲያኖች «እኛ የአላህ ልጆችና ወዳጆቹ ነን።» አሉ። «ታዲያ በኃጢአቶቻችሁ ለምን ይቀጣችኋል? አይደላችሁም:: እናንተ ከፈጠራቸው መካከል የሆናችሁ ሰዎች ናችሁ:: አላህ ለሚሻው ይምራል:: የሚሻውን ይቀጣል:: የሰማያትና የምድር በመካከላቸዉም ያለው ሁሉ ንግስናው የአላህ ብቻ ነው:: መመለሻም ወደ እርሱ ብቻ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 19, '19. እናንተ የመጽሐፉ ሰዎች ሆይ! «አብሳሪና አስፈራሪ አልመጣልንም።» እንዳትሉ መልዕክተኞቻችን በተቋረጡበት ጊዜ መመሪያዎችን የሚያብራራ ሆኖ መልዕክተኛችን ሙሐመድ በእርግጥ መጣላችሁ:: አብሳሪና አስፈራሪም በእርግጥ መጣላችሁ፡፡ አላህ በሁሉ ነገር ላይ ቻይ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 20, '20. ሙሳም ለሕዝቦቹ ባለ ጊዜ አስታውስ፡- «ሕዝቦቼ ሆይ! አላህን በእናንተ ላይ የዋለውን ጸጋ አስታውሱ፣ በውስጣችሁ ነብያትን ባደረገ፤ ነገስታትም ባደረጋችሁና ከአለማት ህዝብ ለአንድም ያልሰጠውን ችሮታ በሰጣችሁ ጊዜ ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 21, '21. ‹‹ሕዝቦቼ ሆይ! ያችን አላህ ለእናንተ ያደረጋትን የተቀደሰችውን መሬት ግቡ:: ወደ ኋላችሁም አትመለሱ:: ከሳሪዎች ሆናችሁ ትመለሳላችሁና›› (ባሉ ጊዜ የሆነዉን አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 22, '22. «ሙሳ ሆይ! በእርሷ ውስጥ ሀያላን ህዝቦች ስላሉ ከእርሷ እስከሚወጡ ድረስ ፈጽሞ አንገባትም:: ከወጡ ግን ገቢዎች ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 23, '23. ከእነዚያ አላህን ከሚፈሩትና አላህ ጸጋውን ከለገሰላቸው ሰዎች መካከል ሁለት ሰዎች «በእነርሱ በሀያሎቹ ላይ በሩን ግቡ:: በገባችሁ ጊዜ እናንተ አሸናፊዎች ናችሁ:: ትክክለኛ አማኞችም እንደሆናችሁ በአላህ ላይ ብቻ ተመኩ።» አሏቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 24, '24. «ሙሳ ሆይ! እነርሱ በውስጧ እስካሉ ድረስ ፈጽሞ ምንጊዜም አንገባም:: ስለዚህ አንተና ጌታህ ሂዱና ተዋጉ:: እኛ እዚህ ተቀማጮች ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 25, '25. ሙሳም «ጌታዬ ሆይ! እኔ ራሴንና ወንድሜን እንጂ ማንንም ላስገድድ አልችልም። ስለዚህ በእኛና በአመጸኞቹ ሕዝቦች መካከል ተገቢ ፍርድህን ስጥ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 26, '26. አላህም: «ያቺ የተቀደሰችው መሬት በእነርሱ ላይ ለአርባ አመት ያህል እርም ናት። በምድረ በዳ ይንከራተታሉ። (ሙሳ ሆይ!) በአመጸኞችም ሕዝቦች ላይ አትዘን።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 27, '27. (መልዕክተኛችን ሙሐመድ ሆይ!) በእነርሱ ላይ የአደምን ሁለት ልጆች ወሬ (ማለትም) ሁለቱም ቁርባን ባቀረቡና አላህ ከአንደኛቸው ቁርባኑን ተቀብሎ ከሌላው ባልተቀበለበት ጊዜ የሆነውን ታሪክ አንብብላቸው:: ተቀባይነት ያጣው ወንድሙን «እገድልሃለሁ።» አለው። (የተዛተበትም) አለ: «አላህ የሚቀበለው እኮ ከጥንቁቆቹ ብቻ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 28, '28. «ልትገድለኝ እጅህን ወደ እኔ ብትዘረጋ እንኳን እኔ ልገድልህ እጄን ወደ አንተ የምዘረጋ አይደለሁም:: እኔ የአለማቱን ጌታ አላህን እፈራለሁና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 29, '29. «እኔ በኃጢአቴና በኃጢአትህ ወደ ጌታህ ልትመለስና ከእሳት ጓዶች አንዱ ልትሆን እሻለሁ:: ይህም የበደለኞች ቅጣት ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 30, '30. ነፍሱም ወንድሙን መግደሉ አስቻላትና(አስዋበችለት) ገደለው። ከከሳሪዎችም ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 31, '31. ዘንድ አላህ መሬትን የሚጭር ቁራ ላከለት የወንድሙን ሬሳ እንዴት እንደሚቀብር ሊያሳየው። «ወይኔ የወንድሜን ሬሳ እቀብር ዘንድ እንደዚህ ቁራ መሆን እንኳን አቃተኝን?» አለ። ከዚያም ከጸጸተኞች ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 32, '32. በዚህ ምክንያት በኢስራኢል ልጆች ላይ «አንዲትን ንጹህ ነፍስን (ያልገደለችን) ወይም በምድር ላይ ምንንም ያላጠፋችን ነፍስ የገደለ ሁሉ ሰዎችን ሁሉ እንደገደለ ነው:: አንዲትን ነፍስ ህያው ያደረጋትም ሰዎችን ሁሉ ህያው እንዳደረገ ነው።» ማለትን ደነገግን። መልዕክተኞቻችንም ግልጽን ተዐምራት አምጥተውላቸዋል። ከዚህም በኋላ ከእነርሱ ብዙዎቹ በምድር ላይ ወሰንን አላፊዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 33, '33. የእነዚያ አላህንና መልዕክተኛውን የሚዋጉ፤ በምድርም ላይ ለጥፋት የሚንቀሳቀሱ ሁሉ ቅጣት መገደል ወይም መሰቀል ወይም እጆቻቸውንና እግሮቻቸውን በማፈራረቅ መቆረጥ ወይም ከሀገር መባረር ነው:: ይህ ቅጣት ለእነርሱ በቅርቢቱ ዓለም ውርደት ነው:: በመጨረሻይቱም ዓለም ከባድ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 34, '34. (ሙስሊሞች ሆይ!) (ይህ ተግባር የሚፈጸመው) እነዚያ በእነርሱ ላይ ከመቻላችሁ በፊት የተጸጸቱት ሲቀሩ (ነው)፤ አላህም መሀሪና አዛኝ መሆኑን እወቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 35, '35. እናንተ ያመናችሁ ሆይ! አላህን ፍሩ:: ወደ እርሱም የሚያቀርባችሁን ነገር ሁሉ ፈልጉ:: ትድኑ ዘንድም በእርሱ መንገድ ላይ ብቻ ታገሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 36, '36. እነዚያ የካዱት በምድር ላይ ያለ ነገርን ሁሉ እና ከርሱ ጋርም መሰሉ ተጨምሮላቸው ከትንሳኤ ቀን ቅጣት ነፃ ለመሆን እርሱን ቤዛ ቢሰጡ እንኳን ተቀባይነት አያገኙም። ለእነርሱም አሳማሚ ቅጣት አለባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 37, '37. ከእሳት ሊወጡ ይፈልጋሉ:: እነርሱ ግን ሁልጊዜም ከእርሷ ወጪዎች አይደሉም:: ለእነርሱ ዘውታሪ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 38, '38. የወንድ ሌባንና የሴት ሌባን ለሰሩት ወንጀል ከአላህ የሆነ መቀጫ ሲሆን እጆቻቸውን ቁረጡ:: አላህ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 39, '39. ከበደለ በኋላ የተጸጸተና ስራውን ያሳመረ ሁሉ አላህ ጸጸቱን ይቀበለዋል:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ የሰማያትና የምድር ንግስና የእሱ ብቻ መሆኑን አላወክምን? የሚሻውን ሰው ይቀጣል:: ለሚሻውም ሰው ይምራል፡፡ አላህም በነገሩ ሁሉ ላይ ቻይ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 41, '41. መልዕክተኛችን ሙሐመድ ሆይ! እነዚያ ወደ ክህደት የሚቻኮሉ ሆነው ልቦቻቸው ሳያምኑ በአፎቻቸው ብቻ «አመንን» ካሉት አስመሳዮችና ከእነዚያም አይሁዶቹ አያሳዝኑህ:: እነርሱ ውሸትን ብቻ አድማጮች ናቸውና:: ገና ወደ አንተ ላልመጡ ለሌሎች ሕዝቦች አድማጮች ናቸው:: ንግግሮችንም ከስፍሮቻቸው ወደ ሌላ በመቀየር መልዕክት ያጣምማሉ። «ይህንን የተጣመመውን ከተሰጣችሁ ያዙት:: ካልተሰጣችሁም ተጠንቀቁ።» ይላሉ:: አላህ መፈተንን የሚሻበትን ሰው ሁሉ ለእርሱ ከአላህ ለመከላከል ፍጹም አትችልም:: እነዚያ ማለት አላህ ልቦቻቸውን ማጥራትን ያልሻላቸው ሰዎች ናቸው:: ለእነርሱም በቅርቢቱ ዓለም ውርደት አለባቸው:: ለእነርሱ በመጨረሻይቱ ዓለምም ሌላ ከባድ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 42, '42. እነርሱ ውሸትን አድማጮች፤ እርም የሆኑ ነገሮችን በላተኞች ናቸው:: እናም ለዳኝነት ወደ አንተ ዘንድ ከመጡ በመካከላቸው በትክክል ፍረድ። ወይም ተዋቸው:: ብትተዋቸው በምንም አይጎዱሁም:: ከፈረድክ ግን በመካከላቸው በትክክል ፍረድ:: አላህ በትክክል ፈራጆችን ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 43, '43. እነርሱ ዘንድ በውስጧ የአላህ ፍርድ ያለባት ተውራት እያለ እንዴት ያስፈርዱሃል? ከዚያ በኋላ ይሸሻሉ። እነዚያ በፍጹም ትክክለኛ አማኞች አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 44, '44. ተውራትን በውስጡ ለሰዎች መመሪያና ብርሃን ያለባት ሲሆን አወረድነው:: እነዚያ ትዕዛዙን የተቀበሉት ነብያት በአይሁዳውያን ላይ በእርሱ ይፈርዳሉ:: ሊቃውንቱና አዋቂዎቹም ከአላህ መጽሐፍን እንዲጠብቁ በተደረጉትና በእርሱ ላይ መስካሪዎቹ በመሆናቸው እንዲሁ በሱ ይፈርዳሉ:: እናም ሰዎችን አትፍሩ:: እኔን ብቻ ፍሩኝ:: በአንቀፆቼም አነስተኛን ዋጋ አትለውጡ አትግዙ:: እነዚያ አላህ ባወረደው መመሪያ ያልፈረዱ ሁሉ ከሓዲያን ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 45, '45. በእነርሱም ላይ በውስጡ ነፍስን በነፍስ፤ አይንን በአይን፤ አፍንጫን በአፍንጫ፤ ጆሮን በጆሮ፤ ጥርስን በጥርስ፤ ይያዛል:: ቁስሎችንም ማመሳሰል አለባቸው ብለን ደነገግን:: ይህንን መብቱን ይቅር ያለ ሁሉ እርሱ ለኃጢአቱ ማሰረዣው ነው:: አላህ ባወረደው መመሪያ የማይፈርዱ ሁሉ እነዚያ በደለኞቹ ማለት እነርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 46, '46. በነብያቶች ፈለግ ላይ የመርየምን ልጅ ዒሳን በስተፊቱ ያለውን ተውራትን አረጋጋጭ ሲሆን አስከተልን:: ኢንጅልም በውስጡ ቀጥተኛ መመሪያና ብርሃን ያለበት በስተፊቱ ያለውን ተውራትን የሚያረጋግጥ ለጥንቁቆቹም መሪና ገሳጭ ሲሆን ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 47, '47. የኢንጂል ባለቤቶች በውስጡ አላህ ባወረደው ህግ ይፍረዱ:: አላህ ባወረደው የማይፈርዱ አመጸኞች ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ! )ከበፊቱ የነበረውን መጽሐፍ አረጋጋጭና በእርሱ ላይ ተጠባባቂ አድርገን ባንተ ላይ ቁርኣንን አወረድን:: እናም በመካከላቸው አላህ ባወረደው ህግ ፍረድ:: እውነቱ ከመጣልህ በኋላ ዝንባሌዎቻቸውን አትከተል:: ለሁላችሁም ህግንና መንገድን አደረግን:: አላህ በፈለገ ኖሮ አንድ ሕዝብ ባደረጋችሁ ነበር:: ግን በሰጣችሁ ሕግጋት ሊሞክራችሁ ነው ለእያንዳንዳችሁ መንገዶችን ያደረገው:: እናም በጎ ስራዎችን ለመስራት ተሽቀዳደሙ:: የሁላችሁም መመለሻ ወደ አላህ ብቻ ነው:: ከዚያ በእርሱ ትለያዩበት የነበራችሁትን ነገር እውነታ ይነግራችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) በመካከላቸው አላህ ባወረደው ህግ ፍረድ እንጂ ፈላጎቶቻቸውን አትከተል:: አላህ ወደ አንተ ካወረደው ከከፊሉ እንዳያሳስቱህ ተጠንቀቃቸው ማለትን አወረድን:: ከውሳኔው እምቢ ብለው ቢዞሩም አላህ የሚሻው በከፊሉ ኃጢአታቸው ሊቀጣቸው መሆኑን እወቅ:: ከሰዎቹ ብዙዎቹም አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 50, '50. ለመሆኑ የመሀይምነትን ፍርድ ይፈልጋሉን? ለሚያረጋግጡ ህዝቦች ሁሉ ከአላህ ይበልጥ ፍርዱ ያማረ ማን ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 51, '51. እናንተ ያመናችሁ ሆይ! አይሁድንና ክርስቲያኖችን ረዳቶች አታድርጓቸው:: ከፊላቸው ለከፊሉ ረዳቶች ናቸውና:: ከናንተ ውስጥ እነርሱን ረዳቶቹ (ወዳጆቹ) የሚያደርጋቸው ከእነርሱው ነው:: አላህ አመጸኞችን ህዝቦች አያቀናም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያን በልቦቻቸው ውስጥ የንፍቅና በሽታ ያለባቸውን ሰዎች «የጊዜ መለዋወጥ እንዳያገኘን እንፈራለን።» የሚሉ ሆነው አይሁድን ለመርዳት ሲቻኮሉ ታያቸዋለህ:: አላህ ድል መቀዳጀትን ወይም ከእርሱ ዘንድ የሆነን ነገር ሊያመጣና ከዚያ በነፍሶቻቸው ውስጥ በደበቁት ነገር ተጸፃቾች እንደሚሆኑ ይከጀላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 53, '53. እነዚያ ያመኑት ሰዎች «እነዚያ ‹ከናንተ ጋር ነን› ብለው የጠነከረ መሀላቸውን በአላህ የማሉት እነዚህ ናቸውን?» ይላሉ:: ስራዎቻቸዉም ተበላሹ:: ከሳሪዎችም ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 54, '54. እናንተ ያመናችሁ ሆይ! ከእናንተ ውስጥ ከሃይማኖቱ ወደ ክህደት የሚመለስ ሁሉ አላህ በእርሱ ስፍራ የሚወዳቸውና የሚወዱትን በምዕምናን ላይ ትሁቶች፤ በከሓዲያን ላይ ሀያላን፤ የሆኑትንና በአላህ መንገድ የሚታገሉን የወቃሽንም ወቀሳ የማይፈሩ ህዝቦችን ያመጣል:: ይህ የአላህ ችሮታ ነው:: ለሚሻው ሰው ይሰጠዋል:: አላህ ችሮታው ሰፊ ሁሉንም አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 55, '55. (አማኞች ሆይ!) ረዳታችሁ አላህና መልዕክተኛው እንደዚሁም እነዚያ በአላህ ያመኑት ናቸው:: እነርሱ ማለት እነዚያ ሶላትን በደንቡ የሚሰግዱ እነርሱም (ለአምልኮ) የሚያጎነብሱ ሆነው ምጽዋትን የሚሰጡ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 56, '56. አላህን፤ መልዕክተኛውንና እንደዚሁ እነዚያ በአላህ ያመኑትን ሰዎች የሚወዳጅ (ከአላህ ጭፍሮች ይሆናል።) የአላህ ጭፍሮች ደግሞ አሸናፊዎቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 57, '57. እናንተ ያመናችሁ ሆይ! ከእነዚያ ከበፊታችሁ መጽሐፉን ከተሰጡትና ከእነዚያ ሃይማኖታችሁን መሳለቂያና መጫዎቻ ካደረጉት ከሓዲያን መካከል ወዳጆች አታድርጉ:: ትክክለኛ አማኞች እንደሆናችሁ አላህን ብቻ ፍሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 58, '58. (ሙስሊሞች ሆይ!) ወደ ሶላት በጠራችሁም ጊዜ ጥሪዋን መሳለቂያና መጫዎቻ ያደርጓታል። ይህ እነርሱ የማያስተውሉ ህዝቦች በመሆናቸው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 59, '59. (መልዕክተኛችን ሙሐመድ ሆይ!) «የመጽሐፉ ባለቤቶች ሆይ! በአላህና ወደኛ በተወረደው በፊትም በተወረደው ለማመናችን አብዛኞቻችሁም አመጸኞች ለመኾናችሁ እንጅ (ሌላን ነገር) ከኛ ትጠላላችሁን?» በላቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 60, '60. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ዘንድ ቅጣቱ ከዚህ ሁሉ የከፋን ነገር ልንገራችሁን?» በላቸው:: እርሱም «አላህ የረገማቸውና በእነርሱም ላይ የተቆጣባቸው ናቸው:: ከመካከላቸዉም ዝንጀሮዎችና ከርከሮዎች ያደረጋቸው ጣዖትንም የተገዙ ሰዎች ሃይማኖት ነው:: እነዚያ በጣም በከፋ ስፍራ ናቸው:: ከቀጥተኛዉም መንገድ በጣም የተሳሳቱ ናቸው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 61, '61. ( አማኞች ሆይ!) ወደ እናንተ በመጡ ጊዜ ከክህደት ጋር ሁነው የገቡ ከእርሱ (ከክህደቱ) ጋር ሁነውም የወጡ ሲሆኑ ልክ እንደናንተ «አምነናል» ይላሉ:: አላህ ያንን ይደብቁት የነበረውን ነገር ሁሉ ጠንቅቆ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 62, '62. (መልዕክተኛችን መሐመድ ሆይ!) ከእነርሱ ብዙዎቹን በኃጢአትና በበደል እርምንም የሆነ ለመብላት ሲጣደፉ ታያቸዋለህ:: ይሰሩት የነበረው በጣም ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 63, '63. ቀሳውስቱና ሊቃውንቱ ከኃጢአት ንግግራቸውና እርምን ከመብላታቸው አይከለክሏቸዉም ኖሯልን? ይሰሩት የነበረው በጣም ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 64, '64. አይሁድ «የአላህ እጅ የታሰረ ነው።» አሉ:: እጆቻቸው ይታሰሩ:: ባሉትም ነገር ይረገሙ። ይልቁንም የአላህ ሁለቱም እጆቹ የተዘረጉ ናቸው:: እንደፈለገ ይለግሳል:: (መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህ ወደ አንተ የተወረደው ቁርኣን ከእነርሱ መካከል ለብዙዎቹ ትዕቢትንና ክህደትን በእርግጥ ይጨምርባቸዋል:: በአይሁድ መካከል ጠብንና ጥላቻን እስከ ትንሳኤ ቀን ድረስ አደረግን:: ለጦር እሳትን ባቀጣጠሉ ቁጥር አላህ ያጠፋባቸዋል:: በምድር ውስጥ ለማበላሸት ይሮጣሉ:: አላህም አበላሾችን ሁሉ አይወድም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 65, '65. የመጽሐፉ ባለቤቶች ባመኑና በተጠነቀቁ ኖሮ ከእነርሱ ኃጢአቶቻቸውን በእርግጥ ባበስንና የመጠቀሚያ ገነቶችን በእርግጥ ባስገባናቸው ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 66, '66. እነርሱ ተውራትንና ኢንጂልን ከጌታቸው ወደ እነርሱ የተወረደውን መጽሐፍ በሰሩበት ኖሮ ከበላያቸውና ከእግሮቻቸው ስር በተመገቡ ነበር:: ከእነርሱ መካከል ትክክለኛ ህዝቦች አሉ:: ከእነርሱ መካከል ብዙዎቹ ግን የሚሰሩት ነገር ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 67, '67. (መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህ ወደ አንተ የተወረደውን ቁርኣን አድርስ:: ይህን ባትሰራ ግን የጌታህን መልዕክቱን አላደርስክም:: አላህም ከሰዎች (ተንኮል) ይጠብቅሃል:: አላህ ከሓዲያን ሕዝቦችን አያቀናም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ የመጽሐፍ ባለቤቶች ሆይ! ተውራትን፤ ኢንጂልን እና ከጌታችሁ ወደ እናንተ የተወረደውን ቁርኣንን እስከምትሰሩባቸው ድረስ በምንም ላይ አይደላችሁም።» በላቸው:: ከጌታህ ወደ አንተ የተወረደው ቁርኣን ከእነርሱ ብዙዎቹን ትዕቢትንና ክህደትን በእርግጥ ይጨምርባቸዋል:: በካሐዲያን ህዝቦች ላይ አትዘን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 69, '69. እነዚያ ያመኑ፤ አይሁዳዊያን፤ ሳቢያኖችና ክርስቲያኖች ከእነርሱ መካከል በአላህና በመጨረሻው ቀን በትክክል ያመኑና መልካምን የሰሩ ሁሉ በእነርሱ ላይ ስጋት የለባቸዉም። አይተክዙምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 70, '70. የኢስራኢል ልጆች የጠበቀ ቃል ኪዳን በእርግጥ ያዝንባቸው:: ወደ እነርሱም መልዕክተኞችን ላክን:: ነፍሶቻቸው በማትወደው ነገር መልዕክተኛ በመጣላቸው ቁጥር ከፊሉን አስተባበሉ:: ከፊሉንም ይገድላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 71, '71. በእነርሱ ላይ ፈተና አለመኖሩዋን ጠረጠሩምና ታወሩ ደነቆሩም:: ከዚያም አላህ ከእነርሱ ላይ ጸጸትን ተቀበለ:: ከዚያም ከእነርሱ ብዙዎቹ እንደገና ታወሩ ደነቆሩ:: አላህ የሚሰሩትን ሁሉ ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 72, '72. እነዚያ «አላህ እርሱ የመርየም ልጅ አልመሲህ ነው።» ያሉ በእርግጥ በአላህ ካዱ:: አል መሲህም አለ፡- «የኢስራኢል ልጆች ሆይ! ጌታዬንና ጌታችሁን አላህን ብቻ ተገዙ:: እነሆ በአላህ የሚያጋራ ሰው ሁሉ አላህ በእርሱ ላይ ገነትን በእርግጥ እርም አደረገ:: መኖሪያዉም እሳት ናት:: ለበዳዩችም ምንም ረዳቶች የሏቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 73, '73. እነዚያ «አላህ የሶስት ሶስተኛ ነው።» ያሉ በእርግጥ ሁሉ ካዱ። ከአምላክም አንድ አምላክ ብቻ እንጂ ሌላ አምላክ የለም:: ከሚሉትም ነገር ካልተከለከሉ እነዚያን የካዱትን ሁሉ አሳማሚ ቅጣት በእርግጥ ይነካቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 74, '74. ለመሆኑ እንደነዚህ አይነቶች ወደ አላህ አይመለሱምና ምህረትን አይለምኑትምን? አላህ መሀሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 75, '75. የመርየም ልጅ አልመሲህ ከበፊቱ ብዙ መልዕክተኞች የቀደሙት መልዕክተኛ እንጂ ሌላ አይደለም:: እናቱም በጣም እውነተኛ አማኝ ናት:: ሁለቱም ምግብን የሚበሉ ነበሩ:: (መልዕክተኛችን ሙሐመድ ሆይ!) አናቅጽን ለከሓዲያን እንዴት እንደምናብራራና ከዚያ እነርሱ ከእውነት እንዴት እንደሚመለሱ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 76, '76. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከአላህ ሌላ ለእናንተ መጉዳትንና መጥቀምን የማይችልን ትገዛላችሁን? አላህ እርሱ ሁሉን ሰሚና ሁሉን አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 77, '77. (መልዕክተኛች ሙሐመድ ሆይ!) «እናንተ የመጽሐፉ ባለቤቶች ሆይ! በሃይማኖታችሁ ከእውነት ውጭ ወሰንን አትለፉ:: ፊትም የተሳሳቱትንና ብዙዎቹን ህዝቦች ያሳሳቱትን ከቀጥተኛው መንገድም አሁን የተሳሳቱትን ህዝቦች ከንቱ ዝንባሌዎች (ስሜቶች) አትከተሉ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 78, '78. ከኢስራኢል ልጆች መካከል እነዚያ በአላህ የካዱት በዳውድና በመርየም ልጅ ዒሳ አንደበት ተረገሙ:: ይህም የአላህን ትዕዛዝ በመጣሳቸውና ወሰን የሚያልፉ በመሆናቸው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 79, '79. ይሰሩት ከነበረው መጥፎ ነገር አይከላከሉም ነበር:: ይሰሩት የነበረው ነገር በእርግጥ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 80, '80. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ ብዙዎቹን ከእነዚያ ከካዱት ጋር ሲወዳጁ ታያለህ:: በእነርሱ ላይ አላህ በመቆጣቱ ለእነርሱ ነፍሶቻቸው ያስቀደሙት ስራ በጣም ከፋ። እነርሱም በቅጣቱ ውስጥ ዘውታሪዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 81, '81. በአላህና በነቢዩ ወደርሱም በተወረደው ቁርኣን የሚያምኑ በኾኑ ኖሮ ወዳጆች አድርገው ባልያዙዋቸው ነበር፡፡ ግን ከእነርሱ ብዙዎቹ አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 82, '82. (መልዕክተኛችን ሙሐመድ ሆይ!) አይሁድና እነዚያ በአላህ ያጋሩት ለእነዚያ ላመኑት በጠላትነት ከሌሎች ሁሉ የበረቱ ሆነው ታገኛቸዋለህ:: ከእነርሱ መካከል እነዚያ «እኛ ክርስቲያኖች ነን።» ያሉትን ደግሞ ለእነዚያ ላመኑት በወዳጅነት ይበልጥ የቀረቧቸው ሆነው ታገኛቸዋለህ:: ይህም ከእነርሱ መካከል ቀሳውስትና መነኮሳት በመኖራቸውና እነርሱም የማይኮሩ በመሆናቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 83, '83. ወደ መልዕክተኛው የተወረደውን ቁርኣን በሰሙ ጊዜ እውነቱን ከመረዳታቸው የተነሳ ዓይኖቻቸው እንባን ሲያፈሱ ታያለህ:: ይላሉም: «ጌታችን ሆይ! ባንተ አምነናልና ከመስካሪዎች ጋር ፃፈን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 84, '84. «ጌታችን ከመልካም ሰሪዎች ጋር ገነትን ሊያስገባን የምንከጅል ስንሆን በአላህና ከእርሱ በመጣልን እውነት ሁሉ የማናምንበት ምን ምክንያት አለን?» (ይላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 85, '85. እናም ባሉት ምክንያት አላህ በስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶችን በውስጣቸው ዘወታሪዎች ሲሆኑ መነዳቸው። ይህም የበጎ ሰሪዎች ዋጋ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 86, '86. እነዚያም የካዱና በአናቅጻችን ያስተባበሉ ሁሉ የእሳት ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 87, '87. እናንተ ያመናችሁ ሆይ! አላህ ለእናንተ የፈቀደላችሁን ጣፋጮች በራሳችሁ ላይ እርም አታድርጉ:: ወሰንንም አትለፉ:: አላህ ወሰን አላፊዎችን ሁሉ አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 88, '88. (ሙስሊሞች ሆይ!) አላህ ከሰጣችሁ ሲሳይ የተፈቀደ ጥሩ ሲሆን ብሉ። ያንን ያመናችሁበት ጌታችሁን አላህንም ፍሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 89, '89. (ሙስሊሞች ሆይ!) አላህ ከመሀሎቻችሁ መካከል በውድቁ አይዛችሁም:: ባሰባችሁበት መሀላ ግን ይይዛችኋል:: እናም መሀላዎችን ባፈረሳችሁ ጊዜ ማሰረዣው ቤተሰቦቻችሁን ከምትመግቡት ከመካከለኛው ምግብ ለአስር ሚስኪኖች ማብላት ወይም እነርሱን ማልበስ ወይም የአንዲትን ባሪያ ጫንቃን ነፃ ማውጣት ነው:: ከተባሉት አንዱንም ያለገኘ ሶስት ቀናትን መፆም ብቻ ነው:: ይህ በማላችሁና መሀላዎቻችሁን ባፈረሳችሁ ጊዜ ማሰረዣው ነው:: መሀላዎቻችሁንም ጠብቁ:: ልክ እንደዚሁ አላህ ለእናንተ አናቅጽን ያብራራል:: እናንተም ልታመሰግኑት ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 90, '90. እናንተ ያመናችሁ ሆይ! የሚያሰክር መጠጥ፤ የቁማር ጫዎታ፤ ጣዖታትን መገዛት እና አዝላምም ከሰይጣን ስራ የሆነ እና እርኩስ ተግባር ብቻ ናቸው። ትድኑ ዘንድም ራቁት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 91, '91. ሰይጣን የሚፈልገው በሚያሰክር መጠጥና በቁማር አማካኝነት በመካከላችሁ ጠብንና ጥላቻን ሊጭርና አላህን ከማውሳትና ከስግደት ሊያግዳችሁ ብቻ ነው:: ታዲያ እናንተ ከእነዚህ ነገሮች ተከልካዩች ናችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 92, '92. (ሙስሊሞች ሆይ!) አላህን ብቻ ታዘዙ:: መልዕክተኛውንም ታዘዙ:: ተጠንቀቁ:: ብትሸሹም በመልዕክተኛችን ላይ ያለበት በግልጽ መልዕክቱን ማድረስ ብቻ መሆኑን እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 93, '93. በእነዚያ በአላህ ባመኑትና በጎ ስራዎችን በሰሩት ላይ ከተጠነቀቁና ካመኑ መልካምን ከሰሩ፤ ከዚያም ከተጠነቀቁና ካመኑ፤ ከዚያም ከተጠነቀቁና ስራንም ካሳመሩ ከመከልከሉ በፊት በተመገቡት ነገር ኃጢአት የለባቸዉም። አላህ ስራቸውን አሳማሪዎቹን ሁሉ ይወዳልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 94, '94. እናንተ ያመናችሁ ሆይ! አላህ በሐጅ ጊዜ እጆቻችሁና ጦሮቻችሁ (በሚያገኙት) በሚያድኑት ታዳኝ አውሬ አላህን በሩቁ ሆኖ የሚፈራውን ሰው ሊገልጽ ይሞክራችኋል:: ከዚያ በኋላ ወሰንን ያለፈና ያደነ ሰው ሁሉ አሳማሚ ቅጣት አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 95, '95. እናንተ ያመናችሁ ሆይ! እናንተ በሐጅ ስራ ውስጥ ስትሆኑ አውሬን አትግደሉ:: ከናንተም እያወቀ አውሬን የገደለ ሰው ቅጣቱ ከናንተ መካከል ሁለት የፍትሀዊነት ባለቤቶች የሚፈርዱበትና ወደ ካዕባ ደራሽ መስዋዕት ሲሆን ከቤት እንሰሳዎች የገደለውን ነገር ብጤ መስጠት ወይም ሚስኪኖችን ማብላት ወይም የዚህን ልክ መፆም ማሰረዣው ነው:: ይህም የስራውን ከባድ ቅጣት እንዲቀምስ ነው:: ሳይከለከል በፊት ላለፈው ነገር አላህ ይቅርታ አደረገ:: ወደ ጥፋቱ የተመለሰን ሁሉ አላህ ይበቀለዋል:: አላህ አሸናፊና የብቀላ ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 96, '96. ሙስሊሞች ሆይ! የባህር እንሰሳና ምግቡ ለእናንተና ለመንገደኞች ሁሉ መጠቀሚያ ይሆን ዘንድ ተፈቀደላችሁ:: በሐጅ ላይ እስካላችሁ ድረስ ግን የየብስ አውሬ በእናንተ ላይ እርም ተደረገ:: ያንን ወደ እርሱ የምትሰበሰቡበትን አላህን ፍሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 97, '97. አላህ ያ የተከበረውን ቤት ካዕባን፤ ክልክል የሆነውን ወር፤ ወደ መካ የሚወስደውን መስዋዕቱንና ባለ ምልክቶቹን መንጋዎች ለሰዎች እምነት (ዋልታ) መቋቋሚያ አደረገ:: ይህ የሆነው አላህ በሰማያትና በምድር ያለውን ሁሉ ጠንቅቆ የሚያውቅ መሆኑንና ሁሉን ነገር አዋቂ መሆኑን እንድታውቁ ዘንድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 98, '98. (ሰዎች ሆይ!) አላህ ቅጣተ ብርቱም መሀሪና አዛኝም መሆኑን እወቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 99, '99. በመልዕክተኛው ላይ መልዕክቱን ማድረስ እንጂ ሌላ የለበትም:: አላህ የምትገልጹትንም ሆነ የምትደብቁትን ሁሉ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 100, '100. (መልዕክተኛችን ሙሐመድ ሆይ!) «የመጥፎው ነገር ብዛቱ ቢያስገርምህ እንኳ መጥፎና ጥሩው መቼም አይስተካከሉም። ባለ ልቦች ሆይ! ትድኑ ዘንድ አላህን ብቻ ፍሩ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 101, '101. እናንተ ያመናችሁ ሆይ! ለእናንተ ቢገለጹ ከሚያስከፏችሁ ነገሮች አትጠይቁ:: ቁርኣንም በሚወርድበት ጊዜ ከእርሷ ብትጠይቁ ለእናንተ ትገለፃለች:: ከእርሷ ግን አላህ ይቅርታ አደረገ:: አላህ መሀሪና ታጋሽ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 102, '102. ከናንተ በፊት የነበሩ ሕዝቦች ተመሳሳዩን ጠየቁ። ከዚያም (በትክክል ባለመፈጸማቸው ምክንያት) ከካሐዲያን ሆኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 103, '103. አላህ «በሒራ»፤ «ሳኢባ»፤ «ወሲላ»ና «ሐም» የተባሉ ነገሮች ከሸሪዓ አላደረገም:: ግን እነዚያ የካዱት ህዝቦች በአላህ ላይ ውሸትን ይቀጥፋሉ:: አብዛሀኞቻቸውም አያስተውሉም። (1)', '(1) እነዚህ አላህ መንገድ ያላደረገላቸው ሙሽሪኮች ለጣዖቶቻቸው የምሰጧቸው የእንስሳት ስሞች ናቸው።
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 104, '104. «አላህ ወደ አወረደውና ወደ መልዕክተኛው ኑ» በተባሉ ጊዜ «አባቶቻችንን ያገኝንበት መንገድ ይበቃናል።» ይላሉ:: አባቶቻቸው ምንም የማያውቁና ወደ ቀናው መንገድ የማይመሩ ቢሆኑም ይበቃቸዋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 105, '105. እናንተ ያመናችሁ ሆይ! ነፍሶቻችሁን (ማዳን ኃላፊነቱ) በራሳችሁ ላይ ነው። ራሳችሁን ወደቀናው መንገድ ከመራችሁ የሌሎች መሳሳት እናንተን አይጎዳችሁም:: የሁላችሁም መመለሻ ወደ አላህ ነው። እናም ትሰሩት የነበራችሁትን ሁሉ ይነግራችኋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 106, '106. እናንተ ያመናችሁ ሆይ! አንዳችሁ ሞት በመጣበት ጊዜ በኑዛዜ ወቅት በመካከላችሁ ለምስክርነት ከናንተ መካከል ሁለት የትክክለኛነት ባለቤቶች የሆኑ ሰዎች፤ ወይም በምድር ብትጓዙና የሞት አደጋ ብትነካችሁ ከሌሎቻችሁ የሆኑ ሁለት ሌሎች ሰዎች መመስከር ነው:: ብትጠራጠሩም ከአስር ሶላት በኋላ አቁሟቸውና «የሚመሰክርለት ሰው የዝምድና ባለቤት ቢሆንም እንኳን በእርሱ ዋጋን አንገዛም:: የአላህን ምስክርነት አንደብቅም:: ያን ጊዜማ ደብቀን ብንገኝ ከኃጢአተኞች ነን።» ብለው በአላህ ስም ይምላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 107, '107. ሆኖም እነርሱ ኃጢአት (በውሸት ምስክርነት) የተገቡ መሆናቸው ቢታወቅ ከእነዚያ ከሟቹ ቅርብ ዘመዶች ውርስ ከተገባቸው ሁለት ሌሎች ሰዎች በስፍራቸው በምስክሮች ስፍራ ይቆሙና «ምስክርነታችን ከእነርሱ ምስክርነት ይልቅ እውነት ነው ወሰንም አላለፍንም። ያን ጊዜ እኛ ከበዳዩቹ ነን።» ሲሉ በአላህ ይምላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 108, '108. ይህ (አሰራር) ምስክርነት በተገቢው ላይ ለማምጣታቸው ወይም ከመሀላዎቻቸው በኋላ የመሀላዎቹ ወደ ወራሾች መመለስን ለመፍራት በጣም የቀረበ ነው:: አላህን ብቻ ፍሩ:: እሱን ብቻ ስሙትም:: አላህ አመጸኛ ሕዝቦችን አይመራምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 109, '109. (መልዕክተኛችን ሆይ!) አላህ መልዕክተኞቹን ሰብስቦ እንዲህ ባለ ጊዜ የሚሆነውን አስታውስ፡- «ሕዝቦቻችሁ ምን መለሱላችሁ?» መልዕክተኞቹም: «እኛ እውቀቱ የለንም:: ሩቅ ሚስጥሮችን ሁሉ የምታውቀው አንተው ነህ።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 110, '110. አላህ እንዲህ በሚልበት ጊዜ የሚሆነውን አስታውስ፡- «የመርየም ልጅ ዒሳ ሆይ! ላንተና ለእናትህ የዋልኩላችሁን ውለታ አስታውስ:: በሩሀል ቁዱስ (በጅብሪል) አጠነከርኩህ:: በሕጻንነትህም አድገህም ሰዎችን ማናገር ቻልክ። መጽሐፉንና ጥበብን ተውራትንና ኢንጂልንም አስተማርኩህ:: ከጭቃም የወፍ ቅርጽ ዓይነት በፈቃዴ መሥራት ቻልክ:: በሷ ውስጥ ነፈህ:: በፈቃዴም እውነተኛ በራሪ ሆነች:: እውር ሆኖ የተወለደንና ለምጻምን በፈቃዴ መፈወስ ቻልክ:: ሟችንም በፈቃዴ አስነሳህ:: የኢስራኢልንም ልጆች ግልጽ መረጃ ባመጣህላቸው ጊዜ ሊያጠቁህ ሲያስቡ አቀብኩልህ:: ከመካከላቸዉም እነዚያ በአላህ የካዱት ‹ይህ ግልጽ ድግምት ነው› አሉ:: ይህን ሁሉ ውለታዬን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 111, '111. «ለሃዋሪያቱም፡- ‹በእኔና በመልዕክተኛዬ እመኑ።› የሚል ራዕይ በገለጽኩ ጊዜም የሆነውን አስታውስ። ‹አምነናል:: እኛ ሙስሊሞች ለመሆናችን ምስክር ሁን› አሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 112, '112. «ሃዋሪያቶቹም፡- ‹የመርየም ልጅ ዒሳ ሆይ! ጌታህ ከሰማይ ማዕድ ሊያወርድልን ይቻላልን?› ባሉ ጊዜ የሆነውን አስታውስ። ዒሳም፡-‹ትክክለኛ አማኞች ከሆናችሁ አላህን ብቻ ፍሩ።› አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 113, '113. «‹ከእርሱ ልንመገብ ልቦቻችንም እርካታን ይጎናጸፉ ዘንድ ብቻ ነው ይህን የጠየቅነው:: የነገርከንም ተጨባጭ እውነት መሆኑን ልናውቅና ለዚህም መስካሪዎች ለመሆን ፈልገን ነው።› አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 114, '114. «የመርየም ልጅ ዒሳም፡- ‹ጌታችን አላህ ሆይ! ከሰማይ ማዕድን አውርድልን ለእኛ ለመጀመሪያዎቻችንና ለመጭዎቹም ትውልዶች በዓል (የደስታ እለት) ካንተ የሆነችም ተዐምር ትሆንልን ዘንድ :: ሲሳይንም ለግሰን:: አንተ ከለጋሾች ሁሉ የበለጥክ ለጋሽ ነህና› አለ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 115, '115. አላህም፡- «ማዕዷን አወርድላችኋለሁ:: ግና ከዚህ ተአምር በኋላ ከመካከላችሁ በእኔ ለካዱት ሁሉ በዓለማት ላይ ማንንም የማልቀጣውን አስከፊ ቅጣት እቀጣቸዋለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 116, '116. (መልዕክተኛች ሙሐመድ ሆይ!) አላህ፡- «የመርየም ልጅ ዒሳ ሆይ! ሰዎችን ‹እኔንና እናቴን ከአላህ ውጭ ሁለት አማልዕክት አድርጋችሁ ያዙን።› ብለሃልን?» በሚለው ጊዜ የሚሆነውን አስታውስ:: ዒሳም አለ፡- «ክብርና ልዕልና ላንተ ብቻ ይሁን! ለእኔ ልለው የማይገባኝን ነገር ማለቴ ፈጽሞ አግባብ አይደለም:: ይህን ተናግሬ ከሆነም ታውቀዋለህ:: አንተ በውስጤ ያለውን ሁሉ ጠንቅቀህ ታውቃለህ:: እኔ ግን ባንተ ውስጥ ያለውን አላውቅም:: አንተ ሩቅ ሚስጥራትን ሁሉ አዋቂ ነህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 117, '117. «የነገርኳቸው ያን ያዘዝከኝን ብቻ ነው:: ‹የእኔም የእናንተም ጌታ የሆነውን አላህን ብቻ አምልኩ ነው› ያልኳቸው:: በመካከላቸው በነበርኩበት ወቅት ስለ እነርሱ መስካሪ ነበርኩ:: እንዳርግ ካደረግከኝ በኋላ ግን የእነርሱ ጠባቂና ተቆጣጣሪ አንተው ብቻ ነበርክ:: አንተ በሁሉም ነገር ላይ መስካሪ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 118, '118. «ብትቀጣቸው እነርሱ የአንተው ባሮችህ ናቸው:: ብትምራቸው ደግሞ አንተ ኃያልና ጥበበኛ ነህ።» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 119, '119. አላህም እንዲህ ይላል፡- «ይህ ቀን እውነቱ ለእውነተኞች የሚጠቅምበት ቀን ነው::» ለእውነተኞች ከስሮቿ ወንዞች የሚፈሱባት ገነት ተዘጋጅቶላቸዋል:: በውስጧም ለዝንተ ዓለም ይኖራሉ:: አላህ በእነርሱ ተግባር ተደስቷል:: እነርሱም በእርሱ ችሮታ ተደስተዋል:: ይህ ታላቅ ስኬት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (5, 120, '120. የሰማያት የምድርና በውስጣቸው ያሉ ፍጡራን ሁሉ ባለቤትነት የአላህ ብቻ ነው:: እርሱ በሁሉም ነገር ላይ ቻይ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 1, '1.ምስጋና ሁሉ ለዚያ ሰማያትንና ምድርን ለፈጠረ ጨለማዎችንና ብርሃንን ላደረገው ለአላህ የተገባ ነው:: ከዚያም እነዚያ በእርሱ የካዱ ሁሉ ጣዖታትን ከጌታቸው ጋር ያስተካክላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 2, '2. (ሰዎች ሆይ!) እርሱ ያ ከጭቃ የፈጠራችሁ ከዚያም የሞት ጊዜን የወሰነ ነው:: እርሱም ዘንድ ለትንሳኤ የተወሰነ ጊዜ አለ:: ከዚያም እናንተ በመቀስቀሳችሁ ትጠራጠራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 3, '3. እርሱም ያ በሰማያትም በምድርም ሊገዙት የሚገባው አላህ ነው:: (ሰዎች ሆይ!) ሚስጥራችሁንም ሆነ ግልፃችሁን ጠንቅቆ ያውቃል። የምትሰሩትን ሁሉ ጠንቅቆ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 4, '⒋ ከጌታቸው አናቅጽ አንዱም አይመጣላቸዉም ከእርሱ የሚሸሹ ቢሆኑ እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 5, '5. ቁርኣን በመጣላቸው ጊዜም በእርግጥ አስተባበሉ:: ግን የእዚያ በእርሱ ይሳለቁበት የነበሩት ነገር ዜናዎች ቅጣት ይመጣባቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 6, '6. ከበፊታቸው ከክፍለ ዘመናት ህዝቦች መካከል ብዙዎቹን ማጥፋታችንን አላዩምን? ለእናንተ ያላስመቸነውን ለእነርሱ በምድር ውስጥ አስመቸናቸው:: በእነርሱም ላይ ዝናብን የተከታተለ ሲሆን ላክን:: ወንዞችንም በስራቸው እንዲፈሱ አደረግን:: በኃጢአቶቻቸዉም ምክንያት አጠፋናቸው:: ከኋላቸዉም ሌሎችን ሰዎች በየክፍለ ዘመኑ አስገኘን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 7, '7. በእነርሱ ላይ በወረቀት የተፃፈን መጽሐፍ ባወረድንና በእጆቻቸው በነኩት ኖሮ እነዚያ ከሓዲያን «ይህ ግልጽ ድግምት እንጂ ሌላ አይደለም።» ባሉ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 8, '8. «በእርሱ (በሙሐመድ) ላይ መልአክ ለምን አይወረድለትም?» አሉ። ነገር ግን መላዕክን ባወረድንለትና (ባያምኑ ኖሮ) የጥፋታቸው ነገር በተፈረደ ነበር:: ከዚያም አይቆዩም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 9, '9. መልዕክተኛውን ከመላዕክት መካከል ባደረግነው ኖሮ ወንድ ሰው አድርገን በመላክ በእነርሱ ላይ የሚያመሳስሉትን ነገር ባመሳሰልንባቸው ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊት በነበሩ መልዕክተኞችም ላይ ተላግጧል:: እናም በእነዚያ ባላገጡት ላይ ያላገጡበት ውጤት በእነርሱ ላይ ተፈጽሟል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ! ከሓዲያንን) «በምድር ላይ ሂዱና የእነዚያን የአስተባባዮችን መጨረሻ እንዴት እንደነበረ ተመልከቱ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 12, '12. (መልዕክተኛችን ሙሐመድ ሆይ!) በላቸው: «በሰማያትና በምድር ያለው ሁሉ የማን ነው?» በላቸውም: «የአላህ ብቻ ነው። አላህ በራሱ ላይ እዝነትን ፃፈ:: በዚያ ጥርጥር በሌለበት በትንሳኤ ቀን ይሰበስባችኋል:: እነዚያ ነፍሶቻቸውን ያከሰሩ ማለት እነርሱው ናቸው። እናም አያምኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 13, '13. «በሌሊትም ሆነ በቀን ጸጥ ያለው ሁሉ የእርሱው ነው:: እርሱም ሰሚውና አዋቂው ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 14, '14. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰማያትንና ምድርን ፈጣሪ ከሆነው አላህ እርሱ ፍጡርን የሚመግብና ለራሱ የማይመገብ አምላክ ሲሆን ሌላን አምላክ እይዛለሁን?» በላቸው። «እኔ መጀመሪያ ትዕዛዝን ከተቀበለ ሰው እንድሆን ታዘዝኩ:: ‹ከአጋሪዎችም ፈጽሞ አትሁን።› ተብያለሁ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ በጌታዬ ላይ ባምጽ የዚያን የታላቁን ቀን ቅጣት እፈራለሁ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 16, '16. በዚያ ቀን ከእርሱ ላይ ቅጣት የሚመለስለት ሰው ሁሉ በእርግጥ አላህ አዘነለት:: ይህም ግልጽ ስኬት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ችግር ቢያደርስብህ ከእርሱ በስተቀር ሌላ ማንም አስወጋጅ የለም:: በጎ ነገርን ቢሰጥህም እርሱ በሁሉ ነገር ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 18, '18. እርሱ ከባሮቹ በላይ ሲሆን ሁሉን አሸናፊ ነው:: እርሱ ጥበበኛውና ውስጠ አዋቂው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 19, '19. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከምስክርነት ሁሉ ይበልጥ ታላቁ የትኛው ነው?» በላቸው። «አላህ፤ በእኔና በእናንተ መካከል መስካሪ ነው። ይህም ቁርኣን እናንተንና የደረሰውንም ሁሉ ላስፈራራበት ወደ እኔ ተወረደ:: ከአላህ ጋር ሌሎች አማልክት መኖራቸውን እናንተ ትመሰክራላቸሁን?» በላቸው:: «እኔ ግን ፈጽሞ በዚህ አልመሰክርም።» በላቸው:: «እርሱ አንድ አምላክ ብቻ ነው:: እኔም በአላህ ከምታጋሩት ሁሉ ንጹህ ነኝ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 20, '20. እነዚያ መጽሐፍን የሰጠናቸው አይሁድና ክርስቲያኖች ልክ ልጆቻቸውን እንደሚያውቁ ሁሉ ሙሐመድንም በትክክል ያውቁታል:: እነዚያ ነፍሶቻቸውን ያከሰሩት እነርሱ ፈጽሞ አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 21, '21. በአላህ ላይ ውሸትን ከቀጣጠፈ ወይም በአናቅጽ ካስተባበለ ይበልጥ በደለኛ ማን ነው? እነሆ በደለኞች አይድኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 22, '22. (መልዕክተኛችን ሙሐመድ ሆይ!) ሁላቸውንም በምንሰበሰብበትና ከዚያም ለእነዚያም በአላህ ላጋሩት፤ «‹እነዚያም ለአላህ ተጋሪዎች ናቸው› ብላችሁ ታስቧቸው የነበሩት ተጋሪዎቻችሁ የት ናቸው?» የምንልበትን ቀን (አስታውስ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 23, '23. ከዚያም የፊትና መልሳቸው «በጌታችን በአላህ ይሁንብን አጋሪዎች አልነበርንም።» ማለት እንጂ ሌላ አይሆንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) በነፍሶቻቸው ላይ እንዴት እንደዋሹና ይቀጣጥፉት የነበሩት ነገር ሁሉ ከእነርሱ እንዴት እንደተሰወረባቸው ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 25, '25. ከእነርሱ መካከል ወደ አንተ የሚያዳምጥ ሰው አለ:: በልቦቻቸው ላይ እንዳያውቁት ሽፋኖችን፤ በጆሮዎቻቸዉም ላይ እንዳይሰሙት ድንቁርናን አደረግን:: ተዐምርን ሁሉ እንኳን ቢያዩ በእርሷ አያምኑም:: ወደ አንተ በመጡ ጊዜ የሚከራከሩህ ሆነው እነዚያ በአላህ የካዱ ሰዎች «ይህ ቁርኣን የቀድሞዎቹ ሰዎች ጹሑፍ ተረቶች ስብስብ እንጂ ሌላ አይደለም።» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 26, '26. እነርሱም ሰዎችን ከእርሱ ይከልክላሉ፤ ከእርሱም ይርቃሉ፤ በዚህም ተግባራቸው ነፍሶቻቸውን እንጂ ሌላን አያጠፉም:: ግን አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 27, '27. (መልዕክተኛችን ሙሐመድ ሆይ!) በእሳትም ላይ እንዲቆሙ በተደረጉ ጊዜ «ምን ነው ወደ ምድረ ዓለም በተመለስንና በጌታችን አናቅጽ ባላስተባበልን ከትክክለኛ አማኞችም ጋር በሆንን ዋ! ምኞታችን።» ባሉ ጊዜ ብታይ ኖሮ (የሚያስደነግጥህን ነገር ባየህ ነበር)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 28, '28. ይልቁንስ ከዚህ በፊት ይደብቁት የነበሩት ነገር ሁሉ ለእነርሱ ተገለጸ:: ወደ ምድረ ዓለም በተመለሱም ኖሮ ወደ ተከለከሉት ነገር በተመለሱ ነበር:: እነርሱ ሐሰተኞች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 29, '29. «ሕይወት ማለት ቅርቢቱ ሕይወታችን እንጂ ሌላ አይደለችም:: እኛም ፈጽሞ ተቀስቃሾች አይደለንም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) በጌታቸው ዘንድ ለምርመራ እንዲቆሙ በተደረጉ ጊዜ ብታይ ኖሮ (አስደንጋጭን ነገር ባየህ ነበር::) «ይህ እውነት አይደለምን?» ይላቸዋል:: እነርሱም «በጌታችን ይሁንብን እውነት ነው።» ይላሉ:: «እናም ትክዱት በነበራችሁት ምክንያት ቅጣቱን ቅመሱ።» ይላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 31, '31. እነዚያ ከአላህ ጋር መገናኘትን ያስተባበሉ ሁሉ በእርግጥ ከሰሩ:: ስዓቲቱም በድንገት በመጣችባቸው ጊዜ እነርሱ ኃጢአቶቻቸውን በጀርባዎቻቸው ላይ የሚሸከሙ ሲሆኑ «በምድረ ዓለም ባጓደልነው ነገር ላይ ዋ ጥፋታችን!» ይላሉ። አዋጅ ያ የሚሸከሙት ነገር ምንኛ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 32, '32. የቅርቢቱ ሕይወት ማለት ጨዋታና ላግጣ እንጂ ሌላ አይደለችም። የመጨረሻይቱ አገር (ገነት) ግን ለእነዚያ ለሚጠነቀቁት ሰዎች ሁሉ በጣም በላጭ ናት። አታውቁምን? (አትገነዘቡምን)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 33, '33. (መልዕክተኛችን ሙሐመድ ሆይ!) ያ የሚሉህ ነገር እንደሚያሳዝንህ በእርግጥ እናውቃለን:: እነርሱ በእርግጥ አያስተባብሉህም:: ግን በዳዮች በአላህ አናቅጽ ይክዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 34, '34. (መልዕክተኛችን ሙሐመድ ሆይ!) ከበፊትህ የነበሩት መልዕክተኞች ተስተባብለዋል:: በተስተባበሉበትም ነገርና በተሰቃዩት ላይ እርዳታችን እስከመጣላቸው ድረስ ታገሱ:: የአላህን ቃላት የሚለዉጥ የለም:: ከመልዕክተኞቹም ወሬ (የምትረጋጋበት) በእርግጥ መጣልህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 35, '35. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢስላምን መተዋቸው ባንተ ላይ ከባድ ቢሆንብህም በምድር ውስጥ ቀዳዳን ወይም በሰማይ ውስጥ መሰላልን ልትፈልግና ተዓምር ልታመጣላቸው ከቻልክ ሞክር:: አላህ በፈለገ ኖሮ ሁሉንም በቅኑ መንገድ ላይ በሰበሰባቸው ነበር:: ስለዚህ ከተሳሳቱት ሰዎች በፍጹም አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 36, '36. ጥሪን የሚቀበሉት እነዚያ የሚሰሙት ብቻ ናቸው:: ሙታንማ አላህ ይቀሰቅሳቸዋል:: ከዚያም ወደ እርሱ ብቻ ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 37, '37. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያን «ከጌታው በእርሱ ላይ ለምን ተአምር አልተወረደለትም?» አሉ:: «አላህ ተአምርን ለማውረድ ቻይ ነው:: ግን አብዛኞቻቸው ይህን እውነታ አያውቁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 38, '38. በምድር ላይ የሚሄድ ተንቀሳቃሽም ሆነ በሁለት ክንፎቹ የሚበር ሁሉ መሰሎቻችሁ ሕዝቦች እንጂ ሌላ አይደሉም:: በመጽሐፉ ውስጥ ምንንም ነገር አልተውንም:: ከዚያ ሁሉም ወደ ጌታቸው ይሰበሰባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 39, '39. እነዚያ በአናቅጻችን ያስተባበሉ ሁሉ እውነትን የማይሰሙ ደንቆሮዎች፤ ሐቅን የማይናገሩ ዲዳዎችና በጨለማዎች ውስጥ ያሉ ናቸው:: አላህ መጥመሙን የሚሻበትን ሰው ያጠመዋል:: ወደ ቀናው መንገድ መመራቱን የሚሻለትን ሰው ደግሞ በቀጥተኛው መንገድ ላይ ያደርገዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) «የአላህ ቅጣት ቢመጣባችሁ ወይም ትንሳኤ ብትመጣባችሁ ከአላህ ሌላ ትጠራላችሁን? እውነተኞች ከሆናችሁ (እስኪ ንገሩኝ።)» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 41, '41. «በፍፁም። እውነታው እርሱን ብቻ ትጠራላችሁ:: ቢሻ ወደ እርሱ የምትጠሩበትን ነገር ያስወግድላችኋልና የምታጋሩትንም ሁሉ ትረሱታላችሁ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊት ለነበሩት ሕዝቦች አያሌ መልዕክተኞችን በእርግጥ ላክን:: (ከዚያም እንቢተኛ ሆኑ::) ለእኛ ይተናነሱም ዘንድ በድህነትና በችግር ቀጣናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 43, '43. ታዲያ ቅጣታችን በመጣባቸው ጊዜ አይተናነሱም ኖሯልን? ነገር ግን ልቦቻቸው ደረቁ:: ይሰሩት የነበሩትንም መጥፎ ነገር ሰይጣን መልካም ነገር አስመስሎ አሳያቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 44, '44. በእርሱ ይገሰጹበት የነበረውን ነገር በዘነጉ ጊዜ ለእነርሱ የሁሉን ነገር ደጃፎችን ከፈትንላቸውና በኑሮ አስመቸናቸው:: በተሰጡትም ነገር በተደሰቱ ጊዜ በድንገት ያዝናቸው:: ወዲያውኑም እነርሱ ተስፋ ቆራጮች ሆኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 45, '45. የእነዚያ የበደሉት ሕዝቦች መጨረሻ ተቆረጠ:: ምስጋና ሁሉ ለዓለማት ጌታ ለሆነው ለአላህ ብቻ ይገባው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 46, '46.(መልዕክተኛችን ሙሐመድ ሆይ!) «እስቲ ንገሩኝ አላህ መስሚያችሁንና ማያዎቻችሁን ቢወሰድባችሁና በልቦቻችሁ ላይ ቢያትም ከአላህ ሌላ እርሱኑ የሚያመጣላችሁ አምላክ ማን ነው?» በላቸው:: አናቅጽን እንዴት እንደምናብራራና ከዚያም እነርሱ እንዴት መንገዱን እንደሚስቱ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) «እስቲ ንገሩኝ የአላህ ቅጣት ድንገት ወይም በይፋ ቢመጣባችሁ ከአመጸኛ ህዝቦች ሌላ ይጠፋልን?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 48, '48. መልዕክተኞችንም በመልካም አብሳሪና ከመጥፎ አስፈራሪ አድርገን እንጂ አንልክም:: እናም በእነርሱ ያመኑና በጎ ተግባርን የሰሩ ሁሉ ስጋት የለባቸዉም። አይተክዙምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 49, '49. እነዚያ አናቅጻችንን ያስተባበሉት ደግሞ በአመፃቸው ምክንያት ቅጣት ያገኛቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) «የአላህ ግምጃ ቤቶች እኔ ዘንድ ናቸው አልላችሁም:: ሩቅ ሚስጥርንም አላውቅም:: መልዓክ ነኝም አልልም:: ወደ እኔ የሚወርድልኝን መልዕክት ብቻ እንጂ ሌላን አልከተልም።» በላቸው። «እውርና የሚያይ ይስተካከላሉን? አታስተነትኑምን!» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ከአላህ ሌላ ወዳጅና አማላጅ የሌላቸው ሲሆኑ ወደ ጌታቸው መሰብሰብን የሚፈሩትን ሰዎች ይጠነቀቁ ዘንድ በእርሱ(ቁርኣን) አስፈራራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያን የጌታቸውን ፊት የሚሹ ሆነው በጧትና በማታ የሚጠሩትን አማኞች ከአጠገብህ አታባር:: እነርሱን መቆጣጠር ባንተ ላይ ምንም የለብህም:: አንተንም መቆጣጠር በእነርሱ ላይ ምንም የለባቸዉም::ታባርራቸውና ከበደለኞችም ትኾን ዘንድ (አታባር)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁም «ከመካከላችን አላህ በእነርሱ ላይ ችሮታውን የለገሳቸው እነዚህ ናቸውን?» ይሉ ዘንድ ከፊላቸውን በከፊሎች ሞከርን:: አላህ አመስጋኞቹን ከሁሉም በላይ አዋቂ አይደለምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 54, '54. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም በተዐምራታችን የሚያምኑት ሰዎች ሁሉ ወደ አንተ በመጡ ጊዜ «ሰላም በእናንተ ላይ ይሁን:: ጌታችን በራሱ ላይ እዝነትን ፃፈ:: እነሆ ከናንተ ውስጥ ስህተትን ስራ የሰራና ከዚያ ተጸጽቶ ወዲያውኑ ስራውን ላሳመረ እርሱ (አላህ) መሀሪና አዛኝ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 55, '55. ልክ እንደዚሁም እውነቱ እንዲገለጽና የወንጀለኞችም መንገድ ትብራራ ዘንድ አናቅጽን እንገልፃለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 56, '56. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ እነዚያን ከአላህ ሌላ የምትጠሯቸውን (ባዕድ አማልክት) ከመገዛት ተከልክያለሁ።» በላቸው። «ዝንባሌያችሁንም አልከተልም:: ያን ካደረኩኝ በእርግጥ ተሳሳትኩ:: እኔም ከተመሪዎቹ አይደለሁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 57, '57. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎች ሆይ! እኔ ከጌታዬ በመጣልኝ ግልጽ ማስረጃ ላይ ነኝ:: እናንተ ግን በእርሱ አስተባበላችሁ:: ያ የምትቻኮሉበት ቅጣት ውሳኔ እኔ ዘንድ አይደለም:: ፍርዱ ለአላህ ብቻ ነው:: አላህ እውነቱን ይፈርዳል:: እርሱም ከፈራጆች ሁሉ በላጭ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 58, '58. «ያ የምትቻኮሉበት ቅጣት እኔ ዘንድ በሆነ ኖሮ በእኔና በእናንተ መካከል ነገሩ (ቅጣታችሁ) በተፈጸመ ነበር:: አላህ በደለኞችን አዋቂ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 59, '59. የሩቅ ሚስጥሮች መክፈቻዎች ሁሉ እርሱ ዘንድ ብቻ ናቸው:: ከእርሱ በስተቀር ማንም አያውቃቸዉም:: በየብስና በባህር ውስጥ ያለውን ሁሉ ያውቃል:: አንዲትም ቅጠል አትረግፍም አላህ የሚያውቃት ብትሆን እንጂ:: በመሬት ጨለማዎች ውስጥ ቅንጣት እርጥብም ሆነ ደረቅ አንድም ነገር የለም ግልጽ በሆነው መጽሐፍ ውስጥ የተመዘገበ ቢሆን እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 60, '60. እርሱ (አላህ) ያ በሌሊት የሚያስተኛችሁ በቀን የሰራችሁትንም ሁሉ የሚያውቅ ከዚያም የተወሰነው ጊዜ ይፈጸም ዘንድ በቀን ውስጥ የሚቀሰቅሳችሁ ነው:: ከዚያም መመለሻችሁ ወደ እርሱ ብቻ ነው:: ከዚያም ትሰሩት የነበራችሁትን ነገር ሁሉ ይነግራችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 61, '61. እርሱ ከባሮቹ በላይ ሲሆን ሁሉን አሸናፊ ነው:: በእናንተ ላይም ተጠባባቂዎች መላዕክትን ይልካል:: አንዳችሁንም የሞት ሰዓቱ በመጣበት ጊዜ የሞት መልዕክተኞቻችን ትዕዛዛትን የማያጓድሉ ሲሆኑ ይገድሉታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 62, '62. ከዚያም እውነተኛ ወደ ሆነው ጌታቸው ወደ አላህ ይመለሳሉ:: (ሰዎች ሆይ!) አስትዉሉ! አዋጅ ፍርዱ ለእርሱ ብቻ ነው:: እርሱም ከተቆጣጣሪዎች ሁሉ ይበልጥ ፈጣን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 63, '63. (መልዕክተኛችን ሙሐመድ ሆይ!) «ያ ከየብስና ከባህር ጨለማዎች በግልጽና በሚስጢር ‹ከዚህ ቢያድነን ከአመስጋኞች እንሆናለን› ስትሉ የምትጠሩት ስትሆኑ የሚያድናችሁ ማን ነው?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 64, '64. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ከእርሷና ከጭንቅም ሁሉ ያድናችኋል:: ከዚያ እናንተ በእሱ ባዕድ አምላክን ታጋራላችሁ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) «እርሱ (አላህ) ከበላያችሁ ወይም ከእግሮቻችሁ በታች ቅጣትን በእናንተ ላይ ሊልክ ወይም የተለያዩ ሕዝቦች ስትሆኑ ሊያደባልቃችሁና ከፊላችሁን የከፊሉን ጭካኔ ሊያቀምስ ቻይ ነው።» በላቸው። ይገነዘቡ ዘንድ አናቅጽን እንዴት እንደምናብራራ ተመልከት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 66, '66. እርሱ(ቁርኣን) ከአላህ የመጣ እውነት ሲሆን ህዝቦችህ ግን አስተባበሉት:: (መልዕክተኛችን ሙሐመድ ሆይ!) «በናንተ ላይ ጠባቂ አይደለሁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 67, '67. ለየወሬ ሁሉ የሚደርስበት መፈጸሚያ ጊዜ አለው:: ወደ ፊትም በትክክል ታውቁታላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ አናቅጻችንን ለማስተባበል ወደ ክርክር የሚገቡትን ሰዎች በምታይ ጊዜ በሌላ ወሬ እስከሚገቡ ድረስ ተዋቸው:: ሰይጣንም መከልከልህን ቢያስረሳህና አብረሀቸው ሆነህ እንኳን ካስታወስክ በኋላ ከበደለኞች ሕዝቦች ጋር አትቀመጥ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 69, '69. እነዚያም በሚጠነቀቁት ህዝቦች ላይ በሂሳባቸው ምንም የለባቸዉም:: ግን ይጠነቀቁ ዘንድ መገሰጽ አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 70, '70. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያንም ሃይማኖታቸውን ጨዋታና ቀልድ አድርገው የያዙትንና ቅርቢቱ ሕይወት ያታለለቻቸውን ተዋቸው:: ነፍስ ሁሉ በሰራችው ስራ እንዳትጠፋ በእርሱ (በቁርአን) አስታውስ:: ለእርሷ ከአላህ ሌላ ወዳጅም ሆነ አማላጅ ማንም የላትም:: ፊዳ የተባለን ሁሉ ብትከፍል እንኳን ተቀባይነት የላትም:: እነዚያ በሰሩት ስራ የተጠፉት ናቸው:: በክህደታቸው ምክንያት ከፈላ ውሃ መጠጥና አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 71, '71. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከአላህ ሌላ የማይጠቅምንና የማይጎዳን እንገዛለን? አላህ በቀናው መንገድ ከመራን በኋላ የኋሊት እንመለሳለን? እንደዚያ በምድር ላይ የዋለለ ሲሆን ሰይጣናት አሳስተውት ለእርሱ ‹ወደ እኛ ና› እያሉ ወደ ቅን መንገድ የሚጠሩ ወዳጆች ቢኖሩትም (እንደማይከተላቸው) እንሆናለንን?» በላቸው:: «የአላህ መንገድ ቀጥተኛው መንገድ ነው:: ለዓለማት ጌታ ልንገዛም ታዘዝን።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 72, '72. «ሶላትን በትክክል ስገዱ አላህን ፍሩትም።» (ተብለን ታዘናል በላቸው።) እርሱ ወደ እርሱ የምትሰበሰቡበት አምላክ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 73, '73. እርሱም ያ ሰማያትንና ምድርን በትክክል የፈጠረ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) «ሁን» የሚልበትንና ወዲያዉም የሚሆንበትን ቀን አስታውስ:: ቃሉም እውነት ነው:: በቀንዱ በሚነፋበት ቀንም ንግስናው የእርሱ ብቻ ነው:: ሩቁንና ቅርቡን አዋቂ ነው:: እርሱም ጥበበኛውና ውስጠ አዋቂው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 74, '74. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢብራሂም ለአባቱ ለአዘር፡- «ጣኦትን አማልክት ታደርጋለህን? እኔ አንተንም ወገኖችህንም ግልጽ ጥመት ውስጥ ሆናችሁ አየኋችሁ።» ባለው ጊዜ የሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 75, '75. ልክ በዚህ አኳኋን ኢብራሂም ጽኑ እምነት ይኖረው ዘንድ የሰማያትንና የምድርን ግዛት አሳየነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 76, '76. ሌሊቱ በጽልመቱ በሸፈነው ጊዜ አንድ ኮከብ አየ። «ይህ ጌታዬ ነው» አለም:: ኮከቡ በጠለቀ ጊዜም፡- «ጠላቂዎችን አልወድም» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 77, '77. ጨረቃውን ደምቆ ባየ ጊዜም፡- «ይህ ጌታዬ ነው።» አለ:: ጨረቃውም በጠለቀ ጊዜ፡- «ጌታዬ ቅኑን ጎዳና ካልመራኝ መንገድ ከተሳሳቱ ሰዎች እሆናለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 78, '78. ጸሐይዋንም ደምቃ ጮራዋን ባየ ጊዜ፡- «ይህ ጌታዬ ነው። ይህ በጣም ትልቅ ነው።» አለ:: በጠለቀችም ጊዜ (አንዲህ) አለ፡- «ወገኖቼ ሆይ! እኔ ከምታጋሩት ሁሉ የጠራሁ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 79, '79. «እኔ ወደ ቀጥተኛው ሃይማኖት የተዘነበልኩ ስሆን ፊቴን ሰማያትንና ምድርን ወደ ፈጠረው አምላክ አላህ አዙሬያለሁ:: እናም ከአጋሪዎችም አይደለሁም።» (አለ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 80, '80. ወገኖቹም ተከራከሩት። (እርሱም) አላቸው: «በእርግጥ የመራኝ ስሆን በአላህ ጉዳይ ትከራከሩኛላችሁን? በእርሱም የምታጋሩትን ነገር አልፈራም:: ግን ጌታዬ ቢሻ (ያገኘኛል):: ጌታዬም ሁሉንም ነገር በእውቀቱ ሰፋ። አትገነዘቡምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 81, '81. «በእናንተ ላይ በእርሱ ማስረጃ ያላወረደበትን እናንተ ማጋራታችሁን የማትፈሩ ስትሆኑ የምታጋሩትን ጣዖት እንዴት እኔ እፈራለሁ?! የምታውቁም ብትሆኑ ከሁለቱ ክፍሎች ደህና ለመሆን ይበልጥ ተገቢው ማንኛው ነው?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 82, '82. እነዚያ በአላህ ያመኑና እምነታቸውን በእሱ በማጋራት ያልቀላቀሉ ሁሉ እነዚያ ለእነርሱ የተሟላ ደህንነት አለላቸው:: ወደ ቀናው መንገድ የተመሩም እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 83, '83. እነዚህ ማስረጃዎቻችን ናቸው:: ለኢብራሂም በህዝቦቹ ላይ አስረጅ እንዲሆኑ ሰጠነው:: የምንፈልገውን ሰው በደረጃዎች ከፍ እናደርጋለን:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ጥበበኛና አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 84, '84. ለእርሱም ልጁን ነብዩ ኢስሀቅንና የልጅ ልጁን ነብዩ የዕቆብን ሰጠነው:: ሁሉንም ወደ ቀናው መንገድ መራናቸው:: ኑህንም ከእነርሱ በፊት ወደ ቀናው መንገድ መራነው:: ከዘሮቹም ነብዩ ዳውድንም፤ ነብዩ ሱለይማንንም፤ ነብዩ አዩብንም፤ ነብዩ ዮሱፍንም፤ ነብዩ ሙሳንና፤ ነብዩ ሀሩንንም መራን:: በጎ ሰሪዎችን ሁሉ ልክ እንደዚሁ እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 85, '85. ዘከርያን፤ ያህያን፤ ዒሳን፤ ኢልያስንም ወደ ቀናው መንገድ መራን:: ሁሉም ከመልካሞቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 86, '86. ነብዩ ኢስማኢልንም፤ ነብዩ አል የሰዕንም፤ ነብዩ ዩኑስንም፤ ነብዩ ሉጥንም መራን:: ሁሉንም በዓለማት ላይ አበለጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 87, '87. ከአባቶቻቸዉም፣ ከዘሮቻቸዉም፣ ከወንድሞቻቸዉም ብዙዎችን መራን:: መረጥናቸዉም:: ወደ ቀጥታኛዉም መንገድ መራናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 88, '88. ይህ የአላህ መመሪያ ነው:: በእርሱ ከባሮቹ የሚሻውን ወደ ቀናው መንገድ ይመራበታል:: በአላህ ባጋሩም ኖሮ ይሰሩት የነበሩት መልካም ተግባር ሁሉ ከእነርሱ በታበሰባቸው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 89, '89. እነዚህ እነዚያ መጽሐፍትንና ጥበብን ነብይነትንም የሰጠናቸው ሰዎች ናቸው:: እነዚህ የመካ ከሓዲያን በእርሷ ቢክዱም በእርሷ የማይክዱ ሕዝቦችን አዘጋጅተንላታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 90, '90. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚህ ነብያት እነዚያ አላህ የመራቸው ናቸው:: ስለሆነም ፈለጋቸውን ተከተል:: «በእርሱ (በቁርኣን) ምንም ዋጋ አልጠይቃችሁም:: እርሱ ለዓለማት ግሳጼ ሊሆን የወረደ እንጂ ሌላ አይደለም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 91, '91. (ከሓዲያን) «አላህ በሰው ላይ ምንም አላወረደም።» ባሉ ጊዜ አላህን ተገቢውን ክብሩን አላከበሩትም:: (መልዕክተኛችን ሙሐመድ ሆይ!) እንዲህ በላቸው «ያንን ለሰዎች ብርሃንና ቅን መመሪያ ሆኖ ሙሳ ያመጣውን መጽሐፍ ክፍልፍሎች የምታደርጉት ስትሆኑ ማን አወረደው? (የወደዳችኋትን) ትገልጿታላችሁ ብዙውንም ትደብቃላችሁ፤ እናንተም ሆናችሁ አባቶቻችሁም ያላወቃችሁትን ተስተማራችሁ::» (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ አወረደው።» በላቸው:: ከዚያም በውሸታቸው ውስጥ የሚጫወቱ ሲሆኑ ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 92, '92. ይህ ያወረድነው ብሩክና ያንንም በፊት የነበረውን (መጽሐፍ) አረጋጋጭ መጽሐፍ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) የከተሞችንም እናት (መካን) ኗሪዎችን እና በዙሪያዋ ያሉትንም ሰዎች ልታስጠነቅቅበት አወረድነው:: እነዚያም በመጨረሻይቱ ዓለም የሚያምኑት ሰዎች እነርሱ በሶላታቸው የሚጠባበቁ ሲሆኑ በእርሱ ያምናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 93, '93. በአላህ ላይ ውሸትን ከቀጣጠፈ ወይም ወደ እርሱ ምንም ያልተወረደለት ሲሆን «ወደ እኔ ተወረደልኝ።» ካለና «አላህ ያወረደውን አይነት ማውረድም በእርግጥ እችላለሁ።» ካለ ይበልጥ እራሱን በዳይ ማን ነው? በደለኞችን በሞት መከራዎች ውስጥ በሆኑ ጊዜ መላዕክት እጆቻቸውን ዘርጊዎች ሆነው (ለቅጥጥብ) «ነፍሶቻችሁን አውጡ:: ከአላህ ላይ እውነትን ያልሆነን ነገር ትናገሩም የነበራችሁና በአናቅጽም ላይ ትኮሩ በነበራችሁት ምክንያት ዛሬ የውርደት ቅጣት ትመነዳላችሁ» በሚሏቸው ጊዜ ብታይ ኖሮ (አስደንጋጭን ነገር ባየህ ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 94, '94. «በመጀመሪያ ጊዜ ልክ እንደፈጠርናችሁ ሆናችሁ የሰጠናችሁን ሁሉ ከጀርባዎቻችሁ ኋላ የተዋችሁ ስትሆኑ ለየብቻችሁ ሆናችሁ በእርግጥ ወደ እኛ መጣችሁ:: እነዚያንም እነርሱ በእናንተ (ጉዳይ) ለአላህ ተጋሪዎቹ ናቸው:: የምትሏቸውን አማላጆቻችሁን ከናንተ ጋር አናይም:: ግንኙነታችሁ በእርግጥ ተቋረጠ:: ከናንተም ያ ያማልደናል የምትሉት ሁሉ ጠፋ» (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 95, '95. አላህ የፍሬና የዛፍ ቅንጣትን ፈልቃቂ ነው:: ከሙት ነገር ሕያውን ያወጣል:: ከሕያዉም ነገር ሙትን አውጭ ነው:: ይህ አላህ ጌታችሁ ነው:: ታዲያ እንዴት ከእውነት ትሸሻላችሁ (ትርቃላችሁ)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 96, '96. ጎሕን ከጽልመት ጨለማ ፈልቃቂ፤ ሌሊቱን ማረፊያ፤ ጸሐይንና ጨረቃን ለጊዜ ስሌት መጠቀሚያ ያደረገ አምላክ ነው:: ይህ የዚያ የአሸናፊውና የሁሉን አዋቂው አምላክ ውሳኔ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 97, '97. አላህ ያ በየብስና በባህር ጨለማዎች ውስጥ ራሳችሁን መምራት ትችሉ ዘንድ ከዋክብትን የፈጠረላችሁ አምላክ ነው:: ለሚያውቁ ሁሉ አናቅጽን በሚገባ አብራርተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 98, '98. (ሰዎች ሆይ! ) እርሱ (አላህ) ያ ከአንዲት ነፍስ ያስገኛችሁ አምላክ ነው:: በማሕጸን ውስጥ ማረፊያንና ምድር ላይም መኖሪያን አመቻቸላችሁ:: መገንዘብ ለሚችሉ ሁሉ አናቅጽን በሚገባ አብራርተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 99, '99. እርሱ (አላህ) ያ ከሰማይ ውሃን ያወረደ አምላክ ነው:: በእርሱም የሁሉንም ዓይነት እጽዋት አበቀልን:: የተደራረበን ቅንጣት የምናወጣበትን ለምለም አዝመራም ከርሱ አወጣን:: ከዘንባባ እንቡጥም የተቀራረቡ የሆኑ ዘለላዎችን አወጣን:: የወይን አትክልት ቦታዎችን አዘጋጀን:: ቅጠሎቻቸው የሚመሳሰሉ ፍሬዎቻቸው ግን የማይመሳሰሉ የሆኑትን የዘይቱን(ወይራ) እና የሩማን እጽዋትም ከሰማይ ባወረድነው ዝናብ አበቀልን:: (የሰው ልጆች ሆይ!) ፍሬውን ባፈራና በበሰለ ጊዜ እስቲ ተመልከቱት:: እጅግ አስደናቂ ሆኖ ታገኙታላችሁ:: በእነዚህ ክስተቶች ውስጥ በትክክል በአላህ ለሚያምኑ ሰዎች ሁሉ በርካታ ተአምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 100, '100. (ሰዎች) የፈጠራቸው አላህ ሲሆን አጋንንትን በመታዘዝ ለእርሱ ተጋሪዎች አደረጉ:: ወንዶች ልጆችና ሴቶች ልጆች አለው በማለት ያለ ዕውቀት በእርሱ ላይ ቀጠፉ:: አላህ ጥራት የተገባውና ከሚሉት ነገር ሁሉ የላቀ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 101, '101. እርሱ ሰማያትንና ምድርን ያለ ብጤ ፈጣሪ ነው:: ለእርሱም ሚስት የሌለው ሲሆን እንዴት ለእርሱ ልጅ ይኖረዋል? ሁሉንም ነገር ፈጠረ:: እርሱ ሁሉንም ነገር አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 102, '102. ይህ ጌታችሁ አላህ ነው:: ከእርሱ በስተቀር አምላክ የለም:: ሁሉን ነገር ፈጣሪ ነው:: ስለዚህ እርሱን ብቻ ተገዙት:: እርሱም በነገሩ ሁሉ ላይ ተጠባባቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 103, '103. አይኖች አያገኙትም:: እርሱ ግን አይኖችን ያያል:: እርሱም ሩህሩህና ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 104, '104. (ሰዎች ሆይ!) «ከጌታችሁ ዘንድ ብርሃኖች በእርግጥ መጡላችሁ:: እውነቱን የተመለከተ ሰው ጥቅሙ ለነፍሱ ብቻ ነው:: የታወረም ሰው ጉዳቱ በራሱ ላይ ብቻ ነው:: እኔ በእናንተ ላይ ጠባቂ አይደለሁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 105, '105. ልክ እንደዚሁ ገምግመው «መጽሐፍ አጥንተሃል» እንዲሉና ለሚያውቁ ህዝቦች ቁርኣንን እንድናብራራ አናቅጽን እንገልፃለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 106, '106. (መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህ ወደ አንተ የተወረደውን ብቻ ተከተል:: ከእርሱ በስተቀር ትክክለኛ አምላክ የለም:: አጋሪዎችንም ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 107, '107. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ በፈለገ ኖሮ እነርሱ ጣኦትን ባላጋሩ ነበር:: በእነርሱም ላይ ጠባቂ አላደረግንህም:: አንተም በእነርሱ ላይ ኃላፊ አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 108, '108. (ሙስሊሞች ሆይ!) እነዚያንም ከአላህ ሌላ የሚገዟቸውን ጣዖታትን አትስደቡ:: እነርሱም ድንበርን በማለፍ ያለ እውቀት አላህን ይሰድባሉና:: ልክ እንደዚሁ ለህዝቦች ሁሉ ስራቸውን ደግ አስመሰልንላቸው:: ከዚያም መመለሻቸው ወደ ጌታቸው ብቻ ነው:: ይሰሩት የነበሩትንም ሁሉ ይነግራቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 109, '109. (መልዕክተኛችን ሙሐመድ ሆይ!) ተዐምር ብትመጣላቸው በእርሷ በቁርጥ እንደሚያምኑ ጥብቅ መሀላዎቻቸውን በአላህ ማሉ:: «ተዓምራትም ሁሉ የሚከሰቱት ከአላህ ብቻ ነው። እርሷ በመጣች ጊዜም አለማመናቸውን ወይም ማመናቸውን ምን አሳወቃችሁ?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 110, '110. በመጀመሪያም ጊዜ በእርሱ እንዳላመኑ ሁሉ ልቦቻቸውንና አይኖቻቸውን እናገላብጣለን:: በጥመታቸዉም ውስጥ የሚዋልሉ ሲሆኑ እንተዋቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 111, '111. እኛ ወደ እነርሱ መላዕክትን ባወረድንም ኖሮ ሙታንን ባነጋገሩዋቸውና ነገሩን ሁሉ በቡድን በቡድን በእነርሱ ላይ በሰበሰብንም ኖሮ አላህ ካልሻ በስተቀር የሚያምኑ ባልሆኑ ነበር:: ግን አብዛኞቻቸው ይህንን እውነታ ይስታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 112, '112. (መልዕክተኛችን ሙሐመድ ሆይ!) እንደዚሁም ለነብያት ሁሉ ከሰውና ከጋኔን የሆኑን ሰይጣናት ጠላት አደረግን:: ከፊላቸው ወደ ከፊሉ ለማታለል የተዋበን ንግግር ይጥላሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በፈለገ ኖሮ ይህን ጸያፍ ተግባር ባልሰሩት ነበር:: ከቅጥፈታቸዉም ጋር ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 113, '113. ሊያታልሉ የሚጥሩትና የነዚያም በመጨረሻይቱ ህይወት የማያምኑት ሰዎች ልቦች ወደ እርሱ እንዲያዘነብሉ፤ እንዲወዱትና እነርሱ ይቀጥፉ የነበሩትንም እንዲቀጣጥፉ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 114, '114. (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱ ያ መጽሐፍን የተብራራ ሆኖ ወደ እናንተ ያወረደ ሲሆን ከአላህ ሌላ ዳኛን እፈልጋለሁን? በላቸው:: እነዚያ መጽሐፍን የሰጠናቸው ሰዎች ቁርኣን ከጌታህ ዘንድ በእውነት የተወረደ መሆኑን በትክክል ያውቃሉ:: እናም ከተጠራጣሪዎቹ አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 115, '115. (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህ ቃላት እውነተኛና ትክክለኛ ስትሆን ተፈጸመች:: ለቃላቱ ምንጊዜም ለዋጭ የለም:: እርሱ ሰሚውና አዋቂው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 116, '116. (መልዕክተኛችን ሙሐመድ ሆይ!) በምድር ካሉት መካከል አብዛኞቹን ብትከተል የአላህን መንገድ ያሳስቱሀል:: ጥርጣሬን እንጂ ሌላን አይከተሉምና:: እነርሱም የሚዋሹ እንጂ ሌላ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 117, '117. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ከመንገዱ የሚሳሳቱትን አዋቂ ነው:: እርሱም ተመሪዎቹን እንዲሁ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 118, '118. (ሰዎች ሆይ!) በአናቅጹም አማኞች እንደሆናችሁ ሲታረድ የአላህ ስም በእርሱ ላይ የተወሳበትን እንሰሳ ብቻ ብሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 119, '119. (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱን መብላት ካልተገደዳችሁበት በስተቀር በእናንተ እርም የተደረገውን ለእናተ አላህ በእርግጥ የዘረዘረ ሲሆን ከዚያ በእርሱ ላይ የአላህ ስም ከተጠራበት የማትበሉት ምን ምክንያት አላችሁ? ብዙዎቹም ያለ እውቀት በዝንባሌዎቻቸው ብቻ ያሳስታሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ወሰን አላፊዎቹን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 120, '120. የኃጢአትን ግልጹንም ድብቁንም ተው:: እነዚያ ኃጢአትን የሚሰሩ ሁሉ ይሰሩት በነበሩበት ነገር በእያንዳንዱ በእርግጥ ይመነዳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 121, '121. (ሙስሊሞች ሆይ!) በእርሱ ላይ የአላህ ስም ያልተወሳበትን አትብሉ:: እርሱም በእርግጥ አመጽ ነው:: ሰይጣናትም ወደ ወዳጆቻቸው በክትን በመብላት ይከራከሯችሁ ዘንድ ያሾከሹካሉ:: ታዲያ ብትታዘዟቸው በእርግጥ አጋሪዎች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 122, '122. ሙት የነበረና ከዚያም ህያው አድርገነው ለርሱም በሰዎች መካከል የሚሄድበትን ብርሃን ያደረግንለት በጨለማዎች ውስጥ ምንጊዜም የማይወጣ ሆኖ እንዳለው ብጤ ነውን? ልክ እንደዚሁ ለከሓዲያን ሁሉ ይሰሩት የነበሩት ነገር ተዋበላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 123, '123. ልክ እንደዚሁ በየከተማይቱ ውስጥ ታላላቅ ወንጀለኞቿ በውስጧ እንዲያሴሩ አደረግን። በነፍሶቻቸው ላይ እንጂ በሌላ ላይ አያሴሩም:: ግን ይህን እውነታ አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 124, '124. ተዓምር በመጣላቸውም ጊዜ «የአላህ መልዕክተኞች የተሰጡትን ብጤ እስክንሰጥ ድረስ በፍጹም አናምንም» አሉ:: አላህ መልዕክቱን የሚያደርግበትን ስፍራ አዋቂ ነው:: እነዚያን በአላህ ያመጹ ሰዎች ይዶልቱት በነበሩት ነገር አላህ ዘንድ ውርደትና ብርቱ ቅጣት ያገኛቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 125, '125. አላህ ሊመራው የሚሻውን ሁሉ ልቡን ለኢስላም ይከፍትለታል:: ሊያጠመው የሚሻውን ደግሞ ልቡን ጠባብና ተቸጋሪ ወደ ሰማይ ለመውጣት እንደሚታገል ያደርገዋል:: ልክ እንደዚሁ አላህ በእነዚያ በማያምኑት ሰዎች ላይ ርክሰትን ያደርጋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 126, '126. ይህ ያለህበት መንገድ ቀጥተኛ ሲሆን የጌታህ መንገድ ነው:: ለሚያስታውሱ ህዝቦች አናቅጽን እርግጥ ዘርዝረናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 127, '127. ለእነርሱም በጌታቸው ዘንድ የሰላም ሀገር አለላቸው። እርሱ ይሰሩት በነበሩት ምክንያትም ረዳታቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 128, '128. (መልዕክተኛችን ሙሐመድ ሆይ!) ሁሉንም በአንድ ቦታ በሚሰበስባቸው ቀን የሚሆነውን አስታውስ:: «የአጋንንት ቡድኖች ሆይ! ከሰዎች ቡድንን በማጥመም በእርግጥ አበዛችሁ።» ይባላሉ:: ከሰዎችም መካከል የሆኑት ወዳጆቻቸው «ጌታችን ሆይ! ከፊላችን በከፊሉ ተጠቀመ:: ያንን ለእኛ የወሰንክልንን ጊዜያችንን ደረስን።» ይላሉ:: «እሳቲቱ አላህ የሻው ጊዜ ሲቀር በውስጧ ዘወታሪዎች ስትሆኑ መኖሪያችሁ ናት።» ይላቸዋል:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ጥበበኛና አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 129, '129. ልክ እንደዚሁ አንዳንድ በደለኞችን ይሰሩት በነበሩት ጥፋት ምክንያት በከፊሎች ላይ እንሾማለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 130, '130. «የአጋንትና የሰዎች ቡድኖች ሆይ! አንቀፆቼን በእናንተ ላይ የሚተርኩ የዚህንም ቀናችሁን ቅጣት ማግኘትን የሚያስፈራሯችሁ ከናንተው የሆኑ መልዕክተኞች አልመጡላችሁም ነበርን?» ይባላሉ:: «በነፍሶቻችን ላይ መሰከርን።» ይላሉ። የዱንያ ህይወት አታለለቻቸው። በነፍሶቻቸው ላይ እነርሱ ከሓዲያን የነበሩ መሆናቸውንም በራሳቸው መሰከሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 131, '131. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ የሆነው ጌታህ ከተሞችን ባለቤቶችዋ (ማስጠንቀቂያ ያልመጣላቸው) ዘንጊዎች ሆነው ሳሉ በበደል ምክንያት አጥፊ ባለመሆኑ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 132, '132. (መልዕክተኛችን ሙሐመድ ሆይ!) ለሁሉም ከሰሩት (አንፃር) የተበላለጡ ደረጃዎች አሏቸው:: ጌታህም ከሚሰሩት ስራ ዝንጉ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 133, '133. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም በራሱ ተብቃቂ የእዝነት ባለቤት ነው:: ቢሻ ከምድረ ገጽ ያጠፋችኋል:: ከሌሎች ህዝቦችም ዘሮች እንዳስገኛችሁ ሁሉ ከበኋላችሁም የሚሻውን ሰው ይተካል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 134, '134. (ሰዎች ሆይ!) የምትቀጠሩት ሁሉ በእርግጥ መጪ ነው:: እናንተም የምታቅቱ አይደላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 135, '135. (መልዕክተኛችን ሙሐመድ ሆይ!) «ህዝቦቼ ሆይ! በችሎታችሁ ላይ ስሩ እኔ በችሎታዬ ላይ ሰሪ ነኝና:: ምስጉኒቱ ሀገር ገነት ለእርሱ የምትሆንለት ሰው ማን እንደሆነ ወደፊት ታውቃላችሁ:: እነሆ በደለኞች ሁሉ ምንጊዜም አይድኑም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 136, '136. አጋሪዎች ለአላህ ከፈጠራቸው ፍጡራን ከአዝመራውም ከግመል፣ ከከብት፣ ከፍየል፤ ከበጉም ድርሻን አደረጉለት:: በሀሳባቸዉም «ይህ የአላህ ነው፤ ይህ ደግሞ ለተጋሪዎቻችን ነው።» አሉ። ለተጋሪዎቻቸው የሆነው ነገር ወደ አላህ ምንጊዜም አይደርስም:: ለአላህ የሆነው ነገር ግን ወደ ተጋሪዎቹ ይደርሳል አሉ። የሚፈርዱት ፍርድ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 137, '137. ልክ እንደዚሁ ከአጋሪዎች ለብዙዎቹ ሊያጠፏቸውና ሀይማኖታቸውንም በነሱ ላይ ሊያቀላቅሉባቸው ዘንድ ልጆቻቸውን መግደልን ተጋሪዎቻቸው ጣኦታቱ አሳመሩላቸው:: አላህም በሻ ኖሮ (ይህን ጸያፍ ተግባር) ባልሰሩት ነበር:: እናም ከቅጥፈታቸው ጋር ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 138, '138. በሀሳባቸውም «እነዚህ እርም የሆኑ ለማዳ እንሰሳና አዝመራ ናቸው:: የምንሻለት ሰው እንጂ ሌላ ማንም አይበላቸዉም:: እነዚህ ደግሞ ጀርባዎቻቸው እርም የተደረገ ለማዳ እንሰሳ ናቸው:: አይጫኑም:: እነዚህ ሲታረዱ በእነርሱ ላይ የአላህን ስም የማይጠሩባቸዉም እንሳሳት ናቸው።» አሉ:: በእርሱ ላይ ለመቅጠፍ ነገሩን ወደ አላህ አስጠጉ:: ይቀጥፉት በነበሩት ነገር በእርግጥ ይቀጣቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 139, '139. «በእነዚህ እንስሳት ሆዶች ውስጥ ያለው ጽንሱ ሁሉ ለወንዶቻችን ብቻ በተለይ የተፈቀደ ነው:: በሚስቶቻችን ላይ ግን እርም የተደረገ ነው:: ሙት ሆኖ ቢወለድ ግን ወንዶቹም ሆነ ሴቶች በእርሱ ላይ ተጋሪዎች ናቸው።» አሉ:: ይህን በመቅጠፋቸው አላህ በእርግጥ ይቀጣቸዋል:: እርሱ ጥበበኛና አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 140, '140. እነዚያ ያለ እውቀት በሞኝነት ልጆቻቸውን የገደሉና አላህም የሰጣቸውን ሲሳይ በአላህ ላይ በመቅጠፍ በራሳቸው ላይ እርም ያደረጉ ሰዎች ሁሉ በእርግጥ ከሰሩ:: ተሳሳቱም:: ወደ ትክክለኛው መንገድም የተመሩ አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 141, '141. አላህ ያ (በሀረጉ) ዳስ የሚያደርግላቸውንና ዳስ የማያደርግላቸውን አትክልቶች የፈጠረ ነው:: የተምርን ዛፍ፣ አዝመራን፣ ፍሬዎቹ የተለያዩ ሲሆኑ ወይራንና ሩማንንም ቅጠላቸው ተመሳሳይና ጣዕማቸው የማይመሳሰል ሲሆኑ ፈጠረ:: (ሰዎች ሆይ!) ባፈራ ጊዜም ከፍሬው ብሉ:: ባጨዳዉም ቀን ተገቢውን (ዘካ) ለተገቢው ስጡለት:: አታባክኑም:: አላህ አባካኞችን አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 142, '142. ከለማዳ እንሰሳዎችም የሚጫኑትንም የማይጫኑትንም ፈጠረ:: (ሰዎች ሆይ!) አላህ ከሰጣችሁ ሲሳይ ብሉ:: የሰይጣንንም እርምጃዎች አትከተሉ:: እርሱ ለእናንተ ግልጽ ጠላት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 143, '143. ስምንትን ዓይነቶች፤ ከበግ ሁለትን (ወንድና ሴትን) ከፍየልም ሁለትን ፈጠረ:: «ከሁለቱም ክፍሎች አላህ ወንዶችን ብቻ እርም አደረገን? ወይንስ ሴቶችን ብቻ? ወይስ በእርሱ ላይ የሁለቱ ሴቶች ማህጸኖች ያጠቃለሉትን እርም አደረገ? እውነተኞች እንደሆናችሁ በእውቀት (በአስረጂ) ንገሩኝ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 144, '144. ከግመል ሁለትን፤ ከከብት ሁለትን ፈጠረ። «አላህ ከሁለቱ ወንዶችን ብቻ እርም አደረገን? ወይንስ ሴቶችን ብቻ? ወይስ የሁለቱ ሴቶች ማህጸኖች ያጠቃለሉትን? በእውነቱ አላህ በዚህ ነገር ባዘዛችሁ ጊዜ በቦታው ነበራችሁን? ሰዎችን ያለ እውቀት ሊያጠም በአላህ ላይ ውሸትን ከቀጠፈ ሰው ይበልጥ በደለኛ ማን ነው? አላህ በደለኞችን ህዝቦች ቅኑን መንገድ አይመራም::» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 145, '145. (መልዕክተኛችን ሙሐመድ ሆይ!) «ወደ እኔ በተወረደው ቁርኣን ውስጥ በክት ወይም የፈሰሰ ደም፤ ወይም የአሳማ ስጋ እርሱ እርኩስ ነውና፤ ወይም በአመጽ ከአላህ ስም ሌላ በእርሱ ላይ የተወሳበት ካልሆነ በስተቀር ተመጋቢ ላይ እርም የሆነ ነገር አላገኝም። አመጸኛና ወሰን ያለፈ ሳይሆን የተገደደ ሰው ከተወሱት ነገሮች ነፍስን የማዳን ያህል ቢበላ ኃጢአት የለበትም:: ጌታህ መሀሪና አዛኝ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 146, '146. በአይሁዳውያን ላይ የጥፍር ባለቤት እንስሳትን ሁሉ እርም አደረግንባቸው:: ከከብት፤ ከፍየልና ከበግ ሞራዎቻቸውን፤ ጀርባዎቻቸው ወይም አንጀቶቻቸው የተሸከሙት ወይም በአጥንት የተቀላቀሉ ስብ ሲቀር በእነርሱ ላይ እርም አደረግን:: በአመፃቸው ምክንያት ይህን በማድረግ ቀጣናቸው:: እኛም እውነተኞች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 147, '147. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢያስተባብሉልህ፡- «ጌታችሁ የሰፊ ችሮታ ባለቤት ነው:: ብርቱ ቅጣቱም ከአመጸኞች ህዝቦች ላይ አይመለስም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 148, '148. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያ በአላህ ያጋሩት ሰዎች አላህ በሻ ኖሮ እኛም ሆነ አባቶቻችን በአላህ ባላጋራንና አንዳችንም ነገር እርም ባላደረግን ነበር።» ይላሉ:: ልክ እነዚህ እንደ አስተባበሉህ ሁሉ እነዚያ ከበፊታቸው የነበሩ ሕዝቦችም ብርቱ ቅጣታችንን እስከ ቀመሱ ድረስ አስተባበሉ:: «ለእኛ ታስተምሩን ዘንድ ማጋራታችሁን ለመውደዱ እናንተ ዘንድ እውቀት አለን? ጥርጣሬን እንጂ ሌላ አትከተሉም:: እናንተ ዋሾዎች እንጂ ሌላ አይደላችሁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 149, '149. (መልዕክተኛችን ሙሐመድ ሆይ!) «የተሟላው ማስረጃ የአላህ ማስረጃ ብቻ ነው:: በፈለገ ኖሮ ሁላችሁንም ባቀናችሁ ነበር።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 150, '150. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያ አላህ ይህንን እርም ማድረጉን የሚመሰክሩትን ምስክሮቻችሁን እስቲ አምጡ።» በላቸው:: ቢመሰክሩም ከእነርሱ ጋር አትመስክር:: የእነዚያን በአናቅጻችን ያስተባበሉትን፤ የእነዚያንም በጌታቸው ሌላን የሚያስተካክሉ ሲሆኑ በመጨረሻይቱ ዓለም የማያምኑትን ሰዎች ዝንባሌዎች አትከተል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 151, '151. (መልዕክተኛችን ሙሐመድ ሆይ!) በላቸውም: «ኑ ጌታችሁ በእናተ ላይ እርም ያደረገውን ነገርና (በእርሱም ያዘዛችሁን) ላንብብላችሁ። እርሱም በአላህ ምንንም ነገር አታጋሩ:: ለወላጆቻችሁም በጎ ስራን ስሩ:: ልጆቻችሁንም ድህነትን ፈርታችሁ አትግደሉ:: እኛ እናንተንም ሆነ እነርሱን እንመግባችኋለንና:: ወደ ግልፅም ይሁን ድብቅ መጥፎ ስራ አትቅረቡ:: ያችንም አላህ እርም ያደረጋትን ነፍስ በሀቅ ቢሆን እንጂ አትግደሉ:: ይሀችሁ! ታውቁ ዘንድ በእርሱ አዘዛችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 152, '152. «የየቲምንም ገንዘብ አካለ መጠን እስኪድረስ ድረስ በመልካም ሁኔታ እንጂ አትቅረቡ:: ስፍርንና ሚዛንንም በትክከል ሙሉ:: ማንኛዋም ነፍስ የችሎታዋን ያህል እንጂ አናስገድድም:: በተናገራችሁ ጊዜ በዘመዶቻችሁ ላይ ቢሆንም እንኳ እውነትን በመናገር አስተካክሉ:: በአላህ ቃል ኪዳን ሙሉ:: ይሀችሁ ትገሰጹ ዘንድ አላህ በእርሱ አዘዛችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 153, '153. «ይህ ቀጥተኛው መንገዴ ነው:: እናም እርሱን ብቻ ተከተሉ:: የተለያዩ የጥመት መንገዶችንም አትከተሉ:: ከቀጥተኛው የርሱ መንገድ እናንተን ይለያይዋችኋልና:: ይሀችሁ ትጠነቀቁ ዘንድ አላህ በእርሱ አዘዛችሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 154, '154. ከዚያ ለሙሳ መፅሀፍ ሰጠነው መልካም በሰራው ላይ ጸጋችንን ለማሟላት፤ ነገርንም ሁሉ ለመዘርዘር፤ ለህዝቦቹም መሪና እዝነት ይሆን ዘንድ:: እነርሱ ከጌታቸው በመገናኘት ጉዳይ ሊያምኑ ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 155, '155. ይህ ያወረድነው የሆነ የተባረከ መጽሐፍ ነው:: እናም ተከተሉት፤ ይታዘንላችሁም ዘንድ ከክህደት ተጠንቀቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 156, '156. (ያወረድነውም) «መጽሐፍ የተወረደው ከፊታችን በነበሩ ሁለቱ ህዝቦች ላይ ብቻ ነው:: እኛም ከንባባቸው ዘንጊዎች ነበርን» እንዳትሉም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 157, '157. ወይም «እኛ መጽሐፍ በእኛ ላይ በተወረደ ኖሮ ከእነርሱ ይበልጥ የተመራን እንሆን ነበር።» እንዳትሉም ነው:: ስለዚህም ከጌታችሁ ግልጽ ማስረጃ፤ መመሪያ እና እዝነት በእርግጥ መጣላችሁ:: በአላህ አናቅጽ ካስተባበለና ከእርሱም ከዞረ ሰው ይበልጥ ራሱን በዳይ ማን ነው? እነዚያን አናቅጽን የሚተውትን ይተውት በነበሩት አንቀጽ ምክንያት ብርቱ ቅጣት በእርግጥ እንቀጣቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 158, '158. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያን መላዕክት ልትመጣላቸው ወይንም ጌታህ ሊመጣ ወይም ከጌታህ ምልክቶች ከፊሉ ሊመጣ እንጂ ሌላን ይጠባበቃሉን? ከጌታህ ምልክቶች ከፊሉ የሚመጣበት ቀን ግን ከዚያ በፊት አማኝ ያልነበረች ነፍስ ሁሉ ወይም አምና በእምነቷ በጎ ያልሰራች ነፍስ ሁሉ እምነቷ (ጸጸቷ) አይጠቅማትም:: «ያን ቀን እናንተም ተጠባበቁ እኛም ተጠባባቂዎች ነን።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 159, '159. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነዚያ ሃይማኖታቸውን ከለያዩና ቡድን ቡድን ከሆኑ (ሰዎች) ጋር አይደለህም:: ነገራቸው ወደ አላህ ብቻ ነው:: ከዚያም ይሰሩት የነበሩትን ሁሉ ይነግራቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 160, '160. መልካምን ስራ የሰራ ሁሉ ለእርሱ አስር እጥፍ ምንዳ አሉት:: ክፉ ስራን የሰራ ግን መሰሏን ብቻ እንጂ አይመነዳም:: እነርሱም ቅንጣት አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 161, '161. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ ጌታዬ ወደ ቀጥተኛው መንገድ፤ የተስተካከለ ወደሆነው ሃይማኖት የኢብራሂም መንገድ መራኝ:: እሱም ከአጋሪዎች አልነበረም።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 162, '162.(መልዕክተኛችን ሙሐመድ ሆይ!) በላቸው: «ስግደቴ፤ መገዛቴ (መስዋዕቴ)፣ ሕይወቴ፤ ሞቴ የሚገባው ለዓለማት ጌታ ለሆነው ለአላህ ብቻ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 163, '163. (መልዕክተኛችን ሙሐመድ ሆይ!) «ለእርሱ (ለአላህ) አጋር የለዉም:: በዚህ (አላህን ከተጋሪ በማጥራት) ታዘዝኩ:: እኔ የሙስሊሞች መጀመሪያ ነኝ።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 164, '164. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ የሁሉ ጌታ ሲሆን ከአላህ በስተቀር ሌላን ጌታ እፈልጋለሁን? ነፍስ ሁሉ በራሷ ላይ እንጂ ክፉን አትሰራም:: ወንጀለኛ ነፍስ ሁሉ የሌላይቱን ነፍስ ኃጢአት አትሸከምም:: ከዚያ መመለሻችሁ ወደ ጌታችሁ ነው:: ከዚያም ትለያዩበት የነበራችሁትን ሁሉ ይነግራችኋል» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (6, 165, '165. (ሰዎች ሆይ!) እርሱ (አላህ) ያ በምድር ላይ ምትኮች ያደረጋችሁ በሰጣችሁም ጸጋ ሊፈትናችሁ ከፊላችሁን በከፊሉ ላይ በደረጃዎች ከፍ ያደረገ ሃያል ጌታ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ቅጣቱ ፈጣን ነው:: አላህ እጅግ መሀሪና ሩህሩህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 1, '1. አሊፍ፤ ላም፤ ሚም፤ ሷድ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ልታስጠነቅቅበትና ለምእመናንም መገሰጫ እንዲሆን ወደ አንተ የተወረደ ቁርኣን ነው:: ስለዚህ ልብህ ውስጥ ከእርሱ ጭንቀት አይኑር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 3, '3. (ሰዎች ሆይ! ) ከጌታችሁ ወደ እናንተ የተወረደላችሁን መልዕክት ተከተሉ:: ከአላህ ሌላ ረዳቶችን አትከተሉ:: ጥቂትን ብቻ ትገሰፃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 4, '4. ከከተማ (ሰዎች) መካከል ልናጠፋቸው የፈለግነውንና ወዲያውኑ ብርቱ ቅጣታችን ሌሊት ወይም ቀን እነርሱ በቀትር አርፈው ሳሉ የመጣባቸው ብዙ ህዝቦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 5, '5. ቅጣታችንም በመጣባቸው ጊዜ ጸሎታቸው «እኛ በደለኞች ነበርን።» ከማለት በስተቀር ሌላ አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 6, '6. ከዚያ ወደ እነርሱ የተላከባቸውን ህዝቦችና መልዕክተኞቹንም እንጠይቃቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 7, '7. ከዚያም በእነርሱ ላይ የነበሩትን ሁሉ ከእውቀት ጋር እንተርክላቸዋለን:: ከእነርሱ የራቅን አልነበርንምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 8, '8. የዚያን ቀኑ ሚዛን ትክክለኛ ነው:: እናም እነዚያ ሚዛኖቻቸው የከበዱላቸውም እነዚያ እነርሱ የፈለጉትን ያገኙ እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 9, '9. እነዚያ ሚዛኖቻቸው የቀለሉባቸውም በአናቅጻችን ይክዱ በነበሩት ምክንያት ነፍሶቻቸውን ያከሰሩት ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 10, '10. (ሰዎች ሆይ! ) በምድር ላይ በእርግጥም አስመቸናችሁ:: በእርሷም ላይ ለእናንተ መኖሪያዎችን አደረግንላችሁ። ጥቂትን ብቻ ታመሰግናላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 11, '11. በእርግጥም ፈጠርናችሁ:: ከዚያም ቀረጽናችሁ:: ከዚያም ለመላዕክት « ለአደም ስገዱ።» አልን:: ወዲያዉም ሁሉም ሰገዱ:: ኢብሊስ ብቻ ሲቀር:: እሱማ ከሰጋጆቹ አልሆነም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 12, '12. አላህም «ዲያብሎስ ሆይ! ባዘዝኩህ ጊዜ ከመስገድ ምን ከለከለህ?» አለው:: ዲያብሎስም «እኔ ከእርሱ የበለጥኩ ነኝ:: እኔን ከእሳት ፈጠርከኝ እርሱን ግን ከጭቃ ፈጠርከው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 13, '13. (አላህም) «ከእርሷ ውረድ:: በእርሷ ውስጥ ልትኮራ አይገባህምና:: ውጣም:: አንተ ከወራዶቹ ነህና።» አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 14, '14. (ኢብሊስም): «እስከሚቀሰቀሱበት ቀን ድረስ አቆየኝ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 15, '15. አላህ «አንተ ከሚቆዩት ነህ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 16, '16. (ኢብሊስም) አለ: «ስላጠመምከኝም ለእነርሱ በቀጥተኛው መንገድ ላይ በእርግጥ እቀመጥባቸዋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 17, '17. «ከዚያም ከበስተፊቶቻቸው፤ ከየኋላቸዉም፤ ከየቀኞቻቸውና ከየግራዎቻቸዉም በእርግጥ እመጣባቸዋለሁ:: አብዛኞቻቸውንም አመስጋኞች ሆነው አታገኛቸዉም።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 18, '18. «የተጠላህ ብራሪ ስትሆን ከእርሷ ውጣ:: ከእነርሱ መካከልም አንተን ከተከተሉህ እና አንተንም ሁላችሁንም ገሀነምን በእርግጥ በእናንተ እሞላታለሁ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 19, '19. ‹‹አደም ሆይ! አንተና ሚስትህ በገነት ውስጥ ተቀመጡ:: በእርሷም ዉስጥ እንደፈለጋችሁ ተመገቡ:: ግን ይህችን ዛፍ አትቅረቡ:: ራሳቸውን ከሚበድሉት ትሆናላችሁና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 20, '20. ሰይጣንም ከሀፍረተ ገላቸው የተሸሸገውን ሊገልጽባቸው በድብቅ ንግግር ጎተጎታቸው። «ጌታችሁ እኮ መልአኮች እንዳትሆኑ ወይም ከዘላለም ኗዋሪዎቹ እንዳትሆኑ እንጂ ከዚህች ዛፍ አልከለከላችሁም።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 21, '21. «እኔ ለእናንተ በእርግጥ ከሚመክሯችሁ ነኝ።» ሲልም ማለላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 22, '22. በማታለልም አዋረዳቸው:: ከዛፊቱም በቀመሱ ጊዜ ሀፍረተ ገላቸው የሁለቱም ተገለጠባቸው:: ከገነት ቅጠልም በላያቸው ላይ ይደርቱ (ይለጥፉ) ጀመር:: ጌታቸዉም «ይህችን ዛፍ አልከለከልኳችሁም ነበርን? ሰይጣንም ለእናንተ ግልጽ ጠላት ነው አላልኳችሁም ነበርን?» ሲል ጠራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 23, '23. «ጌታችን ሆይ! ነፍሶቻችንን በደልን:: ባትምረንና ባታዝንልን በእርግጥ ከከሳሪዎቹ እንሆናለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 24, '24. (አላህም) «ከፊላችሁ ለከፊሉ ጠላት ሲሆን ከዚህ ዉጡ ወደ ምድር ውረዱ:: ለእናንተም በምድር ላይ እስከ ተወሰነ ጊዜ ድረስ መርጊያና መጠቀሚያ አላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 25, '25. «በእርሷ ላይ ትኖራላችሁ:: በእርሷም ላይ ትሞታላችሁ:: ከእርሷም ውስጥ ትወጣላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 26, '26. የአደም ልጆች ሆይ! ሀፍረተ ገላችሁን የሚሸሽግን ልብስና ጌጥን በእርግጥ በእናንተ ላይ አወረድን:: አላህን የመፍራትም ልብስም እርሱ የተሻለ ነው:: ይህ ከአላህ ተዓምራት ነው:: ይገሰጹ ዘንድ አወረደላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 27, '27. የአደም ልጆች ሆይ! ሰይጣን አባታችሁንና እናታችሁን ሀፍረተ ገላቸውን ሊያሳያቸው ልብሶቻቸውን ከእነርሱ የገፈፋቸው ሲሆን ከገነት እንዳወጣቸው ሁሉ እናንተንም አይሞክራችሁ:: እነሆ እርሱ ከነሰራዊቱ ከማታዩዋቸው ስፍራ ሁነው ያያቹሀልና: እኛ ሰይጣናትን ለእነዚያ ለማያምኑት ወዳጆች አድርገናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) መጥፎንም ሥራ በሠሩ ጊዜ፡- «በእርሷ ላይ አባቶቻችንን አገኘን:: አላህም በእርሷ አዞናል።» ይላሉ። «አላህ በመጥፎ ነገር አያዝም፤ በአላህ ላይ የማታውቁትን ትናገራላችሁን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታዬ በማስተካከል በፍትህ አዘዘ:: በየመስገጃ ቦታ ዘንድም ፊቶቻችሁን እርሱን ለመገዛት አስተካክሉ:: ሃይማኖትንም ለእርሱ ብቻ ፍጹም አድርጋችሁ አምልኩት:: መጀመሪያ እርሱ እንደፈጠራችሁ በመጨረሻም ወደ እርሱ ትመለሳላችሁና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 30, '30. ከፊሉን ወደ ቅን መንገድ መራ:: ከፊሎቹ ደግሞ በእነርሱ ላይ ጥመት ተረጋግጦባቸዋል:: እነርሱ ሰይጣናትን ከአላህ ሌላ ረዳቶች አድርገው ይዘዋልና:: እነርሱም ቅኑን መንገድ የተመሩ እንደሆኑ ያስባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 31, '31. የአደም ልጆች ሆይ! ሀፍረተ ገላችሁን የሚሸፍኑትን ጌጦቻችሁን በየመስገጃው ሁሉ ዘንድ ያዙ:: ብሉም ጠጡም:: ግን አታባክኑ:: እርሱ (አላህ) አባካኞችን አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 32, '32. (መልዕክተኛችን ሙሐመድ ሆይ!) «ያችን ለባሮች የፈጠራትን የአላህን ጌጥ ከሲሳይ ጥሩዎቹን እርም ያደረገ ማን ነው?» በላቸው። «እርሷ በትንሳኤ ቀን ለነዚያ በትክክል ላመኑት ብቻ ስትሆን በቅርቢቱ ህይወትም ተገቢያቸው ናት።» በላቸው:: ልክ እንደዚሁ ለሚያውቁ ህዝቦች ሁሉ አናቅጽን እናብራራለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 33, '33. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታዬ እርም ያደረገው የተገለጸም ሆነ የተደበቀን መጥፎ ስራን፣ ኃጢአትን፤ ያለ አግባብ መበደልንም፣ በእርሱም ማስረጃ ያላወረደበትን ጣኦት በአላህ ማጋራታችሁንና በአላህም ላይ የማታውቁትን መናገራችሁን ብቻ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 34, '34. ለህዝቦች ሁሉ የተወሰነ ጊዜ አላቸው። እናም ጊዜያቸው በደረሰ ወቅት አንዲትንም ሰዓት አይዘገዩም። ከጊዜያቱም አይቀድሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 35, '35. (የአደም ልጆች ሆይ!) ከናንተ መካከል አንቀፆቼን የሚያነቡላችሁ መልዕክተኞች ቢመጡላችሁ ከናንተ ክህደትን የተጠነቀቁና በጎንም ተግባር የሠሩ ሁሉ ምንም ፍርሀት የለባቸዉም:: ምንም አያዝኑምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 36, '36. እነዚያ በአናቅጻችን ያስተባበሉና ከእርሷ የኮሩ ሁሉ እነዚያ የእሳት ጓዶች ናቸው:: እነርሱም በእርሷ ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 37, '37. በአላህ ላይ ውሸትን ከቀጠፈ ወይም በአናቅጹ ካስተባበለ ይበልጥ በዳይ ማን ነው? እነዚያ ከተጻፈላቸው ከመጽሐፉ ውስጥ ሲሆን ድርሻቸው ያገኛቸዋል:: የሞት መልዕክተኞቻችንም የሚገድሏቸው ሆነው በመጡባቸው ጊዜ «ከአላህ ሌላ ትገዟቸው የነበራችሁት የት አሉ?» ይሏቸዋል:: «ከእኛ ተሰወሩብን» ይላሉ:: እነርሱም ከሓዲያን እንደነበሩ በነፍሶቻቸው ላይ ይመሰክራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 38, '38. «ከጋኔንና ከሰዉም ከናንተ በፊት በእርግጥ ካለፉት ህዝቦች ጋር ሆናችሁ እሳት ውስጥ ግቡ።» ይላቸዋል:: አንዲቱ ቡድን ህዝብ ወደ እሳት በገባች ቁጥር ያሳሳተቻትን ብጤዋን ቡድን ትረግማለች:: መላዉም በውስጧ ተሰብስበው በተገናኙ ጊዜ የኋለኛይቱ (ተከታዮች) ቡድን ለመጀመሪያይቱ (ለአስከታዮች) ቡድን፡- «ጌታችን ሆይ! እነዚህ አሳሳቱን ከእሳትም ስቃይ እጥፍን ስጣቸው።» ትላለች:: አላህም፡- «ለሁሉም እጥፍ አለው ግን አታውቁም።» ይላቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 39, '39. መጀመሪያይቱ ቡድንም ለኋለኛይቱ ቡድን «ለእናንተ በእኛ ላይ ምንም ብልጫ አልነበራችሁም ትላለች:: ትሠሩትም በነበራችሁት ቅጣቱን ቅመሱ።» ይሏቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 40, '40. እነዚያ አናቅጻችንን ያስተባበሉና ከእርሷም የኮሩ ሁሉ ለእነርሱ የሰማይ ደጃፎች አይከፈቱላቸዉም:: ግመል በመርፌ ቀዳዳ እስከሚገባ ድረስም ወደ ገነት አይገቡም:: ልክ እንደዚሁ አመጸኞችን እንቀጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 41, '41. ለእነርሱም በሥራቸው ምክንያት ከገሀነም እሳት ምንጣፍ ከበላያቸዉም የእሳት መሸፈኛዎች አሉባቸው:: ልክ እንደዚሁ በደለኞችን እንቀጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 42, '42. እነዚያ በአላህ ያመኑና መልካሞችን የሰሩ ማንኛውንም ነፍስ የችሎታዋን እንጂ አናስገድድም:: እነዚያ የገነት ሰዎች ናቸው:: እነርሱም በእርሷ ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 43, '43. በልቦቻቸው ውስጥ ያለውን ጥላቻም እናስወግዳለን:: ወንዞች በሥሮቻቸው ይፈሳሉ:: «ለዚያም ወደዚህ ላደረሰን ሥራ ለመራን ለአላህ ብቻ ምስጋና ይገባው:: አላህ ባልመራን ኖሮ ወደዚህ አንመራም ነበር:: የጌታችን መልዕክተኞች በእውነት ላይ ሲሆኑ መጥተውልናል።» ይላሉ:: «ይህ ገነት ትሠሩት በነበራችሁት እንድትወርሱት የተደረጋችሁት ነው።» በማለት ይጠራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 44, '44. የገነት ሰዎች የእሳት ሰዎችን «ጌታችን ቃል የገባልንን እውነት ሆኖ አገኘን እናንተስ ጌታችሁ የዛተባችሁን እውነት ሆኖ አገኛችሁትን?» ሲሉ ይጣራሉ:: የእሳት ሰዎችም «አዎን አገኘን» ይላሉ:: በመካከላቸዉም «የአላህ እርግማን በበደለኞች ላይ ይሁን» ሲል አዋጅ ነጋሪ ያውጃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 45, '45. በደለኞች ማለት እነዚያ ከአላህ መንገድ ሌሎችን ክፍሎች የሚከለክሉና የአላህ መንገድ እንድትጣመም የሚፈልጉ በመጨረሻዋ ዓለም ከሓዲያን የሆኑ ሰዎች ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 46, '46. በገነት ሰዎችና በገሀነም ሰዎች መካከል አዕራፍ የሚባል ከባድ መጋረጃ አለ:: በአዕራፍ ላይ ሁሉንም በምልክታቸው የሚያውቁ ሰዎች አሉ:: የገነትን ሰዎችን «ሰላም ለእናንተ ይሁን» በማለት ይጣራሉ:: የአዕራፍ ሰዎች ገነት መግባትን የሚከጅሉ ሲሆኑ ገና እንዲገቡ አልተደረጉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 47, '47. ዓይኖቻቸው ወደ እሳት ሰዎች አቅጣጫ በተዞሩ ጊዜም፡- «ጌታችን ሆይ! እባክህ ከበደለኞች ጋር አታድርገን።» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 48, '48. የአዕራፍ ሰዎች በምልክታቸው የሚያውቋቸውን ታላላቅ ሰዎች ይጠራሉ:: «ክምችታችሁና (ብዛታችሁና) ኩራታችሁ ምን ጠቀማችሁ?» ይሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 49, '49. «እነዚያ የአላህ ችሮታው አይደርሳቸዉም ብላችሁ የማላችሁት ወገኖች ናቸውን? ገነትን ግቡ:: (አሁን ግን) ፍርሃት የለባችሁም:: እናንተም አታዝኑም።» (ተባሉ ይሏቸዋል::)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 50, '50. የእሳት ሰዎች የገነት ሰዎችን «በእኛ ላይ ውሃ ወይም አላህ ከሰጣችሁ ሲሳይ እባካችሁ ጣሉልን (አፍስሱልን)።» ብለው ይጠሯቸዋል:: የገነት ሰዎችም «እነዚህ ሲሳዮች እኮ አላህ በከሓዲያን ላይ እርም አድርጓቸዋል።» ይሏቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 51, '51. ለእነዚያ ሃይማኖታቸውን መሳለቂያና መጫወቻ አድርገው የያዙና የቅርቢቱ ህይወት ያታለለቻቸው የዚህን ቀን መገናኘታቸውን እንደ ረሱና በተአምራታችን ይክዱ እንደ ነበሩ ሁሉ ዛሬ እኛም እንረሳቸዋለን (እንተዋቸዋለን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 52, '52. ከእውቀት ጋር የዘረዘርነው የሆነን መጽሐፍ ለሚያምኑ ህዝቦች መመሪያና እዝነት ሲሆን አመጣንላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 53, '53. የዛቻውን ፍጻሜዉን እንጂ ሌላ ይጠባበቃሉን? (አይጠባበቁም):: ፍጻሜው በሚመጣበት ቀን ግን እነዚያ ከመምጣቱ በፊት የረሱት ሰዎች «የጌታችን መልዕክተኞች በእውነት መጥተዋል። ለእኛስ ያማልዱን ዘንድ አማላጆች አሉን? ወይስ ከዚያ እንሠራው ከነበርነው የተለየ ስራ እንድንሰራ ዘንድ ዕድሉ ይሰጠናልን?» ይላሉ:: በእርግጥም ራሳቸውን ይከስራሉ:: ይቀጥፉት የነበረው ሁሉ ከንቱ ሆኖ ያገኙታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 54, '54. (ሰዎች ሆይ) ጌታችሁ አላህ ያ ሰማያትንና ምድርን በስድስት ቀናት ውስጥ የፈጠረና ከዚያም በዐርሹ ላይ ከፍ ያለ ነው። ቀኑንም በሌሊቱ ይሸፍነዋል:: ሁለቱም እርስ በእርስ በፍጥነት ይፈላለጋሉ:: ጸሐይ ጨረቃና ከዋክብት በትዕዛዙ የተገሩ ናቸው። አስተውሉ! መፍጠርም ማዘዝም የእርሱ (የአላህ) ነው:: የዓለማት ጌታ የሆነው አላህ ክብሩ ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 55, '55. ጌታችሁን ተናንሳችሁና ተዋርዳችሁ በድብቅ ለምኑት:: እርሱ ወሰን አላፊዎችን አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 56, '56. ምድር ከተበጀች በኋላ አታበላሿት:: አላህን ፈርታችሁና ከጅላችሁ ተገዙት:: የአላህ እዝነት ለበጎ አድራጊዎች ሁሉ ቅርብ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 57, '57. አላህ ያ ንፋሶችን ከዝናብ በፊት አብሳሪዎች አድርጎ የሚልክ ነው:: ከባዶችንም ደመናዎች በተሸከሙ ጊዜ ሙት ወደ ሆነ አገር እንነዳዋለን:: በእነርሱም ውሃን እናወርዳለን:: እናም ከፍሬዎች ሁሉ በእነርሱ እናወጣለን:: ልክ እንደዚሁ ሙታንን ከመቃብር እናስወጣለን:: ይህን የምንለው ትገነዘቡ ዘንድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 58, '58. መልካሙ አገር በጌታው ፈቃድ በቃዩ ያማረ ሆኖ ይወጣል። ያ መጥፎ የሆነው አገር ደግሞ በቃዩ ደካማ ሆኖ እንጂ አይወጣም:: ልክ እንደዚሁ ለሚያመሰግኑ ህዝቦች ተዓምራትን እናብራራለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 59, '59. ኑሕን ወደ ወገኖቹ ላክነው፡- «ወገኖቼ ሆይ! አላህን ብቻ ተገዙ:: ለእናንተ ከእርሱ ሌላ ምንም አምላክ የላችሁም:: እኔ በእናንተ ላይ የከባድ ቀንን ቅጣት እፈራላችኋለሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 60, '60. ከህዝቦቹ መካከል መሪዎቹ «እኛ በግልጽ ስህተት ውስጥ ሆነህ እናይሀለን።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 61, '61. ኑሕም አለ: «ወገኖቼ ሆይ! ምንም መሳሳት የለብኝም። ግን እኔ ከዓለማት ጌታ መልዕክተኛ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 62, '62. «የጌታዬን መልዕክቶች አደርስላችኋለሁ:: ለናንተም እመክራችኋለሁ:: ከአላህ በኩልም የማታውቁትን አውቃለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 63, '63. «አላህን ልትፈሩና ይታዘንላችሁም ዘንድ ከናንተው ጎሳ መካከል በሆነ ሰው ላይ እንዲያስጠነቅቃችሁ ከጌታችሁ ግሳጼ ስለመጣላችሁ ትደነቃላችሁን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 64, '64. ወዲያዉም አስተባበሉት:: እርሱንና እነዚያን ከእርሱ ጋር ያሉትንም በታንኳዋ ውስጥ አዳንናቸው:: እነዚያን በአናቅጻችን ያስተባበሉትን ግን በባህር አሰመጥናቸው:: እነርሱ ልበ እውራን ህዝቦች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 65, '65. ወደ ዓድ ህዝቦችም ወንድማቸውን ሁድን ላክን። «ወገኖቼ ሆይ! አላህን ብቻ ተገዙ:: ከእርሱ ሌላ ምንም አምላክ የላችሁም:: የአላህን ቅጣት አትፈሩምን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 66, '66. ከህዝቦቹ መካከል መሪዎቹም «እኛ በሞኝነት ላይ ሆነህ እናይሀለን:: እኛ ከውሸተኞቹ ነህ ብለንም እንጠረጥርሀለን።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 67, '67. እርሱም አላቸው፡- «ወገኖቼ ሆይ! እኔ ሞኝነት የለብኝም:: ግን እኔ ከአለማት ጌታ የተላኩ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 68, '68. «የጌታዬን መልዕክቶች አደርስላችኋለሁ። እኔም ለእናንተ ታማኝና መካሪ ነኝና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 69, '69. ያስጠነቅቃችሁ ዘንድ ከናንተው መካከል በሆነ ሰው ከጌታችሁ የሆነ ግሳጼ ስለመጣባችሁ ትደነቃላችሁን? ከኑህ ህዝቦች በኋላ ምትኮች ባደረጋችሁና በፍጥረትም ግዙፍነትን በጨመረላችሁ ጊዜ የሆነውን አስታውሱ:: የሻችሁትን ታገኙ ዘንድ የአላህን ጸጋዎች አስታውሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 70, '70. «አላህን አንድ አድርገን ብቻውን እንድንገዛውና አባቶቻችን ይገዟቸው የነበሩትን አማልክት እንድንተው መጣህብን? እውነተኛ ከሆንክ የምታስፈራራብንን ቅጣት እስቲ አምጣብን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 71, '71. «ከጌታችሁ የሆነ ቅጣትና ቁጣ በእናንተ ላይ በእውነት ተረጋገጠ:: እናንተና አባቶቻችሁ አማልክት ብላችሁ በጠራችኋቸው ስሞች አላህ በእነርሱ ምንም ማስረጃ ላላወረደባቸው ትከራከሩኛላችሁን? ተጠባበቁ እኔም ከናንተ ጋር ከተጠባባቂዎቹ ነኝና።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 72, '72. እርሱንና እነዚያን አብረውት የነበሩትን በችሮታችን ከቅጣት አዳናቸው::የእነዚያንም በተአምራታችን ያስተባበሉትንና አማኞች ያልነበሩትን መሠረት ቆረጥን፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 73, '73. ወደ ሰሙድ ህዝቦችም ወንድማቸውን ሷሊህን ላክን:: «ወገኖቼ ሆይ! አላህን ብቻ ተገዙ:: ከእርሱ ሌላ ለእናንተ ምንም አምላክ የላችሁም:: እውነተኛ ለመሆኔ ከጌታችሁ የሆነች ምልክት በእርግጥ መጥታላችኋለች:: ይህች ለእናንተ ተዓምር ስትሆን የአላህ ግመል ናትና ተዋት:: በአላህ ምድር ውስጥ እንደፈለገች ትብላ፤ ትጠጣም:: በክፉ አትንኳትም:: አሳማሚ ቅጣት ይይዛችኋልና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 74, '74. ከዓድ ህዝቦችም በኋላ ምትኮች ባደረጋችሁና በምድሪቱም ላይ ባስቀመጣችሁ ጊዜ የሆነውን አስታውሱ:: ከሜዳዎቿ ሸክላ ሕንጻዎችን ትገነባላችሁ:: ከተራራዎቿም ቤቶችን ትጠርባላችሁ:: ስለዚህ የአላህን ጸጋዎች አስታውሱ:: በምድርም ውስጥ አጥፊዎች ሆናችሁ አታበላሹ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 75, '75. ከወገኖቹ መካከል እነዚያ የኮሩት መሪዎች ለእነዚያ ለተሸነፉት በተለይም ከእነርሱ ላመኑት ክፍሎች: «ሷሊህ ከጌታው መላኩን ታውቃላችሁን?» አሏቸው:: እነርሱም «አዎን እናውቃለን:: እኛ እርሱ በተላከበት ነገር ሁሉ ትክክለኛ አማኞች ነን» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 76, '76. እነዚያ የኮሩት እኛ ግን «በዚያ ባመናችሁበት ነገር ከሓዲያን ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 77, '77. እናም ወዲያው ግመሊቱን ወጓትና ከጌታቸው ትዕዛዝ ወጡ:: «ሷሊህ ሆይ! ከመልዕክተኞቹ እንደሆንክ የምታስፈራራብንን ቅጣት እስቲ አምጣብን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 78, '78. ወዲያዉም የምድር መንቀጥቀጥ ያዘቻቸው:: በየቤቶቻቸዉም ውስጥ ተደፍተው አደሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 79, '79. ሷሊህም ከእነርሱ ዞረና «ወገኖቼ ሆይ! የጌታዬን መልዕክት በእርግጥ አደረስኩላችሁ:: ለእናንተም መከርኳችሁ:: ግን እናንተ መካሪዎችን አትወዱም።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 80, '80. (መልዕክተኛችን ሙሐመድ ሆይ!) ሉጥም ለሕዝቦቹ (እንዲህ) ባለ ጊዜ የሆነውን አስታውስ: «ከዓለማት ከናንተ በፊት አንድም ህዝብ ያልፈጸመውን አስቀያሚ ሥራ ትሠራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 81, '81. «እናንተ ከሴቶች ሌላ ወንዶችን በመከጀል ትመጡባቸዋላችሁ። ይልቁንም እናንተ ወሰንን አላፊ ሕዝቦች ናችሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 82, '82. የሕዝቦቹም መልስ «ሉጥንና ተከታዮቹን ከከተማችሁ አውጧቸው:: እነርሱ የሚጥራሩ ሰዎች ናቸው።» ከማለት ውጭ ሌላ አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 83, '83. ከዚያም እርሱንና ቤተሰቦቹን አዳንናቸው ሚስቱ ብቻ ስትቀር:: እርሷማ ለጥፋት ከቀሩት ሰዎች ሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 84, '84. በእነርሱ ላይ የእሳት ዝናብን አዘነብንባቸው:: (መልዕክተኛችን ሙሐመድ ሆይ!) የኃጢአተኞች መጨረሻ እንዴት እንደ ነበረ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 85, '85. ወደ መድየን ሕዝብም ወንድማቸውን ሹዐይብን ላክን። አላቸዉም: «ወገኖቼ ሆይ! አላህን ብቻ ተገዙ:: ከእርሱ በስተቀር ምንም አምላክ የላችሁም:: ከጌታችሁ ዘንድ ግልጽ ማስረጃ መጥቶላችኋል:: ስፍርንና ሚዛንን በትክክል ሙሉ:: የሰዎችንም ገንዘቦቻቸውን አታጉድሉባቸው:: ምድርንም ከተበጀች በኋላ አታበላሹ። አማኞች ከሆናችሁ ይህ ለእናንተ በጣም የተሻለ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 86, '86. «ሰዎችን የምታስፈራሩ፤ ከአላህም መንገድ በእርሱ ያመኑትን የምታግዱና የአላህን መንገድ መጥመሟንም የምትፈልጉ ሆናችሁ በየመንገዱ አትቀመጡ:: ጥቂቶች በነበራችሁና ባበዛችሁ ጊዜ የሆነውን አስታውሱ:: የአጥፊ ህዝቦች መጨረሻ እንዴት እንደነበረም ተመልከቱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 87, '87. «ከናንተም መካከል እኔ በተላኩበት ያመኑ ቡድኖችና ያላመኑ ቡድኖች ቢኖሩ በመካከላችን አላህ እስከሚፈርድ ታገሡ:: እርሱ ከፈራጆች ሁሉ እጅግ በላጭ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 88, '88. ከህዝቦቹ መካከል እነዚያ የኮሩት መሪዎችም፡- «ሹዐይብ ሆይ! አንተንና እነዚያን ካንተ ጋር ያመኑትን ከከተማችን እናወጣችኋለን ወይም ወደ ሃይማኖታችን መመለስ አለባችሁ።» አሉ:: እርሱም አላቸው: «የጠላንም ብንሆን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 89, '89. «አላህ ከእርሷ ከአዳንን በኋላ ወደ ሃይማኖታችሁ ብንመለስ በአላህ ላይ ውሸትን ቀጠፍን:: አላህ ጌታችን ካልሻም በስተቀር ወደ እርሷ ልንመለስ አይገባንም:: የጌታችን እውቀቱ ከሁሉ ሰፋ:: በአላህ ላይ ብቻ ተመካን:: ጌታችን ሆይ! በእኛና በወገኖቻችን መካከል ፍረድ:: አንተም ከፈራጆቹ ሁሉ በላጭ ነህና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 90, '90. ከወገኖቹም መካከል እነዚያ በአላህ የካዱት መሪዎች ለሕዝቡ «ሹዐይብን ብትከተሉ እናንተ ያኔ ከሳሪዎች ናችሁ።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 91, '91. ወዲያውኑ የምድር መንቀጥቀጥ ያዘቻቸው:: በየቤታቸው ውስጥ ተደፍተው አደሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 92, '92. እነዚያ ሹዓይብን ያስተባበሉት ሰዎች በእርሷ እንዳልነበሩባት ሆኑ:: እነዚያ ሹዓይብን ያስተባበሉት ከሳሪዎቹ እነርሱው ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 93, '93. ሹዐይብም ትቷቸው ከእነርሱ ዞረና «ወገኖቼ ሆይ! የጌታዬን መልእክቶች በእርግጥ አደረስኩላችሁ። ለእናንተም መከርኩ:: ታዲያ በከሃዲ ሰዎች ላይ እንዴት አዝናለሁ?» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 94, '94. በየትኛዉም ከተማ ለአላህ ይተናነሱ ዘንድ በድህነትና በችግር የያዝናቸው ብንሆን እንጂ አንድንም ነብይ አልላክንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 95, '95.ከዚያም እስከበዙና «አባቶቻችንን ድህነትና በሺታ በእርግጥ ነክቷቸዋል፡፡ (ይኽም የጊዜ ልማድ ነው)» እስካሉ ድረስ በመጥፎው ስፍራ በጎውን ለወጥን፡፡ ወዲያውም እነርሱ የማያውቁ ኾነው በድንገት ያዝናቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 96, '96. የከተሞቹ (ሰዎችም) በትክክል ባመኑና በተጠነቀቁ ኖሮ በእነርሱ ላይ ከሰማይና ከምድር በረከቶችን በከፈትንላቸው ነበር:: ግን አስተባበሉ:: ይሠሩት በነበሩትም ኃጢአት ምክኒያት ቀጣናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 97, '97. የከተሞቹ (ሰዎች) የተኙ ሆነው ቅጣታችን ሌሊት ሊመጣባቸው አይፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 98, '98. የከተሞቹ ሰዎችም የሚጫወቱ ሆነው ሳሉ ቅጣታችን ቀን በረፋዱ ሊመጣባቸው አይፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 99, '99. የአላህን ማዘናጋት አይፈሩምን? ተማመኑን? የአላህን ማዘናጋት ከከሳሪዎች ሕዝቦች በስተቀር ማንም የሚተማመን የለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 100, '100. ለእነዚያ ምድርን ከባለቤቶቿ ጥፋት በኋላ ለሚወርሱት ብንሻ ኖሮ በኃጢአቶቻቸው ምክኒያት የምንቀጣቸው መሆናችን አልተገለጸላቸዉምን? በልቦቻቸውም ላይ እናትማለን:: ስለዚህም እነርሱ አይሰሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 101, '101. እነዚህ ከተሞች ከወሬዎቻቸው ባንተ ላይ እንተርካለን:: መልዕክተኞቻቸዉም በግልጽ ተዓምራት መጥተውላቸዋል:: ከመምጣታቸው በፊት ባስተባበሉትም ነገር የሚያምኑ አልሆነም:: ልክ እንደዚሁ አላህ በከሓዲያን ልቦች ላይ ያትማል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 102, '102. ለብዙዎቻቸው በቃል ኪዳናቸው መሙላትን አላገኘንም:: ይልቁንም አብዛኞቻቸውን አመጸኞች ሆነው አገኘናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 103, '103. ከዚያም ከበኋላቸው ነብዩ ሙሳን ወደ ፈርዖንና ወደ መማክርቶቹ ተዓምራታችንን አስይዘን ላክነው:: በእርሷም ካዱ:: (መልዕክተኛችን ሙሐመድ ሆይ!) የአጥፊዎች መጨረሻ እንዴት እንደነበረ እስቲ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 104, '104. ሙሳም አለ፡- «ፈርዖን! ሆይ እኔ ከዓለማት ጌታ የተላኩ መልክተኛ ነኝ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 105, '105. «በአላህ ላይ ከእውነት በስተቀር አለመናገር ተገቢዬ ነው:: ከጌታችሁ ተዓምር ይዤ መጥቻለሁና የኢስራኢል ልጆችን ከእኔ ጋር ልቀቅ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 106, '106. ፈርዖንም፡ «በተዓምር የመጣህ ከሆንክና ከእውነተኞቹ ከሆንክ እስቲ አምጣት።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 107, '107. ሙሳም ዘንጉን ምድር ላይ ጣለ:: እርሷም ወዲያውኑ ግልጽ እባብ ሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 108, '108. እጁንም አወጣ:: እርሷም ወዲያውኑ ለተመልካቾች ነጭ ሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 109, '109. ከፈርዖን ሰዎች መማክርቶቹም አሉ፡ «ይህ በእርግጥ አዋቂ ድግምተኛ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 110, '110. «ከምድራችሁ ሊያወጣችሁ ይሻል።» አሉ። (ፊርዓውንም) «ታዲያ ምን? ታዛላችሁ?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 111, '111. እነርሱም አሉ: «እርሱንና ወንድሙን አቆያቸው:: ወደ ከተሞቹ ሁሉ ሰብሳቢዎችን ላክ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 112, '112. «አዋቂ ድግምተኞችን ሁሉ ያመጡልሃልና።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 113, '113. ድግምተኞቹም ወደ ፈርዖን መጡና «እኛ አሸናፊዎች ብንሆን ለኛ ክፍያ አለን?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 114, '114. ፈርዖንም: «አዎን። እናንተ እኔ ዘንድ ከባለሟሎቹ ትሆናላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 115, '115. እነርሱም «ሙሳ ሆይ! ዘንግህን በፊት ትጥላለህ ወይስ ፊት ጣዮቹ እኛ እንሁን?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 116, '116. ሙሳም «በፊት እናንተ ጣሉ።» አላቸው:: ከዚያም ገመዶቻቸውን በጣሉ ጊዜ የሰዎቹን ዓይኖች ደገሙባቸውና አስፈራሯቸው:: ትልቅ ድግምትንም አመጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 117, '117. ወደ ሙሳም «ዘንግህን ጣል» ስንል ላክንበት (ጣላትም) ወዲውኑም የሚቀጣጥፉትን ማታለያ ሁሉ መዋጥ ጀመረች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 118, '118. እውነቱም ተገለጸ:: ይሠሩት የነበሩት ድግምትም ተበላሸ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 119, '119. እዚያ ላይ ተሸነፉና ወራዶች ሆነው ተመለሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 120, '120. ድግምተኞቹም ሰጋጆች ሆነው ሱጁድ ወረዱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 121, '121. አሉም: «በዓለማት ጌታ አመንን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 122, '122. «በሙሳና በሃሩን ጌታ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 123, '123. (ፊርዓውንም) አለ፡ «እኔ ለእናንተ ሳልፈቅድላችሁ በፊት በእርሱ አመናችሁን? ይህ በከተማይቱ ውስጥ ሰውን ከእርሷ ለማውጣት የተስማማችሁበት ተንኮል ነው:: ወደፊት የሚደርሰባችሁን ታውቃላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 124, '124. «እጆቻችሁንና እግሮቻችሁን በማፈራረቅ በእርግጥ እቆራርጣለሁ:: ከዚያም ሁላችሁንም በእንጨት ላይ እስቅላችኋለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 125, '125. እነርሱም አሉ: «እኛ ወደ ጌታችን ተመላሾች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 126, '126. «የጌታችን ተዓምራት በመጡልን ጊዜ ከማመናችን በስተቀር ከእኛ አትጠላም:: ጌታችን ሆይ! በእኛ ላይ ትዕግስትን አፍስስ:: ሙስሊሞችም ሆነን ግደለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 127, '127. ከፈርዖን ሰዎች ቅምጥሎቹ ለፈርዖን: «ሙሳንና ሰዎችን በምድር ላይ እንዲያበላሹና ሙሳም አንተንና አምልኮትህን እንዲተው ትተዋቸዋለህን?» አሉ:: እሱም «ወንዶች ልጆቻቸውን እንገድላለን:: ሴቶቻቸውንም እናስቀራለን:: እኛም ከበላያቸው ነን አሸናፊዎች ነን» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 128, '128. ሙሳም ለሰዎቹ፡- «በአላህ ታገዙ፤ ታገሱም። ምድር ለአላህ ናትና ከባሮቹ መካከል ለሚሻው ያወርሳታል:: ምስጉኗም ፍጻሜ ለጥንቁቆቹ ናት።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 129, '129. ህዝቦቹም «አንተ ከመምጣትህ በፊትም ሆነ ከመጣህልን በኋላ ተሰቃየን።» አሉት:: ሙሳም «ጌታችሁ ጠላቶቻችሁን ሊያጠፋና እንዴት እንደምትሰሩ ይመለከት ዘንድ በምድር ላይ ሊተካችሁ ይከጀላል።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 130, '130. የፈርዖንንም ቤተሰቦች እንዲገሰጹ በድርቅና የፍራፍሬ ምርታቸውን በመቀነስ በእርግጥ ቀጣናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 131, '131. ምቾት በመጣችላቸው ጊዜ «ይህች ለእኛ ተገቢ ናት።» ይላሉ። ክፋት ባገኛቸው ጊዜ ግን ሙሳና አብረውት ያሉት ክፉ ገዶቻቸው እንደሆኑ ያስባሉ። አስተውሉ! ክፉ እድላቸው (ገደቢስነታቸው) ከአላህ ዘንድ ነው:: አብዛኞቻቸው ግን ይህን አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 132, '132. «በማንኛይቱም ተዓምር ልትደግምብን ብታመጣም የምናምንልህ አይደለንም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 133, '133. ወዲያዉም የውሃን ማጥለቅለቅ፤ አንበጣን፤ ቅማልን፤ እንቁራሪቶችን፤ ደምን፤ የተለያዩ ተዓምራት ሲሆኑ በእነርሱ ላይ ላክን:: እነርሱ ግን ኮሩም:: ተንኮለኞችም ህዝቦች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 134, '134. በእነርሱ ላይ ቅጣቱ በወደቀባቸውም ጊዜ «ሙሳ ሆይ! ጌታህን ላንተ ቃል ኪዳን በገባልህ መሠረት ለምንልንና ከእኛ ቅጣቱን ብታነሳልን ላንተ እናምንልሀለን:: የኢስራኢልን ልጆችም ካንተ ጋር እንለቃለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 135, '135. ለሚደርሱበት የተወሰነ ጊዜ ድረስ ቅጣትን ከእነርሱ ላይ ባነሳን ጊዜ ወዲያውኑ እነርሱ ቃላቸውን አፈረሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 136, '136. እነርሱም በተዓምራታችን ስላስተባበሉና ከእርሷ ዘንጊዎች ስለሆኑ ተበቀልናቸው:: በባህር ውስጥም አሰመጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 137, '137. እነዚያንም ደካሞች የነበሩትን ህዝቦች ያቺን በውስጧ በረከት ያደረግንባትን ምድር ምስራቋንም ምዕራቧንም አወረስናቸው:: መልዕክተኛችን ሆይ! የጌታህ መልካሚቱ ቃል በኢስራኢል ልጆች ላይ በመታገሳቸው ተፈጸመች:: ፈርዖንና ሰዎቹ ይሰሩት የነበረውን ህንጻና ዳስ ያደርጉት የነበረውንም አፈረስን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 138, '138. የኢስራኢል ልጆችን ባህሩን አሻገርናቸው:: ለእነርሱ በሆኑ ጣኦታት መገዛት ላይ በሚዘወትሩ ህዝቦች አጠገብ አለፉም:: «ሙሳ ሆይ! ለእነርሱ ለሰዎቹ አማልክት እንዳሏቸው ሁሉ ለኛም አምላክን አድርግልን።» አሉት:: «እናንተ የምትሳሳቱ ህዝቦች ናችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 139, '139. «እነዚህ እነርሱ በውስጡ ያሉበት ነገር ጠፊ ነው:: ይሰሩት የነበሩትም ብልሹ ነው።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 140, '140. «እርሱ ከዓለማት ያበለጣችሁ ሲሆን ከአላህ ሌላ የምትገዙትን አምላክ እፈልግላችኋለሁን?» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 141, '141. የኢስራኢል ልጆች ሆይ! ከፈርዖንም ቤተሰቦች ብርቱን ቅጣት የሚያቀምሷችሁ ወንዶች ልጆቻችሁንም የሚገድሉ ሴቶቻችሁንም የሚተው ሲሆኑ ባዳንናችሁ ጊዜ (የሆነዉን አስታውሱ):: በዚህ ውስጥ ከጌታችሁ የሆነ ከባድ ፈተና አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 142, '142. ነብዩ ሙሳን ሰላሳን ሌሊት (ሊፆምና ልናነጋግረው) ቀጠርነው:: በአስርም (ሌሊት) ሞላናት:: የጌታዉም ቀጠሮ አርባ ሌሊት ሲሆን ተፈጸመ:: ሙሳም ለወንድሙ ለሀሩን «በህዝቦቼ ላይ ተተካኝና አሳምር:: የአጥፊዎችን መንገድ አትከተል።» አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 143, '143. ሙሳ ለቀጠሮው በመጣና ጌታዉም ባነጋገረው ጊዜ፡ «ጌታዬ ሆይ! በእርግጥ ራስህን አሳየኝ ወደ አንተ እመለከታለሁና።» አለ። (አላህም)፡- «እኔን በፍጹም አታየኝም:: ግን ወደ ተራራው ተመልከትና በስፍራው ከረጋ አንተም ታየኛለህ።» አለው:: ጌታዉም ለተራራው በተገለጸ ጊዜ እንኩትኩት አደረገው:: ሙሳም ጮኸና ወደቀ:: በአንሰራራም ጊዜ «ጌታዬ ጥራት ይገባህ ወደ አንተ ተመለስኩ:: እኔም በጊዜያቴ የአማኞች መጀመሪያ ነኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 144, '144. አላህም አለ፡- «ሙሳ ሆይ! እኔ በመልዕክቶቼና በማናገሬ በሰዎች ላይ መረጥኩህ:: የሰጠሁህንም ያዝ። ከአመስጋኞችም ሁን።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 145, '145. ለእርሱም በሰሌዳዎቹ ላይ ከሁሉ ነገር ግሳጼንና ለሁሉ ነገር ማብራራትን ጻፍንለትና አልንም: «በብርታትም ያዛት። ሕዝቦችህንም በመልካሟ እንዲይዙ እዘዛቸው። የአመጸኞቹን አገር በእርግጥ አሳያችኋለሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 146, '146. እነዚያን ያለ አግባብ በምድር ላይ የሚኮሩትን ከአንቀፆቼ በእርግጥ አዞራቸዋለሁ:: ተዓምርንም ሁሉ ቢያዩ እንኳን አያምኑም:: ቅንንም መንገድ ቢያዩ መንገድ አድርገው አይዙትም:: ግን የጥመትን መንገድ ቢያዩ መንገድ አድርገው ይይዙታል:: ይህ እነርሱ በአንቀፆቻችን ስለ አስተባበሉና ከእርሷም ዘንጊዎች ስለሆኑ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 147, '147. እነዚያም በአናቅጻችንና መጨረሻይቱን ዓለም በመገናኘት ያስተባበሉት ሥራዎቻቸው ተበላሹ:: ይሰሩት የነበረውን እንጂ ይመነዳሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 148, '148. የሙሳም ህዝቦች ከእርሱ መሄድ በኋላ ከጌጦቻቸው በወይፈን ቅርጽ የተቀረጸውን እና የራሱ የሆነ ድምጽ የነበረውን አካል አምላክ አድርገው ያዙት:: እርሱ የማያናግራቸው መንገድን የማይመራቸው መሆኑን አይመለከቱምን? አምላክ አደረጉት:: በዳዮችም ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 149, '149. በተጸጸቱና እነርሱም በእርግጥ የተሳሳቱ መሆናቸውን ባዩ ጊዜ «ጌታችን ካላዘነልንና ካልማረን በእርግጥ ከከሳሪዎቹ እንሆናለን።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 150, '150. ሙሳ እየተቆጣና እያዘነ ወደ ህዝቦቹ በተመለሰ ጊዜ «በእኔ ቦታ የተካችሁት ነገር ምንኛ ከፋ! የጌታችሁን ትዕዛዝ ተቻኮላችሁን?» አላቸውና ሰሌዳዎቹንም ጣላቸው። የወንድሙን የራስ ጸጉር ወደ እርሱ እየጎተተው ያዘ:: ወንድሙም፡- «የእናቴ ልጅ ሆይ! ህዝቦቹ ናቁኝ ሊገድሉኝም ተቃረቡ:: ስለዚህ በእኔ ጠላቶችን አታስደስትብኝ። ከአመጸኞች ህዝቦችም ጋር አታድርገኝ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 151, '151. ሙሳም፡- «ጌታዬ ሆይ! ለኔም ለወንድሜም ማረን:: በእዝነትህ ውስጥም አስገባን። አንተም ከአዛኞቹ ሁሉ ይበልጥ አዛኝ ነህና።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 152, '152. እነዚያ ወይፈኑን አምላክ ያደረጉት ሰዎች ከጌታቸው ዘንድ ቁጣ በቅርቢቱም ህይወት ውርደት ያገኛቸዋል:: ቀጣፊዎችን ልክ እንዲዚሁ እንቀጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 153, '153. እነዚያም ኃጢአቶችን የሠሩ ከዚያም በኋላ የተጸጸቱና በአላህ ያመኑ ጌታህ ከእርሷ በኋላ መሀሪና አዛኝ ነው:: (ጸጸታቸውን ይቀበላቸዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 154, '154. ሙሳም ቁጣው በበረደ ጊዜ ሰሌዳዎቹን አነሳቸው:: በግልባጫቸውም ውስጥ ለእነዚያ እነርሱ ጌታቸውን ለሚፈሩት ሰዎች ሁሉ መምሪያና እዝነት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 155, '155. ሙሳም ከህዝቦቹ መካከል ለቀጠሯችን ሰባ ሰዎችን መረጠ:: ከዚያ ብርቱ የምድር እንቅጥቃጤ በደረሰባቸው ጊዜ ሙሳ አለ፡- «ጌታዬ ሆይ! ብትፈልግ ኖሮ ከአሁን በፊት ባጠፋሀቸው ነበር:: እኔንም ባጠፋኸኝ ነበር:: ከእኛ መሀከል ቂሎቹ በሠሩት ጥፋት ታጠፋናለህን? ፈተናይቱ የአንተ ፈተና እንጂ ሌላ አይደለችም:: በእርሷ የምትሻውን ታሳስታለህ። የምትሻውንም ታቀናለህ:: አንተ ረዳታችን ነህና:: ለእኛ ምህረት አድርግልን። እዘንልንም:: አንተ ከመሀሪዎች ሁሉ በላጭ ነህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 156, '156. «ጌታችን ሆይ! ለእኛ በዚች በቅርቢቱ ዓለም መልካሟን በመጨረሻይቱም ዓለም መልካሟን ጻፍልን:: እኛ ወደ አንተ ተመልሰናል።» (ሲል ሙሳ ጌታውን ለመነ):: አላህም አለ: «ቅጣቴ በእርሱ ልቀጣው የምፈልገውን ሰው እቀጣበታለሁ:: ችሮታዬ ከሁሉም ነገር የሰፋ ነው:: ለእነዚያ ለሚጠነቀቁ ዘካንም ለሚሰጡ ለእነዚያም በአናቅጻችን ለሚያምኑ ሁሉ በእርግጥ እጽፈዋለሁ::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 157, '157. ለእነዚያ ያንን እነርሱ ዘንድ በተውራትና በኢንጂል ተጽፎ የሚያገኙትን የማይጽፍና የማያነብን መልዕክተኛ የሚከተሉ ለሆኑ (ሁሉ በእርግጥ እጽፋታለሁ):: በበጎ ሥራ ያዛቸዋል:: ከክፉም ነገር ይከለክላቸዋል:: መልካም ነገሮችንም ለእነርሱ ይፈቅድላቸዋል:: መጥፎ ነገሮችንም በነሱ ላይ እርም ያደርግባቸዋል:: ከእነርሱም ላይ ሸክማቸውንና እነዚያንም በእነርሱ ላይ የነበሩትን እንደ እንዛዝላ ይከብዱ የነበሩ ከባድ ህግጋትን ያነሳላቸዋል:: እነዚያ በእርሱ ያመኑ፤ ያከበሩት፤ የረዱትና ያንን ከርሱ ጋር የተወረደውን ብርሃን የተከተሉ ሁሉ እነዚያ እነርሱ ከቅጣት የሚድኑ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 158, '158. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎች ሆይ! እኔ ወደ እናንተ ወደ ሁላችሁም የአላህ መልዕክተኛ ነኝ:: እርሱም ያ የሰማያትና የምድር ንግስና ለእርሱ ብቻ የሆነ ነው:: እርሱ እንጂ ሌላ አምላክ የለም:: ህያው ያደርጋል:: ይገድላልም:: በአላህ በዚያም በአላህና በቃላቶቹ በሚያምነው የማይጽፍ የማያነብ በሆነው መልዕክተኛውም እመኑ:: ወደ ቅኑ መንገድ ትመሩ ዘንድም ተከተሉት።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 159, '159. ከሙሳ ህዝቦች መካከል በእውነት የሚመሩና በእውነት ፍርድን የሚያስተካከሉ ቡድኖችም አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 160, '160. የሙሳን ህዝቦች አስራ ሁለት ነገዶች አድርገን ከፋፈልናቸው:: ወደ ሙሳም ወገኖቹ ውሃን በፈለጉበት ጊዜ ድንጋዩን በበትርህ ምታው ስንል ላክን:: (መታዉም) አስራ ሁለት ምንጮች ፈለቁ:: ሰዎቹ ሁሉ መጠጫቸውን በእርግጥ አወቁ:: በእነርሱም ላይ ዳመናን አጠለልን:: በእነርሱም ላይ "መንን" እና ድርጭትን አወረድን:: «ከሰጠናችሁም መልካም ሲሳይ ብሉ።» አልን:: ጸጋዎቻችንን በመካዳቸው አልበደሉንም:: ግን ነፍሶቻቸውን የሚበድሉ ህዝቦች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 161, '161. (መልዕክተኛችን ሙሐመድ ሆይ!) ለነርሱም «በዚች ከተማ ተቀመጡ:: ከእርሷም በፈለጋችሁት ስፍራ ብሉ:: ‹የምንፈልገው የኃጢታችንን መርገፍ ብቻ ነው።› በሉም:: የከተማይቱን በር አጎንብሳችሁ ግቡ ኃጢአቶቻችሁን ለእናንተ እንምራለንና:: በጎ ለሠሩት ሰዎች በእርግጥ እንጨምራለን።» ባልን ጊዜ የሆነውን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 162, '162. ከእነርሱም ውስጥ እነዚያ ራሳቸውን የበደሉ ሰዎች ከዚያ ለእነርሱ ከተባለው ሌላ የሆነን ቃል ለወጡ:: በእነርሱም ላይ ይበድሉ በነበሩት በደል ምክንያት መአትን ከሰማይ ላክንባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 163, '163. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዚያም በባህሩ ዳርቻ ከነበረችው ከተማ በቅዳሜ ቀን ወሰን ባለፉ ጊዜ በሰንበታቸው ቀን አሳዎቻቸው የተከማቹ ሆነው በሚመጡላቸው ጊዜ የሆነውን ጠይቃቸው:: ሰንበትንም በማያከብሩበት (በሌላው) ቀን አይመጡላቸዉም:: ልክ እንደዚሁ በአመፃቸው ምክንያት እንሞክራቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 164, '164. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም ከፊሎቹ ህዝቦች «አላህ አጥፊያቸው ወይም በብርቱ ቅጣት ቀጫቸው የሆኑትን ህዝቦች ለምን ትገስጻላችሁ?» ባሉ ጊዜ ገሳጮቹም «በጌታችሁ ዘንድ በቂ ምክንያት እንዲሆንና እነርሱም ቢከለከሉ ብለን ነው።» ባሉበት ጊዜ የሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 165, '165. የተገሰጹበትንም ነገር በተው ጊዜ እነዚያን ከክፉ የሚከለክሉትን ክፍሎች አዳንን:: እነዚያንም የበደሉትን ሰዎች ያምጹ በነበሩበት ምክንያት በብርቱ ቅጣት ቀጣናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 166, '166. ከእርሱም ከተከለከሉት ነገር በኮሩ ጊዜ ለእነርሱ «ወራዶች ዝንጀሮዎች ሁኑ።» አልን:: (ሆኑም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 167, '167. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም እስከ ትንሳኤ ቀን ክፉ ቅጣትን የሚያቀምሳቸውን ወገን በነሱ ላይ በእርግጥ የሚልክ መሆኑን ባስታወቀ ጊዜ (የሆነውን አስታውሳቸው):: ጌታህ በእርግጥ ቅጣተ ፈጣን ነው:: እርሱም በእርግጥ እጅግ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 168, '168. (የኢስራኢልን ልጆችን) በምድር ላይ የተለያዩ ህዝቦች አድርገንም ከፋፈልናቸው:: ከእነርሱ መልካሞች አሉ:: ከእነርሱም ከዚያ ሌላ የሆኑ አሉ:: ይመለሱ ዘንድም በተድላዎችና በመከራዎቻች ሞከርናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 169, '169. ከኋላቸዉም መጽሐፉን የወረሱ መጥፎ ምትኮች በእነርሱ ቦታ ተተኩ:: የዚህም የቅርቡን ጠፊ ጥቅም ይይዛሉ:: ብጤዉም ጥቅም ቢመጣላቸው የሚይዙት ሲሆኑ «በሠራነው ለእኛ ምህረት ይደርግልናል።» ይላሉ:: በአላህ ላይ በእውነት በስተቀር እንዳይናገሩ በእነርሱ ላይ የመጽሐፉ ቃል ኪዳን አልተያዘባቸዉምን? በእርሱ ውስጥ ያለውንም አላነበቡምን? የመጨረሻይቱን አገር ለእነዚያ ጌታቸውን ለሚፈሩት ሰዎች ሁሉ በላጭ ናት:: አታውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 170, '170. እነዚያም መጽሐፉን ጠብቀው የሚይዙ፤ ሶላትንም በደንቡ የሰገዱ ሁሉ (ምንዳቸውን እንከፍላቸዋለን):: እኛ የመልካም ሠሪዎችን ምንዳ አናጠፋምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 171, '171. (መልዕክተኛችን ሙሐመድ ሆይ!) የጡርን ተራራ ነቅለን ከበላያቸው እንደ ጥላ ሆኖ ባነሳነውና እርሱም በእነርሱ ላይ ወዳቂ መሆኑን ባረጋገጡ ጊዜ የሆነውን( አስታውስ):: «የሰጠናችሁን በብርታት ያዙ:: ትጠነቀቁም ዘንድ በዉስጡ ያለውን ተገንዘቡ።» አልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 172, '172. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም ከአደም ልጆች ከጀርቦቻቸው ዘሮቻቸውን ባወጣና «ጌታችሁ አይደለሁምን?» ሲል በነፍሶቻቸው ላይ ባስመሰከራቸው ጊዜ (የሆነውን አስታውስ):: «ጌታችን ነህ መሰከርን» አሉ። በትንሳኤ ቀን «ከዚህ ቃል ኪዳን ዘንጊዎች ነበርን» እንዳትሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 173, '173. ወይም «ጣኦታትን ያጋሩት ከኛ በፊት የነበሩት አባቶቻችን ብቻ ናቸው:: እኛም ከእነርሱ በኋላ የሆንን ዘሮች ነበርን አጥፊዎቹ በሠሩት ጥፋት እኛን ታጠፋናለህን?» እንዳትሉ አስመሰከርናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 174, '174. ልክ እንደዚሁም (እንዲያስቡ) እንዲመለሱም አናቅጽን እናብራራለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 175, '175. (መልዕክተኛችን ሙሐመድ ሆይ!) የዚያን ተዓምራታችንን የሰጠነውንና ከዚያ እርሱም ከእርሷ የወጣውን ሰይጣንም ያስከተለውን በዚህም ምክንያት ከጠማሞቹ የሆነውን ሰው ወሬ በእነርሱ ላይ አንብብላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 176, '176. ብንፈልግ ኖሮ በእርሷ ከፍ ባደረግነው ነበር:: እርሱ ግን ወደ ምድር ተዘነበለ:: ፍላጎቱንም ተከተለ:: ብጤዉም ብታባርረዉም ባታባርረዉም ምላሱን አውጥቶ እንደሚያለከልክ ውሻ ነው:: ይህ የእነዚያ በአናቅጻችን ያስተባበሉት ህዝቦች ምሳሌ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ያስተነትኑም ዘንድ ታሪኮችን ተርክላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 177, '177. የእነዚያ በአናቅጻችን ያስተባበሉትና ነፍሶቻቸውን ይበድሉ የነበሩት ሰዎች ምሳሌ ከፋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 178, '178. አላህ የሚያቀናው ሰው ሁሉ ቅን ማለት እርሱው ነው:: የሚያጠማቸዉም ሰዎች እነዚያ ከሳሪዎቹ ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 179, '179. ከአጋንንትም ሆነ ከሰዎች መካከል ብዙዎችን ለገሀነም በእርግጥ ፈጠርን:: ለእነርሱ የማያውቁባቸው ልቦች አሏቸው:: ለእነርሱም የማያዩባቸው ዓይኖች አሏቸው:: ለእነርሱም የማይሰሙባቸው ጆሮዎች አሏቸው:: እነዚያ እንደ እንስሳዎች ናቸው:: ይልቁንም እነርሱ በጣም የተሳሳቱ ህዝቦች ናቸው:: እነዚያ ዘንጊዎቹ እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 180, '180. ለአላህ መልካም ስሞች አሉት:: (ዱዓ ስታደርጉ) በእርሷ ጥሩት:: እነዚያን ስሞቹን የሚያጣምሙትን ክፍሎች ተዋቸው:: ይሠሩት የነበሩትን ነገር በእርግጥ ይመነዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 181, '181. ከፈጠርናቸዉም መካከል በእውነት የሚመሩና በእውነት ፍርድን የሚያስተካክሉ ህዝቦችም አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 182, '182. እነዚያን በአናቅጻችን ያስተባበሉትን ሰዎች ከማያውቁት ስፍራ ቀስ በቀስ እናዘናጋቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 183, '183. ለእነርሱም ጊዜ እሰጣቸዋለሁ:: ጥበቤ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 184, '184. በነብያቸው በሙሐመድ ምንም እብደት የሌለበት መሆኑን አያስተውሉምን? እርሱ ግልጽ አስፈራሪ እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 185, '185. በሰማያትና በምድር ግዛት ውስጥ ከማንኛዉም ነገር አላህ በፈጠራቸው ሁሉ የሞት ጊዜያቸዉም በእርግጥ መቅረቡ የሚፈራ መሆኑን አያስተውሉምን? ለመሆኑ እነርሱ ከቁርኣን ወዲያ በየትኛው ንግግር ያምናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 186, '186. አላህ የሚያጠመውን ለእርሱ ምንም አቅኝ የለዉም:: በጥመታቸዉም ውስጥ የሚዋልሉ ሲሆኑ ይተዋቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 187, '187. (መልዕክተኛችን ሙሐመድ ሆይ!) ትንሳኤ መቼ እንደምትመጣ ይጠይቁሃል:: «እውቀቷ በጌታዬ ዘንድ ብቻ ነው:: በመከሰቻዋ ጊዜም እርሱ እንጂ ሌላ አይገልጽላችሁም:: በሰማያትና በምድርም ከበደች:: በድንገት ቢሆን እንጂ አትመጣባችሁም።» በላቸው:: ስለ እርሷ በደንብ እንደተረዳ አድርገው ይጠይቁሃል:: «እውቀቷ ግን አላህ ዘንድ ብቻ ነው:: ግን አብዛኞቹ ሰዎች ይህን ነገር ጠንቅቀው አያውቁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 188, '188. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ የፈለገዉን በስተቀር ለራሴ ጥቅምንም ሆነ ጉዳት ማምጣት አልችልም:: የሩቅን ሚስጥር የማውቅ በነበርኩ ኖሮ ከመልካም ነገር ሁሉ ባበዛሁና ክፉም ነገር ባልነካኝ ነበር:: እኔም ለሚያምኑ ህዝቦች ሁሉ አስፈራሪና አብሳሪ እንጂ ሌላ አይደለሁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 189, '189. (ሰዎች ሆይ!) እርሱ ያ ከአንዲት ነፍስ (ከአደም) የፈጠራችሁና ከእርሷም መቀናጆዋን ወደ እርሷ ይረካ ዘንድ የፈጠረ ነው:: በተገናኛትም ጊዜ ቀላልን እርግዝና አረገዘች:: ጽንሱን ይዛው ሄደች:: ባረገዘችም ጊዜ «ደግን ልጅ ብትሰጠን በእርግጥ ከአመስጋኞቹ እንሆናለን።» ሲሉ ጌታቸውን አላህን ለመኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 190, '190. መልካምን ልጅ በሰጣቸዉም ጊዜ በሰጣቸው ልጅ (ስም) ለእርሱ ተጋሪዎችን አደረጉለት:: አላህ ከሚያጋሩት ሁሉ ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 191, '191. ምንንም የማይፈጥሩትንና እነርሱ ራሳቸው የሚፈጠሩትን ፍጡሮች በአላህ ያጋራሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 192, '192. ለነርሱም መርዳትንም የማይችሉትን፤ ነፍሶቻቸውንም እንኳን የማይረዱትን ያጋራሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 193, '193. ወደ ቅን መንገድ ብትጠሯቸዉም አይከተሏችሁም:: ብትጠሯቸው ወይም ዝምተኞች ብትሆኑም በእናንተ ላይ እኩል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 194, '194. (ከሀዲያን ሆይ!) እነዚያ ከአላህ ሌላ የምትገዟቸው ጣኦቶች ብጤዎቻችሁ የአላህ ባሮች ናቸው:: እውነተኞች ከሆናችሁ እስቲ ጥሯቸውና ለእናንተ ይመልሱላችሁ:: (መመለስ አይችሉም።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 195, '195. ለእነርሱ የሚሄዱባቸው እግሮች አሏቸውን? ወይስ የሚጨብጡባቸው እጆች አሏቸውን? ወይንስ እነርሱ የሚያዩባቸው አይኖች አሏቸውን? ወይንስ እነርሱ የሚሰሙባቸው ጆሮዎች አሏቸዉን? (መልዕክተኛችን ሙሐመድ ሆይ!) «ያጋራችኃቸውን ጥሩና ከዚያም አሲሩብኝ:: ጊዜም አትስጡኝ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 196, '196. (መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ በላቸው) «የእኔ ረዳቴ ያ ቁርኣንን ያወረደልኝ አላህ ብቻ ነው:: እርሱ መልካም ሠሪዎችን ሁሉ ይረዳልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 197, '197. (አጋሪዎች ሆይ! ) «እነዚያ ከአላህ ሌላ የምትገዟቸው ጣኦታት ሁሉ ሊረዷችሁ ፍጽሞ አይችሉም:: ነፍሶቻቸውንም እንኳን አይረዱም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 198, '198. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ ቀናው መንገድ እንዲመሩ ብትጠሯቸው አይሰሙም። እነርሱንም የማያዩ ሲሆኑ ወደ አንተ ሲመለከቱ ታያቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 199, '199. (መልዕክተኛችን ሙሐመድ ሆይ!) ይቅርባይነትን ያዝ:: በመልካምም እዘዝ:: ባለጌዎቹንም ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 200, '200. (መልዕክተኛችን ሙሐመድ ሆይ!) የሰይጣን የተንኮል ጉትጎታ ቢያጋጥምህ በአላህ ብቻ ተጠበቅ:: አላህ ሁሉን ሰሚና ሁሉንም አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 201, '201.እነዚያ የተጠነቀቁት ከሰይጣን የኾነ ዘዋሪ በነካቸው ጊዜ (ጌታቸውን) ይገነዘባሉ:: ወዲያዉም እነርሱ ተመልካቾች ይሆናሉ:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 202, '202. ወንድሞቻቸዉም ጥመትን ይጨምሩላቸዋል:: ከዚያም እነርሱ አይገቱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 203, '203. (መልዕክተኛችን ሙሐመድ ሆይ!) ተዓምርም ባላመጣህላቸው ጊዜ «በራስህ ለምን አትመርጣትም።» ይላሉ:: «ከጌታዬ ወደ እኔ የተወረደውን ብቻ ነው የምከተለው:: ይህ ቁርኣን ከጌታችሁ የተወረደ ሲሆን ለሚያምኑ ህዝቦች ሁሉ መረጃ፤ መመሪያና እዝነት ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 204, '204. (ሙስሊሞች ሆይ!) ቁርኣን በሚነበብበት ጊዜ እርሱን በጥሞና አድምጡ:: ጸጥም በሉ። ይታዘንላችኋልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 205, '205. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህን በሚስጥር ተናንሰህና ፈርተህ ከጩኸት በታች በሆነ ድምጽ በጥዋትና በማታ አውሳው:: ከዘንጊዎቹም አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (7, 206, '206. እነዚያ በጌታህ ዘንድ ያሉት መላዕክት እንኳን እርሱን ከመገዛት ፈጽሞ አይኮሩም:: ሁል ጊዜም ያወድሱታል:: ለእርሱም ብቻ ይሰግዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 1, '1.(መልዕክተኛችን ሙሐመድ ሆይ!) በጦርነት ከተማረኩ ገንዘቦች ይጠይቁሃል። «በጦርነት የተዘረፉ ገንዘቦች የአላህና የመልዕክተኛው ናቸው:: ስለዚህ አላህን ፍሩ:: በመካከላችሁ ያለውንም ሁኔታ አሳምሩ:: ትክክለኛ አማኞች ከሆናችሁ አላህንና መልዕክተኛውን ታዘዙ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 2, '2. ፍጹም ትክክለኛ አማኞች ማለት እነዚያ አላህ በተወሳ ጊዜ ልቦቻቸው የሚፈሩ፤ በእነርሱም ላይ የቁርኣን አናቅጽ በተነበቡ ጊዜ እምነትን የሚጨምሩላቸውና በጌታቸው ላይ ብቻም የሚመኩት ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 3, '3. እነዚያ ሰላትንም (ወቅቱን ጠብቀውና ደንቡን አሟልተው) የሚሰግዱና ከሰጠናቸዉም ሲሳይ የሚለግሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 4, '4. እነዚያ ትክክለኛ አማኞች ማለት እነርሱው ናቸው:: ለእነርሱ በጌታቸው ዘንድ ብዙ ደረጃዎች፤ የአላህ ምሕረትና የከበረ ሲሳይ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 5, '5. (መልዕክተኛችን ሙሐመድ ሆይ! ይህ በምርኮ ክፍያ ሂደት ላይ የታየው የከፊሉ ሰው መጥላት ምሳሌው) ከአማኞች ከፊሉ እየጠሉ ጌታህ ከቤትህ በእውነት ላይ ሆነህ እንዳወጣህ ምሳሌ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 6, '6.(መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱ እያዩ ወደ ሞት እንደሚነዱ ሆነው በእውነቱ ነገር ላይ በመጋደል ግዴታነት ከተገለጸላቸው በኋላ ይከራከሩሃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 7, '7. (እናንተ ተከራካሪዎች ሆይ!)፤ አላህ ከሁለቱ ቡድኖች አንደኛዋን ለእናንተ ናት ሲል ተስፋ በሰጣችሁና የኃይል ባለቤት ያልሆነችውን የነጋዴይቱን ቡድን ለእናንተ ልትሆን በወደዳችሁ ጊዜ አላህም በተስፋ ቃላቱ እውነቱን ማረጋገጡን ሊገልጽና የካሓዲያንንም መጨረሻ ሊቆርጥ በፈለገ ጊዜ (የሆነውን አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 8, '8. ይህንንም ያደረገው አጋሪዎቹ ቢጠሉም እውነቱን ሊያረጋግጥና ክህደትን ሊያጠፋ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 9, '9. (ሙስሊሞች ሆይ!) ከጌታችሁ እርዳታን በፈለጋችሁ ጊዜ «እኔ በሺህ መላዕክት ተከታታዮች ሲሆኑ እረዳችኋለሁ።» ሲል ለእናንተ የተቀበላችሁን አስታውሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 10, '10. አላህ ይህንን እርዳታ ለብስራትና ልቦቻችሁ በእርሱ ሊረኩበት እንጂ ለሌላ አላደረገዉም:: ድልም የሚገኘው ከአላህ ዘንድ ብቻ ነው:: አላህ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ! ) ከእርሱ በሆነው ጸጥታ በጦር ግንባር በእንቅልፍ በሸፈናችሁና ውሃውንም በእርሱ ሊያጠራችሁ፤ የሰይጣንንም ጉትጎታ ከናንተ ላይ ሊያስወግድላችሁ፤ ልቦቻችሁንም በትዕግሥት ሊያጠነክርላችሁ፤ በእርሱም ጫማዎችን በአሸዋው ላይ ሊያደላድልላችሁ በእናንተ ላይ ከሰማይ ዝናብን ባወረደ ጊዜ የሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 12, '12. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ወደ መላዕክቱ «እኔ በእርዳታዬ ከናንተ ጋር ነኝና እነዚያን በእኔ ያመኑትን ሰዎች አጽናኑ:: በእነዚያ በአላህ በካዱት ልቦች ውስጥ ደግሞ ፍርሀትን እጥላለሁ:: ከአንገቶችም በላይ እራሶችን ምቱ:: ከእነርሱም የቅርንጫፎችን መለያ ( አትቆች) ሁሉ ምቱ።» ሲል ያወረደውን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 13, '13. ይህ የሆነው በአላህና በመልዕክተኛው ስለካዱ ነው:: አላህንና መልዕክተኛውን ለሚቃወም ሁሉ አላህም ቅጣቱ ብርቱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 14, '14. (ከሓዲያን ሆይ!) ይህ ቅጣታችሁ ነው:: እናም ቅመሱት:: ለከሓዲያን የገሀነም እሳት ቅጣት በእርግጥ አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 15, '15. እናንተ ያመናችሁ ሆይ! እነዚያን በአላህ የካዱትን ለጦር ሲጓዙ ባገኛቹኋቸው ጊዜ ጀርባዎችን አታዙሩላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 16, '16. ያን ጊዜ ለግድያ ለመዘዋወር ወይም ወደ ሰራዊት ለመቀላቀል ሳይሆን ጀርባውን የሚያዞርላቸው ሰው ሁሉ ከአላህ የሆነን ቁጣ አትርፏል። መኖሪያዉም ገሀነም ናት:: የገሀነም መመለሻነትም ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 17, '17. እናንተ አልገደላችኋቸዉም:: ግን አላህ ገደላቸው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጭብጥን አፈር በወረወርክም ጊዜ አንተ አልወረወርክም:: ግን አላህ ወረወረ። አማኞችን ሁሉ ከእርሱ የሆነን መልካም ፈተናን ለመፈተን ይህንን አደረገ። አላህም ሁሉን ሰሚ፤ ሁሉንም አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 18, '18. ይህ ከአላህ የተቸረ ዕውነት ነው:: አላህ የከሓዲያንን ሁሉ ተንኮል አድካሚ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 19, '19. (ከሓዲያን ሆይ!) ፍትሕን ብትጠይቁ ፍትሁ በእርግጥ መጥቶላችኋል:: ክሕደትና መዋጋታችሁን ብትከለከሉም እርሱ ለእናንተ የተሻለ ነው:: ወደ መጋደል ብትመለሱም እንመለሳለን:: ሰራዊታችሁ ብትበዛም እንኳ ለእናንተ ምንም አትጠቅማችሁም:: አላህ ሁልጊዜም ከትክክለኛ አማኞች ጋር ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 20, '20. እናንተ ያመናችሁ ሆይ! አላህንና መልዕክተኛውን ታዘዙ:: እናንተም እየሰማችሁ ከእርሱ አትሽሹ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 21, '21. እንደነዚያም የማይሰሙ ሲሆኑ ሰማን እንዳሉትም አትሁኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 22, '22. ከተንቀሳቃሾች ፍጡራን ሁሉ አላህ ዘንድ መጥፎዎች ማለት እነዚያ ሐቅን የማይሰሙ ደንቆሮዎቹ፣ እውነትን የማይናገሩና እውነታን የማያስተውሉት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 23, '23. በውስጣቸው ደግ መኖሩን አላህ ባወቀ ኖሮ የመረዳትን መስማት ያሰማቸው ነበር:: ደግ የሌለባቸው መሆኑን እያወቀ ባሰማቸዉም ኖሮ እነርሱ እውነትን የተዉ ሆነው በሸሹ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 24, '24. እናንተ ያመናችሁ ሆይ! (መልዕክተኛው) ህያው ወደ የሚያደርጋችሁ (እምነት) በጠራችሁ ጊዜ ለአላህና ለመልዕክተኛው ታዘዙ:: አላህ በሰውየውና በልቡ መካከል የሚጋርድ መሆኑንና ወደ እርሱም የምትሰበሰቡ መሆናችሁንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 25, '25. (እናንተ ያመናችሁ ሆይ!) ከናንተ መካከል እነዚያን የበደሉትን ብቻ ለይታ የማትጎዳን ፈተና ተጠንቀቁ:: አላህ ቅጣቱ ብርቱ መሆኑንም እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 26, '26. (ሙስሊሞች ሆይ!) እናንተ በምድር ላይ የተናቃችሁ ጥቂቶች ሆናችሁ ሳላችሁ ሰዎች ሊነጥቋችሁ የምትፈሩ ስትሆኑ ያስጠጋችሁን፤ በእርዳታዉም ያበረታችሁን፤ ከመልካሞች ሲሳዮችም ታመሰግኑ ዘንድ የሰጣችሁን አላህን አስታውሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 27, '27. እናንተ ያመናችሁ ሆይ! አላህንና መልዕክተኛውን አትካዱ:: አደራዎቻችሁንም እያወቃችሁ አትካዱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 28, '28. ገንዘቦቻችሁና ልጆቻችሁ ለፈተና ብቻ መሆናቸውንና አላህ ዘንድ ታላቅ ምንዳ ያለ መሆኑን ዕወቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 29, '29. እናንተ ያመናችሁ ሆይ! አላህን ብትፈሩ የእውነት መለያ ብርሃንን ያደርግላችኋል:: ክፉ ሥራዎቻችሁንም ከናንተ ላይ ያብስላችኋል:: እናንተንም ይምርላችኃል:: አላህ የታላቅ ችሮታ ባለቤት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም በአላህ የካዱ ሰዎች ሊያስሩህ ወይም ሊገድሉህ ወይም ከመካ ሊያስወጡህ ባንተ ላይ ባሴሩብህ ጊዜ የሆነውን አስታውስ:: ያሴራሉም:: አላህም ተንኮላቸውን ይመልስባቸዋል:: አላህ ግን ከሴረኞቹ ሁሉ በላይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 31, '31. አናቅጻችን በነርሱ ላይ በተነበቡ ጊዜም: «በእርግጥ ሰምተናል። በሻን ኖሮ የዚህን አባባል ተመሳሳይ ባልን ነበር:: ይህ የመጀመሪያዎቹ ሰዎች ተረቶች እንጂ ሌላ አይደለም።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 32, '32. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታችን ሆይ! ይህ እርሱ ካንተ ዘንድ የተወረደ እውነት እንደሆነ በእኛ ላይ ከሰማይ ድንጋዮችን አዝንብብን ወይም አሳማሚ ቅጣትን አምጣብን።» ባሉጊዜ (የሆነውን አስታውስ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 33, '33. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ በመካከላቸው እያለህ አላህ የሚቀጣቸው አይደለም። እነርሱም ምሕረትን የሚለምኑት ሲሆኑ አላህ የሚቀጣቸው አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 34, '34. እነርሱ ከተከበረው መስጊድ የሚከለክሉ ሲሆኑ አላህ የማይቀጣቸው ለመሆኑ ለእነርሱ ምን ዋስትና አላቸው? የቤቱ ጠባቂዎቹ አልነበሩም:: ጠባቂዎቹም ክሕደትን ተጠንቃቂዎቹ እንጂ ሌሎቹ አይደሉም:: ግን አብዛኛዎቹ አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 35, '35. በከዕባ ውስጥ ስግደታቸውም ማፏጨትና ማጨብጨብ እንጂ ሌላ አልነበረም። «ትክዱት በነበራችሁትም ነገር ቅጣትን ቅመሱ» (ይባላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 36, '36. እነዚያ የካዱት ከአላህ መንገድ ሊከለክሉ ገንዘቦቻቸውን ያወጣሉ:: በእርግጥም ያወጡታል:: ከዚያ ግን በእነርሱ ላይ ጸጸት ይሆንባቸዋል:: ከዚያም ይሸነፋሉ:: እነዚያም የካዱት ሁሉ ወደ ገሀነም ይሰበሰባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 37, '37. አላህ መጥፎውን ነገር ከመልካሙ ሊለይ መጥፎውንም ከፊሉን በከፊሉ ላይ ሊያደርግና በአንድ ላይ ሊያነባብረው በገሀነም ውስጥም ሊያደርገው (ይሰበሰባሉ):: እነዚያ እነርሱ ከሳሪዎቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 38, '38. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነዚያ በአላህ ለካዱት ቢከለከሉ ለእነርሱ በእርግጥ ያለፈውን ሥራ ምሕረት እንደሚደረግላቸው፤ ወደ መጋደል ቢመለሱም (እንደምናጠፋቸው ንገራቸው)። የቀድሞዎቹ ሕዝቦች ልማድ በእርግጥ አልፏልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 39, '39. ሁከት እስከሚጠፋና ሃይማኖት ሁሉ ለአላህ ብቻ እስከሚሆንም ድረስ ተጋደሏቸው:: ቢከለከሉም አላህ የሚሠሩትን ሁሉ ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 40, '40. (ሙስሊሞች ሆይ!) ከእምነት ቢዞሩም አላህ ረዳታችሁ መሆኑን እወቁ:: እርሱ ምን ያምር ጠባቂ! ምን ያምርም ረዳት ነው!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 41, '41.(እናንተ ያመናችሁ ሆይ!) ከማንኛዉም ነገር በጦርነት ከካሓዲያን የማረካችሁትም ሁሉ አንድ አምስተኛው ለአላህና ለመልዕክተኛው፤ ለነብዩ የዝምድና ባለቤቶች፤ ለየቲሞች፤ ለሚስኪኖች፤ ለመንገደኞችም የተገባ መሆኑን እወቁ:: በአላህና በዚያም እውነትና ውሸት በተለየበት ቀን ሁለቱ ቡድኖች በተገናኙበት (በበድር) ቀን ባገልጋያችን ላይ ባወረድነውም የምታምኑ እንደ ሆናችሁ ይህንን እወቁ:: አላህም በነገሩ ሁሉ ላይ ቻይ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 42, '42. (ሙስሊሞች ሆይ!) እናንተ በቅርቢቱ ዳርቻ ሁናችሁ እነርሱ ደግሞ በሩቂቱ ዳርቻ ሆነው የነጋዴዎቹም ቡድን ከናንተ በታች ሲሆኑ በሰፈራችሁ ጊዜ ያደረግንላችሁን አስታውሱ:: በተቃጠራችሁም ኖሮ ግን በቀጠሮው በተለያያችሁ ነበር:: ግን አላህ ሊሠራው የሚገባውን ነገር ሊፈጽምና የሚጠፋም ከአስረጅ መድረስ በኋላ እንዲጠፋ፤ ሕያው የሚሆንም ከአስረጅ መድረስ በኋላ ሕያው እንዲሆን ያለቀጠሮ አጋጠማችሁ:: አላህ በእርግጥ ሁሉን ሰሚና ሁሉንም አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ በሕልምህ እነርሱን ጥቂት አድርጎ ባሳየህ ጊዜ አስታውስ:: እነርሱን ብዙ አድርጎ ባሳየህም ኖሮ በፈራችሁና በነገሩ በተጨቃጨቃችሁ ነበር ግን አላህ አዳናችሁ:: እርሱ በደረቶች ውስጥ ያለን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህም ሊሠራው የሚገባን ነገር ይፈጽም ዘንድ በተጋጠማችሁ ጊዜ እነርሱን በዓይኖቻችሁ ጥቂት አድርጎ ያሳያችሁንና በዓይኖቻቸውም ላይ ያሳነሳችሁን (አስታውሱ)፡፡ ነገሮቹም ሁሉ ወደ አላህ ብቻ ይመለሳሉ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 45, '45. እናንተ ያመናችሁ ሆይ! ሰራዊትን በገጠማችሁ ጊዜ እርጉ (መክቱ):: አላህንም በብዙው አውሱ:: በእርግጥ ትድናላችሁና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 46, '46. (ሙስሊሞች ሆይ!) አላህንና መልዕክተኛውን ታዘዙ :: አትጨቃጨቁም ትፈራላችሁና ኃይላችሁም ትሄዳለችና:: ታገሡም አላህ በእርዳታው ከትዕግሥተኞች ጋር ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 47, '47. እንደ እነዚያ ለትዕቢትና ለሰዎች ይዩልኝ ሲሉ ከአላህም መንገድ ለማገድ ከሀገራቸው እንደወጡት ሰዎች አትሁኑ:: አላህ በሚሠሩት ሁሉ በእውቀቱ ከባቢ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 48, '48. ሰይጣንም ሥራዎቻቸውን ለእነርሱ ባሳመረላቸውና «ዛሬ ለእናንተ ከሰዎች አሸናፊ የላችሁም:: እኔም ለእናንተ ረዳት ነኝ።» ባለ ጊዜም (የሆነውን አስታውስ):: ሁለቱ ቡድኖችም በተያዩ ጊዜ ወደኋላው አፈገፈገ:: «እኔ ከናንተ ንጹህ ነኝ:: እኔ እናንተ የማታዩትን አያለሁ:: እኔ አላህን እፈራለሁ:: አላህም ቅጣተ ብርቱ ነው።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) አስመሳዮችና እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸው ሰዎች «እነዚህን ሙስሊሞች ሃይማኖታቸው አታለላቸው።» ባሉ ጊዜ (የነበረውን አስታውስ):: በአላህ ላይ የሚጠጋ (ሁልጊዜም ያሸንፋል):: አላህ ሁሉንም አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያንም በአላህ የካዱትን ሰዎች መላዕክት ፊቶቻቸውንና ጀርቦቻቸውን እየመቱ «የቃጠሎን ስቃይ ቅመሱ።» እያሉ በሚገድሏቸው ጊዜ ብታይ ኖሮ (አስደንጋጭን ነገር ታይ ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 51, '51. «ይህ እጆቻችሁ ባስቀደሙት ምክንያት አላህ ለባሮቹ በዳይ ባለመሆኑ ነው።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 52, '52. የእነዚያ ሰዎች ልማድ እንደ ፈርዖን ቤተሰብና እንደነዚያም ከእነርሱ በፊት እንደ ነበሩት ህዝቦች ልማድ ነው:: በአላህ አናቅጽ ካዱ:: አላህም በኃጢአቶቻቸው ያዛቸው:: አላህ ሀይለኛና ቅጣተ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 53, '53. ይህ ቅጣት አላህ በሕዝቦች ላይ የለገሰውን ጸጋ በነፍሶቻቸው ያለውን ነገር እስከሚለውጡ ድረስ የማይለውጥ በመሆኑ ምክንያት ነው:: አላህም ሁሉን ሰሚና ሁሉንም አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 54, '54. እንደ ፈርዖን ቤተሰቦችና እንደእነዚያ ከእነርሱ በፊት እንደ ነበሩት ልማድ (እስከሚለውጡ ድረስ አይለውጥባቸዉም)። በጌታቸው ታዓምራት አስተባበሉና በኃጢአቶቻቸው አጠፋናቸው:: የፈርዖንን ቤተሰቦች አስመጥናቸው:: ሁሉም በዳዮች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 55, '55. ከሚንቀሳቀሱ እንስሳዎች ሁሉ አላህ ዘንድ ይበልጥ ክፉዎቹ እነዚያ የካዱት ሰዎች ናቸው:: ስለዚህ እነርሱ አያምኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 56, '56. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ከእነርሱ ቃል ኪዳን የያዝክባቸውና ከዚያም በየጊዜው ቃል ኪዳናቸውን የሚያፈርሱ ናቸው:: እነርሱም አይጠነቀቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 57, '57. (መልዕክተኛችን ሙሐመድ ሆይ!) በጦር ላይ ብታገኛቸው በእነርሱ ቅጣት ምክንያት ሌሎቹ ከሓዲያን ይገሠጡ ዘንድ ከኋላቸው ያሉትን በትንባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 58, '58. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሕዝቦችም በኩል ክህደትን ብትፈራ የቃል ኪዳኑን መፍረስ በማወቅ በኩል ተመሳሳይ ሆናችሁ ቃል ኪዳናቸውን ወደ እነርሱ ጣልላቸው:: አላህ ከዳተኞችን ሁሉ አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 59, '59. እነዚያም የካዱት ከአላህ ቅጣት ያመለጡ መሆናቸውን አያስቡ:: እነርሱ አያቅቱምና (አያሸንፉምና)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 60, '60. (እናንተ ያመናችሁ ሆይ!) ለእነርሱ ከማንኛውም ኃይልና ከታጀቡ ፈረሶች የቻላችሁትን ሁሉ በእርሱ የአላህን ጠላትና ጠላታችሁን ሌሎችንም ከእነርሱ በስተቀር ያሉትን የማታውቋቸውን አላህ ብቻ የሚያውቃቸውን አስመሳዮች የምታሸብሩበት ስትሆኑ አዘጋጁላቸው:: ከማንኛዉም ነገር በአላህ መንገድ የምትለግሱት ምንዳው ወደ እናንተ በሙሉ ይሰጣል:: እናንተ ቅንጣት አትበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 61, '61. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ ዕርቅ ቢያዘነብሉ አንተም ወደ እርቁ ተዘንበልና በአላህ ላይ ብቻ ተመካ:: እነሆ እርሱ ሁሉን ሰሚ እና ሁሉን አዋቂው ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 62, '62. (መልዕክተኛችን ሙሐመድ ሆይ!) ሊያታልሉህ ቢፈልጉ አላህ በቂህ ነው:: እርሱ ያ በእርዳታውና በምዕምናን ያበረታህ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 63, '63. በልቦቻቸውም መካከል ያስማማ ነው፡፡ (መልዕክተኛችን ሙሐመድ ሆይ!) በምድር ያለውን ሁሉ ሀብት ብትለገስ ኖሮ እንኳን በልቦቻቸው መካከል ባላስማማህ ነበር:: ግን አላህ በመካከላቸው አስማማ:: እርሱ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 64, '64. አንተ ነብይ ሆይ! ለሁሉ ነገር በቂህ አላህ ነው:: ለተከተሉህም ምዕምናን በቂያቸው አላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 65, '65. አንተ ነብይ ሆይ! አማኞችን ጠላቶቻቸውን በመዋጋት ላይ አደፋፍራቸው:: ከናንተ ውስጥ ሃያ ታጋሾች ቢኖሩ ሁለት መቶን ያሸንፋሉ:: ከናንተም መካከል መቶ ሰዎች ቢኖሩ ከእነዚያ ከካዱት ሕዝቦች መካከል አንድ ሺሕን ያሸንፋሉ:: ምክንያቱም እነርሱ የማይገነዘቡ ህዝቦች ናቸዉና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 66, '66. አሁን አላህ ከናንተ ላይ አቀለለላችሁ:: በእናንተ ውስጥም ድክመት መኖሩን አወቀ:: ስለዚህ ከናንተ መካካል መቶ ታጋሾች ቢኖሩ ሁለት መቶን ያሸንፋሉ:: ከናንተም አንድ ሺህ ቢኖሩ በአላህ ፍቃድ ሁለት ሺዎችን ያሸንፋሉ:: አላህ ከታጋሾቹ ጋር ነዉና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 67, '67. ለነብይ በምድር ላይ ጠላቶቹን እስኪያደክም ድረስ ለእርሱ ምረኮኞች ሊኖሩት አይገባም:: (አማኞች ሆይ!) የቅርቢቱን ዓለም ጠፊ ጥቅም ትፈልጋላችሁ:: አላህ መጨረሻይቱን ይሻል:: አላህም ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 68, '68. ከአላህ ያለፈ ውሳኔ ባልነበረ ኖሮ በወሰዳችሁት ቤዛ ከባድ ቅጣት በነካችሁ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 69, '69. (አማኞች ሆይ!) ያ! ከጠላት የማረካችሁትን ሀብት የተፈቀደና መልካም ሲሆን ብሉ:: አላህንም ፍሩ:: አላህም መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 70, '70. አንተ ነብይ ሆይ! ከምርኮኞች መካከል በእጆቻችሁ ላሉት «አላህ በልቦቻቸው ውስጥ በጎን ነገር (እምነትን) ቢያውቅ ከተወሰደባችሁ የተሻለን ይሰጣችኋል:: ለእናንተም ይምራችኋል:: አላህም መሓሪና አዛኝ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 71, '71. (መልዕክተኛችን ሙሐመድ ሆይ!) ሊክዱህ ቢፈልጉ ከዚህ በፊት አላህን በእርግጥ ከድተዋል:: እናም ከእነርሱ አስመችቶሃል:: አላህም ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 72, '72. እነዚያ በአላህ አምነው ለእርሱም ሲሉ ከሀገራቸው የተሰደዱ በአላህ መንገድ ላይም በገንዘቦቻቸውና በነፍሶቻቸው የታገሉ እና እነዚያም ስደተኞቹን ያስጠጉና የረዱ ሰዎች እነዚያ ከፊሎቻቸው ለከፊሉ ረዳቶች ናቸው:: እነዚያ አምነውም ያልተሰደዱ ሰዎች ደግሞ ለአላህ ብለው እስከሚሰደዱ ድረስ ከእነርሱ ምንም ዝምድና የላችሁም:: በሃይማኖት እርዳታን ቢፈልጉባችሁ በእናንተና በእነርሱ መካከል ቃል ኪዳን ባላችሁ ሕዝቦች ላይ ካልሆነ በስተቀር በእናንተ ላይ እነርሱን መርዳት አለባችሁ:: አላህ የምትሠሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 73, '73. እነዚያም በአላህ የካዱ ሰዎች ከፊሎቻቸው ለከፊሉ ረዳቶች ናቸው:: (ከምዕምናን ጋር መረዳዳትን ከከሓዲያን መቆራረጥን) ባትሠሩት በምድር ላይ ሁከትና ታላቅ ጥፋት ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 74, '74. እነዚያ አምነው ለእርሱም ሲሉ የተሰደዱት፤ በአላህ መንገድ ላይም የታገሉ እና እነዚያም ያስጠጉና የረዱ እነዚያ ትክክለኛ አማኞች እነርሱው ናቸው:: ለእነርሱም ምሕረትና የከበረ ሲሳይ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (8, 75, '75. (እናንተ ያመናችሁ ሆይ!) እነዚያ በኋላ ያመኑና ከሀገራቸው የተሰደዱ ከናንተም ጋር ሆነው የታገሉ እነዚያ ከናንተው ናቸው:: የዝምድናዎች ባለቤቶች በአላህ መጽሐፍ ከፊሎቻቸው ከከፊሉ ለመውረስ የተገቡ ናቸው። አላህ ሁሉን ነገር አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 1, '1.(ሙስሊሞች ሆይ! ይህ) ከአላህና ከመልዕክተኛው ወደ እነዚያ ቃል ኪዳን ወደ ተጋባችኋቸው አጋሪዎች የሚደርስ የውል መሻሪያ መልዕክት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 2, '2. (ከሓዲያን ሆይ!) በምድር ላይ አራት ወሮችን ጸጥተኛ ስትሆኑ ተንቀሳቀሱ:: እናንተ ከአላህ ቅጣት የማታመልጡ መሆናችሁንና አላህ ከሓዲያንን አዋራጅ መሆኑንም እወቁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 3, '3. (ይህ) ከአላህና ከመልዕክተኛው በታላቁ ሐጅ ቀን የወጣ አላህ እና መልዕክተኛው ከአጋሪዎቹ ንጹህ መሆናቸውን የሚገልፅ አዋጅ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ከክህደት ብትጸጸቱ እርሱ ለእናንተ በላጭ ነው:: ከእምነት ብትሸሹ ግን እናንተ አላህን የማታቅቱት መሆናችሁን እወቁ በማለት ወደ ሰዎች የሚደርስ ማስታወቂያ ነው:: እነዚያን በአላህ የካዱትን ሰዎች በአሳማሚ ቅጣት አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 4, '4. እነዚያ ከአጋሪዎቹ መካከል እነዚያ ቃል ኪዳን የተጋባችሁላቸውና ከዚያ ምንም ያላጎደሉባችሁ፤ በእናንተ ላይ ለማጥቃት አንድንም ያልተባበሩባችሁ ቃል ኪዳናቸውን እስከ ጊዜያቸው መጨረሻ ድረስ ሙሉላቸው:: አላህ ጥንቁቆችን ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 5, '5. የተከበሩት ወሮች ባለቁ ጊዜ አጋሪዎቹን ባገኛችሁባቸው ስፍራ ሁሉ ግደሏቸው:: ያዟቸዉም:: ክበቧቸዉም:: እነርሱንም ለመጠባበቅ ስትሉ በየኬላው ላይ ተቀመጡ:: ሆኖም ቢጸጸቱ፤ ሶላትን በደንቡ ቢሰግዱና ግዴታ የሆነባቸውን የዘካ ምጽዋትን በትክክል ከሰጡ መንገዳቸውን ልቀቁላቸው:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) ከአጋሪዎች መካከል አንዱ ጥገኝነትን ቢጠይቅህ የአላህን ቃል ይሰማ ዘንድ አስጠጋው:: ከዚያ ወደ ሰላም ማግኛው ስፍራ አድርሰው:: ይህም የሆነው እነርሱ የማያውቁ ህዝቦች በመሆናቸው ነው ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 7, '7. ለአጋሪዎች ከአላህና ከመልዕክተኛው ዘንድ የሰላም ቃል ኪዳን እንዴት ይኖራቸዋል? እነዚያ በተከበረው መስጊድ ዘንድ ቃል ኪዳን የገባችሁላቸው ሰዎች ብቻ ሲቀሩ:: እነዚያማ በቃል ኪዳናቸው ለእናንተ ቀጥ እስካሉላችሁ ድረስ ለእርሱም በቃላችሁ ቀጥ በሉላቸው:: አላህ ጥንቁቆችን ሁሉ ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 8, '8. በእናንተ ላይ ቢያይሉ ዝምድናንና ቃልኪዳንን የማይጠብቁ ሰዎች ሲሆኑ እንዴት ከአላህና ከመልዕክተኛው ዘንድ ቃልኪዳን ይኖራቸዋል? በአፎቻቸው ይሸነግሏችኋል:: ልቦቻቸው ግን እምቢ ይላሉ:: አብዛኞቻቸዉም አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 9, '9. በአላህ አናቅጽ ጥቂትን ዋጋ ገዙ:: እናም ከመንገዱም ሰዎችን አገዱ:: እነርሱ ይሰሩት የነበሩት ሥራም እጅግ በጣም ከፋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 10, '10. በትክክለኛ አማኞች ላይ ዝምድናንም ሆነ ቃል ኪዳንን አይጠብቁም:: ወሰን አላፊዎች ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 11, '11. (ሙስሊሞች ሆይ!) ቢጸጸቱ፤ ሶላትንም ደንቡን አሟልተው ቢሰገዱና ግድ የሆነባቸውንም ዘካን በትክክል ቢሰጡ የእምነት ወንድሞቻችሁ ናቸው:: ለሚያውቁ ህዝቦች ሁሉ አናቅጽን እናብራራለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 12, '12. ከቃልኪዳናቸው በኋላ መሀላዎቻቸውን ካፈረሱና ሃይማኖታችሁን ካንቋሸሹ የክህደት መሪዎች ከክህደት ተግባራቸው ይከለከሉ ዘንድ ተዋጓቸው:: እነርሱ ምንም ቃልኪዳን የላቸዉምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 13, '13. እነዚያ መሀላዎቻቸውን ያፈረሱትን፤ መልዕክተኛውንም ከሀገር ለማውጣት ያሰቡትን ህዝቦች እነርሱ ለመጀመሪያ ጊዜ ጦርነት የጀመሯችሁን ህዝቦች ሲሆኑ ለምን አትወጓቸዉም? ትፈሯቸዋላችሁን? ትክክለኛ አማኞች ከሆናችሁ አላህን ይበልጥ ልትፈሩት የተገባው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 14, '14. (ሙስሊሞች ሆይ!) ተጋደሏቸው:: አላህ በእጆቻችሁ ያሰቃያቸዋል:: ያዋርዳቸዋልም:: በእነርሱም ላይ ይረዳችኋል:: የአማኝ ህዝቦችን ልቦችንም ያሽራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 15, '15. የልቦቻቸውንም ቁጭት ያስወግዳል:: አላህ ከሚፈልገው ሰው ላይ ጸጸትን ይቀበላል:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 16, '16. አላህ ከመካከላችሁ በትክክል ለአላህ መስዋዕት የሚከፍሉትንና (የታገሉትንና) ከአላህ፣ ከመልዕክተኛውና ከትክክለኛ አማኞች በስተቀር አማካሪ ያልያዙትን ክፍሎች ለይቶ ሳያውቅ (ሳይገልጽ) የምትተዉ መሰላችሁን? አላህ የምትሰሩትን ሁሉ ዉስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 17, '17. አጋሪዎች በራሳቸው ላይ በክህደት የሚመሰክሩ ሲሆኑ የአላህን መስጊዶች ሊንከባከቡ አይገባቸዉም:: እነዚያ ሥራዎቻቸው የተበላሹና በአኼራም በእሳት ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 18, '18. የአላህን መስጊዶች የሚንከባከቡ ሰዎች በአላህና በመጨረሻው ቀን ያመኑ፤ ሶላትንም ደንቡን ጠብቀው የሚሰግዱ፤ ግዴታ ምጽዋትን በትክክል የሚሰጡ፤ ከአላህ ሌላ ምንንም ያልፈሩ ሰዎች ብቻ ናቸው:: እንዲህ ያሉት ሰዎች ቀናዉን መስመር ከያዙት መሆናቸው ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 19, '19. ሰዎችን ማጠጣትንና የተከበረውን መስጊድ መንከባከብን፤ በአላህና በመጨረሻው ቀን እንዳመነና በአላህ መንገድም እንደታገለ ሰው እምነትና ትግል አደረጋችሁትን? በአላህ ዘንድ ፈጽሞ ሁለቱ ተግባሮች አይስተካከሉም:: አላህ በዳይ ህዝቦችን ሁሉ ወደ ቀጥተኛው መንገድ አይመራምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 20, '20. እነዚያ በአላህ ያመኑት ከየአገሮቻቸዉም የተሰደዱት በገንዘቦቻቸውና በነፍሶቻቸዉም በአላህ መንገድ ላይ የታገሉት አላህ ዘንድ በደረጃ በጣም የላቁ ናቸው:: ፍላጎታቸውን ያገኙ ማለትም እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 21, '21. ጌታቸው ከእርሱ በሆነው እዝነትና ውዴታ፤ በውስጧ የማያቋርጥ መጠቀሚያ ባለባት ገነትም ያበስራቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 22, '22. በውስጧ ዘላለም ዘውታሪዎች ሲሆኑ ያበስራቸዋል:: አላህ እርሱ ዘንድ ታላቅ ምንዳ አለና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 23, '23. እናንተ ያመናችሁ ሆይ! አባቶቻችሁንና ወንድሞቻችሁን ክህደትን ከእምነት አብልጠው ከወደዱ ወዳጆች አድርጋችሁ አትያዟቸው:: ከናንተ መካከል እነርሱን ወዳጅ የሚያደርጓቸው ሁሉ በዳዮች ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) አባቶቻችሁ፤ ወንዶች ልጆቻችሁ፤ ወንድሞቻችሁ፤ ሚስቶቻችሁ ዘመዶቻችሁ፤ የሰበሰባችኋቸው ሀብቶች፤ መክሰሯን የምትፈሯት ንግድና የምትወዷቸው መኖሪያዎች በእናንተ ዘንድ ከአላህ፤ ከመልዕክተኛውና በእርሱ መንገድ ከመታገል ይበልጥ የተወደዱ ከሆኑ አላህ ጉዳዩን እስከሚያመጣ ድረስ ተጠባበቁ በላቸው:: አላህ አመጸኞች ህዝቦችን ሁሉ አይመራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 25, '25. (ሙስሊሞች ሆይ!) አላህ በብዙ የጦር ሜዳዎች ላይ እገዛውን ለግሶላችኋል:: የሁነይንም ቀን ብዛታችሁ ባስደነቀቻችሁና ለእናንተም ብዛት ምንም ባልጠቀመቻችሁ ጊዜ ምድርም ከስፋቷ ጋር በጠበበቻችሁና ከዚያ ተሸናፊዎች ሆናችሁም በዞራችሁ ጊዜ ረዳችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 26, '26. ከዚያም አላህ እርጋታውን በመልዕክተኛውና በምዕመናኖች ላይ አወረደ:: ያላያችኋቸውንም ሰራዊት አወረደ:: እነዚያን የካዱትንም ሰዎች በመግደልና በመማረክ አሰቃየ:: ይህም የከሓዲያን ፍዳ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 27, '27. ከዚያም ከዚህ በኋላ አላህ ከሚፈልገው ሰው ላይ ጸጸትን ይቀበላል:: አላህ እጅግ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 28, '28. እናንተ ያመናችሁ ሆይ! በአላህ አጋሪዎች እርኩሶች ብቻ ናቸው:: እናም ከዚህ ዓመታቸው በኋላ ወደ ተከበረው መስጊድ እንዳይቀርቡ። ድህነትንም ብትፈሩ አላህ ቢፈልግ ከችሮታው በእርግጥ ያከብራችኋል:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 29, '29. (ሙስሊሞች ሆይ!) ከእነዚያ መጽሐፍን ከተሰጡ ሰዎች መካከል እነዚያን በአላህና በመጨረሻው ቀን የማያምኑትን ክፍሎች አላህና መልዕክተኛው እርም ያደረጉትንም እርም የማያደርጉትን፤ እውነተኛውንም ሃይማኖት የማይቀበሉትን የተዋረዱ ሆነው ግብርን በእጆቻቸው እስከሚሰጡ ድረስ ተዋጓቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 30, '30. አይሁድ «ኡዘይር የአላህ ልጅ ነው።» አሉ:: ክርስቲያኖችም «አል-መሲህ የአላህ ልጅ ነው።» አሉ:: ይህ በአፎቻቸው የሚናገሩት ጸያፍ ቃላቸው ነው:: የእነዚያን ከእነርሱ በፊት የካዱትን (ሰዎች) ቃል ያመሳስላሉ:: አላህ ያጥፋቸው:: ከእውነት እንዴት ያፈነግጣሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 31, '31. አይሁድና ክርስቲያኖች ከእርሱ በስተቀር ሌላ አምላክ የሌለውን አንዱን አምላክ አላህን ብቻ ሊገዙ እንጂ ያልታዘዙ ሲሆኑ ሊቃውንቶቻቸውን፤ መነኮሳቶቻቸውንና የመርየምን ልጅ አልመሲሕንም ከአላህ ሌላ አማልክት አድርገው ያዙ:: ከእርሱ በስተቀር ትክክለኛ አምላክ የለም:: አላህ ግን ከሚያጋሩት ሁሉ የጠራ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 32, '32. ከሓዲያን የአላህን ብርሃን በአፎቻቸው ለማጥፋት ይፈልጋሉ:: እርሱ (አላህ) ከሓዲያን ቢጠሉም እንኳ ብርሃኑን መሙላትን እንጂ ሌላን አይሻም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 33, '33. አላህ ያ አጋሪዎቹ ቢጠሉም ከሃይማኖት ሁሉ በላይ ይፋ ያደርገው ዘንድ መልዕክተኛው ሙሓመድን በቅን መንገድና በእውነተኛ ሃይማኖት ላይ አድርጎ የላከው ብቸኛ አምላክ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 34, '34. እናንተ ያመናችሁ ሆይ! ከሊቃውንትና ከመነኮሳት ብዙዎቹ የሰዎችን ገንዘቦች በውሸትም ይበላሉ:: ከአላህም መንገድም ሰዎችን ያግዳሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያንም ወርቅንና ብርን የሚያደልቡትን በአላህም መንገድ ላይ የማያወጧቸውን ሰዎች በአሳማሚ ቅጣት አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 35, '35. (በብሩና በወርቁ) ላይ በገሀነም እሳት ውስጥ በሚግሉበትና ግንባሮቻቸውም፣ ጎኖቻቸውም፣ ጀርቦቻቸውም በእርሱ በሚተኮሱበት ቀን አሳማሚ በሆነ ቅጣት አብስራቸው:: «ይህ ለነፍሶቻችሁ ያደለባችሁት ነው:: ታደልቡት የነበራችሁትንም ቅመሱ።» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 36, '36. የወራት ቁጥር አላህ ዘንድ በአላህ መጽሐፍ ውስጥ ሰማያትንና ምድርን በፈጠረበት ቀን አስራ ሁለት ወር ብቻ ነው:: ከእነርሱም መካከል አራቱ የተከበሩ ወሮች ናቸው:: ይህ ቀጥተኛው ሃይማኖት ነው:: በእነርሱ ውስጥም (ክብሮቻቸውን በመጣስ) ነፍሶቻችሁን አትበድሉ:: አጋሪዎችንም በአንድ ላይ ሆነው እንደሚጋደሏችሁ በአንድ ላይ ሆናችሁ ተጋደሏቸው:: አላህ በእርዳታው እርሱኑ ከሚፈሩት ጋር መሆኑን እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 37, '37. የአንዱን ወር ክብር ወደ ሌላው ማዘግየት በክህደት ላይ ክህደትን መጨመር ነው:: በዚህ ተግባር ላይ እነዚያ በአላህ የካዱት (ሰዎች) ይሳሳቱበታል:: በአንደኛው ዓመት የተፈቀደ ያደርጉታል:: በሌላው ዓመት ደግሞ ያወግዙታል:: ይህም አላህ ያከበራቸውን ወሮች ቁጥር ሊሞሉበትና አላህ እርም ያደረገውን ደግሞ የተፈቀደ ሊያደርጉበት ነው:: መጥፎ ሥራዎቻቸው ለእነርሱ ተዋበላቸው:: አላህ ከሓዲያን ህዝቦችን ወደ ቀናው መንገድ አይመራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 38, '38. እናንተ ያመናችሁ ሆይ! «በአላህ መንገድ ለመታገል ዝመቱ።» በተባላችሁ ጊዜ ወደ ምድር የምትወዘፉት ለምንድን ነው? የቅርቢቱን ህይወት ከመጨረሻይቱ ህይወት ይበልጥ ወደዳችሁን? የቅርቢቱ ህይወት ጥቅም ከመጨረሻይቱ ህይወት አንፃር ጥቂት እንጂ ምንም አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 39, '39. ( አማኞች ሆይ!) ለዘመቻ ባትወጡ አላህ አሳማሚ ቅጣት ይቀጣችኋል:: ከናንተ ሌላ የሆኑን ህዝቦችም ይለውጣል:: አላህን በምንም አትጎዱትምም:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 40, '40. (ሙስሊሞች ሆይ!) ነብዩ ሙሐመድን ባትረዱት እነዚያ በአላህ የካዱት ህዝቦች የሁለት ሰዎች ሁለተኛ ሆኖ ከመካ ባስወጡት ጊዜ አላህ ረድቶታል:: ሁለቱም በዋሻው ሳሉ ለጓደኛው «አትዘን አላህ ከእኛ ጋር ነውና» ባለ ጊዜ አላህ እርጋታውን በእርሱ ላይ አወረደ:: ባላያችኋቸዉም ሰራዊት አበረታው:: የእነዚያን በአላህ የካዱትን ሰዎች ቃል የበታች አደረገ:: የአላህ ቃል ግን የበላይ ነው:: አላህ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 41, '41.(አማኞች ሆይ!) ቀላሎችም ከባዶችም ኾናችሁ ዝመቱ:: በአላህ መንገድ በገንዘቦቻችሁና በነፍሶቻችሁ ታገሉ :: ይህ ተግባር የምታውቁ ከሆናችሁ ለእናንተ በጣም የተሻለ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) የጠራህባቸው ነገር ቅርብ ጥቅምና መካከለኛ ጉዞ በሆነ ኖሮ በተከተሉህ ነበር:: ግን በእነርሱ ላይ መንገዲቱ ራቀችባቸው:: «በቻልንም ኖሮ ከናንተ ጋር በወጣን ነበር» ሲሉ በአላህ ይምላሉ:: እራሳቸውን ለጥፋት (በውሸት) ይዳርጋሉ :: አላህ እነርሱ ውሸታሞች መሆናቸውን ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ! ) አላህ ይቅር ብሎሀል:: እነዚያ እውነተኞቹ እስከሚገለጹልህና ውሸታሞቹን ለይተህ እስከምታውቅ ድረስ ለእነርሱ ከዘመቻ እንዲቀሩ ለምን ፈቀድክላቸው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ በአላህና በመጨረሻው ቀን የሚያምኑት በገንዘቦቻቸውና በነፍሶቻቸው ከመታገላቸው ለመቅረት ፈቃድን አይጠይቁህም:: አላህም በትክክል የሚፈሩትን ሰዎች ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ፈቃድ የሚጠይቁህ እነዚያ በአላህና በመጨረሻው ቀን የማያምኑት፤ ልቦቻቸው የተጠራጠሩት ሰዎች ብቻ ናቸው:: እነርሱም በጥርጣሬያቸው ውስጥ ይዋልላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ ዘመቻ መውጣት ባሰቡ ኖሮ ለእርሱ ዝግጅትን ባሰናዱ ነበር:: ግን አላህ ለመውጣት እንቅስቃሴያቸውን ጠላውና አሰነፋቸው:: «ከተቀማጮቹ ጋር ተቀመጡ።» ተባሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 47, '47. (አማኞች ሆይ!) ከናንተ ጋር በወጡ ኖሮ ጥፋትን እንጂ አይጨምሩላችሁም ነበር:: ሁከትንም የሚፈልጉላችሁ ሲሆኑ በመካከላችሁ ነገርን በማሳበቅ ይቻኮሉ ነበር:: በእናንተ ውስጥ ለእነርሱ አዳማጮች አሏቸው:: አላህም በዳዮችን አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱ ጠይዎች ሲኾኑ እውነቱ እስከመጣና የአላህም ትዕዛዝ እስከተገለጸ ድረስ ከዚህ በፊት ሁከትን በእርግጥ ፈለጉ፡፡ ነገሮችንም ሁሉ አገላበጡልህ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 49, '49. ከእነርሱም ውስጥ «ፍቀድልኝ አትሞክረኝ» የሚል ሰው አለ። (ሙስሊሞች) አስተውሉ! እነኝህ ሰዎች በመከራ ውስጥ ወደቁ:: ገሀነም ከሓዲያንን ከባቢ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) መልካም ነገር ቢያገኝህ ያስከፋቸዋል:: መከራ ቢያገኝህ ግን «ፊቱንም ይህን ፈርተን የግል ጥንቃቄያችንን ይዘናል።» ይላሉ። ተደሳቾች ሆነዉም ይሸሻሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ለእኛ የጻፈልን እንጂ ሌላ አይነካንም:: እርሱ ረዳታችን ነው:: ምዕምናን በአላህ ላይ ብቻ ይመኩ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእኛ ላይ ከሁለቱ መልካሞች አንደኛዋን እንጂ ሌላን ትጠባበቃላችሁን? እኛም አላህ ከእርሱ በሆነው ቅጣት ወይም በእጆቻችን የሚያጠፋችሁ መሆኑን በእናንተ ላይ እንጠባበቃለን:: ተጠባበቁ:: እኛም ከናንተው ጋር ተጠባባቂዎች ነንና።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) «ወዳችሁም ሆነ ጠልታችሁ ለግሱ ከናንተ ተቀባይ የላችሁም:: እናንተ አመጸኞች ህዝቦች ናችሁና።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 54, '54. ልግስናዎቻቸውን ከእነርሱ ተቀባይነት እንዳይኖራቸው ያደረገው በአላህና በመልዕክተኛው የካዱ፤ ሶላትንም ስልቹዎች ሆነው እንጂ የማይሰግዱ፤ እነርሱም ጠይዎች ሆነው እንጂ የማይሰጡ ከመሆናቸው በስተቀር ሌላ ነገር አልከለከላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 55, '55. (መልዕክተኛችን ሙሐመድ ሆይ!) ገንዘቦቻቸውና ልጆቻቸው አይድነቁህ:: አላህ የሚሻው በቅርቢቱ ህይወት በእነርሱ (በገንዘቦቻቸውና በልጆቻቸው) ሊቀጣቸው ነፍሶቻቸዉም ከሓዲያን ሆነው ሊሞቱ ብቻ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 56, '56. እነርሱም ከናንተ ጋር ለመሆናቸው በአላህ ይምላሉ:: እነርሱ ግን ከናንተ ጋር አይደሉም:: ይልቁንም እነርሱ አጋሪዎችን ያገኘው ነገር እንዳያገኛቸው የሚፈሩ ህዝቦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 57, '57. (ሙስሊሞች ሆይ!) መጠጊያ ወይም መሸሸጊያ ዋሻዎችን ወይም መግቢያ ቀዳዳዎችን ባገኙ ኖሮ በፍጥነት ወደ እርሱ በሸሹ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 58, '58. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ መካከል በምጽዋቶች ክፍፍል ዙሪያ የሚዘልፉህ ሰዎች አሉ:: ከእርሷም የሚሹትን ያህል ቢሰጡ ይደሰታሉ:: ከእርሷ ምንም ካልተሰጣቸው ግን ይጠላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 59, '59. እነርሱም አላህና መልእክተኛው የሰጣቸውን በወደዱ፤ «አላህ በቂያችን ነው አላህ ከችሮታው በእርግጥ ይሰጠናል፣ መልክተኛውም (ይሰጠናል) እኛ ወደ አላህ ከጃዮች ነን።» ባሉ ኖሮ ለነርሱ በተሸላቸው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 60, '60. ግዴታ ዘካን የሚከፈሉት ለድሆች፤ ለችግረኞች፤ በእርሷም ላይ ለሚሰሩ ሠራተኞች፤ ልቦቻቸው በኢስላም ለሚለማመዱት ወገኖች፤ ጫንቃዎችን (ባሪያዎች) ነጻ ለማውጣት፤ ባለ እዳ ለሆኑት፤ በአላህ መንገድም ለሚሰሩና (ስንቅ ላለቀበት) መንገደኛ ብቻ ነው:: ይህ ስርአት ከአላህ የተደነገገ ግዴታ ነው:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 61, '61. (መልዕክተኛችን ሙሐመድ ሆይ! ) ከአስመሳዮች መካከል ነብዩ ሙሐመድን የሚያስቸግሩና «እርሱ እኮ ወሬ ሰሚ ነው።» የሚሉ አሉ። «ለእናንተ የበጎ ወሬ ሰሚ ነው:: በአላህ ያምናል:: አማኞችንም ያምናቸዋል:: ከናንተ መካከል ለእነዚያ በአላህ ላመኑት ሰዎችም እዝነት ነው።» በላቸው:: እነዚያ የአላህን መልዕክተኛ የሚያስቸግሩ ሰዎች ሁሉ አሳማሚ ቅጣት አለባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 62, '62. አላህንና መልዕክተኛውን ሊያስወድዱ ሲገባቸው እናንተን ሊያስወድዷችሁ ዘንድ በአላህ ይምሉላችኋል። ትክክለኛ አማኞች ከሆኑ (ግን አላህንና መልዕክተኛው ሊያስወድዱ ይገባቸዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 63, '63. አላህንና መልዕክተኛውን የሚከራከር ሰው ሁሉ በውስጡ ዘውታሪ ሲሆን የተዘጋጀችለት የገሀነም እሳት መሆኑን አያውቁምን? ይህ ደግሞ ታላቅ ውርደት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 64, '64. (መልዕክተኛችን ሙሐመድ ሆይ!) አስመሳዮች በልቦቻቸው ውስጥ ያለውን ነገር ሁሉ የሚነግራቸው ምዕራፍ በእነርሱ ላይ መወረዱን ዘወትር ይፈራሉ:: «ተሳለቁ:: አላህ የምትፈሩትን ነገር ሁሉ ገላጭ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) ብትጠይቃቸው «እኛ የምንዘባርቅና የምንጫወት ሰዎች ብቻ ነበርን።» ይላሉ:: «በአላህ፤ በአናቅጹና በመልዕክተኛው ላይ ትቀልዱ ነበራችሁን?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 66, '66. (አስመሳዮች ሆይ!) አታመካኙ ከእምነታችሁ በኋላ በእርግጥ ክዳችኋልና:: ከናንተ አንዷን ቡድን ብንምር የሌላዋን ቡድን አባላት ግን ኃጢአተኞች በመሆናቸው እንቀጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 67, '67. የወንድ አስመሳዮችና የሴት አስመሳዮች ከፊሎቻቸው ከከፊሉ ናቸው:: በመጥፎ ነገር ያዛሉ:: ከደግ ነገርም ይከለክላሉ:: እጆቻቸውን ከልግስና ይሰበስባሉ:: ለአላህ መታዘዝን ረሱ (ተዉ):: ስለዚህ እርሱም ተዋቸው:: አስመሳዮቹ አመጸኞች ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 68, '68. የወንድ አስመሳዮችንና የሴት አስመሳዮችን እንዲሁም ከሓዲያንን የገሀነምን እሳት በውስጧ ዘውታሪዎች ሲሆኑ አላህ ቃል ገብቶላቸዋል:: እርሷ በቂያቸው ናት:: አላህ ረግሟቸዋል:: ለእነርሱም ዘውታሪ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 69, '69. (አስመሳዮች ሆይ!) ተግባራችሁ ልክ እንደእነዚያ ከናንተ በፊት እንደነበሩት ህዝቦች ነው:: ከናንተ ይበልጥ በሃይል የበረቱ በገንዘብና በልጆችም ከናንተ ይበልጥ የበዙ ነበሩ:: በእድላቸው ተጠቀሙ:: እነዚያም ከእናንተ በፊት የነበሩት በዕድላቸው እንደተጠቀሙ በዕድላችሁ ተጠቀማችሁ፡፡ እንደዘባረቁትም ዘባረቃችሁ:: እነዚያ ስራዎቻቸው በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም ተበላሸ:: ከሳሪዎቹም ማለት እነርሱው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 70, '70. የእነዚያ ከእነርሱ በፊት የነበሩት የኑህ፤ የዓድ፤ የሰሙድ፤ የኢብራሂም ህዝቦች፤ የመድየን ባለቤቶችና የተገልባጮቹም ከተሞች ታሪክ አልመጣላቸዉምን? መልዕክተኞቻቸው ግልጽ ተዓምራትን አመጡላቸው:: አላህ የሚበድላቸው አልነበረም:: ግን በራሳቸው ነፍሶቻቸውን የሚበድሉ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 71, '71. ወንድ አማኞችና ሴት አማኞች ከፊሎቻቸው ለከፊሉ ረዳቶች ናቸው:: በደግ ነገር ያዝዛሉ:: ከክፉም ነገር ይከለክላሉ:: ሶላትን ይሰግዳሉ:: ዘካን ይሰጣሉ:: አላህንና መልዕክተኛውን ይታዘዛሉ:: እነዚያን አላህ በእርግጥ ያዝንላቸዋል:: አላህ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 72, '72. አላህ የወንድ ትክክለኛ አማኞችንና የሴት ትክክለኛ አማኞችን ከስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲሆኑ በመኖሪያ ገነቶችም ውስጥ መልካም መኖሪያ ቤቶችን ቃል ገብቶላቸዋል:: ከአላህ የሆነው ውዴታ ደግሞ ከሁሉ የበለጠ ነው:: ይህ እርሱ ታላቅ ዕድል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 73, '73. አንተ ነብዩ ሆይ! ከሓዲያንንና አስመሳዮችን ታገል:: በእነርሱ ላይም ጨክን:: መኖሪያቸዉም ገሀነም ናት:: መመለሻይቱም በጣም ከፋች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 74, '74. ምንም ያላሉ ለመሆናቸው በአላህ ይምላሉ:: ግን የክህደትን ቃል በእርግጥ አሉ:: ከእስልምናቸዉም በኋላ ካዱ:: ያላገኙትንም ነገር አሰቡ:: አላህና መልዕክተኛው ከችሮታው ያከበራቸው መሆኑን እንጂ ሌላን አልጠሉም:: ቢጸጸቱም ለእነርሱ የተሻለ ይሆናል:: ቢሸሹም አላህ በቅርቢቱና በመጨረሻይቱ ዓለም አሳማሚን ቅጣት ይቀጣቸዋል:: ለእነርሱም በምድር ውስጥ ምንም ወዳጅና ረዳት የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 75, '75. ከእነርሱም መካከል አላህን «ከችሮታው ቢሰጠን በእርግጥ እንመጸውታለን::በእርግጥ ከመልካሞችም እንሆናለን።» ሲል ቃል የገባ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 76, '76. ከዚያም ከችሮታዉም በሰጣቸው ጊዜ ሰሰቱ:: እነርሱ ቃል ኪዳናቸውን የተው ሆነዉም ዞሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 77, '77. ለአላህ ቃል የገቡትን በማፍረሳቸውና ይዋሹትም በነበሩት ውሸት ምክንያት እስከሚገናኙት ቀን ድረስ ንፍቅናን በልቦቻቻው አስከተላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 78, '78. (አስመሳዮችን) አላህ ምስጢራቸውንና ውይይታቸውን የሚያውቅ መሆኑንና አላህም ሩቅ ነገሮችን ሁሉ በጣም አዋቂ መሆኑን አያውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 79, '79. እነዚያ ከምዕምናን በምጽዋቶች ፈቃደኛ የሆኑትን የችሎታቸውን ያክል እንጂ የማያገኙትን ሰዎች የሚያነውሩና በእነርሱ የሚሳለቁ ሰዎች ሁሉ አላህ ከእነርሱ ይሳለቅባቸዋል:: ለእነርሱም አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 80, '80. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነርሱ ምሕረትን ብትለምንላቸዉም ወይም ባትለምንላቸው ሁሉም እኩል ነው:: ለእነርሱ ሰባ ጊዜ ምህረትን ብትለምንላቸው እንኳን አላህ በፍጹም አይምራቸዉምና:: ምክንያቱም እነርሱ በአላህና በመልዕክተኛው ክደዋልና:: አላህ አመጸኞች ህዝቦችን አያቀናም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 81, '81. እነዚያ ከዘመቻ የቀሩት ሰዎች ከአላህ መልዕክተኛ በኋላ ተገንጥለው በመቀመጣቸው ተደሰቱ:: በአላህ መንገድ በገንዘቦቻቸውና በነፍሶቻቸው መታገልን ጠሉ:: ለሌሎችም «በሐሩር አትሂዱ» አሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «የገሀነም እሳት ትኩሳት በጣም ከዚህ የበረታ ነው።» በላቸው:: እናም የሚያውቁ ቢሆኑ ኖሮ ከዘመቻው አይቀሩም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 82, '82. አስመሳዮች ጥቂት ጊዜን ብቻ ይሳቁ:: ይሠሩት በነበሩት እኩይ ተግባር ምክንያት ዋጋ ብዙ ጊዜ ያለቅሳሉና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ መካከል ወደ ሆነችው ቡድን አላህ በሰላም ቢመልስህና ካንተ ጋር ዘመቻ ለመውጣት ቢያስፈቅዱህ «ከእኔ ጋር በፍጹም አትወጡም:: ከእኔም ጋር ጠላትን አትዋጉም:: እናንተ በመጀመሪያ ጊዜ መቀመጥን ወዳችኋልና:: ይልቁንም ከተቀማጮች ጋር ተቀመጡ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 84, '84. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ መካከል በሞተ በአንዱም ሰው ላይ ቢሆን ፈጽሞ አትስገድ:: በመቃብሩም ላይ አትቁም:: እነርሱ በአላህና በመልዕክተኛው ክደዋል:: እነርሱ አመጸኞችም ሆነው ሞተዋልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 85, '85. (መልዕክተኛችን ሙሐመድ ሆይ!) ገንዘቦቻቸውና ልጆቻቸው አይድነቁህ:: አላህ የሚፈልገው በቅርቢቱ ዓለም በገንዘቦቻቸውና በልጆቻቸው ሊቀጣቸውና ከሓዲያንም ሆነው ነፍሶቻቸው እንዲወጡ ሊያደርግ ብቻ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 86, '86. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ እመኑ:: ከመልዕክተኛው ጋር ሆናችሁ ታገሉ በማለት የቁርኣን ምዕራፍ በተወረደ ጊዜ ከእነርሱ የሰፊ ሀብት ባለቤቶች የሆኑት ሰዎች ለመቅረት ፈቃድ ይጠይቁሃል:: «ከተቀማጮቹ ጋር እንሁን ተወን» ይሉሃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 87, '87. በቤት ከሚቀሩት ወገኖች ጋር መሆናቸውን ወደዱ:: በልቦቻቸዉም ላይ (ዝገት) ታተመባቸው:: ስለዚህ እነርሱ አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 88, '88. ግን መልዕክተኛውና ከእርሱ ጋር ያመኑት ሰዎች በገንዘቦቻቸዉም በነፍሶቻቸዉም ታገሉ:: እነዚያም መልካሞች ሁሉ ለእነርሱ ብቻ የተዘጋጁ ናቸው:: እነዚያም እነርሱ ምኞታቸውን ያገኙ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 89, '89. አላህ ለእነርሱ በሥራቸው ወንዞች የሚፈሱባቸውን ገነቶችን በውስጣቸው ዘውታሪዎች ሲሆኑ አዘጋጅቶላቸዋል:: ይህ ታላቅ ማግኜት (እድል) ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 90, '90. ከአረብ ዘላኖች መካከል ይቅርታ ፈላጊዎቹ እንዲፈቀድላቸው መጡ:: እነዚያ አላህንና መልዕክተኛውን ያስተባበሉት ግን ተቀመጡ:: እነዚያን በአላህ የካዱት ሰዎች አሳማሚ ቅጣት በእርግጥ ይነካቸዋል (ያገኛቸዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 91, '91. በደካሞች ላይ፤ በበሽተኞች ላይ፤ በእነዚያም ለስንቅና ለትጥቅ የሚያወጡት ገንዘብ በማያገኙት ላይ ለአላህና ለመልዕክተኛው ፍጹም ታዛዦች ከሆኑ ወደ ዘመቻ ባይወጡም ኃጢአት የለባቸዉም:: በበጎ አድራጊዎች ላይ ምንም የመወቀሻ መንገድ የለባቸዉም:: አላህ መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 92, '92. (መልዕክተኛችን ሙሐመድ ሆይ!) በነዚያም መጓጓዣያ እንድትሰጣቸው ፈልገው ወደ አንተ በመጡ ጊዜ «እናንተን የምጭንበት (አጋሰስ) አላገኝም።» ያልካቸው ስትሆን የሚያወጡት ገንዘብ ባለማግኘታቸው ለማዘናቸው ዓይኖቻቸው እንባን እያፈሰሱ በዞሩት ላይ ምንም ወቀሳ የለባቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 93, '93. (መልዕክተኛችን ሙሐመድ ሆይ!) የሚወቀሱት እነዚያ ባለጸጋዎች ሆነው ሳሉ ለመቅረት ፈቃድ በሚጠይቁህ ሰዎች ላይ ብቻ ናቸው:: ከቀሪዎቹ ጋር መሆናቸውን ወደዱ:: አላህ በልቦቻቸው ላይ አተመባቸው:: ስለዚህ እነርሱ አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 94, '94. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነርሱ በተመለሳችሁ ጊዜ ምክንያቶቻቸውን ያቀርቡላችኋል:: «አታመካኙ እናንተን ፈጽሞ አናምንም:: አላህ ከወሬዎቻችሁ አስቀድሞ ነግሮናልና:: አላህና መልዕክተኛው ሥራችሁን ያያሉ:: ከዚያ ሩቅንና ቅርብን ሁሉ አዋቂ ወደ ሆነው አላህ ትመለሳላችሁ:: ወዲያዉም ትሠሩት የነበራችሁትን ሁሉ ይነግራችኋል።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 95, '95. (አማኞች ሆይ!) ከዘመቻ ወደ እነርሱ በተመለሳችሁ ጊዜ ጥፋታቸውን ይቅር እንድትሉሏቸው ለእናንተ በአላህ ይምላሉ:: እነርሱን ተዏቸው:: እነርሱ እርኩሶች ናቸውና:: ይሠሩትም በነበረው ኃጢአት መኖሪያቸው ገሀነም ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 96, '96. እነርሱ ትወዱላቸው ዘንድ ለእናንተ ይምሉላችኋል:: እናንተ ብትወዱላቸውም አላህ ከአመጸኛ ህዝቦች አይወድም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 97, '97. ዘላን አረቦች በክሕደትና በንፍቅና በጣም የበረቱ፤ አላህ በመልዕክተኛው ላይ ያወረደውን ህግጋት ባለማወቅም የተገቡ ናቸው:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 98, '98. ከዘለኖች መካከል በአላህ መንገድ የሚያወጣውን ገንዘብ እዳ አድርጎ የሚይዝና በእናንተ ላይ የጊዜን መገለባበጥ የሚጠባበቅ ሰው አለ:: በእነርሱ ላይ ጥፋቱ ይዙርባቸው:: አላህ ሁሉን ሰሚና ሁሉንም አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 99, '99. ከአረብ ዘላኖች መካከል በአላህና በመጨረሻው ቀን የሚያምን የሚሰጣቸውንም ምጽዋቶች አላህ ዘንድ መቃረቢያዎችና ወደ መልዕክተኛው ጸሎቶች መዳረሻ አድርጎ የሚይዝ ክፍል አለ:: አስተዉሉ! እርሷ ለእነርሱ በእርግጥ አቃራቢ ናት:: አላህ በችሮታው ውስጥ በገነቱ በእርግጥ ያስገባቸዋል:: አላህ መሓሪና አዛኝ ነውና ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 100, '100. ከስደተኞቹም ሆነ ከረዳቶቹ የመጀመሪያዎቹ ቀዳሚዎችና እነዚያም በበጎ ሥራ የተከተሏቸው ሰዎች አላህ የእነርሱን ተግባር ወዶላቸዋል:: እነርሱም ወደውለታል:: በሥሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸዉም ዘለዓለም ነዋሪዎች ሲሆኑ ለእነርሱ አዘጋጅቶላቸዋል:: ይህ ታላቅ እድለኛነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 101, '101. (መልዕክተኛችን ሙሐመድ ሆይ!) በዙሪያችሁም ካሉት የዐረብ ዘላኖች አስመሳዮች አሉ:: ከመዲና ሰዎችም በንፍቅና ላይ በማመጽ የዘወተሩ አሉ:: አታውቃቸዉም:: እኛ እናውቃቸዋለን:: ሁለት ጊዜ እንቀጣቸዋለን:: ከዚያ ወደ ታላቅ ቅጣት ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 102, '102. ሌሎችም ኃጢአቶቻቸውን የተናዘዙ መልካም ሥራንና ሌላን መጥፎ ሥራ የቀላቀሉ አሉ:: አላህ ጸጸታቸውን ሊቀበል ይከጀላል:: አላህ መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 103, '103. (መልዕክተኛችን ሙሐመድ ሆይ!) ከገንዘቦቻቸው የምታጠራቸውና የምታፋፋቸውን ምጽዋት ያዝ:: ለነሱም ዱኣ አድርግላቸው፡፡ ዱኣእህ ለእነሱ እርጋታ ነውና አላህም ሰሚ ዐዋቂ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 104, '104. አላህም እርሱ ከባሮቹ ንሰሃን የሚቀበልና ምጽዋቶችንም የሚወስድ፤ አላህ ብቸኛ ጸጸትን ተቀባይና አዛኝ መሆኑን አያውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 105, '105. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሥሩ:: አላህ መልዕክተኛውና አማኞችም ሥራችሁን በእርግጥ ያያሉና:: ሩቁንና ቅርቡን ሁሉ አዋቂ ወደ ሆነው አላህ በእርግጥ ትመለሳላችሁ:: ትሰሩት የነበራችሁትን ሁሉ ይነግራችኋል።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 106, '106. ሌሎችም የአላህን ውሳኔ ትዕዛዝ እንዲጠብቁ የተቆዩ ህዝቦች አሉ:: ይቀጣቸዋል ወይም ጸጸታቸውን ይቀበላቸዋል:: አላህ ሁሉን አዋቂና ጥበበኛ ነዉና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 107, '107. እነዚያም አማኞችን ለመጉዳት ክህደትንም ለማበረታታት በአማኞችም መካከል ለመለያየት ከአሁን በፊት አላህንና መልዕክተኛውን የተዋጋውን ሰው ለመጠባበቅ መስጊዱን የሠሩት ሰዎች ከእነርሱ ናቸው:: «መልካምን እንጂ ሌላ አልሻንም።» ሲሉ በእርግጥ ይምላሉ:: አላህ ደግሞ ውሸታሞች መሆናቸውን በእርግጥ ይመሰክራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 108, '108. (መልዕክተኛችን ሙሐመድ ሆይ!) በእርሱ ውስጥ በፍጹም አትስገድ:: ይልቁንም ከመጀመሪያ ቀን ይዞ በአላህ ፍራቻ ላይ የተመሠረተው (የቁባ ) መስጊድ በውስጡ ልትሰግዱበት የተገባው ነው:: በውስጡ መጥራራትን የሚወዱ ወንዶች አሉ:: አላህ ተጥራሪዎችን ይወዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 109, '109. አላህን በመፍራትና ውዴታውን በመፈለግ ላይ ግንቡን የመሠረተ ሰው ወይስ ጎርፍ በሸረሸረው ለመናድ በተቃረበ ገደል አፋፍ ላይ ግንቡን የመሠረተውና እርሱንም ይዞት ወደ ገሀነም እሳት ውስጥ የወደቀው ይበልጣልን? አላህ በደለኛ ሕዝቦችን አይመራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 110, '110. ያ የካቡት ግንባቸው ልቦቻቸው በሞት ካልተቆራረጡ በስተቀር በልቦቻቸው ውስጥ የመጠራጠር ምክንያት ከመሆን አይወገድም:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 111, '111. አላህ ከትክክለኛ አማኞች ነፍሶቻቸውንና ገንዘቦቻቸውን ገነትን ለእነርሱ በማድረግ ገዛቸው:: በአላህ መንገድ ላይ ይጋደላሉ:: ይገድላሉም:: ይገደላሉም:: በተውራት፤ በኢንጂልና በቁርኣንም የተነገረውን ተስፋ በእርሱ ላይ አረጋገጠ:: ከአላህ የበለጠ በቃል ኪዳኑ የሚሞላ ማን ነው? (ትክክለኛ አማኞች ሆይ!) በዚያም በእርሱ በተሻሻጣችሁበት ሽያጫችሁ ተደሰቱ:: ይህ ታላቅ ዕድል ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 112, '112. እነርሱ ተጸፃቾች፤ ተገዢዎች፤ አመስጋኞች፤ ፆመኞች፤ (በሶላት) አጎንባሾች፤ በግንባር ተደፊዎች፤ በበጎ ሥራ አዛዦች፤ ከክፉ ከልካዮች እና የአላህንም ሕግጋት ጠባቂዎች ናቸው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ትክክለኛ አማኞችንም አብስር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 113, '113. መልዕክተኛዉም ሆነ እነዚያ በእሱ ያመኑት ሰዎች ለአጋሪዎቹ የዝምድና ባለቤቶች ቢሆኑም እንኳ ከሓዲያን እነርሱ የእሳት ጓዶች መሆናቸው ከተገለጸላቸው በኋላ የአላህን ምሕረት ሊለምኑላቸው የሚገባ አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 114, '114. ኢብራሂምም ለአባቱ ምህረትን መለመኑ ቀድሞ ገብቶለት የነበረውን ቃል ለመሙላት እንጂ ለሌላ አልነበረም:: እናም የአላህ ጠላት መሆኑ በተገለጸለት ጊዜ ከእርሱ ራቀ:: (ተወው):: ኢብራሂም በእርግጥ አልቃሻ እና ታጋሽ ነበርና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 115, '115. አላህ ህዝቦችን ካቀናቸው በኋላ የሚጠነቀቁትን ነገር እሥከሚገልጽላቸው ድረስ ሳያውቁ በሰሩት ጥፋት ጥፋተኛ የሚያደርግ ጌታ አይደለም:: አላህ በነገሩ ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 116, '116. አላህ የሰማያትና የምድር ንግስና የእርሱ ብቻ ነው:: ህያው ያደርጋል:: ይገድላልም:: ለእናንተም ከእርሱ በስተቀር ጠባቂም ሆነ ወዳጅ የላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 117, '117. በመልዕክተኛው በስደተኞችና በረዳቶች በእነዚህም በችግሩ ጊዜ (በተቡክ ዘመቻ) ከእነርሱ የከፊሎቹ ልቦች ለመቅረት ሊዘነበሉ ከተቃረቡ በኋላ በተከተሉት ላይ አላህ በእርግጥ ጸጸታቸውን ተቀበለ:: ከዚያ ከእነርሱ ንሰሃ መግባታቸውን ተቀበለ:: እርሱ(አላህ ) ለእነርሱ ሩህሩህና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 118, '118. በእነዚያም ወደ ኋላ በቀሩት በሶስቱ ሰዎች ላይ ምድር ከስፋቷ ጋር በእነርሱ ላይ እስከምትጠብባቸው፤ ነፍሶቻቸዉም በእነርሱ ላይ እስከምትጠብባቸው፤ ከአላህም ወደ እርሱ ብቻ እንጂ ሌላ መጠጊያ አለመኖሩን እስከሚያረጋግጡ ድረስ በተቆዩት ላይ አላህ ጸጸትን ተቀበለ:: ከዚያም ይጸጸቱ ዘንድ ወደ ጸጸት መራቸው:: አላህ ጸጸትን ተቀባይና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 119, '119. እናንተ ያመናችሁ ሆይ! አላህን በትክክል ፍሩ:: ከእውነተኞቹም ጋር ሁኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 120, '120. የመዲና ሰዎችና በዙሪያቸው ያሉት የዘላን ዓረብ ህዝቦች ከአላህ መልዕክተኛ ጥሪ ወደ ኋላ ሊቀሩና ነፍሶቻቸውንም ከነፍሱ አብልጠው ሊወዱ አይገባቸዉም ነበር:: ይህም የሆነው ለእነርሱ መልካም ሥራ የሚጻፍላቸው ቢሆን እንጂ በአላህ መንገድ ላይ ጥምም ድካምም ርሀብም የማይነካቸው ከሓዲያንንም የሚያስቆጭን ስፍራ የማይረግጡ ከጠላትም የሚጎዳን ነገር (መግደል) የማያገኙ በመሆናቸው ነው:: አላህ የመልካም ሠሪዎችን ምንዳ አያጠፋምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 121, '121. ትንሽንም ትልቅንም ልግስና አይለግሱም ወንዝንም አያቋርጡም አላህ ይሠሩት ከነበረው የበለጠን ምንዳ ይመነዳቸው ዘንድ ለእነርሱ የሚጽፍላቸው ቢሆን እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 122, '122. ምእምናንም (ከነቢዩ ጋር ካልኾነ) በሙሉ ሊወጡ አይገባም፡፡ ከእነሱ ውስጥ ከየክፍሉ አንዲት ጭፍራ ለምን አትወጣም፡፡ (ሌሎቹ) ሃይማኖትን እንዲማሩና ወገኖቻቸው ወደነርሱ በተመለሱ ጊዜ እንዲጠነቀቁ ይገስጹዋቸው ዘንድ (ለምን አይቀሩም)፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 123, '123. እናንተ ያመናችሁ ሆይ! እነዚያን በአቅራቢያችሁ ያሉትን ከሓዲያን ተዋጉ:: በናንተ ውስጥ ብርታትን ያግኙ:: አላህም ከሚጠነቀቁት ጋር መሆኑን እወቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 124, '124. ምዕራፍ በተወረደ ጊዜ ከአስመሳዮች ውስጥ «ማንኛችሁ ነው ይህ ምዕራፍ እምነትን የጨመረለት?» የሚል ሰው አለ:: እነዚያ ያመኑት ሰዎች የሚደሰቱ ሲሆኑ እምነትን ጨመረላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 125, '125. እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸው ክፍሎች ግን በርክሰታቸው ላይ እርክሰትን ጨመረላቸው:: እነርሱም ከሓዲያን ሆነው ሞቱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 126, '126. በየዓመቱ አንድ ወይም ሁለት ጊዜ እነርሱ የሚሞከሩ መሆናቸውን አያዩምን? ከዚያ አይጸጸቱምን?እነርሱም አይገሰጹምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 127, '127. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱን የሚያወሳ ምዕራፍም በተወረደ ጊዜ «የሚያያችሁ (ሰው) አለን?» እያሉ ከፊሎቻቸው ወደ ከፊሉ ይመለከታሉ:: ከዚያ ተደብቀው ይሄዳሉ:: እነርሱ የማያውቁ ህዝቦች በመሆናቸው አላህ ልቦቻቸውን አዞረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 128, '128. (ሰዎች ሆይ!) ከጎሳችሁ ውስጥ የሆነ መቸገራችሁ በእርሱ ላይ ከባድ ጉዳይ የሆነበት፤ እናንተ እምነት እንዲኖራችሁ በጣም የሚጓጓና ለትክክለኛ አማኞችም ሩህሩህና አዛኝ የሆነ መልዕክተኛ (ሙሐመድ) መጣላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (9, 129, '129. (መልዕክተኛችን ሙሐመድ ሆይ!) «ቢያፈገፍጉ አላህ በቂዬ ነው:: ከእርሱ ሌላ አምላክ የለም:: በእርሱ ላይ ብቻ ተመካሁ:: እርሱም የታላቁ ዐርሽ ጌታ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 1, '1. አሊፍ፤ ላም፤ ራ፤ እነዚህ ጥበብ ከተሞላው መፅሀፍ አንቀፆች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎችን (ከሓዲያንን) አስፈራራ፤ እነዚያን ያመኑትን ደግሞ ከጌታቸው ዘንድ መልካም ምንዳ ያላቸው መሆኑን አብስር» በማለት ከእነርሱ መካከል ወደ ሆነ አንድ ሰው ራዕይን ማውረዳችን ለሰዎች ድንቅ ሆነባቸውን? ከሓዲያን «ይህ (ሰው) ግልጽ ድግምተኛ ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 3, '3. ጌታችሁ ያ ሰማያትንና ምድርን በስድስት ቀናት ውስጥ ብቻ የፈጠራቸው አላህ ነው:: ከዚያም ነገሩን ሁሉ የሚያስተናብር ሲሆን (ለሱ ክብር በምስማማ መልኩ) በዐርሹ ላይ ተደላደለ፡፡ ከእርሱ በጎ ፈቃድ በኋላ ቢሆን እንጂ አንድም አማላጅ የለም:: እነሆ ይህ አላህ ጌታችሁ ነው:: እናም በትክክል ተገዙት:: አትገሰጹምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 4, '4. (ሰዎች ሆይ!) የሁላችሁም መመለሻችሁ ወደ እርሱ ብቻ ነው:: ይህም የተረጋገጠ የአላህ ቃል ኪዳን ነው:: እርሱ መፍጠርን ይጀምራል:: ከዚያም እነዚያ ያመኑትንና መልካም የሠሩትን ሰዎች በትክክል ይመነዳ ዘንድ ፍጡራንን ከሞት በኋላ ህያው ያደርጋል:: እነዚያ የካዱት ክፍሎች ግን በክህደታቸው ምክንያት የፈላ ውሃ መጠጥና አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 5, '5. እርሱ ያ ጸሐይን አንጸባራቂ ጨረቃንም አብሪ ያደረገ፤ የዓመታትን ቁጥርና ሒሳብን ታውቁ ዘንድም ለጨረቃ የተለያዩ መስፈሪያ እርከኖችን የወሰነ ነው:: አላህ ይህንን በእውነት እንጂ በከንቱ አልፈጠረዉም:: ለሚያውቁ ሕዝቦችም አናቅጽን ያብራራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 6, '6. ሌሊትና ቀን በመተካካታቸው አላህ በሰማያትና በምድር ውስጥ በፈጠረው ሁሉ ለሚጠነቀቁ ሕዝቦች ታላላቅ ተአምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 7, '7. እነዚያ ከኛ ጋር መገናኘታቸውን ተስፋ የማያደርጉ ቅርቢቱን ሕይወት የወደዱና በእርሷም የረኩ እነርሱ ከአናቅጻችን ዘንጊዎች የሆኑት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 8, '8. እነዚያ ይሠሩት በነበሩት ኃጢአት ምክንያት መኖሪያቸው በእሳት ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 9, '9. እነዚያ በአላህ ያመኑትና መልካም ሥራዎችን የሠሩ ሰዎች ሁሉ ጌታቸው በእምነታቸው ምክንያት የገነትን መንገድ ይመራቸዋል:: ከሥሮቻቸው ወንዞች ይፈስሳሉ:: በመጠቀሚያ ገነቶች ውስጥም ዝንታለም ይኖራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 10, '10. በእርሷም ውስጥ ጸሎታቸው የሚሆነው «ጌታችን ሆይ! ጥራት ይገባህ።» ማለት ብቻ ነው:: በእርሷ ውስጥ መከባበሪያቸው ሰላም መባባል ነው:: የመጨረሻ ጸሎታቸዉም «ምስጋና ሁሉ ለዓለማት ጌታ ለሆነው ለአላህ ብቻ ይገባው።» ማለት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 11, '11. አላህ ለሰዎች ደግን ነገር ለማግኘት እንደ መቻኮላቸው የሚጠይቁትንም ክፉን ነገር ቢያቻኩልባቸው ኖሮ በዚያችው ጊዜያቸው እድሜያቸው በተፈጸመ ነበር:: እነዚያን መገናኘታችንን ተስፋ የማያደርጉትን ሰዎች በጥመታቸው ውስጥ እየዋለሉ እንተዋቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 12, '12. የሰውን ልጅ ጉዳት ባገኘው ጊዜ በጎኑ ላይ ተጋድሞ ወይም ተቀምጦ ወይም ቆሞ ይለምንና ጉዳቱን ከእሱ ላይ በገለጥንለት ጊዜ ላገኘው ጉዳት እንዳልተማጸንን ሆኖ ያልፋል:: ልክ እንደዚሁ ለድንበር አላፊዎች ሁሉ ይሠሩት የነበሩት መጥፎ ሥራ ተሸለመላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 13, '13. ከናንተ በፊት የነበሩትን የብዙ ክፍለ ዘመናት ሰዎች መልዕክተኞቻቸው በማስረጃዎች የመጡላቸው ሲሆኑ በበደሉና የማያምኑም በሆኑ ጊዜ አጠፋናቸው:: ልክ እንደዚሁ ተንኮለኞችን ህዝቦች እንቀጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 14, '14. ከዚያ እንዴት እንደምትሠሩ ልንመለከት ከእነርሱ በኋላ በምድር ላይ ምትኮች አደረግናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) አናቅጻችን ግልጽ ሆነው በእነርሱ ላይ በተነበቡላቸው ጊዜ እነዚያ መገናኘታችንን የማይፈሩት (የማይሹት) ሰዎች «ከዚህ ሌላ የሆነን ቁርኣን አምጣልን ወይም ለውጠው።» ይላሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ ከራሴ በኩል ልለውጠው አይገባኝም:: ወደ እኔ የሚወረደውን እንጂ አልከተልም:: እኔ በጌታዬ ትዕዛዝ ላይ ባምጽ የታላቅን ቀን ቅጣት እፈራለሁ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 16, '16. (መልዕከተኛችን ሙሐመድ ሆይ!) «አላህ በሻ ኖሮ በእናንተ ላይ ባላነበብኩትና አላህ እርሱን ባላሳወቃችሁ ነበር:: በእናንተም ውስጥ ከእርሱ በፊት ምንም ሳልል ብዙን እድሜ በእርግጥ ኖሬያለሁ። አታውቁምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 17, '17. በአላህ ላይ እብለትን ከቀጣጠፈ ወይ ከአናቅ ጹ መካከል (በአንዷ እንኳን) ካስተባበለ ይበልጥ በዳይ ማን ነው? እነሆ አመጸኞች አይድኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 18, '18. አጋሪዎች ከአላህ ሌላ የማይጎዳቸውንና የማይጠቅማቸውን ይገዛሉ:: «እነዚህ አላህ ዘንድ አማላጆቻችን ናቸው።» ይላሉም። (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ በሰማያትና በምድር ውስጥ የማያውቀው ነገር ኖሮ እናንተ ትነግሩታላችሁን?» በላቸው:: አላህ ከሚያጋሩት ሁሉ ጠራ:: ላቀም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 19, '19. ሰዎች አንድ ህዝብ እንጂ ሌላ አልነበሩም:: ከዚያ ተለያዩ:: ከጌታህ ያለፈ ቃልም ባልነበረ ኖሮ በዚያ በሚለያዩበት ነገር በመካከላቸው በቶሎ በተፈረደ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርሱ ላይም ከጌታው የሆነች ተዓምር ለምን አትወረድለትም?» ይላሉ:: «ሩቅ ነገር ሁሉ የአላህ ብቻ ነው:: እናንተም ተጠባበቁ እኔም ከናንተው ጋር ከሚጠባበቁት ነኝ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰዎች ካገኛቸው ጉዳት በኋላ እዝነትን ምቾትን ባቀመስናቸው ጊዜ ወዲያውኑ ለእነርሱ በተዓምራቶቻችን በማላገጥ ተንኮል ይኖራቸዋል:: «አላህ ቅጣቱ ፈጣን ነው።» በላቸው። መልዕክተኞቻችን የምታሴሩትን ነገር ሁሉ በእርግጥ ይጽፋሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 22, '22. (ሰዎች ሆይ!) አላህ ያ በየብስና በባሕር የሚያስኬዳችሁ ነው:: በመርከቦችም ውስጥ በሆናችሁና በእነርሱም በመልካም ነፋስ በእርሷ የተደሰቱ ሆነው መርከቦቹ በተንሻለሉ ጊዜ ሀይለኛ ነፋስ ትመጣባቸዋለች:: ከየስፍራዉም ማዕበል ይመጣባቸዋል:: እነርሱም ለጥፋት የተከበቡ መሆናቸውን ሲያረጋግጡ ያን ጊዜ አላህን «ከዚህች ጭንቀት ብታድነን ከአመስጋኞቹ እንሆናለን።» ሲሉ እምነታቸውን ለእርሱ ብቻ ፍጹም አድርገው ይለምኑታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 23, '23. በአዳናቸዉም ጊዜ እነርሱ ወዲያውኑ ያለ አግባብ በምድር ላይ ወሰን ያልፋሉ። እናንተ ሰዎች ሆይ ወሰን ማለፋችሁ ጥፋቱ በነፍሶቻችሁ ላይ ብቻ ነው:: እርሱ የቅርቢቱ ህይወት መጠቀሚያ ነው:: ከዚያ መመለሻችሁ ወደ እኛ ነው:: ትሠሩት የነበራችሁትንም ሁሉ እንነግራችኋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 24, '24. . የቅርቢቱ ህይወት ምሳሌ ከሰማይ እንዳወረድነው ውሃ በእርሱም ሰውና እንስሳዎች ከሚበሉት የምድር በቃይ ተቀላቅሎበት እንደፋፋ ምድርም ውበትዋን በያዘችና ባጌጠች ጊዜ ባለቤቶችዋን በእርሷ ላይ እነርሱ ቻዮች መሆናቸውን ባሰቡ ጊዜ ትዕዛዛችን ሌሊት ወይም ቀን መጥቶባት ትላንት እንዳልነበረች የታጨደች እንዳደረግናት ብጤ ነው:: ልክ እንደዚሁ ለሚያስተነትኑ ሕዝቦች ሁሉ አናቅጽን እናብራራለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 25, '25. አላህ (ሁል ጊዜም) ወደ ሰላም አገር ይጠራል:: የሚፈልገዉን ሰዉም ወደ ቀጥተኛው መንገድ ይመራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 26, '26. ለእነዚያ መልካም ለሠሩት ሰዎች መልካም ነገርና (ገነት) ሌላ ተጨማሪም አላቸው:: ፊቶቻቸውንም ጥቁረትና ውርደት አይሸፍናቸዉም:: እነዚያ የገነት ሰዎች ናቸው:: እነርሱ በውስጧ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 27, '27. እነዚያ ኃጢአቶችን የሠሩት ደግሞ ኃጢአቲቱን የሚመጥን ቅጣት አለባቸው:: ውርደትም ትሸፍናቸዋለች :: እነርሱ ከአላህ ቅጣት ጠባቂ የላቸዉም:: ፊቶቻቸው በድቅድቅ ጨለማ ቁራጮች እንደ ተሸፈኑ ይሆናሉ:: እነዚያ የእሳት ሰዎች ናቸው:: እነርሱ በውስጧ ዘለዓለም ነዋሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) አማልክትንና አምላኪዎቻቸውን ሁሉ በአንድ የምንሰበስባቸውንና ከዚያም ለእነዚያ ላጋሩት «እናንተም ተጋሪዎቻችሁም ቦታችሁን ያዙ።» የምንልበትን ተጋሪዎቻቸዉም (እንዲህ) የሚሏቸው ሲሆኑ በመካከላቸው የምንለይበትን ቀን አስታውስ «ትገዙ የነበረው እኛን አልነበረም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 29, '29. (ጣኦታቶቹ) «እኛን ለመገዛታችሁ ዘንጊዎች ለመሆናችን በኛና በእናንተ መካከል የአላህ መስካሪነት በቃ።» ይሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 30, '30. በዚያ ቀን ነፍስ ሁሉ ያሳለፈችውን ሥራ ታውቃለች:: አጋሪዎች ወደ አላህ እውነተኛ ወደሆነው ጌታቸው ይመለሳሉ:: ያ በአላህ ላይ ይቀጣጥፋት የነበሩት ሁሉ ነገርም ይጠፋባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 31, '31. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከሰማይና ከምድር ሲሳይን የሚሰጣችሁ ማን ነው? መስሚያዎችንና ማያዎችንስ የፈጠረላችሁ ማን ነው? ከሙትም ህያውን የሚያወጣ፤ ከህያዉም ሙትን የሚያወጣስ ማን ነው? ነገሩን ሁሉ የሚያስተናብርስ ማን ነው?» በላቸው:: «በእርግጥ አላህ ነው።» ይሉሃል:: «ታዲያ ለምን ታጋራላችሁ? ታዲያ አትፈሩትምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 32, '32. እውነተኛው ጌታችሁ አላህ ብቻ ነው:: ከእውነት በኋላ ጥመት እንጂ ሌላ ምን አለ? ከእውነት እንዴት ትዞራላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 33, '33. ልክ እንደዚሁ የጌታህ ቃል በእነዚያ ባመጹት ሰዎች ላይ ፈጽሞ የማያምኑ መሆናቸው ተረጋገጠ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 34, '34. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከምታጋሯቸው ጣኦታት መካከል መፍጠርን የሚጀምር ከዚያ የሚመልስ አለን?» በላቸው። «አላህ ግን መፍጠርን ይጀምራል:: ከዚያ ይመልሰዋል:: ታዲያ ከእምነት እንዴት ትዘራላችሁ?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 35, '35. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከምታጋሯቸው ጣኦታት መካከልስ ወደ እውነት መንገድ የሚመራ አለን?» በላቸው:: «አላህ ግን ወደ እውነቱ ይመራል:: ወደ እውነት የሚመራው ጌታ ነውን ሊከተሉት የተገባው? ወይስ ካልተመራ በስተቀር የማይመራው? ለእናንተ ምን ( አስረጅ) አላችሁ? እንዴት በውሸት ትፈርዳላችሁ?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 36, '36. አብዛኞቻቸው ጥርጣሬን እንጂ አይከተሉም:: ጥርጣሬ ደግሞ ከእውነት በፍጹም አያብቃቃም:: አላህ የሚሠሩትን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 37, '37. ይህም (ቁርኣን) ከአላህ ሌላ ከሆነ ፍጡር የተቀጠፈ ሊሆን አይገባዉም:: ይልቁንም ያንን ከእርሱ በፊት ያለውን መጽሐፍ የሚያረጋግጥና በመጽሐፉ ውስጥ ያለውን የሚዘረዝር በእርግጥ ጥርጣሬ የሌለበት ሲሆን ከዓለማት ጌታ የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 38, '38. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእውነት ሙሐመድ ቀጣጠፈው» ይላሉን? ይህን የሚሉ ከሆነ «መሰሉን አንድ ምዕራፍ እንኳ እስቲ አምጡ:: ለዚህም ጉዳይ ከአላህ ሌላ የቻላችሁትን ሁሉ ረዳት ጥሩ:: እውነተኞች እንደሆናችሁ ለዚህ ተጋግዛችሁ አምጡ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 39, '39. ይልቁንም እውቀቱን ባላዳረሱትና ፍቹም ገና ባልመጣላቸው ነገር አስተባበሉ:: እንደዚሁ እነዚያ ከእነሱ በፊት የነበሩት አስተባብለዋል፡፡ (መልዕክተኛችን ሙሐመድ ሆይ!) የበዳዮች መጨረሻ እንዴት ይመስል እንደ ነበር በጥሞና ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመካከላቸው ወደፊት በቁርኣን የሚያምኑ አሉ:: ከእነርሱም መካከል በእርሱ የማያምኑ አሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ አጥፊዎቹን በጣም አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) «ቢያስተባብሉህም ለእኔ የራሴ ሥራ አለኝ:: እናንተም የራሳችሁ ሥራ አላችሁ:: እናንተ እኔ ከምሠራው ተግባር ንጹህ ናችሁ (አትጠየቁም):: እኔም እናንተ ከምትሠሩት ነገር ንጹህ ነኝ (አልጠየቅም)።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 42, '42. ከእነርሱ መካከል ወደ አንተ ንግግር የሚያዳምጡ የሚሰሙና የማያምኑ አሉ:: አንተ ደንቆሮዎችን የማያውቁ ቢሆኑም ታሰማለህን?::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 43, '43. ከእነርሱም መካከል ወደ አንተ የሚመለከቱ አሉ:: አንተ ልበ እውራንን የማያዩ ቢሆኑም ትመራለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 44, '44. አላህ ሰዎችን ምንም አይበድልም:: ግን ሰዎች ነፍሶቻቸውን ይበድላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያንን ከቀን አንዲትን ሰዓት እንጂ አንዳልቆዩ መስለው በመካከላቸው የሚተዋወቁ ሲሆኑ በምንሰበስባቸው ቀን የሚከሰተውን አስታውስ:: እነዚያ በአላህ መገናኘት ያስተባበሉት ሁሉ በእርግጥ ከሰሩ:: የተመሩም አልነበሩምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) የዚያንም የምናስፈራራባቸውን ነገር ውጤት ከፊሉን (በሕይወትህ ሳለህ) ብናሳይህ (መልካም ነው):: ወይም ሳናሳይህ ብንገድልህ (ጉዳዩ የእኔ ነው):: መመለሻቸው ወደ እኛ ነውና:: ከዚያ አላህ በሚሠሩት ሥራ ላይ ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 47, '47. ለሕዝቦችም ሁሉ መልዕክተኛ አላቸው:: መልዕክተኛቸው በመጣ ጊዜ (ሲያስተባብሉት) በመካከላቸው በትክክል ይፈረዳል:: እነርሱም ፍጹም አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) «እውነተኞች ከሆናችሁ የቅጣቱ ቀጠሮ መቼ ነው?» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) «ለራሴ ጉዳትን ማድረስም ሆነ ጥቅምን ማስከበር አላህ ከሻው በስተቀር አልችልም:: ለህዝቦች ሁሉ የተወሰነ ጊዜ አላቸው:: ጊዜያቸው በደረሰ ወቅት አንዲትን ሰዓት እንኳን አይቆዩም:: አይቀደሙምም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) «እስቲ ንገሩኝ ቅጣቱ በሌሊት ወይም በቀን ቢመጣባችሁ አጋሪዎቹ የሚያስቸኩላቸው ነገር ምንድን ነው?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 51, '51. «ከዚያም ቅጣቱ በወደቀ ጊዜ በእርሱ አመናችሁበትን? በእርግጥ በእርሱ የምትቻኮሉ የነበራችሁ ስትሆኑ አሁን ነው የምታምኑትን?» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 52, '52. ከዚያ ለእነዚያ ለበደሉት ሰዎች «ዘውታሪውን ቅጣት ቅመሱ። ትሠሩ የነበራችሁትን እኩይ ተግባር ዋጋ እንጂ ትመነዳላችሁን? (አትመነዱም)።» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) «(ከሞት በኋላ መቀስቀስ) እውነት ነውን?» ሲሉ ይጠይቁሃል:: «አዎን! በጌታዬ እምላለሁ እርሱ እውነት ነው:: እናንተም የምታቅቱ አይደላችሁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 54, '54. ለበደለች ነፍስ ሁሉ በምድር ላይ ያለው ሀብት ሁሉ የእርሷ ቢሆንላት በእርግጥ ቤዛ ባደረገችው ነበር:: ቅጣቱንም ባዩ ጊዜ ጸጸትን ይደብቃሉ (ይገልጻሉ):: በመካከላቸዉም በትክክል ይፈረዳል:: እነርሱም ቅንጣት ያህል አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 55, '55. አስተውሉ! በሰማያትና በምድር ያለው ሁሉ የአላህ ብቻ ነው:: አስተዉሉ! የአላህ የተስፋ ቃል እርግጥ ነው:: ግን አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 56, '56. እርሱ ሕያው ያደርጋል:: ይገድላልም:: ወደ እርሱም ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 57, '57. ሰዎች ሆይ! ከጌታችሁ ዘንድ ግሳጼ በደረቶች ውስጥ ላለው በሽታም ፍቱን መድሀኒት፤ ለአማኞችም ብርሃንና እዝነት የሆነ መልዕክት በእርግጥ መጣላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 58, '58. (መልዕክተኛችን ሙሐመድ ሆይ!) «በአላህ ችሮታና በእዝነቱ ተደሰቱ:: በዚህም ምክንያት ይደሰቱ:: እርሱ ከሚሰበስቡት ሀብት ሁሉ በላጭ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 59, '59. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ከሲሳይ ለእናንተ ያወረደው ከእርሱም ከፊሉን እርም ከፊሉን የተፈቀደ ያደረጋችሁትን አያችሁን?» በላቸው:: «አላህ ይህንን ለእናንተ ፈቀደላችሁን? ወይስ በአላህ ላይ ትቀጣጥፋላችሁ?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 60, '60. እነዚያ በአላህ ላይ ውሸትን የሚቀጣጥፉ ሰዎች በትንሳኤ ቀን በአላህ ጥርጣሬያቸው ምንድን ነው? አይቀጡም ይመስላቸዋልን? አላህ በሰዎች ላይ ቅጣትን ባለማቻኮል የልግስና ባለቤት ነው:: ግን አብዛኛዎቹ አያመሰግኑትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 61, '61. (መልዕክተኛችን ሙሐመድ ሆይ!) በማንኛዉም ነገር ላይ አትሆንም፤ ከእርሱም ከቁርኣን ትንሽም አታነብም፤ ማንኛውንም ሥራ አንተም ሆንክ ሰዎቹ አትሠሩም፤ በገባችሁበት ጊዜ በናንተ ተግባር ላይ ተጠባባቂዎች ብንሆን እንጂ :: በምድርም ሆነ በሰማይ የብናኝ ክብደት ያክል እንኳን ከጌታህ እውቀት አይርቅም:: ከዚያም ያነሰም ሆነ የተለቀ ነገር በግልጹ መጽሐፍ ውስጥ የተጻፈ ቢሆን እንጂ የለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 62, '62. አስተውሉ! የአላህ ወዳጆች ፍርሀት የለባቸዉም። አይተክዙምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 63, '63. እነርሱም እነዚያ ያመኑትና አላህን የሚፈሩት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 64, '64. ለእነርሱ በቅርቢቱ ህይወትም ሆነ በመጨረሻይቱ ዓለም ብስራት አለላቸው:: የአላህ ቃል አይለወጥም:: ይህ እርሱ ታላቅ እድል (ስኬታማነት) ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) ንግግራቸዉም አያሳዝንህ:: ኃይል በሙሉ የአላህ ብቻ ነውና:: እርሱም ሰሚውና ሁሉን አዋቂው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 66, '66. አስተውሉ! በሰማያት ያሉትና በምድርም ያሉት ሁሉ በእርግጥ የአላህ ናቸው፤ እነዚያ ከአላህ ሌላ ተጋሪዎችን የሚጠሩ ምንን ይከተላሉ? ጥርጣሬን እንጂ ሌላ አይከተሉም፡፡ እነርሱም የሚዋሹ እንጂ አይደሉም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 67, '67. (ሰዎች ሆይ!) እርሱ ያ ሌሊትን በውስጡ ልታርፉበት ጨለማ ቀንንም ልትሠሩበት ብርሃን ያደረገላችሁ ነው:: በዚህ ውስጥ ለሚሰሙ ህዝቦች ሁሉ በእርግጥ ብዙ ተአምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 68, '68. «አላህ ልጅን ወለደ።» አሉ። ከሚሉት ሁሉ ጥራት ተገባው:: እርሱ በራሱ ተብቃቂ ነው:: በሰማያትና በምድር ያለው ሁሉ የእርሱ ብቻ ነው:: እናንተ ዘንድ በዚህ በምትሉት ምንም አስረጂ የላችሁም:: በአላህ ላይ የማታውቁትን ትናገራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 69, '69. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያ በአላህ ላይ ውሸትን የሚቀጣጥፉ ሰዎች ፈጽሞ አይድኑም።» በላቸው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 70, '70. እነርሱ በቅርቢቱ ዓለም ጥቂት ጊዜ ይጠቀሙና ከዚያም መመለሻቸው ወደ እኛ ነው:: ከዚያም ይክዱ በነበሩበት ምክንያት ብርቱን ቅጣት እናቀምሳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 71, '71. (መልዕክተኛችን ሙሐመድ ሆይ!) የኑህንም ወሬ በእነርሱ ላይ አንብብላቸው:: ለህዝቦቹ ባለ ጊዜ አስታውሱ «ህዝቦቼ ሆይ! በእናንተ ውስጥ ብዙን ጊዜ መቆየቴ የአላህንም ተዓምራት ለእናንተ ማስታወሴ በእናንተ ላይ የከበደ ቢሆንባችሁም በአላህ ላይ ተጠግቻለሁ:: ነገራችሁንም ከምታጋሯቸው ጣኦታት ጋር ሆናችሁ እስቲ ቁረጡ:: ከዚያም ነገራችሁ በእናንተ ላይ ድብቅ አይሁን ግለጹት:: ከዚያም የሻችሁትን ወደ እኔ አድርሱ:: ጊዜም አትስጡኝ (ከምንም አልቆጥራችሁም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 72, '72. «ብትሸሹም (አትጎዱኝም::) ከምንዳ ምንንም አለመንኳችሁምና:: ምንዳዬ በአላህ ላይ እንጂ በሌላ ላይ አይደለምና:: ከሙስሊሞች እንድሆንም ታዝዣለሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 73, '73. አስተባበሉት እርሱንና ከእርሱ ጋር የነበሩትን ሰዎች በታንኳይቱ ውስጥ አዳንናቸው:: ለጠፉት ምትኮች አደረግናቸው:: እነዚያንም በአናቅጻችን ያስተባበሉትን አሰመጥን:: (መልዕክተኛችን ሙሐመድ ሆይ!) የተስፈራሩት ህዝቦች መጨረሻ እንዴት እንደ ነበር እስቲ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 74, '74. ከዚያም ከእርሱ በኋላ መልዕክተኞችን ወደየ ህዝቦቻቸው ላክን:: በግልጽ ማስረጃዎችም መጡላቸው:: ከመላካቸው በፊት ባስተባበሉት ነገር የሚያምኑ አልሆኑም:: ልክ እንደዚሁ በወሰን አላፊዎች ልቦች ላይ እናትማለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 75, '75. ከዚያም ከእነርሱ በኋላ ሙሳንና ሃሩንን ወደ ፈርዖንና ወደ መማክርቱ በተአምራታችን ላክን:: ኮሩም:: ትእቢተኞች ህዝቦችም ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 76, '76. ከእኛም ዘንድ እውነቱ በመጣላቸው ጊዜ «ይህ በእርግጥ ግልጽ ድግምት ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 77, '77. ሙሳ አለ፡- «እውነቱን በመጣላችሁ ጊዜ ድግምተኞች የማይድኑ ሲኾኑ (እርሱ ድግምት ነው) ትላላችሁን?ይህ ድግምት ነውን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 78, '78. እነርሱም «አባቶቻችንን ካገኘንበት ሃይማኖት ልታዞሩንና በምድር ውስጥ ለእናንተም ኩራት ሹመት ልትኖራችሁ መጣህብን:: እኛ ለእናንተ በፍጹም አማኞች አይደለንም።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 79, '79. ፈርዖን፡- «አዋቂ ድግምተኛን ሁሉ አምጡልኝ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 80, '80. ድግምተኞቹ በመጡ ጊዜም ሙሳ ለእነርሱ፡- «እናንተ የምትጥሉትን ነገር ጣሉ።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 81, '81. በጣሉም ጊዜ ሙሳ፡- «ያ በእርሱ የመጣችሁበት ነገር ድግምት ነው:: አላህ በእርግጥ ያፈርሰዋል:: አላህ የአጥፊዎችን ሥራ ፈጽሞ አያበጅምና።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 82, '82. አላህም ከሓዲያን ቢጠሉም እውነትን በቃላቱ ያረጋግጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 83, '83. ለሙሳም ከፈርዖንና ከሹማምንቶቻቸው ማሰቃየትን በመፍራት ከወገኖቹ ጥቂት ትውልዶች ብቻ እንጂ አላመኑለትም:: ፈርዖንም በምድር ላይ በእርግጥ ይኮራ ነበር። እርሱም በእርግጥ ወሰን ካለፉት ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 84, '84. ሙሳም፡- «ህዝቦቼ ሆይ! በአላህ አምናችሁ እንደ ሆነ በእርሱ ላይ ብቻ ተጠጉ:: ታዛዦች እንደ ሆናችሁም በአላህ ላይ ብቻ ተመኩ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 85, '85. አሉ፡- «በአላህ ላይ ተጠጋን:: ጌታችን ሆይ! ለበደለኞች ህዝቦች መፈተኛ አታድርገን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 86, '86. «በእዝነትህም ከከሓዲያን ህዝቦች ግፍ አድነን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 87, '87. ወደ ሙሳና ወደ ወንድሙ፡ «ለህዝቦቻችሁ በግብጽ ውስጥ ቤቶችን ሥሩ:: ቤቶቻችሁንም መስገጃ አድርጉ:: ሶላትንም በደንቡ ስገዱ:: ምዕመናኖቹንም አብስር።» ስንል ላክን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 88, '88. ሙሳም: «ጌታችን ሆይ! አንተ ለፈርዖንና ለሹሞቹ በቅርቢቱ ህይወት ጌጥን ብዙ ገንዘቦችንም በእርግጥ ሰጠህ:: ጌታችን ሆይ! ከመንገድህ ያሳስቱ ዘንድ ሰጠሃቸው:: ጌታችን ሆይ! ገንዘቦቻቸውን አጥፋ:: በልቦቻቸዉም ላይ አትም:: አሳማሚን ቅጣት አስከሚያዩ አያምኑምና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 89, '89. (አላህም) ፡- «ጸሎታችሁ ተሰምታለች:: ቀጥም በሉ:: የእነዚያን የማያውቁትን ሰዎች መንገድ አትከተሉ።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 90, '90. የኢስራኢል ልጆችን ባህሩን አሳለፍናቸው:: ፈርዖንና ሰራዊቱም ወሰን ለማለፍና ለመበደል ተከተሏቸው:: የመስመጥ አደጋ ባገኘውም ጊዜ «አመንኩ:: እነሆ ከዚያ የእሥራኤል ልጆች ካመኑበት አምላክ በስተቀር ሌላ የእውነት አምላክ የለም:: እኔም ከታዛዦቹ (ሙስሊሞች) አንዱ ነኝ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 91, '91. «ከአሁን በፊት በእርግጥ ያመጽክና ከአጥፊዎችም የነበርክ ስትሆን አሁን ታምናለህን?» ተባለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 92, '92. እናም ዛሬ ከኋላህ ለሚመጡ ትውልዶች ተዓምር ትሆን ዘንድ አካልህን (ከባሕሩ) እናወጣሀለን ከሰዎችም ብዙዎቹ ከተዐምሮቻችን በእርግጥ ዘንጊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 93, '93. የኢስራኢልን ልጆችም ምስጉንን ስፍራ በእርግጥ አሰፈርናቸው:: ከመልካም ሲሳዮችም ሰጠናቸው:: እውቀትም እስከመጣላቸው ድረስ አልተለያዩም:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በእርሱ ይለያዩበት በነበሩት ነገር በትንሳኤ ቀን በመካከላቸው ይፈርዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 94, '94. (መልዕክተኛችን ሙሐመድ ሆይ!)) ወደ አንተ ካወረድነው በመጠራጠር ውስጥ ከሆንክ እነዚያን ካንተ በፊት መጽሐፉን የሚያነቡትን ሰዎች ጠይቅ:: እውነቱ ከጌታህ ዘንድ መጥቶልሃል:: እናም ከተጠራጣሪዎች አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 95, '95. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነዚያ የአላህን አናቅጽ ካስተባበሉት ሰዎች አትሁን:: ከከሳሪዎቹ ትሆናለህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 96, '96. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ የጌታህ ቃል የተረጋገጠባቸው ሰዎች አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 97, '97. ተዓምራት ሁሉ ቢመጣላቸዉም አሳማሚን ቅጣት እስከሚያዩ ድረስ(አያምኑም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 98, '98. ከነብዩ ዩኑስ በፊት ካለፉት ከተሞች ያመነችና እምነት የጠቀማት ከተማ ለምን አልኖረችም? ግን የነብዩ ዩኑስ ህዝቦች ባመኑ ጊዜ በቅርቢቱ ህይወት የውርደትን ቅጣት ከእነርሱ ላይ አነሳንላቸው:: እስከ ጊዜም ድረስ አጣቀምናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 99, '99. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በሻ ኖሮ በምድር ያሉት ሁሉ በአንድ የተሰበሰቡ ሆነው ባመኑ ነበር:: ታዲያ አንተ ሰዎችን አማኞች እንዲሆኑ ታስገድዳለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 100, '100. ማንኛዋም ነፍስ በአላህ ፈቃድ ቢሆን እንጂ የምታምን አይደለችም:: ከእነዚያ በማያውቁት ላይ ርክሰትን ያደርጋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 101, '101. (መልዕክተኛችን ሙሐመድ ሆይ!) «በሰማያትና በምድር ውስጥ ያሉትን ተዓምራት ተመልከቱ።» በላቸው:: ሆኖም ተዓምራትና አስፈራሪዎች ለማያምኑ ህዝቦች ምንም አይጠቅሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 102, '102. የእነዚያን ከእነርሱ በፊት ያለፉትን ህዝቦች ቀኖች ብጤ ያገኟቸውን አይነት ቀናትን እንጂ ሌላን ይጠባበቃሉን? (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተም ተጠባበቁ እኔም ከናንተው ጋር ከሚጠባበቁት ነኝ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 103, '103. መልዕክተኞቻችንንና እነዚያን ያመኑትንም ከጭንቅ ሁሉ እናድናለን:: እንደዚሁም ምእምናንን (ከጭንቅ ሁሉ) እናድናለን፡፡ ይህ በእኛ ላይ ተረጋገጠ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 104, '104. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎች ሆይ! ከእኔ ሃይማኖት በመጠራጠር ውስጥ ከሆናችሁ እነዚያን ከአላህ ሌላ የምትገዟቸውን አልገዛም:: ይልቁንም ያንን የሚገድላችሁን አላህን ብቻ እገዛለሁ:: ከትክክለኛ አማኞች እንድሆንም ታዝዣለሁ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 105, '105. (መልዕክተኛችን ሙሐመድ ሆይ!) ፊትህን ወደ ቀጥታው መንገድ ያዘነበልክ ስትሆን ለሃይማኖት ቀጥ አድርግ:: ከአጋሪዎቹም አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 106, '106. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከአላህ በስተቀር የማይጠቅምህንና የማይጎህዳን አትገዛ:: ይህን ብትሠራ ግን ያን ጊዜ ከበደለኞቹ ትሆናለህ (ተብያለሁ» በላቸው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 107, '107. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ጉዳትን ቢያደርስብህ ከእርሱ ሌላ ለእርሱ ገላጭ የለዉም:: በጎ ነገርም ቢሻልህ ለችሮታው መላሽ ማንም የለም:: ከባሮቹ የሚሻውን በእርሱ ይለይበታል:: እርሱም መሓሪውና አዛኙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 108, '108. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎች ሆይ! እውነቱ ከጌታችሁ በእርግጥ መጣላችሁ:: በእርሱ የተመራም የሚመራው ለራሱ ብቻ ነው:: የተሳሳተም የሚሳሳተው ጉዳቱ በራሱ ላይ ብቻ ነው:: እኔ በእናንተ ላይ ተጠባባቂ አይደለሁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (10, 109, '109. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ አንተ የሚወረደውን ነገር ተከተል:: አላህ በእነርሱና ባንተ መካከል ባለው ጉዳይ ላይ እስከሚፈርድ ድረስ ታገሥ:: እርሱም ከፈራጆቹ ሁሉ በላጭ ፈራጅ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 1, '1.አሊፍ፤ ላም፤ ራ፤. ይህ ቁርኣን አናቅጾቹ በጥንካሬ የተሰካኩ ከዚያም የተዘረዘሩ፤ ጥበበኛና ውስጠ አዋቂ ከሆነው (አምላክ) ዘንድ የተወረደ መጽሐፍ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 2, '2. መልዕክተኛው (እንዲህ በሚልበት ሰዎች ሆይ! ): «አላህን እንጂ ሌላን አትገዙ:: እኔ ለእናንተ ከእርሱ ዘንድ የተላኩ አስፈራሪና አብሳሪ ነኝ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 3, '3. (እንዲህም በሚልበት ሰዎች ሆይ! ): «ጌታችሁን ምህረት ለምኑት:: ከዚያ ወደ እርሱ ተመለሱ:: እስከ ተወሰነ ጊዜ ድረስ መልካምን መጥቀም ይጠቅማችኋል:: ለትሩፋት ባለቤት ሁሉ ችሮታውን (ምንዳዉን) ይሰጠዋል:: ብትሸሹም እኔ በእናንተ ላይ የታላቅን ቀን ቅጣት እፈራላችኋለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 4, '4. «መመለሻችሁ ወደ አላህ ብቻ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 5, '5. ሙስሊሞች ሆይ! አስተውሉ! እነርሱ ከእርሱ ከአላህ ይደበቁ ዘንድ ደረቶቻቸውን ያጥፋሉ:: ሙስሊሞች ሆይ! አስተውሉ! ልብሶቻቸውን በሚከናነቡ ጊዜ የሚደብቁትንም ሆነ የሚገልጹትን ሁሉ ያውቃል:: እርሱ በደረቶች ውስጥ ያለውን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 6, '6. በምድርም ላይ ምንም ተንቀሳቃሽ የለችም ምግቧ በአላህ ላይ ያለና ማረፊያዋንም ሆነ መርጊያዋን የሚያውቅ ቢሆን እንጂ:: ሁሉም ነገር ግልጽ በሆነው መጽሐፍ ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 7, '7. አላህ ያ ሰማያትንና ምድርን በስድስት ቀናት ውስጥ የፈጠረ ነው:: ዐርሹም በውሃ ላይ ነበር:: የትኛችሁ ስራችሁ ያማረ መሆኑ ይፈትናችሁ ዘንድ ፈጠራችሁ:: «እናንተ ከሞት በኋላ በእርግጥ ተቀስቃሾች ናችሁ» ብትልም። እነዚያ የካዱት «ይህ ግልጽ ድግምት እንጂ ሌላ አይደለም።» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 8, '8. ቅጣቱንም ለተቆጠሩ ጥቂት ጊዜያቶች ብናቆይላቸው «ከመውረድ የሚከለክለው ምንድን ነው?» ይላሉ:: ሙስሊሞች ሆይ! አስተውሉ:: በሚመጣባቸው ቀን ከእነርሱ ላይ ተመላሽ አይደለም:: በእርሱ ይሳለቁበት የነበሩትም ቅጣት በእነርሱ ላይ ይወርድባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 9, '9. ሰውንም ከችሮታችን ብናቀምሰውና ከዚያ ብንወስድበት እርሱ ተስፋ ቆራጭና ክህደተ ብርቱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 10, '10. ካገኘችዉም ችግር በኋላ ጸጋዎቻችንን ብናቀምሰው «ችግሮች ከእኔ ላይ ተወገዱ።» ይላል:: አያመሰግንም:: እርሱ ተደሳችና ጉረኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 11, '11. እነዚያ የታገሱና መልካም ሥራዎችንም የሰሩ ሁሉ እነዚያ ለእነርሱ ምህረትና ታላቅ ምንዳ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 12, '12. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርሱ ላይ (የሀብት) ድልብ ለምን አልተወረደም? ወይም ከእርሱ ጋር መልአክ ለምን አልመጣም?» ማለታቸውን በመፍራት ወደ አንተ ከሚወርደው ከፊሉን ልትተው በእርሱም ልብህ ጠባብ ሊሆን ይፈራልሃል:: አንተ አስፈራሪ ብቻ ነህ:: አላህ በሁሉ ነገር ላይ (ወኪል) ተጠባባቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቁንም «ቁርኣንን ቀጣጠፈው» ይላሉን? «እውነተኞች እንደሆናችሁ ብጤው የሆኑን አስር የተቀጣጠፉ ምዕራፎች እስቲ አምጡ:: ከአላህም ሌላ የቻላችሁትን ረዳት ጥሩ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 14, '14. ለእናንተ ምላሽ ካልሰጧችሁ «(ጣዖት አምላኪያን ሆይ!) የተወረደው በአላህ እውቀት ብቻ መሆኑንና ከእርሱ ሌላ አምላክ አለመኖሩንም እወቁ:: እናም አትሰልሙምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 15, '15. ቅርቢቱን ህይወትና ጌጧን የሚሹ የሆኑትን ሁሉ ሥራዎቻቸውን ምንዳዋን በእርሷ ውስጥ ወደ እነርሱ እንሞላላቸዋለን:: እነርሱም በእርሷ ውስጥ ምንም አይጎድልባቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 16, '16. እነዚያ እነርሱ በመጨረሻይቱ ዓለም ከእሳት በስተቀር የሌላቸው ናቸው:: የሰሩትም ሥራ በእርሷ ውስጥ ተበላሸ:: በቅርቢቱ ዓለም ይሰሩት የነበሩትም በጎ ሥራ ብልሹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 17, '17. ከጌታው ዘንድ አስረጅ የደረሰውንና ከእርሱም የሆነ መስካሪ የሚከተለው ከቁርኣን በፊትም ለሙሳ መጽሐፍ መሪና እዝነት ሲሆን የመሰከረለት (ሰውና) የቅርቢቱን ህይወት እንደሚሻው (ሰው) ነውን? እነዚያ በእርሱ (ቁርኣን) ያምናሉ:: ከአህዛቦቹ በእርሱ የሚክድ ሰው ሁሉ መመለሻው እሳት ናት:: (መልዕክተኛችን ሙሐመድ ሆይ!) ከእርሱም በመጠራጠር ውስጥ አትሁን:: እሱ ከጌታህ ዘንድ የሆነ እውነት ነው:: ግን አብዛኞቹ ሰዎች አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 18, '18. በአላህ ላይ ውሸትን ከሚቀጣጥፍ ይበልጥ በዳይ ማነው? እነዚያ በጌታቸው ላይ ይቀረባሉ:: መስካሪዎቹም «እነዚህ በጌታቸው ላይ የዋሹት ናቸው።» ይላሉ:: «አስተዉሉ! የአላህ እርግማን በበዳዮች ላይ ብቻ ይሁን።» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 19, '19. እነርሱም እነዚያ ከአላህ መንገድ ሰዎችን የሚከለክሉ የአላህን መንገድ መጥመሟንም የሚሹት ናቸው:: እነርሱም በመጨረሻይቱ ዓለም ከሓዲያን ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 20, '20. እነዚያም በምድር ውስጥ ከአላህ የሚያመልጡ አልነበሩም:: ከአላህ ሌላ ለእነርሱ ረዳቶች አልነበሯቸዉም:: ለእነርሱ ቅጣቱ ይደራረብላቸዋል:: እውነትን መስማትን የሚችሉ አልነበሩም:: የሚያዩም አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 21, '21. እነዚያ እነርሱ ነፍሶቻቸውን ያከሰሩና ይቀጣጥፉት የነበሩት ነገር የጠፋባቸው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 22, '22. እነርሱ በመጨረሻይቱ ዓለም በጣም ከሳሪዎቹ ለመሆናቸው ጥርጥር የለዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 23, '23. እነዚያ ያመኑትና በጎ ሥራዎችን የሠሩት ወደ ጌታቸዉም የተዋረዱት እነዚያ የገነት ናቸው:: እነርሱ በውስጧ ዘላለም ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 24, '24. የሁለቱ ክፍሎች ምሳሌ አይኑ የማያይ አይነ ስውር፤ ጆሮው የማይሰማ ደንቆሮ ሰውና አይኑ የሚያይ ጆሮው የሚሰማ ሰው ብጤ ነው:: ሁለቱ በምሳሌነት ይስተካከላሉን? አትገሰጹንም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 25, '25. ኑሕን ወደ ህዝቦቹ ላክንና አላቸዉም: «እኔ ለእናንተ ግልጽ አስፈራሪ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 26, '26. «አላህን እንጂ ሌላን አትገዙ። እኔ ለእናንተ የአሳማሚን ቀን ቅጣት እፈራላችኋለሁና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 27, '27. ከህዝቦቹም መካከል እነዚያ የካዱት መሪዎች «ብጤያችን ሰው ሆነህ እንጂ አናይህም:: እነዚያም እነርሱ ሐሳበ ጥሬዎች የሆኑት ወራዶቻችን እንጂ ሌላ ተከትሎህ አናይህም:: ለእናንተም በእኛ ላይ ምንም ብልጫን አናይም:: ከቶውንም ውሸታሞች መሆናችሁን እንጠረጥራችኋለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 28, '28. እርሱም አላቸው: «ህዝቦቼ ሆይ! እስቲ ንገሩኝ ከጌታዬ በግልጽ ማስረጃ ላይ ሆኜ ከእርሱም ዘንድ የሆነን ችሮታ ነብይነት ቢሰጠኝና በእናንተ ላይ ግን ይህች እውነታ ብትደበቅባችሁ እናንተ ለእርሷ ጠይዎች ስትሆኑ እርሷን በመቀበል እናስገድዳችኋለንን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 29, '29. «ህዝቦቼ ሆይ! በእርሱ የተላክሁበትን በማድረስ ላይ ገንዘብን አልጠይቃችሁም:: ምንዳዬ ከአላህ እንጂ ከሌላ አይደለም:: እኔም እነዚያን በአላህ ያመኑትን ከአጠገቤ አባራሪ አይደለሁም:: እነርሱ ከጌታቸው ጋር የሚገናኙ ናቸውና:: ግን እኔም የምትሳሳቱ ህዝቦች ሆናችሁ አያችኋለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 30, '30. «ህዝቦቼ ሆይ! ባባርራቸው ከአላህ ቅጣት የሚያድነኝ ማን ነው? አትገሰጹምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 31, '31. «ለናንተም እኔ ዘንድ የአላህ ግምጃ ቤቶች አሉ:: ሩቅንም አውቃለሁ አልላችሁም:: እኔም መልአክ ነኝ አልላችሁም:: ለእነዚያም ዓይኖቻችሁ ለሚያዋርዷቸው አላህ ደግ ነገርን እምነትን አይሰጣቸዉም አልልም:: አላህ በነፍሶቻቸው ውስጥ ያለውን ሁሉ ነገር አዋቂ ነው:: እኔ ያን ጊዜ ከበደለኞች እሆናለሁና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 32, '32. «ኑህ ሆይ! በእርግጥ ተከራከርከን:: እኛን መከራከርህንም አበዛህ:: ከእውነተኞቹም ከሆንክ የምታስፈራራብንን ቅጣት አምጣው እስቲ።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 33, '33. አላቸውም: «እርሱን የሚያመጣባችሁ አላህ የፈለገ ከሆነ ብቻ ነው። እናንተም የምታቅቱ አይደላችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 34, '34. «እናንተም አላህ ሊያጠማችሁ ፈልጎ ከሆነ ልመክራችሁ ብፈልግም ምክሬ አይጠቅማችሁም:: እርሱ ጌታችሁ ነው:: ወደ እርሱም ብቻ ትመለሳላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 35, '35. ይልቁንም ቀጠፈው ይላሉን? (ሙሐመድ ሆይ) «ብቀጥፈው ኃጢአቴ ቅጣቱ በእኔ ላይ ነው:: እኔም ከምታጠፉት ጥፋት ሁሉ ንጹህ ነኝ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 36, '36. ወደ ኑህም (እንዲህ በሚል) ተወረደ: «እነሆ ከህዝቦችህ በእርግጥ ካመኑት በስተቀር ወደፊት ሌሎች አያምኑም:: ይሠሩትም በነበሩት ክህደት አትዘን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 37, '37. «በጥበቃችንና በትዕዛዛችን ሆነህ መርከቢቱን ሥራ። በእነዚያም በበደሉት ሰዎች ነገር አታናግረኝ። እነርሱ በእርግጥ የሚሰምጡ ናቸውና።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 38, '38. ከወገኖቹም መሪዎቹ በእርሱ አጠገብ ባለፉ ቁጥር በእርሱ ላይ እየተሳለቁበት መርከቢቱን ይሠራል። አላቸውም: «በእኛ ብትሳለቁ እኛም እንደተሳለቃችሁብን በእናንተ እንሳለቅባችኋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 39, '39. «የሚያዋርደው ቅጣት የሚመጣበትን በእርሱም ላይ ዘውታሪ ቅጣት የሚሰፍርበትን ማንነት ወደ ፊት ታውቃላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 40, '40. ትዕዛዛችንም በመጣና እቶኑም በገነፈለ ጊዜ «በመርከቧ ውስጥ ከየዓይነቱ ሁሉ ሁለት ሁለት (ወንድና ሴት) ቤተሰቦችህንም ቃል ያለፈበት ብቻ ሲቀር ያመነንም ሰው ሁሉ ጫን።» አልነው:: ከእርሱም ጋር ጥቂቶች እንጂ አላመኑም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 41, '41. «‹መሄዷም መቆሟም በአላህ ስም ነው።› እያላችሁ በእርሷ ተሳፈሩ:: ጌታዬ መሓሪና አዛኝ ነውና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 42, '42. እርሷም እንደ ተራራዎች በሆነ ማዕበል ውስጥ እነርሱን ይዛቸው የምትንሻለል ስትሆን (በአላህ ስም ተቀመጡባት።) ኑህም ልጁን ከመርከቢቱ የራቀ ሆኖ ሳለ «ልጄ ሆይ! ከእኛ ጋር ተሳፈር። ከከሓዲያንም አትሁን።» ሲል ጠራው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 43, '43. ልጁም «ከውሃው ወደሚጠብቀኝ ተራራ እጠጋለሁ።» አለ:: አባቱም «ዛሬ ከአላህ ትዕዛዝ ምንም ጠባቂ የለም:: እርሱ ብቻ ያዘነለት ካልሆነ በስተቀር።» አለው:: ማዕበሉም በመካከላቸው ጋረደ:: ልጁም ከሰማጮች ሆነ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 44, '44. ተባለም «ምድር ሆይ! ዉሃሽን ዋጪ:: ሰማይ ሆይ! ዝናብሽን ያዢ።» ውሃዉም ሠረገ:: ቅጣቱም ተፈጸመ:: ጁዲይ በሚባለም ተራራ ላይ መርከቢቱ ተደላደለች:: «ለከሓዲያን ጥፋት ተገባቸው (ጥፉ)።» ተባለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 45, '45. ኑህም ጌታውን- «ጌታዬ ሆይ! ልጄ ከቤተሰቤ አንዱ ነው:: ቃል ኪዳንህም እውነት ነው:: አንተም ከፈራጆች ሁሉ ይበልጥ አዋቂ ነህ።» በማለት ጠየቀ (ተጣራ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 46, '46. አላህም «ኑህ ሆይ! እርሱ ከቤተሰብህ አይደለም:: እርሱ መልካም ያልሆነ ስራ ነው:: በእርሱ እውቀት የሌለህንም ነገር አትጠይቀኝ:: እኔ ከአላዋቂዎች እንዳትሆን እገስጽሃለሁ።» አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 47, '47. «ጌታዬ ሆይ! በእርሱ ለእኔ እውቀት የሌለኝን ነገር የምጠይቅህ ከመሆን እኔ ባንተ እጠበቃለሁ:: ለእኔም ባትምረኝና ባታዝንልኝ ከከሳሪዎቹ እሆናለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 48, '48. «ኑህ ሆይ! ከእኛ በሆነ ሰላም ባንተ ላይና አንተም ጋር ባሉት ህዝቦች ላይ በሆኑ በረከቶችም የተጎናጸፍክ ሆነህ ወደ ምድር ውረድ:: ከነሱው ዘሮች የሆኑ ህዝቦችም በቅርቢቱ ዓለም በእርግጥ እናስመቻቸዋለን:: ከዚያም ከእኛ የሆነ አሳማሚ ቅጣት ይደርስባቸዋል።» ተባለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ዘገባ ከሩቁ ወሬዎች መካከል ወደ አንተ ያወረድነው ነው:: አንተም ሆንክ ህዝቦችህ ከዚህ በፊት የምታውቁት አልነበራችሁም:: ታገሥ ምስጉን የሆነችው ፍጻሜ ለሚጠነቀቁት ብቻ ናትና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 50, '50. ወደ ዓድም ወንድማቸውን ሁድን ላክን:: አላቸው፡ «ወገኖቼ ሆይ! አላህን ብቻ ተገዙ:: ከእርሱ ሌላ ምንም አምላክ የላችሁም:: እናንተ ቀጣፊዎች እንጂ ሌላ አይደላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 51, '51. «ህዝቦቼ ሆይ! በእርሱ (በማድረሴ) ላይም ምንዳን አልጠይቃችሁም:: ምንዳዬ በዚያ በፈጠረኝ ላይ እንጂ በሌላ ላይ አይደለም:: አታውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 52, '52. «ህዝቦቼ ሆይ! ጌታችሁን ምህረትን ለምኑት:: ከዚያ ወደ እርሱ ተጸጸቱ:: ዝናብን በእናንተ ላይ ተከታታይ አድርጎ ይልክላችኋልና:: ወደ ኃይላችሁም ሀይልን ይጨምርላችኋል:: አመጸኞችም ሆናችሁ አትሽሹ::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 53, '53. እነርሱም አሉ፡- «ሁድ ሆይ! በአስረጂ አልመጣህልንም:: እኛም ላንተ ንግግር ብለን አማልክቶቻችንን የምንተው አይደለንም:: እኛም ላንተ ትክክለኛ አማኞች አይደለንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 54, '54. «ከፊሎቹ አማልክቶቻችን በክፉ ነገር በዕብደት ለክፈውሃል እንጂ ሌላን አንልም።» አሉ:: እርሱም አላቸው: «እኔ አላህን አስመሰክራለሁ:: ከምታጋሩትም እኔ ንጹህ መሆኔን መስክሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 55, '55. «ከእርሱ ሌላ አማልክትን ከምታጋሩት ንጹህ ነኝ። ሁላችሁም ሆናችሁ ተንኮልን ሥሩብኝ ከዚያ አታቆዩኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 56, '56. «እኔ ጌታዬና ጌታችሁ በሆነው በአላህ ላይ ብቻ ተመካሁ:: በምድር ላይ ምንም ተንቀሳቃሽ የለችም እርሱ አናትዋን የያዛት ብትሆን እንጂ:: ጌታዬ (ቃሉም ሥራዉም) በቀጥተኛው መንገድ ላይ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 57, '57. «ብትዞሩም ወደ እናንተ የተላኩበትን ነገር በእርግጥ አድርሼላችኋለሁ:: ጌታዬም ሌላን ህዝብ ይተካል:: ምንም አትጎዱትም:: ጌታዬ በሁሉ ነገር ላይ ተጠባባቂ ነውና።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 58, '58. ትዕዛዛችን በመጣ ጊዜ ሁድንና እነዚያን ከእሱጋ ያመኑትን ከእኛ በሆነው ችሮታ አዳን:: ከብርቱ ቅጣትም አዳናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 59, '59. ይህ ነገድ ዓድ ነው:: በጌታቸው ታዐምራት ካዱ:: መልዕክተኞቹንም አመጹ:: የኃያል ሞገደኛን ሁሉ ትዕዛዝም ተከተሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 60, '60. በዚች በቅርቢቱ ዓለምም እርግማን እንዲከተላቸው ተደረጉ:: በትንሳኤም ቀን እንደዚሁ:: አስተውሉ! ዓዶች ጌታቸውን ካዱ። አስተውሉ! የሁድ ህዝቦች ለሆኑት ዓዶች ከእዝነት መራቅ ይገባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 61, '61. ወደ ሠሙዶችም ወንድማቸውን ሷሊህን ላክን። «ህዝቦቼ ሆይ! አላህን ተገዙ:: ከእርሱ ሌላ ለእናንተ አምላክ የላችሁም:: እርሱ በምድር ፈጠራችሁ:: በውስጧ እንድታለሟትም አደረጋችሁ:: ምህረቱንም ለምኑት:: ከዚያም ወደ እርሱ ተመለሱ:: ጌታዬ ለሁሉም ቅርብና ለለመነው ተቀባይ ነውና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 62, '62. እነርሱም «ሷሊህ ሆይ! ከዚህ በፊት በእኛ ውስጥ መሪ ልትሆን በእርግጥ የምትከጀል የነበርክ ስትሆን:: አባቶቻችን የሚገዙትን ከመገዛት ትከለክለናለህን? እኛም ወደሱ ከምትጠራን ነገር በእርግጥ አወላዋይ በሆነ መጠራጠር ውስጥ ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 63, '63. ሷሊህም አለ: «ህዝቦቼ ሆይ! እስቲ ንገሩኝ ከጌታዬ በሆነ ማስረጃ ላይ ሆኜ ከእርሱም የሆነን ችሮታ ነብይነት ቢሰጠኝና ባልታዘዘው ከአላህ ቅጣት የሚያድነኝ ማነው? ከማጥፋትም በስተቀር ምንም አትጨምሩልኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 64, '64. «ህዝቦቼ ሆይ! ይህች ለእናንተ ታዓምር ስትሆን የአላህ ግመል ናት:: ተዋትም በአላህ ምድር ውስጥ ትብላ:: በክፉም አትንኳት። ቅርብ የሆነ ቅጣት ያገኛችኋልና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 65, '65. ወግተው ገደሏትም ሷሊህም «በሀገራችሁም ሶስትን ቀናት ብቻ ተጠቀሙ ይህ የማይዋሽ ቀጠሮ ነው።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 66, '66. እናም ትዕዛዛችን በመጣ ጊዜ ሷሊህንና እነዚያን ከእሱ ጋር ያመኑትን ከእኛ በሆነው እዝነት አዳንን:: ከዚያም ቀን ውርደት አዳንናቸው:: ጌታህ ብርቱውና ሁሉን አሸናፊው ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 67, '67. እነዚያን የበደሉትንም ከባድ ጩኸት ያዛቸው:: በየቤቶቻቸዉም ውስጥ የተንበረከኩ ሙት በድን ሆነው አደሩ(አነጉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 68, '68. በእርሷ ውስጥ እንዳልኖሩ ሆኑ:: አስተውሉ! ሠሙዶች ጌታቸውን በእርግጥ ካዱ:: አስተውሉ! ለሠሙዶች ከአላህ እዝነት መራቅ ተገባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 69, '69. መልዕክተኞቻችንም ወደ ኢብራሂም በልጅ መውለድ ብስራት መጡለትና ሰላም አሉት:: እሱም ሰላም አላቸው:: ጥቂትም ሳይቆይ ወዲያውኑ የተጠበሰን የወይፈን ስጋ አመጣ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 70, '70. እጆቻቸዉም ወደ ምግቡ የማይደርሱ መሆናቸውን ባየ ጊዜ ተግባራቸው እንግዳ ሆነበት:: ከእነርሱም ፍርሃት ተሰማው:: «አትፍራ እኛ ወደ ሉጥ ህዝቦች ተልከናልና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 71, '71. ሚስቱም ቁማ ነበርና ሳቀች:: እናም በኢስሓቅ አበሰርናት:: ከኢስሐቅም በኋላ በልጁ በየዕቁብ አበሰርናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 72, '72. እርሷም «ዋልኝ እኔ አሮጊት ይህም ባለቤቴ ሽማግሌ ሆኖ ሳለ እወልዳለሁን? ይህ በእርግጥ አስደናቂ ነገር ነው።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 73, '73. «በአላህ ትዕዛዝ ትደነቂያለሽን? :: የአላህ እዝነትና በረከት በእናንተ በኢብራሂም ቤተሰቦች ላይ ይሁን:: እሱ ምስጉንና ለጋሽ ነውና።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 74, '74. ከኢብራሂም ፍራቻው በሄደለትና ብስራት በመጣችለት ጊዜ በሉጥ ህዝቦች ነገር ይከራከረን ጀመር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 75, '75. ኢብራሂም በእርግጥ ታጋሽ፤ አልቃሻ (እጅግ የሚማፀን) እና መላሳ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 76, '76. (እነርሱም አሉት): «ኢብራሂም ሆይ! ይህን ክርክር ተው:: እነሆ የጌታህ ትዕዛዝ በእርግጥ መጥቷል:: እነርሱም የማይመለስ ቅጣት የሚመጣባቸው ናቸው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 77, '77. መልዕክተኞቻችንም ወደ ሉጥ በመጡ ጊዜ በእነርሱ ምክንያት አዘነ:: ልቡም በእነርሱ ተጨነቀ:: «ይህ ብርቱ ቀን ነዉ።» አለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 78, '78. ህዝቦቹም ወደ እርሱ እየተጣደፉ መጡና ከዚህም በፊት መጥፎ ሥራዎችን ይሠሩ ነበር:: «ህዝቦቼ ሆይ! እነዚህ ሴቶች ልጆቼ ናቸው:: ለእናንተ ይልቅ በጣም የጸዱ ናቸው:: አግቧቸው እናም አላህን ፍሩ:: በእንግዶቼም አታሳፍሩኝ። ከናንተ ውስጥ አንድ ቅን ሰው እንኳን የለምን?» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 79, '79. «ከሴቶች ልጆችህ እኛ ምንም ጉዳይ የሌለን መሆኑን በትክክል ታውቃለህ:: አንተም የምንሻውን በእርግጥ ታውቃለህ።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 80, '80. «በእናንተ ላይ ኃይል በኖረኝ ወይም ወደ ብርቱ ወገን ብጠጋ ኖሮ (የምሠራውን በሠራሁ ነበር)።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 81, '81. «ሉጥ ሆይ! እኛ የጌታህ መልዕክተኞች ነን:: ህዝቦች ወደ አንተ በክፉ አይደርሱብህም:: ቤተሰብህንም ይዘህ ከሌሊቱ በከፊሉ ውስጥ ሂድ:: ከናንተም አንድም ወደ ኋላው አይገላመጥ:: ሚስትህ ብቻ ስትቀር:: እነሆ እርሷንማ እነርሱን የሚያገኛቸው ስቃይ ሁሉ ያገኛታልና:: ቀጠሯቸው ንጋቱ ላይ ነው:: ንጋቱ ቅርብ አይደለምን?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 82, '82. እናም ትዕዛዛችን በመጣ ጊዜ ከተማይቱን ላይዋን ከታችዋ አድርገን ገለበጥናት:: ተከታታይም የሆነን የሸክላ ድንጋይ በእርሷ ላይ አዘነብንባት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 83, '83. ከጌታህ ዘንድ ምልክት የተደረገባት ስትሆን (አዘነብናት)። እርሷም (መንደሯ) ከበደለኞቹ ህዝቦች ሩቅ አይደለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 84, '84. ወደ መድየንም ወንድማቸውን ሹዐይብን ላክን:: አላቸውም: «ህዝቦቼ ሆይ! አላህን ብቻ ተገዙ:: ከእሱ ሌላ ለእናንተ አምላክ የላችሁም:: ስፍርንና ሚዛንን አታጉሉ:: እኔ በጸጋ ላይ ሆናችሁ አያችኋለሁ:: እኔም በእናንተ ላይ የከባቢን ቀን ቅጣት እፈራላችኋለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 85, '85. «ህዝቦቼ ሆይ! ስፍርንና ሚዛንን በትክክል ሙሉ:: ሰዎችን መብቶቻቸውን አታጓድሉባቸው:: በምድርም ውስጥ አጥፊዎች ሆናችሁ አታበላሹ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 86, '86. «አላህ ያስቀረላችሁ ለእናንተ የተሻለ ነው:: ትክክለኛ አማኞች እንደ ሆናችሁ አላህ በሰጣችሁ ውደዱ። እኔም መካሪ እንጂ በእናንተ ላይ ተጠባባቂ አይደለሁም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 87, '87. «ሹዐይብ ሆይ! ስግደትህ አባቶቻችን የሚገዙትን ጣኦታት እንድንተው ወይም በገንዘቦቻችን የምንሻውን መሥራትን እንድንተው ታዝሃለችን? አንተ በእርግጥ ታጋሹ ቅኑው አንተ ነህና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 88, '88. (እርሱም) አለ: «ህዝቦቼ ሆይ! ንገሩኝ እስቲ ከጌታዬ በሆነ አስረጅ ላይ ሆኜ ከእርሱም የሆነን መልካም ሲሳይ ቢሰጠኝ በቅጥፈት ልቀላቅለው ይገባልን? የከለከልኳችሁንም ነገር በመፈጸም ልለያችሁ አልሻም:: በተቻለኝ ያህል ማበጀትን እንጂ አልሻም:: ለደግ ሥራ መታደሌ በአላህ ፈቃድ ብቻ እንጂ በሌላ አይደለም:: በእርሱ ላይ ብቻ ተመካሁ:: ወደ እርሱም እመለሳለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 89, '89. «ወገኖቼ ሆይ! እኔን መከራከራችሁ የኑህን ህዝቦች ወይም የሁድን ህዝቦች ወይም የሷሊህን ህዝቦች ያገኛቸው ቅጣት ብጤ አይነት እንዲያገኛችሁ አይገፋፋችሁ:: የሉጥም ህዝቦች ከናንተ ሩቅ አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 90, '90. «ጌታችሁንም ምህረት ለምኑት ከዚያ ወደ እርሱ ተመለሱ። ጌታዬ አዛኝና ወዳድ ነውና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 91, '91. «ሹዐይብ ሆይ! ከምትለው ነገር ብዙውን አናውቀዉም (አይገባንም):: እኛም አንተን በኛ ውስጥ ደከማ ሆነህ እናይሃለን:: ጎሶችህም ባልኖሩ ኖሮ በወገርንህ ነበር:: አንተም በእኛ ላይ የተከበርክ አይደለህም።» አሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 92, '92. (እርሱም) አለ: «ህዝቦቼ ሆይ? ጎሳዎቼ በእናንተ ላይ ከአላህ ይልቅ የከበሩ ናቸውን? አላህን ከኋላችሁ ወደ ጀርባ አደረጋችሁት:: ጌታዬ በምትሠሩት ሁሉ ከባቢ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 93, '93. «ህዝቦቼ ሆይ! በችሎታችሁ ልክ ሥሩ እኔ ሠሪ ነኝ። የሚያዋርደው ቅጣት የሚመጣበትንና እርሱ ውሸታም የሆነው ማን እንደ ሆነ ወደ ፊት ታውቃላችሁ:: ጠብቁም እኔም ከናንተ ጋር ተጠባባቂ ነኝና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 94, '94. ትዕዛዛችን በመጣ ጊዜ ሹዐይብንና እነዚያን ከእርሱ ጋር ያመኑትን ከእኛ በሆነው ችሮታ አዳን:: እነዚያን የበደሉትንም (የጂብሪል) ጩኸት ያዘቻቸው። በየቤቶቻቸዉም ውስጥ ተንከፍርረው አደሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 95, '95. በእርሷ ውስጥ እንዳልነበሩ ሆኑ:: አስተዉሉ! ሠሙድ ከአላህ እዝነት እንደራቀች መድየንም ትራቅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 96, '96. ሙሳንም በታዐምራቶቻችንና በግልጽ ብርሃን በእርግጥ ላክነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 97, 'ወደ ፈርዖንና ወደስዎቹ ላክነው፡፡የፈርዖንን ነገር ህዝቦቹ ተከተሉ፡፡ የፈርዖን ነገር ቀጥተኛ አል ነበረም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 98, 'በትንሳኤ ቀን ህዝቦቹን ይቀድማል፡፡ ከዚያም ወደ አሳት ያወርዳቸዋል፡፡ የሚገቡትም አገባብ ምንኛ ከፋ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 99, '99. በዚችም በቅርቢቱ ዓለም እርግማንን አስከተልናቸው:: በትንሳኤም ቀን እንደዚሁ። የተሰጡት ስጦታ ምንኛ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 100, '100. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ከላይ የተነገረው ከከተሞቹ ወሬዎች የተወሰነው ነው:: ባንተ ላይ እንተርከዋለን:: ከእርሷ ቋሚና እጭድም የሆነ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 101, '101. እኛም አልበደልናቸዉም:: ግን ነፍሶቻቸውን በደሉ:: የጌታህ ጉዳይ በመጣ ጊዜ እነዚያ ከአላህ ሌላ የሚገዟቸው አማልክቶቻቸው ሁሉ በምንም አላዳኗቸዉም:: ከማክሰርም በስተቀር ምንም አልጨመሩላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 102, '102. (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህ ቅጣት የከተሞችን ሰዎች በዳዮች ሲሆኑ በቀጣቸው ጊዜ ልክ እንደዚህ ነው:: ቅጣቱ በእርግጥ አሳማሚና ብርቱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 103, '103. በዚህ ውስጥ የመጨረሻውን ቀን ቅጣት ለሚፈሩ ሁሉ መገሰጫ አለ:: ይህ የትንሳኤ ቀን ሰዎች በእርሱ የሚሰበሰቡበት ቀን ነው:: ይህ የሚጣዱት ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 104, '104. ይህንን ቀን ለተቆጠረም (ለተወሰነ) ጊዜ እንጂ አናቆየዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 105, '105. በሚመጣ ቀን ማንኛዉም ነፍስ በእርሱ ፈቃድ ቢሆን እንጂ አትናገርም:: ከእነርሱም መናጢም (እድለቢስ) እድለኛም አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 106, '106. እነዚያ ያመጹትማ በእሳት ውስጥ ናቸው:: ለእነርሱ በእርሷ ውስጥ ማናፋትና መንሰቅሰቅ አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 107, '107. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ከፈለገው በስተቀር ሰማያትና ምድር እስከዘወተሩ ድረስ በውስጧ ዘውታሪዎች ሲሆኑ በእሳት ውስጥ ይኖራሉ:: ጌታህ የሚፈልገውን ሠሪ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 108, '108. እነዚያ እድለኞቹማ ጌታ ከሻው በስተቀር ሰማያትና ምድር እስከ ዘወተሩ ድረስ በውስጧ ዘውታሪዎች ሆነው በገነት ውስጥ ይኖራሉ:: የማያቋርጥ ስጦታን ተሰጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 109, '109. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ከሓዲያን ከሚገዙት ጣኦት በመጠራጠር ውስጥ አትሁን:: አባቶቻቸው ከዚህ በፊት እንደሚገዙት እንጂ አይገዙም:: እኛም እነዚህን ፈንታቸውን የማይጓደል ሲሆን የምንሞላላቸው ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 110, '110. ለሙሳም መጽሐፍን በእርግጥ ሰጠነው:: በእርሱም ተለያዩበት። ከጌታህ ያለፈች ቃል ባልነበረች ኖሮ በመካከላቸው አሁን ይፈረድ ነበር:: እነርሱም ከእርሱ ከቁርኣን አወላዋይ በሆነ መጠራጠር ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 111, '111. ሁሉንም ጌታህ ሥራዎቻቸውን ምንዳቸውን በእርግጥ ይሞላላቸዋል:: እርሱ በሚሠሩት ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 112, '112. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደታዘዝከው ቀጥ በል። ካንተ ጋር ያመኑትም ቀጥ ይበሉ። ወሰንንም አትለፉ። እርሱ የምትሠሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 113, '113. ወደ እነዚያም ወደ በደሉት ህዝቦች አትዘንበሉ:: እሳት ትነካችኋለችና:: ከአላህ ሌላ ጠባቂዎች የሏችሁም ከዚያ አትረዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 114, '114. ሶላትንም በቀን ጫፍና ጫፎች ከሌሊትም ክፍሎች ፈጽም:: መልካም ሥራዎች ኃጢአቶችን ያስወግዳሉና:: ይህ ለተገሳጮች ሁሉ ግሳጼ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 115, '115. ታገስ አላህ የበጎ ሠሪዎችን ምንዳ አያጠፋምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 116, '116. ከናንተ በፊት ከነበሩት ከክፍለ ዘመናት (ሰዎች) ውስጥ በምድር ላይ ከማበላሸት የሚከለክሉ የመልካም ሥራዎች ቅሪት ባለቤቶች ለምን አልነበሩም? ግን ከእነርሱ ያዳንናቸው ጥቂቶቹ ከለከሉና ዳኑ:: እነዚያም የበደሉት ሰዎች አልከለከሉም። በእርሱ የተቀማጠሉበትን ተድላ ተከተሉ አመጠኞችም ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 117, '117. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ከተሞችን ባለቤቶቻቸው መልካም ሠሪዎች ሆነው ሳሉ በመበደል የሚያጠፋቸው አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 118, '118. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በሻ ኖሮ ሰዎችን ሁሉ አንድ ህዝብ ባደረጋቸው ነበር። የተለያዩም ከመሆን አይወገዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 119, '119. ጌታህ ያዘነለት ብቻ ሲቀር ከመለያየት አይወገዱም:: ለዚሁም ነው የፈጠራቸው:: የጌታህ ቃልም «ገሀነምን ከአጋንንትና ከሰዎች ከሁሉም በእርግጥ እሞላታለሁ።» በማለት ተፈጸመች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 120, '120. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመልዕክተኞቹም ዜናዎች ተፈላጊውን ሁሉንም ልብህን በእርሱ የምናጸናበትን እንተርክልሀለን። በዚህችም ሱራ እውነቱ ነገር፣ ለምእምናን ግሳጼና ማስታወሻ መጥቶልሀል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 121, '121. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነዚያም ለማያምኑት (እንዲህ) በላቸው: «ባላችሁበት ሁኔታ ላይ ሥሩ:: እኛ ሠሪዎች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 122, '122. «የራሳችሁን ውጤት ተጠባበቁ እኛ ተጠባባቂዎች ነንና።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (11, 123, '123. (መልዕክተኛችን ሙሐመድ ሆይ!) በሰማያትና በምድር ያለው ሚስጥር ሁሉ የአላህ ብቻ ነው:: ሁሉም ነገር ወደ እርሱ ብቻ ይመለሳል:: ስለዚህ እሱን ብቻ ተገዛው:: በእርሱም ላይ ብቻ ተመካ:: ጌታህም ከሚሰሩት ሁሉ ዘንጊ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 1, '1.አሊፍ፤ ላም፤ ራ፤ እነዚህ አናቅጽ ግልጽና የተብራራ ከሆነው መጽሐፍ አናቅጽ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 2, '2. እኛ ይህንን ቁርኣንን ትረዱት ዘንድ በዐረበኛ ቋንቋ አወረድነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 3, '3.(መልዕክተኛችን ሙሐመድ ሆይ!) ይህንን የቁርኣን ወደ አንተ በማውረዳችን እጅግ ውብና ማራኪ የሆነ ታሪክ እንተርክልሃለን:: ከዚህ በፊት አንተም ይህንን ታሪክ ከማያውቁት ነበርክ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 4, '4. (መልዕክተኛችን ሙሐመድ ሆይ!) ነብዩ ዩሱፍ በልጅነቱ ለአባቱ «አባቴ ሆይ! እኔ አስራ አንድ ኮከቦችን፤ ጨረቃንና ጸሐይን ሲሰግዱልኝ በሕልሜ አየሁኝ።» ባለ ጊዜ የሆነውን ታሪክ ለህዝቦችህ አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 5, '5. አባቱም አለ: «ልጄ ሆይ! ይህን ህልምህን ለወንድሞችህ አትንገር። ባንተ ላይ ተንኮል እንዳያሴሩ። ምክንያቱም ሰይጣን ለሰው ልጅ ሁልጊዜም ግልጽ ጠላት ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 6, '6. «ጌታህ ልክ ይህን ህልም እንዳሳየህ ሁሉ ለነብይነትም ይመርጥሃል:: የንንግግሮችን ፍፃሜ ያስተምርሃል:: ጸጋውንም ቀደም ሲል ለአባቶችህ ለኢብራሂምና ለኢስሃቅ እንደሞላ ሁሉ ላንተና ለያዕቁብ ቤተሰቦችም ይሞላል:: ጌታህ ሁሉን አዋቂና ጥበበኛ ነውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 7, '7. በዩሱፍና በወንድሞቹ ታሪክ ዉስጥ እውቀትን በመሻት ለሚጠይቁ ሁሉ እያሌ ተዓምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 8, '8. (መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) ባሉ ጊዜ: «እኛ በቁጥር ብዙዎች ሁነን እያለ ዩሱፍና ወንድሙ (ብንያም) ከአባታችን ዘንድ ከእኛ ይበልጥ ተወዳጆች ናቸው:: በእውነቱ አባታችን ግልጽ ስህተት ውስጥ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 9, '9. «ዩሱፍን ግደሉት ወይም እሩቅ ቦታ ጣሉት:: ይህን ካረጋችሁ የአባታችሁን ፊት ትኩረትና ውዴታ የራሳችሁ ብቻ ታደርጋላችሁ:: ከዚህ በኋላ ከኃጥያታችሁ በመመለስ መልካም ሰዎች ትሆናለችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 10, '10. ከእነሱ አንድ ተናጋሪ «ዩሱፍን አትግደሉ ግን በጉድጓድ አዘቅት ጨለማ ውስጥ ጣሉት፤ ከተጓዢዎች አንዱ ያነሳዋልና፡፡ ሠሪዎች ብትኾኑ (በዚሁ ተብቃቁ) አላቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 11, '11. አሉም: «አባታችን ሆይ! በዩሱፍ ጉዳይ እኛ ለእርሱ ቅን አሳቢዎች ሁነን ሳለ ለምን አታምነንም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 12, '12. «እስቲ ይዝናና ይጫወት ዘንድ ነገ ከእኛ ጋር አብረህ ላከው::እኛም ለእርሱ ጠባቂዎች ነን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 13, '13. አባቱም «እርሱን መውሰዳችሁ ያሳዝነኛል። ዘንግታችሁት ተኩላ እንዳይበላዉም እፈራለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 14, '14. እነርሱም «እኛ እንዲህ ጭፍሮች ሆነን ተኩላ ከበላውማ ከሳሪዎቹ እኛ ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 15, '15. እርሱንም ወስደውት በጉድጓድ ወለል ላይ ሊጥሉት በወሰኑ ጊዜ «እነርሱ ሳያውቁ ይህን ጸያፍ ተግባራቸውን ወደ ፊት ትነግራቸዋለህ» የሚል መልዕክት ላክንለት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 16, '16. አባታቸውንም በምሽት እያለቀሱ መጡት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 17, '17. «አባታችን ሆይ! እኛ ለሩጫና ለውርወራ ልንሽቀዳደም ሄድን። ዩሱፍንም እቃችን ዘንድ ተውነው:: ወዲያዉም ተኩላ በላው:: አንተም እውነተኞች ብንሆንም የምታምነን አይደለህም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 18, '18. በቀሚሱም ላይ የውሸትን ደም አመጡ:: አባታቸውም: «ይህ ትክክል አይደለም። ይልቁን ነፍሶቻችሁ ውሸት ነገርን ለናንተ ሸለሙላችሁ:: ስለዚህ መልካም ትዕግስት ማድረግ አለብኝ:: በምትሉትም ነገር ላይ መታገዣው አላህ ብቻ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 19, '19. መንገደኞችም መጡ:: ውሃ ቀጂያቸውንም ላኩ:: አኮሌውንም ወደ ጉድጎዱ ሰደደ:: የምስራች:: «ይህ ልጅ ነው።» አለ:: ሸቀጥ አድርገዉም ደበቁት:: አላህ የሚሠሩትን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 20, '20. በርካሽ ዋጋና በሚቆጠሩ ዲርሃሞች ሸጡት:: በእርሱም ላይ ከቸልተኞቹ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 21, '21. ያም ከምስር የገዛው ሰው ለሚስቱ «ይህ ልጅ መኖሪያውን አክብሪ ሊጠቅመን ወይም ልጅ አድርገን ልንይዘው ይከጅላልና።» አላት:: ልክ እንደዚሁ ለዩሱፍ ገዥ ልናደርገውና የሕልሞችንም ፍች ልናስተምረው በምድር ላይ አስመቸነው:: አላህ በነገሩ ሁሉ ላይ አሸናፊ ነው። ግን አብዛኞቹ ሰዎች ይህን አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 22, '22. ጥንካሬውንም በደረሰ ጊዜ ጥበብንና ዕውቀትን ሰጠነው:: ልክ እንደዚህም መልካም ሠሪዎችን ሁሉ እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 23, '23. ያችም እርሱ በቤትዋ የነበረባት ሴት ከነፍሱ አባበለችው:: ደጃፎቹንም ዘጋችና «ይኸው ላንተ ተዘጋጂቼልሃለሁና ቶሎ በል» አለችው:: እሱም «ከዚህ ጸያፍ ተግባር በአላህ እጠበቃለሁ:: እርሱ የገዘኝ ጌታዬ ኑሮዬን ያሳመረልኝ ነውና አልከዳዉም:: እነሆ በደለኞች ሁሉ አይድኑምና» አላት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 24, '24. በእርሱም በእርግጥ አሰበች፡፡ በእርሷም አሰበ ፡፡የጌታውን ማስረጃ ባላዬ ኖሮ (በእርሷም ባሰበ ነበር) ፡፡ልክ እንደዚሁ መጥፎ ነገርንና ኃጢአትን ከእርሱ ላይ ልንመልስለት አስረጃችንን አሳየነው ፡፡እርሱ ከተጠበቁት ባሮቻችን አንዱ ነዉና ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 25, '25. እርሱና እርሷ በሩን ተሸቀዳደሙና ቀሚሱን ከኋላው ቀደደችው። ባለቤትዋን እበሩ አጠገብ አገኙት:: እርሷም ቀደም ብላ «በባለቤትህ መጥፎን ያሰበ ሰው ቅጣቱ መታሰር ወይም አሳማሚ ስቃይ እንጂ ሌላ አይደለም።» አለችው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 26, '26. ዩሱፍም «እርሷ ናት ከነፍሴ ያባበለችኝ።» አለ:: ከቤተሰቦቿም አንድ መስካሪ (እንዲህ) መሰከረ: «ቀሚሱ ከበስተፊት ተቀዶ ከሆነ እርሷ እውነት ተናገረች:: እርሱ ከውሸታሞቹ አንዱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 27, '27. «ቀሚሱም ከበስተኋላው ተቀዶ እንደሆነ ዋሸች:: እርሱም ከእውነተኞቹ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 28, '28. ቀሚሱንም ከበስተኋላ ተቀዶ ባየ ጊዜ አለ: «እርሱ የተናገርሽው ከተንኮላችሁ ነው። የእንናንተ የሴቶች ተንኮል በእርግጥ ብርቱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 29, '29. «ዩሱፍ ሆይ! አንተም ከዚህ ወሬ ተከልከል:: አንቺም ለኃጢአትሽ ማርታን ለምኝ። አንቺ ከስሕተተኞቹ ሆነሻልና።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 30, '30. በከተማው ያሉ ሴቶችም «የዐዚዝ ሚስት ሰራተኛዋን ከነፍሱ ታባብለዋለች:: በእውነቱ ፍቅሩ ልቧን መቷታል:: እኛ በግልጽ ስሕተት ውስጥ ሆና በእርግጥ እናያታለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 31, '31. እርሷም ሐሜታቸውን በሰማች ጊዜ ወደነሱ ላከችባቸው:: ግብዣንም ለእነርሱ አዘጋጀችላቸው:: ለያንዳንዳቸዉም ቢላዋን ሰጠችና «በእነርሱም ላይ ውጣ።» አለችው:: እነርሱም በተመለከቱት ጊዜ በጣም አደነቁት:: እጆቻቸዉንም ቆረጡ። «ለአላህ ጥራት ይገባው:: ይህ ሰው አይደለም:: ይህ የተከበረ መልአክ እንጂ ሌላ አይደለም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 32, '32. በዚህ ጊዜ «ይህ እኮ ነው ያ በእርሱ ፍቅር ያማችሁኝ ሰው:: በእርግጥም ከነፍሱ አባባልኩት ግና እርሱ እንቢ አለ:: ወደፊትም የማዘውን ነገር ባይሠራ በእርግጥ ይታሰራል ከወራዶቹም ይሆናል።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 33, '33. «ጌታዬ ሆይ! ወደ እርሱ ከሚጠሩኝ ነገር (ከዝሙት) ይልቅ መታሰር ለእኔ የተወደደ ነው:: ተንኮላቸውንም ከእኔ ላይ ባትመልስልኝ ወደ እነርሱ እዘነበላለሁ:: ከስሕተተኞቹም እሆናለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 34, '34. ጌታዉም ጸሎቱን ተቀበለው፤ ተንኮላቸውንም ከእርሱ መለሰለት:: እነሆ እርሱ ሁሉን ሰሚና ሁሉን አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 35, '35. ከዚያም ማስረጃዎችን ካዩ በኋላ እስከ ጊዜ ድረስ እንዲያስሩት ለእነርሱ ታያቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 36, '36. ከእሱም ጋር ሁለት ወጣቶች እስር ቤቱ ገቡ:: አንደኛቸው «እኔ በሕልሜ የወይን ጠጅን ስጠምቅ አየሁ።» አለ:: ሌላው ደግሞ «እኔ በራሴ ላይ ቂጣን ተሸክሜ ከእሱ በራሪ አሞራ ስትበላ አየሁ ፍችውን ንገረን እኛ ከአሳማሪዎች ሁነህ እናይሃለንና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 37, '37. ዩሱፍም አለ: «ማንኛዉም የምትሰጡት ምግብ ለእናንተ ከመምጣቱ በፊት ፍችውን የምነግራችሁ ቢሆን እንጂ አይመጣላችሁም:: ይህ ጉዳይ ጌታዬ ካሳወቀኝ ነገር ነው:: እኔም በአላህ የማያምኑትንና በመጨረሻይቱ ዓለም ከሓዲያን የሆኑ ሕዝቦችን ሃይማኖት ትቻለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 38, '38. «የአባቶቼንም የኢብራሂምን፤ የኢስሐቅንና የያዕቁብን ሃይማኖት ተከትያለሁ:: ለእኛ በአላህ ምንንም ማጋራት አይገባንም:: ያ አለማጋራት በእኛ ላይና በሰዎች ላይ የአላህ ችሮታ ነው:: ግን አብዛኞቹ ሰዎች አያመሰግኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 39, '39. «የእስር ቤት ጓደኞቼ ሆይ! የተለያዩ አምላኮች ይሻላሉን ወይስ አሸናፊውና አንዱ አላህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 40, '40. «ከእርሱ ሌላ እናንተና አባቶቻችሁ አማልክት ብላችሁ የጠራችኋቸውን ስሞች እንጂ አትገዙም። አላህ በእርሷ ምንም አስረጂ አላወረደም። ፍርዱ የአላህ እንጂ ሌላ አይደለም:: እርሱን እንጂ ሌላን እንዳትገዙም አዟል:: ይህ ትክክለኛው ሃይማኖት ነው:: ግን አብዛኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 41, '41. «የአስር ቤት ጓደኞቼ ሆይ! አንደኛችሁማ ንጉሡን ጠጅ ያጠጣል። ሌላውም ይሰቀላል:: ከራሱም በራሪ አሞራ ትበላለች:: ያ ፍቹን የምትጠይቁት ነገር ተፈጸመ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 42, '42. ለዚያም ከሁለቱ እርሱ የሚድን መሆኑን ለተጠራጠረው እጌታህ ዘንድ አስታውሰኝ አለው፡፡ ጌታውንም ከማስታወስ ሰይጣን አስረሳው፡፡ ለጥቂት ዓመታትም በወህኒ ቤቱ ውስጥ ቆየ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 43, '43. ንጉሡም «እኔ ሰባት የሰቡ ላሞችን ሰባት የከሱ ላሞች ሲበሉዋቸው፤ ሰባት ለምለም ዘለላዎችም ሌሎች ሰባት ደረቆችን ስብርብር ሲያደርጉ በሕልሜ አየሁ:: እናንተ ታላላቅ ሰዎች ሆይ! ሕልም መፍታት የምታውቁ ከሆናችሁ ሕልሜን ፍቱልኝ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 44, '44. «ሕልሞችህ ቅዠቶች ናቸው:: እኛም የሕልሞችን ፍች አዋቂዎች አይደለንም።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 45, '45. ያም ከሁለቱ መካከል የዳነውና ከብዙ ጊዜ በኋላ ዩሱፍን ያስታወሰው ሰው «እኔ ፍቹን እነግራችኋለሁና ላኩኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 46, '46. «አንተ እውነተኛው ዩሱፍ ሆይ! ሰባትን የሰቡ ላሞች ሰባት ከሲታዎች ላሞች ሲበሏቸው፤ ሰባትን ለምለም ዘለላዎችም ሌሎች ሰባት ደረቆች በእነርሱ ላይ ስብርብር ሲያደርጉ ያየን ሰው ሕልም ፍች እስቲ ተችልን:: ያውቁ ዘንድ ወደ ሰዎቹ ልመለስ እከጅላለሁና።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 47, '47. እርሱም አለ: «ሰባትን የተከታተሉ ዓመታት ትዘራላችሁ ያጨዳችሁትንም ሁሉ ከምትበሉት ጥቂት በስተቀር በዘለላው ውስጥ ተውት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 48, '48. «ከዚያም ከነዚያ በኋላ ካደለባችሁት ጥቂት ሲቀር ለእነርሱ ያደለባችሁትን ሁሉ የሚበሉ ሰባት የችግር ዓመታት ይመጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 49, '49. «ከዚያ ከእነዚያ በኋላ ሰዎቹ በእርሱ ዝናብ የሚያገኙበትና በእርሱም ወይንን የሚጨምቁበት ዓመት ይመጣል።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 50, '50. ንጉሡም «እርሱን አምጡልኝ።» አለ። መልእክተኛዉም ወደ ዩሱፍ በመጣ ጊዜ ዩሱፍ: «ወደ ጌታህ ተመለስና የእነዚያን እጆቻቸውን የቆረጡትን ሴቶች ሁኔታ ጠይቀው ጌታዬ ተንኮላቸውን አዋቂ ነውና።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 51, '51. ንጉሡም «ዩሱፍን ከነፍሱ ባባበላችሁት ጊዜ ነገራችሁ ምንድን ነው?» አላቸው። «ለአላህ ጥራት ይገባው በእርሱ ላይ ምንም መጥፎን ነገር አላወቅንም (አላየንም)።» አሉት። የዐዚዝ ሚስትም አለች: «አሁን እውነቱ ተገለጸ እኔ አባበልኩት እርሱም ከእውነተኞቹ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 52, '52. «ይህ ጌታዬ ሩቅ ሆኖ ሳለ ያልከዳሁት መሆኔንና አላህም የከዳተኞችን ተንኮል የማያቃና መሆኑን እንዲያውቅ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 53, '53. «ነፍሴንም ከስሕተት አላጠራም:: ነፍስ ሁሉ ጌታዬ ያዘነላት (የጠበቃት) ካልሆነች በስተቀር በመጥፎ ነገር በእርግጥ አዛዥ ናትና:: ጌታዬ በጣም መሐሪና አዛኝ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 54, '54. ንጉሡም «እርሱን አምጡልኝ ለራሴ የግሌ አደርገዋለሁና።» አለ። ባናገረዉም ጊዜ «አንተ ዛሬ እኛ ዘንድ ባለሟልና ታማኝ ነህ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 55, '55. «በምድር ግምጃ ቤቶች ላይ ሹም አድርገኝ እኔ ጠባቂ አዋቂ ነኝና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 56, '56. እንደዚሁም ለዩሱፍ በምድር ላይ ከእርሷ በፈለገው ስፍራ የሚሰፍር ሲሆን አስመቸነው:: በችሮታችን የምንሻውን ሰው እንለያለን። የበጎ ሠሪዎችንም ዋጋ አናጠፋም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 57, '57. የመጨረሻይቱም ዓለም ምንዳ ለእነዚያ ላመኑትና ይጠነቀቁ ለነበሩት የበለጠ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 58, '58. የዩሱፍ ወንድሞችም መጡ በእርሱም ላይ ገቡ:: እነርሱም እርሱን የሳቱት ሲሆኑ አወቃቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 59, '59. ጉዳያቸውን ፈጽሞ ስንቃቸውንም ባዘጋጀላቸው ጊዜ አለ: «ከአባታችሁ በኩል የሆነውን ወንድማችሁን አምጡልኝ እኔ ከአስተናጋጆች ሁሉ በላጭ ስሆን ስፍርን የምሞላ መሆኔን አታዩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 60, '60. «እርሱንም ባታመጡልኝ። እኔ ዘንድ ለእናንተ ስፍር የላችሁም:: አትቀርቡኝምም።» አለ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 61, '61. «ስለ እርሱ አባቱን በጥብቅ እንጠይቃለን፤ እኛም ይህንን በእርግጥ ሰሪዎች ነን።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 62, '62. ለአሽከሮቹም፡- «ወደ ቤተሰቦቻቸው በተመለሱ ጊዜ ሸቀጣቸውን (ገንዘባቸውን) ያውቋት ዘንድ በየጓዞቻቸው ውስጥ አድርጉላቸው ሊመለሱ ይከጀላልና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 63, '63. ወደ አባታቸዉም በተመለሱ ጊዜ፡- «አባታችን ሆይ! (ወንድማችንን እስከምንወስድ) ስፍር ከኛ ተከልክሏል። ስለዚህ ወንድማችንን ከእኛ ጋር ላከው፤ ይሰፈርልናልና እኛም ለእርሱ ጠባቂዎች ነን።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 64, '64. «ከአሁን በፊት በወንድሙ ላይ እንዳመንኳችሁ እንጂ በእርሱ ላይ አምናችኋለሁን? አላህም በጠባቂነት ከሁሉ የበለጠ ነው:: እርሱም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነው።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 65, '65. እቃቸውንም በከፈቱ ጊዜ ሸቀጣቸውን ወደ እነርሱ ተመልሶ አገኙት። «አባታችን ሆይ! ምን እንፈልጋለን? ይህች ሸቀጣችን ናት ወደ እኛ ተመልሳልናለች እንረዳባታለን:: ለቤተሰቦቻችንም እንሸምታለን። ወንድማችንንም እንጠብቃለን:: የአንድ ግመልን ጭነትም እንጨምራለን:: ይህ በንጉሱ ላይ ቀላል ስፍር ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 66, '66. «ካልተከበባችሁ በስተቀር እርሱን በእርግጥ የምታመጡልኝ ለመሆናችሁ ከአላህ የሆነን ቃልኪዳን (መተማመኛ) እስከምትሰጡኝ ድረስ ከናንተ ጋር ፈጽሞ አልከዉም።» አላቸው። መተማመኛቸውንም በሰጡ ጊዜ «አላህ በምንለው ሁሉ ላይ ዋስ ነው።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 67, '67. አለም፡- «ልጆቼ ሆይ! በአንድ በር አትግቡ:: ግን በተለያዩ በሮች ግቡ:: ከአላህም ፍርድ በምንም አልጠቅማችሁም (አልመልስላችሁም)። ፍርዱ የአላህ እንጂ የሌላ አይደለም:: በእርሱ ላይ ብቻ ተመካሁ:: ተመኪዎችም ሁሉ በእርሱ ላይ ብቻ ይመኩ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 68, '68. አባታቸው ካዘዛቸው ስፍራ በገቡ ጊዜ ከአላህ ፍርድ ምንም ነገር ከእነርሱ የሚከለክልላቸው አልነበረም:: ግን በየዕቁብ ነፍስ ውስጥ የነበረች ጉዳይ ናት:: ፈጸማት። እርሱም ስላሳወቅነው የእውቀት ባለቤት ነው። ግን አብዛኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 69, '69. በዩሱፍ ላይ በገቡ ጊዜም ወንድሙን ወደ እርሱ አስጠጋውና «እነሆ እኔ ወንድምህ ነኝ:: ይሰሩት በነበሩትም ሁሉ አትበሳጭ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 70, '70. እቃቸውን ባዘጋጀላቸው ጊዜ ዋንጫይቱን በወንድሙ እቃ ውስጥ አደረገና ከዚያ «እናንተ ባለ ግመሎች ሆይ! እናንተ በእርግጥ ሌቦች ናችሁ።» ሲል ጠሪ ተጣራ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 71, '71. ወደ እነርሱ ዞረዉም: «ምንድን ጠፋችሁ?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 72, '72. «የንጉሱ መስፈሪያ ጠፍቶናል እርሱንም ላመጣ ሰው የአንድ ግመል ጭነት አለው። እኔም በእርሱ ተያዥ ነኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 73, '73. «በአላህ እንምላለን! በምድር ላይ ለማጥፋት እንዳልመጣን በእርግጥ አውቃችኋል ሌቦችም አልነበርንም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 74, '74. «ውሸታሞች ብትሆኑስ ቅጣቱ ምንድን ነው?» አሏቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 75, '75. «ቅጣቱ በየዕቁብ ሕግ እቃው በጓዙ ውስጥ የተገኘበት ሰው ራሱ ባሪያ ተደርጎ መውሰድ ነው። እርሱም ቅጣቱ ነው:: ልክ እንደዚሁ በደለኞችን እንቀጣለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 76, '76. ምርመራውን ከወንድሙ እቃ በፊትም በእቃዎቻቸው ጀመረ:: ከዚያ ዋንጫይቱን ከወንድሙ እቃ ውስጥ አወጣት። ልክ እንደዚሁ ለዩሱፍ ብልሃትን አስተማርነው:: አላህ ባልሻ ኖሮ በንጉሱ ሕግ ወንድሙን ሊይዝ አይገባዉም ነበር:: የምንሻውን ሰው በደረጃዎች ከፍ እናደርጋለን። ከእውቀት ባለቤቶች ሁሉ በላይም አዋቂ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 77, '77. «እርሱ ቢሰርቅ ከአሁን በፊት የእርሱው ወንድም በእርግጥ ሰርቋል።» አሉ። ዩሱፍም ይህችን (አስቀያሚ ንግግር) በነፍሱ ውስጥ ደበቃት:: ለእነርሱም አልገለጣትም። በልቡ «እናንተ ሥራችሁ የከፋ ነው:: አላህ የምትሉትን ሁሉ ይበልጥ አዋቂ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 78, '78. «አንተ የተከበርከው ሆይ! ለእርሱ በእርግጥ ታላቅ ሽማግሌ አባት አለው:: ስለዚህ በእርሱ ስፍራ አንደኛችንን ያዝ:: እኛ ከመልካም ሠሪዎች ሆነህ እናይሃለንና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 79, '79. «ዕቃችንን እርሱ ዘንድ ያገኘንበትን ሰው እንጂ ሌላን ከመያዝ በአላህ እንጠበቃለን:: እኛ ያን ባደረግን ጊዜ በእርግጥ በዳዮች ነን።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 80, '80. ከእርሱም ተስፋን በቆረጡ ጊዜ የሚመካከሩ ሆነው ገለል አሉ:: ታላቃቸውም አለ: «አባታችሁ በእናንተ ላይ ከአላህ የሆነን መተማመኛ ቃል ኪዳን በእርግጥ የያዘባችሁ መሆኑንና ከዚህም በፊት በዩሱፍ ላይ ግፍ የሠራችሁትን አታውቁምን? ስለዚህ አባቴ ለእኔ እስከሚፈቅድልኝ ወይም አላህ ለእኔ እስከሚፈርድልኝ ድረስ የምስርን (የግብጽን) ምድር አልለይም:: እርሱ ከፈራጆች ሁሉ በላጭ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 81, '81. «ወደ አባታችሁ ተመለሱ:: በሉትም: ‹አባታችን ሆይ ልጅህ ሰረቀ፤ ባወቅነዉም ነገር እንጂ አልመሰከርንም:: ሩቁንም ነገር ምስጢሩን አዋቂዎች አልነበርንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 82, '82. «‹ያችንም በውስጧ የነበርንባትን ከተማ ያችንም በውስጧ የመጣነውን ባለ ግመል ጓድ ጠይቅ እኛም በእርግጥ እውነተኞች ነን።›»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 83, '83. ያዕቁብም፡- «አይደለም። ነፍሶቻችሁ አንዳች ነገርን ለእናንተ ሸለሙላቸሁና ሠራችሁት እንጂ:: እናም መልካም ትዕግስት ማድረግ አለብኝ:: እነርሱን ሁሉንም የተሰበሰቡ ሆነው አላህ ሊያመጣልኝ ይከጀላል:: እነሆ እርሱ ሁሉን አዋቂና ጥበበኛ ነውና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 84, '84. ከነርሱም ዞር አለና፡- «በዩሱፍ ላይ ዋ ሐዘኔ!» አለ:: ዓይኖቹም ከሐዘን የተነሳ ነጡ:: እርሱም በትካዜ የተሞላ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 85, '85. እነርሱም፡- «በአላህ እንምላለን! ለጥፋት የቀረብክ እስከምትሆን ወይም ከጠፊዎቹ እስከምትሆን ድረስ ዩሱፍን ከማውሳት አትወገድም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 86, '86. «ጭንቀቴንና ሐዘኔን የማሰሙተው ወደ አላህ ብቻ ነው። ከአላህ በኩል የማታውቁትን ነገር እኔ አውቃለሁና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 87, '87. «ልጆቼ ሆይ! ሂዱ ከዩሱፍና ከወንድሙም ወሬ ተመራመሩ:: ከአላህም እዝነት ተስፋ አትቁረጡ:: እነሆ ከአላህ እዝነት ከሓዲያን ህዝቦች እንጂ ማንም ተስፋ አይቆርጥም።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 88, '88. በእርሱም ላይ በገቡ ጊዜ: «አንተ የተከበርከው ሆይ! እኛንም ቤተሰቦቻችንንም ጉዳት ደረሰብን። እርካሽ ሸቀጥም ይዘን መጥተናል:: ስፍርንም ለእኛ ሙላልን:: በእኛም ላይ መጽውት:: አላህ መጽዋቾችን ይመነዳልና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 89, '89. «እናንተ የማታውቁ በነበራችሁ ጊዜ በዩሱፍና በወንድሙ ላይ የሠራችሁትን ግፍ አወቃችሁን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 90, '90. «አንተ በእርግጥ አንተ ዩሱፍ ነህን?» አሉት። «አዎ እኔ በትክክል ዩሱፍ ነኝ:: ይህም ወንድሜ ነው:: አላህ በእኛ ላይ በእርግጥ ለገሰልን:: እነሆ የሚጠነቀቅና የሚታገስ ሰው አላህ ይክሰዋል:: አላህ የበጎ አድራጊዎችን ዋጋ አያጠፋምና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 91, '91. «በአላህ እንምላለን! አላህ በእኛ ላይ በእርግጥ አበለጠህ፤ እኛም በእርግጥ አጥፊዎች ነበርን።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 92, '92. እርሱም አላቸው: «ዛሬ በእናንተ ላይ ምንም ወቀሳ የለባችሁም። አላህ ለእናንተ ይምራል። እርሱም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 93, '93. «ይህንን ቀሚሴን ይዛችሁ ሂዱ:: በአባቴ ፊትም ጣሉት:: የሚያይ ሆኖ ይመጣልና:: ቤተሰቦቻችሁንም በሙሉ ሰብስባችሁ አምጡልኝ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 94, '94. ግመል ጫኞችም ከግብጽ በወጡ ጊዜ አባታቸው «እኔ የዩሱፍን ሽታ በእርግጥ አገኛለሁ:: ባታቄሉኝ ኖሮ ታምኑኝ ነበር።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 95, '95. «በአላህ እንምላለን! አንተ በእርግጥ እስካሁንም በዚያው በቀድሞው ስህተትህ ውስጥ ነህ።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 96, '96. አብሳሪዉም በመጣ ጊዜ ቀሚሱን በፊቱ ላይ ጣለው፤ ወዲያዉም የሚያይ ሆነ:: «እኔ ለእናንተ ከአላህ በኩል የማታውቁትን አውቃለሁ አላልኳችሁም ነበርን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 97, '97. «አባታችን ሆይ! ለኃጢያቶቻችን ምሕረትን ለምንልን:: እኛ ጥፋተኞች ነበርንና።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 98, '98. «ወደ ፊት ለእናንተ ጌታዬን ምሕረትን እለምንላችኋለሁ:: እነሆ እርሱ መሓሪ አዛኝ ነውና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 99, '99. በዩሱፍ ላይም በገቡ ጊዜ ወላጆቹን ወደ እርሱ አስጠጋቸው፤ «በአላህም ፈቃድ ጥብቆች ስትሆኑ ሚስርን (ግብጽ) ግቡ።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 100, '100. ወላጆቹንም በዙፋኑ ላይ አወጣቸው ለርሱም ሰጋጆች ሆነው ወረዱለት። «አባቴም ሆይ! ይህ ፊት ያየኋት ሕልሜ ፍች ነው፡፡ ጌታዬ በእርግጥ እውነት አደረጋት፡፡ ከወህኒ ቤትም ባወጣኝና ሰይጣንም በእኔና በወንድሞቼ መካከል ካበላሸ በኋላ እናንተን ከገጠር ባመጣችሁ ጊዜ በእርግጥ ለእኔ መልካም ዋለልኝ:: ጌታዬ ለሚሻው ነገር እዝነቱ ረቂቅ ነው:: እነሆ እርሱ አዋቂውና ጥበበኛው ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 101, '101. «ጌታዬ ሆይ! ከንግስና በእርግጥ ሰጠኸኝ:: ከህልሞችም ፍች አስተማርከኝ:: የሰማያትና የምድር ፈጣሪ ሆይ! አንተ በቅርቢቱና በመጨረሻይቱ ዓለም ረዳቴ ነህ:: ሙስሊም ሆኜ ግደለኝ:: ወደ መልካም ሰሪዎችም አስጠጋኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 102, '102. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ወደ አንተ የምናወርደው ሲሆን ከሩቅ ወሬዎች ነው:: አንተም እነርሱ በዩሱፍ ላይ የሚያሴሩ ሆነው ነገራቸውን በቆረጡ ጊዜ እነርሱ ዘንድ አብረህ አልነበርክም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 103, '103. አብዛኛዎቹ ሰዎች ለማመናቸው ብትጓጓም የሚያምኑ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 104, '104. (መልዕክተኛችን ሙሐመድ ሆይ!) በቁርኣን ላይ ምንም ዋጋን አትጠይቃቸዉም:: እርሱ ለዓለማት ግሳጼ እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 105, '105. በሰማያትና በምድር ካለችው ምልክት ብዙይቱ እነርሱ ከእርሷ ዘንጊዎች ሆነው በእርሷ ላይ ያልፋሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 106, '106. አብዛኞቻቸዉም እነርሱ አጋሪዎች ሆነው እንጂ በአላህ አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 107, '107. ከአላህ ቅጣት ሽፋኝ አደጋ የምትመጣባቸው ወይም ሰዓቲቱ እነርሱ የማያውቁ ሲሆኑ በድንገት የምትመጣባቸው መሆኑዋን አይፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 108, '108. (መልዕክተኛችን ሙሐመድ ሆይ!) «ይህ መንገዴ ነው:: ወደ አላህ እጠራለሁ:: እኔም የተከተለኝም ሰው በግልጽ ማስረጃ ላይ ነን:: ጥራትም ለአላህ ብቻ ይገባው:: እኔም ከአጋሪዎች አይደለሁም።» በል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 109, '109. ካንተ በፊትም ከከተሞች ሰዎች ወደነርሱ ራዕይ የምናወርድላቸው የሆኑን ወንዶችን እንጂ አላክንም:: በምድር ላይ አይሄዱምና የእነዚያን ከእነርሱ በፊት የነበሩትን ሰዎች መጨረሻ እንዴት እንደሆነ አይመለከቱምን? የአኺራ ደስታ ለተጠነቀቁት ሰዎች ሁሉ በእርግጥ የተሻለች ናት:: አታውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 110, '110. መልዕክተኞች ተስፋ በቆረጡና እነርሱ በእርግጥ የተዋሹ መሆናቸውን በተጠራጠሩ ጊዜ እርዳታችን መጣላቸው:: ከዚያ እኛ የምንፈልገው ሰው እንዲድን ተደረገ:: ቅጣታችንም ከአመፀኞቹ ህዝቦች ላይ አይመለስም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (12, 111, '111. በታሪካቸው ውስጥ ለአዕምሮ ባለቤቶች ሁሉ በእርግጥ መገሰጫ ነበረ:: ይህ ቁርኣን የሚቀጣጥፍ ወሬ አይደለም:: ይልቁንም ያንን በስተፊቱ ያለውን አረጋጋጭ፤ ሁሉን ጉዳዮች ገላጭና ለሚያምኑ ህዝቦችም ሁሉ መሪ፤ ችሮታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 1, '1. አሊፍ ፤ላም ፤ሚይም፤ ራ፤ (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚህ አናቅጽ ከመጽሐፉ አናቅጽ ናቸው:: ያም ከጌታህ ወደ አንተ የተወረደው እውነት ነው:: ግን አብዛኛዎቹ ሰዎች አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 2, '2. አላህ ያ ሰማያትን የምታይዋት ቋሚዎች ሳይኖራት በችሎታው ከፍ ያረጋት፤ ከዚያ በዐርሹ ላይ ከፍ ያለ፤ ጸሐይንና ጨረቃንም የገራ ነው:: ሁሉም ለተወሰነ ጊዜ ይሮጣሉ:: ነገሩን ሁሉ ያስተናብራል:: ከጌታችሁ ጋር መገናኘትን ታረጋግጡ ዘንድ ተዓምራትን ይዘረዝራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 3, '3. እርሱ (አላህ)ያ ምድርን የዘረጋ፤ በእርሷም ውስጥ ተራራዎችንና ወንዞችን ያደረገ:: በውስጧም ከፍሬዎች ሁሉ ሁለት ሁለት ዓይነቶችን ያደረገ ነው:: ሌሊትን በቀን ይሸፍናል:: በዚህም ውስጥ ለሚያስተነትኑ ህዝቦች ሁሉ ብዙ ምልክቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 4, '4. በምድርም ውስጥ የተጎራበቱ ቁርጥራጮች አሉ:: የወይኖች አትክልቶችም፤ አዝርዕቶችም መንታዎችና መንታዎች ያልሆኑ ዘንባባዎችም አሉ:: በአንድ ውሃ ይጠጣሉ:: በጣዕም ግን ይለያያሉ ከፊልዋንም በከፊሉ ላይ በሚበላው ሰብል እናበልጣለን:: በዚህም ውስጥ ለሚያውቁ ሕዝቦች ሁሉ ብዙ ተአምራት አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 5, '5. (መልዕክተኛችን ሙሐመድ ሆይ!) ብትደነቅም አፈር በሆንን ጊዜ እኛ አዲስ ፍጥረት እንሆናለን? ማለታቸው በጣም የሚደንቅ ነው:: እነዚህ እነዚያ ሰዎች ማለት እነዚያ በጌታቸው የካዱት ሰዎች ናቸው:: እነዚህም እንዛዝላዎች በአንገቶቻቸው ላይ ያሉባቸው ናቸው:: እነዚህም የእሳት ጓዶች ናቸው:: እነርሱ በውስጧ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ በፊት የመሰሎቻቸው ቅጣቶች በእርግጥ ያለፉ ሲሆኑ ከመልካሙ በፊት በመጥፎ ያስቸኩሉሃል! ጌታህም ለሰዎች ሁሉ ከመበደላቸው ጋር በእርግጥ የምህረት ባለቤት ነው:: ጌታህ በእርግጥ ቅጣተ ብርቱም ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ በአላህ የካዱት ሰዎች «በእርሱ ላይ ከጌታው ተአምር ለምን አልተወረደለትም?» ይላሉ:: አንተ አስፈራሪ ብቻ ነህ፤ ለሕዝብም ሁሉ መሪ አለላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 8, '8. አላህ ሴት ሁሉ የምታረግዘውን ጽንስ ሁሉ ጠንቅቆ ያውቃል:: ማሕጸኖች የሚያጎድሉትንም ሆነ የሚጨምሩትን ያውቃል:: ነገሩ ሁሉ እርሱ ዘንድ በልክ የተወሰነ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 9, '9. ሩቁንና ቅርቡን አዋቂ የሆነ ታላቅና የላቀ ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 10, '10. ከናንተ ውስጥ ቃሉን ዝቅ ያደረገ፤ በእርሱ የጮኸም፤ እርሱ በሌሊት ተደባቂም በቀን ተገልፆ ሂያጅም የሆነ ሁሉ (እርሱ አላህ ዘንድ) እኩል ነው (አላህ ያውቀዋል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 11, '11. ለእርሱ ለሰው በስተፊቱም ከኋላዉም በአላህ ትዕዛዝ ከክፉ የሚጠብቁት ተተካኪዎች መላዕክት አሉት:: አላህ በሕዝቦች ዘንድ ያለውን (ጸጋ) በነፍሶቻቸው ያለውን (ሁኔታ) እስከሚለውጡ ድረስ አይለውጥም:: አላህም በሰዎች ላይ ክፉን በሻ ጊዜ ለእርሱ መመለስ የለዉም:: ለእነርሱም ከእርሱ ሌላ ምንም ተከላካይ የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 12, '12. እርሱ ያ የምትፈሩና የምትከጅሉም ስትሆኑ ብልጭታን የሚያሳያችሁ ከባዶች ደመናዎችንም የሚያስገኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 13, '13. ነጎድጓድም አላህን በማመስገን ያጠራል:: መላዕክትም እርሱን ከመፍራት ያጠሩታል፤ መብረቆችም ይልካል። እነርሱም (ከሓዲያን) በአላህ የሚከራከሩ ሲሆኑ በእርሷ የሚሻውን ሰው ይመታል:: እርሱም ሀይለ ብርቱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 14, '14. ለእርሱ(አላህ) የእውነት ጥሪ አለው:: እነዚያ ከእርሱ ሌላ የሚገዟቸው ጣዖታት ምሳሌው ወደ አፉ ይደርስ ዘንድ ወደ ውሃ መዳፎቹን በሩቅ ሆኖ እንደሚዘረጋና እንደማይደርስባት ሰው እንጂ ለእነርሱ በምንም አይመልሱላቸዉም:: እርሱም ወደ አፉ ደራሽ አይደለም:: የከሓዲያን ጥሪ በከንቱ ልፋት እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 15, '15. በሰማያትና በምድር ያሉት ሁሉ በዉድም ሆነ በግድ ለአላህ ይሰግዳሉ:: ጥላዎቻቸዉም በጧቶችና በማታዎች ይሰግዳሉ:: (1)', '(1) እዚህ አንድ ሱጁድ ይደረጋል። የቁርኣን ንባብ ሱጁድ (ሱጁዱትላዋህ) ይባላል። በቁርኣን ውስጥ 15 ቦታዎች ይገኛል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 16, '16. (መልዕክተኛችን ሙሐመድ ሆይ!) «የሰማያትና የምድር ጌታ ማን ነው?» በላቸው:: «አላህ ነው።» በልም። «ለነፍሶቻቸው ጥቅምንም ጉዳትን የማይችሉን ረዳቶች ከእርሱ ሌላ ያዛችሁን?» በላቸው። «እውርና የሚያይ ይስተካከላሉን? ወይስ ጨለማዎችና ብርሃን ይስተካከላሉን? ወይስ ለአላህ እንደ እርሱ አፈጣጠር የፈጠሩን ተጋሪዎች አረጉለትና ፍጥረቱ በእነርሱ ላይ ተመሳሰለባቸውን?» በልም። «አላህ ሁለመናውን ፈጣሪ ነው:: እርሱም ብቸኛውና ሁሉን አሸናፊው ነው።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 17, '17. ከሰማይ ውሃን አወረደ:: ሸለቆዎቹም በየመጠናቸው ፈሰሱ:: ጎርፉም አስፋሪውን የውሃ አረፋ ተሸከመ:: ለጌጥ ወይም ለዕቃ ፍላጎት በእርሱ ላይ እሳት የሚያነዱበትም ማዕድን ብጤው የሆነ ኮረፋት አለው:: ልክ እንደዚሁ አላህ ለእውነትና ለውሸት ምሳሌን ያደርጋል:: የውሃ አረፋዉም ግብስብስ ሆኖ ይጠፋል:: ለሰዎች የሚጠቅመውማ በምድር ላይ ይቆያል:: ልክ እንደዚሁ አላህ ምሳሌዎችን ይገልጻል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 18, '18. ለእነዚያ ለጌታቸው ለታዘዙት ሰዎች መልካም ነገር ገነት አለላቸው:: እነዚያም ለእርሱ ያልታዘዙት ለእነርሱ በምድር ያለው ሁሉ ከእርሱም ጋር ብጤው ቢኖራቸው ኖሮ በእርሱ በተበዡበት ነበር:: እነዚያ ለእነርሱ ክፉ ምርመራ አለባቸው:: መኖሪያቸዉም ገሀነም ናት:: ፍራሻቸዉም ገሀነም ከፋች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 19, '19. (መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህ ወደ አንተ የተወረደው ሁሉ እውነት መሆኑን የሚያውቅ ሰው ልክ እንደዚያ እርሱ እውር እንደ ሆነው ሰው ነውን? የሚገሠጹት የአእምሮ ባለቤቶች ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 20, '20. እነዚያ የአላህን ቃል ኪዳን የሚሞሉ የጠበቀውንም ኪዳን የማያፈርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 21, '21. እነዚያም አላህ እንዲቀጠል በእርሱ ያዘዘውን ነገር የሚቀጥሉ፤ ጌታቸውንም የሚያከብሩ፤ መጥፎንም ቁጥጥር የሚፈሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 22, '22. እነዚያም የጌታቸውን ውዴታ ለመፈለግ የታገሱ ሶላትንም አዘውትረው የሰገዱ ሰዎች እኛ ከሰጠናቸው ሲሳይም በምስጢርም ሆነ በግልጽ የመጸወቱ ክፉውንም በበጎ የሚገፈትሩ ናቸው:: እነዚያ ለእነርሱ መጨረሻይቱ ምስጉን አገር አለችላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 23, '23. እርሷም የመኖሪያ ገነቶች ናት:: ይገቡባታል:: ከአባቶቻቸዉም ከሚስቶቻቸዉም ከዝርያቸዉም መልካም የሠራ ሰው ሁሉ ይገባባታል። መላዕክትም በእነርሱ ላይ ከየደጃፉ ሁሉ ይገባሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 24, '24. «ሰላም ለእናንተ ይሁን:: ይህ ምንዳ በመታገሳችሁ የተሰጣችሁ ነው:: የመጨረሻይቱም ሀገር ምን ታምር!» ይሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 25, '25. እነዚያ የአላህን ቃል ኪዳን ከጠበቀ በኋላ የሚያፈርሱ፤ አላህም እንዲቀጠል በእርሱ ያዘዘውን ነገር የሚቆርጡ፤ በምድርም ላይ የሚያበላሹ እነዚያ ለእነርሱ እርግማን አለባቸው:: ለእነርሱም መጥፎ ሀገር ገሀነም አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 26, '26. አላህ ለሚሻው ሁሉ ሲሳይን ያሰፋል:: ለሚሻውም ያጠባል:: ከሓዲያን በቅርቢቱም ሕይወት ተደሰቱ:: የቅርቢቱም ሕይወት ከመጨረሻይቱ አንጻር ትንሽ መጠቀሚያ እንጂ ምንም አይደለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 27, '27. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም በአላህ የካዱት ሰዎች «በእርሱ ላይ ከጌታው ተዓምር ለምን አልተወረደልትም?» ይላሉ:: «አላህ የሚሻውን ሰው ያጠማል:: የተመለሰንም ሰው ወደ እርሱ ይመራል።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 28, '28. እነርሱም እነዚያ በአላህ ያመኑ ልቦቻቸዉም አላህን በማውሳት የሚረኩ ናቸው:: አስተውሉ:: አላህን በማውሳት ልቦች ይረካሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 29, '29. እነዚያ በአላህ ያመኑና መልካም ስራዎችን የሠሩት ለእነርሱ ደግ ኑሮና መልካም መመለሻ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁ ከበፊትዋ ብዙ ሕዝቦች በእርግጥ ያለፉ ወደ ሆነችው ሕዝብ እነርሱ በአር-ረህማን የሚክዱ ሲሆኑ ያንን ወደ አንተ ያወረድነውን ቁርኣን በእነርሱ ላይ ታነብላቸው ዘንድ ላክንህ:: «እርሱ አር-ረህማን ጌታዬ ነው:: ከእርሱ ሌላ ትክክለኛ አምላክ የለም:: በእርሱ ላይ ተመካሁ። መመለሻዬም ወደ እርሱ ብቻ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 31, '31. ቁርኣንም በእርሱ ተራራዎች የሚነዱበት፤ ወይም በእርሱ ምድር የሚቆራረጥበት፤ ወይም በእርሱ ሙታን እንዲናገሩ የሚደረጉበት ቢሆን ኖሮ (ይሀው ቁርአን በሆነ ነበር።) በእውነቱ ነገሩ ሁሉ የአላህ ነው:: እነዚያ በአላህ ያመኑት ሰዎች እነሆ አላህ በሻ ኖሮ ሰዎችን በመላ በእርግጥ ወደ ቀናው መንገድ ይመራቸው እንደ ነበረ አያውቁምን? እነዚያን የካዱት በሥራቸው ምክንያት አጥፊ አደጋ የምታገኛቸው ከመሆን ወይም የአላህ ቀጠሮ እስኪ መጣ በሀገራቸው አቅራቢያ አንተ የምትሰፍርባቸው ከመሆን አይወገዱም:: አላህ ቀጠሮውን አያፈርስምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 32, '32. ካንተ በፊት የነበሩትም መልዕክተኞች በእርግጥ ተላግጦባቸው ነበር:: እናም ለእነዚያም ለካዱት ጊዜን ሰጠኋቸው:: ከዚያም በቅጣት ያዝኳቸው:: ቅጣቴ እንዴት ነበር (ምን ያህል የከፋ ነበር።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 33, '33. (መልዕክተኛችን ሙሐመድ ሆይ!) ነፍስ ሁሉ በሰራችው ሥራ ላይ ተጠባባቂ የሆነው አላህም እንደዚህ እንዳልሆነው ጣዖት ብጤ ነውን? ለአላህ ተጋሪዎችን አደረጉ። «ጥሯቸው:: አላህን በምድር ውስጥ የማያውቀው ነገር ኖሮ ትነግሩታለችሁን? ወይስ ከቃል በቀጥታ ፍቺ በሌለው ከንቱ ቃል ተጋሪዎቹ በማለት ትጠሯቸዋላችሁን?» በላቸው። በእውነቱ ለእነዚያ ለካዱት ተንኮላቸው ተሸለመላቸው። ከእውነቱ መንገድም ታገዱ። አላህ ያጠመመውንም ምንም አቅኚ የለዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 34, '34. ለእነርሱ በቅርቢቱ ሕይወት ቅጣት አለባቸው:: የመጨረሻይቱም ዓለም ቅጣት በጣም የበረታ ነው:: ለእነርሱ ከአላህ ቅጣት ምንም ጠባቂ የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 35, '35. ያች ጥንቁቆች የተሰጧት ገነት ምጣኔዋ (ምሳሌዋ) እንደሚነገራችሁ ነው:: ከሥርዋ ወንዞች ይፈሳሉ:: ምግቧ ሁል ጊዜም የማያቋረጥ ነው:: ጥላዋም እንደዚሁ። ይህች ገነት የእነዚያ የተጠነቀቁት መጨረሻ ናት:: የከሓዲያን መጨረሻ ግን እሳት ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 36, '36. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም መጽሐፉን የሰጠናቸውን ወደ አንተ በተወረደው ይደሰታሉ:: ከአህዛብም ከፊሉን የሚክዱ ሰዎች አሉ። «እኔ የታዘዝኩት አላህን ብቻ እንድገዛና በእርሱም እንዳላጋራ ነው። ወደ እርሱ እጠራለሁ:: መመለሻዬም ወደ እርሱ ብቻ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 37, '37. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁ በዐረብኛ የተነገረ ፍትህ ሲሆን አወረድነው:: እውቀቱ ከመጣልህም በኋላ ዝንባሌዎቻቸውን ብትከተል ከአላህ ቅጣት ወዳጅም ሆነ ጠባቂ ምንም የለህም::37. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁ በዐረብኛ የተነገረ ፍትህ ሲሆን አወረድነው:: እውቀቱ ከመጣልህም በኋላ ዝንባሌዎቻቸውን ብትከተል ከአላህ ቅጣት ወዳጅም ሆነ ጠባቂ ምንም የለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 38, '38. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊት ብዙ መልዕክተኞችን በእርግጥ ልከናል:: ለእነርሱም ሚስቶችንና ልጆችን አድርገናል:: ማንኛዉም መልዕክተኛ በአላህ ፈቃድ እንጂ ተዓምር ሊያመጣ አይገባዉም:: ለየጊዜው ሁሉ ጽሑፍ አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 39, '39. አላህ የሚፈልገውን ያብሳል:: የሚሻውን ያጸድቃል:: የመጽሐፉ ዋና መሠረትም እርሱ ዘንድ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) የዚያን ያስፈራራናቸውን ቅጣት ከፊሉን በሕይወት እያለህ ብናሳይህ መልካም ነው:: ወይም ሳናሳይህ ብንገድልህ ወቀሳ የለብህም:: ባንተ ላይ ያለብህ መልዕክትህን ማድረስ ብቻ ነው:: ምርመራው ግን በእኛ ላይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 41, '41. እኛ ምድርን ከጫፎችዋ የምናጎድላት ሆነን የምናመጣባት መሆናችንን አላወቁምን? አላህም ይፈርዳል:: ለፍርዱም በይግባኝ ገልባጭ የለዉም:: እርሱም ምርመራው ፈጣን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 42, '42. እነዚያም ከእነርሱ በፊት የነበሩት ሰዎች መከሩ (አሴሩ):: አዘንግቶም የመያዙ ዘዴ በሙሉ የአላህ ብቻ ነው:: አላህ ነፍስ ሁሉ የምትሰራውን ያውቃል:: ከሓዲያን የመጨረሻይቱ አገር ለማን እንደምትሆን ወደፊት ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (13, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያም በአላህ የካዱ ሰዎች መልእክተኛ አይደለህም።» ይላሉ። «በእኔና በእናንተ መካከል መስካሪ በአላህና እርሱ ዘንድ የመጽሐፉ እውቀት ባለው ሰው በቃ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 1, '1. አሊፍ፤ ላም፤ ራ፤ (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ቁርኣን ሰዎችን በጌታቸው ፈቃድ ከጨለማዎች ወደ ብርሃን አሸናፊ፤ ምስጉን ወደ ሆነው ጌታ መንገድ ታወጣ ዘንድ ወደ አንተ ያወረድነው መጽሐፍ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 2, '2. ወደ እዚያ በሰማያትና በምድር ያለው ሁሉ የእርሱ ብቻ ወደ ሆነው ጌታ ወደ አላህ መንገድ (ታወጣ ዘንድ ):: ለከሓዲያን ሁሉ ከብርቱ ቅጣት ወዮላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 3, '3. እነዚያ የቅርቢቱን ህይወት ከመጨረሻይቱ ህይወት ይበልጥ የሚወዱና ከአላህ መንገድ ሰዎችን የሚያግዱ፤ መጥመሟንም (ደካማ ጎኗን) የሚፈልጓት ናቸው:: እነዚያ በሩቅ ስህተት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 4, '4. ከመልዕክተኞች ማንኛውንም ለእነርሱ ያብራራላቸው ዘንድ በወገኖቹ ቋንቋ እንጂ በሌላ አልላክንም:: አላህ የሚፈልገውንም ያጠምማል:: የሚፈልገውንም ያቀናል:: እርሱ ሁሉን አሸናፊውና ጥበበኛው ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 5, '5. ሙሳን ወገኖችህን ከጨለማዎች ወደ ብርሃን አውጣ:: የአላህንም ቀናት አስገንዝባቸው በማለት በተዓምራታችን አጠናክረን በእርግጥ ላክነው:: በዚህ ውስጥ በብዙ ታጋሽና በብዙ አመስጋኝ ለሆኑት ሁሉ በእርግጥ ብዙ ተዓምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳም ለህዝቦቹ «ከፈርዖን ቤተሰቦች መጥፎን ቅጣት የሚያቀምሷችሁ፤ ወንዶች ልጆቻችሁን የሚያርዱና ሴቶቻችሁንም የሚተው ሲሆን በአዳናችሁ ጊዜ በእናንተ ላይ የዋለላችሁን የአላህን ጸጋ አስታውሱ:: በዚሃችሁ ከጌታችሁ የሆነ ታላቅ ፈተና አለበት።» ባለ ጊዜ የሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 7, '7. ጌታችሁም፦ «ብታመሰግኑ በእርግጥ እጨምርላችኋለሁ:: ብትክዱም እቀጣችኋለሁ:: ቅጣቴ በእርግጥ ብርቱ ነው።» በማለት ባስታወቀ ጊዜ (የሆነዉን አስታውሱ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 8, '8. ሙሳ፡- «እናንተም በምድር ያለዉም ሁሉ በመላ ብትክዱ አላህ ተብቃቂና ምስጉን ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 9, '9. (ሙስሊሞች ሆይ!) የእነዚያ ከእናንተ በፊት የነበሩት የኑህ ህዝቦች፤ የዓድ፣ የሠሙድም የእነዚያም ከእነርሱ በኋላ የነበሩት ከአላህ በስተቀር ሌላ የማያውቃቸው ህዝቦች ወሬ (ታሪክ) አልመጣላችሁምን? መልዕክተኞቻቸው በማስረጃዎች መጡላቸውና እጆቻቸውን በቁጭት ሊነክሱ ወደ አፎቻቸው መለሱ: «በተላካችሁበት ነገር ካድን እኛም ወደ እርሱ ከምትጠሩን ነገር አወላዋይ በሆነ ጥርጣሬ ውስጥ ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 10, '10. መልዕክተኞቻቸው «ከኃጢአቶቻችሁ እንዲሚራችሁ ወደ ተወሰነ ጊዜም ያለ ቅጣት እንዲያቆያችሁ የሚጠራችሁ ሲሆን ሰማያትንና ምድርን ፈጣሪ በሆነው አላህ በመኖሩ ጥርጣሬ አለን?» አሏቸው:: ህዝቦቹም፡ «እናንተ ብጤያችን ሰው እንጂ (ሌላ ፍጡር) አይደላችሁም:: አባቶቻችን ይገዙት ከነበሩት ልትከለክሉን ትሻላችሁን? ግልጽን አስረጅ ካመጣችሁት ሌላ እስቲ አምጡልን።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 11, '11. መልዕክተኞቻቸውም ለእነርሱ አሉ: «እኛ ብጤያችሁ ሰዎች እንጂ ሌላ አይደለንም:: ግን አላህ ከባሮቹ መካከል በሚሻው ሰው ላይ ይለግሳል:: እኛም በአላህ ፈቃድ እንጂ ማስረጃን ልናመጣላችሁ አይገባንም:: በአላህ ላይ ብቻ ምእመናን ይጠጉ (ይመኩ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 12, '12. «መንገዳችንን በእርግጥ የመራን ሲሆን በአላህ ላይ የማንመካበት ምን አለን? በማሰቃየታችሁም ላይ እንታገሳለን:: በአላህ ላይ ብቻ ተመኪዎች ሁሉ ይመኩ።» (አሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 13, '13. እነዚያ በአላህ የካዱት ለመልእክተኞቻቸው: «ከምድራችን በእርግጥ እናወጣችኋለን ወይም ወደ ሃይማኖታችን ትመለሳላችሁ።» አሉ:: ወደ እነርሱም ጌታቸው እንዲህ ሲል ላከ: «(ከሓዲያን) በዳዮችን እናጠፋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 14, '14. «ከእነርሱ በኋላም በምድሪቱ በእርግጥ እናስቀምጣችኋለን:: ይህ በፊቴ መቆሙን ለሚፈራና ዛቻዬን ለሚፈራ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 15, '15. እርዳታንም ከአላህ ፈለጉ፤ ተረዱም። ጨካኝ ሞገደኛ የሆነም ሁሉ አፈረ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 16, '16. ከስተፊቱ ገሀነም አለበት:: እዥ ከሆነም ውሃ ይጋታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 17, '17. ይጎነጨዋል፤ ሊውጠዉም አይቀርብም:: ሞትም ከየስፍራው ሁሉ ይመጣበታል:: እርሱም የሚሞት አይደለም:: ከበስተፊቱም ከባድ ቅጣት አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 18, '18. የእነዚያ በጌታቸው የካዱት ሰዎች መልካም ሥራዎቻቸው ምሳሌ በነፋሻ ቀን ነፋስ እንደ በረታችበት አመድ ነው:: በሠሩት ሥራ በምንም ላይ ሊጠቀሙ አይችሉም። ይህ እርሱ ሩቅ ጥፋት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 19, '19. (የሰው ልጅ ሆይ!) አላህ ሰማያትንና ምድርን በእውነት የፈጠረ መሆኑን አታይምን? ቢሻ ያጠፋችኋል:: አዲስ ፍጡርንም ያመጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 20, '20. ይህም እናንተን አጥፍቶ አዲስ ፍጥረትን ማምጣት በአላህ ላይ አስቸጋሪ ጉዳይ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 21, '21. የተሰበሰቡ ሆነው ለአላህ ይገለጻሉ። ሐሳበ ደካማዎቹም ተከታዮች ለእነዚያ ለኮሩት «እኛ ለእናንተ ተከታዮች ነበርን እናንተ ከአላህ ቅጣት ከእኛ ላይ አንዳችን ነገር ተከላካዮች ናችሁን?» ይሏቸዋል። አስከታዮቹም። «አላህ ባቀናን ኖሮ በመራናችሁ ነበር።» ይሏቸዋል:: «ብንበሳጭ ወይም ብንታገሥም በእኛ ላይ ሁሉም እኩል ነው:: ለእኛ ምንም መጠጊያ የለንም።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 22, '22. ነገሩም በተፈጸመ ጊዜ ሰይጣን ይላቸዋል: «አላህ እውነተኛውን ቃል ኪዳን ገባላችሁ እኔም ቃል ኪዳንም ገባሁላችሁ:: አፈረስኩባችሁም:: ለእኔም በእናንተ ላይ ምንም ሥልጣን አልነበረኝም:: ግና ጠራኋችሁና ታዘዛችሁኝ:: ስለዚህ አትውቀሱኝ ነፍሶቻችሁንም ውቀሱ:: እኔ የምረዳችሁ አይደለሁም እናንተም የምትረዱኝ አይደላችሁም። እኔ ከአሁን በፊት ለአላህ ተጋሪ በአደረጋችሁት ነገር ሁሉ ካድኩ በዳዮቹ ሁሉ አሳማሚ ቅጣት አለባቸው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 23, '23. እነዚያ በትክክል ያመኑና መልካም ሥራዎችን የሠሩ ሁሉ ከስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘውታሪዎች ሲሆኑ በጌታቸው ፈቃድ እንዲገቡ ይደረጋሉ:: በውስጣቸው መከባበሪያቸው ሰላምታቸው «ሰላም ለእናንተ ይሁን መባባል» ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ መልካምን ቃል ሥሯ በምድር ውስጥ የተደላደለች ቅርንጫፏም ወደ ሰማይ የረዘመች እንደሆነች መልካም ዛፍ አድርጎ ምሳሌን እንዴት እንደገለጸ አላየህምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 25, '25. ፍሬዋን (ምግቧን) በጌታዋ ፈቃድ በየጊዜው ትሰጣለች:: አላህም ለሰዎች ይገሰጹ ዘንድ ምሳሌዎችን ይገልጻል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 26, '26. የመጥፎ ቃል ምሳሌ ከምድር በላይ የተገረሰሰች ለእርሷ ምንም መደላደል የሌላት እንደ ሆነች መጥፎ ዛፍ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 27, '27. አላህ እነዚያን በትክክል ያመኑትን በቅርቢቱም ህይወት ሆነ በመጨረሻይቱም በመቃብር በተረጋገጠው ቃል (በሸሀዳ) ላይ ያደርጋቸዋል (ያጸናቸዋል):: ከሓዲያንንም አላህ ያሳስታቸዋል፤ አላህም የሚሻውን ይሰራልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 28, '28. ወደ እነዚያ የአላህን ጸጋ በክህደት ወደ ለወጡትና ህዝቦቻቸውን በጥፋት ሀገር ወዳሰፈሩት (ወደ ቁረይሾች) አላየህምን? (አልተመለከትክምን?)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 29, '29. ሀገሪቱም የሚገቡባት ስትሆን ገሀነም ናት:: መርጊያነቷ ምንኛ ትከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ለአላህ ከመንገዱ ያሳስቱ ዘንድ ባላንጣዎችን አደረጉለት:: (ሙሐመድ ሆይ!) «ጥቂትን ተጠቀሙ መመለሻችሁም ወደ እሳት ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 31, '31. መልዕክተኛችን ሙሐመድ ሆይ! ለእነዚያ ላመኑት ባሮቼ ሽያጭና ወዳጅነት የሌለበት ቀን ከመምጣቱ በፊት ሶላትን በደንቡ እንዲሰግዱ፤ ከሰጠናቸውም ሲሳይ በሚስጢርም ሆነ በግልጽ እንዲለግሱም ንገራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 32, '32. አላህ ያ ሰማያትንና ምድርን የፈጠረ ከሰማይ ዳመናም ውሃን ያወረደ፤ በእርሱም ከፍሬዎች ሁሉ ለእናንተ ሲሳይን ያወጣላችሁ፤ መርከቦችንም በፈቃዱ በባህር ላይ ይንሳፈፉ ዘንድ ለእናንተ ያገራ፤ ወንዞችንም ለናንተ ያገራ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 33, '33. ጸሓይንና ጨረቃንም ዘወትር ሒያጆች ሲሆኑ ለእናንተ የገራ፤ ሌሊትንና ቀንንም ለእናንተ የገራላችሁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 34, '34. ከለመናችሁትም ሁሉ የሰጣችሁ ነው:: የአላህንም ጸጋ ብትቆጥሩ እንኳ አትዘልቁትም:: ሰው በጣም በደለኛና ከሓዲ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 35, '35. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢብራሂም ባለ ጊዜ አስታውስ: «ጌታዬ ሆይ! ይህንን ሀገር መካን ጸጥተኛ አድርገው:: እኔንና ልጆቼንም ጣኦታትን ከመገዛት አርቀን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 36, '36. «ጌታዬ ሆይ! እነርሱ (ጣኦታቱ) ከሰዎች ብዙዎችን አሳስተዋልና:: የተከተለኝም ሰው እርሱ ከእኔ ነው:: ትዕዛዜን የጣሰ ሰው ግን አንተ መሓሪና አዛኝ ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 37, '37. «ጌታችን ሆይ! እኔ አዝመራ በሌለው ሸለቆ ውስጥ በተከበረው ቤትህ በካዕባ አጠገብ ከዘሮቼ አስቀመጥኩ:: ጌታችን ሆይ! ሶላትን ደንቡን ጠብቀው ይሰግዱ ዘንድ አስቀመጥኳቸው:: ከሰዎችም ልቦችን ወደ እነርሱ የሚናፍቁ አድርግ:: ያመሰግኑህም ዘንድ ከፍሬዎች ስጣቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 38, '38. «ጌታችን ሆይ! አንተ የምንደብቀውንም የምንገልጸውንም ሁሉ በእርግጥ ታውቃለህ:: በአላህ ላይ በምድርም በሰማይም ምንም ነገር አይደበቅም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 39, '39. «ለእዚያ ከሽምግልና በኋላ ኢስማኢልንና ኢስሐቅን ለሰጠኝ አላህ ምስጋና ሁሉ ይገባው። ጌታዬ ልመናን ሰሚ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 40, '40. «ጌታዬ ሆይ! ሶላትን አዘውትሬ የምሰግድ አድርገኝ:: ከዘሮቼም አድርግ ጌታችን ሆይ! ጸሎቴንም ተቀበለኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 41, '41. «ጌታችን ሆይ! ለእኔም ለወላጆቼም ለአማኞችም ሁሉ ምርመራ በሚደረግበት ቀን ማረን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህንም በደለኞች ከሚሠሩት ግፍ ዘንጊ አድርገህ አታስብ። የሚያቆያቸው ዓይኖች እስከሚፈጡበት ቀን ድረስ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 43, '43. ወደ ጠሪው መልአክ ቸኳዮች ራሶቻቸውንም አንጋጣጮች ሆነው ዓይኖቻቸው ይፈጣሉ። ዓይኖቻቸው ወደ እነርሱ አይመለሱም:: ልቦቻቸው ባዶዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰዎችንም ቅጣቱ የሚመጣባቸውን ቀን አስፈራራቸው:: እነዚያም የበደሉትማ «ጌታችን ሆይ! እስከ ቅርብ ጊዜ ድረስ አቆየን:: ጥሪህንም እንቀበላለንና መልዕክተኞቹንም እንከተላለንና።» ይላሉ። ይባላሉም: «ከአሁን በፊት በምድረ ዓለም ለእናንተ ምንም መወገድ የላችሁም በማለት የማላችሁ አልነበራችሁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 45, '45. «በእነዚያም ነፍሶቻቸውን በበደሉት ሰዎች መኖሪያ ውስጥ ተቀመጣችሁ:: በእነርሱም እንዴት እንደሠራንባቸው ለእናንተም ተገለጸላችሁ፤ ለእናንተ ምሳሌዎችንም ገለጽንላችሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 46, '46. በነብዩ ላይ ሴራቸውንም በእርግጥ አሴሩ:: ሴራቸዉም ቅጣቱ አላህ ዘንድ ነው:: ሴራቸዉም ኮረብታዎች በእርሱ የሚወገዱበት አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህንም ለመልዕክተኞቹ የገባላቸውን ቃል ኪዳኑን አፍራሽ አድርገህ አታስብ:: አላህ ሁሉን አሸናፊና የመበቀል ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 48, '48. ምድር በሌላ ምድር የምትለወጥበትን ሰማያትም እንደዚሁ በሌላ ሰማያት የሚለወጥበትን እና አንድ ብቸኛና አሸናፊ ለሆነው አላህ ፍጡራን ሁሉ የሚገለጹበትን ቀን የሚሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) አመጸኞችንም በዚያ ቀን በሰንሰለቶች ተቆራኝተው ታያቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 50, '50. ቀሚሶቻቸው ከካትራሜ የተሰሩ ናቸው:: ፊቶቻቸውንም እሳት ትሸፍናቸዋለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 51, '51. አላህ ይህንን ያደረገው ነፍስ ሁሉ የሠራችውን ትመነዳ ዘንድ ነው:: አላህ ምርመራው ፈጣን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (14, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ቁርኣን ለሰዎች ገሳጭና መድረስ ያለበት ነው:: ሊመከሩበት በእርሱም ሊስፈራሩበት፤ እርሱም አንድ አምላክ ብቻ መሆኑን ሊያውቁበት፤ የአእምሮ ባለቤቶችም ሊገሰጹበት የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 1, '1. አሊፍ፤ ላም፤ ራ፤ እነዚህ አናቅጽ ከመጽሐፍ አናቅጽና ገላጭ ከሆነው ቁርኣን ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 2, '2.እነዚያ በአላህ የካዱት ሰዎች በትንሳኤ ቀን ሙስሊሞች በሆኑ ኖሮ ብለው በብዛት ይመኛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱን ተዋቸው:: ይብሉ ይጠቀሙም:: ተስፋም ያዘናጋቸው:: በእርግጥም መጥፎ ፍጻሜያቸውን ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 4, '4. (መልዕክተኛችን ሙሐመድ ሆይ!) ማንኛይቱንም ከተማ ለእርሷ የተወሰነ መጽሐፍ ጊዜያት ያላት ሆና እንጂ አላጠፋንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 5, '5. ማንኛይቱም ሕዝብ የመጥፊያ ጊዜዋን በምንም ዘዴ አትቀድምም:: ከእርሱም በማንም ሀይል አትዘገይምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 6, '6. እነዚያ የመካ ከሓዲያን አሉ: «አንተ ያ በእርሱ ላይ ቁርኣን የተወረደለት ሆይ! አንተ በእርግጥ እብድ ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 7, '7. «ከእውነተኞቹ እንደ ሆንክ መስካሪ መላዕክት ለምን አታመጣልንም?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 8, '8. መላእክትን ደግሞ በእውነት በቅጣት እንጂ አናወርድም:: ያን ጊዜም የሚቆዩ ጊዜ የሚሰጣቸው አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 9, '9. እኛ ቁርኣንን እኛው አወረድነው:: እኛም ጠባቂዎቹ ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተም በፊት በነበሩት በመጀመሪያዎቹ ሕዝቦች ውስጥ መልክተኞችን በእርግጥ ልከናል:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 11, '11. ማንኛዉም መልዕክተኛ በእርሱ የሚያላግጡበት ሆነው እንጂ አይመጣላቸዉም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 12, '12. ልክ እንደዚሁ ማስተባበልን በአመጸኞች ልቦች ውስጥ እናስገባዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 13, '13. በእርሱ አያምኑበትም፤ የቀድሞዎቹም ድርጊት በእርግጥ አልፋለች (እንደጠፉ ይጠፋሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 14, '14. በእነርሱም ላይ ከሰማይ ደጃፍን በከፈትንላቸውና በእርሱ ሲወጡ ቢውሉም', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 15, '15. «የተዘጉ ዓይኖቻችን ተጭበርብረው ነው:: እንዲያዉም እኛ የተደገመብን ሰዎች ነን።» ባሉ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 16, '16. በሰማይም ላይ ከዋክብቶችን በእርግጥ አድርገናል (ፈጥረናል):: ለተመልካቾችም በከዋክብት አጊጠናታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 17, '17. ከተባረረ ሰይጣንም ሁሉ ጠብቀናታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 18, '18. ግን ወሬ መስማትን የሚሰርቅ ወዲያውኑ አብሪ ችቦ ይከተለዋል:: (ያቃጥለዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 19, '19. ምድርንም ዘረጋናት:: በውስጧም ኮረብታዎችን ጣልንባት:: በውስጧም የተለካን በቃይ ሁሉ አበቀልንባት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 20, '20.(ሰዎች ሆይ!) በእርሷ ውስጥ ለእናንተ ልዩ ልዩ መኖሪያዎችንና ለእርሱ መጋቢዎቹ ያልሆናችሁትንም እንስሳትን አደረግንላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 21, '21. መጋዘኖቹም መክፈቻቸው እኛው ዘንድ ያልሆነ ምንም ነገር የለም:: በተወሰነም ልክ እንጂ አናወርደዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 22, '22. ንፋስን ደመናን ተሸካሚዎች አድርገን ላክን:: ከሰማይም ከደመና ዝናብን አወረድን:: እርሱንም አጠጣናችሁ:: እናንተ ለእርሱ አድላቢዎች (አከማቾች) አይደላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 23, '23. እኛ ሕያው የምናደርግና የምንገድል እኛው ብቻ ነን:: እኛው ፍጡርን ሁሉ የምንወርስ ቀሪ ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 24, '24. ከናንተም ተቀዳሚዎቹን በእርግጥ አውቀናል:: ወደ ኋላ ቀሪዎቹንም በእርግጥ አውቀናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!)ጌታህ ይሰበስባቸዋል:: እርሱ ጥበበኛና ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 26, '26. ሰውንም ከሚቅጨለጨል ሸክላ ከሚገማ ጥቁር ጭቃ በእርግጥ ፈጠርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 27, '27. ጃንን ከሰው በፊት ከእሳት ነበልባል ፈጠርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም ለመላዕክት ባለ ጊዜ (የሆነውን አስታውስ): «እኔ ሰውን ከሚቅጨለጨል ሸክላ ከሚገማ ጭቃ እፈጥራለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 29, '29. «ፍጥረቱን ባስተካከልኩትና በውስጡ ከመንፈሴ በነፋሁበትም ጊዜ ለእርሱ ሰጋጆች ሆናችሁ ውደቁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 30, '30. መላዓክትም ሁሉም ተሰብስበው ሰገዱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 31, '31. ዲያብሎስ ብቻ ሲቀር:: እርሱማ ከሰጋጆቹ ጋር ከመሆን እንቢ አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 32, '32. አላህም፡ «ዲያብሎስ ሆይ! ከሰጋጆቹ ጋር የማትሆን ላንተ ምን ምክንያት አለህ?» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 33, '33. «ከሚቅጨለጨል ሸክላ ከግም ጭቃ ለፈጠርከው ሰው ልሰግድ አይገባኝም።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 34, '34. አላህም አለው: «ከእርሷም ውጣ አንተ የተባረርክ እርጉም ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 35, '35. «ባንተ ላይም እስከ ፍርዱ ቀን ድረስ እርግማን አለብህ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 36, '36. «ጌታዬ ሆይ! እንግዲያውስ እስከሚቀሰቀሱበት ቀን ድረስ አቆየኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 37, '37. አላህም አለ፡- «አንተ ከሚቆዩት ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 38, '38. «እስከታወቀው ቀን ድረስ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 39, '39. ዲያብሎስም አለ፡- «ጌታዬ ሆይ! እኔን በማጥመምህ ይሁንብኝ ለእነርሱ በምድር ላይ ኃጢአትን እሸልምላቸዋለሁ። ሁላቸውንም አጠማቸዋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 40, '40. «ከእነርሱ ፍጹሞቹ ባሮችህ ብቻ ሲቀሩ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 41, '41. አላህም አለ፡- «ይህ በእኔ ላይ መጠበቁ የተገባ ቀጥተኛ መንገድ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 42, '42. «እነሆ ባሮቼ! በእነርሱ ላይ አንተ ስልጣን የለህም። ከጠማሞች የተከተለህ ሰው ብቻ ሲቀር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 43, '43. «ገሀነምም ለእርሱና ለተከተሉት ለሁሉም በእርግጥ ቀጠሯቸው ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 44, '44. «ለእርሷ ሰባት በሮች (ደጃፎች ) አሏት። ለየበሮቹም ሁሉ ከሰይጣናት ቡድኖች የተከፋፈለ ድርሻ አለ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 45, '45. እነዚያ ከኃጢአት የተጠነቀቁት በአትክልቶችና በምንጮች ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 46, '46. «ጸጥተኞች ሆናችሁ በሰላም ግቧት።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 47, '47. በአልጋዎችም ላይ ፊት ለፊት የሚተያዩ ወንድማማቾች ሆነው በልቦቻቸው ውስጥ ያለውን ቂም ሁሉ እናስወግዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 48, '48. በእርሷም ውስጥ ምንም ድካም አይነካቸዉም፤ እነርሱም ከእርሷ ለምንጊዜም የሚወጡ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) መሃሪና አዛኝ እኔው ብቻ መሆኔን ለባሮቼ ንገር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 50, '50. ቅጣቴም እርሱ አሳማሚ ቅጣት መሆኑንም ንገራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) ከኢብራሂም እንግዶችም ወሬ ንገራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 52, '52. በእርሱ ላይ በገቡና ሰላም ባሉት ጊዜ (የሆነውን አስታውስ):: እርሱም፡- «እኛ ከናንተ ፈሪዎች ነን።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 53, '53. «አትፍራ እኛ አዋቂ በሆነ ወንድ ልጅ እናበስርሃለን።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 54, '54. «እርጅና የደረሰብኝ ከመሆኔ ጋር አበሰራችሁኝን? በምን ታበስሩኛላችሁ?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 55, '55. «በእውነት አበሰርንህ ከተስፋ ቆራጮችም አትሁን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 56, '56. «ከጠማማዎችም በስተቀር ከጌታው እዝነት ተስፋን የሚቆርጥ ማነው?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 57, '57. «እናንተ መልዕክተኞች ሆይ! ኧረ ለመሆኑ ነገራችሁ ምንድን ነው?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 58, '58. አሉም: «እኛ አመፀኞች ወደ ሆኑ ሕዝቦች ተልከናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 59, '59. «የሉጥ ቤተሰቦች ብቻ ሲቀሩ እነርሱን እኛ ሁላቸውንም በእርግጥ የምናድናቸው ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 60, '60. «ሚስቱ ብቻ ስትቀር።» (አሉ) እርሷንማ በቅጣቱ ውስጥ ከሚቀሩት ሰዎች መሆኗን ወስነናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 61, '61. መልዕክተኞቹም የሉጥን ቤተሰቦች በመጡባቸው ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 62, '62. ሉጥ «እናንተ የተሳሳታችሁ ሕዝቦች ናችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 63, '63. አሉም: «አይደለም:: እኛ ህዝቦችህ በእሱ ይጠራጠሩበት በነበሩት ቅጣት መጣንልህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 64, '64. «እውነትንም ይዘን መጣንልህ:: እኛም በእርግጥ እውነተኞች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 65, '65. «ከቤተሰብህ ጋር በሌሊቱ ከፊል (አጋማሽ) ላይ ሂድ:: በኋላቸዉም ተከተል:: ከናንተም አንድም ሰው ወደ ኋላው አይገላመጥ:: ወደ ታዘዛችሁበትም ስፍራ እለፉ።» አሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 66, '66. ወደ እርሱም ያንን ትዕዛዝ አወረድን :: እርሱም የእነዚህ ሕዝቦች መጨረሻ ያነጉ ሲሆኑ ስራቸው መቆረጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 67, '67. የከተማይቱም ሰዎች የሚበሳሰሩ ሆነው መጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 68, '68. ሉጥም አለ፡- «እነዚህ እንግዶቼ ናቸውና አታጋልጡኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 69, '69. «አላህንም ፍሩ አታሳፍሩኝም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 70, '70. «ከዓለማት ማንንም እንዳታስተናግድ አልከለከልንህምን?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 71, '71. ሉጥም፡- «እነዚህ ሴቶች ልጆቼ ናቸው። የምትፈጽሙ ከሆናችሁ አግቧቸው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 72, '72. (መልዕክተኛችን ሙሐመድ ሆይ!) በዕድሜህ እንምላለን እነርሱ በእርግጥ በስካራቸው ውስጥ ይዋልላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 73, '73. ጩኸቲቱም ጸሐይ የወጣችባቸው ሲሆኑ ያዘቻቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 74, '74. ላይዋንም ከታችዋ አደረግን:: በእነርሱም ላይ የሸክላ ድንጋዮችን አዘነብንባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 75, '75. በዚህ ውስጥ ለተመልካቾች በእርግጥ ብዙ መገሰጫዎች አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 76, '76. እርሷም ከተማይቱ በቀጥታ መንገድ ላይ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 77, '77. በዚህ ውስጥ በእርግጥ ለአማኞች መገሰጫ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 78, '78. እነሆ የአይካ ሰዎችም በእርግጥ በዳዮች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 79, '79. ከእነርሱም ተበቀልን ሁለቱም የሉጥና የአይከት ሕዝቦች ከተሞች በእርግጥ በግልጽ መንገድ ላይ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 80, '80. የሒጅር ሰዎች መልዕክተኞቹን በእርግጥ አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 81, '81. ተዓምራታችንን ሰጠናቸው ከርሷም ዘንጊዎች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 82, '82. ከኮረብታዎችም ቤቶችን ጸጥተኞች ሆነው ይጠርቡ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 83, '83. ያነጉ ሲሆኑ ጩኸት ያዘቻቸው (ወደሙ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 84, '84. ይሠሩት የነበሩትም ምንም አልጠቀማቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 85, '85. ሰማያትንና ምድርን በመካከላቸው ያለውንም ሁሉ በእውነት እንጂ በላግጣ አልፈጠርንም:: ሰዓቲቱም በእርግጥ መጪ ናት:: መልካምን ይቅርታ አድርግላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 86, '86. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ እርሱ ያልነበረን ነገር ሁሉ ፈጣሪው፤ አዋቂው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 87, '87. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሚደጋገሙ የሆኑን ባለ ሰባት አንቀጽንና ታላቁንም ቁርኣን በሙሉ በእርግጥ ሰጠንህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 88, '88. ከእነርሱ ከከሓዲያን ብዙዎችን ወገኖች በእርሱ ወደ አጣቀምንበት ጸጋ ዓይኖችህን አትዘርጋ፤ በእነርሱም ላይ ባያምኑ አትዘን፤ ክንፍህንም ለአማኞች አለዝብ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 89, '89. (መልዕክተኛችን ሙሐመድ ሆይ!) «ግልጽ አስፈራሪ እኔ ነኝ።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 90, '90. (ሰዎችን ለማገድ የመካን በሮች) በተከፋፈሉት ላይ እንደ አወረድነው (ቅጣት አስፈራሪያችሁ ነኝ በል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 91, '91. እነርሱም እነዚያ ቁርኣንን ክፍልፍሎች ያደረጉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 92, '92. (መልዕክተኛችን ሙሐመድ ሆይ!) በጌታህ እንምላለን ሁላቸውንም እንጠይቃቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 93, '93. ይሠሩት ከነበሩት ነገር ሁሉ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 94, '94. (መልዕክተኛችን ሙሐመድ ሆይ!) የታዘዝክበትንም ነገር በይፋ ግለጽ:: አጋሪዎችንም ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 95, '95. ተሳላቂዎችንም ሁሉ እኛ በቅተንሃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 96, '96. እነርሱም እነዚያ ከአላህ ጋር ሌላ አምላክን ያደረጉ ናቸው:: በእርግጥም ፍጻሜያቸውን ወደፊት ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 97, '97. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተም በሚሉት ነገር ልብህ የሚጠብ መሆኑን እናውቃለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 98, '98. ጌታህን ከማመስገን ጋር አጥራው:: ከሰጋጆቹም ሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (15, 99, '99. (መልዕክተኛችን ሙሐመድ ሆይ!) እውነቱም ነገር (ሞት) እስኪመጣልህ ድረስ ጌታህን ተገዛ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 1, '1. (ከሓዲያን ሆይ!)፤ የአላህ ትዕዛዝ መጣ ስለዚህ አታጣድፉት:: አላህ ከማይገባው ሁሉ ጠራ:: ከሚያጋሩትም ሁሉ ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 2, '2. ከባሮቹ መካከል በሚሻው ሰው ላይ መላዕክትን ከራዕይ ጋር በፈቃዱ ያወርዳል:: «ከሓዲያንን በቅጣት አስጠንቅቁ:: እነሆ ከእኔ በስተቀር ሌላ ትክክለኛ አምላክ የለም:: ፍሩኝም።» ማለትን አስታውቁ በማለት ያወርዳል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 3, '3. ሰማያትንና ምድርን በእውነት ፈጠረ:: ከሚያጋሩት ሁሉ ጠራ :: ከፍም አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 4, '4.ሰውን ከፍትወት ጠብታ ፈጠረው:: ከዚያም እርሱ ወዲያውኑ ትንሣኤን በመካድ ግልጽ ተከራካሪ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 5, '5. (ሰዎች ሆይ!) ግመልን፤ ከብትን፤ ፍየልንም፤ በእርሷ ብርድ መከላከያ ሙቀትና ሌሎች ጥቅሞችም ያሉባት ስትሆን ለእናንተ ፈጠረላችሁ:: ከእርሷም ትበላላችሁ (ትመገባላችሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 6, '6. በእርሷም ወደ ማረፊያዋ በምትመልሷት ጊዜና ጧት ወደ ግጦሽ ቦታዋ በምታሰማሯት ወቅት ለእናንተ ውበት አለላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 7, '7. ጓዞቻችሁንም ነፍሶቻችሁን በማስቸገር እንጂ ወደ ማትደርሱበት አገር ትሸከማለች:: ጌታችሁ በእርግጥ ሩህሩህ እና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 8, '8. ፈረሶችን፤ በቅሎዎችንና አህዮችን ልትጋልቧቸውና ልታጌጡባቸው ፈጠረላችሁ:: የማታውቁትን ድንቅ ነገርም ወደ ፊት ይፈጥራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 9, '9. በአላህም ላይ በችሮታው ቀጥተኛውን መንገድ መግለጽ አለበት:: ከእርሷም ጠማማ አለ:: በሻም ኖሮ ሁላችሁንም ባቀናችሁ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 10, '10. እርሱ ያ ከሰማይ ውሃን ያወረደ ነው:: ከእርሱም ለእናንተ መጠጥ አለላችሁ:: ከእርሱም እንስሳዎችን በእርሱ ውስጥ የምታሰማሩበት ዛፍ ይበቅልበታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 11, '11. በእርሱ አዝመራን፣ የዘይት ወይራን፣ ዘምባባዎችን፣ ወይኖችንና ከፍሬዎችም ሁሉ ያበቅልላችኋል:: በዚህ ክስተት ውስጥ ለሚያስተነትኑ ሕዝቦች ሁሉ በእርግጥ ትልቅ ተዓምር አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 12, '12. ለእናንተ ሌሊትንና ቀንን ጸሐይንና ጨረቃንም ገራላችሁ:: ከዋክብትም በሙሉ በፈቃዱ ብቻ የተገሩ ናቸው:: በዚህ ክስተት ውስጥ ለሚያውቁ ሕዝቦች ሁሉ በእርግጥ አያሌ ተዓምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 13, '13. በምድርም ላይ መልኮቹ የተለያዩ ሆኖ የፈጠረላችሁን ሁሉ ገራላችሁ:: በዚህ ውስጥ ለሚገሠጹ ሕዝቦች ሁሉ ግልጽ ተዐምር አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 14, '14. እርሱ ያ ባሕርን ከእርሱ እርጥብ ስጋን ልትበሉና ከእርሱም የምትለብሱትን ጌጣጌጥ ታወጡ ዘንድ የገራ ነው:: መርከቦችንም በውስጡ ውሃውን ቀዳጆች ሆነው ሲንሻለሉ ታያለህ:: ከችሮታው ልትፈልጉና ልታመሰግኑም ገራላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 15, '15. በምድር ውስጥ በናንተ እንዳታረገርግ ተራራዎችን ጣለባት። ትመሩም ዘንድ ጅረቶችንና መንገዶችን አደረገ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 16, '16. ምልክቶችንም አደረገ:: በከዋክብትም እነርሱ ይመራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 17, '17. (ሰዎች ሆይ!) የሚፈጥር ልክ እንደማይፈጥር ነውን? አትገሠጹምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 18, '18. የአላህን ጸጋ ብትቆጥሩ አትዘልቋትም:: አላህ መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 19, '19. አላህ የምትደብቁትንና የምትገልጹትንም ሁሉ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 20, '20. እነዚያም ከአላህ ሌላ የምትገዟቸው አማልክት ሁሉ ምንንም አይፈጥሩም:: እንዲያዉም እነርሱ ራሳቸው ይፈጠራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 21, '21. እነርሱ ሕያው ያልሆኑ ሙታን ናቸው:: እራሳቸው እንኳን መቼ እንደሚቀሰቀሱ አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 22, '22. አምላካችሁ አንድ አምላክ ብቻ ነው:: እነዚያም በመጨረሻይቱ ዓለም የማያምኑት ልቦቻቸው ከሓዲያን ናቸው:: እነርሱም የኮሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 23, '23. አላህ የሚደብቁትንና የሚገልጹትን ሁሉ የሚያውቅ ለመሆኑ ቅንጣት ያህል ጥርጣሬ የለበትም:: እርሱ ኩሩዎችን አይወድም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 24, '24. ጌታችሁ በሙሐመድ ላይ ምን አወረደ በተባሉ ጊዜም: «የመጀመሪያዎቹ ሕዝቦች ተረቶችን ነው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 25, '25. ይህንን የሚሉት በትንሣኤ ቀን ኃጢአቶቻቸውን በሙሉና ከነዚያም ያለ ዕውቀት ሆነው ከሚያጣምሟቸው ሰዎች ኃጢአቶች ከፊሉን ሊሸከሙ ነው:: ንቁ የሚሸከሙት ኃጢአት ምንኛ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 26, '26. እነዚያ ከእነርሱ (ከቁረይሾች) በፊት የነበሩት ከሓዲያን አሴሩ:: ከዚያም አላህ ሕንጻዎቻቸውን ከመሠረቶቻቸው አፈረሰ:: እናም ጣሪያው በላያቸው ላይ ወደቀባቸው:: ቅጣቱም ከማያውቁት ስፍራ መጣባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 27, '27. ከዚያም በትንሣኤ ቀን ያዋርዳቸዋል:: «እነዚያም በእነርሱ ጉዳይ ትከራከሩኝ የነበራችሁት ተጋሪዎቼ የት ናቸው?» ይላቸዋል። እነዚያ እውቀትን የተሰጡት ክፍሎች «ዛሬ ሐፍረቱና ቅጣቱ በከሓዲያን ላይ ነው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 28, '28. እነዚያ ነፍሶቻችውን በዳይ ሆነው መላዕክት የሚገድሏቸው «ከክፉ ሥራ ምንም ነገር የምንሠራም አልነበርንም» ሲሉ ታዛዥነታቸውን ይገልፃሉ:: «በእውነት አላህ ትሠሩት የነበራችሁትን ነገር አዋቂ ነው።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 29, '29. «የገሀነምንም ደጃፎች በውስጧ ዘውታሪዎች ስትሆኑ ግቡ።» ይባላሉ:: የኩሩ ሰዎች ሁሉ መኖሪያ የሆነችው ገሀነምም በእርግጥ ከፋች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 30, '30. ለእነዚያም ለተጠነቀቁት ሰዎች «ጌታችሁ ምንን ነገር አወረደ?» ተባሉ:: «መልካምን ነገር አወረደ» አሉ:: ለእነዚያ ደግ ለሠሩት ህዝቦች ሁሉ በዚህች በቅርቢቱ ዓለም መልካም ኑሮ አለላቸው:: የመጨረሻይቱም አገር በእርግጥ በላጭ ናት:: የጥንቁቆቹም አገር ገነት ምን ታምር!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 31, '31. እርሷም የሚገቧትና በሥርዋ ወንዞች የሚፈሱባት ስትሆን የመኖሪያ አትክልቶች (ጀነት) ናት:: ለእነርሱም በውስጧ የሚሹት ነገር ሁሉ አለላቸው:: ልክ እንደዚሁም አላህ ጥንቁቆችን ይመነዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 32, '32. እነዚያ ጥሩ ሆነው መላዕክት «ሰላም ለእናንተ ይሁን" እያሉ የሚገድሏቸው "ትሠሩት በነበራችሁት ሥራ ምክንያትም ወደ ገነት ግቡ።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 33, '33. ከሓዲያን የመላዕክትን ወደ እነርሱ መምጣት ወይም የጌታህ ትዕዛዝ መምጣቱን እንጂ ሌላን ይጠባበቃሉን? ከእነርሱ በፊት የነበሩትም ልክ እንደዚህ ሠርተዋል:: አላህም አልበደላቸዉም:: ግን እነርሱ ነፍሶቻቸውን የሚበድሉ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 34, '34. እናም የሠሯቸዉም ኃጢአቶች ቅጣት አገኛቸው:: ይሳለቁበት የነበሩት ነገር ሁሉ በእነርሱ ላይ ወረደባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 35, '35. እነዚያም ጣዖታትን በአላህ ያጋሩ ህዝቦች «አላህ በሻ ኖሮ ከእርሱ ሌላ እኛም ሆንን አባቶቻችን ምንንም ባልተገዛን ነበር:: ያለ እርሱም ትዕዛዝ ምንንም እርም ባላደረግን ነበር።» አሉ:: እነዚያም ከእነርሱ በፊት የነበሩት ህዝቦች ልክ እንደዚሁ ሠሩ:: በመልዕክተኞቹም ላይ ግልጽ ማድረስ ብቻ እንጂ ሌላ የለባቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 36, '36. በየሕዝቡም ሁሉ ውስጥ አላህን ተገዙ ጣዖትን ራቁ በማለት የሚያስተምር መልዕክተኛን ልከናል:: ከእነርሱም ውስጥ አላህ ያቀናው አለ:: ከእነርሱም ውስጥ በእርሱ ላይ ጥመት የተረጋገጠበት አለ:: እናም በምድር ላይ ሂዱ:: የአስተባባዮችም መጨረሻ እንዴት እንደ ነበር ተመልከቱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 37, '37. (መልዕክተኛችን ሙሐመድ ሆይ!) በመቅናታቸው ላይ ብትጓጓ (ምንም ልታደርግ አትችልም):: ምክንያቱም አላህ የሚያጠመውን አያቀናዉምና:: ለእነርሱም ከረዳቶች ምንም የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 38, '38. ጥብቅ መሐሎቻቸውንም «አላህ የሚሞትን ሰው አያስነሳም።» ሲሉ በአላህ ስም ማሉ:: አባባላቸው ሐሰት ነው። ያስነሳቸዋል:: በእርሱ ላይ ቃል ኪዳን ገብቷል:: አረጋግጧልም:: ግን አብዛኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 39, '39. የሚቀሰቅሳቸዉም ለእነርሱ ያንን የሚለያዩበትን ሊገልጽላቸውና እነዚያ የካዱትም እነርሱ ውሸታሞች የነበሩ መሆናቸውን እንዲያውቁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 40, '40. ለማንኛዉም ነገር መሆኑን በፈለግን ጊዜ ቃላችን ለእርሱ "ሁን" ማለት ብቻ ነው:: ወዲያዉም ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 41, '41. እነዚያም ከተበደሉ በኋላ በአላህ መንገድ ላይ የተሰደዱ በቅርቢቱ ዓለም መልካሚቱን አገር (መዲናን) እናሰፍራቸዋለን:: የመጨረሻይቱም ዓለም ምንዳ ታላቅ ነው:: (ከሓዲያን) ቢያውቁ ኖሮ (በተከተሏቸው ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 42, '42. እነርሱ እነዚያ የታገሡና በጌታቸዉም ላይ የሚጠጉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተም በፊት ወደ እነርሱ ወሕይን የምናወርድላቸውን ሰዎችን እንጂ ሌላን አልላክንም:: (ሰዎች ሆይ! ) የማታውቁም ከሆናችሁ የዕውቀትን ባለቤቶችን ጠይቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 44, '44. በግልጽ ማስረጃዎችና በመጽሐፍ ላክናቸው። ለሰዎችም ወደ እነርሱ የተወረደላቸውን ፍች ትገልጽላቸውና ያስተነትኑም ዘንድ ወደ አንተ ቁርኣንን አወረድን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 45, '45. እነዚያን መጥፎዎችን የዶለቱ ሰዎች አላህ በእነርሱ ምድርን የሚያስዉጣቸው ወይም ከማያውቁት ሥፍራ ቅጣት የሚመጣባቸው መሆኑን ተማመኑን? አይፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 46, '46. ወይም ከአገር ወደ አገር በሚዛወሩበት ጊዜ በእንቅስቃሴ ላይ እያሉ የሚይዛቸው መሆኑን አይፈሩምን? እነርሱም አሸናፊዎች አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 47, '47. ወይም ቀስ በቀስ በማጉደል ላይ የሚይዛቸው መሆኑን ተማመኑን? አይፈሩምን? ጌታችሁም ሩሕሩህና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 48, '48. ወደዚያ ከማንኛዉም ነገር አላህ ወደ ፈጠረው ጥላዎቹ እነርሱም የተዋረዱ ሲሆኑ ለአላህ ሰጋጆች ሆነው ከቀኝ እና ከግራዎች ወደ ሚዛወሩት አላዩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 49, '49. በሰማያትና በምድር ያለው ተንቀሳቃሽ ሁሉ መላዕክትም ለአላህ ብቻ ይሰግዳሉ:: እነርሱም አይኮሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 50, '50. ጌታቸውን ከበላያቸው ሲሆን ይፈሩታል:: የታዘዙትንም ሁሉ ይሰራሉ (ይፈጽማሉ):: {1}', '{1} አዚህ የንባብ ሱጁድ (ሱጁድ አትላዋ) ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 51, '51. አላህም አለ: «ሁለት አማልክት አትያዙ እርሱ አንድ አምላክ ብቻ ነው:: እኔን ብቻ ፍሩኝ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 52, '52. በሰማያትና በምድር ያለው ሁሉ የእርሱ ብቻ ነው:: አምልኮም ዘወትር ለርሱ ብቻ ነው:: ከአላህ ሌላ ያለን ትፈራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 53, '53. ማንኛዉም በናንተ ላይ ያለው ጸጋ ከአላህ ብቻ ነው። ከዚያም ችግር በደረሰባችሁ ጊዜ ወደ እርሱ ብቻ ትጮሀላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 54, '54. ከዚያም ከናንተ ላይ ችግርን ባነሳላችሁ ጊዜ ከናንተ የሆኑ ቡድኖች ወዲያውኑ በጌታችሁ ጣዖትን ያጋራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 55, '55. የሚያጋሩትም በሰጠናቸው ሊክዱ ነው:: ተጠቀሙም ወደፊትም የሚደርስባቸውን ታውቃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 56, '56. ለማያውቁት ጣዖታትም ከሰጠናቸው ሲሳይ ድርሻን ያደርጋሉ:: በአላህ እምላለሁ ትቀጣጥፉት ከነበራችሁት ሁሉ በእርግጥ ትጠየቃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 57, '57. ለአላህ ሴቶች ልጆችን ያደርጋሉ። ጥራት ይገባው። ለእነርሱ ግን የሚፈልጉትን ያደርጋሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 58, '58. ከመሀከላቸው አንዱ በሴት ልጅ (መወለድ) በተበሰረ ጊዜ እርሱ የተቆጨ ሆኖ ፊቱ ጠቁሮ ቅስሙ ይሰበራል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 59, '59. ከተበሰረበት ነገር መጥፎነት በውርደት ላይ ሆኖም ቢሆን ይያዘውን? ወይስ በአፈር ውስጥ ይደብቀውን? በማለት እያምታታ ከሰዎች ይደበቃል:: የሚፈርዱት ፍርድ ምንኛ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 60, '60. ለእነዚያ በመጨረሻይቱ ዓለም ለማያምኑት ሰዎች ሁሉ መጥፎ መገለጫ አላቸው:: ለአላህ ግን ታላቅ መገለጫ አለው:: እርሱም ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 61, '61. አላህም ሰዎችን በበደላቸው ሁሉ በቀጣቸው ኖሮ በምድር ላይ ከተንቀሳቃሽ ምንንም ባላስቀረ ነበር:: ግን እስከተወሰነ ጊዜ ድረስ ያቆያቸዋል:: ጊዜያቸዉም በመጣ ወቅት አንዲትን ሰዓት አይዘገዩም፤ አይቀድሙም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 62, '62. ለአላህም የሚጠሉትን ነገር ያደርጋሉ:: ለእነርሱም መልካሚቱ (ሀገር) እንዳለቻቸው በምላሶቻቸው ውሸትን ይናገራሉ:: ለእነርሱም እሳት ያለቻቸው መሆናቸውና እነርሱም ወደ እርሷ በቅድሚያ የሚነዱ መሆናቸው ጥርጥር የለበትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 63, '63. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ እንምላለን ካንተ በፊት ወደ ነበሩት ሕዝቦች በእርግጥ ብዙ መልዕክተኞችን ልከናል:: ሰይጣንም ለእነርሱ ስራዎቻቸውን ሸለመላቸው:: ረዳታቸው ዛሬም እርሱ ነው:: ለእነርሱም ኋላ አሳማሚ ቅጣት አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 64, '64. (መልዕክተኛችን ሙሐመድ ሆይ!) ያንን በእርሱ የተለያዩበትን ለእነርሱ ልታብራራላቸውና ለሚያምኑትም ህዝቦች መሪና እዝነት ሊሆን እንጂ ባንተ ላይ መፅሀፉን አላወረድንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 65, '65. አላህ ከሰማይ ውሃን አወረደ:: በእርሱም ምድርን ከሞተች በኋላ ህያው አደረገ:: በዚህ ውስጥ ለሚሰሙ ህዝቦች በእርግጥ ተዓምር አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 66, '66. (ሰዎች ሆይ!) ለእናንተ በግመል በከብት በፍየል አፈጣጠር አያሌ ምክር ሰጪ ትምህርት አለላችሁ:: በሆዶች ውስጥ ካለው ከፈርስና ከደም መካከል ጥሩ ወተትን ለጠጪዎች ጣፋጭ ሲሆን እናጠጣችኋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 67, '67. ከዘንባባዎች ከወይኖችም ፍሬዎች እንመግባችኋለን፤ ከእርሱ ጠጅንና መልካም ምግብንም ትሰራላችሁ (ታዘጋጃላችሁ):: በዚህም ውስጥ ለሚያስቡ ህዝቦች በእርግጥ ተዓምር አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም ወደ ንብ እንዲህ ሲል (አስታወቀ) አስተማረ፡ «ከተራራዎች ከዛፍና ሰዎች ከሚሠሩት ቀፎ ቤቶችን ያዢ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 69, '69. «ከዚያም ከፍሬዎች ሁሉ ብይ የጌታሽንም መንገዶች ለአንቺ የተገሩ ሲሆኑ ግቢ።» ከሆዶቿ መልኮቹ የተለያዩ መጠጥ ይወጣል:: በእርሱ ውስጥ ለሰዎች ፍቱን መድሀኒት አለበት። በዚህ ውስጥ ለሚያስተነትኑ ህዝቦች ተዓምር አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 70, '70. አላህም ፈጠራችሁ ከዚያ ይገድላችኋል:: ከናንተም መካከል ከእውቀት በኋላ ምንንም ነገር የማያውቅ ወደሚሆንበት የጃጀ እድሜ የሚመለስም ሰው አለ:: አላህ ሁሉን አዋቂ፤ በሁሉም ነገር ላይ ቻይም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 71, '71. አላህ ከፊላችሁን በከፊሉ ላይ በሲሳይ አበለጠ:: እነዚያም በላጭ የተደረጉት ሲሳያቸውን እጆቻቸው በያዟቸው ባሮች ላይ እነርሱ በእርሱ ይስተካከሉ ዘንድ መላሾች አይደሉም:: ታዲያ በአላህ ጸጋ ለእርሱ ተጋሪ በማድረግ ይክዳሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 72, '72. አላህ ከነፍሶቻችሁ (ከጎሳዎቻችሁ) ለእናንተ ሚስቶችን አደረገ (የትዳር አጋሮችን ፈጠረ)፤ ለእናንተም ከሚስቶቻችሁ ወንዶች ልጆችን የልጅ ልጆችንም አደረገላችሁ:: ከመልካሞችም ጸጋዎች ሰጣችሁ:: ታዲያ በውሸት በጣኦት አምነው በአላህ ጸጋ ይክዳሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 73, '73. ከአላህም ሌላ ከሰማያትና ከምድር ምንንም ሲሳይ የማይሰጧቸውንና ምንንም የማይችሉትን እነርሱ ያመልካሉን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 74, '74. (መልዕክተኛችን ሙሐመድ ሆይ!) ለአላህ አምሳያዎችን አታድርጉ:: አላህ ያውቃል፤ እናንተ ግን አታውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 75, '75. በምንም ላይ የማይችል ሆኖ በይዞታ (አለቃ ያለበት) የሆነውን ባሪያና መልካም ሲሳይን ሰጥተነው እርሱም ከእርሱ ከሰጠነው በሚስጥርና በግልጽ የሚለግሰውን ነፃ ሰው አላህ ለጣኦትና ለእርሱ ምሳሌ አደረገ:: ሁለቱ ይስተካከላሉን? ምስጋና ሁሉ ለአላህ ይሁን:: በእውነቱ አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 76, '76. አላህ ሁለትን ወንዶች (ለከሓዲያንና ለአማኞች) ምሳሌ አደረገ:: አንደኛቸው በምንም ነገር ላይ የማይችል ዲዳ ነው:: እርሱም በጌታው ላይ ሸክም ነው:: ወደ የትም ቢያዞረው ደግ ነገር አያመጣም:: እርሱና ያ በቀጥተኛው መንገድ ላይ ሆኖ በማስተካከል (ፍትህ) የሚያዘው ሰው ይስተካከላሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 77, '77. በሰማያትና በምድር ያለው ሩቅ ምስጢር የአላህ ብቻ ነው:: የሰዓቲቱም ነገር መምጣቷ እንደ ዓይን ቅጽበት እንጂ አይደለም:: ወይም ይበልጥ የቀረበ ነው:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 78, '78. አላህ ከእናቶቻችሁ ሆዶች ምንም የማታውቁ ሆናችሁ አወጣችሁ:: ታመሰግኑ ዘንድም ለእናንተ መስሚያንና ማያዎችን ልቦችንም አደረገላችሁ (ፈጠረላችሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 79, '79. ወደ በራሪዎችም በሰማይ አየር ውስጥ ለመብረር የተገሩ ሲሆኑ ከመውደቅ አላህ እንጂ ሌላ የማይዛቸው መሆናቸውን አይመለከቱምን? በዚህ ውስጥ ለሚያምኑ ህዝቦች ሁሉ አያሌ ተዓምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 80, '80. አላህም ከቤቶቻችሁ ለእናንተ መርጊያን (ማረፊያን) አደረገላችሁ (ፈጠረላችሁ):: ከእንስሳዎችም ቆዳዎችን በጉዟችሁ ቀንም ሆነ በመቀመጫችሁ ቀን የምታቀሏቸውን ቤቶች (ዳሶች) ለእናንተ ፈጠረላችሁ:: ከበጓ ሱፎች፣ ከግመሏም ጠጉሮች፣ ከፍየሏም ጠጉሮች የቤት እቃዎችን እስከ ጊዜም ድረስ መጠቃቀሚያን አደረገላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 81, '81. አላህ ከፈጠረው ነገር ለእናንተ ጥላዎችን ፈጠረላችሁ:: ከጋራዎችም መከለያዎችን ፈጠረላችሁ:: ሐሩርንም ብርድንም የሚጠብቋችሁን ልብሶች፤ የጦራችሁንም አደጋ የሚጠብቋችሁን ጥሩሮች ፈጠረላችሁ:: ልክ እንደዚሁ ትሰልሙ ዘንድ ጸጋውን በእናንተ ላይ ይሞላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 82, '82. (መልዕክተኛችን ሙሐመድ ሆይ!) ከኢስላም ቢሸሹም ባንተ ላይ ያለብህ ግልጽ ማድረስ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 83, '83. የአላህን ጸጋ ያውቃሉ:: ሆኖም ከዚያ ይክዷታል:: አብዛኞቻቸዉም ከሓዲያን ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 84, '84. ከየህዝቡም ሁሉ መስካሪን የምንቀሰቅስበትን ቀን አስታውስ:: ከዚያ ለእነዚያ ለካዱት ንግግር አይፈቀድላቸዉም:: እነርሱም በወቀሳ አይታለፉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 85, '85. እነዚያ የበደሉ ሰዎች ቅጣትን ባዩ ጊዜ ለእነርሱ አይቃለልላቸዉም:: ጊዜም አይሰጣቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 86, '86. እነዚያ በአላህ ያጋሩት ሰዎች ተጋሪዎቻቸውን ባዩ ጊዜ «ጌታችን ሆይ! እነዚህ ካንተ ሌላ እናመልካቸው የነበሩ ተጋሪዎቻችን ናቸው።» ይላሉ። አማልክቶችም «ውሸታሞች ናችሁ።» በማለት ቃሉን ወደ እነርሱው መልሰው ይወረውራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 87, '87. አጋሪዎቹ በዚያ ቀንም ታዛዥነታቸውን ወደ አላህ ያቀርባሉ:: ይቀጣጥፉት የነበሩትም ሁሉ ከእነርሱ ይጠፋባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 88, '88. እነዚያ በአላህ የካዱና ከአላህ መንገድ የከለከሉ ያጠፉ በነበሩት ምክንያት ቅጣትን በቅጣት ላይ ጨመርንባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 89, '89. (መልዕክተኛችን ሙሐመድ ሆይ!) በየህዝቡ ሁሉ ውስጥ ከጎሳቸው በራሳቸው ላይ መስካሪን የምንቀሰቅስበትንና አንተንም በእነዚህ ሕዝቦች ላይ መስካሪ አድርገን የምናመጣብህን ቀን አስታውስ:: መጽሐፉንም ለሁሉም ነገር አብራሪ፤ መመሪያ፣ እዝነትና ለሙስሊሞች አብሳሪ ሆኖ ባንተ ላይ አወረድነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 90, '90. አላህ በማስተካከል (በፍትህ) ፤ በማሳመር (በመልካም ሥራ) እና ለዝምድና ባለቤት በመስጠትም ያዛል። ከአስከፊ (ጸያፍ ነገር) ከማመንዘር፤ ከሚጠላ ነገር ሁሉ ከመበደልም ይከለክላል:: ትገነዘቡ ዘንድ ይገሥጻችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 91, '91. (ሙስሊሞች ሆይ!) ቃል ኪዳን በገባችሁ ጊዜ በአላህ ቃል ኪዳን ሙሉ:: መሓሎቻችሁንም ከአጠነከራችኋት በኋላና አላህን በእናንተ ላይ መስካሪ ያደረጋችሁ ስትሆኑ አታፍርሱ:: አላህ የምትሠሩትን ሁሉ ያውቃልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 92, '92. ቃል ኪዳናችሁን በማፍረስ አንዲቱ ሕዝብ ከሌላይቱ ሕዝብ የበዛች ለመሆንዋ በመካከላችሁ መሓሎቻችሁን ለክዳት መግቢያ አድርጋችሁ የምትይዙ ስትሆኑ እንደዚያች ፈትሏን ከጠነከረ በኋላ ትርትሮች አድርጋ እንዳፈረሰችው ሴት አትሁኑ:: አላህ በእርሱ ይሞክራችኋል፤ በትንሣኤ ቀንም ትለያዩበት የነበራችሁትን ነገር በእርግጥ ያብራራላችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 93, '93. አላህ በፈለገ ኖሮ አንዲት ሕዝብ ባደረጋችሁ ነበር:: ግን አላህ የሚሻውን ሰው ያጠማል:: የሚሻውን ሰው ያቀናል:: ትሠሩት ከነበራችሁት ሁሉ በእርግጥ ትጠየቃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 94, '94. ጫማዎች ከተደላደሉ በኋላ እንዳያንዳልጡ ከአላህ መንገድ በመከልከላችሁ ምክንያት ቅጣትንም እንዳትቀምሱ መሓሎቻችሁን በመካከላችሁ ለክዳት መግቢያ አታድርጉት:: ለእናንተም ያን ጊዜ ታላቅ ቅጣት አላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 95, '95. በአላህ ቃል ኪዳን ጥቂትን ዋጋ አትግዙ። የምታውቁ ብትሆኑ አላህ ዘንድ ያለው ምንዳ እርሱ ለእናንተ በላጭ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 96, '96. እናንተ ዘንድ ያለው ሁሉ ያልቃል:: አላህ ዘንድ ያለው ግን ለዘለዓለም ቀሪ ነው (አያልቅም):: እነዚያንም የታገሡትን ይሠሩት በነበሩት በመልካሙ ምንዳቸውን እንመነዳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 97, '97. ከወንድም ይሁን ከሴት እርሱ አማኝ ሆኖ በጎን የሠራ ሁሉ መልካም ኑሮን እናኖረዋለን:: ይሠሩት ከነበሩት ነገር በመልካሙም ምንዳቸውን እንመነዳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 98, '98. ቁርኣንንም ለማንበብ ባሰብክ ጊዜ እርጉም ከሆነው ሰይጣን በአላህ ተጠበቅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 99, '99. እርሱ በእነዚያ በትክክል ባመኑትና በጌታቸው ላይ በሚጠጉት ላይ ለእርሱ ሥልጣን የለዉምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 100, '100. ሥልጣኑ በእነዚያ በሚታዘዙት ላይና በእነዚያም እነርሱ በእርሱ ምክንያት አጋሪዎች በሆኑት ላይ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 101, '101. (መልዕክተኛችን ሙሐመድ ሆይ!) በአንቀጽም ስፍራ ሌላ አንቀጽን በለወጥን ጊዜ አላህም የሚያወርደውን ነገር አዋቂ ነው:: «አንተ ቀጣፊ እንጂ ሌላ አይደለህም።» ይላሉ:: በእውነቱ አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 102, '102. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያን ያመኑትን ሰዎች ለማረጋጋት ሙስሊሞቹንም ለመምራትና ለማብሰር ቁርኣንን ጂብሪል እውነተኛ ሲሆን ከጌታህ አወረደው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 103, '103. እነርሱም «እርሱን ቁርኣንን የሚያስተምረው ሰው ብቻ ነው።» ማለታቸውን በእርግጥ እናውቃለን:: የዚያ ወደ እርሱ የሚያስጠጉበት ሰው ቋንቋ ዐረበኛ ያልሆነ ዐጀምኛ ነው:: ይህ ቁርኣን ግን በግልጽ በዐረብኛ ቋንቋ የተነገረ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 104, '104. እነዚያን በአላህ አናቅጽ የማያምኑትን አላህ አይመራቸዉም:: ለእነርሱም አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 105, '105. ውሸትን የሚቀጣጥፉት እነዚያ በአላህ አናቅጽ የማያምኑት ብቻ ናቸው:: እነዚያም ውሸታሞቹ እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 106, '106. ከእምነቱ በኋላ በአላህ የካደ ሰው ብርቱ ቅጣት አለው። ልቡ በእምነት የረካ ሆኖ በክሕደት ቃል ለመናገር የተገደደ ሰው ብቻ ሲቀር:: ግን ልባቸውን በክሕደት የከፈቱ ሰዎች ከአላህ ቁጣ አለባቸው:: ለእነርሱም ታላቅ ቅጣት አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 107, '107. ይህ ቅጣት እነርሱ ቅርቢቱን ሕይወት ከመጨረሻይቱ በመምረጣቸው ምክንያትና አላህም ከሓዲያንን ሕዝቦች የማያቀና በመሆኑ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 108, '108. እነዚያ እነርሱ በልቦቻቸው፤ በዓይኖቻቸውና በጆሮቻቸዉም ላይ አላህ ያተመባቸው ናቸው:: እነዚያም ዝንጉዎቹ እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 109, '109. እነርሱ በመጨረሻይቱ ዓለም ከሳሪዎቹ እነርሱ ለመሆናቸው ጥርጥር የለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 110, '110. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዚያም ጌታህ ለእነዚያ ከተፈተኑ በኋላ ለተሰደዱት ከዚያም ለታገሉትና ለታገሡት ሁሉ ጌታህም ከፈተናዋ በኋላ በእርግጥ መሐሪና አዛኝ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 111, '111. (መልዕክተኛችን ሙሐመድ ሆይ!) ነፍስ ሁሉ ከራሷ ላይ የምትከራከር ሆና የምትመጣበትን ነፍስም ሁሉ የሠራችውን ዋጋ የምትቀበልበትን ቀን (አስታውስ):: እነርሱም ፈጹሞ አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 112, '112. አላህ ጸጥተኛ የረካች ሲሳይዋ ሰፊ ሆኖ ከየስፍራው ይመጣላት የነበረችውንና ከዚያም በአላህ ጸጋዎች የካደችውን አላህም ይሠሩት በነበሩት ኃጢአት የረሀብንና የፍርሀትን ቅጣቶች ያቀመሳትን ከተማ ምሳሌ አደረገ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 113, '113. ከእነርሱም ውስጥ የሆነ መልዕክተኛም በእርግጥ መጣላቸው:: አስተባበሉትም እነርሱም በዳዬች ሆነው ቅጣቱ ያዛቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 114, '114. አላህም ከሰጣችሁ ሲሳይ የተፈቀደና ንጹሕ ሲሆን ብሉ:: የአላህንም ጸጋ እርሱን የምትገዙት ከሆናችሁ አመስግኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 115, '115. በእናንተ ላይ እርም ያደረገው በክትን፣ ደምን፣ የአሳማን ሥጋ፣ ያንንም በሚታረድ ጊዜ በእርሱ ላይ ከአላህ ስም ሌላ የተወሳበትን ብቻ ነው:: አመጸኛና ወሰን አላፊም ሳይሆን ከእነዚህ አንዱን ለመብላት የተገደደ ሰው ይፈቀድለታል:: አላህ መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 116, '116. (ሰዎች ሆይ) በአላህ ላይ ውሸትን ልትቀጣጥፉ ምላሶቻችሁ በሚመጥኑት ውሸት «ይህ የተፈቀደ ነው፤ ይህ ደግሞ እርም ነው» አትበሉ:: እነዚያ በአላህ ላይ ውሸትን የሚቀጣጥፉ ክፍሎች በፍጹም አይድኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 117, '117. ጥቂት መጣቀም ብቻ አለላቸው:: ለእነርሱም አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 118, '118. (መልዕክተኛችን ሙሐመድ ሆይ!) በእነዚያ አይሁድ በሆኑት ሰዎች ላይ ከአሁን በፊት ባንተ ላይ የተረክነውን ነገር እርም አድርገንባቸዋል:: እኛም አልበደልናቸዉም:: ግን ራሳቸው ነፍሶቻቸውን ይበድሉ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 119, '119. ከዚያም ጌታህ ለእነዚያ በስህተት መጥፎን ለሠሩትና ከዚያም ከዚህ በኋላ ለተጸጸቱ ሥራቸውንም ላበጁ ጌታህ ከእርሷ በኋላ በእርግጥ መሓሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 120, '120. ኢብራሂም ለአላህ ታዛዥ፤ ወደ ቀጥተኛ ሃይማኖት ተዘንባይ ህዝብ ነበር:: ከአጋሪዎችም አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 121, '121. ለጸጋዎቹ አመስጋኝ ነበር:: መረጠው:: ወደ ቀጥተኛዉም መንገድ መራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 122, '122. በቅርቢቱም ዓለም በጎ ነገርን ሰጠነው:: እርሱም በመጨረሻይቱ ዓለም በእርግጥ ከመልካሞቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 123, '123. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዚያም የኢብራሂምን ሃይማኖት ቀጥተኛ ሲሆን ተከተል:: ከአጋሪዎቹም አልነበረም ማለትን ወደ አንተ አወረድን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 124, '124. (መልዕክተኛችን ሙሐመድ ሆይ!) በቅዳሜ ቀን መስራት ክልክል የተደረገው በእነዚያ በእርሱ በተለያዩበት ሰዎች ላይ ብቻ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም በትንሳኤ ቀን ይለያዩበት በነበሩት ነገር በመካከላቸው በእርግጥ ይፈርዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 125, '125. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ ጌታህ መንገድ በብልሃትና በመልካም ግሳጼ በለዘብተኛ ቃልም ሰዎችን ጥራ:: በዚያችም እርሷ መልካም በሆነችው ዘዴ ተከራከራቸው:: ጌታህ ከመንገዱ የተሳሳተውን ሰው አዋቂ ነው:: እንደዚሁም እርሱ ቅን የሆኑትን ሰዎች አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 126, '126. (ሙስሊሞች ሆይ!) ብትበቀሉም በእርሱ በተቀጣችሁበት ብጤ ተበቀሉ:: ብትታገሱ ግን እርሱ ለታጋሾች በእርግጥ በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 127, '127. (መልዕክተኛችን ሙሐመድ ሆይ!) ታገስ:: መታገስህ በአላህ ማስቻል ብቻ እንጂ አይደለም:: በእነርሱም ላይ ባያምኑ አትተክዝ:: ባንተ ላይ በሚመክሩት ተንኮልም በጭንቀት ውስጥ አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (16, 128, '128. አላህ ከእነዚያ እነርሱ ከሚፈሩትና ከእነዚያም እነርሱ ከመልካም ሠሪ ከሆኑት ሰዎች ጋር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 1, '1. ጥራት ለዚያ ባሪያውን (ሙሐመድን) ከተከበረው የሐረም መስጊድ ወደ እዚያ ዙሪያውን ወደ ባረክነው ሩቁ (አል አቅሷ) መስጊድ በሌሊት ለወሰደው አምላክ ለአላህ ይሁን:: ይህን ያደረግን ተዓምራታችንን ልናሳየው ነው:: እነሆ እርሱ (አላህ) ሰሚዉና ተመልካቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 2, '2. ለሙሳም (ተውራት የተባለውን) መጽሐፍ ሰጠነውና ለኢስራኢል ልጆች መሪ አደረግነው:: ከእኔ ሌላ ወኪል (መጠጊያ) አድርጋችሁ ማንንም አታድርጉ“ስንልም አዘዝናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 3, '3. «ከኑህ ጋር (በመርከቧ ላይ) የጫንናቸው (አማኝ )ዝርዮች ሆይ! (አላህን ተገዙ)፤ ኑህ በእርግጥ አምላኩን በብዛት አመስጋኝ ባሪያ ነበርና» አልናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 4, '4. ለኢስራኢል ልጆችም፡ “በምድር ላይ ሁለት ጊዜ ጥፋት ትፈጽማላችሁ:: አለቅጥም አምባገነን ትሆናላችሁ::” ስንል በመጽሐፉ ውስጥ ገለጽን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 5, '5. ከሁለቱ የመጀመሪያው ጥፋት መፈጸሚያ ወቅቱ በደረሰ ጊዜ የበረታ ኃይል ያላቸውን ባሮቻችንን በእናነተ ላይ ላክንባችሁ:: እነርሱም ቤቶችን ሁሉ በረበሩ:: ይህ መፈጸሙ የማይቀር ውሳኔ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 6, '6. (የኢስራኢል ልጆች ሆይ!) ከዚያም በኋላ በእነርሱ ላይ የድል አድራጊነትን እድል ሰጠናችሁ:: ገንዘብንና ወንዶች ልጆችንም ለገስናችሁ:: በሰው ኃይልም ብዙ አደረግናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 7, '7. መልካምን ብትሠሩ ለነፍሶቻችሁ መልካምን ሠራችሁ:: መጥፎንም ብትሠሩ በነፍሶቻችሁ ላይ ነው:: የኋለኛይቱ ጥፋት ቀጠሮ በደረሰ ጊዜ ፊቶቻችሁን ሊያስከፉ፤ መስጊዱንም በመጀመሪያ ጊዜ እንደገቡቡት ሊገቡ፤ ያሸነፉትንም ሁሉ ፈጽመው ማጥፋትን እንዲያጠፉ እንልካቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 8, '8. (የኢስራኢል ልጆች ሆይ! በመጽሐፉም አልን ብትጸጸቱ) «ጌታችሁ ሊያዝንላችሁ ይከጀላል:: ወደ ማጥፋት እንደገና ብትመለሱም እኛም ወደ ቅጣቱ እንመለሳለን:: ገሀነምንም ለከሓዲያን ሁሉ ማሰሪያ አድርገናል።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 9, '9. ይህ ቁርኣን ወደዚያች በሁሉ ነገር ቀጥተኛ ወደ ሆነችው መንገድ ይመራል:: እነዚያንም በጎ የሚሠሩትንም አማኞች ለእነርሱ ታላቅ ምንዳ ያላቸው መሆኑን ያበስራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 10, '10. እነዚያም በመጨረሻይቱ ዓለም የማያምኑት ለእነርሱ አሳማሚ ቅጣትን አዘጋጅተንላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 11, '11. ሰው መልካምን ነገር እንደሚለምን ሁሉ መጥፎንም ነገር ይለምናል:: ሰዉም ቸኳይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 12, '12. ሌሊትንና ቀንን ለችሎታችን ምልክቶች አደረግን:: የሌሊትን ምልክትም አበስን:: የቀንን ምልክትም የምታሳይ አደረግን:: ይህም የሆነበት ከአላህ ትርፍን ልትፈልጉበትና የዓመታትንም ቁጥርና ሒሳብን ታውቁበት ዘንድ ነው:: ነገሩንም ሁሉ ለያይተን ዘረዘርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 13, '13. ሰውን ሁሉ በራሪውን (ሥራውን) በአንገቱ ላይ አስያዝነው:: ለእርሱም በትንሣኤ ቀን የተዘረጋ ሆኖ የሚያገኘው የሆነን መጽሐፍ እናወጣለታለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 14, '14. (ከዚያም) «መጽሐፍህን አንብብ:: ዛሬ ባንተ ላይ ተቆጣጣሪነት በነፍስህ ብቻ በቃ።» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 15, '15. በቀናው መንገድ የተመራ ሁሉ የሚመራው ለእራሱ ብቻ ነው:: ከቀናው መንገድ የተሳሳተም የመሳሳቱ ጉዳት በእርሱ ላይ ብቻ ነው:: ተሸካሚም ነፍስ የሌላይቱን ኃጢአት አትሸከምም:: መልዕክተኛንም እስከምንልክ ድረስ ማንንም የምንቀጣ አይደለንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 16, '16. ማንኛዋንም ከተማ ለማጥፋት በፈለግን ጊዜ ባለ ጸጋዎችዋን እናዛቸዋለን:: በውስጧም ያምፃሉ:: በእርሷም ላይ የቅጣት ቃሉ ይፈጸምባታል:: ከዚያም ማውደምን እናወድማታለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 17, '17. ከኑሕም በኋላ ከየክፍለ ዘመናት ሰዎች ያጠፋናቸው ብዙዎች ናቸው:: (መልዕክተኛችን ሙሐመድ ሆይ!) የባሮቹንም ኃጢአቶች ውስጠ አዋቂ ተመልካች መሆን በጌታህ ብቻ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 18, '18. ጊዜያዊቱን ዓለም (በሥራው) የሚፈልግ ሁሉ ለእርሱ ከእርሷ ውስጥ የፈለግነውን ጸጋ ብቻ ለምንፈልገውም ብቻ እናስቸኩልለታለን:: ከዚያም ለእርሱ ገሀነምን መኖሪያ አድርገንለታል:: ተወቃሽና ከአላህ እዝነት የተባረረ ሆኖ ይገባባታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 19, '19. የመጨረሻይቱን ዓለም የፈለገ እና እርሱ አማኝ ሆኖ ለእርሷ ተገቢ የሆነን ሥራ የሠራ ደግሞ እነዚህ ሥራቸው የተመሰገነ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 20, '20. ሁሉንም እነዚህንም እነዚያንም ከጌታህ ስጦታ በዚህ ዓለም እንጨምርላቸዋለን:: የጌታህም ስጦታ በዚች ዓለም ክልክል አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) ከፊላቸውን በከፊሉ ላይ እንዴት እንዳስበለጥን ተመልከት:: የመጨረሻይቱም ሀገር በማዕረጎች በጣም የከበረችና በመብለጥም የላቀች ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 22, '22. (የሰው ልጅ ሆይ!) ከአላህ ጋር ሌላን አምላክ አታድርግ:: የተወቀስክ፤ ረዳት የሌለህ ትሆናለህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 23, '23. (የሰው ልጅ ሆይ!) ጌታህ እንዲህ ሲል አዘዘ:: እርሱን እንጂ ሌላን አትገዙ፤ ለወላጆቻችሁም መልካምን ሥሩ፤ ባንተ ዘንድ ሆነው ከወላጆችህ አንዳቸው ወይም ሁለታቸው እርጅናን ቢደርሱ «ኡፍ!» እንኳን አትበላቸው:: አትገላምጣቸዉም:: ለእነርሱም መልካምን ቃል ብቻ ተናገራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 24, '24. (ልጅ ሆይ!) ለሁለቱም የመተናነስ ክንፍን ዝቅ አድርግላቸው። «ጌታዬ ሆይ! በሕጻንነቴ በርህራሄ እንዳሳደጉኝ ሁሉ ለእነርሱም እዘንላቸው።» በልም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 25, '25. (ሰዎች ሆይ!) ጌታችሁ በነፍሶቻችሁ ውስጥ ያለውን ነገር ሁሉ ይበልጥ አዋቂ ነው:: ታዛዦችም ብትሆኑ ወይም ብታጠፉ እርሱ ለተመላሾች ሁሉ መሓሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 26, '26. (የሰው ልጅ ሆይ!) ለዝምድና ባለቤት ሁሉ ተገቢ መብቱን ስጥ:: ለምስኪንና ለመንገደኛም እንዲሁ መብቱን ስጥ:: (በሁሉም ነገር ላይ) ማባከንንም አታባክን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 27, '27. አባካኞች የሰይጣናት ወንድሞች ናቸውና:: ሰይጣንም ለጌታው ብርቱ ከሓዲ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 28, '28. ከጌታህም የምትከጅላትን ጸጋ ለማምጣት በማሰብ ከእነርሱ ብትዞር ለእነርሱ ልዝብን ቃል ተናገራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 29, '29. እጅህን ወደ አንገትህ ታጥፋ የታሠረች አታድርግ:: መዘርጋትንም ሁሉ አትዘርጋት:: የተወቀስክና የተቆጨህ ትሆናለህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 30, '30. ጌታህ ሲሳይን ለሚፈልገው ሁሉ ያሰፋል። ለሚፈልገውም ያጠባል። እርሱ በባሮቹ ሁኔታ ውስጠ አዋቂና ተመልካች ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 31, '31. (ሰዎች ሆይ!) ልጆቻችሁንም ድህነትን በመፍራት አትግደሉ:: እኛ እንመግባቸዋለን:: እናንተንም እንመግባችኃለን:: እነርሱን መግደል ታላቅ ኃጢአት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 32, '32. (ሰዎች ሆይ!) ዝሙትንም አትቅረቡ:: እርሱ በእርግጥ መጥፎ ሥራ ነውና:: መንገድነቱም ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 33, '33. (ሰዎች ሆይ!) ያቺንም አላህ ያከበራትን ነፍስ ያለ ሕግ አትግደሉ:: የተበደለ ሆኖ ለተገደለም ሰው ዘመዱ በገዳዩ ላይ ስልጣንን አድርገንለታል:: በመግደል ወሰንን አይለፍ:: እርሱ እገዛ ያለው ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 34, '34. (ሰዎች ሆይ!) የየቲምንም ገንዘብ የብርታቱን ጊዜ እስኪደርስ ድረስ በዚያች እርሷ መልካም በሆነች ሁኔታ እንጂ አትቅረቡ:: በቃል ኪዳናችሁም ሙሉ:: ቃል ኪዳን የሚጠየቁበት ጉዳይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 35, '35. (ሰዎች ሆይ!) በሰፈራችሁም ጊዜ ስፍርን ሙሉ:: በትክክለኛው ሚዛንም መዝኑ:: ይህ መልካም ነገር ነው:: መጨረሻዉም ያማረ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 36, '36. (የሰው ልጅ ሆይ!) ላንተ በእርሱ እውቀት የሌለህንም ነገር አትከተል:: መስሚያ፤ ማያ፤ ማሰቢያም እነዚህ ሁሉ ባለቤታቸው ከእነርሱ ተጠያቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 37, '37. (የሰው ልጅ ሆይ!) በምድር ላይ የተንበጣረርክ ሆነህም አትሂድ:: አንተ ፈጽሞ ምድርን አትሰረጉድምና:: በርዝመትም ፈጽሞ ጋራዎችን አትደርስምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 38, '38. (የሰው ልጅ ሆይ!) ይህ ሁሉ ክፋቱ ከጌታህ ዘንድ የተጠላ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 39, '39. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ጌታህ ከጥበብ ወደ አንተ ካወረደው ነገር ነው:: ከአላህ ጋር ሌላን አምላክ አታድርግ:: የተወቀስክ፤ የተባረርክ ሆነህ በገሀነም ውስጥ ትጣላለህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 40, '40. (ጣኦታዊያን ሆይ!) ጌታችሁ በወንዶች ልጆች መረጣችሁና ከመላዕክት ሴቶችን ልጆች ለራሱ ያዘን? እናንተ ከባድ ቃልን በእርግጥ ትናገራላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 41, '41. ይገሰጹ ዘንድ በዚህ ቁርኣን ውስጥ ደጋግመን በእርግጥ ገለጽን:: ለእነርሱ ግን ከትክክለኛው መንገድ መበርገግን እንጂ ሌላን አይጨምርላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነርሱ እንደሚሉት ከእርሱ ጋር ሌላ አማልክት በነበሩ ኖሮ ያን ጊዜ ወደ ዐርሹ ባለቤት መንገድን በፈለጉ ነበር።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 43, '43. ጥራት ይገባው:: አላህ እነርሱ ከሚሉት ነገር ሁሉ ከፍ ያለን ልቅና ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 44, '44. ሰባቱ ሰማያትና ምድር እንዲሁም በውስጣቸውም ያለው ሁሉ እርሱን ያጠራሉ:: ከነገሩ ሁሉ እሱን ከማመስገን ጋር የሚያጠራው እንጂ አንድም የለም:: ማጥራታቸውን ግን አታውቁትም:: እርሱ ታጋሽና መሓሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ቁርኣንን ባነበብክ ጊዜ ባንተና በእነዚያ በመጨረሻይቱ ዓለም በማያምኑት ሰዎች መካከል የሚሸሸግን ግርዶሽ አድርገናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) እንዳያውቁትም በልቦቻቸው ላይ ሽፋንን፤ በጆሮቻቸዉም ውስጥ ድንቁርናን አደረግን:: ጌታህንም ብቻውን ሆኖ በቁርኣን ባወሳሀው ጊዜ የሚሸሹ ሆነው በጀርባዎቻቸዉ ላይ ይዞራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 47, '47. እኛ ወደ አንተ በሚያዳምጡ፤ በሚንሾካሸኩ፤ በዳዮችም እርስ በእርሳቸው «የተደገመበትን ሰው እንጂ አትከተሉም።» በሚሉ ጊዜ የሚያዳምጡበትን ምክንያት አዋቂ ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) ላንተ ምሳሌዎችን እንዴት እንዳደረጉልህና ከዚያም እንዴት እንደ ተሳሳቱ ተመልከት:: ወደ እውነቱ ለመድረስ ትክክለኛውን መንገድ መከተል አይችሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 49, '49. አሉም፡- «አጥንቶችና ብስብሶች በሆን ጊዜ እኛ እንዴት እንደገና አዲስ ፍጥረት ሆነን በእርግጥ ተቀስቃሾች እንሆናለን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) (እንዲህ) በላቸው: «ድንጋዮች ወይም ብረትም ሁኑ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 51, '51. ወይም በልቦቻቸሁ ውስጥ የሚተልቅን ፍጥረትም ሁኑ (መቀስቀሳችሁ አይቀርም።)» «የሚመልሰንም ማነው?» ይላሉም። «ያ በመጀመሪያ ጊዜ የፈጠራችሁ ነው።» በላቸው:: ወደ አንተም ራሶቻቸውን ይነቀንቃሉ። «እርሱም መቼ ነው?» ይላሉም:: (መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) በላቸው: «እርሱ በቅርብ ቀን ሊሆን ይችላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 52, '52. «እርሱም የሚጠራችሁንና አላህን አመስጋኞቹ ሆናችሁ ጥሪውን የምትቀበሉበት፤ ጥቂትን ቀናት እንጂ ያልቆያችሁ መሆናችሁን የምትጠራጠሩበት ቀን ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) ለባሮቼም ንገራቸው:: መልካም የሆነችውን ቃል ብቻ ይናገሩ:: ሰይጣን በመካከላቸው ያበላሻልና:: ሰይጣን ለሰው ልጆች ግልጽ ጠላት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 54, '54. (ሰዎች ሆይ!) ጌታችሁ በእናንተ ሁኔታ አዋቂ ነው:: ቢፈልግ ያዝንላችኋል፤ ቢፈልግም ይቀጣችኃል። (መልዕክተኛችን ሙሐመድ ሆይ!) በእነርሱ ላይ ሀላፊ ሆነህ አላክንህም:: አታስገድዳቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 55, '55. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በሰማያትና በምድር ያለውን ሁሉ አዋቂ ነው:: ከፊሉን ነብያት በከፊሉ ላይ አብልጠናል:: ዳውድንም ዘቡርን ሰጥተነዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 56, '56. (መልዕክተኛችን ሙሐመድ ሆይ!) በለቸው (ጣዖታዊያን ሆይ!) « እነዚያን ከእርሱ ሌላ አማልዕክት የምትሏቸውን እስቲ ጥሯቸው:: ከናንተም ላይ ጉዳትን ማስወገድን ወደ ሌላ ማዞርንም አይችሉም።»።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 57, '57. እነዚያ እነርሱ የሚገዟቸው ማንኛቸዉም (ወደ አላህ) በጣም ቀራቢያቸው እንኳን ለራሳቸው ወደ ጌታቸው መቃረቢያን ሥራ ይፈልጋሉ:: እዝነቱንም ይከጅላሉ:: ቅጣቱንም ይፈራሉ:: (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህ ቅጣት የሚፈራ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 58, '58. አንዲትም ከተማ የለችም እኛ ከትንሳኤ ቀን በፊት አጥፊዎችዋ ወይም ብርቱን ቅጣት ቀጭዎችዋ ብንሆን እንጂ:: ይህም በመጽሐፍ የተጻፈ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 59, '59. ተዓምራትን ከመላክ የቀድሞዎቹ ሰዎች በእርሷ ማስተባበልና መጥፋት እንጂ ሌላ አልከለከለንም። ለሠሙድም ግመልን ግልጽ ተዓምር ሆና ሰጠናቸው:: በእርሷም በደሉ፤ ተዓምራትንም ለማስፈራራት እንጂ አንልክም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 60, '60. (መልዕክተኛችን ሙሐመድ ሆይ!) ላንተም ጌታህ በእውቀቱ ሰዎችን ያካበበ መሆኑን በነገርንህ ጊዜ የሆነውን አስታውስ:: በሌሊቱ ጉዞ በዓይንህ ያሳየንህም ትርኢት ለሰዎች ፈተና እንጂ አላደረግነዉም:: በቁርኣንም የተረገመችውን ዛፍ እንደዚሁ ፈተና እንጂ አላደረግንም፤ እናስፈራራቸዋለንም፤ ትልቅንም ጥመት እንጂ አይጨምርላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 61, '61. (መልዕክተኛችን ሙሐመድ ሆይ!) ለመላዕክትም «ለአደም ስገዱ» ባልናቸው ጊዜ የነበረውን ሁኔታ አስታውስ:: ወዲያዉም ሰገዱ ዲያብሎስ ብቻ ሲቀር «ከጭቃ ለፈጠርከው ሰው እሰግዳለሁን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 62, '62. «እስቲ ንገረኝ ይህ ያ በእኔ ላይ ያበለጥከው ነውን? እስከ ትንሳኤ ቀን ድረስ ብታቆየኝ ዘሮቹን ጥቂቶች ሲቀሩ ወደ ስህተት በእርግጥ እስባቸዋለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 63, '63. አላህም አለው: «ሂድ ከእነርሱም የተከተለህ ገሀነም የተሟላች ቅጣት ስትሆን ፍዳችሁ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 64, '64. «ከእነርሱ የቻልከውንም ሰው በድምጽህ ገፋፋ:: በእነርሱም ላይ በፈረሰኞችህ በእግረኞችህም ሆነህ ለልብ (አውጅ)። በገንዘቦቻቸዉም በልጆቻቸዉም ተጋራቸው:: የተስፋ ቃልም ግባላቸው።» ሰይጣንም ማታለልን እንጂ ተስፋ ቃልን አይገባላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 65, '65. ንጹህ ባሮቼ ግን በእነርሱ ላይ ፈጽሞ ላንተ ስልጣን የለህም:: ዋስም በጌታህ በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 66, '66. (ሰዎች ሆይ!) ጌታችሁ ያ ከችሮታው ትፈልጉ ዘንድ መርከቦችን በባህር ላይ ለእናንተ የሚነዳላችሁ ነው:: እነሆ እርሱ ለእናንተ አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 67, '67. በባህሩ ውስጥ ሆናችሁ ጉዳት በደረሰባችሁ ጊዜ የምትጠሯቸው አማልክት ሁሉ ይጠፉባችሁና እርሱ አላህ ብቻ ይቀራል። ወደ የብስም በማድረስ ባዳናችሁ ጊዜ እምነትን ትተዋላችሁ:: ሰው ሲባል በጣም ከሓዲ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 68, '68. (ሰዎች ሆይ!) የየብሱን በኩል ምድርን በናንተ መገልበጡን ወይም ጠጠርን የያዘ ንፋስን በእናንተ ላይ መላኩን ከዚያም ለእናንተ ጠባቂ አለማግኘታችሁን አትፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 69, '69. ወይስ ሌላ ጊዜ ወደ እርሱ (ወደ ባህር) የሚመልሳችሁ ወዲያውኑም በእናንተ ላይ ብርቱን ነፋስ የሚልክ፤ በክህደታችሁም ምክንያት የሚያሰምጣችሁ መሆኑን ከዚያም በእኛ ላይ በእርሱ ተከታይነት (ረዳትን) ለእናንተ የማታገኙ መሆናቸሁን አትፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 70, '70. የአደምን ልጆች በእርግጥ ከሌላው ፍጡር አከበርናቸው:: በየብስና በባህርም አሳፈርናቸው:: ከመልካሞችም ሲሳዮችም ሰጠናቸው፤ ከፈጠርናቸው ፍጡራንም በብዙዎቹ ላይ ማብለጥን አበለጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 71, '71. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰዎችን ሁሉ በመሪያቸው የምንጠራበትን ቀን አስታውስ። ያ መጽሐፉንም በቀኙ የተሰጠ ሰው እነዚያ መጽሐፋቸውን ያነባሉ፤ በተምር ፍሬ ስንጥቅ ላይ ያለውን ክር ያክል እንኳን አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 72, '72. በዚህች ዓለም ልበ እውር የሆነ ሰው ሁሉ እርሱ በመጨረሻይቱም ዓለም እውር ነው:: መንገድንም በጣም የተሳሳተ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 73, '73. (መልዕክተኛችን ሙሐመድ ሆይ!) እነሆ ከዚያም ወደ አንተ ካወረድነው ሌላን በእኛ ላይ ትዋሽ ዘንድ ሊፈትኑህ በእርግጥ ተቃረቡ፤ ያን ጊዜም ወዳጅ አድርገው በያዙህ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 74, '74.(መልዕክተኛችን ሙሐመድ ሆይ!) ባላረጋጋንህም ኖሮ ወደ እነርሱ ጥቂትን ዝንባሌ ልትዘነበል በእርግጥ በተቃረብክ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 75, '75. (መልዕክተኛችን ሙሐመድ ሆይ!) ያን ጊዜ የሕይወትን ሆነ የሞትን ድርብ ቅጣት እናቀምስህ ነበር:: ከዚያም ላንተ በእኛ ላይ ረዳትን አታገኝም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 76, '76. ከምድሪቱ (ከዓረብ) ምድር ከእርሷ ያወጡህ ዘንድ ሊያሸብሩህ በእርግጥ ተቃረቡ:: ያን ጊዜም ካንተ በኋላ ጥቂትን ጊዜ እንጂ አይቆዩም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 77, '77. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመልዕክተኞቻችን ካንተ በፊት በእርግጥ እንደ ላክናቸው ሰዎች ልማድ ብጤ ይጠፋ ነበር፤ ለልማዳችንም መለወጥን አታገኝም (አይለወጥም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 78, '78. ሶላትን ከጸሐይ መዘንበል እስከ ሌሊት ጨለማ ድረስ ስገድ:: የጎህንም ሶላት ስገድ:: የጎህ ሶላት መላዕክት የሚገኙበት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 79, '79. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሌሊት ላንተ ተጨማሪ የሆነችን ሶላት በቁርኣን ስገድ:: ጌታህ ምስጉን በሆነ ስፍራ በእርግጥ ያቆምሃልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 80, '80. (መልዕክተኛችን ሙሐመድ ሆይ!) በልም: «ጌታዬ ሆይ! የተወደደን መግባት አስገባኝ፤ የተወደደንም መውጣት አስወጣኝ:: ለእኔም ካንተ ዘንድ የተረዳን ስልጣን አድርግልኝ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 81, '81. (መልዕክተኛችን ሙሐመድ ሆይ!) «እውነት መጣ ውሸትም ተወገደ፤ እነሆ ውሸት ተወጋጅ ነውና።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 82, '82. ከቁርኣን ለአማኞች መድሓኒትና እዝነት የሆነን እናወርዳለን በዳዮችንም ኪሳራን እንጂ ሌላ አይጨምርላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 83, '83. በሰዉም ላይ ጸጋችንን በለገስን ጊዜ ከምስጋና ይዞራል ጎኑንም ከእውነት ያርቃል:: ችግርም በነካው ጊዜ ተስፋ ቆራጭ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 84, '84. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሁሉም በሚመስለው መንገድ ላይ ይሠራል:: ጌታችሁም እርሱ መንገዱ ቀጥተኛ የሆነውን አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 85, '85. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያን ከሩህ ይጠይቁሃል። «ሩህ ከጌታዬ ነገር ነው:: ከእውቀትም ጥቂትን እንጂ አልተሰጣችሁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 86, '86. (መልዕክተኛችን ሙሐመድ ሆይ!) ብንሻ ያንን ወደ አንተ ያወረድነውን በእርግጥ እንወስድብሃለን:: ከዚያም ላንተ በእኛ ላይ በእርሱ ለማስመለስ ተያዢን አታገኝም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 87, '87. ግን ከጌታህ በሆነው እዝነት ጠበቅነው:: ችሮታው ባንተ ላይ ታላቅ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 88, '88. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎችና ጋኔኖች የዚህን ቁርኣን ቢጤ በማምጣት ላይ ቢሰበሰቡና ከፊላቸው ለከፊሉ ረዳት ቢሆኑም እንኳ ብጤውን አያመጡም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 89, '89. በዚህም ቁርኣን ውስጥ ከምሳሌው ሁሉ ለሰዎች በእርግጥ መላልሰን አብራራን:: አብዛኞቹም ሰዎች ክህደትን እንጂ ሌላን እምቢ አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 90, '90. (መልዕክተኛችን ሙሐመድ ሆይ!) አሉም: «ለእኛ ከምድር ምንጭን እስከምታፈልቅልን ድረስ ላንተ አናምንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 91, '91. «ወይም ከዘንባባዎችና ከወይን የሆነች አትክልት ላንተ እስከምትኖርህና በመካከሏም ጅረቶችን በብዛት እስከምታንቧቧ ድረስ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 92, '92. «ወይም እንደምትለው ከሰማይ ቁራጮችን በእኛ ላይ እስከምታወርድ ወይም አላህንና መላዕክትን በግልጽ እስከምታመጣ ድረስ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 93, '93 «ወይም ከወርቅ የሆነ ቤት ላንተ እስከሚኖርህ ወይም በሰማይ እስከምትወጣ፤ ለመውጣትህም በእኛ ላይ የምናነበው የሆነን መጽሐፍ እስከምታወርድልን ድረስ ፈጽሞ አናምንልህም።» አሉ:: «ጌታዬ ጥራት ይገባው:: እኔ መልዕክተኛ (የሆንኩ) ሰው እንጂ ሌላ ነገር ነኝ እንዴ?!» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 94, '94. ሰዎችን መሪ ቁርኣን በመጣላቸው ጊዜ በሱ ከማመን «አላህ ሰውን መልዕክተኛ አድርጎ ላከን?» ማለታቸው ብቻ እንጂ ሌላ አልከለከላቸዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 95, '95. (መልዕክተኛችን ሙሐመድ ሆይ!) በምድር ላይ ተረጋግተው የሚጓዙ መላእክት ቢኖሩ ኑሮ ከሰማይ የመልአክ መልዕክተኛ እናወርድላቸው እንደነበር ንገራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 96, '96. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእኔና በእናንተ መካከል ላለን ልዩነት መስካሪ በአላህ በቃ:: ምክኒያቱም እርሱ ባሮቹን ጠንቅቆ አዋቂና ተመልካች ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 97, '97. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ያቀናው በእርግጥም የተቀና ማለት እርሱው ነው:: እርሱ ያጠመማቸውን ግን ከቅጣቱ የሚያድናቸው ማንም ወዳጅ አታገኝላቸዉም:: የትንሳኤ ቀንም እውር፤ ዲዳና፤ ደንቆሮ አድርገን በፊቶቻቸው እየተጎተቱ እንሰበስባቸዋለን:: መኖሪያቸዉም ገሀነም ናት:: ሀይሏ በደከመ ጊዜም ግለትን እንጨምርላቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 98, '98. ይህ ቅጣት የሚጠብቃቸው ቅጣታቸው ነው:: ምክንያቱም በመልዕክተኞቻችን ክደው «የበሰበሰ አጥንት ከሆንና (ወደ አቧራነት) ከተቀየርን በኋላ እንደ አዲስ እንቀሰቀሳለን?» በማለታቸውም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 99, '99. ያ ሰማያትንና ምድርን የፈጠረ አላህ ብጤያቸውን በመፍጠር ላይ ቻይ መሆኑን በእርሱ ጥርጣሬ የሌለበትንም ጊዜ ለሞትም ለትንሳኤም ለእነርሱ የወሰነ መሆኑን አላወቁምን? በደለኞችም ከክህደት በስተቀር እምቢ አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 100, '100. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ የጌታዬን የችሮታ መካዚኖች ብትይዙ ኖሮ ያን ጊዜ በማውጣታችሁ ማለቋን በመፍራት በጨበጣችሁ ነበር:: ሰው በጣም ንፉግ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 101, '101. ለሙሳ ግልጽ የሆኑን ዘጠኝ ተዓምራት በእርግጥ ሰጠነው:: በመጣቸዉም ጊዜ የኢስራኢልን ልጆች ከፈርዖን እንዲለቀቁ ጠይቅ አልነው:: ፈርዖንም፡- «ሙሳ ሆይ! እኔ የተደገመብህ መሆንህን በእርግጥ እጠረጥርሃለሁ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 102, '102. ሙሳም፡- «እነዚህን ተዓምራት መግሰጫዎች ሲሆኑ የሰማያትና የምድር ጌታ እንጂ ሌላ እንዳላወረዳቸው በእርግጥ አውቀሀል:: እኔም ፈርዖን ሆይ! የምትጠፋ መሆንህን በእርግጥ እጠረጥርሃለሁ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 103, '103. ከምድርም ሊያባርራቸው አሰበ:: እርሱንና ከእርሱ ጋር የነበሩትን ሰዎች ሁሉንም አሰመጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 104, '104. ከእርሱም በኋላ ለኢስራኢል ልጆች «ምድሪቱን ተቀመጡባት:: የኋለኛይቱም ሰዓት ቀጠሮ በመጣ ጊዜ እናንተን የተከማቻችሁ ስትሆኑ እናመጣችኋለን።» አልናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 105, '105. ቁርኣንን በእውነትም አወረድነው:: በእውነትም ወረደ:: (መልዕክተኛችን ሙሐመድ ሆይ!) አንተንም አብሳሪና አስፈራሪ አድርገን እንጂ አልላክንህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 106, '106. (መልዕክተኛችን ሙሐመድ ሆይ!) ቁርኣንንም በሰዎች ላይ ሁነህ በዝግታ ታነበው ዘንድ ከፋፈልነው:: ቀስ በቀስ ማውረድንም አወረድነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 107, '107. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርሱ እመኑ ወይም አትመኑ።» በላቸው:: እነዚያ ከእርሱ በፊት እውቀትን የተሰጡት በእነርሱ ላይ በተነበበ ጊዜ ሰጋጆች ሆነው በሸንጎበቶቻቸው ላይ ይወድቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 108, '108. ይላሉም: «ጌታችን ጥራት ይገባው። እነሆ የጌታችን ተስፋ ተፈጻሚ ነው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 109, '109. እያለቀሱም በአሸንጎበቶቻቸው (በአገጮቻቸው) ላይ ይወድቃሉ:: አላህም ፍርሃትን ይጨምርላቸዋል::{1}', '{1} አዚህ የንባብ ሱጁድ (ሱጁድትላዋ) ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 110, '110. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህን ጥሩ ወይም አር-ረህማንን ጥሩ:: ማንኛውንም ስም ብትጠሩ መልካም ነው:: ለእርሱ ብዙ መልካም ስሞች አሉትና።» በላቸው። በስግደትህም ስታነብ በጣም ድምጽህን አትጩህ:: በእርሷም በጣም ድምጽህን ዝቅ አታድርግ:: በሁለቱ መካከል የሆነ መንገድን ፈልግ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (17, 111, '111. (መልዕክተኛችን ሙሐመድ ሆይ!) «ምስጋና ሁሉ ለዚያ ልጅን ላልያዘው ለእርሱም በንግስናው ተጋሪ ለሌለው ለእርሱም ከውርደት የሚያድነው ወዳጅ ለሌለው ለአላህ ብቻ ይገባው።» በል። እርሱን ማክበርንም አክብረው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 1, '1-ምስጋና ሁሉ ለዚያ መጽሐፉን በውስጡ ቅንጣት መጣመምን ሳያደርግ በባሪያው (በሙሐመድ) ላይ ላወረደው ለአላህ ብቻ ይገባው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 2, '2. ቀጥተኛ ሲሆን ከርሱ ዘንድ የሆነን ብርቱን ቅጣት ሊያስፈራራበት፤ እነዚያንም በጎ ሰሪዎችን ለእነርሱ መልካም ምንዳ ያላቸው መሆኑን ሊያበስርበት (አወረደው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 3, '3. በውስጡም ዘለዓለም የሚቆዩ መሆናቸውን ሊያበስርበት አወረደው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 4, '4. እነዚያንም «አላህ ልጅን ይዟል።» ያሉትን ሊያስፈራራበት (ቁርኣንን አወረደው።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 5, '5.ለእነርሱም ሆነ ለአባቶቻቸው ስለ አላህ ልጅ መኖር ምንም እውቀት የላቸዉም:: ከአፎቻቸው የሚወጣው ቃል ምን አከበደው! ውሸትን እንጂ ሌላን አይናገሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) በዚህም ንግግር በቁርኣን ካላመኑ በፈለጎቻቸው ላይ በቁጭት ነፍስህን አጥፊ ልትሆን ይፈራልሀል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 7, '7.እኛ ማንኛቸው ሥራው ያማረ መሆኑን ልንፈትናቸው በምድር ላይ ያለን ሁሉ የእርሷ ጌጥ አደረግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 8, '8. እኛ በእርሷ ላይ ያለውን ሁሉ በመጨረሻ ቡቃያ የሌለበት ምልጥ አፈር አድራጊዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 9, '9-(መልዕክተኛችን ሙሐመድ ሆይ!) የዋሻውና የሰሌዳው ባለቤቶች ከተዓምራታችን ሲሆኑ ግሩም መሆናቸውን አሰብክን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) ወጣቶቹ ወደ ዋሻው በተጠጉና: «ጌታችን ሆይ! ካንተ ዘንድ እዝነትን ስጠን:: ለእኛም ከነገራችን ቅንን ነገር አዘጋጅልን።» ባሉ ጊዜ (የሆነውን ታሪክ አስታውስ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 11, '11. በዋሻዉም ውስጥ የተቆጠሩን ዓመታት በጆሮዎቻቸው ላይ መታንባቸው (አስተኛናቸው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 12, '12.ከዚያም ከሁለቱ ክፍሎች ለቆዩት ጊዜ ልክ ያረጋገጠው ማንኛው መሆኑን ልናውቅ ከተኙበት አስነሳናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ ወሬያቸውን ባንተ ላይ በእውነት እንተርክልሃለን:: እነርሱ በጌታቸው በትክክል ያመኑ ወጣቶች ናቸው:: ወደ ቀናው መንገድ መመራትንም ጨመርንላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 14, '14. በንጉሳቸው ፊት በቆሙና እንዲህም ባሉ ጊዜ ልቦቻቸውን በእምነት አጠነከርን: «ጌታችን የሰማያትና የምድር ጌታ ነው:: ከእርሱ ሌላ አምላክን አንገዛም:: ከእሱ ሌላን ብናመልክማ ወሰን ያለፈን ንግግር በእርግጥ ተናገርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 15, '15. «እነዚህ ህዝቦቻችን ከእርሱ ሌላ አማልክትን ያዙ:: እውነተኞች ከሆኑ በእነርሱ ላይ ግልጽ ማስረጃን ለምን አያመጡም? በአላህ ላይ ውሸትን ከሚቀጣጥፍ ይበልጥ በዳይ ማን ነው?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 16, '16. «እነርሱንና ያንን ከአላህ ሌላ የሚገዙትን በተለያችሁ ጊዜ ወደ ዋሻው ተጠጉ። ጌታችሁ ለእናንተ ከችሮታው ይዘረጋላችኋልና፤ ከነገራችሁም ለእናንተ መጠቃቀሚያ ያዘጋጅላችኋልና።» (ተባባሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 17, '17.ጸሐይዋ በወጣች ጊዜ ከዋሻቸው ወደ ቀኝ ጎን ስታዘነብል ታያታለህ:: በገባችም ጊዜ ከሰፊው ዋሻ ውስጥ እያሉ በግራ በኩል ትተዋቸዋለች:: ይህ ከአላህ ተዓምራት አንዱ ነው:: አላህ ያቀናው በእርግጥም የተቀናው እርሱ ብቻ ነው:: እርሱ ያጠመመውን ደግሞ ቅኑን መንገድ የሚመራው ረዳት ማንንም አታገኝለትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 18, '18. እነርሱ በጥልቅ እንቅልፍ ውስጥ እያሉ የነቁ ይመስሉሃል:: ወደቀኝና ወደ ግራ ጎናቸው እናገላብጣቸዋለን:: ውሻቸዉም በዋሻቸው በር ላይ የፊት እግሩን ዘርግቷል:: ብታያቸው ኖሮ ከእነርሱ በእርግጥ የምትሸሽ ኾነህ በዞርክ ነበር:: በፍርሀትም በተሞላህ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 19, '19. ልክ እንዳስተኛናቸውም ሁሉ በመካከላቸው እንዲጠያየቁም ቀሰቀስናቸው:: ከእነርሱ አንድ ተናጋሪ «ምን ያህል ቆያችሁ አለ?» ሌሎቹም «አንድን ቀን ወይም የቀንን ከፊል ቆየን።» አሉ። ተባባሉም: «ጌታችሁ የቆያችሁትን ጊዜ ልክ አዋቂ ነው:: ከዚህም ገንዘባችሁ ጋር አንዳችሁን ወደ ከተማይቱ ላኩ:: ከምግብ የትኛዋ ንጹህ መሆኗንም ይመልከት:: (ከንጹሑ) ምግብን ያምጣላችሁ:: ቀስም ይበል:: በእናንተም አንድንም ሰው አያሳውቅ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 20, '20. «እነርሱ በእናንተ ላይ ቢዘልቁ ይቀጠቅጧችኋል:: ወይም ወደ ሃይማኖታቸው ይመልሷችኋል፤ ያን ጊዜም በፍጹም ፍላጎታችሁን አታገኙም።» ተባባሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 21, '21. ልክ እንደዚሁም የአላህ ቀጠሮ እርግጠኛ መሆኑን ሰዓቲቱም በእርሷ ጥርጣሬ የሌለ መሆኑን ያውቁ ዘንድ በእነርሱ ላይ ሰዎችን አሳወቅን:: አማኞቹና ከሓዲያን ነገራቸውን በመካከላቸው ሲከራከሩ የሆነውን አስታውስ:: ከሓዲያን «በእነርሱ ላይ ግንብን ገንቡ።» አሉ:: ጌታቸው ለእነርሱ ይበልጥ አዋቂ ነው:: እነዚያ በነገራቸው ላይ ያሸነፉት ግን «በእነርሱ ላይ በእርግጥ መስጊድን እንሰራለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 22, '22. (መልዕክተኛችን ሙሐመድ ሆይ!) (ስለ እነርሱ የተወሰኑ ቡድኖች በጥርጣሬ) «ሶስት ናቸው አራተኛው ውሻቸው ነው።» ይላሉ:: (ሌሎች ቡድኖች) «አምስት ናቸው ስድስተኛው ውሻቸው ነው።» ይላሉ። በሩቅ ወርዋሪዎች ሆነው (ባላወቁት አለም) ሲገምቱ። (ሶስተኛው ቡድን ደግሞ) «ሰባት ናቸው ስምንተኛቸው ውሻቸው ነዉ።» ይላሉ:: «ጌታዬ ብቻ ቁጥራቸውን አዋቂ ነው:: ጥቂት ሰው እንጂ አያውቃቸዉም።» በላቸው:: እናም በእነርሱ ነገር ግልጽን ክርክር እንጂ ጠልቀህ አትከራከር:: በእነርሱም ጉዳይ ከመጽሐፉ ሰዎች አንድንም አትጠይቅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 23, '23 ለማንኛዉም ነገር «እኔ ይህንን ነገ ሠሪ ነኝ።» አትበል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 24, '24. «አላህ ቢሻ እሠራዋለሁ።» ብትል እንጂ። በረሳህ ጊዜም ጌታህን አውሳ። «ጌታዬም ከዚህ ይበልጥ ለቀጥታ የቀረበን ሊመራኝ ይከጀላል» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 25, '25. በዋሻቸዉም ውስጥ ሶስት መቶ ዓመታትን ቆዩ:: ዘጠኝ አመታትንም ጨመሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 26, '26.(መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ብቻ የቆዩትን ልክ በትክክል አዋቂ ነው። የሰማያትና የምድር ሚስጢር የእሱ ብቻ ነዉ። እርሱ (አላህ) ሁሉን ተመልካች ሁሉን ሰሚ መሆኑ ይግረምህ። ለእነርሱ ከእርሱ በስተቀር ምንም ወዳጅ የላቸዉም:: በፍርዱም አንድንም አያጋራም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 27, '27.(መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህ መጽሀፍ ወደ አንተ የተወረደውን አንብብ:: ለቃሎቹ ለዋጭ የላቸዉም:: ከርሱም በስተቀር መጠጊያን በፍጹም አታገኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) ነፍስህንም ከእነዚያ ጌታቸውን ፊቱን የሚሹ ሆነው በጥዋትና በማታ ከሚገዙት ጋር አስታግስ:: የቅርቢቱንም ህይወት ሽልማት የምትሻ ሆነህ አይኖችህ ከእነርሱ ወደ ሌላ አይለፉ:: ያ ልቡን እኛን ከማስታወስ ያዘነጋነውንና የግል ፍላጎቱን የተከተለውን ነገሩ ሁሉ ወሰን ማለፍ የሆነውን ሰው አትታዘዝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰዎች ሆይ! እውነቱ ሁሉ ከጌታችሁ ነው:: ስለዚህ የፈለገም ሰው በእውነቱ ይመን:: የፈለገም ሰው ይካድ።» በላቸው:: እኛ ለበደለኛ ከሓዲያን አጥሯ በእነርሱ ላይ የከበበ የሆነችውን እሳት አዘጋጅተናል:: ከጥም ለመዳን እርዳታን ቢፈልጉ እንደ ዘይት ዝቃጭ ባለ ፊቶችን በሚጠብስ ውሃ ይረዳሉ:: መጠጡም ከፋ፤ መደገፊያይቱም ምንኛ አስከፋች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 30, '30. እነዚያ በአላህ ያመኑና መልካም ሥራዎችን የሠሩ እኛ ሥራ ያሳመረን ምንዳ አናጠፋም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 31, '31.እነዚያ ለእነርሱ የመኖሪያ ገነቶች ከስሮቻቸው ወንዞች የሚፈሱባቸው አሏቸው:: በእርሷ ውስጥ ከወርቅ የሆኑን አምባሮች ይሸለማሉ:: ከቀጭን ሀርና ከወፍራም ሀርም አረንጓዴ ልብሶችን ይለብሳሉ:: በውስጧ በባለ አጎበር አልጋዎች ላይ የተደገፉ ሆነው ይቀመጣሉ:: እነዚህ ሰዎች ምንዳቸው ምን ያምር! መኖሪያቸው ገነትም ምንኛ አማረች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 32, '32. (መልዕክተኛችን ሙሐመድ ሆይ!) ለከሓዲያን የሁለትን ሰዎችን ምሳሌ ግለጽላቸው:: ለአንደኛው ከሓዲ ሁለት የወይን አትክልቶች አደረግንለት። በዘንባባም ከበብናቸው። በመካከላቸውም አዝመራን አደረግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 33, '33. ሁለቱም አትክልቶች ሰብላቸውን ሰጡ፤ ከርሱም ምንም አላጎደሉም። በመካከላቸዉም ወንዝን አፈሰስን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 34, '34.ለእርሱ ከአትክልቶቹ ሌላ ፍሬያማ ሀብት ነበረው:: ለአማኙ ጓደኛዉም የሚወዳደረው ሲሆን «እኔ ካንተ በገንዘብ ይበልጥ የበዛሁ በወገንም ይበልጥ የበረታሁ ነኝ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 35, '35. እርሱም ነፍሱንም በዳይ ሆኖ ወደ አትክልቱ ገባ። (እንዲህም) አለ: «ይህች አትክልት መቸም ትጠፋለች ብዬ አልጠረጥርም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 36, '36. «ሰዓቲቱንም ትከሰታለች ብዬ አልጠረጥርም፤ እንደምትለው ወደ ጌታዬም ብመለስ ከእርሷ የበለጠን መመለሻ በእርግጥ አገኛለሁ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 37, '37. አማኙ ጓደኛውም ለእርሱ የሚመላለሰው ሲሆን (እንዲህ) አለው: «በዚያ ከአፈር ከዚያም ከፍትወት ጠብታ በፈጠረህ ከዚያም ሰው ባደረገህ ሃያል አምላክ ካድክን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 38, '38. «እኔ ግን አላህ ጌታዬ ነው እላለሁ። በጌታዬም አንድንም አላጋራም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 39, '39. «እኔን በገንዘብም ሆነ በልጅ ካንተ በጣም ያነስኩ ሆኜ ብታየኝም ወደ አትክልትህ በገባህ ጊዜ ‹አላህ የሻው ሆኗል። በአላህ ቢሆን እንጂ ብልሃትም የለም› አትልም ኖሯልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 40, '40. «ጌታዬ ከአትክልትህ የበለጠን ሊሰጠኝ በአትክልትህ ላይ ደግሞ በሰማይ መብረቆችን ሊልክባትና የምታንዳልጥ ምልጥ ምድር ልትሆንም ይቻላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 41, '41. «ወይም ውሀው ሰራጊ ሊሆንብህ ይችላል። ያን ጊዜ እርሱን መፈለጉን ፈጽሞ አትችልም።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 42, '42. ሀብቱም ተጠፋ:: እርሷ በዳሶችዋ ላይ የወደቀች ሆና በእርሷ ባወጣው ገንዘብ ላይ የተጸጸተ መዳፎቹን የሚያገላብጥና «ወይ ጸጸቴ! በጌታዬ አንድንም ባላጋራሁ።» የሚል ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 43, '43.እርሱም ከአላህ ሌላ የሚረዱት ቡድኖች አልነበሩትም:: ተረጂም አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 44, '44.እዚያ ዘንድ በትንሳኤ ቀን ስልጣኑ እውነተኛ ለሆነው ለአላህ ብቻ ነው:: እርሱ በመመንዳት የበለጠ ፍጻሜንም በማሳመር የበለጠ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነርሱም የቅርቢቱን ህይወት ምሳሌ አውሳላቸው:: እርሷ ከሰማይ እንዳወረድነው ውሃ በእርሱም የምድር ቡቃያ እንደተቀላቀለበት፤ ከተዋበ በኋላም ደርቆ ንፋሶች የሚያበኑት ደቃቅ እንደሆነ ብጤ ናት:: አላህ በነገሩ ሁሉ ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 46, '46. ገንዘብና ልጆች የቅርቢቱ ህይወት ጌጦች ብቻ ናቸው:: መልካም ቀሪ ሥራዎች ግን በጌታህ ዘንድ በምንዳ በላጭ ናቸው:: በተስፋም በላጭ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) ተራራዎችን የምናስኬድበትን ቀን አስታውስ:: ምድርንም ግልጽ ሆና ታያታለህ:: እንሰበስባቸዋለንም:: ከእነርሱ አንድንም አንተዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 48, '48. የተሰለፉ ሆነው በጌታህ ላይ ይቀርባሉ:: ይባላሉም «በመጀመሪያ ጊዜ እንደፈጠርናችሁ በእርግጥ ወደ እኛ መጣችሁ:: በእውነቱ ለእናንተ የመቀስቀሻ ጊዜን አናደርግም መስሏችሁ ነበር።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 49, '49 ለሰው ሁሉ መጽሐፉ ይቀርባል:: ወዲያዉም ከሓዲያንን በውስጡ ካለው ነገር ፈሪዎች ሆነው ታያቸዋለህ። «ዋ ጥፋታችን! ይህ መጽሐፍ ከሥራ ትንሽንም ትልቅንም የቆጠራት ቢሆን እንጂ የማይተወው ምን አለው?» ይላሉ:: የሠሩትንም ነገር ሁሉ ቅርብ ሆኖ ያገኙታል:: ጌታህም አንድንም አይበድልም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) ለመላዕክት «ለአደም ስገዱ።» ባልናቸው ጊዜ (የሆነውን አስታውስ):: ወዲያዉም ዲያብሎስ ብቻ ሲቀር ሁሉም ሰገዱ:: ከአጋንንት ጎሳ ነበርና:: ከጌታዉም ትዕዛዝ ወጣ:: እርሱንና ዘሮቹን እነርሱም ለእናንተ ጠላቶች ሲሆኑ ከኔ ሌላ ረዳቶች ታደርጋላችሁን? ለበዳዮች ልዋጭነቱ ከፋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 51, '51.የሰማያትና የምድርም አፈጣጠር አላሰየኋቸዉም:: የነፍሶቻቸውንም አፈጣጠር እንደዚሁ አሳሳቾችንም ረዳቶች አድርጌ የምይዝ አይደለሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያንም አምላክ የምትሏቸውን ተጋሪዎቼን ጥሩ።» የሚልበትን ቀን አስታውስ:: ይጠሯቸዋልም። ግን አይመልሱላቸዉም:: በመካከላቸዉም መጥፊያን ስፍራ ገሀነምንም አደረግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 53, '53. ከሓዲያንም እሳትን ያያሉ፤ እነርሱም በውስጧ ወዳቂዎች መሆናቸውን ያረጋግጣሉ:: ከእርሷም መሸሻን አያገኙም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 54, '54. በዚህም ቁርኣን ውስጥ ከየምሳሌው ሁሉ ለሰዎች መላልሰን ገለጽን፤ ሰዉም ከነገሩ ሁሉ ይበልጥ ክርክረ ብዙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 55, '55.ሰዎችንም መመሪያ በመጣላችሁ ጊዜ ከማመንና ጌታቸውንም ምህረትን ከመለመን የከለከላቸው የመጀመሪያዎቹ ህዝቦች ልማድ መጥፋት ልትመጣባቸው ወይም ቅጣቱ በየዓይነቱ ሊመጣባቸው መጠባበቅ ብቻ እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 56, '56. መልዕክተኞችንም አብሳሪዎችና አስፈራሪዎች ሆነው እንጂ አንልክም:: እነዚያ የካዱትም በውሸት እውነቱን በእሱ ሊያበላሹ ይከራከራሉ:: አንቀፆቼንና በእርሱ የተስፈራሩበትንም ነገር ማላገጫ አድርገው ያዙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 57, '57.በጌታዉም አናቅጽ ከተገሰጸና ከእርሷም ከዞረ፤ ሁለት እጆቹም ያስቀደሙትን ነገር ከረሳቸዉም ይበልጥ በዳይ ማን ነው? እኛ በልቦቻቸው ላይ እንዳያውቁት ሽፋኖችን፤ በጆሮዎቻቸዉም ውስጥ ድንቁርናን አደረግን። (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ መመራትም ብትጠራቸው ያን ጊዜ ፈጽሞ አይመሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 58, '58. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም በጣም መሀሪው የእዝነት ባለቤት ነው:: በሠሩት ሥራ ቢይዛቸው ኖሮ ቅጣቱን ለእነርሱ ባስቸኮለባቸው ነበር:: ግን ለእነርሱ ከእርሱ ሌላ መጠጊያን ፈጽሞ የማያገኙበት ቀጠሮ አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 59, '59.እነዚህ ከተሞችም በበደሉ ጊዜ አጠፋናቸው፤ ለመጥፊያቸዉም የተወሰነ ጊዜ አደረግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 60, '60. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳ ለወጣቱ «የሁለቱን ባህሮች መገናኛ እስከምደርስ ወይም ብዙን ጊዜ እስከምሄድ ድረስ ከመጓዝ አልወገድም።» ያለውን (አስታውስ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 61, '61. የሁለቱን ባህር መገናኛ በደረሱም ጊዜ ዓሳቸውን ረሱ፤ ዓሳውም መንገዱን በባህር ውስጥ ቀዳዳ አድርጎ ያዘ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 62, '62. ባለፉም ጊዜ ለወጣቱ «ምሳችንን ስጠን ከዚህ ጉዟችን በእርግጥ ድካምን አግኝተናልና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 63, '63. «አየህን? ወደ ቋጥኟ በተጠጋን ጊዜ እኔ ዐሳውን ረሳሁ፤ ሰይጣን እንጂ ሌላ አላስረሳኝም፤ በባህሩም ውስጥ መንገዱን አስደናቂ መንገድ አድርጎ ያዘ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 64, '64. ሙሳም «ይህ እኮ እንፈልገው የነበረው ነው።» አለው። ከዚያ በኮቴዎቻቸው (ዱካቸው) ላይ እየተከተሉ ተመለሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 65, '65.ከባሮቻችንም ከእኛ ዘንድ ችሮታን የሰጠነውን ከኛም ዘንድ እውቀትን ያስተማርነውን አንድን ባሪያችንን አገኙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 66, '66. ሙሳ «ለእርሱ ከተማርከው ነገር ቀጥተኛን እውቀት ታስተምረኝ ዘንድ ልከተልህ?» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 67, '67. ባሪያዉም አለ: «አንተ ከእኔ ጋር መታገስን በጭራሽ አትችልም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 68, '68. «በእውቀት ባልደረስክበት ነገር ላይስ እንዴት ትታገሳለህ?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 69, '69. ሙሳም «አላህ የፈለገ እንደሆነ ታጋሽና ላንተ ትዕዛዝን የማልጥስ ሆኜ ታገኘኛለህ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 70, '70. «ብትከተለኝም ላንተ ከእርሱ ማውሳትን እስከምጀምርልህ ድረስ ከምንም ነገር እንዳትጠይቀኝ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 71, '71. ሄዱም:: በመርከቢቱም በተሳፈሩ ጊዜ መርከቢቱን ቀደዳት። «ባለቤቶችዋን ልታሰምጥ ቀደድካትን? ትልቅን ጥፋት በእርግጥ ሠራህ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 72, '72. «አንተ ከእኔ ጋር ትዕግስትን ፈጽሞ አትችልም አላልኩምን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 73, '73. «በረሳሁት ነገር አትያዝብኝ:: ከነገሬም ችግርን አታሸክመኝ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 74, '74. ወርደው ተጓዙም ወጣቱንም ልጅ ባገኘውና በገደለው ጊዜ «ነፍስን ያልገደለችን ንጹህን ነፍስ ገደልክን? በእርግጥ መጥፎን ነገር ሰራህ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 75, '75. «አንተ ከእኔ ጋር ትዕግስትን ፈጽሞ አትችልም አላልኩህምን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 76, '76. «ከአሁኒቱ በኋላ ከምንም ነገር ብጠይቅህ አትጎዳኘኝ:: ከእኔ የይቅርታን መጨረሻ በእርግጥ ደርሰሃል።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 77, '77. ሄዱም። ወደ አንዲት ከተማ ሰዎች ዘንድ ደረሱ ከነዋሪዎች ምግብን ጠየቁ:: (እንደ እንግዳ) ማስተናገዳቸዉንም እምቢ አሉ:: በእርሷም ውስጥ ለመውደቅ የተቃረበን የቤት ግድግዳ አገኙ:: አቆመው:: ሙሳም «ብትፈልግ ኖሮ በእርሱ ላይ ዋጋን በተቀበልክ ነበር።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 78, '78. አለም: «ይህ በእኔና ባንተ መካከል መለያያችን ነው። በእርሱ ላይ መታገስን ያልቻለክበትን ፍቺ እነግርሃለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 79, '79. «መርከቢቱማ በባህር ውስጥ ለሚሠሩ ምስኪኖች ነበረች:: ከኋላቸው መርከብን ሁሉ በቅሚያ የሚወስድ ክፉ ንጉስ ነበረና እንዳይቀማቸው ላስነውራት ፈልጌ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 80, '80. «ያ ወጣቱም ልጅ ወላጆቹ አማኞች ነበሩ:: ቢያድግ በትዕቢትና በክህደት ወላጆቹን የሚያስገድዳቸው መሆኑን ፈራን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 81, '81. «ጌታቸው በንጹሕነት ከእርሱ በላጭን፤ በእዝነትም ከእርሱ በጣም ቀራቢን ልጅ ሊለውጥላቸው ፈለግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 82, '82. «ግድግዳዉም በከተማይቱ ውስጥ የነበሩ የሁለት የቲሞች ወጣቶች ነበር:: በስሩም ለእነርሱ የሆነ የተቀበረ ድልብ ነበረና አባታቸዉም መልካም ሰው ነበር:: ጌታህም ለአካለ መጠን እንዲደርሱና ከጌታህ ችሮታ ድልባቸውን እንዲያወጡ ፈቀደ:: በፈቃዴም አልሠራሁትም:: ይህ ያ በእርሱ ላይ መታገስን ያልቻልከው ነገር ፍቹ ነው።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ!) ስለ ዙልቀርነይንም ይጠይቁሀል:: «በእናንተ ላይ ከእርሱ ወሬን (ማስታወሻን) አነባለሁ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 84, '84.እኛ እርሱን በምድር ላይ አስመቸነው:: በነገሩም ሁሉ መዳረሻ መንገድን ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 85, '85. መንገድንም (ወደ ምዕራብ) ተከተለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 86, '86. ወደ ጸሐይ መግቢያም በደረሰ ጊዜ ጥቁር ጭቃማ ምንጭ ውስጥ ስትጠልቅ አገኛት:: በአጠገቧም ህዝቦችን አገኘ:: «ዙልቀርነይን ሆይ! ወይም በመግደል ትቀጣለህ፤ ወይም በእነርሱ መልካም ነገርን ትሠራለህ።» አልነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 87, '87. (እርሱም) አለ: «የበደለውንማ ወደፊት እንቀጣዋለን ከዚያ ወደ ጌታው ይመለሳል:: ብርቱንም ቅጣት ይቀጣዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 88, '88. «ያመነና መልካምን ሥራ የሰራ ለእርሱ ከምንዳ በኩል መልካሚቱ ገነት አለችው:: ለእርሱም ከትዕዛዛችን ገርን ነገር እናዘዋለን።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 89, '89-. ከዚያ መንገድን (ወደ ምስራቅ) ቀጠለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 90, '90.ወደ ጸሐይ መውጫ በደረሰም ጊዜ ለእነርሱ ከበታቹ መከለያን ባላደረግንላቸው ህዝቦች ላይ ስትወጣ አገኛት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 91, '91.ነገሩ ልክ እንደዚሁ ነው:: እርሱም ዘንድ ባለው ነገር ሁሉ በእርግጥ በእውቀት ከበብን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 92, '92. ከዚያ (ወደ ሰሜን አቅጣጫ) መንገድን ቀጠለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 93, '93.በሁለቱ ጋራዎችም መካከል በደረሰ ጊዜ በአቅራቢያቸው ንግግርን ለማወቅ የማይቃረቡ ህዝቦችን አገኘ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 94, '94. «ዙልቀርነይን ሆይ! የዕጁጅና መዕጁጅ በምድር ላይ አበላሾች ናቸው። ግብር እናድርግልህና በእኛና በእነርሱ መካከል ግድብን ታደርግልን?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 95, '95. (እርሱም) አለ: «ጌታዬ ያስመቸብኝ ሀብት ከናንተ ግብር በላጭ ነው:: እናም በጉልበት ብቻ እገዙኝ:: በእናንተና በእነርሱ መካከል ብርቱን ግድብ አደርጋለሁና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 96, '96. «የብረትን ታላላቅ ቁራጮች ስጡኝ።» አላቸው:: በሁለቱ ኮረብታዎች ጫፍ መካከልም ባስተካከለ ጊዜ «አናፉ» አላቸው። ብረቱን እሳትም ባደረገው ጊዜም: «የቀለጠውን ነሀስ ስጡኝ በእርሱ ላይ አፈስበታለሁና።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 97, '97. የእጁጅና መእጁጅ ይህን መከላከያ ሊወጡት አልቻሉም:: ለእርሱ መሸንቆሩንም እንኳን አልቻሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 98, '98. «ይህ ግድብ ከጌታዬ ችሮታዎች ነው:: የጌታዬ ቀጠሮ በመጣ ጊዜ እንኩትኩት ያደርገዋል:: የጌታዬም ቀጠሮ የተረጋገጠ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 99, '99. በዚያን ቀን ከፊላቸውን በከፊሉ የሚቀላቀሉ አድርገን እንተዋቸዋለን:: በቀንዱም ይነፋል:: መሰብሰብንም እንሰበስባቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 100, '100. ገሀነምንም በዚያ ቀን ለከሓዲያን በጣም ማቅረብን እናቀርባታለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 101, '101.ለእነዚያ አይኖቻቸው ከግሳጼዬ በሽፋን ውስጥ ለነበሩትና መስማትንም የማይችሉ ለነበሩት እናቀርባታለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 102, '102. እነዚያ በእኔ የካዱት ባሮቼን ከኔ ሌላ አማልክት አድርገው መያዛቸውን የማያስቆጣኝ አድርገው አሰቡን? እኛ ገሀነምን ለከሓዲያን መስተንግዶ አዘጋጅተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 103, '103. (መልዕክተኛችን ሙሐመድ ሆይ!) (እንዲህ) በላቸው: «በሥራዎች በጣም ከሳሪዎቹን እንንገራችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 104, '104. «እነዚያ እነርሱ ሥራን የሚያሳምሩ የሚመስላቸው ሲሆኑ በቅርቢቱ ህይወት ሥራቸው የጠፋባቸው ናቸው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 105, '105. እነዚያ እነርሱ በጌታቸው ተዓምራትና መገናኘት የካዱ ናቸው። ሥራዎቻቸዉም ተበላሸ:: ለእነርሱም በትንሳኤ ቀን ሚዛንን አናቆምላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 106, '106. ነገሩ ይህ ነው:: በክህደታቸው፣ አንቀፆቼንና መልዕክተኞቼንም መሳለቂያ አድርገው በመያዛቸው ፍዳቸው ገሀነም ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 107, '107. እነዚያ በአላህ ያመኑና መልካም ሥራዎችን የሠሩ ፊርደውስ የተባለው የገነት ክፍል ለእነርሱ መስፈሪያ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 108, '108. በእርሷ ውስጥ ዘውታሪዎች፤ ከእርሷም መዛወርን የማይፈልጉ ሲሆኑ መስፈሪያቸው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 109, '109. (መልዕክተኛችን ሙሐመድ ሆይ!) «ባህሩ ለጌታዬ ቃላት መጻፊያ ቀለሞችን ቢሆን ኖሮ ብጤውን ጭማሪ ብናመጣም እንኳ የጌታዬ ቃላት ከማለቋ በፊት ባህሩ ባለቀ ነበር።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (18, 110, '110. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ መሰላችሁ ሰው ነኝ አምላካችሁ አንድ አምላክ ብቻ ነው የሚል መልዕክት ወደ እኔ የሚወረድልኝ:: እናም ከጌታው ጋር መገናኘት የሚፈልግ ሰው ሁሉ መልካም ሥራን ይሥራ:: በጌታዉም መገዛት ላይ አንድንም አያጋራ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 1, '1. ካፍ፤ ሃ፤ ያ፤ ዐይን፤ ሷድ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 2, '2. ይህ ጌታህ ባርያውን ዘከሪያን በችሮታው ያወሳበት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 3, '3. ጌታውን የሚስጢርን ጥሪ በተጣራ ጊዜ የሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 4, '4. (እንዲህም) አለ: «ጌታዬ ሆይ! እኔ አጥንቴም ደከመ:: ራሴም በሽበት ተንቀለቀለ። ጌታዬ ሆይ! አንተንም በመለመኔ፤ ምንጊዜም ዕድለ ቢስ እልሆንኩም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 5, '5. «እኔም ከበኋላዬ (ከሞትኩ በኋላ) ዘመዶቼን (ከእምነት እንዳይወጡ) ፈራሁ:: ሚስቴም መካን ነበረች:: ስለዚህ ካንተ ዘንድ ለእኔ ልጅን ስጠኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 6, '6. «የሚወርሰኝ ከየዕቁብ ቤተሰቦችም የእምነትን ሃላፊነት የሚወርስን ልጅ ስጠኝ:: ጌታዬ ሆይ! ተወዳጅም አድርገው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 7, '7. «ዘከሪያ ሆይ! እኛ ስሙ የሕያ በሆነና ከዚያ በፊት ሞክሼን ባላደረግንለት ወንድ ልጅ እናበስርሃለን።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 8, '8. «ጌታዬ ሆይ! ሚስቴ መካን እኔም ከእርጅና የተነሳ ድርቀትን የደረስኩ ስሆን እንዴት ልጅ ይኖረኛል?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 9, '9. (ጅብሪልም) አለ: «ነገሩ ልክ እንደዚሁ ነው። ጌታህ ‹ከዚህ በፊት ምንም ያልነበርከውን የፈጠርኩህ ስሆን እርሱ በእኔ ላይ ቀላል ነው።› ብሏል።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 10, '10. እርሱም «ጌታዬ ሆይ! እንግዲያውስ ምልክት አድርግልኝ።» አለ። «ምልክትህ (ጤናማ ሆነህ ሳለህ) ሶስት ሌሊት ከነቀናቸው ሰዎችን ማነጋገር አለመቻልህ ነው።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 11, '11. እርሱም ከምኩራቡ ወደ ህዝቦቹ ወጣ:: ጧትና ማታ ጌታችሁን አውሱ አጥሩትም በማለትም ወደ እነርሱ ጠቀሰ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 12, '12. «የሕያ ሆይ! መጽሐፉን በጥብቅ ያዝ።» አልነው:: ጥበብንም በሕጻንነቱ ሰጠነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 13, '13. ከእኛም የሆነን ርህራሄና ንጽህናንም (ሰጠነው):: ጥንቁቅም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 14, '14. ለወላጆቹም በጎ ሠሪ ነበር:: ትዕቢተኛና አመጸኛም አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 15, '15. በተወለደበት ቀንና በሚሞትበት ቀን ህያው ሆኖ በሚነሳበትም ቀን ሰላም በእሱ ላይ ይሁን ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 16, '16. (መልዕክተኛችን ሙሐመድ ሆይ!) መርየም ከቤተሰቧ ወደ ምስራቃዊ ስፍራ በተለየች ጊዜ የሆነውን ታሪኳን በመጽሐፉ ውስጥ አውሳ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 17, '17. ከእነርሱም መጋረጃን አደረገች:: መንፈሳችንንም (መልዐኩ ጂብሪልን) ወደ እርሷ ላክን:: ለእርሷም ትክክለኛ ሰው ሆኖ ተመሰለላት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 18, '18. «ካንተ በአር-ረህማን እጠበቃለሁ። ጌታህን ፈሪ ከሆንክ (አትቅረበኝ)።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 19, '19. «እኔ ንጹሕ የሆነን ልጅ ላንቺ ልሰጥ የመጣሁ የጌታሽ መልዕክተኛ ነኝ።» አላት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 20, '20. «በጋብቻ አንድም ሰው ያልነካኝ ሆኜ አመንዝራ ዝሙትኛ ሳልሆን ለእኔ እንዴት ልጅ ይኖረኛል!» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 21, '21. (መልአኩም) «ነገሩ ልክ እንደዚሁ ነው የሚፈጸመው። ጌታሽ ‹እርሱ በእኔ ላይ ገር ነው:: ለሰዎችም ተዓምር ከእኛም ችሮታ ልናደርገው ይህንን ሰራን፤ ነገሩ የተወሰነም ነው።› ብሏል።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 22, '22. ወዲያውኑም አረገዘችው:: እርሱንም በሆድዋ ይዛው ወደ ሩቅ ስፍራ ገለል አለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 23, '23. ምጡ ወደ ዘንባባይቱ ግንድ አስጠጋት:: እርሷም «ወይኔ! ምነው ከዚህ በፊት በሞትኩና የተረሳሁ በሆንኩ።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 24, '24. ከበታቿም እንዲህ ሲል ጠራት: «አትዘኝ። ጌታሽ ከበታችሽ ትንሽን ወንዝ በእርግጥ አድርጓልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 25, '25. «የዘምባባይቱን ግንድ ወደ አንቺ ወዝውዢው:: በአንቺ ላይ የበሰለን የተምር እሸት ያረግፍልሻልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 26, '26. «ብይ፤ ጠጭም። ተደሰችም ከሰዎች አንድንም ብታይ እኔ ለአዛኙ አምላክ ዝምታን ተስያለሁ:: እናም ዛሬ ማንንም ሰው በፍጹም አላነጋግርም በይ።» አላት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 27, '27. እርሱን ተሸክማው ወደ ዘመዶቿ መጣች (እንዲህም) አሏት: «መርየም ሆይ! ከባድ ነገርን በእርግጥ ፈጸምሽ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 28, '28. «አንቺ የሃሩን እህት ሆይ! አባትሽ መጥፎ ሰው አልነበረም:: እናትሽም አመንዝራ ዝሙተኛ አልነበረችም።» አሏት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 29, '29. እርሷም ወደ ህፃኑ አመለከተች:: እነርሱም «በአንቀልባ ያለን ህፃን እንዴት እናናግራለን?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 30, '30. ህፃኑም አለ: «እኔ የአላህ አገልጋይ ነኝ፤ መጽሐፍን ሰጥቶኛል። ነብይም አድርጎኛል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 31, '31. «በየትም ስፍራ ብሆን የተባረኩኝ አድርጎኛል። በህይወትም እስካለሁ ሶላትንና ዘካን አዞኛል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 32, '32. «ለእናቴም ታዛዥ አድርጎኛል:: ትዕቢተኛ እድለቢስ አላደረገኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 33, '33. «በተወለድሁበት ቀን በምሞትበት ቀንና ሕያው ሆኜ በምቀሰቀስበትም ቀን ሰላም በእኔ ላይ ይስፈን።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 34, '34. የመርየም ልጅ ዒሳ ይሀው ነው፤ ያ በእርሱ የሚጠራጠሩበት እውነተኛ ቃል ይህ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 35, '35. ለአላህ ልጅን መያዝ አይገባዉም:: ከጉድለት ሁሉ ጠራ:: አንድን ነገር በወሰነ ጊዜ ለእርሱ የሚለው «ሁን» ብቻ ነው:: ወዲያዉም ይሆናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 36, '36. ዒሳ ለህዝቦቹ «አላህ የእኔም ጌታዬ የእናንተም ጌታችሁ ነውና ተገዙት:: ይህ ቀጥተኛው መንገድ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 37, '37. ከመካከላቸዉም አንጃዎች በእርሱ ነገር ላይ ተለያዩ:: ለእነዚያም ለካዱት ሰዎች ከታላቁ ቀን መጋፈጥ ክስተት ወዮላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 38, '38. ወደ እኛ በሚመጡ ቀን ምን ያህል ሰሚ ምን ያህል ተመልካች አደረጋቸው:: ግን አመጸኞች በዳዮች ዛሬ በዚህች ዓለም በግልጽ ስህተትና ጥመት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 39, '39. (መልዕክተኛችን ሙሐመድ ሆይ!) በሚፈረድበት ጊዜ የቁጭትን ቀን አስፈራራቸው እነርሱ አሁን በመዘንጋት ላይ ናቸው:: እነርሱ አያምኑምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 40, '40. ምድርንና በእርሷም ላይ ያለውን ፍጡር ሁሉ እኛ እንወርሳለን:: ወደ እኛም ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) በመጽሐፉ ውስጥ ኢብራሂምን አውሳ:: እርሱም በጣም እውነተኛ ነብይ ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 42, '42. ለአባቱ (እንዲህ) ባለው ጊዜ የሆነውን አስታውስ: «አባቴ ሆይ! የማይሰማንና የማያይን ላንተም ምንንም የማይጠቅምህን (የማይፈይድህን) ጣዖት ለምን ታመልካለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 43, '43. «አባቴ ሆይ! እኔ አንተ ያልደረሰህን እውቀት መጥቶልኛልና ተከተለኝ:: ቀጥተኛውን መንገድ እመራሃለሁና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 44, '44. «አባቴ ሆይ! ሰይጣንን አትገዛ \\አታምልክ\\:: ሰይጣን ለአር-ረህማን አመጸኛ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 45, '45. «አባቴ ሆይ! እኔ የአር-ረህማን ቅጣት ሊያገኝህ እና ከዚያ የሰይጣን ጓደኛ ልትሆን እፈራለሁ::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 46, '46. አባቱም «ኢብራሂም ሆይ! አንተ አምላኮቼን ትተህ የምትዞር ነህን? ከዚህ ተግባርህ ባትከለከል በእርግጥ እወግርሃለሁ:: ረዥም ጊዜንም ተወኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 47, '47. ኢብራሂምም አለ: «ደህና ሁን (ሰላም ላንተ ይሁን):: ከጌታዬ ምህረትን እለምንልሃለሁ:: እርሱ ለእኔ በጣም ሩህሩህ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 48, '48. «እናንተንና ከአላህ ሌላ የምትገዙትን ሁሉ እርቃለሁ:: ጌታዬንም ብቻ እገዛለሁ፤ ጌታዬን በመገዛት የማፍር አለመሆኔን እከጅላለሁ (ተስፋ አደርጋለሁ)።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 49, '49. እነርሱንና ከአላህ ሌላ የሚገዙትን በራቀ ጊዜ ኢስሐቅንና የዕቁብን ሰጠነው:: ሁለቱንም ነብይ አደረግናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 50, '50. ለእነርሱም ከችሮታችን ሰጠናቸው:: ለእነርሱም ከፍ ያለ ምስጉን ዝናን አደረግንላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) በመጽሐፉ ውስጥ ሙሳን አውሳ:: እርሱ ምርጥ ነበርና:: መልዕክተኛ ነብይም ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 52, '52. ከጡር ጋራ በስተቀኝ ጎን በኩልም ጠራነው። በሚስጥር ያነጋገርነውም ስንሆን አቀረብነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 53, '53. ከእዝነታችንም (ከችሮታችንም) ወንድሙን ሃሩንን ነብይ አደረግንለት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 54, '54. (መልዕክተኛችን ሙሐመድ ሆይ!) በመጽሐፉ ውስጥ ኢስማዒልንም አውሳ:: እርሱ ቀጠሮን አክባሪ ነበርና። መልዕክተኛ ነብይም ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 55, '55. ቤተሰቦቹንም በሶላትና በዘካ ያዝ ነበር:: በጌታዉም ዘንድ ተወዳጅ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 56, '56. (መልዕክተኛችን ሙሐመድ ሆይ!) በመጽሐፉ ውስጥ ኢድሪስንም አውሳ:: እርሱ እውነተኛ ነብይ ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 57, '57. (ኢድሪስን) ወደ ከፍተኛም ስፍራ አነሳነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 58, '58. እነዚህ (አሥሩ) እነዚያ አላህ በእነርሱ ላይ ችሮታውን የለገሰላቸው ከነብያት ከአዳም ዘር ከኑሕ ጋር በመርከቢቱ ላይ ከጫንናቸዉም ዘሮች ከኢብራሂምና ከኢስራኢልም ዘሮች ከመራናቸውና ከመረጥናቸዉም የሆኑት የአር-ረህማን አናቅጽ በእነርሱ ላይ በተነበቡ ጊዜ ሰጋጆችና አልቃሾች ሆነው ወደ መሬት የሚወድቁ (የሚደፉ) ናቸው። {1}', '{1} እዚህ ሱጁዱ ትላዋ ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 59, '59. ከእነርሱም በኋላ ሶላትን ያጎደሉ ከንቱ ፍላጎቶችንም የተከተሉ መጥፎ ትውልዶች ተተኩ:: «ገይ» የሚባልን የገሀነምንም ሸለቆ በእርግጥ ያገኛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 60, '60. ግና ከእነርሱ የተጸጸቱ በአላህ ያመኑ በጎንም ስራ የሰሩ ሰዎች ወደ ገነት ይገባሉ:: አንዳችንም አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 61, '61. የመኖሪያን ገነቶች ያችን አር-ረህማን ለባሮቹ በሩቅ ሆነው ሳሉ ተስፋ ቃል የገባላቸውን ይገባሉ:: እርሱ ተስፋው ሁልጊዜም ተፈጻሚ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 62, '62. በእርሷ ሰላምን እንጂ ውድቅን ነገር አይሰሙም:: ለእነርሱም በእርሷ ውስጥ ጧትም ማታም ሲሳያቸው አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 63, '63. ይህ ያቺ ከባሮቻችን ጥንቁቆች ለሆኑት ሁሉ የምናወርሳት ገነት ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 64, '64. (ጂብሪልም ለነቢዩ) «በጌታህ ትእዛዝ እንጂ አንወርድም:: በፊታችን፤ በኋላችንና በዚህም መካከል ያለው ሁሉ የእርሱ ብቻ ነው:: ጌታህም ረሺ አይደለም።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 65, '65. እርሱ የሰማያትና የምድር በሁለቱም መካከል ላለው ሁሉ ጌታ ነውና ተገዛው:: እርሱን በመገዛትም ላይ ታገሥ:: ለእርሱ ሞክሼን ታውቃለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 66, '66. ሰው «በሞትኩ ጊዜ ወደ ፊት ህያው ሆኜ ከመቃብር እወጣለሁን?» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 67, '67. ሰው ከዚህ በፊት ምንም ነገር ያልነበረ ሲሆን የፈጠርነው መሆኑን አያስታውስምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) በጌታህ እንምላለን ሰይጣናት ጋር በእርግጥ እንሰበስባቸዋለን:: ከዚያም በገሀነም ዙሪያ የተንበረከኩ ሆነው እናቀርባቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 69, '69. ከዚያም ከየቡድኖቹ ሁሉ ከእነርሱ ያንን በአር-ረህማን ላይ በድፍረት በጣም ብርቱ የሆነውን መዘን እናወጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 70, '70. ከዚያም እነዚያን በእርሷ ለመቃጠል ይበልጥ ተገቢ የሆኑትን ሰዎች እናውቃለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 71, '71. (ሰዎች ሆይ!) ከናንተ መካከል ወደ ገሀነም የማይወርድ አንድም የለም:: መውረዱም ጌታህ የፈረደው ግዴታና አይቀሬ ዉሳኔ ነው:: {1}', '{1} ይህ ጀሀነም መውረድ ትርጉሙ ሙስሊሞች በርሷ ላይ በተዘረገው ሲራጥ በተባለ በጣም ቀጭን ድልድይ ላይ ያልፋሉ ማለት ነው፣ ሰው ያለ ጥፋት ገሀነም የማይገባ መሆኑ የተወቀ ነው [ተፍሲር ኢብኑጀሪር አጥጠበሪ]');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 72, '72. ከዚያም እነዚያን አላህን የፈሩትን ብቻ እናድናለን:: አመጸኞችን ደግሞ የተንበረከኩ ሆነው በውስጧ እንተዋቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 73, '73. በእነርሱም ላይ አናቅጻችን ግልጽ ማስረጃዎች ሆነው በተነበቡላቸው ጊዜ እነዚያ የካዱት ለእነዚያ ላመኑት «ከሁለቱ ክፍሎች መኖሪያው የበለጠውና ሸንጎዉም ይበልጥ የሚያምረው ማንኛው ነው?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 74, '74. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ በፊት ከክፍለ ዘመናት ህዝቦች እነርሱ በእይታ በጣም ያማሩትን ብዙዎችን አጥፍተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 75, '75. (መልዕክተኛችን ሙሐመድ ሆይ!) «በስህተት ውስጥ የሆነውን አዛኙ አምላክ ለእርሱ ጥመትን ይጨምርለት (ማዘግየትን ያዘግየው::) የሚዛትባቸውንም ቅጣትን ወይም ሰዓቲቱን ባዩ ጊዜ እርሱ ስፍራው መጥፎና ሰራዊቱ ደካማ ማን እንደሆነ በእርግጥ ያውቃሉ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 76, '76. እነዚያንም የቀኑትን ሰዎች አላህ ቅንነትን ይጨምርላቸዋል:: መልካም ቀሪ ስራዎች በጌታህ ዘንድ በምንዳ በላጭ ናቸው:: በመመለሻነትም የተሻሉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 77, '77. (መልዕክተኛችን ሙሐመድ ሆይ!) ያንን በአናቅጻችን የካደውንና «በትንሣኤ ቀን ገንዘብም ሆነ ልጅ በእርግጥ እሰጣለሁ» ያለውን አየህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 78, '78. ሩቁን ምስጢር አወቀን ? ወይስ አዛኙ አምላክ ዘንድ ቃል ኪዳንን ያዘ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 79, '79. ከዚህ አቋሙ ይታቀብ:: አይሰጠዉም:: የሚለውን ሁሉ በእርግጥ እንጽፋለን:: ለእርሱም ከቅጣት ጭማሬን እንጨምርለታለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 80, '80. አለኝ የሚለውንም ሁሉ እንወርሰዋለን ወደ እኛም ብቻውን ሆኖ ይመጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 81, '81. ከአላህ ሌላ አማልክትን ለእነርሱ መከበሪያ አማላጅ እንዲሆኗቸው ያዙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 82, '82. ከዚህ ተግባራቸው ይከልከሉ (ይታቀቡ):: መገዛታቸውን በእርግጥ ወደፊት ይከዷቸዋል:: በእነርሱም ላይ ተቃራኒ (ባላጋራ) ይሆኑባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰይጣናትን በከሓዲያን ላይ በመጥፎ ሥራ የሚገፋፏቸው ሲሆኑ የላክንባቸው መሆናችንን አላየህምን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 84, '84. (መልዕክተኛችን ሙሐመድ ሆይ!) በእነርሱም መቀጣት ላይ አትቸኩል:: ለእነርሱ ቀንን እንቆጥርላቸዋለንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 85, '85. ትክክለኛ አማኞችን የተከበሩ ቡድኖች ሆነው ወደ አዛኙ አምላክ የምንሰበሰብበትንና:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 86, '86. ከሓዲያንን የተጠሙ ሆነው ወደገሀነም የምንነዳበትን ቀን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 87, '87. አዛኙ አምላክ ዘንድ ቃል ኪዳንን የያዘ ቢሆን እንጂ ሌሎች ማማለድን አይችሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 88, '88. አጋሪዎች «አዛኙ አምላክ አላህ ልጅ ወለደ።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 89, '89.(አጋሪዎች ሆይ!) እጅግ ከባድና መጥፎን ነገር በእርግጥ አመጣችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 90, '90. ከዚህ ንግግራቸው ሰማያት ሊቀደዱ፤ ምድርም ልትሰነጠቅ፤ ጋራዎችም ተንደው ሊወድቁ ይቃረባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 91, '91. ይህም ለአዛኙ አምላክ ልጅ አለው ስላሉ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 92, '92. አዛኙ ጌታ ልጅን መያዝ አይገባዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 93, '93. በሰማያትና በምድር ያለው ሁሉ በትንሣኤ ቀን (ለአር-ረህማን) ለአዛኙ ጌታ ባሪያ ሆነው የሚመጡ እንጂ ሌላ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 94, '94. አላህ በእርግጥ በዕውቀቱ ከቧቸዋል:: መቁጠርንም ቆጥሯቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 95, '95. ሁሉም በትንሳኤ ቀን ለየብቻ ሆነው ወደ እርሱ መጪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 96, '96. እነዚያ በአላህ ያመኑና በጎ ስራዎችን የሰሩ ሁሉ አር-ረህማን ለእነርሱ ውዴታን ይሰጣቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 97, '97. (መልዕክተኛችን ሙሐመድ ሆይ!) በምላስህም ቁርኣንን ያገራነው በእርሱ ጥንቁቆችን ልታበስርበትና በእርሱ ተከራካሪ ሕዝቦችን ልታስፈራራበት ዘንድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (19, 98, '98. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም በፊት ከክፍለ ዘመናት ህዝቦች ብዙ ትውልዶችን አጥፍተናል:: ከእነርሱ አንድን እንኳ ታያለህን? ወይንስ ለእነርሱ ሹክሹክታን ትሰማለህን? (አታይም፣ አጸማምም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 1, '1. ጧሃ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 2, '2.(መልዕክተኛችን ሙሐመድ ሆይ!) ቁርኣንን አንድትቸገር ባንተ ላይ አላወረድንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 3, '3. አላህን ለሚፈራ ሁሉ መገሠጫ ይሆን ዘንድ እንጂ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 4, '4. ቁርኣን ምድርንና የላይኛዎቹን (የተከበሩ) ሰማያትን ከፈጠረ አምላክ ተወረደ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 5, '5.እርሱ አዛኙ ጌታ (አር-ረህማን) በዐርሹ ላይ ከፍ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 6, '6. በሰማያት፤በምድርና በመካከላቸዉም ያለው ከአፈር በታችም ያለው ሁሉ የእርሱ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) በንግግር ብትጮህ (አላህ ከጩኸቱ የተብቃቃ ነው።) እርሱ ምስጢርን ከዚያም በጣም የተደበቀንም ያውቃልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 8, '8.አላህ ከእርሱ ሌላ አምላክ የለም:: ለእርሱ መልካሞች የሆኑ አያሌ ስሞች አሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 9, '9.(መልዕክተኛችን ሙሐመድ ሆይ!) የሙሳ ወሬ (ታሪክ) መጥቶሃልን (ደርሶሃልን)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 10, '10. እሳትን ባየና ለቤተሰቦቹ «(እዚህ) ቆዩ:: እኔ እሳትን አየሁ፤ ከእርሷ ችቦን ላመጣላችሁ ወይም እሳቲቱ ዘንድ መሪን ላገኝ እከጅላለሁ።» ባለ ጊዜ የሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 11, '11. እናም ወደ እርሷ በመጣ ጊዜ (እንዲህ) በማለት ተጠራ: «ሙሳ ሆይ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 12, '12. «እኔ ጌታህ ነኝ። ጫማዎችህን አውልቅ፤ አንተ በተቀደሰው ሸለቆ በጡዋ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 13, '13. «እኔም መረጥኩህ ስለ ሆነም የሚወረድልህን ነገር በደንብ አዳምጥ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 14, '14. «እኔ አላህ ነኝ። ያለ እኔ ትክክለኛ አምላክ የለምና እኔን ብቻ ተገዛኝ:: ሶላትንም እኔን ለማውሳት በአግባቡ ስገድ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 15, '15. «ነፍስ ሁሉ በምትሰራው ነገር ትመነዳ ዘንድ ሰዓቲቱ በእርግጥ መጪ ናት። የትንሳኤውን ወሬ ልደብቃት እቀርባለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 16, '16. (ሙሳ ሆይ!) «በእርሷ የማያምንና ዝንባሌውን የሚከተል ሰው ሁሉ ከእርሷ አያግድህ ትጠፋለህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 17, '17. (ሙሳ ሆይ!) «ይህችም በቀኝ እጅህ ያለችው ምንድን ናት?» (ተባለ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 18, '18. «እርሷ በትሬ ናት:: በእርሷም እደገፍባታለሁ:: በእርሷም ለፍየሎቼ ቅጠልን አረግፍባታለሁ:: በእርሷ ሌሎች ጉዳዮችም አሉኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 19, '19. አላህም «ሙሳ ሆይ! እስቲ ጣላት።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 20, '20.ሙሳም ጣላትና፤ ወዲያዉም እርሷ የምትሮጥ እባብ ሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 21, '21.አላህም አለው: «ሙሳ ሆይ! ያዛት አትፍራም ወደ መጀመሪያ ጠባይዋ እንመልሳታለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 22, '22. «እጅህንም ወደ ብብትህ አስገባ:: ሌላ ተዓምር ስትሆን ያለ ምንም ችግር ነጭ ሆና ትወጣለችና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 23, '23. (ሙሳ ሆይ!) «ከተዓምራቶቻችን ታላቋን እናሳይህ ዘንድ ይህን ፈጸምን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 24, '24. (ሙሳ ሆይ!) «ወደ ፈርዖን ሂድ:: እርሱ ወሰን (ድንበር) አልፏልና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 25, '25. ሙሳም አለ: «ጌታዬ ሆይ! ልቤን አስፋልኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 26, '26. «ጉዳዬንም አግራልኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 27, '27. «የምላሴን መኮላተፍም አስወግድልኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 28, '28. «ንግግሬን ይረዱ ዘንድ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 29, '29. «ከቤተሰቦቼም ለእኔ ረዳትን አድርግልኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 30, '30. «ወንድሜን ሃሩንን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 31, '31. «ኃይሌንም በእርሱ አበርታልኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 32, '32. «በነገሬም አጋራው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 33, '33. «በብዛት እንድናጠራህና', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 34, '34. «በብዛት እንድናወሳህ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 35, '35. «አንተ በእኛ ነገር አዋቂ ነህና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 36, '36. አላህም አለ: «ሙሳ ሆይ! ልመናህ በእርግጥ ተቀባይነትን አገኝቷል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 37, '37. «ሙሳ ሆይ! በሌላም ጊዜ ባንተ ላይ በእርግጥ ውለታን ውለናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 38, '38. «ለእናትህ በራእይ ባሳወቅን ጊዜ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 39, '39. «‹ሕፃኑን በሳጥኑ ውስጥ አስገቢው እርሱንም (ሳጥኑን) በባህር ላይ ጣይው፤ ባህሩም በዳርቻው ይጥለዋል (ይተፋዋል):: ለእኔም ለእርሱም ጠላት የሆነ ሰው ይይዘዋልና› በማለት (ባሳወቅን ጊዜ ለገስንልህ)። ልትወደድና በዐይኔ እይታ (በእኔም ጥበቃ) ታድግ ዘንድ ባንተ ላይም ከእኔ የሆነ መወደድን ጣልኩብህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 40, '40. «እህትህ በምትሄድና ‹የሚያሳድገውን ሰው ላመላክታችሁን?› ባለች ጊዜ (መወደድን ጣልኩብህ):: ወደ እናትህም ዓይኗ እንዲረጋና እርሷ እንዳታዝንም መለስንህ:: ነፍስንም ገደልክ ከጭንቅም አዳንንህ:: ፈተናዎችንም ፈተንህ:: በመድየን ቤተሰቦችም ውስጥ ብዙ ዓመታትን ተቀመጥክ:: ከዚያ ሙሳ ሆይ! በተወሰነ ጊዜ ላይ መጣህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 41, '41. «ለራሴም ለመልዕክተኝነት መረጥኩህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 42, '42. «አንተና ወንድምህ በተዓምራቴ ሆናችሁ ሂዱ:: እኔንም ከማውሳትም አትቦዝኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 43, '43. «ወደ ፈርዖን ሂዱ:: እርሱ ወሰን አልፏልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 44, '44. «እርሱ ምን አልባትም ይገሰጥ ወይም ይፈራ ዘንድ:: ለእርሱ ለስላሳን ቃል ተናገሩት።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 45, '45. «ጌታችን ሆይ! በእኛ ላይ ክፋት በመስራት መቸኮሉን ወይም ኩራትን መጨመሩን እንፈራለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 46, '46. አላህም አለ: «እኔ በእርግጥ ከናንተ ጋር ነኝና አትፍሩ:: የሚለውንም ሁሉ እሰማለሁ። የሚፈጸመዉንም አያለሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 47, '47. እናም ወደ እርሱም ሂዱና (እንዲህ) በሉት: ‹እኛ የጌታህ መልዕክተኞች ነንና የኢስራኢልን ልጆች ሁሉ ከእኛ ጋር ልቀቅ። አታሰቃያቸዉም:: ከጌታህ በሆነው ተዓምር በእርግጥ መጥተንሃልና:: ሰላምም ቀጥታን በተከተለ ሁሉ ላይ ይሁን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 48, '48. «‹እነሆ የአላህ ቅጣት እውነትን ባስተባበለና እምቢ ባለ ሰው ላይ እንደሆነ በእርግጥ አያሌ መልዕክት ተወረደልን።› በሉት።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 49, '49. ፈርዖንም «ሙሳ ሆይ! ጌታችሁ ማነው?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 50, '50. «ጌታችን ያ ለፍጥረቱ ሁሉ የሚያስፈልገውን ቅርጹንና ባህሪውን የሰጠው ከዚያም ሁሉንም ለተፈጠረለት የመራው ነው።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 51, '51. ፈርዖንም «የመጀመሪያይቱ ዘመናት ህዝቦች ሁኔታስ ምንድን ነው?» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 52, '52. ሙሳም «የዚህ ዕውቀት እጌታዬ ዘንድ በመጽሐፍ የተመዘገበ ነው:: ጌታዬ አይሳሳትም አይረሳምም።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 53, '53. ያ ምድርን ለእናንተ ምንጣፍ ያደረገላችሁ በእርሷም ውስጥ ለእናንተ መንገድን ያገራላችሁ ውሃንም ከሰማይ ያወረደላችሁ ነው። በእርሱም ከተለያየ በቃይ ዓይነቶችን አወጣንላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 54, '54. ለራሳችሁ ብሉ:: እንስሳዎቻችሁንም አግጡ:: (ባዮች ሆነን አወጣንላችሁ።) በዚህ ውስጥ ለአእምሮ ባለቤቶች ሁሉ በእርግጥ ተዐምራት አለበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 55, '55. (ሰዎች ሆይ!) ከእርሷ (ከምድር) ፈጠርናችሁ:: ወደ እርሷም ውስጥ እንመልሳችኋለን:: ከእርሷም በሌላ ጊዜ እናወጣችኋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 56, '56.ተዓምራቶቻችንንም ሁሏንም ለፈርዖን በእርግጥ አሳየነው:: አስተባበለም:: እምቢም አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 57, '57. አለም: «ሙሳ ሆይ! ከምድራችን በድግምትህ ልታወጣን መጣህብን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 58, '58. «መሰሉንም ድግምት እናመጣብሃለን:: በእኛና ባንተም መካከል እኛም አንተም የማንጥሰው የሆነ ቀጠሮን በመካከለኛ ስፍራ አድርግልን።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 59, '59.ሙሳም: «ቀጠሯችሁ ያ የማጌጫው የበአሉ ቀን ነው። ሰዎችም ረፋድ ላይ እንዲሰበሰቡ ይሁን።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 60, '60. ፈርዖንም ዞረ:: ተንኮሉን ሰበሰበ:: ከዚያ መጣ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 61, '61.ሙሳም ለእነርሱ: «ወዮላችሁ በአላህ ላይ ውሸትን አትቅጠፉ:: በቅጣት ያጠፋችኋልና:: የቀጠፈም ሰው በእርግጥ አፈረ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 62, '62. (ድግምተኞቹ) በመካከላቸውም ነገራቸውን ተጨቃጨቁ፡፡ ውይይትንም ደበቁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 63, '63. አሉም: «እነዚህ በእርግጥ ደጋሚዎች ናቸው:: ከምድራችሁ በድግምታቸው ሊያወጧችሁ በላጪቱንም መንገዳችሁን ሊያስወግዱባችሁ ይሻሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 64, '64. «ተንኮላችሁንም አጠንክሩ:: ከዚያም ተሰልፋችሁ ኑ:: ዛሬ ያሸነፈም ሰው ምኞቱን አገኘ።» ተባባሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 65, '65. «ሙሳ ሆይ! በመጀመሪያ ትጥላለህ ወይስ እኛ እንጣል? (ምረጥ)» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 66, '66. ሙሳም «እናንተ በመጀመሪያ ጣሉ።» አላቸው። ጣሉም:: ወዲያዉም ገመዶቻቸውና ዘንጎቻቸው ከድግምታቸው የተነሳ የሚሮጡ እባቦች ሆነው (መስለው) ወደ እርሱ ተመሰሉበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 67, '67.ሙሳም በውስጡ ፍርሃት አደረበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 68, '68. አልነውም: «አትፍራ። የበላዩ አንተ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 69, '69. «በቀኝ እጅህ ያለችውን ብትር ጣል:: ያንን የሰሩትን ሁሉ ትውጣለችና። ያ የሰሩት ሁሉ የድግምተኛ ተንኮል ብቻ ነውና:: ድግምተኛም በመጣበት ስፍራ ሁሉ አይቀናዉም::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 70, '70. ድግምተኞቹም ሱጁድ ወረዱ: «በሃሩንና በሙሳ ጌታ አመንን።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 71, '71. (ፈርዖንም) «ለእናንተ ሳልፈቅድላችሁ በፊት ለእርሱ አመናችሁለትን! እርሱ በእርግጥ ያ ድግምትን ያስተማራችሁ መሪያችሁ ነው:: እጆቻችሁንና እግሮቻችሁን (በማናጋት) ግራንና ቀኝን በማፈራረቅ እቆራርጣችኋለሁ:: በዘምባባም ግንዶች ላይ እሰቅላችኋለሁ:: የማንኛችን ቅጣት በጣም ብርቱና የሚቆይ መሆኑን በዚያ ጊዜ ታውቃላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 72, '72. አሉትም: «ከመጡልን ተዓምራትና ከዚያ ከፈጠረን አምላክ ፈጽሞ አናስበልጥህም:: እናም የምትፈርደውን ፍረድ:: የምትፈርደው በዚህች በአነስተኛይቱ ህይወት ብቻ ላይ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 73, '73. «ኃጢአቶቻችንንና ከድግምትም እንድንፈጽመው ያስገደድከንን ይምረን ዘንድ እኛ በጌታችን አምነናል:: አላህ በጣም በላጭ ነው:: ቅጣቱም ሆነ ምንዳው በጣም የሚዘወትር ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 74, '74. ከሃዲ ሆኖ ወደ ጌታው የሚመጣ (የሚሞት) ሰው ሁሉ ለእርሱ ገሀነም አለችለት:: በውስጧም አይሞትም ህያዉም አይሆንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 75, '75.እነዚያ በጎ ስራዎችን የሰሩና አማኝ ሆነው ወደ ጌታቸው የመጡ ሰዎች ደግሞ እነዚያ ለእነርሱ ከፍተኛ ደረጃዎች አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 76, '76.ከስሮቻቸው ወንዞች የሚፈሱባቸው የመኖሪያ ገነቶች በውስጣቸው ዘውታሪዎች ሲሆኑ አሏቸው:: ይህም አይነቱ ክፍያ ለተጥራራ ሁሉ ምንዳው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 77, '77. ወደ ሙሳም «ባሮቼን ይዘህ በሌሊት ሂድ:: ለእነርሱም በባህር ውስጥ ደረቅ መንገድን አድርግላቸው:: ፈርዖን ያገኘኛል ብለህ አትፍራ:: ከመስመጥም አትጨነቅ።» ስንል በእርግጥ ላክንበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 78, '78. ፈርዖን ከሰራዊቱ ጋር ሆኖ ተከተላቸው:: ከባህሩም የሚሸፍን ነገር ሸፈናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 79, '79.ፈርዖንም ህዝቦቹን አሳሳታቸው:: ቅኑንም መንገድ አልመራቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 80, '80. የኢስራኢል ልጆች ሆይ! ከጠላታችሁ በእርግጥ አዳንናችሁ:: በጡር ተራራም ቀኝ ጎን ላይ ቀጠሮ አደረግንላችሁ። በእናንተም ላይ መናንና ሰልዋን (ድርጭት) አወረድንላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 81, '81. ከሰጠናችሁ ሲሳይ ከመልካሙ ብሉ:: በእርሱም ወሰንን አትለፉ:: ቁጣዬ በእናንተ ላይ ይወርድባችኋልና:: ቁጣዬ የሚወርድበት ሁሉ በእርግጥ ይጠፋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 82, '82.እኔም ለተጸጸተ ላመነም መልካምንም ለሰራ ከዚያ ለተመራ ሁሉ በእርግጥ መሓሪ ነኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 83, '83. «ሙሳ ሆይ! ከህዝቦችህ ምን አስቸኮለህ?» ተባለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 84, '84. «እነርሱ እነዚህ በዱካዬ ላይ ያሉ ናቸው:: ጌታዬ ሆይ! ትወድልኝ ዘንድ ወደ አንተ ቸኮልኩ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 85, '85.(አላህም) «እኛም ካንተ በኋላ ሰዎችህን በእርግጥ ፈተንን:: ሳምራዊዉም አሳሳታቸው።» አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 86, '86. ሙሳም ወደ ሰዎች የተቆጣና ያዘነ ሆኖ ተመለሰ:: «ህዝቦቼ ሆይ! ጌታችሁ መልካም ተስፋን አልቀጠራችሁምን? ቀጠሮው በእናንተ ላይ ረዘመባችሁን? ወይስ በእናንተ ላይ ከጌታችሁ ቅጣት ሊወርድባችሁ ፈለጋችሁና ቃል ኪዳኔን አፈረሳችሁ?» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 87, '87. «ቀጠሮህን በፈቃዳችን አልጣስንም:: ግን እኛ ከህዝቦች ጌጥ ሸክሞችን ተጫን:: በእሳት ላይ ጣልናትም:: ሳምራዊዉም እንደዚሁ አብሮን ጣለ።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 88, '88. ለእነርሱም የመጓጎር ባህሪ ያለውን ጥጃን (መሰል) አካልን አወጣላቸው። «ተከታዮቹ ሆይ! ይህ የእናንተም ሆነ የሙሳ አምላክ ነው:: ግን ረሳው እንጂ።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 89, '89.ወደ እነርሱ ንግግርን የማይመልስ ለእነርሱም ጉዳትንና ጥቅምን የማይችል መሆኑን አያዩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 90, '90-.ከዚያ በፊት ሀሩንም በእርግጥ አላቸው: «ህዝቦቼ ሆይ! ይህ በእርሱ የተሞከራችሁበት ብቻ ነው:: ጌታችሁም አር-ረህማን ነው:: ተከተሉኝም፤ ትእዛዜንም ስሙ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 91, '91. «ሙሳ ወደ እኛ እስከሚመለስ በእርሱ መገዛት ላይ ከመቆየት ፈጽሞ አንወገድም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 92, '92- ሙሳም አለ፡- «ሃሩን ሆይ! ተሳስተው ባየሃቸው ጊዜ ምን ከለከለህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 93, '93. «እኔን ከመከተል? ትእዛዜን ጣስክን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 94, '94. «ሃሩን የእናቴ ልጅ ሆይ! ፂሜንም ሆነ ራሴን አትያዝ:: እኔ ‹በኢስራኢል ልጆች መካከል ለያየህ ቃሌንም አልጠበክም› ማለትህን ፈራሁና ነው።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 95, '95. ሙሳም «ሳምራዊው ሆይ! ነገርህ ምንድን ነው?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 96, '96. ሳምራዊውም: «እነርሱ ያላዩትን ነገር አየሁ:: ከመልዕክተኛው ፈረስ ኮቴ ዱካም ጭብጥ አፈርን ዘገንኩ:: በቅርጹ ላይ ጣልኳትም:: ልክ እንደዚሁ ነፍሴ ሸለመችልኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 97, '97. ሙሳም ለሳምራዊው አለው: «ሂድ። በህይወትህ ላየኸው ሰው ሁሉ ‹መነካካት የለም› እያልክ ኑር:: ላንተም ፈጽሞ የማትቀር ቀጠሮ አለህ:: ወደ እዚያዉም በእርሱ ላይ ተገዢው ሆነህ ወደ ቆየህበት አምላክህ ተመልከት:: በእርግጥ እናቃጥለዋለን:: ከዚያም በባህሩ ውስጥ እንበትነዋለን::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 98, '98.(ሰዎች ሆይ!) ጌታችሁም ያ ከእርሱ በስተቀር ሌላ አምላክ የሌለ የሆነው አላህ ብቻ ነው:: እውቀቱ ሁሉን ነገር አዳረሰ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 99, '99. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁ በእርግጥ ካለፉት ወሬዎች ባንተ ላይ እንተርካለን፤ ከእኛም ዘንድ ቁርኣንን በእርግጥ ሰጠንህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 100, '100.ከእርሱ ያፈገፈገ ሰው እርሱ በትንሳኤ ቀን ከባድን ቅጣት ይሸከማል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 101, '101.በእርሱ ውስጥ ዘውታሪዎች ሆነው ይሸከማሉ:: በትንሳኤ ቀን ለእነርሱ እጣ ፈንታ የሆነው ሸክም ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 102, '102. በቀንዱ በሚነፋ ቀን ሸክማቸው ከፋ:: ከሓዲያን በዚያ ቀን ዓይኖቻቸው ሰማያዊዎች ሆነው እንሰበስባቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 103, '103. «አስርን (ቀን) እንጂ አልቆያችሁም።» በመባባል በመካከላቸው ይንሾካሾካሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 104, '104. በሃሳብ ቀጥተኛቸው «አንድን ቀን እንጂ አልቆያችሁም።» በሚል ጊዜ የሚሉትን ነገር እኛ አዋቂዎች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 105, '105. (መልዕክተኛችን ሙሐመድ ሆይ!) ከጋራዎች ይጠይቁሃልና (እንዲህ) በላቸው: «ጌታዬ መበተንን ይበትናቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 106, '106. «ትክክል ሜዳም ሆና ይተዋታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 107, '107. «በእርሷ ዝቅታና ከፍታን ፈጽሞ አታይም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 108, '108. (መልዕክተኛችን ሙሐመድ ሆይ!) በዚያ ቀን ለመሰብሰብ ጠሪውን ምንም እንከን የሌለውን ተጣሪ ይከተላሉ:: ድምፆችም ሁሉ ለአር-ረህማን ጸጥ ይላሉ:: ስለዚህ (የኮቴ) ሹክሹክታን እንጂ አትሰማም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 109, '109.በዚያ ቀን ለእርሱ አር-ረህማን የፈቀደለትንና ለእርሱም ቃልን የወደደለትን ብቻ ቢሆን እንጂ ምልጃ አንድንም አትጠቅምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 110, '110. በስተፊታቸው ያለውንም ሆነ በስተኋላቸው ያለውን ሁሉ ያውቃል:: በእርሱ ላይ ግን ማንም በእውቀቱ አያካብብም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 111, '111. ፊቶችም ሁሉ ህያውና የሁሉ አስተናባሪ ለሆነው አላህ ተዋረዱ:: በደልንም የተሸከመ በእርግጥ ከሰረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 112, '112. አማኝ ሆኖ መልካም ስራዎችን የሰራ በደልንም ሆነ መጉደልን አይፈራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 113, '113.ልክ እንደዚሁም ዐረብኛ ቁርኣን ሆኖ አወረድነው:: አላህን ይፈሩ ዘንድ ወይም ለእነርሱ ግሣጼን ያድስላቸው ዘንድ ከዛቻ ደጋግመን በውስጡ ገለጽን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 114, '114. (መልዕክተኛችን ሙሐመድ ሆይ!) እውነተኛው ንጉስ አላህ ከሓዲያን ከሚሉት ነገር ሁሉ ላቀ:: ወደ አንተ መወረዱም ከመፈጸሙ በፊት ቁርኣንን በማንበብ አትቸኩል:: «ጌታዬ ሆይ! ዕውቀትን ጨምርልኝ።» በልም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 115, '115. ወደ አደምም ከዚህ በፊት ቃል ኪዳንን በእርግጥ አወረድንና ረሳ:: ለእርሱም ቆራጥነትን አላገኘንለትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 116, '116.(መልዕክተኛችን ሙሐመድ ሆይ!) ለመላእክትም «ለአደም ስገዱ።» ባልን ጊዜ (የሆነውን አስታውስ):: እነርሱም ዲያብሎስ ብቻ ሲቀር ሰገዱ:: እሱማ እምቢ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 117, '117.ከዚያም አልን: «አደም ሆይ! ይህ ላንተም ለሚስትህም በእርግጥ ጠላት ነው:: ስለዚህ ከገነት አያውጣችሁ፤ ትለፋለህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 118, '118.(አደም ሆይ!) «ላንተ በእርሷ ውስጥ አለመራብና አለመታረዝ አለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 119, '119. «አንተም ከእርሷ ውስጥ አትጠማም:: በጸሐይም አትተኮስም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 120, '120. ሰይጣን ወደ እርሱ (አደም) « አደም ሆይ! በመዘውተሪያ ዛፍ በማይጠፋ ንግስናም ላይ ላመላክትህን?» በማለት ጎተጎተ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 121, '121.ከእርሷም በሉ:: ለእነርሱም ሀፍረተ ገላቸው ተገለጸች:: ከገነትም ቅጠል በላያቸው ላይ ይለጥፉ ጀመር:: አደምም የጌታውን ትእዛዝ ረስቶ ጣሰ:: ተሳሳተም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 122, '122. ከዚያም ጌታው መረጠው:: ከእርሱም ጸጸቱን ተቀበለው:: መራዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 123, '123.አላህም አላቸው፡- «ከፊላችሁ ለከፊሉ ጠላት ሲሆን (አደምና ሐዋ) ሁላችሁም ከእርሷ ውረዱ:: ከእኔ የሆነ መመሪያ ቢመጣላችሁ መመሪያየን የተከተለ ሁሉ አይሳሳትም:: አይቸገርምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 124, '124. «ከግሳጼዬ የዞረ ግን በዚህች ዓለም ጠባብ ኑሮ አለው:: በትንሳኤ ቀንም ዕውር ሆኖ እንቀሰቅሰዋለን::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 125, '125. «ጌታዬ ሆይ! ለምን ዕውር አድርገህ አስነሳኸኝ:: በእርግጥ የማይ የነበርኩ ስሆን» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 126, '126. «ነገሩ ልክ እንደዚሁ ነው:: ተዓምራቶቻችን መጡልህና ተውካቸውም:: ልክ እንደዚሁም ዛሬ ትተዋለህ።» ይለዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 127, '127.እንደዚሁም ያጋራንና በጌታው አናቅጽ ያላመነን እንቀጣዋለን:: የመጨረሻይቱ ዓለም ቅጣት በጣም ብርቱና ለሁልጊዜም ዘውታሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 128, '128. (መልዕክተኛችን ሙሐመድ ሆይ! ቁረይሾች) ከእነርሱ በፊት ከክፍለ ዘመናት ህዝቦች ብዙዎችን ያጠፋን መሆናችን በመኖሪያዎቻቸው የሚሄዱ ሆነው ሳሉ ለእነርሱ አልተገለጸላቸዉምን? በዚህ ውስጥ ለአእምሮ ባለቤቶች በእርግጥ መልዕክቶች አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 129, '129.(መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህ ያለፈች ቃልና የተወሰነ ጊዜ ባልነበረ ኖሮ ቅጣቱ አሁኑኑ የሚይዛቸው ይሆን ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 130, '130. (መልዕክተኛችን ሙሐመድ ሆይ! ) በሚሉትም ሁሉ ላይ ታገሥ፤ ጌታህንም ጸሐይ ከመውጣቷ በፊትና ከመግባቷም በፊት የምታመሰግን ሆነህ አጥራው:: ከሌሊት ሰዓቶችም በቀን ጫፎችም አጥራው:: በሚሰጥህ ምንዳ ልትወድ ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 131, '131.ዐይኖችህን ከሰዎች የተወሰኑ ክፍሎችን ልንፈትናቸው ወደ አጣቀምንበት ወደ ቅርቢቱ ህይወት ጌጦች አትዘርጋ:: የጌታህ ሲሳይ በጣም በላጭና ዘውታሪ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 132, '132.(መልዕክተኛችን ሙሐመድ ሆይ!) ቤተሰብህንም በሶላት ላይ እዘዝ:: አንተም በእርሷ ላይ ዘውትር:: ሲሳይን አንጠይቅህም:: እኛ እንሰጥሃለን:: መልካሚቱ መጨረሻ ለጥንቁቆቹ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 133, '133. (መልዕክተኛችን ሙሐመድ ሆይ!) ተከራካሪዎችህ «ከጌታው በሆነ ተዓምር አይመጣምን?» አሉ:: በመጀመሪያዎቹ ጹሁፎች ውስጥ ያለችው ማስረጃ አልመጣቻቸዉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 134, '134. እኛም (ከሙሐመድ መላክ) በፊት በቅጣት ባጠፋናቸው ኖሮ «ጌታችን ሆይ! ከመዋረዳችንና ከማፈራችን በፊት አናቅጽህን እንከተል ዘንድ ወደኛ መልዕክተኛን አትልክልንም ነበርን?» ባሉ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (20, 135, '135. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሁሉም ተጠባባቂ ነው:: ተጠባበቁም የቀጥታዉም መንገድ ባለቤቶች እነማን እንደ ሆኑ እነማንም እንደ ተመሩ ወደፊት ታውቃላችሁ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 1, '1. ለሰዎች እነርሱ በዝንጋታ ውስጥ መሰናዳትን የተዉ ሆነው ሳሉ ምርመራቸው ቀረበ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 2, '2. ከጌታቸው አዲስ የተወረደ ቁርኣን አይመጣላቸዉም:: እነርሱ የሚያላግጡበት ሆነው ፤ የሚያዳምጡት ቢሆኑ እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 3, '3.ልቦቻቸው ዝንጉዎች ሆነው። እነዚያም የበደሉት ሰዎች መንሾካሾክን ደበቁ:: «ይህ ብጤያችሁ ሰው እንጂ ሌላ ነውን? እናንተም የምታዩ ስትሆኑ ድግምትን ለመቀበል ትመጣላችሁን?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 4, '4. (ሙሐመድም) «ጌታዬ ቃልን ሁሉ በሰማይና በምድር ውስጥ ያለ ሲሆን ያውቃል:: እርሱም ሰሚና አዋቂ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 5, '5. በእውነቱ «ቁርኣኑ የሕልሞች ቅዠቶች ነው። ይልቁንም ቀጠፈው፤ እንዲያዉም እርሱ ቅኔን ገጣሚ ነው:: የቀድሞዎቹም እንደ ተላኩ ሁሉ መልዕክተኛ ከሆነ በተዓምር ይምጣብን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 6, '6. ከእነርሱ በፊት ያጠፋናት ከተማ አላመነችም:: ታዲያ እነርሱ ያምናሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 7, '7.(መልዕክተኛችን ሙሐመድ ሆይ!) ከአንተም በፊት ወደእነሱ የምናወርድላቸው የኾነን ሰዎችን እንጂ ሌላን አላክንም፡፡ የማታውቁ ከሆናችሁ የመጽሐፉን ባለቤቶች ጠይቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 8, '8.ምግብን የማይበላ አካልም አላደረግናቸዉም:: ዘውታሪዎችም አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 9, '9.ከዚያ ቀጠሮን ሞላንላቸውና እነርሱንና የምንሻውን ሰው አዳንናቸዉም:: ወሰን አላፊዎችንም አጠፋን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 10, '10. (ሙስሊሞች ሆይ!) ክብራችሁ በውስጡ ያለበትን መጽሐፍ ወደእናንተ በእርግጥ አወረድን፡፡ አታውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 11, '11. በዳይም ከነበረች ከተማ ያጠፋናትና ከኋላዋም ሌሎችን ህዝቦች ያስገኘነው ብዙ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 12, '12. ቅጣታችንም በተሰማቸው ጊዜ እነርሱ ወዲያውኑ ከርሷ ለመሸሽ ይገሰግሳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 13, '13. «አትገስግሱ፤ ትጠየቁም ይሆናልና በእርሱ ወደ ተቀማጠላችሁበት ጸጋ ወደ መኖሪያዎቻችሁም ተመለሱ።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 14, '14. «ዋ ጥፋታችን! እኛ በእርግጥ በዳዮች ነበርን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 15, '15.የታጨዱ ሬሳዎችም እስካደረግናቸው ድረስ ይህቺ ጥሪያቸው ከመሆን አልተወገደችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 16, '16. ሰማይንና ምድርን በመካከላቸው ያለውንም ሁሉ ቀላጆች ሆነን አልፈጠርንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 17, '17.መጫዎቻን (ሚስትንና ልጅን) ልንይዝ በሻን ኖሮ ከኛ ዘንድ በያዝነው ነበር፤ ግን ሰሪዎች አይደለንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 18, '18. በእርግጥ እውነትን በውሸት ላይ እንጥላለን:: አንጎሉን ያፈርሰዋልም:: ወዲያዉም እርሱ ጠፊ ነው:: ለእናንተም ከዚያ (ሚስትና ልጅ) አለው በማለት ከምትመጥኑት ነገር ብርቱ ቅጣት አላችሁ:: (ወዮላችሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 19, '19. በሰማያትና በምድር ዉስጥ ያለው ሁሉም የእርሱ ብቻ ነው:: እርሱ ዘንድ ያሉትም መላእክት እርሱን ከመገዛት አይኮሩም:: አይሰለቹምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 20, '20. በበሌሊትና በቀንም ያጠሩታል:: አይታክቱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 21, '21. ይልቁንም ከምድር የሆኑን ሙታንን የሚያስነሱ አማልክትን ያዙን? የለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 22, '22.በሰማያትና በምድር ውስጥ ከአላህ ሌላ አማልክት በነበሩ ኖሮ ሁለቱም በተበላሹ ነበር:: የዐርሹ ጌታ አላህም ከሚሉት ሁሉ ጠራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 23, '23. አላህ ከሚሰራው ሁሉ አይጠየቅም:: እነርሱ (ፍጥረቶቹ) ግን ይጠየቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቁንም ከርሱ ሌላ አማልክትን ያዙን? «አስረጃችሁን አምጡ:: ይህ ቁርኣን እኔ ዘንድ ያለው ህዝብ መገሰጫ፤ ከኔ በፊትም የነበሩት ህዝቦች መገሠጫ ነው።» በላቸው:: እንዲያዉም አብዛኞቻቸው እውነቱን አያውቁም:: ስለዚህ እነርሱ እንቢተኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊትም እነሆ ከእኔ ሌላ አምላክ የለምና ተገዙኝ በማለት ወደ እርሱ የምናወርድለት ቢሆን እንጂ ከመልዕክተኛ አንድንም አላክንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 26, '26. «አር-ረሕማንም ከመላእክት መካከል ልጅን ያዘ።» አሉ። ጥራት ተገባው። አይደለም መላእክት የተከበሩ ባሮች ብቻ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 27, '27. በንግግር አይቀድሙትም፤ ያዘዘውንም ይፈጽማሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 28, '28.በፊታቸው ያለውንና በኋላቸው ያለውንም ሁሉ ያውቃል:: ለወደደውም እንጂ ለሌላው አያማልዱም:: እነርሱም እርሱን ከመፍራታቸው የተነሳ ተጨናቂዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 29, '29. ከእነርሱም «እኔ ከእርሱ ሌላ አምላክ ነኝ።» የሚል ያንን ገሀነምን እንመነዳዋለን፤ በዳዮችን እንደዚሁ እንመነዳለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 30, '30. እነዚያም በአላህ የካዱ ሰዎች ሰማያትና ምድር የተጣበቁ የነበሩና የለያየናቸው መሆናችንን አያውቁምን? ህያው የሆነንም ነገር ሁሉ ከውሃ ፈጠርን። አያምኑምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 31, '31. በምድርም ውስጥ በእነርሱ እንዳታረገርግ ጋራዎችን አደረግን። ይመሩም ዘንድ በእርሷ ውስጥ ሰፋፊ መንገዶችን አደረግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 32, '32. ሰማይንም ከመውደቅ የተጠበቀ ጣራ አደረግን:: እነርሱ ግን ከተዓምራቱ ዘንጊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 33, '33.እርሱም ሌሊትንና ቀንን ጸሐይንና ጨረቃንም የፈጠረ ነው:: ሁሉም በየ ምህዋራቸው (ፈለካቸው) ውስጥ ይዋኛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 34, '34. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊት ለማንም ሰው ዘለዓለም መኖርን አላደረግንም:: ታዲያ ብትሞት እነርሱ ዘውታሪዎች ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 35, '35.(ሰዎች ሆይ!) ነፍስ ሁሉ ሞትን ቀማሽ ናት:: ለመፈተንም በክፉም በበጎም እንሞክራችኋለን:: ወደ እኛም ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 36, '36. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም በአላህ የካዱት ሰዎች ባዩህ ጊዜ መሳለቂያ አድርገው እንጂ አይዙህም። እነርሱ በአር-ረህማን መወሳት እነርሱ ከሓዲያን ሲሆኑ: «ያ አማልክቶቻችሁን በክፉ የሚያነሳቸው ይህ ነውን?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 37, '37. ሰው ቸኳይ ሆኖ ተፈጠረ:: ታዓምራቶቼን በእርግጥ አሳያችኋለሁና አታቻኩሉኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 38, '38. «እውነተኞች ከሆናቸሁ ይህ ቀጠሮም መቼ ነው?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 39, '39.እነዚያ በአላህ የካዱ ሰዎች ከፊቶቻቸውና ከጀርቦቻቸው ላይ እሳትን የማይከለክሉበትን እነርሱም የማይረዳዱበትን ጊዜ ቢያውቁ ኖሮ ይህንን አይሉም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 40, '40. ይልቁንም ሰዓቲቱ በድንገት ትመጣቸዋለች:: ታስደነግጣቸዋለችም:: መመለሷንም አይችሉም:: እነርሱም የሚቆይላቸው አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊትም የነበሩት መልዕክተኞች በእርግጥ ተቀለደባቸው፤ በእነዚያ ከእነርሱ ይቀልዱ በነበሩት ይሳለቁበት የነበሩት ቅጣት ሰፈረባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከአር-ረህማን ቅጣት በሌሊትና በቀን የሚጠብቃችሁ ማነው?» በላቸው:: በእውነቱ እነርሱ ከጌታቸው ግሠጼ ከቁርኣን ዘንጊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 43, '43.ለእነርሱ ከእኛ ሌላ የምትከላከልላቸው አማልዕክት አለቻቸውን? ነፍሶቻቸውን መርዳትን አይችሉም:: እነርሱም (ከሓዲያኑ) ከእኛ አይጠብቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 44, '44.በእውነትም እነዚህንና አባቶቻቸውን በእነርሱ ላይ ዕድሜ እስከ ረዘመባቸው ድረስ አጣቀምናቸው:: ተታለሉም። እኛ ምድርን ከጫፎቿ የምናጎድላት ሆነን ስንመጣባት አያዩምን? እነርሱ አሸናፊዎች ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) «የማስፈራራችሁ በተወረድልኝ ብቻ ነው። ግን ደንቆሮዎች በሚስፈራሩበት ጊዜ ጥሪን አይሰሙም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 46, '46. ከጌታህ ቅጣትም ወላፈን ብትነካቸው «ዋ ጥፋታችን! እኛ በዳዮች ነበርን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 47, '47.በትንሳኤ ቀን ትክክለኛ ሚዛኖችን እናቆማለን:: ማንኛይቱም ነፍስ ምንንም አትበደልም:: ስራው የሰናፍጭ ቅንጣት ያክል ቢሆንም እርሷን እናመጣታለን:: ተቆጣጣሪነትም በእኛ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 48, '48. ለሙሳና ለሃሩንም እውነትንና ውሸትን የሚለይን ብርሃንን ለጥንቁቆችም መገሰጫን በእርግጥ ሰጠናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 49, '49. ለእነዚያ ጌታቸውን በሩቅ ለሚፈሩት እነርሱም ከሰዓቲቱ ተጨናቂዎች ለሆኑት መገሰጫን ሰጠን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 50, '50.ይህም (ቁርኣን) ያወረድነው የኾነ ብሩክ መገሰጫ ነው፡ ታዲያ እናንተ ለእርሱ ከሓዲያን ናችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 51, '51. ለኢብራሂምም ከዚያ በፊት ቅን መንገዱን በእርግጥ ሰጠነው:: እኛም በእርሱ ተገቢነት አዋቂዎች ነበርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 52, '52. ለአባቱና ለህዝቦቹ፡- «ይህቺ ቅርጻ ቅርጽ ያቺ እናንተ ለእርሷ ተገዢዎች የሆናችኃት ምንድን ናት?» ባለ ጊዜ መራነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 53, '53. «አባቶቻችንን ለእርሷ ተገዢዎች ሆነው አገኘን።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 54, '54. «እናንተም አባቶቻችሁም በእርግጥ በግልጽ ስህተት ውስጥ ነበራችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 55, '55. «በምሩ መጣህልን? ወይንስ አንተ ከሚቀልዱት ነህ?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 56, '56. (እርሱም) አለ: «አይደለም። ጌታችሁ የሰማያትና የምድር ጌታ ያ የፈጠራቸው ነው:: እኔም በይሃችሁ ላይ ከመስካሪዎች ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 57, '57. «በአላህ እምላለሁ ዟሪዎች ሆናችሁ ከሄዳችሁ በኋላ ጣዖቶቻችሁን ተንኮል እሰራባቸዋለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 58, '58. ዘወር ሲሉም ስብርብሮች አደረጋቸው:: ለእነርሱ የሆነ አንድ ትልቅ ጣዖት ብቻ ሲቀር :: ወደ እርሱ ይመለሱ ዘንድ እርሱን ብቻ ተወው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 59, '59. «በአማልክቶቻችን ይህንን የሰራ ማነው? እርሱ በእርግጥ ከበደለኞች ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 60, '60. «ኢብራሂም የሚባል ጎበዝ (ወጣት) በመጥፎ ሲያነሳቸው ሰምተናል።» ተባባሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 61, '61. «ይመሰክሩበት ዘንድ በሰዎች ዓይን ፊት ላይ አምጡት።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 62, '62. «ኢብራሂም ሆይ! በአማልክቶቻችን ይህንን የሰራህ አንተ ነህን?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 63, '63. «አይደለም:: ይህ ትልቃቸው ሰራው፤ ይናገሩም እንደ ሆነ ጠይቋቸው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 64, '64. ወደ ነፍሶቻቸዉም ተመለሱ: «እናንተ በመጠየቃችሁ በዳዮቹ እናንተው ናችሁ።» ተባባሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 65, '65. ከዚያም በራሶቻቸው ላይ ተገለበጡና «እነዚህ የሚናገሩ አለመሆናቸውን በእርግጥ አውቀሃል።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 66, '66.ኢብራሂምም አላቸው: «ታዲያ ለእናንተ ብታመልኳቸው ምንም የማይጠቅማችሁንና ባታመልኳቸዉም በምንም ነገር የማይጎዳችሁን ጣዖታትን ከአላህ ሌላ ትገዛላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 67, '67. «ኡፍ! ለእናንተም ሆነ ከአላህ ሌላ ለምትገዙት ጣዖታት። አታስተውሉምን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 68, '68. «ሰሪዎች (ተቆርቋሪዎች) እንደ ሆናችሁ ኢብራሂምን በእሳት አቃጥሉት አማልክቶቻችሁንም እርዱ።» አሉ:: (በእሳት ላይ ጣሉትም።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 69, '69. «እሳት ሆይ! በኢብራሂም ላይ ቀዝቃዛና ሰላም ሁኚ።» አልን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 70, '70. በእርሱም ተንኮልን አሰቡ። በጣም ከሳሪዎች አደረግናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 71, '71. እርሱንና ሉጥንም ወደዚያች በውስጡ ለዓለማት በረከትን ወደ አደረግንባት ምድር በመውሰድ አዳንናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 72, '72.ለእርሱም ኢስሐቅን ያዕቆብንም ተጨማሪ አድርገን ሰጠነው:: ሁሉንም መልካሞች አደረግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 73, '73. በትእዛዛችንም ወደ በጎ ስራ የሚመሩ መሪዎች አደረግናቸው:: ወደነሱም መልካም ስራዎችን መስራትን፤ ሶላትንም መስገድን ዘካንም መስጠትን አወረድን:: ለእኛም ተገዢዎች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 74, '74. ሉጥንም ፍርድንና ዕውቀትን ሰጠነው:: ከዚያችም መጥፎ ስራዎችን ትሰራ ከነበረችው ከተማ አዳንነው:: እነርሱ ክፉ ሰዎች አመጸኞች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 75, '75. በችሮታችንም ውስጥ አስገባነው:: እርሱ ከመልካሞች አንዱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 76, '76.(መልዕክተኛችን ሙሐመድ ሆይ!) ኑሕንም ከዚያ በፊት ጌታውን በጠራ ጊዜ የሆነውን አስታውስ:: ለእርሱም ጥሪውን ተቀበልነው፤ እርሱንም ቤተሰቦቹንም ከከባድ ጭንቅ አዳን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 77, '77.ከእነዚያም በታዓምራቶቻችን ከአስተባበሉት ህዝቦች ተንኮል ጠበቅነው:: እነርሱ ክፉ ህዝቦች አመጸኞች ነበሩና ሁሉንም አሰመጥናቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 78, '78.(መልዕክተኛችን ሙሐመድ ሆይ ! ) ዳውድንና ሱለይማንንም በአዝመራው ነገር በሚፈርዱ ጊዜ የህዝቦቸ ፍየሎች ሌሊት በእርሱ ውስጥ በተሰማሩ ጊዜ አስታውስ:: ፍርዳቸውንም አዋቂዎች ነበርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 79, '79. ለሱለይማንም ትክክለኛይቱን ፍርድ አሳወቅነው:: ለሁሉም ጥበብንና እውቀትን ሰጠን:: ተራራዎችን ከዳውድ ጋር የሚያወድሱ ሲሆን ገራን፤ አእዋፍንም እንደዚሁ ገራን ሰሪዎችም ነበርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 80, '80.የብረት ልብስንም ስራ ለእናንተ ከጦራችሁ ትጠብቃችሁ ዘንድ አስተማርነው:: እናንተ አመስጋኞች ናችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 81, '81. ለሱለይማንም ነፋስን በኃይል የምትነፍስ በትእዛዙ ወደዚያች በእርሷ ውስጥ በረከትን ወደ አደረግንባት ምድር (ወደ ሻም) የምትነፍስ ስትሆን (ገራንለት) በነገሩ ሁሉም አዋቂዎች ነበርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 82, '82.ከሰይጣናትም ለእርሱ (ሉልን ለማውጣት) የሚጠልሙንና ከዚያ ሌላ ያለን ስራ የሚሰሩን ገራንለት፤ ለእነርሱም ተጠባባቂዎች ነበርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ!) አዩብንም ጌታውን «እኔ መከራ አገኘኝ:: አንተም ከአዛኞች ሁሉ ይበልጥ አዛኝ ነህ።» ሲል በተጣራ ጊዜ የሆነውን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 84, '84. ለእርሱም ጥሪውን ተቀበልነው፤ ከጉዳትም በእርሱ ላይ የነበረውን ሁሉ አስወገድን:: ቤተሰቦቹንም ከእነርሱም ጋር መሰላቸውን ከእኛ ዘንድ ለችሮታና ለተገዢዎች ለማስገንዘብ ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 85, '85. ኢስማዒልንም፤ ኢድሪስንም፤ ዙልኪፍልንም፤ አስታውስ:: ሁሉም ከታጋሾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 86, '86. በችሮታችንም ውስጥ አስገባናቸው:: እነርሱ ከመልካሞቹ ናቸውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 87, '87. (መልዕክተኛችን ሙሐመድ ሆይ!) የዓሳውንም ባለቤት ተቆጥቶ በሄደ ጊዜ የሆነውን አስታውስ:: በእርሱም ላይ ፈጽሞ የማንፈርድበት መሆናችንን ጠረጠረ:: ዓሳም ዋጠው:: በጨለማዎችም ውስጥ ሆኖ «ካንተ በስተቀር ሌላ አምላክ የለም ጥራት ይገባህ:: እኔ በእርግጥ ከበዳዮች ነበርኩ።» በማለት ተጣራ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 88, '88. ለእርሱም ጥሪውን ተቀበልነው:: ከጭንቅም አዳነው:: ልክ እንደዚሁም ምዕምናንን እናድናለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 89, '89. (መልዕክተኛችን ሙሐመድ ሆይ!) ዘከሪያንም «ጌታዬ ሆይ! ብቻዬን አትተወኝ:: አንተም ከወራሾች ሁሉ በላጭ ነህ።» ሲል ጌታውን በተጣራ ጊዜ አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 90, '90. ለእርሱም ጥሪውን ተቀበልነው:: ለእርሱም የህያን ሰጠነው:: ለእርሱም ሚስቱን አበጀንለት:: እነርሱ በበጎ ስራዎች የሚቻኮሉ ከጃዮችና ፈሪዎች ሆነው የሚለምኑንም ነበሩ:: ለእኛ ተዋራጆችም ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 91, '91.(መልዕክተኛችን ሙሐመድ ሆይ!) ያችንም ብልቷን (ከዝሙት) የጠበቀችውንና በእርሷም ውስጥ ከመንፈሳችን የነፋንባትን እርሷንም ሆነ ልጇን ለዓለማት ተዓምር ያደረግናትን መርየምን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 92, '92. እነዚህ ህግጋት አንድ መንገድ ሲሆኑ በእርግጥ የሃይማኖታችሁ ህግጋት ናቸው:: እኔም ጌታችሁ ነኝና ተገዙኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 93, '93.በሃይማኖታቸዉም ነገር በመካከላቸው ተለያዩ:: ሁሉም ወደ እኛ ተመላሾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 94, '94. እርሱ ያመነ ሆኖ ከበጎ ስራዎች ማንኛውንም የሚሰራም ምንዳውን አይነፍግም፤ እኛም ለእርሱ መዝጋቢዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 95, '95. ባጠፋናትም ከተማ ላይ ዘበት ነው፤ (ወደ ዱኒያ) አይመለሱምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 96, '96.የዕጁጅና መዕጁጅም እነርሱ ከየሸንተረሩ የሚንደረደሩ ሲሆኑ ግድባቸው በተከፈተች ጊዜ ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 97, '97. እውነተኛዉም ቀጠሮ በቀረበ ጊዜ ያንን ጊዜ እነሆ የእነዚያ ከሀዲያን ዓይኖች ይፈጥጣሉ:: «ዋ ጥፍታችን! ከዚያ ቀን በእርግጥ በዝንጋቴ ላይ ነበርን:: በእውነትም በዳዮች ነበርን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 98, '98. (ከሓዲያን ሆይ!) እናንተና ከአላህ ሌላ የምትገዟቸው ጣዖታት የገሀነም ማገዶዎች ናችሁ:: እናንተ ለእርሷ ወራጆች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 99, '99.እነዚህ ጣዖታት አማልክት በነበሩ ኖሮ ገሀነምን አይገቧትም ነበር:: ግን ሁሉም በእርሷ ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 100, '100.እነርሱ በእርሷ ውስጥ ይንሰቀሰቃሉ:: እነርሱም በውስጧ ምንንም አይሰሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 101, '101. እነዚያ ከእኛ መልካሟ ቃል ለእነርሱ ያለፈችላቸው እነዚያ ከእርሷ የተራቁ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 102, '102. ድምጿንም አይሰሙም:: እነርሱም ነፍሶቻቸው በሚሹት ነገር ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 103, '103. ታላቁ ድንጋጤ አያስተክዛቸዉም:: መላእክትም «ይህ ያ ! ትቀጠሩት የነበራችሁት ቀናችሁ ነው።» እያሉ ይቀበሏቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 104, '104. (መልዕክተኛችን ሙሐመድ ሆይ!) ለመጽሐፎች ገፆች እንደሚጠቀለሉ ሁሉ ሰማይን የምንጠቀልልበትን ቀን አስታውስ:: የመጀመሪያን ፍጥረት እንደ ጀመርን እንመልሰዋለን:: ይህን መፈጸሙ የማይቀር ቀጠሮን ቀጠርን:: እኛ የቀጠርነውን ሰሪዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 105, '105. ምድርንም መልካሞቹ ባሮቼ ይወርሷታል ማለትን ከመጽሐፉ (ከተጠበቀው ሰሌዳ) በኋላ በመጽሐፎች በእርግጥ ጽፈናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 106, '106.በዚህ ቁርኣን ውስጥ ያሉት ህግጋት ለአላህ ተገዢ ህዝቦች ሁሉ በቂ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 107, '107. (መልዕክተኛችን ሙሐመድ ሆይ!) ለዓለማት እዝነት አድርገን እንጂ አልላክንህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 108, '108. (መልዕክተኛችን ሙሐመድ ሆይ!) «ያ ወደ እኔ የሚወርደው መልዕክት ‹አምላካችሁ አንድ አምላክ ብቻ ነው።› የሚል ነው:: ታዲያ እናንተ ፍጹም ታዛዦች ናችሁን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 109, '109. (መልዕክተኛችን ሙሐመድ ሆይ!) እምቢ ቢሉም (እንዲህ) በላቸው: «የታዘዝኩትን በእኩልነት አሳውቂያችኋለሁ:: የምትስፈራሩበትም ነገር ቅርብ ወይም ሩቅ መሆኑን አላውቅም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 110, '110. «እርሱ ከንግግር ጩኸቱን ያውቃል:: የምትደብቁትንም ሁሉ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 111, '111. (መልዕክተኛችን ሙሐመድ ሆይ!) «እርሱም ቅጣትን ማቆየት ምናልባት ለእናንተ ፈተናና እስከ ጊዜው መጣቀሚያ እንደ ሆነም አላውቅም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (21, 112, '112. «ጌታዬ ሆይ! በእውነት ፍረድ:: ጌታችንም እጅግ በጣም ሩህሩህን በምትሉት ነገር ላይ መታገዣ ነው።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 1, '1.እናንተ ሰዎች ሆይ! ጌታችሁን (አላህን) ፍሩ:: የሰዓቲቱ እንቅጥቃጤ በጣም ከባድ ነገር ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 2, '2. በምታዩዋት ቀን ሁኔታው አጥቢ ሁሉ ያጠባችውን ልጅ ትዘነጋዋለች። እርጉዝ ሴት ሁሉ እርጉዝዋን ትጨነግፋለች:: ሰዎቹንም በድንጋጤ ብርታት የሰከሩ መስለው ታያቸዋለህ:: እነርሱ ከመጠጥ የሰከሩ ሁው ሳይሆን ግን የአላህ ቅጣት ብርቱ ስለሆነ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 3, '3. ከሰዎች መካከል ያለ ምንም ዕውቀት በአላህ ነገር የሚከራከር፤ ሞገደኛ ሰይጣንንም የሚከተል ሰው አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 4, '4. እነሆ የተከተለውን ሰው እርሱ ያጠመዋል:: ወደ አቃጣይ እሳት ስቃይም ይመራዋል ማለት በእርሱ ላይ ተጽፏል:: (ተወስኖባቸዋል)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 5, '5. ሰዎች ሆይ! ከሞት በኋላ ከመቀስቀስ በመጠራጠር ጉዳይ እንደ ሆናችሁ የመጀመሪያውን (አፈጣጠራችሁን ተመልከቱ። እኛም) ከአፈር ፈጠርናችሁ:: ከዚያ ከፍትወት ጠብታ፤ ከዚያም ከረጋ ደም፤ ከዚያም ከቁራጭ ስጋ ፍጥረትዋ ሙሉ ከሆነችና ሙሉ ካልሆነች (ችሎታችንን) ለእናንተ ልንገልጽላችሁ ፈጠርናችሁ። የምንሻውንም እስከ ተወሰነ ጊዜ ድረስ በማህጸን ውስጥ እናረጋዋለን። ከዚያም ህፃን ሆናችሁ እናወጣችኋለን:: ከዚያም ሙሉ ጥንካሪያችሁን ትደርሱ ዘንድ (እናሳድጋችኋለን):: ከናንተም መካከል በወጣትነቱ የሚሞት ሰው አለ:: ከናንተም መካከል ከዕውቀት በኋላ ምንንም ላያውቅ ወደ ጃጀ ዕድሜ የሚመለስ ሰው አለ:: ምድርንም ደረቅ ሆና ታያታለህ:: በእርሷም ላይ ውሃን ባወረድን ጊዜ ትላወሳለች \\ትነቃነቃለች\\:: ትነፋለችም:: ውበት ካለው የእጽዋት አይነት ሁሉ ታበቅላለችም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 6, '6. ይህ ሁሉ አላህ ፍፁም እውነት፤ እርሱም ሙታንን ህያው የሚያደርግ፤ በሁሉ ነገር ላይ ቻይ በመሆኑ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 7, '7. የሰዓቲቱም መከሰት ፈጽሞ ጥርጣሬ የሌለበት በመሆኑና አላህ በመቃብሮች ውስጥ ያለን ሁሉ የሚቀሰቅስ በመሆኑም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 8, '8. ከሰዎች መካከል ያለ ምንም ዕውቀት ያለ አንዳች ማስረጃም ያለ አብራሪ መጽሐፍም ጎኑን ያጠፈ ሆኖ ከአላህ መንገድ ሊያሳስት በአላህ ነገር የሚከራከር ሰው አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 9, '9. ጎኑን ያጠፈ ሆኖ ከአላህ መንገድ ሊያሳስት (ይከራከራል)። በቅርቢቱ ዓለም ለርሱ ውርደት አለው:: በትንሳኤ ቀንም አቃጣይን (የእሳት) ቅጣት እናቀምሰዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 10, '10. «ይህ እጆችህ ባስቀደሙት ኃጢአት ነው፣ አላህም ለባሮቹ ፈጽሞ በዳይ አይደለም።» (ይባላል።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 11, '11. ከሰዎችም መካከል በሃይማኖት ጫፍ ላይ ሆኖ አላህን የሚገዛ ሰው አለ:: እናም መልካም ነገር ካገኘው በእምነቱ ላይ ይረጋል:: መከራ ካገኘው ግን በፊቱ ላይ ይገለበጣል (ይክዳል):: ይህ አይነቱ ሰው የቅርቢቱን ዓለምም ሆነ የመጨረሻይቱን ዓለም ከሰረ:: ይህ ነው ግልጽ ኪሳራ ማለት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 12, '12. ከአላህ ሌላ የማይጎዳውንና የማይጠቅመውን ይገዛል:: ይህ እርሱ ከእውነት የራቀ ስህተት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 13, '13. ያንን ከጥቅሙ ይልቅ ጉዳቱ ወደ እሱ የሚቀርብን ይገዛል:: ረዳቱ ምንኛ ከፋ! ወዳጁም ምንኛ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 14, '14. አላህ እነዚያን በትክክል ያመኑትንና መልካም ስራዎችን የሰሩትን ሰዎች በስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች ያስገባቸዋል:: አላህም የሚሻውን ነገር ሁሉ በእርግጥ ይሰራልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 15, '15. አላህ (መልዕክተኛውን) ሙሐመድን በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም አይረዳዉም ብሎ የሚያስብ ሰው ካለ ገመድን ወደ ሰማይ ይዘርጋና ከዚያ (ትንፋሹ እስኪቆረጥ) ይታነቅ:: ይህ ተግባሩ ተንኮሉ የሚያስቆጨውን ነገር ያስወግደለት እንደሆነም ይመልከት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 16, '16. ልክ እንደዚሁ (ቁርኣንን) የተብራሩ አናቅጽ አድርገን አወረድነው:: አላህ የሚሻውን ሁሉ ይመራልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 17, '17. እነዚያ በአላህ ያመኑ እነዚያ አይሁዳውያን፤ እነዚያ ምንም እምነት የሌላቸው ሳቢያኖች፤ ክርስቲያኖችም፤ መጁሶችም እነዚያም (ጣዖታትን በአላህ) ያጋሩ ሁሉ አላህ በትንሳኤ ቀን በመካከላቸው በፍርድ ይለያል:: አላህ በነገሩ ሁሉ ላይ በእርግጥ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 18, '18. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ በሰማያትና በምድር ያለው ሁሉ ጸሐይና፤ ጨረቃም፤ ከዋክብትም፤ ተራሮችም፤ ዛፎችም፤ ተንቀሳቃሾችም ፍጡራንና ከሰዎች ብዙዎችም ለእርሱ የሚሰግዱለት መሆኑን አታውቅምን? ብዙዉም በእርሱ ላይ የአላህ ቅጣት ተረጋገጠበት:: አላህ የሚያዋርደው ሰው ለእርሱ ምንም አክባሪ የለዉም:: አላህ የሻውን ይሰራልና:: {1}', '{1} እዚህ የንባብ ሱጁድ (ሱጁዱ ትላዋ) ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 19, '19. እነዚህ በጌታቸው ጉዳይ የተከራከሩ ሁለት ባላጋራዎች ናቸው:: እነዚያ በአላህ የካዱት የእሳት ልብሶች ተለክተውላቸዋል፤ እንዲቀልጥ ከራሶቻቸው ላይ የፈላ ውሃ ይምቧቧባቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 20, '20. በሆዶቻቸው ውስጥ ያለውና ቆዳዎቻቸው በእርሱ ይቀለጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 21, '21. ለእነርሱም (መቅጫ) ከብረት የሆኑ መዶሻዎች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 22, '22. ከጭንቀት ብርታት የተነሳ ከእርሷ ለመውጣት በፈለጉ ቁጥር በእርሷ ውስጥ እንዲመለሱ ይደረጋሉ። «ያን በጣም የሚያቃጥለውን ቅጣት ቅመሱ።» (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 23, '23. አላህ እነዚያን በትክክል ያመኑትንና መልካም ስራዎችን የሰሩትን ሰዎች በስሮቻቸው ጅረት ወንዞች በሚፈሱባቸው ገነቶች ያስገባቸዋል:: በእርሷ ውስጥ የወርቅ አንባሮችና ሉልን ይሸለማሉ:: በእርሷ ውስጥ ልብሶቻቸዉም ከሐር የተሰሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 24, '24. ወደ መልካም ንግግር ተመሩ፣ ወደ ምስጉን መንገድም ተመሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 25, '25. እነዚያ በአላህ የካዱ ሰዎችን ከአላህ መንገድና ከዚያም በውስጡ ነዋሪ ለሆኑትም ሆነ ከሩቅ ለሚመጡት (ሰዎች) እኩል ካደረግነው ከተከበረው መስጊድ የሚከለክሉ ሁሉ (አሳማሚ ቅጣት እንቀጣቸዋልን::) በእርሱም ውስጥ ከትክክለኛ መንገድ በመዘንበል ራሱን በዳይ ሆኖ (ማንኛውንም ነገር) የሚያስብ ከአሳማሚ ቅጣት እናቀምሰዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 26, '26. (መልዕክተኛችን ሙሐመድ ሆይ!) ለኢብራሂም የቤቱን የከዕባን ስፍራ መመለሻ ባደረግንለት (እንዲህ) ባልነውም ጊዜ (የሆነውን አስታውስ): «በኔ ምንንም አታጋራ:: ቤቴንም ለሚዞሩትና ለሚቆሙበት (ለኢባዳ) ለሚያጎነብሱትና በግንባራቸዉም ለሚደፉት (ሩኩዕና ሱጁድ ለሚያደርጉት) ንጹህ አድርግላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 27, '27. «ኢብራሂም ሆይ! በሰዎች መካከል የሐጅን ትእዛዝ አሰማ:: እግረኞችና ከየሩቅ መንገድ በሚመጡ ከሲታ ግመሎች ሁሉ ላይም ሆነዉም ይመጡልሃልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 28, '28. «ለእነርሱ የሆኑ ጥቅሞችን ያገኙ ዘንድና በእነዚያ በታወቁ ቀናትም ውስጥ ከለማዳ እንስሳዎች በሰጣቸው ሲሳይ ላይ የአላህን ስም ያወሱ ዘንድ ይመጡልሃል:: ከእርሷም ብሉ:: ችግረኛ ድሀንም አብሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 29, '29. «ከዚያም (እንደ ጠጉርና ጥፍር ያሉትን) ትርፍ አካላቸውንና እድፋቸውን ያስወግዱ:: ስለቶቻቸውንም በትክክል ይሙሉ:: በጥንታዊዉም ቤት በካዕባ ዙሪያ ይዙሩ።» አልን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 30, '30. ይሀው ነው። የአላህንም ህግጋት የሚያከብር ሁሉ እርሱ እጌታው ዘንድ ለእርሱ በጣም የተሻለ መልካም ነው:: የቤት እንስሳትም በእናንተ ላይ እርም መሆኑ ከሚነበብላችሁ በስተቀር ለእናንተ ተፈቅዳላችኋለች:: ከጣዖታትም ርክሰት ተጠንቀቁ:: ሐሰትንም ቃል ራቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 31, '31. ለአላህ ታዛዦች፤ በእርሱ የማታጋሩና ወደ ቀጥተኞች መንገድ የተዘነበላችሁ ሁኑ:: በአላህ የሚያጋራ ሁሉ ከሰማይ እንደ ወደቀና በራሪ እንደምትነጥቀው ወይም ንፋስ በሩቅ ስፍራ እንደምትጥለው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 32, '32. (ነገሩ) ይህ ነው። የአላህን ሃይማኖታዊ ምልክቶች የሚያከብር ሁሉ ይህ ድርጊቱ አላህን ከሚፈሩ ልቦች የሚፈጸም ጥንቃቄ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 33, '33. ለእናንተ በእርሷ እስከ ተወሰነ ጊዜ ድረስ ጥቅሞች አሏችሁ:: ከዚያም የ(ኡዱሂያ)ማረጃ ስፍራ እጥንታዊው ቤት አጠገብ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 34, '34. ከቤት እንስሳት በሰጣቸው ሲሳይ ላይ የአላህን ስም ብቻ ያወሱ ዘንድ ለህዝቦች ሁሉ (ወደ አላህ) መስዋዕት ማቅረብን ሀይማኖታዊ ሥርአቶችን ደነገግን:: አምላካችሁ አንድ አምላክ ብቻ ነው:: እርሱንም ብቻ ታዘዙ:: ለአላህ ተዋራጆችንም በመልካም ነገር አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 35, '35. እነዚያን አላህ በተወሳ ጊዜ ልቦቻቸው የሚጨነቁትን (የሚፈሩትን)፤ በደረሰባቸዉም መከራ ላይ ታጋሾችን፤ ሰላትንም አስተካክለው ሰጋጆችን፤ ከሰጠናቸዉም ሲሳይ የሚለግሱትን በገነት አብስር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 36, '36. ግመሎችንም ለእናንተ ከአላህ ሃይማኖት ምልክቶች አደረግናቸው:: በእነርሱ ለእናንተ ብዙ መልካም ጥቅሞች አሏችሁ:: በእርሷም ላይ ስታርዷት በሦስት እግሮቿ ቆማ የተሰለፈች ሆና የአላህን ስም አውሱ:: ጎኖቻቸዉም በወደቁ ጊዜ ከእርሷ ብሉ:: በግልጽ ለማኝንም ለልመና የሚያገዳድምንም አብሉ:: ልክ እንደዚሁ ታመሰግኑ ዘንድ ለእናንተ ገራናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 37, '37. አላህን ስጋዎቿም ሆኑ ደሞቿ ፈጽሞ አይደርሰዉም:: ግን ከእናንተ የሆነው ፍራቻ ይደርሰዋል:: እንደዚሁ አላህን በመራችሁ ላይ ልታከብሩት ለእናንተ ገራት:: (መልዕክተኛችን ሙሐመድ ሆይ!) በጎ ሰሪዎችንም አብስር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 38, '38. አላህ ከእነዚያ በእርሱ ካመኑት ላይ ይከላከልላቸዋል። አላህ ከዳተኛንና ውለታ ቢስን ሁሉ አይወድምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 39, '39. ለእነዚያ በከሓዲያን ለሚገደሉት ትክክለኛ አማኞች የተበደሉ በመሆናቸው መጋደል ተፈቀደላቸው:: አላህ እነርሱን በመርዳት ላይ በእርግጥ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 40, '40. ለእነዚያ «ጌታችን አላህ ነው።» ከማለታቸው በስተቀር ያለ አግባብ ከየቀያቸው የተባረሩ ለሆኑት ከራሳቸው ላይ መከላከል ተፈቀደ:: አላህ ሰዎችን ከፊላቸውን በከፊሉ መገፍተሩ ባልነበረ ኖሮ ገዳማት፣ ቤተክርስቲያኖችም፣ ምኩራቦችና በውስጣቸው የአላህ ስም በብዛት የሚወሳባቸው መስጊዶችም በተፈረሱ ነበር:: አላህም ሃይማኖቱን የሚረዳውን ሁሉ በእርግጥ ይረዳዋል:: አላህ ብርቱና ሁሉን አሸናፊ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 41, '41. እነርሱ ማለት እነዚያ በምድር ላይ ብናስመቻቸው (የበላይነትን ሰጥተን ባጎናጸፍናቸው ኖሮ) ሶላትን እንደሚገባ የሚያስተካክሉ፤ ዘካንም የሚሰጡ፤ በደግ ነገርም የሚያዝዙ፤ ከመጥፎ ነገርም የሚከለከሉ ናቸው:: የነገሮች ሁሉ መጨረሻ ወደ አላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢያስተባብሉህም ከእነርሱ በፊት የኑሕ ህዝቦች፣ የዓድና የሰሙድም በእርግጥ አስተባብለዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 43, '43. የኢብራሂምም ህዝቦች የሉጥም ህዝቦች እንደዚሁ አስተባብለዋል፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 44, '44. የመድየንም ሰዎች እንዲሁ አስተባብለዋል:: ሙሳም ተስተባብሏል:: ለከሓዲያንም ጊዜን ሰጠኋቸው:: ከዚያ ያዝኳቸው። ጥላቻዬም እንዴት ነበረ (ተመልከቱ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 45, '45. ከከተሞች መካከል በደለኛ ሆነው ያጠፋናቸው እና በጣሪያዎቻቸው ላይ ወዳቂ የሆኑ ብዙ ናቸው:: ከተራቆተም የውሃ ጉድጓድ ከተገነባም ህንፃ ያጠፋነው ብዙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 46, '46. ለእነርሱም የሚያውቁባቸው ልቦች፤ ወይም የሚሰሙባቸው ጆሮዎች ይኖሯቸው ዘንድ በምድር ላይ አይሄዱምን? እነሆ ዓይኖች አይታወሩም:: እነዚያ በደረቶች ውስጥ ያሉት ልቦች ናቸው የሚታወሩት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ! ) አላህ ቀጠሮውን በፍጹም የማይጥስ ሲሆን ቅጣትን እንድታመጣ ያቻኩሉሃል (ያጣድፉሃል):: በጌታህ ዘንድ አንዱ ቀን ከምትቆጥሩት ቀን እንደ አንድ ሺህ ዓመት የሚመጥን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 48, '48. ከከተማ በዳይ ሆና ጊዜ የሰጠኋትና ከዚያ የያዝኳት የቀጣኋት ብዙ ናት:: የመጨረሻው መመለሻም ወደ እኔ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ ሰዎች ሆይ! እኔ ለእናንተ ግልጽ አስፈራሪ ብቻ ነኝ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 50, '50. እነዚያም በትክክል ያመኑና መልካም ስራዎችን የሰሩ ለእነርሱ ምህረትና ያማረ ሲሳይ አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 51, '51. እነዚያ ከአላህ የሚያመልጡ መስሏቸው ተዓምራታችንን በመንቀፍ የተጉ ሁሉ እነርሱ የእሳት ጓዶች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊት አንድንም መልዕክተኛ ወይም ነብይ አላክንም ባነበበ ጊዜ ሰይጣን በንባቡ ውስጥ የማጥመሚያን ሀሳብ የሚጥል ቢሆን እንጂ:: ወዲያዉም አላህ ሰይጣን የሚጥለውን ማጥመሚያ ቃል ያስወግዳል:: ከዚያም አላህ አናቅጽን ያጠነክራል (ያጸናል):: አላህ ሁሉን አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 53, '53. ሰይጣን የሚጥለውን ነገር ለእነዚያ በልቦቻቸው ውስጥ በሽታ ላለባቸውና ልቦቻቸው ደረቆች ለሆኑት ፈተና ሊያደርግ ይጥላል:: በዳዮችም ከእውነት በራቀ ጭቅጭቅ (ውዝግብ) ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 54, '54. እነዚያም እውቀትን የተሰጡት እርሱ (ቁርኣን) ከጌታህ የሆነ እውነት መሆኑን እንዲያውቁና በእርሱ እንዲያምኑ ልቦቻቸዉም በእርሱ እንዲረኩ (ያጠነክራል):: አላህም እነዚያን በትክክል ያመኑትን ሁሉ ወደ ቀጥተኛው መንገድ በእርግጥ መሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 55, '55. እነዚያ የካዱት ሰዎች ሰዓቲቱ በድንገት እስከምትመጣባቸው ወይም ከደግ ነገር መካን የሆነው ቀን ቅጣት እስከሚመጣባቸው ድረስ በቁርኣን ጉዳይ ከመጠራጠር አያቆሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 56, '56. በዚያ ቀን ንግስናው የአላህ ብቻ ነው:: በመካከላቸውም ይፈርዳል:: እነዚያም ያመኑትና መልካም ስራዎችን የሰሩት በመደሰቻ ገነቶች ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 57, '57. እነዚያም የካዱትና በአናቅጻችንም ያስተባበሉት ሁሉ እነዚያ ለእነርሱ አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 58, '58. እነዚያም ለአላህ ሀይማኖት ሲሉ የተሰደዱና ከዚያም ሲታገሉ የተገደሉ ወይም የሞቱ አላህ መልካምን ሲሳይ በእርግጥ ይሰጣቸዋል:: አላህም እርሱ ከሰጪዎች ሁሉ በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 59, '59. የሚወዱትን መግቢያ ገነትን በእርግጥ ያስገባቸዋል:: አላህም በእርግጥ አዋቂና ታጋሽ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 60, '60. (ነገሩ) ይህ ነው:: ያ በተበደለበት ብጤ (መጠን) የተበቀለና ከዚያ በእርሱ ላይ ግፍ የተዋለበት ሰው አላህ በእርግጥ ይረዳዋል:: አላህ ይቅር ባይና መሓሪ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 61, '61. ይህ የሆነው አላህ ሌሊትን በቀን ውስጥ የሚያስገባ፤ ቀንንም በሌሊት ውስጥ የሚያስገባ (ቻይ) ፤ ሁሉንም ሰሚ፤ ሁሉንም ተመልካች በመሆኑ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 62, '62. ይህ የሆነው አላህም ፍፁም እውነት በመሆኑ፤ ከርሱም ሌላ የሚገዙት ነገር ፍጹም ውሸት በመሆኑና አላህም የሁሉ በላይ ታላቅ በመሆኑ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 63, '63. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ከሰማይ ውሃን ማውረዱንና ከዚያ ምድር የምትለመልም መሆኗን አላየህምን? አላህ ፍጹም ሩህሩህና ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 64, '64. (መልዕክተኛችን ሙሐመድ ሆይ!) በሰማያት ውስጥና በምድር ውስጥ ያለው ሁሉ የእርሱ ብቻ ነው:: አላህ እርሱ ተብቃቂዉና ምስጉኑ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 65, '65. አላህ በምድር ውስጥ ያለን ሁሉ ለእናንተ የገራላችሁ መርከቦችንም በባህር ውስጥ በፈቃዱ የሚንሻለሉ ሲሆኑ የገራላችሁ መሆኑን፤ ሰማይንም በፈቃዱ ካልሆነ በምድር ላይ እንዳትወድቅ የሚይዛት መሆኑን አላየህምን? አላህ ለሰዎች በእርግጥ ሩህሩህና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 66, '66. እርሱም ያ ህያው ያደረጋችሁ ነው:: ከዚያም ይገድላችኋል:: ከዚያም ህያው ያደርጋችኋል:: ሰው በእርግጥ በጣም ከሓዲ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 67, '67. (መልዕክተኛችን ሙሐመድ ሆይ!) ለየህዝቡ ሁሉ እነርሱ የሚሰሩበት የሆነን ስርዓተ ሃይማኖት አድርገናል:: ስለዚህ በነገሩ አይከራከሩህ:: ወደ ጌታህ መንገድም ጥራ:: አንተ በእርግጥ በቅኑ መመርያ ላይ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢከራከሩህም (እንዲህ) በላቸው: «አላህ የምትሰሩትን ሁሉ አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 69, '69. «አላህ በትንሳኤ ቀን በዚያ በእርሱ ትለያዩበት (ትወዛገቡበት) በነበራችሁት ሁሉ በመካከላችሁ ይፈርዳል።» (በላቸው)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 70, '70. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ በሰማይና በምድር ውስጥ ያለን ሁሉ በእርግጥ የሚያውቅ መሆኑን አታውቅምን? ይህ በመጽሐፍ ውስጥ የተመዘገበ እውነት ነው:: ይህም በአላህ ላይ ገር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 71, '71. ከአላህ ሌላም ምንም ማስረጃን ያላወረደበትንና ለእነርሱም በእርሱ እውቀት የሌላቸውን ነገር ያመልካሉ፤ ለበዳዮች ምንም ረዳት የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 72, '72. (መልዕክተኛችን ሙሐመድ ሆይ!) አናቅጻችን የተብራሩ ሆነው በእነርሱ ላይ በሚነበቡ ጊዜ በእነዚያ በአላህ በካዱት ሰዎች ፊት ላይ ጥላቻን ታውቃለህ:: በእነዚያ አናቅጻችንን በሚያነቡት ላይም በኃይል ሊተናኮሏቸው ይቃረባሉ:: ይልቅ ከዚህ የከፋን ነገር ልንገራችሁን? እርሷም እሳት ናት:: አላህ ለእነዚያ በርሱ ለካዱት ሰዎች ሁሉ ቀጥሯታል:: መመለሻነቷ ምን ይከፋ በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 73, '73. ሰዎች ሆይ! አስደናቂ ምሳሌ ተገለጸላችሁ:: ለእርሱም አድምጡት፤ እነዚያ ከአላህ ሌላ የምትገዟቸው ጣዖታት ሁሉ ዝንብን ለመፍጠር ቢሰበሰቡ ፈጽሞ መፍጠር እንኳ አይችሉም:: አንዳችንም ነገር ዝንብ ቢነጥቃቸው ከእርሱ አያስጥሉትም:: ፈላጊዉም (አምላኪው) ተፈላጊዉም (ተመላኪው) ደከሙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 74, '74. አላህን ተገቢ ክብሩን አላከበሩትም:: አላህ በጣም ሀያልና ሁሉን አሸናፊ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 75, '75. አላህ ከመላእክት ውስጥ መልዕክተኞችን ይመርጣል:: ከሰዎችም መካከል እንደዚሁ መልዕክተኞችን ይመርጣል:: አላህ ሁሉን ሰሚ ሁሉን ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 76, '76. በስተፊታቸዉም ሆነ በስተኋላቸው ያለን ሁሉ ያውቃል:: ወደ አላህም ነገሮች ሁሉ ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 77, '77. እናንተ ያመናችሁ ሆይ! ከአላህ ቁጣ ትድኑ ዘንድ በስግደታችሁ አጎንብሱ:: በግንባራችሁም ላይ ተደፉ:: (ሩኩዕና ሱጁድ አድርጉ) ጌታችሁንም በትክክል ተገዙት:: በጎንም ነገር ስሩ:: ልትድኑ ይከጀልላችኋልና:: {1}', '{1} እዚህ የንባብ ሱጁድ (ሱጁድ ትላዋ) ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (22, 78, '78. በአላህም ሃይማኖት ተገቢውን ትግል ታገሉ:: እርሱ መርጧችኋል:: በናንተም ላይ በሃይማኖቱ ውስጥ ምንም ችግር አላደረገባችሁም:: የአባታችሁን የኢብራሂምን ሃይማኖት ተከተሉ:: እርሱ (አላህ) ከዚህ በፊት በነበሩት መጽሐፍትም ሆነ በዚህ ቁርኣን ሙስሊሞች ብሎ ሰይሟችኋል። (ይሄዉም) መልዕክተኛው በእናንተ ላይ መስካሪ እንዲሆን እና እናንተም በሰዎች ላይ መስካሪዎች እንድትሆኑ ነው:: ሶላትንም አስተካክላችሁ ስገዱ:: ዘካንም በአግባቡ ለተገቢው ስጡ:: በአላህም ተጠበቁ:: እርሱ ረዳታችሁ ነውና:: እርሱ ምን ያማረ ጠባቂ፤ ምን ያማረም ረዳት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 1, '1.ምእምናን ፍላጎታቸውን ሁሉ በእርግጥ አገኙ (ተሳካላቸው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 2, '2. እነዚያም በስግደታቸው ውስጥ አላህን ፈሪዎች የሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 3, '3. እነዚያም ከመጥፎ ነገር ሁሉ የራቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 4, '4. እነዚያም ዘካን በአግባቡ ሰጪዎች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 5, '5. እነዚያም እነርሱ ብልቶቻቸውን ጠባቂዎች የሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 6, '6. በሚስቶቻቸው ወይም እጆቻቸው በያዟቸው ሴት ባሪያዎች ላይ ካልሆነ በቀር (ብልቶቻቸውን ጠባቂ የሆኑት)፤ እነርሱ በነዚህ የማይወቀሱ ናቸውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 7, '7. ከዚህ ሌላ በሆነ መንገድ (ስሜታቸዉን ሊያረኩ) የፈለጉ ሰዎች እነዚያ እነርሱ የአላህን ወሰን አላፊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 8, '8. እነዚያም ለአደራዎቻቸውና ለቃል ኪዳናቸው ጠባቂዎች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 9, '9. እነዚያም በስግደቶቻቸው ላይ (ሁለንተናዋን) የሚጠባበቁ የሆኑት', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 10, '10. እነዚያ ወራሾቹ እነርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 11, '11. እነዚያ ፊርደውስን (ላዕላይ ገነትን) የሚወርሱ ናቸው:: እነርሱ በእርሷ ውስጥ ዘውታሪዎች እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 12, '12. በእርግጥ ሰውን (አደምን) ከነጠረ ጭቃ ፈጠርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 13, '13. ከዚያም በተጠበቀ መርጊያ ውስጥ የፍትወት ጠብታ አደረግነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 14, '14. ከዚያም ጠብታዋን (በአርባ ቀን) የረጋ ደም አድርገን ፈጠርን፤ የረጋውንም ደም ቁራጭ ስጋ አድርገን ፈጠርን፤ ቁራጭዋንም ስጋ አጥንቶች አድርገን ፈጠርን:: አጥንቶችንም ስጋን አለበስናቸው። ከዚያም (በዉስጡ ነፍስን በመዝራት) ሌላ ፍጥረት አድርገን አስገኘነው:: ከቅርፅ ሰጪዎችም ሁሉ በላጭ የሆነው አላህ ከሁሉ ላቀ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 15, '15. (ሰዎች ሆይ!) ከዚያም እናንተ ከዚህ በኋላ በእርግጥ ሟቾች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 16, '16. ከዚያም እናንተ በትንሳኤ ዕለት ትቀሰቀሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 17, '17. በእርግጥም ከበላያችሁ ሰባትን ሰማያት ፈጠርን:: ከፍጥረቶቹም ዘንጊዎች አይደለንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 18, '18. ከሰማይም ውሃን በልክ አወረድን:: በምድርም ውስጥ አስቀመጥነው:: እኛም እርሱን በማስወገድ ላይ በእርግጥ ቻዮች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 19, '19. በእርሱም ከዘምባባዎችና ከወይኖች አትክልቶችን ለእናንተ አስገኘንላችሁ:: በውስጧ ለእናንተ ብዙ ፍራፍሬዎች አሏችሁ:: ከእርሷም ትበላላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 20, '20. ከሲና ተራራም የምትወጣ ዛፍ በቅባትና ለበይዎች መባያ በሚሆን ዘይት ተቀላቅላ የምትበቅልን አስገኘንላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 21, '21. (ሰዎች ሆይ!) እናንተም በግመል፤ በከብት በፍየልና በበግ መገምገሚያ አላችሁ:: በሆዶችዋ ውስጥ ካለው ወተት እናጠጣችኋለን:: ለእናንተም በእርሷ ብዙ ጥቅሞች አሏችሁ:: ከእርሷም ትበላላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 22, '22. በእርሷም ላይና በመርከብም ላይ ትጫናላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 23, '23. ኑሕን ወደ ህዝቦቹ በእርግጥ ላክነው። ወዲያዉም «ህዝቦቼ ሆይ! አላህን ብቻ ተገዙ:: ከእርሱ ሌላ ምንም አምላክ የላችሁም:: አትጠነቀቁምን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 24, '24. ከህዝቦቹም እነዚያ ታላላቆቹ ሰዎች አሉ: «ይህ ብጤያችሁ ሰው እንጂ ሌላ አይደለም። በእናንተ ላይ መብለጥን ይፈልጋል። አላህም ቢፈልግ ኖሮ መላእክትን ባወረደ ነበር። ይህንንም የሚለውን በመጀመሪያዎቹ አባቶቻችን አልሰማንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 25, '25. «እርሱ እብደት ያለበት ሰው እንጂ ሌላ አይደለም:: በእርሱም እስከ ጊዜው ድረስ ተጠባበቁ።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 26, '26. ኑሕም «ጌታዬ ሆይ! ስለ አስተባበሉኝ እርዳኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 27, '27. ወደ እርሱ እንዲህ ስንል ላክን: «በተመልካችነታችንና በትእዛዛችን ታንኳን ስራ። ከዚያ ትእዛዛችን በመጣና ምድጃው (እቶኑ) በፈለቀ ጊዜ በውስጧ ከሁሉም ነገር ሁለት ሁለት ዓይነቶችንና ቤተሰቦችህን ከእነርሱ መካከል ጠፊ በመሆኑ ቃል ያለፈበት ብቻ ሲቀር አስገባ። በእነዚያ ራሳቸውን በአላህ በመካድ በበደሉት ሰዎች ጉዳይ አታነጋግረኝ። እነርሱ በውኃ ተሰማጪዎች ናቸውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 28, '28. አንተም አብረውህ ካሉት ፍጡሮች ጋር በታንኳይቱ ላይ በተደላደልክ ጊዜ በል: «ምስጋና ሁሉ ለዚያ ከበደለኛ ህዝቦች ላዳነን አላህ ይገባው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 29, '29. «ጌታዬ ሆይ! ብሩክ የሆነን ማውረድ አውርደኝ:: አንተም ከአደላዳዮች ሁሉ በላጭ ነህና።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 30, '30. በዚህ ውስጥ ለሃያልነታችን አያሌ ተዓምራት አሉበት:: እነሆ እኛ (የኑሕን ሰዎች) ፈታኞች ነበርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 31, '31. ከዚያ ከኋላቸው ሌሎችን የክፍለ ዘመናት ህዝቦች አስገኘን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 32, '32. በውስጣቸዉም ከእነርሱ የሆኑን መልዕክተኛ አላህን ተገዙ ከእርሱ ሌላ ትክክለኛ አምላክ የላችሁም:: አትጠነቀቁምን? በማለት ላክን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 33, '33. ከህዝቦቹም እነዚያ የካዱት ሰዎች በመጨረሻይቱም ቀን መገናኘት ያስተባበሉት በቅርቢቱም ህይወት ያቀማጠልናቸው ታላላቅ ሰዎች አሉ: «ይህ ብጤያችሁ ሰው እንጂ ሌላ አይደለም። ከምትበሉት ምግብ ይበላል፤ ከምትጠጡትም ውሃ ይጠጣል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 34, '34. «የናንተው ብጤያችሁ የሆነን ሰው ብትታዘዙ በእርግጥ የተሞኛችሁ ናችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 35, '35. «‹እናንተ ሞታችሁ አፈርና አጥንቶችም በሆናችሁ ጊዜ እናንተ ከመቃብር ትወጣላችሁ› በማለት ያስፈራራችኋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 36, '36. «ያ የምትስፈራሩበት ነገር ከእውነት ራቀ፤ በጣም ራቀ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 37, '37. «እርሷ (ህይወት) ማለት ቅርቢቱ ህይወታችን ብቻ እንጂ ሌላ አይደለችም:: እንሞታለን። ህያዉም እንሆናለን። እኛም ፈጽሞ ተቀስቃሾች አይደለንም" (አሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 38, '38. «እርሱ በአላህ ላይ ውሸትን የቀጠፈ ሰው እንጂ ሌላ አይደለም:: እኛም በእርሱ አማኞች አይደለንም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 39, '39. መልዕክተኛዉም «ጌታዬ ሆይ! ስላስተባበሉኝ በእነርሱ ላይ እርዳኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 40, '40. አላህም «ከጥቂት ጊዜ በኋላ በጥፋታቸው በእርግጥ ተጸጻቾች ይሆናሉ።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 41, '41. ወዲያዉም (የጥፋት) ጩኸቲቱ በእውነት ያዘቻቸው፤ እንደ ጎርፍ ግብስባሽም አደረግናቸው:: ለበደለኞች ህዝቦችም ከእዝነት መራቅ ተገባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 42, '42. ከዚያም ከእነርሱ በኋላ ሌሎችን የክፍለ ዘመናት ህዝቦች አስገኘን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 43, '43. ማንኛይቱም ህዝብ ጊዜዋን አትቀድምም:: ከጊዜያቸዉም አይቆዩምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 44, '44. ከዚያም መልዕክተኞቻችንን በተከታታይ ላክን፤ ማንኛይቱንም ህዝብ መልእክተኛዋ በመጣላት ቁጥር አስተባበሉት። ከፊላቸውንም በከፊሉ በጥፋት አስከታተልን፤ ወሬዎችም አደረግናቸው፤ ለማያምኑም ህዝቦች ከእዝነታችን መራቅ ተገባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 45, '45. ከዚያ ሙሳንና ወንድሙን ሃሩንን በተአምራታችንና በግልጽ ማስረጃ ላክናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 46, '46. ወደ ፈርዖንና ወደ ጭፍሮቹ ላክናቸው። ድሮውም የኮሩና የተንበጣረሩ ህዝቦችም ነበሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 47, '47. «ህዝቦቻቸው ለኛ ተገዢዎች ሆነው ሳሉ ብጤያችን ለሆኑ ሰዎች እናምናለን?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 48, '48. አስተባበሏቸዉም፤ ከጠፊዎችም ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 49, '49. ሙሳንም ነገዶቹ ይመሩ ዘንድ መጽሐፍን በእርግጥ ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 50, '50. የመርየምን ልጅ ዒሳንና እናቱንም ተዓምር አደረግናቸው:: የመደላደልና የምንጭ ባለቤት ወደ ሆነች ከፍተኛ ስፍራም አስጠጋናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 51, '51. እናንተ መልእክተኞች ሆይ! ከተፈቀዱት ምግቦች ሁሉ ብሉ:: በጎ ስራንም ስሩ:: እኔ የምትሰሩትን ሁሉ አዋቂ ነኝና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 52, '52. ይህችም በአንድ አምላክ የማመን ህግጋት አንድ መንገድ ስትሆን ሃይማኖታችሁ ናት:: እኔም ጌታችሁ ነኝና ፍሩኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 53, '53. ከዚያም ተከታዮቻቸው ሃይማኖታቸውን በመካከላቸው ክፍልፍሎች አድርገው ቆራረጡ፤ ህዝቦች ሁሉ እነርሱ ዘንድ ባለው ሃይማኖት ተደሳቾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 54, '54. (መልዕክተኛችን ሙሐመድ ሆይ!) እስከ ጊዜያቸዉም ድረስ በጥመታቸው ውስጥ ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 55, '55. ከገንዘብና ከልጆች በእርሱ የምንጨምርላቸውን ያስባሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 56, '56. በበጎ ነገሮች የምንቻኮልላቸው እንደሆነ ያስባሉን? አይደለም፤ ይህ ሁሉ እነርሱን ለማዘናጋት መሆኑን አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 57, '57. እነዚያ እነርሱ ጌታቸውን ከመፍራት የተነሳ ተጨናቂዎች የሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 58, '58. እነዚያም እነርሱ በጌታቸው ተዓምራት የሚያምኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 59, '59. እነዚያም በጌታቸው የማያጋሩት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 60, '60. እነዚያም የሚሰጡትን ነገር ሁሉ እነርሱ ወደ ጌታቸው ተመላሾች መሆናቸውን ልቦቻቸው የሚፈሩ ሆነው የሚሰጡ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 61, '61. እነዚያ በመልካም ስራዎች ይጣደፋሉ:: እነርሱም ለርሷ ቀዳሚዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 62, '62. ማንኛይቱንም ነፍስ የችሎታዋን ያህል እንጂ አናስገድዳትም:: እኛም ዘንድ በእውነት የሚናገር መጽሐፍ አለ:: እነርሱም አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 63, '63. በእውነቱ ከሓዲያን ልቦቻቸው ከዚህ መጽሐፍ በዝንጋታ ውስጥ ናቸው:: ለእነርሱም ከዚህ ሌላ እነርሱ ለእርሷ ሰሪዎችዋ የሆኑ መጥፎ ስራዎች አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 64, '64. ቅምጥሎቻቸውንም በቅጣት በያዝናቸው ጊዜ ወዲያውኑ እነርሱ ይወተውታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 65, '65. (ይባላሉም) «ዛሬ አትወትውቱ፤ እናንተ ከእኛ ዘንድ አትረዱምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 66, '66. «አንቀፆቼ በእናንተ ላይ በእርግጥ ይነበቡላችሁ ነበር። እናንተ ግን በተረከዞቻችሁ ላይ ወደ ኋላችሁ ትመለሱ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 67, '67. «በእርሱ (በክልሉ ቤት) ኩሩዎች ሌሊት ተጫዋቾች (ቁርኣንንም) የምትተው ሆናችሁ (ትመለሱ ነበር)።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 68, '68. የቁርኣንን ንግግርን አያስተነትኑምን? ወይስ ለመጀመሪያዎቹ አባቶቻቸው ያልመጣ ነገር መጣባቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 69, '69. ወይስ መልዕክተኛቸውን አላወቁምን? ስለዚህ እነርሱ በእርሱ ከሓዲያን ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 70, '70. ወይስ «በእርሱ ዕብደት አለበት» ይላሉን? እብድ አይደለም። እውነትን ይዞ መጣላቸው:: አብዛኞቻቸዉም ግን እውነትን ጠይዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 71, '71. እውነታው (አላህ) ዝንባሌዎቻቸውን በተከተለ ኖሮ ሰማያትና ምድር በውስጣቸዉም ያለው ሁሉ በእርግጥ በተበላሸ ነበር:: ይልቁንም ክብራቸው ያለበትን ቁርኣን አመጣንላቸው:: እነርሱም ክብራቸውን ዘንጊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 72, '72. ወይስ (መልዕክተኛችን ሙሐመድ ሆይ!) ግብርን ትጠይቃቸዋለህን? የጌታህም ችሮታ ከሁሉም በላጭ ነው:: እርሱም ከሰጪዎች ሁሉ በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 73, '73.(መልዕክተኛችን ሙሐመድ ሆይ!) አንተ ወደ ቀጥተኛው መንገድ በእርግጥ ትጠራቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 74, '74. እነዚያም በመጨረሻይቱ ዓለም የማያምኑት ሰዎች ግን ከትክክለኛው መንገድ ተዘንባዮች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 75, '75. ባዘንላቸውና በእነርሱ ያለውን ጉዳትም ባነሳንላቸው ኖሮ በጥመታቸው ውስጥ የሚዋዥቁ ሆነው ይዘወትሩ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 76, '76. በእርግጥም በቅጣት ያዝናቸው:: ታዲያ ለጌታቸው አልተናነሱም:: የሚዋደቁም አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 77, '77. በእነርሱም ላይ የብርቱ ቅጣት ባለቤት የሆነ ደጃፍን በከፈትንባቸው ጊዜ እነርሱ ያን ጊዜ በእርሱ ተስፋ ቆራጮች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 78, '78. እርሱም ያ መስሚያዎችን፤ ማያዎችንና ልቦችን ለእናንተ የፈጠረላችሁ ነው:: ጥቂትን እንጂ አታመሰግኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 79, '79. እርሱም ያ በምድር ውስጥ የበተናችሁ ነው:: በመጨረሻም ጊዜ ወደ እርሱም ትሰበሰባላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 80, '80. እርሱም ያ ህያው የሚያደርግ የሚገድልም ነው:: የሌሊትና የቀን መተካካትም የእርሱ ነው :: አታውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 81, '81. ይልቁንም የመካ ከሓዲያን ልክ የፊተኞቹ ህዝቦች እንዳሉት ብጤ አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 82, '82. አሉም: «በሞትንና አፈርና አጥንቶች በሆንን ጊዜ እኛ እንደገና ተቀስቃሾች ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 83, '83. «ይህንን ሁኔታ እኛም ሆነ ከእኛ በፊት የነበሩት አባቶቻችን በእርግጥ ተቀጥረናል፤ ይህ የመጀመሪያዎቹ ሰዎች ተረቶች እንጂ ሌላ አይደለም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 84, '84. (መልዕክተኛችን ሙሐመድ ሆይ!) «ምድርና በውስጧ ያለው ሁሉ የማን ነው? የምታውቁ ከሆናችሁ እስቲ ንገሩኝ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 85, '85. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርግጥ የአላህ ነው።» ይሉሃል። «ታዲያ አትገሠጹምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 86, '86. (መልዕክተኛችን ሙሐመድ ሆይ!) «የሰባቱ ሰማያት ጌታ የታላቁም ዐርሽ ጌታ ማን ነው?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 87, '87. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርግጥ አላህ ነው።» ይሉሃል፤ «እንግዲያ አትፈሩትምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 88, '88. «የነገሩ ሁሉ ግዛት በእጁ የሆነ፤ እርሱ የሚጠብቅ በእርሱ ላይ የማይጠበቅ ማን ነው? የምታውቁ ከሆናችሁ (እስቲ መልሱልኝ)» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 89, '89. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርግጥ አላህ ነው።» ይሉሃል፤ «ታዲያ እንዴት ትታለላላችሁ?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 90, '90. ይልቁንም እውነትን አመጣንላቸው እነርሱም በመካዳቸው ውሸታሞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 91, '91. አላህ ምንም ልጅን አልያዘም አልወለደም:: ከእርሱም ጋር አንድም አምላክ የለም:: ሌላ አምላክ በነበረማ አምላኩ ሁሉ የፈጠረውን ነገር በማስተዳደር ከሌላው በተለየ ነበር:: ከፊላቸዉም በከፊሉ ላይ በነገሰ ነበር:: አላህ ከሓዲያን እሱን ከሚመጥኑበት መግለጫ ሁሉ ጠራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 92, '92. ሩቁንና ቅርቡን ሁሉ አዋቂ ነው:: በእርሱ ከሚያጋሩትም ሁሉ ከፍ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 93, '93. (መልዕክተኛችን ሙሐመድ ሆይ!) በል: «ጌታዬ ሆይ! የሚስፈራሩበትን ቅጣት ብታሳየኝ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 94, '94. «ጌታዬ ሆይ! በበደለኞች ህዝቦች ውስጥ አታድርገኝ።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 95, '95. እኛ የምናስፈራራቸውን ነገር ልናሳይህ በእርግጥ ቻዮች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 96, '96. (መልዕክተኛችን ሙሐመድ ሆይ!) በዚያች እርሷ መልካም በሆነችው ጠባይ መጥፎይቱን ነገር መልስ:: እኛ ከሓዲያን የሚሉትን ሁሉ አዋቂዎች ነንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 97, '97. (መልዕክተኛችን ሙሐመድ ሆይ!) (እንዲህ) በል: «ጌታዬ ሆይ ከሰይጣናት ጉትጎታዎች ባንተ እጠበቃለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 98, '98. «ጌታዬ ሆይ! ወደ እኔ ከመጣዳቸው ከመቅረባቸውም ባንተው እጠበቃለሁ።» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 99, '99. አንዳቸውን ሞት በመጣበት ጊዜ ይላል: «ጌታዬ ሆይ! ወደ ምድረ ዓለም መልሱኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 100, '100. «ችላ ብዬ የተውኩትን በጎ ስራ ልሰራ እከጅላለሁና።» (ይላል)። (ይህን ከማለት ይከልከል):: እርስዋ እርሱ ተናጋሪዋ የሆነች ቃል (ብቻ) ናት:: ከበስተፊታቸዉም እስከሚቀሰቀሱበት ቀን ድረስ ግርዶ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 101, '101. በቀንዱም በተነፋ ጊዜ በዚያ ቀን በመካከላቸው ዝምድና የለም። አይጠያየቁምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 102, '102.ሚዛኖቻቸው የከበዱላቸው ሰዎች እነዚያ እነርሱ ፍላጎታቸውን ያገኙ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 103, '103. እነዚያ ሚዛኖቻቸዉም የቀለሉባቸው ሰዎች እነዚያ እነርሱ ነፍሶቻቸውን ያከሰሩ ናቸው፤ በገሀነም ውስጥ ዘውታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 104, '104. ፊቶቻቸውን እሳት ትገርፋቸዋለች:: እነርሱም በእርሷ ውስጥ ከንፈሮቻቸው የተኮማተሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 105, '105. «አንቀፆቼ በእናንተ ላይ የሚነበቡላችሁና በእነርሱ የምታስተባብሉ አልነበራችሁምን?» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 106, '106. (እነርሱም) ይላሉ: «ታላቁ ጌታችን ሆይ! በእኛ ላይ መናጢነታችን አሸነፈችንና ጠማማ ህዝቦች ነበርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 107, '107. «ጌታችን ሆይ! ከእርሷ አውጣንና ወደ ዱንያ መልሰን:: ከዚህ በኋላ ወደ ክህደት ብንመለስ እኛ በዳዮች ነን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 108, '108. አላህም ይላቸዋል: «ወራዶች ሆናችሁ በውስጧ አርፋችሁ ኑሩ እንጂ ፍጹም አታናግሩኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 109, '109. «እነሆ ከባሮቼ መካከል ‹ጌታችን ሆይ! አምነናልና ማረን:: እዘንልንም:: አንተ ከአዛኞች ሁሉ ይበልጥ አዛኝ ነህ› የሚሉ ክፍሎች ነበሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 110, '110. «እኔንም ማውሳትን እስካስረሷችሁ ድረስም ማላገጫ አድርጋችሁ ያዛችኋቸው:: በእነርሱም ላይ ትስቁባቸው ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 111, '111. «እኔ ዛሬ በትዕግስታቸው ምክንያት ፍላጎታቸውን የሚያገኙት እነርሱን ብቻ በማድረግ መነዳኋቸው።» ይላቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 112, '112. «በምድር ውስጥ ስንትን አመታትን ቆያችሁ?» ይላቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 113, '113. «አንድ ቀንን ወይም ከፊል ቀንን ቆየን:: ቆጣሪዎችንም ጠይቅ» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 114, '114. ይላቸዋልም: «እናንተ የቆያችሁትን መጠን የምታውቁ ብትሆኑ ኖሮ (በእሳት ውስጥ ከምትቆዩት ጊዜ አንጻር) ጥቂትን ጊዜ እንጂ አልቆያችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 115, '115. «የፈጠርናችሁ ለከንቱ መሆኑን እናንተም ወደ እኛ የማትመለሱ መሆናችሁን ጠረጠራችሁን? (ለከንቱ የፈጠርናችሁ መሰላችሁን?)።» (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 116, '116. የእውነቱ ንጉስ አላህ ከፍተኛነት ተገባው:: ከእርሱ ሌላ ትክክለኛ አምላክ የለም:: የዚያ የሚያምረው ዐርሽ ጌታም እሱ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 117, '117. ከአላህ ጋር ሌላን አምላክ በእርሱ ማስረጃ የሌለውን የሚገዛ ሁሉ ምርመራው እጌታው ዘንድ ብቻ ነው:: እነሆ ከሓዲያን አይድኑም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (23, 118, '118. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታዬ ሆይ! ማር:: እዘንም:: አንተም ከአዛኞች ሁሉ በላጭ ነህና።» በል፡:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 1, '1.(ሙስሊሞች ሆይ!) (ይህ) ያወረድነውና በእናንተ ላይ (እንድትሰሩበት) የደነገግነው ምዕራፍ ነው:: እርሱ በርሷም ውስጥ ትገሰጹ ዘንድ ግልጽ አናቅጽን አውርደናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 2, '2. ዝሙተኛይቱ ሴትና ዝሙተኛው ወንድ ከሁለቱ እያንዳንዳቸው (ያላገቡ እንደሆኑ) መቶ ግርፋትን ግረፏቸው:: በአላህና በመጨረሻው ቀን የምታምኑ እንደሆናችሁ በእነርሱ ላይ በደነገገው በአላህ ፍርድ ርህራሄ አትያዛችሁ። ሙስሊሞች ሆይ! ቅጣታቸውንም በምትፈጽሙበት ጊዜ ከአማኞች የተወሰኑ ቡድኖች ይገኙበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 3, '3. ዝሙተኛ ወንድ ዝሙተኛን ሴት ወይም በአላህ አጋሪን ሴት እንጂ ሌላን አያገባም (አይፈልግም) :: ዝሙተኛይቱም ሴት ዝሙተኛ ወይም በአላህ አጋሪ ወንድ እንጂ ሌላ አያገባትም (አይፈልጋትም):: ይህም በአማኞች ላይ ተከልክሏል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 4, '4. እነዚያ ጥብቆችን ሴቶች በዝሙት የሚሰድቡ ከዚያ በሰደቡበት አራት ምስክሮች ያላመጡ ሰማንያ ግርፋት ግረፏቸው:: ከእነርሱም ምስክርነትን ለሁልጊዜ አትቀበሉ:: እነዚያም እነርሱ አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 5, '5. እነዚያ ከዚህ በኋላ የተጸጸቱና ሥራቸውን ያሳመሩ ሲቀሩ:: አላህ በጣም መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 6, '6. እነዚያ ሚስቶቻቻውን (በዝሙት) የሚሰድቡ ለነሱም ከነፍሶቻቸው በስተቀር ምስክሮች የሌሏቸው የሆኑ የአንዳቸው ምስክርነት ከእውነተኞች ለመሆናቸው በአላህ ስም አራት ጊዜ ምሎ መመስከር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 7, '7. አምስተኛይቱም ከውሸታሞች ቢሆን በእርሱ ላይ የአላህ እርግማን እንዲሰፍንበት (ምሎ መመስከር ነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 8, '8. «እርሱም ከውሸታሞች ነው።» ብላ አራት ጊዜ በአላህ ስም መመስከሯ ከእርሷ ላይ ቅጣትን ይከላከልላታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 9, '9. አምስተኛይቱም እርሱ ከእውነተኞች ቢሆን በርሷ ላይ የአላህ ቁጣ ይኑርባት ብላ መመስከሯ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 10, '10. (እናንተ ያመናችሁ ሆይ!) በእናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረና አላህ ጸጸትን ተቀባይና ጥበበኛ ባልሆነ ኖሮ (ውሸታሙን ሁሉ በዚሁ አለም ላይ ይገልጸው ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 11, '11. እነዚያ መጥፎን ውሸት ያመጡ ከናንተው የሆኑ ቡድኖች ናቸው:: ለእናንተ ክፉ ነገር እንደሆነ አታስቡት፤ በእውነቱ እርሱ ለእናንተ መልካም ነገር ነው:: ከጭፍሮቹ ለእያንዳንዱ ሰው ከኃጢአት የሠራው ሥራ ዋጋ አለው:: ያም ከእነርሱ ትልቁን ኃጢአት የተሸከመው ለእርሱ ከባድ ቅጣት አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 12, '12. (ውሸቱን) በሰማችሁት ጊዜ አማኞችና ምዕመናት በነፍሶቻቸው ለምን ደግን ነገር አልጠረጠሩም? ለምንስ «ይህ ግልጽ ቅጥፈት ነው።» አላሉም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 13, '13. በእርሱ ላይ ለምን አራትን ምስክሮች አላመጡም? ምስክሮቹንም ካላመጡ እነዚያ አላህ ዘንድ ውሸታሞቹ እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 14, '14. በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም በእናንተ ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ በውስጡ በገባችሁበት ወሬ ምክንያት ታላቅ ቅጣት በእርግጥ በደረሰባችሁ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 15, '15. በምላሶቻችሁም በምትቀባበሉት ጊዜ ለእናንተም በእርሱ እውቀት በሌላችሁ ነገር በአፎቻችሁ በተናገራችሁና አላህ ዘንድ ከባድ ኃጢአት ሆኖ ሳለ ቀላል አድርጋችሁ ባሰባችሁት ጊዜ ከባድ ቅጣት በነካችሁ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 16, '16. በሰማችሁትም ጊዜ: «በዚህ ጉዳይ ልንናገር ለእኛ አይገባንም:: አላህ ጥራት ይገባህ:: ይህ ከባድ ቅጥፈት ነው።» አትሉም ነበርን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 17, '17. አማኞች እንደሆናችሁ ወደ ዚህ መሰል ተግባር ብጤው በፍጹም እንዳትመለሱ አላህ ይገስጻችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 18, '18. ለእናንተም አላህ አናቅጽን ይገልጽላችኋል:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 19, '19. እነዚያ በነዚያ በትክክል በአላህ ባመኑት ሰዎች መካከል መጥፎ ወሬ እንድትስፋፋ የሚወዱ ለእነርሱ በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም አሳማሚ ቅጣት አላቸው:: አላህ ሁሉን ነገር ያውቃል እናንተ ግን አታውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 20, '20. በእናንተም ላይ የአላህ ችሮታውና እዝነቱ ባልነበረ አላህም ሩህሩህና አዛኝ ባልሆነ ኖሮ (ቶሎ ባጠፋችሁ ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 21, '21. እናንተ ያመናችሁሆይ! የሰይጣንን እርምጃዎች አትከተሉ:: የሰይጣንን እርምጃዎች የሚከተል ሰው ሁሉ ኃጢአትን ተሸከመ:: እርሱ በመጥፎና በሚጠላ ነገር ያዛልና፤ በእናንተም ላይ የአላህ ችሮታና እዝነቱ ባልነበረ ኖሮ ከናንተ አንድም ፈጽሞ (ከወንጀል) ባልጠራ ነበር:: ግን አላህ የሚሻውን ሰው ያጠራል:: አላህ ሁሉንም ሰሚ ሁሉንም አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 22, '22. ከናንተም መካከል የችሮታና የክብረት ባለቤቶች የሆኑት ክፍሎች ለቅርብ ዘመዶችና ለድሆችና በአላህም መንገድ ለተሰደዱ ሰዎች ምንንም ነገር ላይሰጡ አይማሉ:: ይቅርታም ያድርጉ:: ጥፋተኞቹንም ይለፉ። አላህ ለእናንተ ሊምር አትወዱምን ? አላህ መሓሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 23, '23. እነዚያ ጥብቆቹንና ከዝሙት ዘንጊዎቹን ምዕምናት የሚሰድቡ ሰዎች ሁሉ በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም ተረገሙ:: ለእነርሱም ታላቅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 24, '24. በእነርሱ ላይ ምላሶቻቸው እጆቻቸውና እግሮቻቸው ይሰሩት በነበሩት ነገር ሁሉ በሚመሰክሩባቸው ቀን ከባድ ቅጣት አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 25, '25. በዚያም ቀን አላህ ተገቢ ዋጋቸውን ይሞላላቸዋል:: አላህም ፍፁም ግልፅ እውነት መሆኑን ያውቃሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 26, '26. መጥፎዎቹ ሴቶች ለመጥፎዎቹ ወንዶች፤መጥፎዎቹ ወንዶችም ለመጥፎዎቹ ሴቶች ብቻ የተገቡ ናቸው:: ጥሩዎቹ ሴቶችም ለጥሩዎቹ ወንዶች፤ ጥሩዎቹ ወንዶችም ለጥሩዎቹ ሴቶች ብቻ የሚገቡ ናቸው:: እነዚህ ጥሩዎቹም መጥፎዎቹ ከሚሉት ነገር ንጹህ የተደረጉ ናቸው:: ለእነርሱ በገነት ምህረትና መልካም ሲሳይ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 27, '27. እናንተ ያመናችሁ ሆይ! እስከምታስፈቅዱና በባለቤቶቹ ላይ ሰላምታን እስከምታቀርቡ ድረስ በሌላ ሰዎች ቤቶች አትግቡ:: ይህ ጉዳይ ለእናንተም መልካም ነው:: እናንተ ትገነዘቡ ዘንድ በዚህ ታዘዛችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 28, '28. በውስጧም አንድንም ሰው ባታገኙ ለእናንተ እስከሚፈቀድላችሁ ድረስ አትግቧት። «ተመለሱ» ከተባላችሁም ተመለሱ:: እርሱ ለእናንተ የተሻለ ነው:: አላህ የምትሠሩትን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 29, '29. መኖሪያ ያልሆኑን ቤቶች ግን በውስጣቸው ለእናንተ ጥቅም ካላችሁ ሳታስፈቅዱ ብትገቡ በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: አላህም የምትገልጹትንም ሆነ የምትደብቁትን ሁሉ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ለአማኞች ንገራቸው አይኖቻቸውን (ያልተፈቀደላቸዉን) ከማየት ይከልክሉ:: ብልቶቻቸውንም ይጠብቁ:: ይህ ለእነርሱ የተሻለ ነው:: አላህ በሚሠሩት ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 31, '31. (መልዕክተኛችን ሙሐመድ ሆይ!) ለምዕመናት (ሴቶችም) ንገራቸው አይኖቻቸውን ይከልክሉ። ብልቶቻቸውንም ይጠብቁ:: ጌጣቸውንም ግልጽ ከሆነው በስተቀር ሆን ብለው አይግለጡ:: ጉፍታዎቻቸውንም በአንገትጌዎቻቸው ያጣፉ:: (የውስጥ) ጌጣቸውንም ለባሎቻቸው ወይም ለአባቶቻቸው ወይም ለባሎቻቸው አባቶች ወይም ለወንዶች ልጆቻቸው ወይም ለባሎቻቸው ወንዶች ልጆች ወይም ለወንድሞቻቸው ወይም ለወንድሞቻቸው ወንዶች ልጆች ወይም ለእህቶቻቸው ወንዶች ልጆች ወይም ለሴቶቻቸው (ሙስሊም ሴቶች) ወይም በእጆቻቸው ለያዙት (ባሪያ) ወይም ከወንዶች ለሴት ጉዳይ የሌላቸው ለሆኑ ተከታዮች ወይም ለእነዚያ በሴቶች ሀፍረተ ገላ ላይ ላላወቁ ህጻኖች ካልሆነ በስተቀር አይግለጹ:: ከጌጣቸዉም የሚሸፍኑት ይታወቅ ዘንድ በእግሮቻቸው አይምቱ:: ምዕመናኖች ሆይ! ከጀሀነም ቅጣት ትድኑ ዘንድ ሁላችሁም ወደ አላህ ተጸጸቱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 32, '32. (ሙስሊሞች ሆይ!) ከናንተ መካከል ትዳር የሌላቸውን ሰዎች አጋቡ:: ከወንዶች ባሮቻችሁና ከሴቶች ባሮቻችሁም ለጋብቻ ብቁ የሆኑትን ክፍሎች አጋቡ:: ድሆች ከሆኑም አላህ ከችሮታው ያከብራቸዋል:: አላህ ስጦታው ሰፊና ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 33, '33. እነዚያም የማግቢያን ጣጣ የማያገኙ ሰዎች አላህ ከችሮታው እስከሚያከብራቸው ድረስ ይጠብቁ። እነዚያንም እጆቻችሁ ከጨበጧቸው አገልጋዮች መካከል ገንዘብ ሰጥተው ነጻ ለመውጣት መጻጻፍን የሚፈልጉትን ከእነርሱ መልካም ነገርን ብታውቁ (ብታዩ) ተጻጻፏቸው:: አላህ ከሰጣችሁ ገንዘብም ስጧቸው:: ሴቶች ባሮቻችሁንም መጠበቅን ከፈለጉ የቅርቢቱን ህይወት ጥቅም ለመፈለግ ብላችሁ በዝሙት ተግባር ላይ አታስገድዷቸው:: የሚያስገድዳቸዉም ሰው አላህ ከመገደዳቸው በኋላ ለተገደዱት መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 34, '34. (ሰዎች ሆይ!) ወደ እናንተ አብራሪ የሆኑን አናቅጽ ከእነዚያ ከበፊታችሁ ካለፉትም ምሳሌዎች ዓይነት ምሳሌን ለጥንቁቆችም መገሰጫን በእርግጥ አወረድን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 35, '35. አላህ የሰማያትና የምድር ብርሃን (አብሪ) ነው፤ የብርሃኑ ምሳሌ በውስጡ መብራት እንዳለባት ዝግ መስኮት፤ መብራቱ በብርጭቆ ውስጥ የሆነ፤ ብርጭቆው ደግሞ ፍጹም ሉላዊ ክብ የምትመስል ምስራቃዊም ምዕራባዊም ካልሆነች፤ ከተባረከች የወይራ ዛፍ ዘይቷ እሳት ባይነካዉም እንኳ ሊያበራ የሚቀርብ ከሆነች ዘይት የሚቃጠል እንደሆነ መብራት ነው:: ይህ በብርሃን ላይ የሆነ ብርሃን ነው:: አላህ ወደ ብርሃኑ የሚሻውን ሰው ይመራል:: አላህም ለሰዎች ምሳሌዎችን ያቀርባል። አላህ በነገሩ ሁሉ ላይ አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 36, '36. አላህ እንዲከበሩና ስሙ በውስጣቸው እንዲወሳ ባዘዘው ቤቶች ውስጥ አወድሱት:: በውስጧ በጧትና በማታ ለርሱ ያጠሩታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 37, '37. አላህን ከማውሳትና ሶላትን ከመስገድ ዘካንም ከመስጠት ንግድም ሽያጭም የማያታልላቸው ልቦችና ዓይኖች በእርሱ የሚገላበጡበትን ቀን የሚፈሩ የሆኑ ሰዎች ያጠሩታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 38, '38. አላህም የሰሩትን ስራ መልካሙን ሊመነዳቸው ከችሮታዉም ሊጨምርላቸው ያጠሩታል:: አላህም ለሚሻው ሁሉ ያለ ግምት ይሰጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 39, '39. እነዚያም በአላህ የካዱት ሰዎች መልካም ስራዎቻቸው በበረሃ ሜዳ እንዳለ ሲሪብዱ ነው:: ሲሪብዱ ውሃ የጠማው ሰው እንደውሃ አስቦት በቀረቡት ጊዜ ምንም ነገር ሆኖ እንደማያገኘው ነው፤ አላህንም እስፍራው ዘንድ ያገኘዋል:: ምርመራውንም ይሞላለታል፤ አላህም ምርመራው ፈጣን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) ወይም መጥፎ ስራዎቻቸው ከበላዩ ማዕበል ከበላዩ ደመና ያለበት ማዕበል በሚሸፍነው ጥልቅ ባህር ውስጥ እንዳሉ ጨለማዎች ነው:: እነዚያ ከፊላቸው ከከፊሉ በላይ ድርብርብ የሆኑ ጨለማዎች ናቸው:: በዚህች የተሞከረ ሰው እጁን ባወጣ ጊዜ ሊያያት አይደርስም:: አላህ ለእርሱ ብርሃንን ያላደረገለት ሰው ሁሉ ለእርሱ ምንጊዜም ምንም ብርሃን የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ በሰማያትና በምድር ላይ ያለ ሁሉ በራሪዎችም ክንፎቻቸውን በአየር ላይ ያንሳፈፉ ሆነው ለእርሱ የሚያጠሩ መሆናቸውን አላወቅህምን? ሁሉም ስግደቱንና ማጥራቱን በእርግጥ አወቀ:: አላህ የሚሰሩትን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 42, '42. የሰማያትም ሆነ የምድር ግዛት የአላህ ነው:: መመለሻም ወደ አላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ደመናን የሚነዳ መሆኑን አላየህምን? ከዚያም ከፊሉን ከከፊሉ ያገናኛል፤ ከዚያም የተደራረበ ያደርገዋል፤ ዝናቡንም ከመካከሉ የሚወጣ ሆኖ ታየዋለህ፤ ከሰማይም ከደመናም በውስጡ ካሉት ጋራዎችም በረዶን ያወርዳል:: በእርሱም የሚሻውን ሰው በጉዳት ይነካል:: ከሻዉም ሰው ላይ ይመልሰዋል:: የብልጭታው ብርሃን ዓይኖችን ሊወስድ ይቀርባል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 44, '44. አላህ ሌሊትንና ቀንን ያገላብጣል፤ በዚህም ለአስተዋዮች በእርግጥ ማስረጃ አለበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 45, '45. አላህም ተንቀሳቃሽን ሁሉ ከውሃ ፈጠረ:: ከእነርሱም መካከል በሆዱ ላይ የሚሄድ አለ፤ ከእነርሱም መካከል በሁለት እግሮቹ ላይ የሚሄድ አለ፤ ከእነርሱም መካከል በአራት እግሩ የሚሄድ አለ:: አላህ የሚሻውን ሁሉ ይፈጥራል:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 46, '46. አብራሪን አናቅጽ በእርግጥ አወረድን፤ አላህ የሚሻውን ወደ ቀጥተኛ መንገድ ይመራዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 47, '47. (አስመሳዮች) «በአላህና በመልዕክተኛው አምነናል ታዘናልም» ይላሉ። ከዚያም ከዚህ በኋላ ከእነርሱ ከፊሉ ይሸሻል:: እነዚያም ትክክለኛ አማኞች አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 48, '48. ወደ አላህና ወደ መልዕክተኛዉም በመካከላቸው ለሚከሰቱ ጉዳዮች ሊፈርድ በተጠሩ ጊዜ ከእነርሱ መካከል ከፊሉ ወዲያውኑ ይሸሻሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 49, '49. እውነቱም (ሐቁ) ለእነርሱ ቢሆን ወደ እርሱ ታዛዣች ሆነው ይመጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 50, '50. በልቦቻቸው ውስጥ በሽታ አለን? ወይስ በነብይነቱ ተጠራጠሩን? ወይስ አላህና መልዕክተኛው በእነርሱ ላይ የሚበድሉ መሆንን ይፈራሉን? ይልቁንም እነዚያ እነርሱ በዳዮቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 51, '51. የምዕምናን ቃል ግን የነበረው ወደ አላህና ወደ መልዕክተኛው በመካከላቸው ሊፈርድ በተጠሩ ጊዜ «ሰማን ታዘዝንም» ማለት ብቻ ነው:: እነዚህ ማለት እነዚያ የፈለጉትን የሚያገኙቱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 52, '52. አላህንና መልዕክተኛውን የሚታዘዝ፤ አላህንም የሚፈራና ቁጣውን የሚጠነቀቀው፤ ፍላጎታቸውን የሚያገኙ እነዚያ እነርሱ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) ለዘመቻ ብታዛቸው በእርግጥ እንደሚወጡ የጠነከሩ መሓላዎቻቸውን በአላህ ስም ይምላሉ፤ «አትማሉ:: የታወቀ የንፍቅና መታዘዝ ነውና:: አላህ በምትሰሩት ነገር ሁሉ ውስጠ አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 54, '54. (መልዕክተኛችን ሙሐመድ ሆይ! ሙስሊሞች ሆይ!) «አላህንና መልዕክተኛውንም ታዘዙ:: ብትሸሹም አትጎዱትም:: በእርሱ ላይ ያለበት የተገደደውን ማድረስ ብቻ ነው:: በእናንተም ላይ ያለባችሁ የተገደዳችሁትን መታዘዝ ብቻ ነው:: ብትታዘዙትም ወደ ቀናው መንገድ ትመራላችሁ በመልዕክተኛው ላይ ግልጽ ማድረስ እንጂ ሌላ የለበትምና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 55, '55. አላህ እነዚያን ከናንተ መካከል በትክክል ያመኑትንና መልካም ስራዎችን የሰሩትን እነዚያን ከእነርሱ በፊት የነበሩትን እንደተካቸው ሁሉ በምድር ላይ በእርግጥ ሊተካቸው፤ ለእነርሱም ያንን የወደደላቸውን ሃይማኖታቸውን ሊያደላድልላቸው፤ ከፍርሃታቸዉም በኋላ ደህናነትን ሊለውጥላቸው የተስፋን ቃል ሰጥቷቸዋል:: በእኔ ምንንም የማያጋሩ ሆነው ሊገዙኝ ነው፤ ከዚያም በኋላ በሱ የካዱ ሰዎች እነዚያ አመጸኞች ማለት እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 56, '56. (ሙስሊሞች ሆይ!) ይታዘንላችሁ ዘንድ ሶላትን አስተካክላችሁ ስገዱ፣ ምጽዋትንም ስጡ፣ መልዕክተኛውንም ታዘዙ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 57, '57. እነዚያን በአላህ የካዱትን በምድር ውስጥ የሚያቅቱ አድርገህ አታስብ፤ መኖሪያቸውም እሳት ናት:: ገሀነም በእርግጥም ምንኛ ትከፋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 58, '58. እናንተ ያመናችሁ ሆይ! እነዚያ እጆቻችሁ የጨበጧቸው ባሮች እነዚያም ከናንተ መካከል ለአካለ መጠን ያልደረሱት (ህፃናት) በሶስት ጊዜ: ከጎህ ስግደት በፊት፤ በቀትር ልብሶቻችሁን በምታወልቁበት ጊዜና ከምሽት ስግደትም በኋላ ወደ እናንተ ለመግባት ሲፈልጉ ያስፈቅዷችሁ:: እነዚህ የእናንተ ሶስት የሐፍረተ ገላ መግለጫ ጊዜያቶች ናቸውና:: ከእነዚህ በኋላ ግን በእናንተም ሆነ በነሱ ላይ (ያለፈቃድ በመግባት) ኃጢአት የለም:: እናንተን ለማገልገል በዙሪያችሁ ዟሪዎች ናቸውና:: ከፊላችሁ በከፊሉ ላይ ዟሪ ነውና፤ ልክ እንደዚሁ አላህ ለእናንተ ህግጋቱን ይገልጽላችኋል:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 59, '59. ከናንተም መካከል ለአቅመ አዳም በደረሱ ጊዜ እነዚያ ከእነርሱ በፊት የነበሩት ታላላቆች እንዳስፈቀዷችሁ ያስፈቅዱ:: ልክ እንደዚሁ አላህ ለእናንተ አንቀፆቹን ያብራራል:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 60, '60. (ሙስሊሞች ሆይ!) እነዚያ ጋብቻን የማይፈልጉት ባልቴቶች በጌጥ የተገለጹ ሳይሆኑ የላይ ልብሶቻቸውን ቢጥሉ በእርሱ ኃጢአት የለባቸዉም:: ግን መጠበቃቸው ለእነርሱ የተሻለ ነው:: አላህም ለሚባለው ሁሉ ሰሚ ለሁሉም አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 61, '61. (ከሰዎች ጋር በመብላት) በዕውር (አይነስውር) ላይ ኃጢአት የለበትም:: በአንካሳም ላይ ኃጢአት የለበትም:: በበሽተኛም ላይ ኃጢአት የለበትም:: በነፍሶቻችሁም ላይ ከቤቶቻችሁ ወይም ከአባቶቻችሁ ቤቶች ወይም ከእናቶቻችሁ ቤቶች ወይም ከውድሞቻችሁ ቤቶች ወይም ከእህቶቻችሁ ቤቶች፤ ወይም ከአባት ወንድሞች አጎቶቻችሁ ቤቶች፤ ወይም ከአባት እህቶች አክስቶቻችሁ ቤቶች ወይም ከእናት ወንድሞች የሹሞቻችሁ ቤቶች፤ ወይም ከእናት እህቶች የሜዎቻችሁ ቤቶች ወይም መክፈቻዎችን ከያዛችሁት ቤት ወይም ከወዳጃችሁ ቤት ብትበሉ ኃጢአት የለባችሁም:: ተሰብስባችሁ ወይም ተለያይታችሁ ብትበሉ በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: ቤቶችንም በገባችሁ ጊዜ ከአላህ ዘንድ የሆነችን የተባረከች መልካም ሰላምታ በነፍሶቻችሁ ላይ ሰላም በሉ:: ልክ እንደዚህ አላህ አናቅጽን ለእናንተ ያብራራል፤ ልታውቁ ይከጅላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 62, '62. (መልዕክተኛችን ሙሐመድ ሆይ!) ትክክለኛ አማኞች ማለት እነዚያ በአላህና በመልዕክተኛው ያመኑት:: ከመልዕክተኛው ጋር በሚሰበሰብ ጉዳይ ላይ በሆኑ ጊዜ እስከሚያስፈቅዱት ድረስ የማይሄዱት ብቻ ናቸው:: እነዚያ የሚያስፈቅዱህ እርሱ እነዚያ በትክክል በአላህና በመልዕክተኛው የሚያምኑት ናቸው:: ለግል ጉዳያቸዉም ፈቃድ በጠየቁህ ጊዜ ከእነርሱ ላሻኸው ሰው ፍቀድለት:: ለእነርሱም ከአላህ ምህረትን ለምንላቸው:: አላህ መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 63, '63. አማኞች ሆይ በመካከላችሁ የመልዕክተኛውን ጥሪ ከፊላችሁ ከፊሉን እንደመጥራት አታድርጉት:: ከናንተ ውስጥ እነዚያን እየተከለሉ በመሽሎክሎክ የሚወጡትን አላህ በእርግጥ ያውቃቸዋል:: እነዚያም ትእዛዙን የሚጥሱ ሁሉ መከራ እንዳትደርስባቸው ወይም አሳማሚ ቅጣት እንዳያገኛቸው ይጠንቀቁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (24, 64, '64. (ሙስሊሞች ሆይ! አስተዉሉ) በሰማያትና በምድር ያለው ሁሉ የአላህ ብቻ ነው:: እናንተ በእርሱ ላይ ያላችሁበትን ሁኔታ በእርግጥ ያውቃል:: ወደ እርሱ የሚመለሱበትን ቀንም ያውቃል:: ከዚያ የሰሩትንም ሁሉ ይነግራቸዋል:: አላህም ነገሩን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 1, '1. ያ ፉርቃንን (እውነትን ከውሸት የሚለየውን) ቁርኣን በባሪያው ላይ ለዓለማት አስፈራሪ ይሆን ዘንድ ያወረደው (አምላክ) ክብሩ ላቀ (ጥራት ተገባው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 2, '2. አላህ ያ የሰማያትና የምድር ንግስና የእርሱ ብቻ የሆነ፤ ልጅንም ያልያዘ (ልጅም የሌለው)፤ በንግስናዉም ተጋሪ የሌለው፤ ሁሉንም ነገር የፈጠረና በትክክልም (በስርአት) የመጠነው አምላክ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 3, '3. ከሓዲያን ከእርሱ ከአላህ ሌላ ምንንም የማይፈጥሩንና እነርሱ ራሳቸው የሚፈጠሩ፤ ለነፍሶቻቸዉም (ከራሳቸው ላይ) ጉዳትን መከላከልም ሆነ ለራሳቸው ጥቅምን ማምጣት (ማስከበር) የማይችሉ፤ ለሞት ማብቃትም ሆነ ህይወትን መለገስና ከሞት መቀስቀስንም የማይችሉን አማልክትን አምላክ አድርገው ያዙ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 4, '4. እነዚያ በአላህ የካዱ ሰዎች «ይህ ቁርኣን እርሱ (ሙሐመድ) በራሱ የቀጠፈውና በእርሱም ላይ ሌሎች ህዝቦች ያገዙት ውሸት እንጂ ሌላ አይደለም።» አሉ። በእርግጥም በደልንና እብለትን ፈጸሙ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 5, '5. «እነዚህ የመጀመሪያ ሰዎች ተረቶች (አፈታሪክ) ናቸው። አስጽፎታል፤ እናም በእርሱ ላይ ጧትና ማታ ትነበብለታለች።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) «ያ በሰማያትና በምድር ውስጥ ያለን ምስጢር የሚያውቀው አወረደው:: እርሱ መሓሪና አዛኝ ነውና።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 7, '7. አሉም: «ይህ መልዕክተኛ ምን አይነት መልዕክተኛ ነው? ምግብ የሚመገብ ወደ ገበያ የሚመላለስ፤ ከእርሱ ጋር አስፈራሪ ይሆን ዘንድ ወደ እርሱ መልአክ (በገሃድ) አይወረድም ኖሯልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 8, '8. «ወይም ወደ እርሱ ድልብ አይሰጠዉምን? ወይም ከእርሷ የሚበላባት አትክልት ለእርሱ አትኖረዉምን?» አሉ። «በዳዮችም ላመኑት የተደገመበትን ሰው እንጂ ሌላን አትከተሉም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 9, '9.(መልዕክተኛችን ሙሐመድ ሆይ!) ላንተ ምሳሌዎችን እንዴት እንዳደረጉልህና ከዚያም እንዴት እንደ ተሳሳቱ ተመልከት:: ወደ እውነት ለመድረስ መንገድንም አይችሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 10, '10. ያ ቢሻ ከዚህ ካሉት የተሻለን ከስሮቻቸው ወንዞች የሚፈሱባቸው አትክልት ስፍራዎችን ላንተ የሚያደርግልህ ህንጻ ቤቶችንም የሚያደርግልህ የሆነው ጌታ ችሮታው በዛ:: (ክብሩ ላቀ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 11, '11. ይልቁንም እነርሱ በትንሳኤ አስተባበሉ:: በትንሳኤ ላስተባበለም ሁሉ አቃጣይ እሳት አዘጋጅተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 12, '12. ከሩቅ ስፍራ ባየቻቸው ጊዜ የእርሷን የቁጭት መገንፈልንና ማናፋትን ይሰማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 13, '13. ከጓደኞቻቸው ጋር (ከሰይጣኖቻቸው ጋር) በአንድ የታሰሩ ሆነዉም ከእርሷ በጠባብ ስፍራ በተጣሉ ጊዜ በዚያ ስፍራ ጥፋትን ይጠራሉ:: (ዋ ጥፋታችን! ይላሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 14, '14. ዛሬማ አንድን ጥፋት ብቻ አትጥሩ:: ይልቁንም ብዙን ጥፋት ጥሩ ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) (እንዲህ) በላቸው: «ይህ የተሻለ ነውን? ወይስ ጥንቁቆቹ ተስፋ የተሰጡት የዘልዓለሟ ገነት?» ገነት ለእነርሱ ምንዳና መመለሻ ሆነች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 16, '16. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነርሱ በውስጧ ዘውታሪዎች ሆነው የሚፈልጉት ሁሉ አለላቸው:: ይህ ተስፋ ከጌታህ ሊለመን የሚገባው ተስፋ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 17, '17. እነርሱንና ከአላህ ሌላ የሚገዟቸውን የሚሰበስብበትንና «እናንተ እነዚህን ባሮቼን አሳሳታችሁን? ወይስ እነርሱው እራሳቸው መንገድን ሳቱ?» የሚልበትን ቀን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 18, '18. (ተመላኪዎቹም): «አላህ ሆይ! ጥራት ይገባህ:: ከአንተ ሌላ ረዳቶችን ልንይዝ አይገባንም:: ግን እነርሱንም ሆነ አባቶቻቸውን መገንዘብን እስከ ተውና ጠፊ ህዝቦችም እስከሚሆኑ ድረስ አጣቀምካቸው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 19, '19. በምትሉትም አማልክቶቻችሁ አስዋሹዋችሁ:: ቅጣቴን መገፍተርንም ሆነ እራሳችሁን መርዳት አትችሉም:: ከናንተም የሚበድልን ሰው ታላቅን ቅጣት እናቀምሰዋለን:: (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊትም ከመልዕክተኞች እነርሱ በእርግጥ ምግብን የሚበሉ በገበያዎችም የሚሄዱ ሆነው እንጂ አላክንም:: ከፊላችሁንም ለከፊሉ ፈተና አድርገናል:: ትታገሳላችሁን? ጌታህም ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 21, '21. እነዚያ መገናኘታችንን የማይጠብቁ ሰዎች «በእኛ ላይ ለምን መላእክት አልወረደም ወይም ጌታችንን ለምን አናይም?» አሉ። በነፍሶቻቸው ውስጥ በእርግጥ ኮሩ። ታላቅንም አመጽ አመጹ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 22, '22. መላዕክትን በሚያዩበት ቀን በዚያ ጊዜ ለአመጸኞች የምስራች የላቸዉም። (መላዕክቱም) «የተከለከለ ክልክል» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 23, '23. ወደ ሰሩት ስራም እናስባለን:: ከዚያም እንደ ተበተነ ትቢያ እናደርገዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 24, '24. የገነት ሰዎች በዚያ ቀን በመርጊያ የተሻሉ በማረፊያም በጣም ያማሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰማይ በደመና የምትቀደድበትንና መላእክትም መውረድን የሚወርዱበትን ቀን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 26, '26. እውነተኛው ንግስና በዚያ ቀን ለአር-ረህማን ብቻ ነው:: በከሓዲያን ላይ አስቸጋሪ ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 27, '27. (መልዕክተኛችን ሙሐመድ ሆይ!) በዳይም «ዋ ምኞቴ! ከመልዕክተኛው ጋር ቀጥተኛን መንገድ ምነው ይዤ በሆነ፤ እያለ (በጸጸት) ሁለት እጆችን የሚነክስበትን ቀን (አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 28, '28. «ዋ ጥፋቴ! እገሌን በወዳጅነት ባልያዝኩ ኖሮ እመኛለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 29, '29. (የእምነት ቃል የሆነው) «ቁርኣን ከመጣልኝ በኋላ ከማስታወስ በእርግጥ አሳሳተኝ።» ይላል:: ሰይጣንም ለሰው አጋላጭ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 30, '30. መልዕክተኛዉም (ሙሐመድ) «ጌታዬ ሆይ! ህዝቦቼ ይህንን ቁርኣን የተተወ ነገር አደረጉት።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 31, '31. ልክ እንደዚሁም ለነብያቱ ሁሉ ከአመጸኞች የሆነ ጠላትን አድርገናል:: መሪነትና ረዳትነት በጌታህ በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 32, '32. እነዚያ በአላህ የካዱ ሰዎችም «ቁርኣንን በእርሱ ላይ ለምን በጠቅላላ በአንድ ጊዜ አልተወረደለትም።» አሉ። ልክ እንደዚሁ በእርሱ ልብህን ልናረጋ (ከፋፍለን በተለያየ አወረድነው):: ቀስ በቀስ መለያየትንም ለየነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 33, '33. (መልዕክተኛችን ሙሐመድ ሆይ!) በየትኛዉም ጥያቄ አይመጡብህም እውነተኛውን መልስና መልካም ፍቹንም የምናመጣልህ ብንሆን እንጅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 34, '34. እነዚያ በፊቶቻቻው ላይ እየተጎተቱ ወደ ገሀነም የሚሰበሰቡት እነዚያ ስፍራቸው የከፋ መንገዳቸዉም የጠመመ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 35, '35. በእርግጥም ለሙሳ መጽሐፍን ሰጠነው:: ከእርሱም ጋር ወንድሙን ሃሩንን ረዳት አደረግንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 36, '36. «ወደ እነዚያም በተዓምራታችን ወደ አስተባበሉት ህዝቦች ሂዱ።» አልናቸው። (አስዋሿቸዉም) ማጥፋትንም አጠፋናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 37, '37. የኑህን ሰዎችም መልዕክተኞችን ባስተባበሉ ጊዜ አሰመጥናቸው:: ለሰዎችም መገሰጫ አደረግናቸው፤ ለበደለኞችም አሳማሚን ቅጣት አዘጋጅተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 38, '38. ዓድንም፤ሰሙድንም፤ የረስ ሰዎችንና በዚህ መካከል የነበሩትንም ብዙ የክፍለ ዘመናት ህዝቦችንም አጠፋን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 39, '39. ሁሉንም (ገሠጽን):: ለእነርሱ ምሳሌዎችን ገለጽን:: ሁሉንም ማጥፋትን አጠፋናቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 40, '40. በዚያችም ክፉ ዝናብን በተዘነበችው ከተማ ላይ (የመካ ከሓዲያን) በእርግጥ መጥተዋል:: የሚያዩዋት አልነበሩምን? በእውነቱ መቀስቀስን የማይፈሩ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) ባዩህም ጊዜ (እንዲህ) እያሉ መሳለቂያ እንጅ ሌላ አያደርጉህም: «ያ አላህ መልዕክተኛ እድርጎ የላከው ይህ ነውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 42, '42. «እነሆ በእርሷ ላይ መታገሳችን (ጽናታችን) ባልነበረ ኖሮ ከአማልክቶቻችን ሊያሳስተን ቀርቦ ነበር።» ሲሉም ይሳለቃሉ:: ወደ ፊትም ቅጣትን በሚያዩ ጊዜ መንገድን በጣም የተሳሳተው ማን እንደ ሆነ በእርግጥ ያኔ ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) ፍላጎቱን አምላኩ አድርጎ የያዘን ሰው አየህን? አንተም በእርሱ ላይ ጠባቂ ትሆናለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 44, '44. ይልቁንም አብዛኛዎቻቸው የሚሰሙ ወይም የሚያውቁ መሆናቸውን ታስባለህን? እነርሱ እንደ እንስሳዎች እንጂ ሌላ አይደሉም:: ከቶውንም እነርሱ ከእንስሳዎች በባሰ መንገድን የተሳሳቱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ ጥላን እንዴት እንደ ዘረጋ አላየህምን? በሻም ኖሮ የረጋ ባደረገው ነበር:: ከዚያ ጸሐይን በእርሱ ላይ ምልክት አደረግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 46, '46. ከዚያም ቀስ በቀስ ወደ እኛ ሰበሰብነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 47, '47. እርሱም ያ ለእናንተ ሌሊትን ልብስ እንቅልፍንም ማረፊያ ያደረገ:: ቀንንም መተኛ ያደረገላችሁ አምላክ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 48, '48. እርሱ (አላህ) ያ ንፋሶችን አብሳሪዎች ሲሆኑ ከዝናቡ በስተፊት የላከ ነው:: ከሰማይም አጥሪ ውሃን አወረድን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 49, '49. በእርሱ የሞተችን ሀገር ህያው ልናደርግበት፤ ከፈጠርነዉም ፍጡር እንስሳዎችንና ብዙ ሰዎችንም ልናጠጣበት አወረድነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 50, '50. ጸጋችንን ይገነዘቡም ዘንድ በመካከላቸው ከፋፈልነው አበላለጥነዉም:: ግን አብዛኛዎቹ ሰዎች ክህደትን እንጂ እንቢ አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 51, '51. በሻንም ኖሮ በየከተማይቱ አስፈራሪን በላክን ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 52, '52. ከሓዲያንን አትታዘዛቸው:: በእርሱም (በቁርኣን) ታላቅን ትግል ታገላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 53, '53. እርሱ ያ ሁለትን ባህሮች አጎራብቶ የለቀቀ ነው:: አንዱ ጥም የሚቆርጥና ጣፋጭ ነው:: ሌላኛው ደግሞ የሚመረግግ ጨው ነው:: በመካከላቸዉም ከመቀላቀል መለያንና የተከለለን ክልል ያደረገ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 54, '54. እርሱም ያ ከውሃ ሰውን የፈጠረ የዝምድናና የአማችም ባለቤት ያደረገው ነው:: ጌታህም ሁሉን ነገር ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 55, '55. ከአላህ ሌላ የማይጠቅማቸውንና የማይጎዳቸውን አካል ይገዛሉ:: ከሓዲ በጌታው ላይ (በማመጽ ለሰይጣን) ረዳት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 56, '56. (መልዕክተኛችን ሙሐመድ ሆይ!) አብሳሪና አስፈራሪ አድርገን እንጂ አላክንህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 57, '57. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእርሱ ላይ ዋጋን በፍጹም አልጠይቃችሁም። ወደ ጌታው መልካም መንገድን ለመያዝ የሻ ሰው ይስራ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 58, '58. በዚያም በማይሞተው ህያው አምላክ ላይ ተመካ፤ ከማመስገንም ጋር አጥራው:: የባሮቹን ኃጢአቶች ውስጥ በማወቅ በእርሱ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 59, '59. ያ ሰማያትንና ምድርን በመካከላቸው ያለውንም ሁሉ በስድስት ቀናት ውስጥ ብቻ የፈጠረ ነው። ከዚያም በዐርሹ ላይ ከፍ አለ:: አር-ረህማን ነው:: ከእርሱም አዋቂን ጠይቅ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 60, '60. ለእነርሱም «ለአር-ረህማን ስገዱ።» በተባሉ ጊዜ «አር-ረህማን ማን ነው? ለምታዘንና ለማናውቀው እንሰግዳለን እንዴ?» ይላሉ። ይህም መራቅን ጨመራቸው። {1}', '{1} እዚህ የንባብ ሱጁድ (ሱጁዱ ትላወህ) ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 61, '61. ያ በሰማይ ቡሩጆችን ያደረገና በእርሷም አንጸባራቂን ጸሐይ አብሪ ጨረቃንም የፈጠረ ጌታ ክብሩ በጣም ላቀ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 62, '62. እርሱም ያ ያመለጠውን ስራ ማስታወስን ለሚፈልግ ወይም ማመስገንን ለሚፈልግ ሌሊትንና ቀንን ተተካኪ ያደረገ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 63, '63. የአር-ረህማን ባሮች እነዚያ በምድር ላይ በዝግታ የሚሄዱት፤ ባለጌዎችም (በክፉ) ባነጋገሯቸው ጊዜ ሰላም የሚሉት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 64, '64. እነዚያም ለጌታቸው በግንባራቸው ተደፊዎችና ቋሚዎች (ሰጋጆች) ሆነው የሚያድሩት ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 65, '65. እነዚያም (እንዲህ) የሚሉት ናቸው: «ጌታችን ሆይ! የገሀነምን ቅጣት ከእኛ ላይ መልስልን ቅጣቷ የማይለይለቅ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 66, '66. «እርሷ መርጊያና መቀመጫ ለመሆን ከፋች!» የሚሉት ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 67, '67. እነዚያም በለገሱ ጊዜ የማያባክኑት የማይቆጥቡትም ናቸው:: በዚህም መካከል ልግስናቸው ትክክለኛ የሆነ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 68, '68. እነዚያም ከአላህ ጋር ሌላን አምላክ የማይገዙት፤ ያችንም አላህ እርም ያደርጋትን ነፍስ ያለ ህግ የማይገድሉ እና የማያመነዝሩት ናቸው:: ይህንን የሚፈጽም ሰው ወንጀለኛ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 69, '69. በትንሳኤ ቀን ቅጣት ይደራረብበታል:: በእርሱም ውስጥ የተዋረደ ሆኖ ዘልአለሙን ይኖራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 70, '70. ተጸጽቶ የተመለሰና ያመነ መልካምንም የሰራ ሰው ብቻ ሲቀር እነዚያም አላህ መጥፎ ስራዎቻቸውን በመልካም ስራዎች ይለውጣል:: አላህም እጅግ መሓሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 71, '71. ተጸጽቶ የተመለሰና መልካምን ተግባር የሰራ እርሱ በአላህ ዘንድ የተወደደን መመለስ ወደ አላህ ይመለሳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 72, '72. እነዚያ በሐሰት የማይጣዱ፤ በውድቅ ቃል (ተናጋሪ) አጠገብም ባለፉ ጊዜ የተከበሩ ሆነው የሚያልፉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 73, '73. እነዚያም በጌታቸው አናቅጽ በተገሠጹ ጊዜ (የተረዱ ተቀባዮች ሆነው እንጂ) ደንቆሮዎችና እውሮች ሆነው በእርሷ ላይ የማይደፉት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 74, '74. እነዚያ «ጌታችን ሆይ! ከሚስቶቻችንና ከዘሮቻችን ለዓይኖች መርጊያን ለእኛ ስጠን፤ አላህን ለሚፈሩትም መሪ አድርገን።» የሚሉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 75, '75. እነዚያ በመታገሳቸው የገነትን ሰገነቶች ይመነዳሉ:: በእርሷም ውስጥ ውዳሴንና ሰላምታን ይሰጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 76, '76. በእርሷ ውስጥ ዘውታሪዎች ሆነው (ይሰጣሉ):: መርጊያና መኖሪያይቱ ገነት አማረች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (25, 77, '77. (መልዕክተኛችን ሙሐመድ) «ጸሎታችሁ ባልነበረ ኖሮ ጌታዬ እናንተን ከምንም አይቆጥራችሁም ነበር:: አስተባበላችሁ:: እናም ወደ ፊት ቅጣት ያዣችሁ ይሆናል።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 1, '1. ጣ፤ሲን፤ሚይም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 2, '2. እነዚህ ግልጽ የሆነው መጽሀፍ አናቅጽ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 3, '3.(መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያን አማኞች ባለ መሆናቸው በቁጭት ነፍስህን እንዳታጠፋ ይፈራልሃል (ያሰጋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 4, '4. ብንሻ ኖሮ በእነርሱ ላይ ከሰማይ ተዓምርን እናወርድና አንገቶቻቸው (መሪዎቻቸው) ለእርሷ ተዋራጆች እናደርጋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 5, '5. ከአር-ረህማን ዘንድ አዲስ የተወረደ ተግሳፅ አይመጣላቸዉም:: ከእርሱ የሚሸሹ ቢሆኑ እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 6, '6. በእርግጥም አስተባበሉ:: የዚያም በእርሱ ይሳለቁበት የነበሩት ወሬዎች ፍጻሜ ይመጣባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 7, '7.ወደ ምድርም በውስጧ ከመልካም በቃይ ጎሳ ብዙን እንዳበቀልን አላዩምን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 8, '8. በዚህ አስደናቂ ምልክት አለበት፤ አብዛኞቻቸዉም ትክክለኛ አማኞች አልነበሩም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 9, '9. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በትክክል ሁሉን አሸናፊና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም ሙሳን «ወደ እነዚያ በደለኛ ህዝቦች ሂድ።» በማለት በጠራው ጊዜ የሆነውን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 11, '11. «ወደ ፈርዖን ህዝቦች አላህን አይፈሩምን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 12, '12. ሙሳም «ጌታዬ ሆይ! እኔ ያስተባብሉኛል ብዬ እፈራለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 13, '13. «ልቤም ይጠባል፤ ምላሴም ይንተባተባል። ስለዚህ ወደ ሃሩንም ላክ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 14, '14. «በተጨማሪም ለእነርሱም በእኔ ላይ (የደም) ወንጀል አላቸው:: ስለዚህ እንዳይገድሉኝም እፈራለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 15, '15. አላህ አለ: «ተው! አይነኩህም ሁለታችሁም በተአምሮታችን ታጅባችሁ ሂዱ። እኛ ከናንተ ጋር ሁነን ሰሚዎች ነንና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 16, '16. «ወደ ፈርዖንም ሂዱና። በሉትም: ‹እኛ የዓለማት ጌታ መልዕክተኞች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 17, '17. «‹የኢስራኢልን ልጆችም ከእኛ ጋር ልቀቅልን።›» (በሉት)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 18, '18. ፈርዖንም አለ፡ «ልጅ ሆንህ በእኛ ውስጥ አላሳደግንህምን? በእኛ ውስጥም ከዕድሜህ ብዙ ዓመታትን አልተቀመጥክምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 19, '19. «ያችን የሰራሃትን ስራስ አልሰራህምን? አንተ ከውለታ ቢሶች ነህ።» (አለ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 20, '20. ሙሳም አለ፡ «ያን ጊዜ እኔም ከተሳሳቱት ሆኜ ሰራኋት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 21, '21. «በፈራኋችሁም ጊዜ ከናንተ ሸሸሁ። ጌታዬም ለእኔ ጥበብን ሰጠኝ:: ከመልዕክተኞችም አደረገኝ:።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 22, '22. «ይህችም የኢስራኢልን ልጆች ባሪያ በማድረግህ በእኔ ላይ የምትመጻድቅባት ጸጋ ናት።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 23, '23. ፈርዖን: «ሙሳ ሆይ! ላከኝ የምትለው የዓለማት ጌታ ምንድን ነው?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 24, '24. ሙሳ፡- «የሰማያት የምድርና በመካከላቸዉም ያለው ፍጡር ሁሉ ጌታ ነው። የምታረጋግጡ ብትሆኑ ነገሩ ይህ ነው።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 25, '25. ፈርዖንም ዙሪያውን ላሉት ሰዎች: «አትሰሙምን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 26, '26. ሙሳ፡- «ጌታችሁና የመጀመሪያዎቹ አባቶቻችሁም ጌታ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 27, '27. ፈርዖን፡- «ያ ወደ እናንተ የተላከው መልዕክተኛችሁ በእርግጥ ዕብድ ነው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 28, '28. ሙሳ፡- «(አላህ) የምስራቅና የምዕራብ በመካከላቸዉም ያለው ነገር ሁሉ ጌታ ነው:: ታውቁ እንደሆናችሁ (እመኑበት)።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 29, '29. ፈርዖን: «ከእኔ ሌላ አምላክን ብትይዝ በእውነቱ ከእስረኞቹ አደርግሃለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 30, '30. ሙሳ፡- «ግልጽ የሆነ አስረጅ ባመጣም እንኳን?» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 31, '31. ፊርዓውን «እንግዲያውስ ከእውነተኞች እንደሆንክ አስረጁን አምጣው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 32, '32. በትሩንም ጣለ:: እርሷም ወዲያውኑ ግልጽ እባብ ሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 33, '33 እጁንም አወጣ እርሷም ወዲያውኑ ለተመልካቾች ነጭ (የምታበራ) ሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 34, '34. ፈርዖንም በዙሪያው ላሉት መማክርት አለ: «ይህ በእርግጥ አዋቂ ድግምተኛ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 35, '35. «ከምድራችሁ በድግምት ሊያወጣችሁ ይፈልጋልና ምንን ታዛላችሁ?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 36, '36. እነርሱም አሉ: «እርሱንና ወንድሙን አቆያቸው:: ወደየከተሞቹ ሁሉ ሰብሳቢዎችን ላክ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 37, '37. «በጣም አዋቂ ድግምተኞችን ሁሉ ያመጡልሃልና።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 38, '38. ድግምተኞችም በታወቀ ቀን ቀጠሮ ተሰበሰቡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 39, '39. ለሰዎቹም ተባለ: «እናንተ ተሰብስባችኋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 40, '40. «ድግምተኞቹን እነርሱ አሸናፊዎች ቢሆኑ እንከተል ዘንድ» ተባለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 41, '41. ድግምተኞቹም በመጡ ጊዜ ለፈርዖን: «እኛ አሸናፊዎች ብንሆን ለእኛ ዋጋ አለን?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 42, '42. እርሱም( ፈርዖን) «አዎን። እናንተ ያን ጊዜ እኔ ዘንድ ከባለሟሎቹ ትሆናላችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 43, '43. ሙሳ ለእነርሱ: «የምትጥሉትን ጣሉ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 44, '44. ገመዶቻቸውንና በትሮቻቸውንም ጣሉ:: «በፈርዖንም ክብር ይሁንብን። እኛ በእርግጥ አሸናፊዎች ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 45, '45. ሙሳም ብትሩን ጣለ:: ወዲያዉም እርሷ የሚያስመስሉትን ሁሉ ትውጣለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 46, '46. ከዚያም ድግምተኞቹ ሰጋጆች ሆነው ሱጁድ አደረጉ(ወረዱ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 47, '47. እነርሱም አሉ፡- «በዓለማት ጌታ አመንን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 48, '48. «በሙሳና በሃሩን ጌታ (አመንን)።» (አሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 49, '49. ፈርዖንም «ለእናንተ ሳልፈቅድላችሁ በፊት ለእርሱ አመናችሁን? እርሱ ያ ድግምትን ያስተማራችሁ ታላቃችሁ ነው። ወደፊትም በእርግጥ የሚያገኛችሁን ታውቃላችሁ:: እጆቻችሁንና እግሮቻችሁን ቀኝና ግራን (በማናጋት) በማፈራረቅ እቆራርጣችኋለሁ:: ሁላችሁንም እሰቅላችኃለሁ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 50, '50. እነርሱም አሉ፡- «ጉዳት የለብንም እኛ ወደ ጌታችን ተመላሾች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 51, '51. «እኛ የምዕምናን መጀመሪያ በመሆናችን ጌታችን ኃጢአቶቻችንን ለኛ ሊምር እንከጅላለን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 52, '52. ወደ ሙሳም «ባሮቼን ይዘህ ሌሊት ሂድ እናንተ የሚከተሏችሁ ናችሁና።» ስንል ላክን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 53, '53. ፈርዖንም በየከተሞቹ ሰብሳቢዎችን (እንዲህ ሲል) ላከ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 54, '54. «እነዚህ ጥቂቶቹ ቡድኖች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 55, '55. «እነርሱም ለእኛ አስቆጪዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 56, '56. «እኛም ብዙዎች ጥንቁቆች ነን።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 57, '57. አወጣናቸዉም፤ ከአትክልቶችና ከምንጮች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 58, '58. ከድልቦችም ከመልካም መቀመጫዎችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 59, '59. ልክ እንደዚሁ ለኢስራኢል ልጆች አወረስናትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 60, '60. ጸሐይዋ ስትወጣም ተከተሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 61, '61. ሁለቱ ቡድኖችም በተያዩ ጊዜ የሙሳ ጓዶች «እኛ (የፈርዖን ሰዎች) የሚደርሱብን ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 62, '62. ሙሳ «በፍፁም! ጌታዬ ከእኔ ጋር ነው። በእርግጥ ይመራኛል።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 63, '63. ወደ ሙሳም «ባህሩን በበትርህ ምታው።» ስንል ላክንበት:: ከዚያ መታውና ተከፈለ፤ ክፍሉም ሁሉ እንደ ታላቅ ጋራ ሆነ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 64, '64. እዚያም ዘንድ ሌሎችን አቀረብን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 65, '65. ሙሳንና ከእርሱ ጋር ያሉትንም ሰዎች ሁሉንም አዳን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 66, '66. ከዚያም ሌሎቹን አሰመጥን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 67, '67. በዚህ ውስጥ ታላቅ ተዐምር አለበት፤ አብዛሀኞቻቸዉም ትክክለኛ አማኞች አልነበሩም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ አላህ እርሱ አሸናፊና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 69, '69. (መልዕክተኛችን ሙሐመድ ሆይ!) በእነርሱም (በህዝቦችህ) ላይ የኢብራሂምን ወሬ አንብብላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 70, '70. ለአባቱና ለህዝቦቹ «ምንን ትገዛላችሁ?» ባለ ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 71, '71. «ጣኦታትን እንገዛለን:: እርሷንም በመገዛት ላይ እንቆያለን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 72, '72. ኢብራሂም አለ፡- «በጠራችኋቸው ጊዜ ይሰሟችኋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 73, '73. «ወይስ ይጠቅሟችኋልን? ወይስ ይጎዷችኋልን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 74, '74. «የለም! ነገር ግን አባቶቻችን ልክ እንደዚሁ ሲሰሩ አገኘን(ና እኛም እነርሱን እንከተላለን።») አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 75, '75. እርሱም አለ: «ትገዙት የነበራችሁትን አስተዋላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 76, '76. «እናንተም የቀድሞዎቹ አባቶቻችሁም እየተገዛችሁት ያለውን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 77, '77. «እነርሱም ጣኦቶቹ ለእኔ ጠላቶች ናቸው:: የዓለማት ጌታ ብቻ ሲቀር:: እርሱማ ወዳጄ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 78, '78. «እርሱ ያ የፈጠረኝ ነው:: እርሱም ይመራኛል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 79, '79. «ያም እርሱ የሚያበላኝና የሚያጠጣኝም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 80, '80. «በታመምኩም ጊዜ እርሱ ያሽረኛል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 81, '81. «ያም የሚገድለኝ ከዚያም ህያው የሚያደርገኝ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 82, '82. «ያም በፍርዱ ቀን ኃጢአቴን ሊምርልኝ የምከጅለው ነው።» (አለ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 83, '83. (ኢብራሂምም) «ጌታዬ ሆይ! እውቀትን ስጠኝ በደጋጎቹም ሰዎች አስጠጋኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 84, '84. «በኋለኞቹም ህዝቦች ውስጥ ለእኔ መልካም ዝናን አድርግልኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 85, '85. «የጸጋይቱን ገነት ከሚወርሱትም ሰዎች አድርገኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 86, '86. «ለአባቴም ኃጢያቱን ማር። እርሱ ከተሳሳቱት ነበርና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 87, '87. «በሚቀሰቀሱበት ቀንም አታዋርደኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 88, '88. «ገንዘብም ሆነ ልጆች በማይጠቅሙበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 89, '89. «ወደ አላህ በንጹህ ልብ የመጣ ቢሆን አንጂ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 90, '90. ገነትም ለጥንቁቆቹ በምትቀረብበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 91, '91. ገሀነምም ለጠማሞቹ በምትገለጽበት ቀን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 92, '92. ለእነርሱም «እነዚያ ትገዟቸው የነበራችሁት የት ናቸው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 93, '93. « ከአላህ ሌላ ሲሆኑ (ትገዟቸው የነበራችሁ) ይረዱዋችኋልን? ወይስ ለራሳቸው ይረዳሉን?» በሚባል ቀን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 94, '94. በውስጧም እነርሱና ጠማሞች በፊቶቻቸው ተጥለው ይንከባለላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 95, '95 የሰይጣንም ሰራዊቶች መላዉም ይጣላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 96, '96. እነርሱም በርሷ ውስጥ የሚከራከሩ ሆነው ይላሉ:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 97, '97. «በአላህ እንምላለን፤ እኛ በግልጽ መሳሳት ውስጥ ነብርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 98, '98. «በዓለማት ጌታ ባስተካከልናችሁ ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 99, '99. «አመጸኞቹም እንጅ ሌላ አላሳሳተንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 100, '100. «ከአማላጆችም ለኛ ምንም የለንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 101, '101. «አዛኝ ወዳጅም የለንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 102, '102 «ለእኛም አንዲት ጊዜ እንኳን የመመለስ እድል በኖረንና ከትክክለኛ አማኞች በሆን እንመኛለን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 103, '103. በዚህ ውስጥ አስደናቂ ግሣጼ አለበት:: አብዛሀኞቻቸዉም ትክክለኛ አማኞች አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 104, '104. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም እርሱ በእርግጥ ሁሉን አሸናፊዉና አዛኙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 105, '105. የኑህ ህዝቦች መልዕክተኞችን አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 106, '106. ወንድማቸው ኑህ ለእነርሱ ባላቸው ጊዜ፡ «አትጠነቀቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 107, '107. «እኔ ለእናንተ ታማኝ መልዕክተኛ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 108, '108. «አላህንም ፍሩ ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 109, '109. «በእርሱም ላይ ምንም ዋጋ አልጠይቃችሁም:: ዋጋዬ ከዓለማት ጌታ ብቻ እንጂ በሌላ ላይ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 110, '110. «አላህንም ፍሩ። ታዘዙኝም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 111, '111. እነርሱም «ወራዶቹ ብቻ የተከተሉህ ሆነህ ላንተ እናምናለን?» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 112, '112. እርሱም አላቸው፡- «ይሰሩት በነበሩት ነገር ምን ዕውቀት አለኝና?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 113, '113. «ምርመራቸው በጌታዬ ላይ እንጅ በሌላ ላይ አይደለም:: ብታውቁ ኖሮ ይህንን ትረዱት ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 114, '114. «እኔ አማኞችን አባራሪ አይደለሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 115, '115. «እኔም እኮ ግልጽ አስፈራሪ እንጂ ሌላ አይደለሁም።» (አለ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 116, '116. «ኑህ ሆይ! ከምትለው ባትከለከል በእርግጥ ከሚወገሩት ትሆናለህ።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 117, '117. እርሱም አለ፡- «ጌታየ ሆይ! ህዝቦቼ አስተባበሉኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 118, '118. «በእኔና በእነርሱም መካከል ተገቢ ፍርድን ፍረድ:: ከእነርሱ አድነኝም:: ከእኔ ጋር ያሉትን አማኞችም አድን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 119, '119. እርሱንም ሆነ ከእርሱ ጋር ያሉትን ሁሉ በተሞላው መርከብ ውስጥ አዳንን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 120, '120. ከዚያም በኋላ ቀሪዎቹን አሰመጥን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 121, '121. በዚህ ውስጥ ታላቅ ግሣጼ አለበት፤ አብዛሀኞቻቸዉም ትክክለኛ አማኞች አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 122, '122. ጌታህም እርሱ በእርግጥ ሁሉን አሸናፊዉና አዛኙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 123, '123. ዓድ መልዕክተኞችን አስተባበለች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 124, '124. ወንድማቸው ሁድ ለእነርሱ ባላቸው ጊዜ: «አትጠነቀቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 125, '125. «እኔ ለእናንተ ታማኝ መልዕክተኛ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 126, '126. «አላህን ብቻ ፍሩ ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 127, '127. «በእርሱም ላይ ምንም ዋጋ አለምናችሁም:: ዋጋዬ በዓለማት ጌታ ላይ ብቻ እንጅ በሌላ ላይ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 128, '128. «የምትጫወቱ ሆናችሁ በከፍተኛ ስፍራ ሁሉ ላይ ምልክት ትገነባላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 129, '129. «የውሃ ማጠራቀሚያዎችንና ህንፃዎችንም ለዘላለም መኖርን የምትከጅሉ ሆናችሁ ትሰራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 130, '130. «በቀጣችሁም ጊዜ ጨካኞች ሆናችሁ ትቀጣላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 131, '131. «አላህንም ፍሩ። ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 132, '132. «ያንንም በምታውቁት ጸጋ ያጣቀማችሁን ጌታን (አላህን) ፍሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 133, '133. «በእንስሳዎችና በልጆችም ያጣቀማችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 134, '134. «በአትክልቶችና በምንጮችም ያጣቀማችሁን ጌታን (አላህን) ፍሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 135, '135. «እኔ በእናንተ ላይ የታላቅን ቀን ቅጣት እፈራለሁና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 136, '136. እነርሱም አሉ: «ብትገስጽም ወይም ከገሳጮች ባትሆንም በእኛ ላይ እኩል ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 137, '137. «(ያለንበትን አንለቅም)። ይህ የፊተኞቹ ሰዎች መንገድ እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 138, '138. «እኛም የምንቀጣ አይደለንም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 139, '139. አስተባበሉትም፤ አጠፋናቸዉም፤ በዚህም ውስጥ እርግጠኛ ግሣጼም አለበት:: አብዛኞቻቸዉም ምዕምናን አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 140, '140. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም እርሱ በእርግጥ አሸናፊውና አዛኙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 141, '141. የሰሙድ ህዝቦች መልዕክተኞችን አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 142, '142. ወንድማቸው ሷሊህ ለእነርሱ ባላቸው ጊዜ: «አትጠነቀቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 143, '143. «እኔ ለእናንተ ታማኝ መልዕክተኛ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 144, '144. «አላህን ፍሩ ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 145, '145. «በእርሱም ላይ ምንም ዋጋ አልለምናችሁም:: ዋጋዬ በዓለማት ጌታ ላይ ብቻ እንጂ በሌላ ላይ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 146, '146. «በዚያ እዚህ ባለው ጸጋ ውስጥ የረካችሁ ሆናችሁ ትቀራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 147, '147. «በአትክልቶችና በምንጮች ውስጥ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 148, '148. «በአዝመራዎችም ፍሬዋ የበሰለ በሆነች ዘንባባም ውስጥ ትቀራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 149, '149. «ብልሆች ሆናችሁ ከጋራዎች ቤቶችንም ትጠርባላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 150, '150. «አላህንም ፍሩ፤ ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 151, '151. «የወሰን አላፊዎችንም ትዕዛዝ አትከተሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 152, '152. «የእነዚያን በምድር ላይ የሚያጠፉትንና የማያበጁትን (ትዕዛዝ አትከተሉ)።» (አለ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 153, '153. እነርሱም አሉ: «አንተ በብዙ ከተደገመባቸው ሰዎች ብቻ ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 154, '154. «አንተ ብጤያችን ሰው እንጂ ሌላ አይደለህም። ከእውነተኞችም ከሆንክ ተዐምርን አምጣ።» (አሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 155, '155. እርሱም አለ: «ይህች ግመል ናት:: ለእርሷ የመጠጥ ፋንታ አላት:: ለእናንተም የታወቀ ቀን ፋንታ አላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 156, '156. «በክፉም አትንኳት የታላቅ ቀን ቅጣት ይይዛችኋልና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 157, '157. ወጓትም:: ወዲያው ተጸፃቾች ሆነው አነጉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 158, '158. ቅጣትም ያዛቸው በዚህም ውስጥ አያሌ ግሣጼ አለበት:: አብዛኞቻቸዉም አማኞች አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 159, '159. ጌታህም እርሱ በእርግጥ ሁሉን አሸናፊውና አዛኙ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 160, '160. የሉጥ ህዝቦች መልዕክተኞችን አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 161, '161. ወንድማቸው ሉጥ ለእነርሱ ባለ ጊዜ: «አትጠነቀቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 162, '162. «እኔ ለእናንተ ታማኝ መልዕክተኛ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 163, '163. «አላህንም ፍሩ ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 164, '164. «በእርሱም ላይ ምንም ዋጋ አለምናችሁም:: ዋጋዬ በዓለማት ጌታ ላይ እንጅ በሌላ ላይ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 165, '165. «ከዓለማት ሰዎች መካከል የተለየ ወንዶችን ትገናኛላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 166, '166. «ከሚስቶቻችሁም ጌታችሁ ለእናንተ የፈጠረላችሁን ትተዋላችሁን? በእውነት እናንተ ወሰን አላፊዎች ህዝቦች ናችሁ።» (አለ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 167, '167. እነርሱም አሉ: «ሉጥ ሆይ! ከዚህ ነገርህ ባትከለከል በእርግጥ በሀይል ከአገር ከሚወጡት ትሆናለህ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 168, '168. እርሱም አለ: «እኔ ስራችሁን ከሚጠሉት ሰዎች አንዱ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 169, '169. «ጌታዬ ሆይ! እኔንም ሆነ ቤተሰቦቼን እኒህ ህዝቦች ከሚሰሩት ስራ ቅጣት አድነን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 170, '170. እርሱንም ሆነ ቤተሰቦቹንም በጠቅላላ አዳንናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 171, '171. በቀሪዎቹ ውስጥ የሆነች አሮጊት ስተቀር (እርሷ ግን ጠፋች)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 172, '172. ከዚያም ሌሎቹን አጠፋን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 173, '173. በእነርሱም ላይ የድንጋይን ዝናብን አዘነብንባቸው:: የተስፋራሪዎችም ዝናብ ከፋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 174, '174. በዚህ ውስጥ አስደናቂ ተዐምር አለበት:: አብዛኞቻቸዉም ምዕምናን አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 175, '175. ጌታህ እርሱ አሸናፊውና አዛኙ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 176, '176. የአይካ ሰዎች መልዕክተኞችን አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 177, '177. ወንድማቸው ሹዐይብ ለእነርሱ ባላቸው ጊዜ: «አትጠነቀቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 178, '178. «እኔ ለእናንተ ታማኝ መልዕክተኛ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 179, '179. «አላህን ፍሩ፤ ታዘዙኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 180, '180. «በእርሱም ላይ ምንም ዋጋ አልጠይቃችሁም፤ ዋጋዬ በዓለማት ጌታ ላይ እንጂ በሌላ ላይ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 181, '181. «ስፍርንም ሙሉ:: ከአጎዳዮችም አትሁኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 182, '182. «በትክክለኛ ሚዛንም መዝኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 183, '183. «ሰዎችንም ነገሮቻቸውን አታጉድሉባቸው:: በምድርም ላይ አጥፊዎች ሆናችሁ አታበላሹ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 184, '184. «ያንንም የፈጠራችሁን የቀድሞዎቹንም ፍጡሮች የፈጠረውን ፍሩ።» (ባለ ጊዜ የሆነውን አስታውስ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 185, '185. እነርሱም አሉ: «ሹዓይብ ሆይ! አንተ በብዛት ከተደገመባቸው ሰዎች አንዱ ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 186, '186. «አንተም ብጤያችን ሰው እንጂ ሌላ አይደለህም:: እነሆ ከውሸታሞች ነህ ብለን እንጠረጥርሃለን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 187, '187. «ከእውነተኞችም እንደሆንክ በእኛ ላይ ከሰማይ ቁራጭን ጣልብን።» (አሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 188, '188. «ጌታዬ የምትሰሩትን ሁሉ አዋቂ ነው።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 189, '189. አስተባበሉትም የጥላይቱ ቀን ቅጣትም ያዛቸው፤ እርሱ የከባድ ቀን ቅጣት ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 190, '190. በዚህ ውስጥ አስደናቂ ተዐምር አለበት:: አብዛዛቻቸዉም አማኞች አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 191, '191. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም እርሱ በእርግጥ አሸናፊዉንና አዛኙ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 192, '192. (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱም (ቁርኣን) በእርግጥ ከዓለማት ጌታ የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 193, '193. እርሱን ታማኙ መንፈስ ጂብሪል አወረደው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 194, '194. ከአስፈራሪዎች ነብያት ትሆን ዘንድ በልብህ ላይ አወረደው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 195, '195. ግልጽ በሆነ ዐረብኛ ቋንቋ፤ (አወረደው)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 196, '196. እርሱም (ቁርኣን) በቀድሞዎቹ መጽሐፍት ውስጥ የተወሳ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 197, '197. የኢስራኢል ልጆች ሊቃውንት የሚያውቁት መሆኑ ለእነርሱ (ለመካ ከሓዲያን) ምልክት አይሆናቸዉም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 198, '198. ከአዕጀሞች ባንዱ ላይ ባወረድነዉም ኖሮ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 199, '199. በእነርሱ ላይ ቢያነበዉም በእርሱ አማኞች አይሆኑም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 200, '200. እንድዚሁ ማስተባበልን በተንኮለኞች ልቦች ውስጥ አስገባነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 201, '201. አሳማሚ ቅጣትን እስከሚያዩ ድረስ በእርሱ አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 202, '202. እነርሱ የማያውቁ ሲሆኑ ቅጣቱ ድንገት እስከሚመጣባቸዉም ድረስ (አያምኑም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 203, '203. በመጣባቸው ጊዜ: «እኛ የምንቆይ ነን?» እስከሚሉም (አያምኑም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 204, '204. በቅጣታችን ያቻኩላሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 205, '205. (መልዕክተኛችን ሙሐመድ ሆይ! ) አየህን? ብዙ ዓመታትን ብናጣቅማቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 206, '206. ከዚያም ያ ይስፈራሩበት የነበሩት ቢመጣባቸው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 207, '207. ይጣቀሙበት የነበሩት ሁሉ ከእነርሱ ምንም አያብቃቃቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 208, '208. አንዲትንም ከተማ ለእርሷ አስፈራሪዎች ያሏት (እና ያስተባበለች) ሆና እንጂ አላጠፋንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 209, '209. ይህች ግሣጼ ናት:: በዳዮችም አልነበርንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 210, '210. ሰይጣናትም እርሱን ቁርኣንን አላወረዱትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 211, '211. ለእነርሱም አይገባቸዉም፤ አይችሉምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 212, '212. እነርሱ የመላዕክትን ንግግር ከመስማት የተከለከሉ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 213, '213. (መልዕክተኛችን ሙሐመድ ሆይ!) ከአላህም ጋር ሌላን አምላክ አትገዛ:: ከሚቀጡት ትሆናለህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 214, '214. (መልዕክተኛችን ሙሐመድ ሆይ!) ቅርቦች ዘመዶችህንም አስጠንቅቅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 215, '215. (ሙሐመድ ሆይ!) ከምዕምናንም ለተከተሉህ ሰዎች ክንፍህን ዝቅ አድርግ ልዝብ ሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 216, '216. (መልዕክተኛችን ሙሐመድ ሆይ!) እንቢ ካሉህ «እኔ ከምትሰሩት ወንጀል ሁሉ ንጹህ ነኝ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 217, '217. (ሙሐመድ ሆይ!) አሸናፊና አዛኝ በሆነው ጌታህ ላይም ተጠጋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 218, '218. በዚያ ለሶላት በምትቆም ጊዜ በሚያይህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 219, '219. በሰጋጆች ውስጥ መዘዋወርህንም (በሚያየው ጌታህ ላይ ተጠጋ::)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 220, '220. እነሆ እርሱ (አላህ) ሁሉ ሰሚና ሁሉን አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 221, '221. ሰይጣናት በማን ላይ እንደሚወርዱ ልንገራችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 222, '222. በውሸታም ኃጢአተኛ ሁሉ ላይ ይወርዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 223, '223. የሰሙትን ወደ ጠንቋዮች ይጥላሉ:: አብዛኞቻቸዉም ውሸታሞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 224, '224. (መልዕክተኛችን ሙሐመድ ሆይ!) ባለ ቅኔዎችንም ጠማማዎች ይከተሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 225, '225. እነርሱ (በንግግር) ሸለቆ ሁሉ የሚዋልሉ መሆናቸውን አታይምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 226, '226. እነርሱም የማይሰሩትን ነገር የሚናገሩ መሆናቸውን አታይምን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (26, 227, '227. እነዚያ ያመኑና መልካም ስራዎችን የሰሩ አላህን በብዛት ያወሱ ከተበደሉም በኋላ (በቅኔ) የተከላከሉ ሲቀሩ፤ (እነርሱ አይወቀሱም)። እነዚያም የበደሉ ከሞቱ በኋላ እንዴት ያለን መመለስ እንደሚመለሱ በእርግጥ ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 1, '1. ጣ፤ ሲን፤ ይህ ከቁርኣኑና ከገላጩ መጽሐፍ አናቅጽ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 2, '2. ለምዕምናን መሪና ብስራት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 3, '3. ለእነዚያ ሶላትን ለሚሰግዱት፤ ዘካንም ለሚሰጡ፤ እነርሱም በመጨረሻይቱ ሕይወት እነርሱ የሚያረጋግጡ ለሆኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 4, '4. እነዚያ በመጨረሻይቱ ዓለም የማያምኑት ለእነርሱ ክፉ ሥራዎቻቸውን ሸለምንላቸው:: ስለዚህ እነርሱ ይዋልላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 5, '5. እነርሱ እነዚያ ክፉ ቅጣት ያላባቸው ናቸው:: እነርሱም በመጨረሻይቱ ዓለም እነርሱ በጣም ከከሳሪዎቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተም ቁርኣንን ጥበበኛና አዋቂ ከሆነው ጌታህ ዘንድ በእርግጥ ትስሰጣለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳ ለቤተሰቦቹ «እኔ እሳትን አየሁ ከእርሷ ወሬን አመጣላችኋለሁ፤ ወይም ትሞቁ ዘንድ የተለኮሰ ችቦን አመጣላችኋለሁ» ባለ ጊዜ የሆነውን አውሳላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 8, '8. በመጣትም ጊዜ እንዲህ በማለት ተጠራ፡- «በእሳቲቱ ያለው ሰውና በዙሪያዋ ያሉም ሰዎች ሁሉ ተባረኩ:: የዓለማትም ጌታ አላህ ጥራት ይገባው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 9, '9. «ሙሳ ሆይ! እነሆ እኔ አሸናፊዉና ጥበበኛው (አምላክህ) አላህ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 10, '10. «በትርህንም ጣል» (ተባለና ጣለም):: እርሷ እንደ ትንሽ እባብ በፍጥነት ስትስለከለክ ባያትም ጊዜ ፊቱን አዙሮ ሸሸ:: አልተመለሰምም:: «ሙሳ ሆይ! አትፍራ:: መልዕክተኞች እኔ ዘንድ ፈጽሞ አይፈሩምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 11, '11. «ግን የበደለ ሰው ከዚያም ከመጥፎ ሥራው በኋላ መልካምን የለወጠ እኔ መሓሪ፤ አዛኝ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 12, '12. «እጅህንም በአንገትየህ ውስጥ አስገባ ያለ ነውር (ወይም ያለ ለምጽ) ነጭ ሆና ትወጣለችና በዘጠኝ ታዐምራት ወደ ፈርዖንና ወደ ሕዝቦቹ ሂድ እነርሱ አመጸኞች ህዝቦች ናቸውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 13, '13. ተዓምራታችንም ግልጽ ሆና በመጣቻቸው ጊዜ «ይህ ግልጽ ድግምት ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 14, '14. ነፍሶቻቸዉም ያረጋገጧት ሲሆኑ ለበደልና ለኩራት በእርሷ ካዱ:: የአበላሾችም ፍጻሜ እንዴት እንደነበረ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 15, '15. ለዳውድና ለሱለይማንም እውቀትን በእርግጥ ሰጠናቸው:: «ምስጋና ሁሉ ለአላህ ለዚያ ከአማኞች ባሮቹ በብዙዎቹ ላይ ላበለጠን ይገባው።» አሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 16, '16. ሱለይማንም ዳውድን ወረሰ:: አለም «ሰዎች ሆይ የበራሪን ንግግር (የወፍን ቋንቋ) ተስተማርን ከነገሩም ሁሉ ተሰጠን ይህ እርሱ በእርግጥ ግልጽ የሆነ ችሮታ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 17, '17. ለሱለይማንም ከአጋንንት ከሰዉም ከበራሪም የሆኑት ሰራዊቶቹ ተሰበሰቡ:: እነርሱም ይከመከማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 18, '18. በጉንዳንም ሸለቆ በመጡ ጊዜ አንዲት ጉንዳን፡- «እናንተ ጉንዳኖች ሆይ! ወደ መኖሪያዎቻችሁ ግቡ:: ሱለይማንና ሰራዊቱ እነርሱ የማያውቁ ሲሆኑ እንዳይሰባብሯችሁ።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 19, '19. ከንግግርዋም እየሳቀ ጥርሱን ፈገግ አደረገ። «ጌታዬ ሆይ! ያቺን በእኔና በወላጆቼ ላይ የለገስካትን ጸጋህን እንዳመሰግን የምትወደውንም በጎ ሥራ እንድሠራ ምራኝ፤ በችሮታህም በመልካሞቹ ባሮችህ ውስጥ አስገባኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 20, '20. በራሪዎቹንም ተመለከተ:: ከዚያ «ሁድሁድን ለምን አላየሁትም! በእውነት ከራቁት ነበርን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 21, '21. «ብርቱን ቅጣት በእርግጥ እቀጣዋለሁ:: ወይም በእርግጥ አርደዋለሁ:: ወይም ግልጽ የሆነ አስረጅን ያቀርብልኛል።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 22, '22. (ሁድሁድ የተባለው ወፍ) እሩቅ ያልሆነንም ጊዜ ቆየ:: ከዚያም አለ «ያላወቅከውን ነገር አወቅኩ ከሰበእም እርግጠኛን ወሬ አመጣሁልህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 23, '23. «እኔ የምትገዛቸው የሆነችን ሴት ከነገሩም ሁሉ የተሰጠችን አገኘሁ:: ለእርሷም ታላቅ ዙፋን አላት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 24, '24. «እርስዋንም ሕዝቦችዋንም ከአላህ ሌላ ለጸሐይ ሲሰግዱ አገኘኋቸው። ሰይጣንም ለእነርሱ ሥራዎቻቸውን ሸልሞላቸዋል። ከእውነተኛዉም መንገድ አግዷቸዋል:: ስለዚህ እነርሱ ወደ እውነት አይመሩም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 25, '25. «ለዚያም በሰማያትና በምድር ዉስጥ የተደበቀውን ለሚያወጣው የምትሸሽጉትንና የምትገልጹትንም ሁሉ ለሚያውቀው አላህ እንዳይሰግዱ ሰይጣን አግዷቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 26, '26. «አላህ ከእርሱ ሌላ አምላክ የለም:: የታላቁ ዐርሽ ጌታ ነው።» (አለ) {1}', '{1} እዚህ የንባብ ሱጁድ (ሱጁዱ ትላወህ) ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 27, '27. ሱለይማንም አለ፡- «እውነት እንደ ተናገርክ ወይም ከውሸታሞቹ እንደሆንክ ወደ ፊት እናያለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 28, '28. «ይህንን ደብዳቤዬን ይዘህ ሂድ:: ወደ እነርሱም ጣለው ከዚያ ከእነርሱ ዘወር በልና ምን እንደሚመልሱም ተመልከት።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 29, '29. እርሷም በደረሳት ጊዜ አለች፡- «እናንተ መማክርቶች ሆይ! እኔ ክብር ያለው ጽሑፍ ወደ እኔ ተጣለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 30, '30. «እርሱ ከሱለይማን ነው። እርሱም በአላህ ስም እጅግ በጣም ሩህሩህ በጣም አዛኝ በሆነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 31, '31. «‹በእኔ ላይ አትኩሩ:: ታዛዦችም ሆናችሁ ወደ እኔ ኑ› የሚል ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 32, '32. «እናንተ መማክርቶች ሆይ! በነገሬ የሚበጀውን ንገሩኝ እስከምትነግሩኝ ድረስ አንድንም ነገር ቆራጭ አይደለሁምና» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 33, '33. «እኛ የሃይል ባለቤቶች የብርቱ ጦርም ባለቤቶች ነን:: ግን ትዕዛዙ ከወደ አንቺ ብቻ ነው። ምን እንደምታዝዢንም አስተውይ» አሏት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 34, '34. እርሷም አለች፡- «ንጉሶች ከተማን በሃይል በገቡባት ጊዜ ያበላሿታል የተከበሩ ሰዎቿንም ወራዶች ያደርጋሉ:: ልክ እንደዚሁ ነው የሚያደርጉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 35, '35. «እኔም ወደ እነርሱ ገጸበረከትን የምልክና መልዕክተኞቹ በምን እንደሚመልሱ የምጠባበቅ ነኝ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 36, '36. መልዕክተኛው ሱለይማንን በመጣውም ጊዜ አለ፡- «በገንዘብ ትረዱኛላችሁን? አላህም የሰጠን ከሰጣችሁ የበለጠ ነው:: ይልቁንም እናንተ በገጸበረከታችሁ ትደሰታላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 37, '37. «ወደ እነርሱ ተመለስ:: ለእነርሱም በእርሷ ችሎታ በሌላቸው ሰራዊት እንመጣባቸዋለን:: ከእርሷም እነርሱ የተዋረዱ ሆነው በእርግጥ እናወጣቸዋለን።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 38, '38. «እናንተ መኳንንቶች ሆይ! ሙስሊሞች ሆነው ወደ እኔ ሳይመጡ በፊት ዙፋኗን የሚያመጣልኝ ማንኛችሁ ነው?» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 39, '39. ከጋኔን ሃይለኛው «ከችሎትህ ከመነሳትህ በፊት እኔ እርሱን አመጣልሃለሁ:: እኔም በእርሱ ላይ ብርቱ ታማኝ ነኝ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 40, '40. ያ እርሱ ዘንድ ከመጽሐፉ ጥልቅ ዕውቀት ያለው ሰው «የተገለጸው ዓይንህ ወደ አንተ ከመመለሱ በፊት እኔ እርሱን አመጣልሃለሁ።» አለ:: እንደዚሁም አደረገ:: እርሱ ዘንድ ረግቶ ባየዉም ጊዜ «ይህ ከጌታዬ ችሮታ ነው። የማመሰግን ወይም የምክድ መሆኔን ሊሞክረኝ ቸረልኝ:: አላህን ያመሰገነ ሁሉ የሚያመሰግነው ለራሱ ነው:: አላህን የካደም ሰው ሁሉ ጌታዬ ከእርሱ ተብቃቂ፤ ቸር ነው።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 41, '41. «ዙፋኗን ለእርሷ አሳስቱ ታውቀው እንደሆነ ወይም ከእነዚያ ከማያውቁት ትሆን እንደሆነ እናያለን።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 42, '42. በመጣችም ጊዜ፡- «ዙፋንሽ እንደዚህ ነውን?» ተባለች «እርሱ ልክ እርሱን ነው የመሰለኝ።» አለች። ሱለይማንም አለ: «ከእርሷ በፊትም እውቀትን ተሰጠን:: ሙስሊሞችም ነበርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 43, '43. «ከአላህ ሌላ ትገዛው የነበረችውንም ከለከላት:: እርሷ ከከሓዲያን ሕዝቦች ነበረችና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 44, '44. «ሕንጻውን ግቢ።» ተባለች:: ባየችዉም ጊዜ ባህር ነው ብላ ጠረጠረችው:: ከባቶቿም ገለጠች:: «እርሱ ከመስተዋት የተለሰለሰ ህንጻ ነው።» አሏት:: «ጌታዬ ሆይ! እኔ ነፍሴን በደልኩ ከሱለይማንም ጋር ሆኜ ለዓለማት ጌታ ለአላህ ታዘዝኩኝ።» አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 45, '45. ወደ ሰሙድም ወንድማቸውን ሷሊህን አላህን ተገዙ በማለት በእርግጥ ላክነው:: ወዲያዉም እነርሱ የሚነታረኩ ሁለት ቡድኖች ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 46, '46. «ሕዝቦቼ ሆይ! ከመልካሙ በፊት በክፉው ቅጣትን አምጣብን በማለት ለምን ታስቸኩላላችሁ ይታዘንላችሁ ዘንድ አላህን ምህረትን አትለምኑምን?» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 47, '47. «ባንተና ካንተም ጋር ባሉት ሰዎች ምክንያት ገደ ቢሶች ሆንን።» አሉት:: «ገደ ቢስነታችሁ አላህ ዘንድ ነው:: ይልቁንም እናንተ የምትፈተኑ ህዝቦች ናችሁ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 48, '48. በከተማይቱም ውስጥ ምድርን የሚያበላሹና የማያሳምሩ ዘጠኝ ሰዎች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 49, '49. ዘጠኞቹም «እርሱንና ቤተሰቦቹን ሌሊት እንግደልና ከዚያም ለዘመዱ የቤተሰቦቹን መገደል አላየንም:: እኛም እውነተኞች ነን ልንል በአላህ እንማማል።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 50, '50. ተንኮልንም መከሩ:: እነርሱም የማያውቁ ሲሆኑ በተንኮላቸው ምክኒያት አጠፋናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) የተንኮላቸዉም መጨረሻ እንዴት እንደ ነበረ እኛ እነርሱንም ሕዝቦቻቸውንም በሙሉ እንዴት እንዳጠፋናቸው ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 52, '52. እንዚህም በበደላቸው ምክንያት ባዶዎች ሲሆኑ እነዚህም ቤቶቻቸው ናቸው:: በዚህም ውስጥ ለሚያውቁ ህዝቦች ሁሉ አስደናቂ ተዐምር አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 53, '53. እነዚያንም ያመኑትንና ከክህደት ይጠነቀቁ የነበሩትን አዳንን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 54, '54. (መልዕክተኛችን ሙሐመድ ሆይ!) ሉጥንም ለህዝቦቹ ባለ ጊዜ (አስታውስ):: «እናንተ የምታዩ ስትሆኑ መጥፎን ነገር ትሠራላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 55, '55. «እናንተ ከሴቶች አልፋችሁ ወንዶችን ለመከጀል ትመጣላችሁን? በእውነቱ እናንተ የምትሳሳቱ ህዝቦች ናችሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 56, '56. የህዝቦቹም መልስ «የሉጥን ቤተሰቦች ከከተማችሁ አውጡ:: እነርሱ የሚጥራሩ ሰዎች ናቸውና።» ማለት እንጂ ሌላ አልነበረም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 57, '57. እርሱንና ቤተሰቦቹንም አዳንን:: ሚስቱ ብቻ ስትቀር:: እርሷማ በጥፋቱ ውስጥ ከቀሪዎቹ አደረግናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 58, '58. በእነርሱም ላይ የድንጋይ ዝናብን አዘነብንባቸው:: የተስፈራሪዎቹም የቅጣት ዝናብ ከፋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 59, '59. (መልዕክተኛችን ሙሐመድ ሆይ!)፡- «ምስጋና ሁሉ ለአላህ ይገባው:: በእነዚያም በመረጣቸው ባሮቹ ላይ ሁልጊዜም ሰላም ይውረድ:: አላህ በላጭ ነውን? ወይስ ያ በእርሱ የሚያጋሩት ጣዖት?» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 60, '60. ወይስ ያ ሰማያትንና ምድርን የፈጠረና ከሰማይም ለእናንተ ውሃን ያወረደው ማን ሆነና? በእርሱም ባለ ውበት የሆኑትን የታጠሩ አትክልቶችን ዛፍዋን ልታበቅሉ ለእናንተ ችሎታ ሳይኖራችሁ እኛ ብቻችንን አበቀልን:: ከአላህ ጋር ሌላ አምላክ አለን? (የለም) ግን እነርሱ ከእውነት የሚያዘነብሉ ህዝቦች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 61, '61. ወይስ ምድርን መርጊያ ያደረገና በመካከሏም ወንዞችን ያደረገ ለእርሷም ጋራዎችን ያደረገ በጣፋጩና በጨዋማው በሁለቱ ባህሮችም መካከል ግርዶን ያደረገ ማን ሆነና? ከአላህ ጋር ሌላ አምላክ አለን? ግን አብዛኞቻቸው አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 62, '62. ወይስ ችግረኛን በለመነው ጊዜ የሚቀበል መከራንም የሚያስወግድ በምድርም ላይ ምትኮች የሚደርጋችሁ ማን ሆነና? ከአላህ ጋር ሌላ ትክክለኛ አምላክ አለን? ጥቂትንም አትገሰጹም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 63, '63. ወይስ በየብስና በባህር ጨለማዎች ውስጥ የሚመራችሁ ንፋሶችንም ከዝናቡ በፊት አብሳሪ ሆነው የሚልክ ማን ሆነና? ከአላህ ጋር ሌላ ትክክለኛ አምላክ አለን? አላህ በእርሱ ከሚያጋሯቸው ነገሮች ሁሉ ላቀ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 64, '64. ወይስ መፍጠርን የሚጀምር ከዚያም የሚመልሰው፤ ከሰማይና ከምድርም ሲሳይን የሚሰጣቸሁ አምላክ ማን ሆነና? ከአላህ ጋር ሌላ ትክክለኛ አምላክ አለን? እውነተኞች እንደሆናችሁ አስረጃችሁን አምጡ በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) «በሰማያትና በምድር ያለው ሁሉ ሩቅን ምስጢር አያውቅም:: አላህ ግን ያውቀዋል:: መቼ እንደሚቀሰቀሱም አያውቁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 66, '66. በእውነት የመጨረሻይቱን ዓለም ሁኔታ ማወቃቸው ተሟላን? አይደለም። እነርሱ ከእርሷ በመጠራጠር ውስጥ ናቸው:: በእውነትም እነርሱ ከእርሷ እውሮች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 67, '67. እነዚያም በአላህ የካዱት አሉ፡- «እኛም አባቶቻችንም ዐፈር በሆንን ጊዜ እንደ ገና ከመቃብር የምንወጣ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 68, '68. «ይህንን እኛም ሆነ ከእኛ በፊትም የነበሩት አባቶቻችን በእርግጥ ተቀጥረንበታል:: ይህ የመጀመሪያዎቹ ሰዎች ተረቶች እንጂ ሌላ አይደለም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 69, '69. (መልዕክተኛችን ሙሐመድ ሆይ!) «በምድር ላይ ሂዱ የአመጸኞችም መጨረሻ እንዴት እንደነበረ ተመልክቱ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 70, '70. (መልዕክተኛችን ሙሐመድ ሆይ!) በእነርሱም ላይ አትዘን:: ከሚመክሩብህም ነገር በጭንቀት ውስጥ አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 71, '71. «እውነተኞችም እንደሆናችሁ ይህ ቀጠሮ መቼ ነው?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 72, '72. (መልዕክተኛችን ሙሐመድ ሆይ!) «የዚያ የምትቻኮሉበት ከፊሉ ለእናንተ የቀረበ መሆኑ ተረጋግጧል።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 73, '73. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም በሰዎች ላይ በእርግጥ የችሮታ ባለቤት ነው:: ግን አብዛኛዎቻቸው አያመሰግኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 74, '74. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም ልቦቻቸው የሚደብቁትንና የሚገልጹትን ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 75, '75. በሰማይም ሆነ በምድር ውስጥ ምንም የተደበቀ ነገር የለም:: ገላጭ በሆነው መጽሐፍ ውስጥ ያለ ቢሆን እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 76, '76. ይህ ቁርኣን እነዚያ የኢስራኢል ልጆች እነርሱ በእርሱ ላይ የሚለያዩበትን ጉዳይ አብዛኛውን ይነግራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 77, '77. እርሱም ለአማኞች ብቸኛ መምሪያና እዝነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 78, '78. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በመካከላቸው በትክክል ፍርዱ ይፈርዳል፤ እርሱም ሁሉን አሸናፊዉና አዋቂው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 79, '79. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህም ላይ ተጠጋ:: አንተ ግልጽ በሆነው እውነት ላይ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 80, '80. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ ሙታንን አታሰማም። ደንቆሮዎችንም የሚተው ሆነው በዞሩ ጊዜ ጥሪን አታሰማም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 81, '81.(መልዕክተኛችን ሙሐመድ ሆይ!) አንተም ልበ ዕውሮችን ከጥመታቸው አቅኚ አይደለህም:: እነዚያን በአናቅጻችን በትክክል የሚያምኑትን እንጂ አታሰማም:: እነርሱ ፍጹም ታዛዦች (ሙስሊሞች) ናቸውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 82, '82. በእነርሱም ላይ የቅጣት ቃሉ በተረጋገጠ ጊዜ ሰዎቹ በአናቅጻችን የማያረጋግጡ እንደነበሩ የምትነግራቸውን እንስሳ ለእነርሱ ከምድር እናወጣላቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሕዝቦቹም ሁሉ በአናቅጽ የሚያስተባብሉትን ቡድኖች የምንሰበስብበትን ቀን አስታውስ:: እነርሱም ይከመከማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 84, '84. በመጡም ጊዜ (አላህ) ይላቸዋል፡ «በአንቀጾቼ እርሷን በማወቅ ያላዳረሳችሁ ስትሆኑ አስተባበላችሁን? ወይስ ምንን ትሰሩ ነበራችሁ?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 85, '85. በመበደላቸዉም ምክኒያት በእነርሱ ላይ ቃሉ ይፈጸምባቸዋል:: እነርሱም አይናገሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 86, '86. እኛ ሌሊትን በእርሱ ውስጥ እንደሚያርፉበት ቀንንም የሚያሳይ እንዳደረግን አያዩምን? ለሚያምኑ ሕዝቦች በዚህ ውስጥ አያሌ ተዓምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 87, '87. (መልዕክተኛችን ሙሐመድ ሆይ!) በቀንዱም በሚነፋ ቀን በሰማያት ውስጥ ያሉትና በምድርም ውስጥ ያሉት ሁሉ አላህ የሻው ነገር ብቻ ሲቀር በሚደነግጡ ጊዜ የሚሆነውን አስታውስ። ሁሉም የተናነሱ ሆነዉም ወደ እርሱ ይመጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 88, '88. ጋራዎችንም እርሷ እንደ ደመና አስተላለፍ የምታልፍ ስትሆን የቆመች ናት ብለህ የምታስባት ሆና ታያለህ፤ የዚያን ነገሩን ሁሉ ያጠነከረውን የአላህን ጥበብ ተመልከት:: እርሱ በምትሠሩት ሁሉ ውስጥ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 89, '89. መልካም ሥራን የሰራ ለእርሱ ከእርሷ የበለጠ ምንዳ አለው:: እነርሱም በዚያ ቀን ከድንጋጤ ነፃ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 90, '90. መጥፎንም የሰሩ ፊቶቻቸው በእሳት ውስጥ ይደፋሉ። «ትሠሩት የነበራችሁትን እንጂ አትመነዱም» ይበላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 91, '91. (መልዕክተኛችን ሙሐመድ ሆይ! በላቸው:) «የታዘዝኩት የዚህችን አገር የመካን ጌታ ያንን ክልክል ያደረጋትንም አላህን እንድገዛ ብቻ ነው:: ነገሩም ሁሉ የእርሱ ነው:: ከሙስሊሞችም እንድሆን ታዝዣለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 92, '92. «ቁርኣንንም እንዳነብ ታዝዣለሁ:: በቀጥተኛው መንገድ የተመራ ሁሉ የሚመራው ለራሱ ብቻ ነው:: የተሳሳተም እኔ ከአስፈራሪዎች ነኝ እንጂ ሌላ አይደለሁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (27, 93, '93. (መልዕክተኛችን ሙሐመድ ሆይ!) «ምስጋናም ሁሉ ለአላህ ብቻ ነው:: ተአምራቱን ወደ ፊት ያሳያችኋል:: ታውቋታላችሁም።» በላቸው:: ጌታህ ከምትሠሩት ነገር ሁሉ ዘንጊ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 1, '1.ጧ፤ ሲን፤ ሚም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚህ አናቅጽ ገላጭ ከሆነው መጽሐፍ አናቅጽ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 3, '3. ከሙሳና ከፈርዖን ዜና ለሚያምኑ ህዝቦች ሁሉ ባንተ ላይ እናነባለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 4, '4. ፈርዖን በምድር ላይ ተንበጣረረ:: ነዋሪዎቿንም የተከፋፈሉ ጓዶች አደረጋቸው:: ከእነርሱም ቡድኖችን ያዳክማል:: ወንዶች ልጆቻቸውን በብዛት ያርዳል:: ሴቶቻቸውንም ይተዋል፤ እርሱ ከሚያበላሹት ሰዎች ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 5, '5. በእነዚያ በምድር ውስጥ በተጨቆኑት ህዝቦች ላይ ልንለግስና መሪዎችም ልናደርጋቸው ወራሾችም ልናደርጋቸው እንሻለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 6, '6. ለእነርሱም በምድር ላይ ልናስመች ፈርዖንን፤ ሃማንንና ሰራዊቶቻቸውንም ከእነርሱ ይፈሩት የነበሩትን ነገር ልናሳያቸው እንሻለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 7, '7. ወደ ሙሳም እናት “አጥቢው፤ በእርሱም ላይ በፈራሽ ጊዜ በባህሩ ውስጥ ጣይው፤ አትፍሪም:: አትዘኝም:: እኛ ወዳንቺ መላሾቹና ከመልእክተኞቹም አድራጊዎቹ ነንና” ማለትን አመለከትን (አወረድን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 8, '8. የፈርዖን ቤተሰቦችም መጨረሻው ለእነርሱ ጠላት ሐዘንም ይሆን ዘንድ አነሱት:: ፈርዖንና ሃማንም ሰራዊቶቻቸዉም ኃጢአተኞች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 9, '9. የፈርዖንም ሚስት “ለእኔም ሆነ ላንተ የዓይናችን መርጊያ ነው:: አትግደሉት:: ሊጠቅመን ወይም ልጅ ልናደርገው ይከጀላልና” አለች:: እነርሱም ፍጻሜውን የማያውቁ ሆነው (አነሱት)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 10, '10. የሙሳም እናት ልብ ባዶ ሆነ:: ከምእምናን ትሆን ዘንድ በልቧ ላይ ባላጠነከርን ኖሮ ልትገልጸው ቀርባ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 11, '11. ለእህቱም “ተከታተይው” አለቻት:: (እርሱንም) እነርሱ የማያውቁ ሲሆኑ በሩቅ ሆና አየችው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 12, '12. ወደ እናቱ ከመመለሱ በፊትም አጥቢዎችን መጥባትን በእርሱ ላይ እርም አደረግን:: እህቱም “ለእናንተ የሚያሳድግላችሁን እነርሱም ለእርሱ ቅን አገልጋዮች የሆኑን ቤተሰቦች ላመልክታችሁን?” አለችም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 13, '13. ወደ እናቱም ዓይኗ እንድትረጋ እንዳታዝንም የአላህም የተስፋ ቃል እርግጥ መሆኑን እንድታውቅ መለስነው:: ግን አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 14, '14. ብርታቱንም በደረሰና በተስተካከለ ጊዜ ጥበብንና እውቀትን ሰጠነው፤ ልክ እንደዚሁም መልካም ሰሪዎችን እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 15, '15. ሙሳ ከተማይቱንም ሰዎቿ በዝንጋቴ ላይ ሆነው ሳሉ ገባ:: በእርሷም ውስጥ የሚጋደሉን ሁለት ሰዎች አገኘ:: ይህ (አንዱ) ከወገኑ ነው፤ ይህ (ሌላው) ደግሞ ከጠላቱ ነው፤ ያ ከወገኑ የሆነው ሰው በዚያ ከጣላት በሆነው ሰው ላይ እርዳታን ጠየቀው:: ሙሳም በጡጫ መታው:: ገደለዉም:: “ይህ ከሰይጣን ስራ ነው:: እርሱ ግልጽ አሣሣች ጠላት ነውና” አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 16, '16. “ጌታዬ ሆይ! እኔ ነፍሴን በደልኩ ለኔም ማር” አለ ለርሱም ምህረት አደረገለት:: እርሱ መሓሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 17, '17. “ጌታዬ ሆይ! በእኔ ላይ በመለገስህ ይሁንብኝ (ከስህተቴ እጸጸታለሁ):: ለአመጸኞችም ፈጽሞ ረዳት አልሆንም” አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 18, '18. በከተማይቱም ውስጥ ፈሪና የሚጠባበቅ ሆኖ አደረ:: በንጋቱም ያ ትላንት እርዳታን የጠየቀው ሰው በጩኸት እርዳታን ይጠይቀዋል:: ሙሳም ለእርሱ፡- “አንተ በእርግጥ ግልጽ ጠማማ ነህ” አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 19, '19. ሙሳ ያንን እርሱ ለሁለቱም ጠላት የሆነው ሰው በኃይል ሊይዘው በፈለገም ጊዜ “ሙሳ ሆይ በትላንትናው ቀን ነፍስን እንደ ገደልክ ልትገድለኝ ትፈልጋለህን? በምድር ላይ ጨካኝ መሆንን እንጂ ሌላ አትፈልግም ከመልካም ሰሪዎች መሆንን አትፈልግም” አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 20, '20. ከከተማይቱም ዳርቻ አንድ ሰው እየሮጠ መጣ “ሙሳ ሆይ! ሹማምንቶቹ ሊገድሉህ ባንተ ይመካከራሉና ውጣ እኔ ላንተ ከመካሪዎች ነኝና” አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 21, '21. የፈራና የሚጠባበቅ ሆኖም ከእርሷ ወጣ:: “ጌታዬ ሆይ! ከበደለኞች ህዝቦች አድነኝ” አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 22, '22. ወደ መድየን አቅጣጫ ፊቱን ባዞረ ጊዜም “ጌታዬ ቀጥተኛውን መንገድ ሊመራኝ እከጅላለሁ” አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 23, '23. ወደ መድየንም ውሃ በመጣ ጊዜ እርሱ ላይ ከሰዎች ቡድኖችን መንጋዎቻቸውን የሚያጠጡ ሆነው አገኘ:: ከእነርሱ በታችም ከውሃው መንጎቻቸውን የሚከለክሉ ሁለት ሴቶች ልጆችን አገኘ። “ነገራችሁ ምንድን ነው?” አላቸው። “እረኞች ሁሉ መንጋዎቻቸውን እስከሚመልሱ አናጠጣም። አባታችንም ትልቅ ሽማግሌ ነው።” አሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 24, '24. ለሁለቱም አጠጣላቸው ከዚያ ወደ ጥላው ዘወር አለና “ጌታዬ ሆይ! እኔ ከመልካም ነገር ወደ እኔ ለምታወርደው ፈላጊ ነኝ” አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 25, '25. ከሁለቱ አንደኛይቱም ከሀፍረት ጋር የምትሄድ ሆና ወደ እርሱ መጣች፤ “አባቴ ለእኛ ያጠጣህልንን ዋጋ ሊሰጥህ ይጠራሃል” አለችው፤ ወደ እርሱ በመጣና ወሬውን በእርሱ ላይ በተረከለትም ጊዜ “አትፍራ:: ከበደለኞች ህዝቦች ድነሃል” አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 26, '26. ከሁለቱ አንደኛይቱም “አባቴ ሆይ ቅጠረው ከቀጠርከው ሰው ሁሉ በላጩ፤ ብርቱው፤ ታማኙ ነውና” አለችው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 27, '27. “ስምንትን ዓመታት ልታገለግለኝ እኔ ከእነዚህ ሁለት ሴቶች ልጆቼ አንዲቷን ላጋባህ እሻለሁ፤ ዐስርን ብትሞላም ካንተ ነው:: ባንተ ላይ ማስቸገርንም አልሻም:: አላህ የሻ እንደሆነ ከመልካም ሰዎች ሆኜ ታገኘኛለህ” አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 28, '28. ሙሳም "ይህ ውለታ በእኔና ባንተ መካከል ረጊ ነው:: ከሁለት ጊዜያቶች ማንኛውንም ብፈጽም በእኔ ላይ ወሰን ማለፍ የለም:: አላህ በምንለው ላይ ሁሉ ምስክር ነው" አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 29, '29. ሙሳም ጊዜውን በጨረሰና ከቤተሰቦቹ ጋር በሄደ ጊዜ ከጡር ተራራ ጎን እሳትን አየ:: ለቤተሰቡም “እዚህ ቆዩ:: እኔ እሳትን አየሁ:: ከእርሷ አጠገብ ወሬ ወይም ትሞቁ ዘንድ ከእሳት ትንታግን (ችቦን) አመጣላችኋለሁ” አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 30, '30. ወደ እርሷ በመጣም ጊዜ ከሸለቆው ቀኝ ዳርቻ ከዛፊቱ በኩል በተባረከችው ስፍራ ውስጥ “ሙሳ ሆይ! እኔ የዓለማት ጌታ አላህ ነኝ” በማለት ተጠራ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 31, '31. “ብትርህንም ጣል” ተባለ:: እንደ ትንሽ እባብ ስትስለከለክ ባያትም ጊዜ ወደ ኋላ ዞሮ ሸሸ:: አልተመለሰምም፤ ተባለም: “ሙሳ ሆይ! ተመለስ አትፍራም፤ አንተ ከጥብቆቹ ነህና', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 32, '32. "እጅህን በአንገትጌህ ውስጥ አስግባ:: ያለ ነውር ነጭ ሆና ትወጣለችና፤ ክንፍህንም ከፍርሃት ለመዳን ወደ አንተ አጣብቅ:: እነዚህም ከጌታህ የሆኑ ወደ ፈርዖንና ወደ መኳንቶች የሚደርሱ ሁለት አስረጅዎች ናቸው:: እነርሱ አመጠኞች ህዝቦች ነበሩና።“', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 33, '33. ሙሳ አለ: "ጌታዬ ሆይ! እኔ ከእነርሱ ነፍስን ገድያለሁ ስለዚህ እንዳይገሉኝ እፈራለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 34, '34. "ወንድሜንም ሃሩን እርሱ ምላሱ ከእኔ የተባ (የተሻለ) ነው:: እውነተኛነቴንም የሚያረጋግጥልኝ ረዳት ሆኖ ከእኔ ጋር ላከው እኔ ሊያስተባብሉኝ እፈራለሁና።”', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 35, '35. (አላህም)፡- “ጡንቻህን በወንድምህ በእርግጥ እናበረታለን:: ለሁለታችሁም ስልጣንን እናደርጋለን:: ወደ እናንተም በመጥፎ አይደርሱም:: በታዓምራታችን ሂዱ:: እናንተና የተከተላችሁ ሁሉ አሸናፊዎች ናችሁ” አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 36, '36. ሙሳም ተዓምራቶቻችንም ግልጽ ሆነው በመጣባቸው ጊዜ “ይህ የተቀጠፈ ድግምት እንጅ ሌላ አይደለም:: ይህንንም በመጀመሪያዎች አባቶቻችን ውስጥ አልሰማንም” አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 37, '37. ሙሳም “ጌታዬ ከእርሱ ዘንድ በቀጥታው መንገድ የመጣውን ምስጉኒትም አገር ለእርሱ የምትሆንለትን ሰው አዋቂ ነው:: እነሆ በደለኞች አይድኑም” አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 38, '38. ፈርዖንም “እናንተ ቡድኖች ሆይ! ከእኔ ሌላ ለእናንተ አምላክን ምንም አላውቅም:: ሃማን ሆይ! ጭቃ ለእኔ አቃጥልልኝ:: ጡብ ስራልኝ:: ለእኔም ከፍተኛ ህንጻን ስራልኝ:: ወደ ሙሳ አምላክ ልወጣ እከጅላለሁና:: እኔም ከውሸታሞች መሆኑን እጠረጥረዋለሁ” አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 39, '39. እርሱም ሰራዊቶቹም በምድር ላይ ያለ አግባብ ኮሩ:: እነርሱም ወደእኛ የማይመለሱ መሆናቸውን ጠረጠሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 40, '40. እርሱንም ሰራዊቱንም በጥብቅ ያዝናቸው:: በባህርም ውስጥ ጣልናቸው:: (መልዕክተኛችን ሙሐመድ ሆይ!) የበደለኞች መጨረሻም እንዴት እንደነበረ ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 41, '41. ወደ እሳት የሚጠሩ መሪዎችም አደረግናቸው:: በትንሳኤም ቀን አይረዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 42, '42. በዚችም በቅርቢቱ ዓለም ውስጥ እርግማንን አስከተልናቸው:: በትንሳኤም ቀን እነርሱ ከሚባረሩት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 43, '43. የፊተኞቹን የክፍለ ዘመናት ህዝቦችንም ከአጠፋን በኋላ ለሰዎች የልብ ብርሃን መሪም እዝነትም ሲሆን ይገሠጹ ዘንድ ለሙሳ መጽሐፉን በእርግጥ ሰጠነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 44, '44. ወደ ሙሳም ትዕዛዝን ባወረድንለት ጊዜ ከተራራው በምዕራባዊው ጎን አልነበርክም:: ከተጣዱትም አልነበርክም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 45, '45. እኛ ግን ከእርሱ ኋላ አያሌ የክፍለ ዘመናትን ሰዎች አስገኘን:: በእነርሱም ላይ ዕድሜዎች ተራዘሙ:: በመድየንም ሰዎች ውስጥ ተቀማጭና በእነርሱ ላይ አናቅጻችንን የምታነብ አልነበርክም:: እኛ ግን ላኪዎችህ ሆንን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 46, '46. በጠራነዉም ጊዜ በጡሩ (ጋራ) ጎን አልነበርክም፤ ግን ካንተ በፊት ምንም አስፈራሪ ያልመጣባቸውን ህዝቦች ታስፈራራ ዘንድ ከጌታህ በሆነ ችሮታ ላክንህ ሊገሠጹ ይከጅላልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 47, '47. እጆቻቸዉም ባሳለፉት ምክንያት መከራ የምትነካቸውና “ጌታችን ሆይ! አናቅጽህን እንድንከተል ከትክክለኛ አማኞችም እንድንሆን ወደ እኛ መልዕክተኛን አትልክም ኖሯልን? ይህ ሁሉ የሚሉ ባልሆኑ ኖሮ” አንልክም ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 48, '48. እውነቱም ከኛ ዘንድ በመጣላቸው ጊዜ “ለሙሳ የተሰጠው ብጤ አይሰጠዉም ኖሯልን?” አሉ፤ ከዚህ በፊት ሙሳ በተሰጠው አልካዱምን? “ሁለት የተረዳዱ ድግምቶች ናቸው። እኛ በሁሉም ከሓዲያን ነን” አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 49, '49. “ከአላህ ዘንድ የሆነን መጽሐፍ እርሱ ከሁለቱም ይበልጥ ቅን የሆነን አምጡ፤ እውነተኞች እንደ ሆናችሁ ብታመጡት እከተለዋለሁ” በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 50, '50. እሺ ባይሉህም የሚከተሉት ዝንባሌዎቻቸውን ብቻ መሆኑን ዕወቅ፤ ከአላህም የሆነ መምሪያ ሳይኖረው ዝንባሌውን ብቻ ከተከተለ ይበልጥ የጠመመ አንድም የለም፤ አላህ በደለኞች ህዝቦችን አይመራምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 51, '51. ይገሠጹም ዘንድ ቃልን (ቁርኣንን በያይነቱ) ለእነርሱ በእርግጥ አስከታተልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 52, '52. እነዚያም ከእርሱ በፊት መጽሐፍን የሰጠናቸው እነርሱ በእርሱ ያምናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 53, '53. በእነርሱ ላይ በሚነበብላቸዉም ጊዜ «በእርሱ አምነናል:: እርሱ ከጌታችን የሆነ እውነት ነው እኛ ከእርሱ በፊት ሙስሊሞች ነበርን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 54, '54. እነዚያ በመታገሳቸው ምክኒያት ዋጋቸውን ሁለት ጊዜ ይሰጣሉ:: ክፉውንም ነገር በበጎ ምግባር ይገፈትራሉ፤ ከሰጠናቸዉም ሲሳይ ይለግሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 55, '55. ውድቅንም ቃል በሰሙ ጊዜ ከእርሱ ይርቃሉ። «ለእኛ ስራዎቻችን አሉን:: ለእናንተም ስራዎቻችሁ አሉላችሁ:: ሰላም በእናንተ ላይ ይሁን ባለጌዎችን አንፈልግም።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 56, '56. አንተ የወደድከውን ሰው ፈጽሞ አታቀናም:: ግን አላህ የሚሻውን ሰው ያቀናል:: እርሱም ቅኖቹን አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 57, '57. «ካንተ ጋር ቅንን መንገድ ብንከተል ከምድራችን እንባረራለን።» አሉም:: ከእኛ ዘንድ የተሰጠ ሲሳይ ሲሆን የነገሩ ሁሉ ፍሬዎች ወደ እርሱ የሚሄዱበትን ጸጥተኛ ክልል (መካን) እነርሱ አላስመቸናቸዉምን? ግን አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 58, '58. ከከተማም ኑሮዋን ምቾትዋን የካደችን ከተማ ያጠፋናት ብዙ ናት፤ እነዚህም ከእነርሱ በኋላ ጥቂት ጊዜ እንጂ ያልተኖረባቸው ሲሆኑ መኖሪያዎቻቸው ናቸው:: እኛም ከእነርሱ ወራሾች ነበርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 59, '59. ጌታህም ከተሞችን በዋናዋ ከተማ ውስጥ አናቅጻችንን በእነርሱ ላይ የሚያነብ መልዕክተኛን እስከሚልክ ድረስ አጥፊ አልነበረም:: ከተሞችንም ባለቤቶችዋ በዳዮች ሆነው እንጂ አጥፊዎች አልነበርንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 60, '60. ሰዎች ሆይ! በማንኛዉም ነገር የተሰጣችሁት የቅርቢቱ ሂይወት ጥቅምና ጌጣ ጌጥ ነው:: አላህ ዘንድ ያለዉም ምንዳ በጣም በላጭና ዘውታሪ ነው:: አታውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 61, '61. መልካምን ተስፋ ቃል የገባንለትና እርሱም አግኚው የሆነ ሰው የቅርቢቱን ህይወት ጥቅም እንዳስመቸነውና ከዚያ እርሱ በትንሳኤ ቀን ለእሳት ከሚቀረቡት እንደ ሆነው ሰው ነውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 62, '62. (አላህ) የሚጠራባቸውንና «እነዚያ ተጋሪዎቼ ትሏቸው የነበራችሁት የት ናቸው?» የሚልበትን ቀን (አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 63, '63. እነዚያ በእነርሱ ላይ ቅጣቱ የተረጋገጠባቸው ይላሉ «ጌታችን ሆይ እነዚህ እነዚያ ያጠመምናቸው ናቸው፤ እንደጠመምን አጠመምናቸው (ከእነርሱ) ወደ አንተ ተጥራራን:: እኛን ይገዙ አልነበሩም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 64, '64. «ለአላህ የምታጋሯቸውንም ጥሩ» ይባላሉ:: ይጠሩዋቸዋልም ግን ለእነርሱ አይመልሱላቸዉም:: ቅጣትንም ያያሉ፤ እነርሱ ይመሩ በነበሩ ኖሮ (አያዩትም ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 65, '65. የሚጠራባቸውንና «ለመልዕክተኞች ምንን መለሳችሁ?» የሚልበትን ቀን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 66, '66. በዚያም ቀን ወሬዎች ሁሉ በእነርሱ ላይ ይሰወሩባቸዋል፤ እነርሱም አይጠያየቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 67, '67. የተጸጸተና ያመነማ መልካምንም የሰራ ከሚድኑት ሊሆን ይከጀላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 68, '68. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህም የሚፈልገውን ይፈጥራል:: ይመርጣልም:: ለእነርሱ ምርጫ የላቸዉም:: አላህ ከማይገባው ሁሉ ጠራ ከሚያጋሯቸዉም ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 69, '69. ጌታህም ልቦቻቸው የሚደብቁትንና የሚገልጹትን ሁሉ ያውቃል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 70, '70. እርሱም አላህ ነው። ከእርሱ ሌላ አምላክ የለም:: ምስጋና ሁሉ በመጀመሪያም በመጨረሻይቱም ዓለም ለእርሱ ብቻ ነው:: ፍርዱም የእርሱ ብቻ ነው፤ ወደ እርሱም ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 71, '71. (መልዕክተኛችን ሙሐመድ ሆይ!) «አያችሁን? (እስቲ ንገሩኝ) አላህ በእናንተ ላይ ሌሊትን እስከ ትንሳኤ ቀን ድረስ ዘውታሪ ቢያደርገው ከአላህ ሌላ ብርሃንን የሚያመጣላችሁ አምላክ ማነው? አትሰሙምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 72, '72. (መልዕክተኛችን ሙሐመድ ሆይ!) «አያችሁን? አላህ በእናንተ ላይ ቀንን እስከ ትንሳኤ ቀን ድረስ ዘውታሪ ቢያደርገው ከአላህ ሌላ በውስጡ የምታርፉበትን ሌሊት የሚያመጣላችሁ አምላክ ማን ነው? አታስተውሉምን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 73, '73. ከችሮታዉም ለእናንተ ሌሊትንና ቀንን በውስጡ ልታርፉበት ከትሩፋቱም ልትፈልጉበት አመስጋኞችም ልትሆኑ አደረገላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 74, '74. (መልዕክተኛችን ሙሐመድ ሆይ!) የሚጠራባቸውንም ቀንና «እነዚያ ተጋሪዎቼ ትሉዋቸው የነበራችሁት የት ናቸው?» የሚልበትን ቀን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 75, '75. ከህዝቦችም ሁሉ መስካሪን እናወጣና «ማስረጃችሁን አምጡ» እንላለን። ያን ጊዜ እውነተኛዉም አምላክነት ለአላህ ብቻ መሆኑን ያውቃሉ:: ይቀጣጥፉት የነበሩትም ከእነርሱ ይጠፋባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 76, '76. ቃሩን ከሙሳ ነገዶች አንዱ ነበር:: በእነርሱም ላይ አመጸ:: ከድልቦችም ያንን መክፈቻዎቹ ብቻ የኃይል ባለቤቶች የሆኑ ቡድኖችን ሸክሙ የሚከብድን ሰጠነው:: ወገኖቹ ለእርሱ ባሉትም ጊዜ አስታውስ: «አትኩራ አላህ ኩራተኞችን አይወድምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 77, '77. «አላህም በሰጠህ ሀብት የመጨረሻይቱን አገር ፈልግ:: ሆኖም ከቅርቢቱ አለምም ፈንታህን አትርሳ:: አላህ ወደ አንተ መልካምን እንዳደረገልህ መልካምን አድርግ:: በምድርም ውስጥ ማጥፋትን አትፈልግ:: አላህ አጥፊዎችን አይወድምና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 78, '78. «(ሀብትን) የተሰጠሁት እኔ ዘንድ ባለው እውቀት ነው።» አለ። አላህ ከእርሱ በፊት ከክፍለ ዘመናት ሰዎች በኃይል ከእርሱ ይበልጥ የበረቱትን ሀብትን በመሰብሰብም ይበልጥ የበዙትን በእርግጥ ያጠፋ መሆኑን አያውቅምን? አመጸኞችም ከኃጢአቶቻቸው ጥያቄ አይጠየቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 79, '79. በህዝቦቹም ላይ በጌጡ ውስጥ ሆኖ ወጣ:: እነዚያ ቅርቢቱን ህይወት የሚፈልጉት «ወይ ምኞታችን! ቃሩን የተሰጠው ቢጤ ምነው ለእኛ በኖረን፤ እርሱ የታላቅ ዕድል ባለቤት ነውና።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 80, '80. እነዚያም ዕውቀትን የተሰጡት «ወዮላችሁ! የአላህ ምንዳ ላመነ ሰው መልካምንም ለሰራ በላጭ ነው:: ታጋሾችም እንጂ ሌላው አያገኛትም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 81, '81. በእርሱም በቤትም ምድርን ደረባን (አሰጠምን):: ለእርሱም ከአላህ ሌላ የሚረዱት ቡድኖች ምንም አልነበሩትም:: ከሚረዱትም አልነበረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 82, '82. እነዚያም በትላንትናው ቀን ስፍራውን ይመኙ የነበሩት «ወይ ጉድ! ለካ አላህ ከባሮቹ ለሚሻው ሰው ሲሳይን ያሰፋል:: ያጠባልም:: አላህ በእኛ ላይ በእምነት ባልለገሰልን ኖሮ ምድርን በእኛ ላይ በገለበጠብን ነበር:: ወይ ጉድ! ከሓዲያን አይድኑም።» የሚሉ ሆነው አነጉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 83, '83. ይህች የመጨረሻይቱ አገር ናት:: ለእነዚያ በምድር ውስጥ ኩራትንና ማመጽን ለማይፈልጉት ሁሉ እናደርጋታለን:: ምስጉኒቱም መጨረሻ ለጥንቁቆቹ ብቻ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 84, '84. በደግ ስራ የመጣ ለእርሱ ከእርሷ በላጭ ምንዳ አለው:: በክፉም ስራ የመጡ እነዚህ መጥፎዎችን የሰሩ ይሰሩት የነበሩትን እንጂ አይመነዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 85, '85. (መልዕክተኛችን ሙሐመድ ሆይ!) ያ ቁርኣንን የተከፋፈለ ሆኖ ባንተ ላይ ያወረደውና ህግጋቱን እንድትትገበር ግድ ያደረግብህ አምላክ ወደ መመለሻ (ወደ መካ) በእርግጥ መላሽህ ነው። «ጌታዬ በቅን መንገድ የመጣውንና እርሱም በግልጽ ስህተት ውስጥ የሆነውን አዋቂ ነው» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 86, '86.(መልዕክተኛችን ሙሐመድ ሆይ!) መጽሐፉ ወደ አንተ መወረዱን ተስፋ የምታደርግ አልነበርክም :: ግን ከጌታህ ችሮታ ተወረደልህ:: ለከሓዲያን በፍጹም ረዳት አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 87, '87.(መልዕክተኛችንሙሐመድ ሆይ!) ከአላህም አናቅጽ ወደ አንተ ከተወረዱ በኋላ አያግዱህ:: ወደ ጌታህም ሰዎችን ጥራ:: ከአጋሪዎችም አትሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (28, 88, '88. ከአላህም ጋር ሌላን አምላክ አትገዛ:: ከእርሱም በቀር አምላክ የለም። ከእርሱ በስተቀር ሁሉም ጠፊ ነው:: ፍርዱ የእርሱ ብቻ ነው:: ሁላችሁም ወደ እርሱ ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 1, '1. አሊፍ፤ ላም፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 2, '2. ሰዎቹ አምነናል በማለታቸው ብቻ (ከአላህ በልዩ ልዩ ነገሮች) ሳይፈተኑ የሚተው መሰላቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 3, '3. እነዚያን ከእነርሱ በፊት የነበሩትንም ህዝቦች በርግጥ ፈትነናል። እነዚያን እውነት የተናገሩትን አላህ በእርግጥ ያውቃል። ውሸታሞችንም ያውቃል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 4, '4.ይልቁንም እነዚያ መጥፎዎችን ሥራዎች የሚሠሩት ሰዎች የሚያመልጡን መሰላቸውን? ያ የሚፈርዱት ፍርድ ከፋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 5, '5. የአላህን መገናኘት ተስፋ የሚያደርግ ሰው ሁሉ የአላህ ቀጠሮ በእርግጥ መጪ ነው:: እርሱም ሰሚም ሁሉን አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 6, '6. በአላህ መንገድ ላይ የታገለ ሰው የሚታገለው ለነፍሱ ብቻ ነው:: አላህ ከዓለማት ሁሉ በእርግጥ የተብቃቃ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 7, '7. እነዚያም በአላህና በመልዕክተኛው ያመኑና መልካም ተግባራትንም የሠሩ መጥፎ ሥራዎቻቸውን ከእነርሱ ላይ እናብስላቸዋለን። በዚያም ይሠሩት በነበሩት መልካም ሥራ በእርግጥ እንመነዳቸዋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 8, '8. የሰውን ልጅ ለወላጆቹ መልካም ተግባርን ሁሉ እንዲፈጽም አዘዝነው:: ወላጆችም ላንተም በእርሱ እውቀት የሌለህን ጣኦት በእኔ እንድታጋራው ቢያስገድዱህ አትታዘዛቸው:: መመለሻችሁ ወደ እኔ ነው:: ከዚያም ትሠሩት የነበራችሁትን ሁሉ እነግራችኋለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 9, '9. እነዚያንም በአላህ ያመኑና መልካም ሥራዎችን የሠሩ ሁሉ ከደጋጎቹ ውስጥ በእርግጥ እናስገባቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 10, '10. ከሰዎች መካከል «በአላህ አመንን።» የሚል ሰው አለ:: ከዚያ በአላህ በማመኑ ምክኒያት በተሰቃየ ጊዜ የሰዎችን ማሰቃየት እንደ አላህ ቅጣት ያደርጋል:: (መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህም እርዳታ ቢመጣ እኛ በእርግጥ ከናንተ ጋር ነበርን ይላሉ:: አላህ በዓለማት ሕዝብ ልቦች ውስጥ ያለውን ሁሉ አዋቂ አይደለምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 11, '11. አላህ እነዚያንም በትክክል ያመኑትን በእርግጥ ያውቃል:: መናፍቆቹንም ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 12, '12. እነዚያንም የካዱት ሰዎች ለእነዚያ ላመኑት «መንገዳችንን ተከተሉ:: ኃጢአቶቻችሁንም እንሸከማለን» አሉ:: እነርሱም ከኃጢአቶቻቸው ምንንም ተሸካሚዎች አይደሉም:: እነርሱ በእርግጥ ውሸታሞች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 13, '13. ሸክሞቻቸውንና ከሸክሞቻቸው ጋር ሌሎች ሸክሞችንም በእርግጥ ይሸከማሉ:: በትንሳኤም ቀን ይቀጥፉት ከነበሩት ሁሉ በእርግጥ ይጠየቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 14, '14. ኑሕንም ወደ ህዝቦቹ በእርግጥ ላክነው:: በውስጣቸዉም ሺህ ዓመትን ሀምሳ ዓመት ሲቀር ተቀመጠ:: እነርሱ በዳዮች ሆነዉም የውሃው ማዕበል አጥለቀለቃቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 15, '15. ኑህንና የመርከቢቱን ጓዶች አዳንናቸው:: እርሷንም ለዓለማት ተዓምር አደረግናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 16, '16. መልዕክተኛችን ሙሐመድ ሆይ! ኢብራሒም ለሕዝቦቹ ባለ ጊዜ የሆነውን (አስታውስ)። «አላህን ተገዙ ፍሩትም ይህን ማድረጋችሁ የምታውቁት ብትሆኑ ለናንተ በላጭ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 17, '17. (ሰዎች ሆይ!) ከአላህ ሌላ የምትገዙት ጣኦታትን ብቻ ነው:: ውሸትንም ትቀጥፋላችሁ:: እነዚያ ከአላህ ሌላ የምትገዟቸው ጣዖታት ለእናንተ ሲሳይን ሊሰጧችሁ አይችሉም:: ስለዚህ ሲሳይን ከአላህ ዘንድ ብቻ ፈልጉ:: ተገዙትም:: ለርሱም አመስግኑ ወደ እርሱም ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 18, '18. ብታስተባብሉም ከፊታችሁ የነበሩት ህዝቦች በእርግጥ አስተባብለዋል:: በመልዕክተኛዉም ላይ ግልጽ ማድረስ እንጂ ሌላ የለበትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 19, '19. አላህ መፍጠርን እንዴት እንደሚጀምርና ከዚያ እንዴት እንደሚመልሰው አይመለከቱምን? ይህ በአላህ ላይ ቀላል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) «በምድር ላይ ሂዱ:: እናም መፍጠርን እንዴት እንደጀመረ ተመልከቱ:: ከዚያም አላህ የመጨረሻይቱን መነሳት ያስነሳል:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 21, '21. የሚሻውን ሰው ይቀጣል:: የሚሻውንም ሰው ያዝንለታል ወደ እርሱም ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 22, '22. እናንተ በምድርም ሆነ በሰማይ የምታቅቱ አይደላችሁም። ከአላህም ሌላ ወዳጅም ተከላካይም ምንም የላችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 23, '23. እነዚያም በአላህ አናቅጽና በመገናኘቱ የካዱ እነዚያ ከእዝነቴ ተስፋን ቆረጡ:: እነዚያም ለእነርሱ አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 24, '24. የህዝቦቹም መልስ፡- «ግደሉት ወይም አቃጥሉት።» ማለት እንጂ ሌላ አልነበረም። ከዚያም ከእሳቲቱ አላህ አዳነው። በዚህ ውስጥ ለሚያምኑ ሕዝቦች ብዙ ተዐምራት አሉበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 25, '25. (ኢብራሂም) አለ፡- «ከአላህ ሌላ ጣኦታትን አማልክት የያዛችሁት በቅርቢቱ ህይወት በመካከላችሁ ለመዋደድ ብቻ ነው። ከዚያም በትንሳኤ ቀን ከፊላችሁ በከፊሉ ይክዳል:: ከፊላችሁም ከፊሉን ይረግማል:: መኖሪያችሁም እሳት ናት:: ለእናንተም ከረዳቶች ምንም የላችሁም።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 26, '26. ከዚያም ሉጥ ለእርሱ አመነ:: (ኢብራሂምም) «እኔ ወደ ጌታዬ ተሰዳጅ ነኝ:: እነሆ እርሱ አላህ ሁሉን አሸናፊና ጥበበኛ ነውና።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 27, '27. ለእርሱም ኢስሐቅንና ያዕቆብን ሰጠነው በዘሩም ውስጥ ነብይነትንና መጽሐፍን አደረግን:: ምንዳውንም በቅርቢቱ ዓለም ሰጠነው:: እርሱም በመጨረሻይቱ ዓለም ከደጋጎቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) ሉጥንም ለሕዝቦቹ ባለ ጊዜ አስታውስ: «እናንተ ጠያፍን ሥራ ትሰራላችሁን? በእርሷ ከዓለማት አንድም ሰው አልቀደማችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 29, '29. «እናንተ በእርግጥ ወንዶችን ትመጣላችሁን? መንገድንም ትቆርጣላችሁን? በሸንጓችሁም የሚነወርን ነገር ትሠራላችሁን?» አላቸው:: የሕዝቦቹም መልስ «ከእውነተኞቹ እንደሆንክ የአላህን ቅጣት አምጣብን።» ማለት እንጂ ሌላ አልነበረም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 30, '30. «ጌታዬ ሆይ! በአመጸኞች ሕዝቦች ላይ እርዳኝ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 31, '31. መልዕክተኞቻችንም ወደ ኢብራሂም በብስራት በመጡ ጊዜ «እኛ የዚችን ከተማ ሰዎች አጥፊዎች ነን ሰዎችዋ በዳዮች ነበሩና።» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 32, '32. «በእርሷ ውስጥ ሉጥ አለ እኮ?» አላቸው:: «እኛ በውስጧ ያለውን ካንተ ይበልጥ አዋቂ ነን:: እርሱንማ በእርግጥ እናድነዋለን:: ቤተሰቦቹንም ጭምር ሚስቱ ብቻ ስትቀር እርሷ በጥፋቱ ውስጥ ከሚቀሩት ናት።» አሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 33, '33. መልዕክተኞቻችንም ወደ ሉጥ በመጡት ጊዜ በነሱ ምክንያት አዘነ:: በእነርሱም ልቡ ተጨነቀ። አሉትም: «አትፍራ። አትዘንም። እኛ አዳኞችህ ነን:: ቤተሰቦችህንም ሚስትህ ብቻ ስትቀር:: እርሷ ግን በጥፋቱ ውስጥ ከቀሪዎቹ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 34, '34. «እኛ በዚህ ከተማ ሰዎች ላይ ያምጹ በነበሩበት ምክንያት ከሰማይ ቅጣትን አውራጆች ነን።» (አሉት)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 35, '35. በእርግጥም ለሚያስቡ ሰዎች ሁሉ ከእርሷ ግልጽ ምልክትን ተውን (አስቀረን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 36, '36. ወደ መድየንም ወንድማቸውን ሹዐይብን ላክን። «ህዝቦቼ ሆይ! አላህን ተገዙ:: የመጨረሻውንም ቀን ፍሩ:: በምድርም ውስጥ የምታጠፉ ሆናችሁ አታበላሹ።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 37, '37. እናም አስተባበሉትና የምድር መንቀጥቀጥ ያዘቻቸው፡፡ ባገራቸዉም ውስጥ ተንከፍረው አደሩ (አነጉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 38, '38. ዓድንና ሠሙድንም አጠፋን:: የመኖሪያዎቻቸውን ፍርስራሾች በማየት መጥፋታቸው ለእናንተ በእውነት ተገለጠላችሁ:: ሰይጣንም ሥራዎቻቸውን ለእነርሱ ሸለመላቸው:: ከመንገድም አገዳቸው:: የማስተዋልም ባለቤቶች ነበሩ:: ግን አላስተዋሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 39, '39. ቃሩንንም ፈርዖንንም ሃማንንም አጠፋን:: ሙሳም በተዐምራት በእርግጥ መጣባቸው:: በምድርም ላይ ኮሩ:: አምላጮችም አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 40, '40. ሁሉንም በኃጢአቱ ያዝነው:: ከእነርሱም ውስጥ ጠጠርን ያዘለ ነፍስን የላክንበት አለ:: ከእነርሱም ውስጥ ጩኸት የያዘችው አለ:: ከእነርሱም ውስጥ በእርሱ ምድርን የደረባንበት አለ:: ከእነርሱም ውስጥ ያሰመጥነው አለ:: አላህ የሚበድላቸው አልነበረም:: ግን ነፍሶቻቸውን የሚበድሉ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 41, '41. የእነዚያ ከአላህ ሌላ ረዳቶችን (ጣኦታትን) የያዙ ሰዎች ምሳሌ ቤትን እንደሠራች ሸረሪት ብጤ ነው:: ከቤቶችም ሁሉ በጣም ደካማው የሸረሪት ቤት ነው:: ቢያውቁ ኖሮ አማልክት አድርገው አይገዟቸዉም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 42, '42. አላህ ያንን ከእርሱ ሌላ የሚገዙትን ማንኛውንም ያውቃል:: እርሱም ሁሉን አሸናፊዉና ጥበበኛው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 43, '43. እነዚህንም ምሳሌዎች ለሰዎች እንገልጻቸዋለን:: ከሊቃውንቶቹም በስተቀር ሌሎችአያውቋትም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 44, '44. አላህም ሰማያትንና ምድርን እውነተኛ ሆኖ ፈጠረ፤ በዚህ ውስጥ ለአማኞች ተዐምር አለበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመጽሐፉ ወደ አንተ የተወረደውን አንብብ:: ሶላትንም ደንቡን ጠብቀህ ስገድ:: ሶላት ከመጥፎና ከሚጠላ ነገር ሁሉ ትከለክላለችና:: አላህን ማውሳት ከመልካም ነገር ሁሉ በላጭ ነው:: አላህም የምትሠሩትን ስራ ሁሉ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 46, '46. (እናንተ ያመናችሁ ሆይ!) ከእነርሱ እነዚያን የበደሉትን ሲቀር የመጽሐፉ ባለቤቶችን በዚያች እርሷ መልካም በሆነችው ክርክር እንጂ አትከራከሩ:። በሉም፡- «በዚያ ወደ እኛ በተወረደው ወደ እናንተም በተወረደው አመንን:: አምላካችንም አምላካችሁም አንድ ነው:: እኛም ለእርሱ ታዛዦች ነን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) እንደዚሁም ወደ አንተ መጽሐፍን አወረድን:: እነዚያም መጽሐፍን የሰጠናቸው በእርሱ ያምናሉ:: ከእነዚህም (ከመካ) ሰዎች በእርሱ የሚያምኑ አሉ:: በተዓምራታችንም ከሓዲያን እንጂ ማንም አይክድም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእርሱ በፊትም መጽሐፍን የምታነብ በቀኝህም የምትጽፈው አልነበርክም:: ያን ጊዜ አጥፊዎቹ በእርግጥ በተጠራጠሩ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 49, '49. አይደለም:: እርሱ (ቁርኣን) በእነዚያ እውቀትን በተሰጡት ሰዎች ልቦች ውስጥ የጠለቀ ግልፆች አናቅጽ ነው:: በአናቅጻችንም በዳዮቹ እንጂ ሌላው አይክድም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያን «በእርሱ ላይ ከጌታው ዘንድ ተዐምራት ለምን አልተወረዱም?» አሉ:: »ተዐምራት ከአላህ ዘንድ ብቻ ናቸው:: እኔም ግልጽ አስፈራሪ ብቻ ነኝ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 51, '51. እኛ መጽሐፉን በእነርሱ ላይ የሚነበብ ሆኖ ባንተ ላይ ማውረዳችን አይበቃቸዉምን? በዚህ ውስጥ ለሚያምኑ ሕዝቦች ሁሉ ችሮታና ግሳጼ አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእኔና በእናንተ መካከል መስካሪ በአላህ በቃ:: በሰማያትና በምድር ያለውን ሁሉ ያውቃል።» በላቸው:: እነዚያም በብላሽ ነገር ያመኑና በአላህ የካዱ እነዚያ እነርሱ ከሳሪዎቹ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) በቅጣትም ያስቸኩሉሃል! የተወሰነም ጊዜ ባልነበረ ኖሮ ቅጣቱ በመጣባቸው ነበር:: እነርሱ የማያውቁ ሲሆኑም በድንገት በእርግጥ ይመጣባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 54, '54. በቅጣት ያስቸኩሉሃል! ገሀነምም ከሓዲያንን በእርግጥ ከባቢ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 55, '55. ቅጣቱ ከበላያቸው ከእግሮቻቸዉም ሥር በሚሸፍናቸው ቀን «ትሰሩት የነበራችሁትን ቅመሱ።» በሚላቸዉም ቀን ትከባቸዋለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 56, '56. እናንተ ያመናችሁ ባሮቼ ሆይ! ምድሬ በእርግጥ ሰፊ ናት:: ብትቸገሩ ተሰደዱ እኔንም ብቻ ተገዙኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 57, '57. ነፍስ ሁሉ ሞትን ቀማሽ ናት:: ከዚያም ወደ እኛ ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 58, '58. እነዚያም በአላህ ያመኑና መልካም ስራዎችን የሠሩ ከገነት በስሮቻቸው ወንዞች የሚፈሱባቸው ሰገነቶች በውስጣቸው ዘውታሪዎች ሲሆኑ በእርግጥ እናሰፍራቸዋለን:: የሠራተኞችም ምንዳ ምንኛ አማረ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 59, '59. እነርሱ እነዚያ የታገሱ በጌታቸዉም ላይ የሚመኩ ናቸው፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 60, '60. ከተንቀሳቃሽ ፍጡራን ምግባቸውን የማይሸከሙ ብዙ ናቸው:: አላህ ይመግባቸዋል:: እናንተንም ይመግባል:: እርሱ ሰሚና አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 61, '61. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰማያትንና ምድርን የፈጠረ ጸሐይንና ጨረቃንም የገራ ማን እንደሆነ ብትጠይቃቸው በእርግጥ ”አላህ ነው“ ይሉሃል:: ታዲያ እንዴት ይመለሳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 62, '62. አላህ ከባሮቹ ለሚሻው ሲሳይን ያሰፋል:: ለእርሱም ያጠባል:: አላህ በነገሩ ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 63, '63. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሰማይ ውሃን ያወረደና በእርሱም ምድርን ከሞተች በኋላ ሕያው ያደረጋት ማን እንደሆነ ብትጠይቃቸው "አላህ ነው" ይሉሃል:: "ስለዚህ ምስጋና ሁሉ ለአላህ ነው።“ በላቸው:: ግን አብዛኞቻቸው ይህን አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 64, '64. ይህም የቅርቢቱ ሕይወት መታለያና ጨዋታ እንጂ ሌላ አይደለም:: የመጨረሻይቱም አገር እርሷ በእርግጥ የዘላለም ህይወት አገር ናት:: የሚያውቁ ቢሆኑ ኖሮ ጠፊይቱን ሕይወት አይመርጡም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 65, '65. በመርከቦች ውስጥ በተሳፈሩ ጊዜም አላህን መገዛትን ለእርሱ ብቻ ያጠሩ ሆነው ይጠሩታል:: ወደ የብስ በማውጣት ባዳናቸው ጊዜ ግን ወዲያውኑ እነርሱ ጣዖትን ያጋራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 66, '66. በሰጠናቸው ጸጋ ሊክዱና ሊጠቃቀሙ ያጋራሉ፤ ወደ ፊትም የሚጠብቃቸውን ያውቃሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 67, '67. ሰዎቹ ከየዙሪያቸው ሲነጠቁ እኛ አገራቸውን ጸጥተኛ ክልል ማድረጋችንን አያዩምን? በውድቅ ነገር ያምናሉን? በአላህም ጸጋ ይክዳሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 68, '68. በአላህ ላይ ውሸትን ከቀጣጠፈ ሰው ወይም እውነት በመጣለት ጊዜ ከአስዋሸ ሰው ይበልጥ ራሱን በዳይ ማነው? በገሀነም ውስጥ ለከሓዲያን መኖሪያ የለምን?(አለ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (29, 69, '69. እነዚያም በእኛ መንገድ የታገሉ ህዝቦችን መንገዳችንን በእርግጥ እንመራቸዋለን:: አላህ በእርግጥ ከበጎ ሰሪዎች ጋር ነውና፡:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 1, '1. አሊፍ፤ ላም፤ ሚይም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 2, '2. ሩም (በፋርሶች) ተሸነፈች፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 3, '3. በጣም (ለዐረቡ ዓለም) ቅርብ በሆነችው ምድር ላይ እነርሱም (ከሶስት አመት ያላነሰ ከዘጠኝ ባልበለጠ በጥቂት አመታት ውስጥ) ከመሸነፋቸው በኋላ ያሸንፋሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 4, '4. (ከሶስት አመት ያላነሰ ከዘጠኝ ባልበለጠ) በጥቂት አመታት ውስጥ (ያሸንፋሉ)። ጉዳዩ በፊትም ሆነ በኋላ የአላህ ነውና:: በዚያ ቀንም ምዕምናን ይደሰታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 5, '5. በአላህ እርዳታ (ይደሰታሉ)፡፡ አላህ የሚሻውን ሰው ይረዳል:: እርሱም ሁሉን አሸናፊና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 6, '6. አላህ እርዳታን በቁርጥ ቀጠረ:: አላህ ቀጠሮውን አያፈርስም:: ግን አብዛሀኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 7, '7. ከቅርቢቱ ህይወት ግልጹን ብቻ ያውቃሉ:: እነርሱም ከኋለኛይቱ ዓለም ፍጹም ዘንጊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 8, '8. በነፍሶቻቸው ሁኔታ አያስተውሉምን ? ሰማያትን፤ ምድርንና በመካከላቸው ያለውን ሁሉ በእውነትና በተወሰነ ጊዜ እንጂ አልፈጠራቸዉም:: ከሰዎች መካከል ብዙዎቹ ከጌታቸው ጋር በመገናኘት ከሓዲያን ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 9, '9. በምድር ላይ አይሄዱምና የእነዚያን ከበፊታቸው የነበሩትን ሰዎች ፍፃሜ እንዴት እንደነበር አይመለከቱምን? በኃይል ከእነርሱ ይበልጡ ነበሩ:: ምድርንም አረሱ:: እነዚህ ከአለሟትም የበለጠ አለሟት:: መልዕክተኞቻቸዉም በተአምራቶች መጡባቸው:: ግና አስተባበሉና ጠፉ:: አላህም የሚበድላቸው አልነበረም:: ግና ነፍሶቻቸውን በራሳቸው ይበድሉ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 10, '10. ከዚያም የእነዚያ ያጠፉት ሰዎች መጨረሻ በአላህ አናቅጽ ማስተባበላቸውና በእርሷ የሚሳሳቁ የሚያፌዙ መሆናቸው (ምክንያት መጥፎ ቅጣት) ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 11, '11. አላህ መፍጠርን ይጀምራል:: ከዚያም ይመልሰዋል:: ከዚያም ወደ እርሱ ትመለሳለችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 12, '12. ሰዓቲቱም በምትከሰትበት ቀን አመጸኞች ጭጭ ይላሉ (ተስፋ ይቆርጣሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 13, '13. ለእነርሱም ከሚያጋሯቸው ጣዖታት መካከል አማላጆች አይኖሩዋቸዉም:: በሚያጋሯቸዉም ጣዖታት ከሓዲያን ይሆናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 14, '14. ሰዓቲቱም በምትከሰትበት ቀን በዚያ ቀን ይለያያሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 15, '15. እነዚያ በአላህ ያመኑትና መልካሞችን ስራዎች የሰሩትማ እነርሱ በገነት ጨፌ ውስጥ ይደሰታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 16, '16. እነዚያም በአላህ የካዱትማ በአናቅጻችንና በኋለኛይቱም ዓለም መገናኘት ያስተባበሉት እነዚያ በቅጣት ውስጥ የሚጣዱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 17, '17. አላህንም በምታመሹና በምታነጉም ጊዜ አጥሩት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 18, '18. ምስጋናም በሰማያትና በምድር ውስጥ ለእርሱ ብቻ የተገባው ነው:: በሰርክም በቀትር ውስጥ በምትገቡም ጊዜ አጥሩት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 19, '19. ህያውን ከሙት ያወጣል:: ሙትንም ከህያው ያወጣል:: ምድርንም ከሞተች በኋላ ህያው ያደርጋታል:: ልክ እንደዚሁም (ከመቃብር) ትወጣላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 20, '20. እናንተንም ከአፈር መፍጠሩ ከዚያም እናንተ ወዲያውኑ የምትበታተኑ ሰዎች መሆናችሁ ከአስደናቂ ምልክቶቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 21, '21. ለእናንተም ከነፍሶቻችሁ ሚስቶችን ወደ እነርሱ ትረኩ ዘንድ መፍጠሩ በመካከላችሁም ፍቅርንና እዝነትን ማድረጉ ከአስደናቂ ምልክቶቹ ነው:: በዚህ ውስጥ ለሚያስተውሉ ህዝቦች ሁሉ አያሌ ተዐምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 22, '22. ሰማያትንና ምድርን መፍጠሩ የቋንቋዎቻችሁና የመልኮቻችሁም መለያየት ከአስደናቂ ምልክቶቹ ነው:: በዚህ ውስጥ ለአዋቂዎች አያሌ ታዐምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 23, '23. በሌሊትም ሆነ በቀን መተኛታችሁ ከችሮታዉም መፈለጋችሁም ከምልክቶቹ ነው:: በዚህ ውስጥ ለሚሰሙ ህዝቦች ሁሉ ብዙ ታዐምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 24, '24. ብልጭታንም ፈሪዎችና ከጃዮች ስትሆኑ ለእናንተ ማሳየቱ ከሰማይም ውሃን ማውረዱ በእርሱም ምድርን ከሞተች በኋላ ህያው ማድረጉ ከአስደናቂ ምልክቶቹ ነው:: በዚህ ውስጥ ለሚያስቡ ህዝቦች ሁሉ አያሌ ታዐምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 25, '25. ሰማይና ምድርም ያለ ምሰሶ በትእዛዙ መቆማቸው ከዚያም መልአክ ለትንሳኤ ከምድር ጥሪን በጠራችሁ ጊዜ እናንተ ወዲያውኑ የምትወጡ መሆናችሁ ከአስደናቂ ምልክቶቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 26, '26. በሰማያትና በምድር ውስጥ ያለው ሁሉ የእርሱ ብቻ ነው:: ሁሉም ለእርሱ ታዛዦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 27, '27. እርሱ ያ ፍጡራንን ከምንም የሚጀምር (የሚያስገኝ) ከዚያም የሚመልሳቸው ብቸኛ አምላክ ነው:: መመለሱም በእርሱ ላይ በጣም ቀላል ነው:: ለእርሱም በሰማያትና በምድር ከፍተኛው ምሳሌ (ባህሪ) አለው:: እርሱም ሁሉን አሸናፊና ጥበበኛ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 28, '28. (ጣዖት አምላኪዎች ሆይ!) ለእናንተ ከነፍሶቻችሁ የሆነን ምሳሌ አደረገላችሁ:: እርሱም እጆቻችሁ ከያዟቸው ባሮች ውስጥ በሰጠናችሁ ጸጋ ለእናንተ ተጋሪዎች አሏችሁን? ታዲያ እናንተና እነርሱ በእርሱ እኩል ለኩል (ትክክል) ናችሁን? ነፍሶቻችሁን (ብጤዎቻችሁን) እንደምትፈሩ ትፈሯቸዋላችሁን ? ልክ እንደዚሁ ለሚያስተውሉ ህዝቦች ሁሉ አናቅጽን እንገልጻለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 29, '29. ይልቁንም እነዚህ የበደሉ ሰዎች ያለ ዕውቀት ዝንባሌዎቻቸውን ተከተሉ:: አላህም ያጠመመውን ሰው የሚያቀናው ማነው? ለእነርሱም ከረዳቶች ምንም የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እውነት ተዘንባይ ሆነህም ፊትህን ለሃይማኖት ቀጥ አድርግ:: የአላህን ፍጥረት ያችን አላህ ሰዎችን በርሷ ላይ የፈጠረባትን ሃይማኖት (ያዟት):: የአላህን ፍጥረት መለወጥ የለም:: ይህ ቀጥተኛው ሃይማኖት ነው:: ግን አብዛኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 31, '31. ወደ እርሱ ተመላሾች ሆናችሁ የአላህን ሃይማኖት ያዙ:: ፍሩትም:: ሶላትንም አስተካክላችሁ ስገዱ:: ከአጋሪዎችም አትሁኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 32, '32. ከእነዚያ ሃይማኖታቸውን ከለያዩትና ክፍልፍልም ከሆኑት አትሁኑ:: ህዝብ ሁሉ እነርሱ ዘንድ ባለው ነገር ብቻ ተደሳቾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 33, '33. ሰዎችንም ችግር ባገኛቸው ጊዜ ጌታቸውን ወደ እርሱ ተመላሾች ሆነው ይጠሩታል:: ከዚያም ከእርሱ ችሮታንም ባቀመሳቸው ጊዜ ከእነርሱ ከፊሎቹ ወዲያውኑ በጌታቸው ጣዖትን ያጋራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 34, '34. በሰጠናቸው ጸጋ ሊክዱ (ያጋራሉ):: ተጣቀሙም:: በእርግጥም መጨረሻችሁን ወደፊት ታውቃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 35, '35. በእነርሱ ላይ አላህ አስረጅን አወረደን? ታድያ እርሱ በነዚያ በእርሱ ያጋሩ በነበሩት ነገር ይናገራልን? የለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 36, '36. ሰዎችንም ችሮታን ባቀመስናቸው ጊዜ በእርሷ ይደሰታሉ:: እጆቻቸዉም ባሳለፉት ምክንያት መከራ ብታገኛቸው ወዲያውኑ እነርሱ ተስፋ ይቆርጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 37, '37. አላህ ለሚሻው ሰው ሲሳይን የሚያሰፋ የሚያጠብም መሆኑን አያዩምን? በዚህ ውስጥ ለሚያምኑ ህዝቦች አስደናቂ ምልክቶች አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 38, '38.ስለዚህ (አማኝ ሆይ!) የዝምድናን ባለቤት ተገቢውን ስጠው:: ለድሃም ለመንገደኛም እርዳ:: ይህ ለእነዚያ የአላህን ፊት ለሚሹ ሁሉ መልካም ነው:: እነዚያ እነርሱም በሁለተኛው ዓለም የፈለጉትን የሚያገኙ ምርጥ ክፍሎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 39, '39. (ሰዎች ሆይ!) በሰዎች ውስጥም ይጨመር ዘንድ በማቀድ የምትሰጡት ገንዘብ በአላህ ዘንድ ቅንጣት አይጨምርም:: የአላህን ፊት ብቻ የምትሹ ሆናችሁ የምትሰጡት ምጽዋት ግን እነዚያ እውነተኛ ሰጪዎች (አበርካቾች) እነርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 40, '40. አላህ ያ የፈጠራችሁ ከዚያም ሲሳይን የሰጣችሁ ከዚያም የሚገድላችሁ ከዚያም ህያው የሚያደርጋችሁ ነው:: ከምታጋሯቸው ጣዖታት ውስጥ ከዚሃችሁ አንዳችን የሚሰራ አለን? ለአላህ ጥራት ይገባው በእርሱ ከሚያጋሩትም ሁሉ ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 41, '41. የሰዎች እጆች በሰሩት ኃጢአት ምክንያት የዚያን የሰሩትን ከፊሉን ያቀምሳቸው ዘንድ መከራው በየብስና በባህር ተገለጠ (ተሰራጨ)። እነርሱ ሊመለሱ ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) «በምድር ላይ ሂዱ የእነዚያንም በፊት የነበሩት ሰዎች መጨረሻ እንዴት እንደነበረ ተመልከቱ።» በላቸው:: አብዛኞቻቸው አጋሪዎች ነበሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእርሱ መመለስ የሌለው ቀን የትንሳኤ ቀን ከአላህ ሳይመጣ በፊት ፊትህን ወደ ቀጥተኛው ሃይማኖት ቀጥ አድርግ :: በዚያ ቀን ወደ ገነትና ወደ እሳት ይለያያሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 44, '44. በአላህ የካደ ሰው የክህደቱ ጠንቁ በእርሱው ላይ ብቻ ነው:: መልካምም የሰሩ ሁሉ ለነፍሶቻቸው ማረፊያዎችን ያዘጋጃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 45, '45. እነዚያን ያመኑትንና መልካሞችንም የሰሩትን ከችሮታው ይመነዳ ዘንድ (ይለያያሉ):: እርሱ ከሓዲያንን አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 46, '46. (ሰዎች ሆይ!) ንፋሶችንም (በዝናብ) ልታበስራችሁ ከችሮታዉም (በእርሷ) ሊያቀምሳችሁ መርከቦችም በትእዛዙ እንዲንሻለሉ ከችሮታዉም እንድትፈልጉ ታመሰግኑትም ዘንድ መላኩ ከአስደናቂ ምልክቶቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊትም መልዕክተኞችን ወደ የህዝቦቻቸው በእርግጥ ላክን:: በግልጽ ማስረጃዎችም መጡባቸው:: ከእነዚያ ካመጹትም ተበቀልን:: ምዕመናኖችንም መርዳት በእኛ ላይ ተገቢ ሆነ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 48, '48. አላህ ያ ! ንፋሶችን የሚልክ ነው:: ደመናንም ይቀሰቅሳል:: በሰማይ ላይም እንደሚሻ ይዘረጋዋል :: ቁርጥራጮችም ያደርገዋል:: ዝናቡንም ከደመናው መካከል ሲወጣ ታያለህ:: በእርሱም ከባሮቹ የሚሻውን በለየ ጊዜ ወዲያውኑ እነርሱ ይደሰታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 49, '49. በእነርሱም ላይ ከመውረዱ በፊት ከእርሱ በፊት በእርግጥ ተስፋ ቆራጮች ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 50, '50. ምድርንም ከሞተች በኋላ እንዴት ህያው እንደሚያደርጋት ወደ አላህ ችሮታ ፈለጎች ተመልከት:: ይህን አድራጊ ጌታ ሙታንንም በእርግጥ ህያው አድራጊ ነው :: እርሱም በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 51, '51. ንፋስንም በአዝመራዎች ላይ ብንልክና ገርጥቶ ቢያዩት ከእርሱ በኋላ በእርግጥ ችሮታውን የሚክዱ ይሆናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተም ሙታንን አታሰማም:: ደንቆሮዎችንም ዟሪዎች ሆነው በሸሹ ጊዜ ጥሪን አታሰማም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ እውሮችንም ከጥመታቸው የምታቀና አይደለህም:: በአናቅጻችን የሚያምኑትን ሰዎች እንጂ ሌላን አታሰማም:: እነርሱም ታዛዦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 54, '54. (ሰዎች ሆይ!) አላህ ያ ከደካማ ፍትወት ጠብታ የፈጠራችሁ ነው:: ከዚያ ከደካማነት በኋላም ኃይልን አደረገ:: ከዚያም ከብርቱነት በኋላ ደካማነትና ሽበትንም አደረገ:: የሚሻውን ይፈጥራል:: እርሱም ሁሉን አዋቂውና ቻዩ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 55, '55. ሰዓቲቱ በምትከሰትበት ቀን ከሓዲያን «ከአንዲት ሰዓት በስተቀር በመቃብር (በዱንያ) አልቆየንም።» ብለው ይምላሉ:: ልክ እንደዚሁ በዚህኛው ዐለምም እያሉ ከእውነት ይመለሱ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 56, '56. እነዚያም እውቀትንና እምነትን የተሰጡት «በአላህ መጽሐፍ ፍርድ እስከ ትንሳኤ ቀን በእርግጥ ቆያችሁ ይህም የካዳችሁት የትንሳኤ ቀን ነው:: ግን እናንተ የማታውቁ ነበራችሁ።» ይሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 57, '57. በዚያም ቀን እነዚያን የበደሉትን ማመካኘታቸው አይጠቅማቸዉም:: እነርሱም በወቀሳ አይታለፉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 58, '58. በዚህም ቁርኣን ውስጥ ለሰዎች የምሳሌ አይነቶችን ሁሉ በእርግጥ ገለጽን:: በተዓምርን ብታመጣላቸው እንኳን እነዚያ በአላህ የካዱት ሰዎች «እናንተ አበላሺዎች የጥፋት ተጣሪ ዎች እንጂ ሌላ አይደላችሁም።» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 59, '59 ልክ እንደዚሁ አላህ በነዚያ በማያውቁት ሰዎች ልቦች ላይ ያትማል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (30, 60, '60. (መልዕክተኛችን ሙሐመድ ሆይ!) ስለዚህ ታገሥ:: የአላህ ቀጠሮ እውነት ነውና:: እነዚያም በትንሳኤ የማያረጋግጡት ሰዎች አያቅልሉህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 1, '1. አሊፍ፤ ላም፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 2, '2. እነዚህ አናቅጽ ጥበብ ከተሞላው መጽሐፍ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 3, '3. ለበጎ አድራጊዎች ሁሉ መሪ፣ እዝነት ሲሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 4, '4. ለእነዚያ ሶላትን አስተካክለው ለሚሰግዱ፤ ዘካንም ለሚሰጡት፤ በመጨረሻይቱም ዓለም የሚያረጋግጡ ለሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 5, '5. እነዚያ (የተጠቀሱትን ባህሪያት የሚላበሱ ሰዎች ሁሉ) በጌታቸው መመሪያ ላይ የሚጓዙ ናቸው። እነዚያ ፍላጎታቸውንም ያገኙትም እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 6, '6. ከሰዎች መካከል ያለ ምንም እውቀት ሰዎችን ከአላህ መንገድ ሊያሳስትና የአላህን መንገድ ማላገጫ ሊያደርግ አታላይ ወሬን የሚገዛ አለ:: እነዚያ ይህን የሚያደርጉ ሁሉ ለእነርሱ አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 7, '7. አናቅጻችን በእርሱ ላይ በሚነበቡ ጊዜ እንዳልሰማትና በጆሮቹ ድንቁርና እንዳለበት የኮራ ሆኖ ይዞራል:: (መልዕክተኛችን ሙሐመድ ሆይ!) ይህን ሰው በአሳማሚ ቅጣት አብስረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 8, '8. እነዚያ ያመኑና መልካሞችን ተግባራት የሰሩ ሁሉ ለእነርሱ የጸጋ ገነቶች አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 9, '9. በእርሷ ውስጥ ዘውታሪዎች ሲሆኑ አላህ እውነተኛን የተስፋ ቃል ገባላቸው:: እርሱም ሁሉንም አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 10, '10. ሰማያትን የምታዮዋት ምሰሶ ሳያደርግላት ፈጠረ:: በምድርም ውስጥ በእናንተ እንዳታረገርግ ተራራዎችን ጣለ:: በእርሷም ላይ ከተንቀሳቃሽ ነገሮች ሁሉ በተነ:: ከሰማይም ውሃን አወረድን:: በእርሷ ውስጥ ከመልካም ዓይነት ሁሉ አበቀልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 11, '11. ይህ ሁሉ የአላህ ፍጡር ነው:: እነዚያ ከእርሱ ሌላ ያሉት ምንን እንደ ፈጠሩ እስኪ አሳዩኝ:: በዳዮች በእውነት በግልጽ ጥመት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 12, '12. ለሉቅማንም ጥበብን በእርግጥ ሰጠነው:: አላህን አመስግን አልነዉም:: ያመሰገነም ሁሉ የሚያመሰግነው ለራሱ ብቻ ነው:: የካደም ሰውም (በራሱ ላይ ነው::) አላህ ተብቃቂና ምስጉን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) ሉቅማንም ለልጁ እርሱ የሚገስጸው ሲሆን «ልጄ ሆይ! በአላህ አታጋራ። ማጋራት ታላቅ በደል ነውና።» ያለውን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 14, '14. ሰውንም በወላጆቹ በጎ እንዲያደርግ በጥብቅ አዘዝነው:: እናቱ ከድካም በላይ በሆነ ድካም አረገዘችው:: ጡት መጣያዉም በሁለት ዓመት ውስጥ ነው:: «ለእኔም ለወላጆችህም አመስግን" በማለትም አዘዝነው። መመለሻው ወደ እኔ ብቻ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 15, '15. ላንተ በእርሱ እውቀት የሌለህን ነገር በእኔ እንድታጋራ ቢያስገድዱህ አትታዘዛቸው:: በቅርቢቱም ዓለም በመልካም ስራ ተወዳጃቸው:: ወደ እኔም የተመለሰን ሰው መንገድ ተከተል:: ከዚያ መመለሻችሁ ወደ እኔ ነው:: ትሰሩት የነበራችሁትንም ሁሉ እነግራችኋለሁ (አልነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 16, '16. (ሉቅማንም አለ:) «ልጄ ሆይ! የእርሷ (መጥፎም ይሁን በጎ) የሰናፍጭ ቅንጣት ክብደት ያህል እንኳን ብትሆንና በቋጥኝ ውስጥ ወይም በሰማያት ውስጥ ወይም በምድር ውስጥ ብትሆን አላህ ያመጣታል:: አላህ ሩህሩህና ውስጠ አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 17, '17. «ልጄ ሆይ! ሶላትን አስተካክለህ ስገድ፤ በበጎ ነገርም እዘዝ ከሚጠላም ሁሉ ከልክል፤ በሚያገኝህም መከራ ላይ ታገስ ይህ በምር ከሚያዙ ወሳኝ ነገሮች ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 18, '18. «ጉንጭህንም በኩራት ከሰዎች አታዙር:: በምድርም ላይ ተንበጥርረህ አትሂድ:: አላህ ተንበጥራሪን (ኮራተኛ) ጉረኛን ሁሉ አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 19, '19. «በአካሄድህም መካከለኛ ሁን:: ከድምጽህም ዝቅ አድርግ:: ከድምፆች ሁሉ አስከፊው የአህዮች ድምጽ ነውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 20, '20. (ሰዎች ሆይ!) አላህ በሰማያት እና በምድር ውስጥ ያለውን ነገር ሁሉ ለእናንተ ያገራላችሁ፤ ጸጋዎችንም ግልጽም ይሁኑ ድብቅ የሞላላችሁ መሆኑን አታዩምን? ከስሞች መካከል ያለ በቂ እውቀትና ያለ መሪ፤ ያለ ግልጽ መጽሀፍም፤ ስለ አላህ የሚከራከር አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 21, '21. ለእነርሱም «አላህ ያወረደውን ተከተሉ።» በተባሉ ጊዜ «አይደለም በእርሱ ላይ አባቶቻችንን ያገኘንበትን እንከተላለን።» ይላሉ:: ሰይጣን (ይህን ተግባር በማስዋብ) ወደ እሳት ቅጣት የሚጠራቸው ቢሆንም ይከተሏቸዋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 22, '22. መልካም ሰሪ ሆኖ ፊቱን ወደ አላህ የሚሰጥ ሁሉ ጠንካራ ገመድን በእርግጥ ጨበጠ:: የነገሩ ሁሉ ፍጻሜ ወደ አላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 23, '23. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ የካደም ሁሉ ክህደቱ አያሳዝንህ። መመለሻቸው ወደ እኛ ብቻ ነውና:: ከዚያም የሰሩትንም ሁሉ እንነግራቸዋለን:: አላህ በልቦች ውስጥ ያለን ሁሉ ያውቃልና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 24, '24. ጥቂትን ጊዜ እናጣቅማቸዋለን:: ከዚያም ወደ ብርቱ ቅጣት እናስገድዳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 25, '25. ሰማያትንና ምድርን የፈጠረ ማን እንደሆነ ብትጠይቃቸው «በእርግጥ አላህ ነው።» ይላሉ። «ምስጋና ሁሉ ለአላህ ብቻ ይገባው።» በላቸው:: ይልቁንም አብዛኞቹ አያውቁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 26, '26. በሰማያትና በምድር ያለው ሁሉ የአላህ ብቻ ነው:: አላህ በራሱ ተብቃቂዉና ምስጉኑ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 27, '27. በምድር ያሉ ሁሉ ዛፎች ብዕሮች ቢሆኑ ኖሮ ባህሩም ከእርሱ ማለቅ በኋላ ሰባት ባህሮች የሚጨመሩለት ሆኖ ቀለም ቢሆንና ቢጻፍባቸው የአላህ ቃላት ባላለቀች ነበር:: አላህ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 28, '28. (ሰዎች ሆይ!) እናንተን መፍጠርና እናንተን መቀስቀስ እንደ አንዲት ነፍስ እንጂ ሌላ አይደለም:: አላህ ሁሉን ሰሚና ሁሉን ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 29, '29. (የሰው ልጅ ሆይ) አላህ ሌሊትን በቀን ውስጥ የሚያስገባ ቀንንም በሌሊት ውስጥ የሚያስገባ ጸሀይንና ጨረቃንም የገራ መሆኑን አታይምን? ሁሉም እስከ ተወሰነ ጊዜ ድረስ ይሮጣሉ:: አላህም በምትሰሩት ሁሉ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 30, '30. ይህም የእርሱ (የአላህ) ብቸኛ አምላክነት እውነት በመሆኑ፤ ከእርሱ ሌላ የሚገዙት ጣዖት ሁሉ ውሸት በመሆኑና አላህ የበላይ ታላቅ በመሆኑ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 31, '31. (የሰው ልጅ ሆይ!) ከአስደናቂ ምልክቶቹ ሊያሳያችሁ መርከቦች በአላህ ችሮታ በባህር ውስጥ የሚንሻለሉ መሆናቸውን አታይምን? በዚህ ውስጥ በጣም ታጋሽ አመስጋኝ ለሆኑ ሁሉ አያሌ ተዓምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 32, '32. እንደ ጥላዎች የሆነ ማዕበል በሸፈናቸው ጊዜ ሃይማኖትን ለእርሱ ብቻ ያጠሩ ሆነው አላህን ይጠሩታል:: ወደ የብስ ባዳናቸው ጊዜ ግን ከእነርሱ መካከል ትክክለኛም አለ:: (ከእነርሱም መካከል የሚክድ አለ):: በአናቅጻችንም አታላይና ከዳተኛ የሆነ ሁሉ እንጂ ሌላው አይክድም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 33, '33. እናንተ ሰዎች ሆይ! ጌታችሁን ፍሩ:: ወላጅ ከልጁ በምንም የማይጠቅምበት ልጅም ወላጅን በምንም ጠቃሚ የማይሆንበትን ቀን ፍሩ:: የአላህ ቀጠሮ እውነት ነውና:: ቅርቢቱም ህይወት አትሸንግላችሁ:: በአላህ (መታገስም) አታላዩ (ሰይጣን) አያታልላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (31, 34, '34. አላህ የሰዓቲቱ እውቀት እርሱ ዘንድ ብቻ ነው:: ዝናብንም ያወርዳል:: በማህጸኖችም ውስጥ ያለን ሁሉ ያውቃል። ማንኛይቱም ነፍስ ነገ የምትሰራውን አታውቅም:: ማንኛይቱም ነፍስ በየትኛው ምድር እንደምትሞትም አታውቅም:: አላህ አዋቂና ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 1, '1. አሊፍ፤ ላም፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 2, '2. የመጽሐፉ መወረድ ጥርጥር የለበትም:: የወረደዉም ከዓለማቱ ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 3, '3. ይልቁንም «ቀጠፈው» ይላሉን? አይደለም:: (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱ ከጌታህ የሆነ እውነት ነው:: በእርሱ ካንተ በፊት ከአስፈራሪ ነቢይ ያልመጣባቸውን ሕዝቦች በእርሱ ልታስፈራራበት ያወረደልህ ነው:: እነርሱ ሊመሩ ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 4, '4. አላህ ያ! ሰማያትንና ምድርን በመካከላቸውም ያለውን ሁሉ በስድስት ቀናት ውስጥ የፈጠረ ከዚያም ለክብሩ በሚስማማ መልኩ በዐርሹ ላይ ከፍ ያለ ነው:: ከእርሱ ሌላ ለእናንተ ወዳጅም አማላጅም ምንም የላችሁም:: አትገሰጹምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 5, '5. ነገሩን ሁሉ ከሰማይ ወደ ምድር ያዘጋጃል፤ ከዚያም ከምትቆጥሩት (ዘመን) ልኩ ሺህ ዓመት በሆነ ቀን ውስጥ ወደ እርሱ ይወጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 6, '6. ይህንን ያደረገው ሩቁንም ቅርቡንም ሁሉ አዋቂው፤ ሁሉን አሸናፊና አዛኙ ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 7, '7. ያ የፈጠረውን ነገር ሁሉ ያሳመረው:: የሰውንም ፍጥረት ከጭቃ የጀመረው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 8, '8. ከዚያም ዘሮቹን ከተንጣለለ ከደካማ ውሃ የፈጠረ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 9, '9. ከዚያም ቅርጹን አስተካከለው:: በእርሱ ውስጥም ከመንፈሱ ነፍስ ዘራበት:: ለናንተም ጆሮዎችን ዓይኖችንና ልቦችንም አደረገላችሁ። በጣም ጥቂትን ብቻ ታመሰግናላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 10, '10. «በምድርም ውስጥ በስብሰን በጠፋን ጊዜ እኛ በአዲስ መፈጠር ውስጥ እንሆናለን?» አሉ:: በእውነቱ እነርሱ በጌታቸው መገናኘት ከሓዲያን ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ!) «በእናንተ ላይ የተወከለው መልአከ ሞት ይገድላችኋል:: ከዚያም ወደ ጌታችሁ ትመለሳላችሁ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 12, '12. አመጸኞችም በጌታቸው ዘንድ ራሶቻቸውን ያቀረቀሩ ሆነው፡‐ «ጌታችን ሆይ! አየን። ሰማንም። መልካምን እንሠራለንና (ወደ ምድረ ዓለም) መልሰን እኛ አረጋጋጮች ነን» የሚሉ ሲሆኑ ብታይ ኖሮ( አስደንጋጭን ነገር ታይ ነበር)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 13, '13 በሻንም ኖሮ ነፍስን ሁሉ ቅንነቷን(እምነቷን) በሰጠናት ነበር:: ግን ገሀነምን ከአጋንንትና ከሰዎች የተሰበሰቡ ሆነው በእርግጥ እሞላለሁ ማለት ቃሉ ከእኔ ተረጋግጧል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 14, '14. ይህንንም ቀናችሁን መገናኘትን በመርሳታችሁ ምክንያት ቅጣትን ቅመሱ! እኛ ተውናችሁ። ትሰሩት በነበራችሁትም ጥፋት ዘውታሪን ቅጣት ቅመሱ ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 15, '15. በአናቅጻችን የሚያምኑት እነዚያ በእርሷ በተገሰጹ ጊዜ ሰጋጆች ሆነው የሚወድቁትና እነርሱም የማይኮሩ ሆነው በጌታቸው ምስጋና (ተጎናጽፈው) የሚያወድሱት ሰዎች ብቻ ናቸው። {1}', '{1} እዚህጋ ሱጁዱትላዋ (የንባብ ሱጁድ) መድረግ ያስፈልጋል። በሶላት ውስጥም ከሶላት ውጪም መድረጉ ይወደዳል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 16, '16. ጌታቸውን ለመፍራትና ለመከጀል የሚጠሩት ሆነው ጎኖቻቸው ከመጋደሚያ ቦታዎቻቸው ይርቃሉ:: ከሰጠናቸዉም ጸጋ ይለግሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 17, '17. ይሰሩት በነበሩት ለመመንዳት ከዓይኖች መርጊያ ለእነርሱ የተደበቀላቸውን ጸጋ ማንኛይቱም ነፍስ አታውቅም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 18, '18. አማኝ የሆነ ሰው አመጸኛ እንደሆነ ሰው ነውን? አይስተካከሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 19, '19. እነዚያ ያመኑና መልካሞችን የሰሩማ ለነሱ ይሰሩት በነበሩት ምክንያት መስተንግዶ ሲሆኑ መኖሪያ ገነቶች አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 20, '20. እነዚያ ያመጹትማ መኖሪያቸው እሳት ናት:: ከእርሷ መውጣትን በፈለጉ ቁጥር በእርሷ ውስጥ ይመለሳሉ ለእነርሱም «ያንን በእርሱ ታስተባብሉበት የነበራችሁትን የእሳት ቅጣት ቅመሱ» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 21, '21. ይመለሱ ዘንድ ከትልቁ ቅጣት በፊት (በዚህ ዓለም) ትንሹን ቅጣት በእርግጥ እናቀምሳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 22, '22. በጌታዉም አናቅጽ ከተገሰጸና ከዚያም ከተዋት ሰው ይበልጥ በደለኛ ማነው? (የለም) እኛ ከተንኮለኞቹ ሁሉ ተበቃዮች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 23, '23.ሙሳን መጽሐፍን በእርግጥ ሰጠነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱን ከመገናኘትህም በመጠራጠር ውስጥ አትሁን:: ለኢስራኢል ልጆችም መሪ አደረግነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 24, '24. በታገሱና በተዓምራታችን የሚያረጋግጡ በሆኑም ጊዜ ከእነርሱ በትዕዛዛችን የሚመሩ መሪዎችን አደረግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በዚያ ይለያዩበት በነበሩት ነገር ሁሉ በትንሳኤ ቀን በመካከላቸው በፍርድ ይለያል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 26, '26. ከክፍለ ዘመናት ሰዎች ብዙዎችን ያጠፋን መሆናችን በመኖሪያዎቻቸው የሚሄዱ ሲሆኑ እነርሱ አልተገለጸላቸዉምን? በዚህ ውስጥ አያሌ ምልክቶች አሉበት:: አይሰሙምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 27, '27. እኛ ውሃን ወደ ደረቅ ምድር የምንነዳ እንስሶቻቸውና ነፍሶቻቸው ከእርሱ የሚበሉለትንም አዝመራ በእርሱ የምናወጣ መሆናችንን አያዩምን? አይመለከቱምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 28, '28. «ከእውነተኞችም እንደ ሆናችሁ ይህ ፍርድ መቼ ነው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 29, '29. «በፍርዱ ቀን እነዚያን የካዱትን ሰዎች እምነታቸው አይጠቅማቸዉም:: እነርሱም ጊዜን አይሰጡም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (32, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱን ተዋቸው:: ተጠባበቅም:: እነርሱም ተጠባባቂዎች ናቸውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 1, '1. አንተ ነብይ ሆይ! አላህን ፍራ:: ከሓዲያንንና አስመሳዮችንም አትታዘዝ:: አላህ ሁሉን አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) ከጌታህም ወደ አንተ የሚወረደውን ብቻ ተከተል:: አላህ በምትሰሩት ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ ላይ ተመካ:: መመኪያነትም በአላህ ብቻ በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 4, '4. (ሙስሊሞች ሆይ!) አላህ ለአንድ ሰው በሆዱ ውስጥ ሁለትን ልቦች አላደረገም:: እነዚያን «እንደናቶቻችን ጀርባዎች ይሁኑብን» የምትሏቸውን ሚስቶቻችሁንም እናቶቻችሁ አላደረገም:: ልጅ በማድረግ የምታስጠጓቸውንም ልጆቻችሁ አላደረገም:: ይህ በአፎቻችሁ የምትሉት ቃላችሁ ብቻ ነው:: አላህ እውነትን ይናገራል:: ትክክለኛውን መንገድም ይመራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 5, '5. (ሙስሊሞች ሆይ!) (ልጅ በማድረግ የምታስጠጓቸውን) በአባቶቻቸው ስም በማስጠጋት ጥሯቸው:: እርሱ አላህ ዘንድ ትክክለኛው መንገድ ነውና:: አባቶቻቸውን ባታውቁም በሃይማኖት ወንድሞቻችሁና ዘመዶቻችሁ ናቸው:: በተሳሳታችሁበት ነገርም በእናንተ ላይ ምንም ኃጢአት የለባችሁም:: ልቦቻችሁ አውቀው በሰራችሁት ስህተት ግን ኃጢአት አለባችሁ:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 6, '6. ነብዩ (ሙሐመድ) ለአማኞች ከነፍሶቻቸው ይበልጥ ቀራቢ ነው:: ሚስቶቹም እናቶቻቸው ናቸው:: የዝምድና ባለቤቶችም ከፊላቸው በከፊሉ ላይ (ለውርስ) በአላህ መጽሐፍ ውስጥ ከአማኞችና ከስደተኞች ይልቅ የተገባቸው ናቸው:: ለወዳጆቻችሁ በኑዛዜ መልካም ስራን ብትሰሩ ግን ይፈቀዳል:: ይህ በአላህ መጽሐፉ ውስጥ ቀድሞውኑ የተመዘገበ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) ከነብዮችም ካንተም፤ ከኑህም፤ ከኢብራሂምም፤ ከሙሳም፤ ከመርየም ልጅ ዒሳም የጠበቀ ቃልኪዳናቸውን በያዝን ጊዜ (የሆነውን አስታውስ):: ከእነርሱም የከበደን ቃል ኪዳን ያዝን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 8, '8. አላህ እውነተኞችን ከእውነታቸው ሊጠይቃቸው (ይህንን ሰራ):: ለከሓዲያንም አሳማሚን ቅጣት አዘጋጀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 9, '9. እናንተ ያመናችሁ ሆይ! ብዙ ሰራዊት በመጣባችሁና በእነርሱ ላይ ንፋስንና በአይናችሁ ያላያችሁትን ሰራዊት በላክን ጊዜ ያደረገላችሁን ጸጋ አስታውሱ:: አላህም የምትሰሩትን ተመልካች ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 10, '10. ከበላያችሁም ከናንተ በታችም በመጡባችሁ፤ ዓይኖችም በቃበዙ፤ ልቦችም ወደ ላንቃዎች በደረሱና በአላህም መጥፎ ጥርጣሬዎችን በጠረጠራችሁ ጊዜ ያደረገላችሁን ጸጋ (አስታውሱ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 11, '11. እዚያ ዘንድ አማኞች ተሞከሩ:: ብርቱን መንቀጥቀጥም ተንቀጠቀጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 12, '12. መናፍቆችና እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸው ሰዎች ሁሉ «አላህና መልዕክተኛው ማታለልን እንጂ ሌላን አልቀጠሩንም።» በሚሉም ጊዜ ያደረገላችሁን ውለታ አስታውሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም የሆነ ቡድን «የየስሪብ ሰዎች ሆይ! ለእናንተ ስፍራ የላችሁምና ተመለሱ።» ባሉ ጊዜ (የሆነውን አስታውሱ):: ከእነርሱም መካከል ከፊሎቹ ነውረኛ ሳይሆኑ «ቤቶቻችን ነውረኛ ናቸው።» በማለት ነብዩን ከጦሩ ለመመለስ ፈቃድን ይጠይቃሉ:: መሸሽን እንጂ ሌላን አይፈልጉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 14, '14. በእርሱም ላይ በቤቶቻቸው ከየቀበሌዋ ከጠላት በተገባባትና ከዚያም ከኢስላም መመለስን በተጠየቁ ኖሮ በፍጥነት በሰሯት ነበር ፡፡ በእሷ ጥቂትን ጊዜ እንጂ አይቆዩም ነበር ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 15, '15. ጀርባዎችንም ላያዞሩ ከዚያም በፊት በእርግጥ አላህን ቃል ኪዳን የገቡ ነበሩ:: የአላህም ቃል ኪዳን የሚጠየቁበት ትልቅ ሀላፊነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 16, '16. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከሞት ወይም ከመገደል ብትሸሹ መሸሻችሁ ፈጽሞ አይጠቅማችሁም:: ያን ጊዜም ጥቂትን እንጂ የምትጣቀሙ አትደረጉም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) (ሙስሊምቸ ሆይ!) «አላህ በእናንተ ላይ ክፉን ነገር ቢሻ ያ ከአላህ የሚጠብቃችሁ ማን ነው? ወይም ለእናንተ እዝነትን ቢፈልግ ክፉ የሚያመጣባችሁ ማን ነው?» በላቸው። ከአላህም ሌላ ለእነርሱ ወዳጅም ሆነ ረዳት አያገኙም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 18, '18. ከናንተ ውስጥ የሚያደናቅፉትን ለወንድሞቻቸዉም «ወደ እኛ ኑ» የሚሉትን፤ ውጊያንም ጥቂትን እንጂ የማይመጡትን በእርግጥ አላህ ያውቃቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 19, '19. (አማኞች ሆይ!) በእናንተ ላይ እርዳታን የነፈጉ ሆነው እንጂ የማይመጡትን፤ ሽብሩም በመጣ ጊዜ እንደዚያ ከሞት መከራ በእርሱ ላይ የሚሸፍን አደጋ እንደ ወደቀበት ዓይኖቻቸው ወዲያና ወዲህ የምትንከራተት ሆና ወደ አንተ ሲመለከቱ ታያቸዋለህ:: ሽብሩም በሄደ ጊዜ በገንዘብ ላይ የሚሳሱ ሆነው በተቡ ምላሶች ይነድፏችኋል:: እነዚያ አላመኑም:: ስለዚህ አላህ ስራዎቻቸውን አበላሸ:: ይህም በአላህ ላይ ገር ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 20, '20. (መናፍቆች) አህዛብን አልሄዱም ብለው ያስባሉ አህዛቦችም ቢመጡ እነርሱ በዘላኖች ውስጥ በገጠር የራቁ ሊሆኑ ይመኛሉ:: (ከዚያም) ከወሬዎቻችሁ ይጠይቃሉ:: በእናንተ ውስጥ በነበሩም ኖሮ ጥቂትን እንጂ አይዋጉም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 21, '21. (አማኞች ሆይ!) ከናንተ መካከል አላህንና የመጨረሻውን ቀን የሚከጅል ለሆነና አላህንም በብዙ ለሚያወሳ ሰው ሁሉ በአላህ መልዕክተኛ መልካም መከተል አላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 22, '22. አማኞችም አህዛብን ባዩ ጊዜ «ይህ አላህና መልዕክተኛው የቀጠሩን ነው:: አላህና መልዕክተኛዉም እውነትን ተናገሩ።» አሉ:: ይህ እምነትንና መታዘዝንም እንጂ ሌላን አልጨመረላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 23, '23. ከአማኞች መካከል በእርሱ ላይ ለአላህ ቃል ኪዳን የገቡበትን በእውነት የፈጸሙ ወንዶች አሉ። ከእነርሱም ስለቱን የፈጸመ ለሃይማኖቱ የተገደለም አለ:: ከእነርሱም መካከል ገና የሚጠባበቅ አለ:: የገቡትን ቃል መለወጥንም አለወጡም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 24, '24. አላህ እውነተኞችን በእውነተኛነታቸው ሊመነዳ፤ አስመሳዮችንም ቢፈልግ ሊቀጣ ወይም ቢመለሱ በእነርሱ ላይ ጸጸታቸቸውን ሊቀበል ይህን አደረገ:: አላህ መሃሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 25, '25. እነዚያንም በአላህ የካዱትን በቁጭታቸው የተሞሉ መልካምን ነገር ያላገኙ ሆነው አላህ መለሳቸው:: አማኞቹንም አላህ መጋደልን በቃቸው:: አላህም ብርቱና ሁሉን አሸናፊ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 26, '26. እነዚያንም ከመጽሐፉ ባለቤቶች አህዛቦችን የረዷቸውን (ቁረይዟን) ከምሽጎቻቸው አወረዳቸው:: በልቦቻቸዉም ውስጥ መባባትን ጣለባቸው። ከፊሉን ትገድላላችሁ፤ ከፊሉንም ትማርካላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 27, '27. ምድራቸውንም ቤቶቻቸውንም ገንዘቦቻቸውንም ገና ያልረገጣችኋትንም ምድር አወረሳችሁ:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 28, '28. አንተ ነብይ ሆይ! ለሚስቶችህ (እንዲህ) በላቸው: «ቅርቢቱን ህይወትና ጌጧን የምትፈልጉ እንደ ሆናችሁ ኑ:: አጣቅማችኋለሁና መልካምንም መፍታት እፈታችኋለሁና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 29, '29. «አላህንና መልዕክተኛውን የመጨረሻይቱን አገርም የምትፈልጉ ከሆናችሁ እነሆ አላህ ከናንተ ለመልካም ሰሪዎቹ ትልቅን ምንዳ አዘጋጅቷል።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 30, '30. እናንተ የነብዩ ሚስቶች ሆይ! ከናንተ ውስጥ ግልጽ የሆነን መጥፎ ስራ የምትሰራ ሴት ቅጣቷ ሁለት እጥፍ ሆኖ ይነባበርባታል:: ይህም በአላህ ዘንድ ገር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 31, '31. ከናንተም መካከል ለአላህና ለመልዕክተኛው የምትታዘዝ መልካም ስራንም የምትሰራ ሴት ምንዳዋን ሁለት ጊዜ እንሰጣታለን:: ለእርሷም የከበረን ሲሳይ አዘጋጅተንላታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 32, '32. እናንተ የነቢዩ ሚስቶች ሆይ! እንደ ማናቸዉም ሴቶች አይደላችሁም:: አላህን ብትፈሩ ትበልጣላችሁ። በልቡ ውስጥ በሽታ ያለበት እንዳይከጅል በንግግር እንኳን አትለስልሱም:: መልካምንም ንግግር ተናገሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 33, '33. በቤቶቻችሁም ውስጥ እርጉ:: እንደ ፊተኛይቱ መሃይምነት ጊዜ መገላለጥም (በመጌጥ) አትገለጡ:: ሶላትንም በደንቡ ስገዱ:: ዘካንም ስጡ:: አላህንና መልክተኛውንም ታዘዙ:: የነብዩ ቤተሰቦች ሆይ! አላህ የሚሻው ከናንተ ላይ ርክሰትን ሊያስወግድና ማጥራትንም ሊያጠራችሁ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 34, '34. ከአላህ አናቅጽና ከጥበቡም በቤቶቻችሁ የሚነበበውን አስታውሱ:: አላህ እዝነቱ ረቂቅና ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 35, '35. ሙስሊም ወንዶችና ሙስሊም ሴቶች፤ ምእምናንና ምዕመናትም፤ ታዛዦች ወንዶችና ታዛዦች ሴቶችም፤ እውነተኞች ወንዶችና እውነተኞች ሴቶችም፤ ታጋሽ ወንዶችና ታጋሽ ሴቶችም፤ አላህን ፈሪ ወንዶችና አላህን ፈሪ ሴቶችም፤ መጽዋች ወንዶችና መጽዋች ሴቶችም፤ ጿሚ ወንዶችና ጿሚ ሴቶችም፤ ካልተፈቀደ ስራ ብልቶቻቸውን ጠባቂ ወንዶችና ጠባቂ ሴቶችም፤ አላህን በብዙ አውሺ ወንዶችና አውሺ ሴቶችም አላህ ለእነርሱ ምህረትንና ታላቅን ምንዳ አዘጋጅቶላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 36, '36. አላህና መልዕክተኛው በአንድ ነገር ላይ በወሰኑ ጊዜ ለምዕምናንና ለምዕመናት ከተነገራቸው ከመቀበል ዉጭ ምንም ምርጫ ሊኖራቸው አይገባም:: የአላህንና የመልክተኛውን ትእዛዝ የጣሰ ሰው ሁሉ ግልጽ የሆነን መሳሳት በእርግጥ ተሳሳተ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 37, '37. (መልዕክተኛችን ሙሐመድ ሆይ!) ለዚያም አላህ በእርሱ ላይ ለለገሰለትና አንተም (ነጻ በማውጣት) በእርሱ ላይ ለለገስክለት ሰው አላህ ገላጩ የሆነን ነገር በነፍስህ ውስጥ የምትደብቅና አላህን ልትፈራው ይልቅ የተገባው ሲሆን ሰዎችን የምትፈራ ሆነህ «ሚስትህን ያዝ:: አላህንም ፍራ» በምትል ጊዜ (የሆነዉን አስታውስ):: ዘይድም ከእርሷ ጉዳዩን በፈጸመ ጊዜ በምዕመኖች ላይ ልጅ አድርገው ባስጠጓቸው ሰዎች ሚስቶች ከእነርሱ ጉዳይን በፈጸሙ ጊዜ በማግባት ችግር እንዳይደርስባቸው እርሷን አጋባንህ (ዳርንህ):: የአላህም ትእዛዝ ተፈጻሚ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 38, '38. በነብዩ ላይ አላህ ለእርሱ በፈረደው ነገር ምንም ችግር ሊኖርበት አይገባም:: በእነዚያ ከዚያ በፊት ባለፉት ነብያት አላህ ደነገገው። የአላህም ትእዛዝ የተፈረደ ፍርድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 39, '39. ለእነዚያ የአላህን መልዕክቶች ለሚያደርሱና ለሚፈሩት ከአላህ በስተቀርም አንድንም ለማይፈሩት ተደነገገ። ተቆጣጣሪነትም በአላህ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 40, '40. (እናንተ ያመናችሁ ሆይ!) ሙሐመድ ከወንዶቻችሁ የአንዱም ሰው አባት አይደለም:: ግን የአላህ መልዕክተኛና የነብያት መደምደሚያ ነው:: አላህ በነገሩ ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 41, '41. እናንተ ያመናችሁ ሆይ! አላህን ብዙ ማውሳትን አውሱት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 42, '42. በቀኑ መጀመሪያና መጨረሻም አጥሩት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 43, '43. እርሱ ያ በእናንተ ላይ እዝነትን የሚያወርድ ነው:: መላእክቶችም እንደዚሁ ምህረትን የሚለምኑላችሁ ናቸው:: ከጨለማዎች ወደ ብርሃን ያወጣችሁ ዘንድ (ያዝንላችኋል):: ለትክክለኛ አማኞችም በጣም አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 44, '44. በሚገናኙበት ቀን መከባበሪያቸው ሰላም መባባል ነው:: ለእነርሱም የከበረን ምንዳ አዘጋጅቶላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 45, '45. አንተ ነብይ ሆይ! እኛ መስካሪ አብሳሪና አስፈራሪ አድርገን ላክንህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 46, '46. ወደ አላህም በፈቃዱ ጠሪ፣ አብሪና ብርሃን አድርገን ላክንህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) አማኞችንም ከአላህ ዘንድ ለእነርሱ ታላቅ ችሮታ ያላቸው መሆኑን አብስራቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያንና አስመሳዮችንም አትታዘዛቸው ማሰቃየታቸውንም (ለአላህ) ተው:: በአላህም ላይ ተጠጋ:: በመጠጊያነትም አላህ በቃ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 49, '49. እናንተ ያመናችሁ ሆይ! ምዕመናትን ባገባችሁና ከዚያም ሳትነኳቸው በፊት በፈታችኋቸው ጊዜ ለናንተ በእነርሱ ላይ የምትቆጥሩዋት ዒዳ ምንም የላችሁም:: ሆኖም አጣቅሟቸው (ጉርሻ ስጧቸው):: መልካም ማሰናበትንም አሰናብቷቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 50, '50. አንተ ነብይ ሆይ! እነዚያን መህሮቻቸውን የሰጠሃቸውን ሚስቶችህን፤ አላህ ባንተ ላይ ከመለሰልህም ሴቶች መካከል እነዚያን እጅህ የጨበጠቻቸውን ምርኮኞች ሴቶች፤ እነዚያን ካንተ ጋር የተሰደዱትን የአጎቶችህንና፤ የአክስቶችህን ሴት ልጆች (እንደዚሁም) የእናትህ ወንድም ሴት ልጆችና የእናትህ እህት ሴት ልጆች ማግባትን ላንተ ፈቅደንልሃል:: ማንኛዋም በአላህ ያመነች ሴት ራሷን ለነብዩ ብትሰጥ ነብዩ ሊያገባት የፈለገ እንደ ሆነ ከአማኞች ሌላ ላንተ ብቻ የተሰጠ መብት ሲሆን ፈቀድንልህ:: በአማኞች ላይ በሚስቶቻቸውና እጆቻቸው በጨበጧቸው ባሮች ነገር ግዴታ ያደረግንባቸውን በእርግጥ አውቀናል:: ባንተ ላይ ችግር እንዳይኖር ያለፉትን ፈቀድንልህ:: አላህ መሃሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ መካከል የምትፈልጋትን ታቆያለህ :: የምትፈልጋትንም ወደ አንተ ታስጠጋለህ:: በመፍታት ከአራቅሃትም የፈለግሃትን በመመለስ ብታስጠጋ ባንተ ላይ ኃጢአት የለብህም:: ይህ ዓይኖቻቸው ወደ መርጋት ወደ አለማዘናቸዉም ለሁሉም በሰጠሃቸው ነገር ወደ መውደዳቸዉም በጣም የቀረበ ነው:: አላህም በልቦቻችሁ ውስጥ ያለውን ሁሉ ያውቃል:: አላህ ሁሉን አዋቂና ታጋሽ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 52, '52. ከእነዚህ በኋላ እጅህ ከጨበጠቻቸው ባሮች በስተቀር ሴቶች ላንተ አይፈቅዱልህም ከሚስቶችም መልካቸው ቢደንቅህም እንኳን በእነርሱ ልትለውጥ አይፈቀድልህም። አላህ በነገሩ ሁሉ ተጠባባቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 53, '53. እናንተ ያመናችሁ ሆይ! መድረሱን የማትጠባበቁ ስትሆኑ ወደ ምግብ ካልተፈቀደላችሁ በስተቀር የነብዩን ቤቶች በምንም ጊዜ አትግቡ ግን በተጠራችሁ ጊዜ ግቡ በተመገባችሁም ጊዜ ወዲያውኑ ተበተኑ:: ለወግ የምትጫወቱ ሆናችሁም አትቆዩ:: ይሃችሁ ነብዩን በእርግጥ ያስቸግራል:: ከናንተም ያፍራል። ግን አላህ ከእውነት አያፍርም:: እቃንም ለመዋስ በጠየቃችኋቸው ጊዜ ከመጋረጃ ኋላ ሆናችሁ ጠይቋቸው። ይሃችሁ ለልቦቻችሁም ለልቦቻቸዉም የበለጠ ንጽህና ነው:: የአላህንም መልክተኛ ልታስቸግሩ ሚስቶቹንም ከእርሱ በኋላ ምንጊዜም ልታገቡ ለእናንተ አይገባችሁም። ይሃችሁ አላህ ዘንድ ከባድ ኃጢአት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 54, '54. ማንኛውንም ነገር ብትገልጹ ወይም ብትደብቁት በእርሱ ይመነዳችኋል:: አላህ ነገሩን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 55, '55. (የነብዩ ሚስቶች) በአባቶቻቸው፣ በወንዶች ልጆቻቸዉም፣ በወንድሞቻቸውም፣ በወንድሞቻቸው ወንዶች ልጆችም፣ በእኅቶቻቸው ወንዶች ልጆችም፣ ምዕመናት በሆኑት በሴቶቻቸዉም በጨበጧቸዉም ባሮች (አጠገብ ቢገለጡ) በእነርሱ ላይ ምንም ኃጢአት የለባቸዉም:: (ሴቶች ሆይ!) (ታዘዙ):: አላህን ፍሩ:: አላህ በነገሩ ሁሉ ላይ መስካሪ ነውና፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 56, '56. አላህና መላዕክቱ በነብዩ (ሙሐመድ) ላይ የአክብሮት እዝነትን ያወርዳሉ:: እናንተ ያመናችሁ ሆይ! በእርሱ ላይ የአክብሮት እዝነትን አውርዱ:: የማክበርን ሰላምታንም ሰላም በሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 57, '57. እነዚያ አላህንና መልክተኛውን የሚያስከፉ በቅርቢቱ ዓለምም ሆነ በመጨረሻይቱ ዓለም አላህ ረግሟቸዋል:: ለእነርሱም አዋራጅን ቅጣት ደግሶላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 58, '58. እነዚያም አማኞችና ምዕመናትን ባልሰሩት ነገር በመዝለፍ የሚያሰቃዩ ዕብለትንና ግልጽ ኃጢአትን በእርግጥ ተሸከሙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 59, '59. አንተ ነብይ ሆይ ! ለሚስቶችህ ለሴቶች ልጆችህም ለትክክለኛ አማኞች ሚስቶችም ከመከናነቢያዎቻቸው በላያቸው ላይ እንዲለቁ ንገራቸው። ይህ እንዳይታወቁና በባለጌዎች እንዳይደፈሩ ለመሆን በጣም የቀረበ ነው:: አላህ መሃሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 60, '60. አስመሳዮችና እነዚያ በልቦቻቸው ውስጥ (የአመንዝራነት) በሽታ ያለባቸው በመዲናም ውስጥ (በወሬ) አሸባሪዎቹ ከዚህ ስራቸው ባይከለከሉ በእነርሱ ላይ በእርግጥ እንቀሰቅስሃለን ከዚያ በእርሷ ውስጥ ጥቂትን እንጂ አይጎራበቱህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 61, '61. የተረገሙ ሆነው እንጂ አይጎራበቱህም:: በየትም ስፍራ ቢገኙ ይያዛሉ:: መገደልንም ይገደላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 62, '62. እነዚህ ህጎች በእነዚያ ከዚህ በፊት ባለፉት ህዝቦች ላይ የደነገጋቸው የአላህ ድንጋጌ ናቸው:: ለአላህም ድንጋጌዎች ደግሞ ፈጽሞ መለወጥን አታገኝም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 63, '63. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰዎች ከሰዓቲቱ ይጠይቁሃል:: «እውቀቷ አላህ ዘንድ ብቻ ነው።» በላቸው:: የሚያሳውቅህም ምንድን ነው! ሰዓቲቱ በቅርብ ጊዜ ልትሆን ይከጀላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 64, '64. አላህ ከሓዲያንን በእርግጥ ረግሟቸዋል። ለነርሱም የተጋገመችን እሳት አዘጋጅቷል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 65, '65. በእርሷ ውስጥ ዘለዓለም ዘውታሪዎች ሲሆኑ ወዳጅም ረዳትም አያገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 66, '66. ፊቶቻቸው በእሳት ውስጥ በሚገለባበጡ ቀን «ዋ ምኞታችን! አላህን በተገዛን መልክተኛውንም በታዘዝን ኖሮ» እያሉ ይጸጸታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 67, '67. ይላሉም «ጌታችን ሆይ! እኛ ጌቶቻችንንና ታላላቆቻችንን ታዘዝን መንገዱንም አሳሳቱን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 68, '68. «ጌታችን ሆይ! ከቅጣቱ እጥፍን ስጣቸው ታላቅን እርግማንም እርገማቸው::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 69, '69. እናንተ ያመናችሁ ሆይ! እንደ እነዚያ ሙሳን እንዳሰቃዩት ሰዎች አትሁኑ ካሉትም ነገር ሁሉ አላህ አጠራው:: አላህም ዘንድ ባለሞገስ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 70, '70. እናንተ ያመናችሁ ሆይ! አላህን ፍሩ:: ትክክለኛን ንግግርም ተናገሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 71, '71. ስራዎቻችሁን ለእናንተ ያበጅላችኋልና ኃጢአቶቻችሁንም ለእናንተ ይምርላችኋል:: አላህንና መልዕክተኛውን የሚታዘዝ ሁሉ በእርግጥ ታላቅን እድል አገኘ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 72, '72. እኛ አደራን በሰማያት በምድር እና በተራራዎች ላይ አቀረብናት:: መሸከሟንም እንቢ አሉ ከእርሷም ፈሩ። ሰው ግን ተሸከማት እርሱ በጣም በደለኛና ተሳሳች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (33, 73, '73. ወንዶች አስመሳዮችንና ሴቶች አስመሳዮችን ወንዶች አጋሪዎችንና ሴቶች አጋሪዎችንም አላህ ሊቀጣ በምዕምናንና በምዕመናትም ላይ አላህ ንስሃን ሊቀበል (አደራዋን ሰው ተሸከማት):: አላህ መሃሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 1, '1. ምስጋና ሁሉ ለዚያ በሰማያትም ያለው በምድርም ያለው ሁሉ የእርሱ ለሆነው ለአላህ ብቻ ይገባው:: በመጨረሻይቱም ዓለም ምስጋና ሁሉ ለእርሱ ብቻ ነው:: እርሱም ጥበበኛና ውስጠ አዋቂው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 2, '2. አላህ በምድር ውስጥ የሚገባውን ሁሉ ከእርሷ የሚወጣውንም ከሰማይም የሚወርደውን በእርሷ ውስጥ የሚያርገውንም ሁሉ ያውቃል:: እርሱም አዛኝና መሃሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ በአላህ የካዱትም ሰዎች «ሰዓቲቱ አትመጣብንም» አሉ፡ «ጉዳዩ እንዳሰባችሁት አይደለም። ሩቁን ሁሉ አዋቂ በሆነው ጌታዬ እምላለሁ:: በእርግጥ ትመጣባችኋለች:: የብናኝ ክብደት ያክል እንኳ በሰማያትና በምድር ውስጥ ከእሱ አይሰወርም አይርቅም:: ከዚህ ያነሰም ሆነ የበለጠ የለም በግልጹ መጽሐፍ ውስጥ የተመዘገበ ቢሆን እንጂ::» በላቸው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 4, '4. እነዚያን ያመኑትንና መልካም የሰሩትን ሊመነዳ ሰዓቲቱ ትመጣባችኋለች:: እነዚያ ለእነርሱ ምህረትና የከበረ ሲሳይ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 5, '5. እነዚያም የሚያመልጡ መስሏቸው አናቅጻችንን ለማፍረስ የጣሩ እነዚያ ለእነርሱ ከመጥፎ ቅጣት የሆነ አሳማሚ ስቃይ አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 6, '6. እነዚያም እውቀትን የተሰጡት ያንን ከጌታህ ወደ አንተ የተወረደውን እውነትና አሸናፊ ምስጉን ወደ ሆነው የአላህ መንገድ የሚመራ መሆኑን ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 7, '7. እነዚያም በአላህ የካዱት አሉ: «(ሙታችሁ) ሙሉ መበጣጠስን በተበጣጠሳችሁ ጊዜ በአዲስ መፈጠር ውስጥ ትሆናላችሁ ብሎ የሚነግራችሁን ሰው እናሳያችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 8, '8. «በአላህ ላይ ውሸትን ቀጠፈን? ወይስ በእርሱ እብደት አለበት?» አሉ:: እንዳሉት አይደለም። እነዚያ በመጨረሻይቱ ዓለም የማያምኑት በእርሷ በቅጣት ውስጥ የሚሆኑና አሁንም በራቀ ስህተት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 9, '9. ከሰማይና ከምድር በፊታቸውና በኋላቸው ወደ አለው ሁሉ አይመለከቱምን? ብንሻ እኮ በእነርሱ ምድርን እንደረምስባቸዋለን :: ወይም በእነርሱ ላይ ከሰማይ ቁራጭን እንጥልባቸዋለን:: በዚህ ውስጥ ወደ ጌታው ተመላሽ ለሆነ ባሪያ ሁሉ ታላቅ ምልክት አለበት፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 10, '10. ለዳውድም ከእኛ የሆነን ችሮታ በእርግጥ ሰጠነው:: (አልንም) ተራራዎች ሆይ! ከእሱ ጋር ውዳሴን መላልሱ:: በራሪዎችንም (ገራንለት)። ብረትንም ለእሱ አለዘብንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 11, '11. ሰፋፊዎችን ጥሩሮዎች ስራ:: በአሰራርዋም መጥን:: መልካምንም ስራ ስሩ:: እኔ የምትሰሩትን ነገር ሁሉ ተመልካች ነኝና (አልነው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 12, '12. ለሱለይማንም ንፋስን የቀትር በፊት ጉዞዋ የወር መንገድ፤ የቀትር በኋላ ጉዞዋም የወር መንገድ ሲሆን ገራንለት:: የነሀስንም ምንጭ ለእርሱ አፈሰስንለት:: ከአጋንንቶችም በጌታው ፈቃድ በፊቱ የሚሰሩትን (አደረግንለት):: ከእነርሱም ውስጥ ከትእዛዛችን ዝንፍ የሚል ከነዳጅ እሳት ቅጣት እናቀምሰዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 13, '13. ከምኩራቦች፤ ከምስሎችም እንደ ገንዳ ከሆነ ገበታዎችም፤ ከተደላደለ ታላላቅ ድስቶችም የሚሻውን ሁሉ ይሰሩለታል፣ (አልናቸዉም:) «የዳውድ ቤተሰቦች ሆይ! በጣም አመስጋኞች ሆናችሁ ለጌታችሁ ስሩ::» ከባሮቼ ውስጥ አመስጋኞቹ ጥቂቶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 14, '14. በእርሱም ላይ ሞትን በፈጸምንበት ጊዜ መሞቱን ብትሩን የምትበላ ተንቀሳቃሽ ምስጥ እንጂ ሌላ አላመለከታቸዉም:: በወደቀ ጊዜም አጋንንቶች ሩቅን ሚስጥር የሚያውቁ በሆነ ኖሮ በአዋራጅ ስቃይ ውስጥ የማይቆዩ እንደነበሩ ተረዱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 15, '15. ለሰበእ ነገዶች በመኖሪያቸው በእውነት አስደናቂ ምልክት ነበራቸው:: ከግራና ከቀኝ ሁለት አትክልቶች ነበሯቸው:: «ከጌታችሁ ሲሳይ ብሉ ለእሱም አመስግኑ:: አገራችሁ ውብ አገር ናት:: ጌታችሁም መሃሪ ጌታ ነው» ተባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 16, '16. አላህን ከማመስገን ዞሩም:: በእነርሱም ላይ የግድቡን ጎርፍ ለቀቅንባቸው:: በሁለቱ አትክልቶቻቸዉም ሌሎች ሁለትን አትክልቶች ባለ መርጋጋ ፍሬዎችን ባለ ጠደቻና ከቁርቁራም ባለ ጥቂት ዛፎችን ለወጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 17, '17. በመካዳቸው ምክንያት ይህንን መነዳናቸው:: (እንደዚህ ያለውን ቅጣት) በጣም ከሓዲ ለሆነ ሰው ብቻ እንጂ ለሌላው እንሰጣለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 18, '18. በእነርሱና በዚያች በውስጧ በረከትን ባደረግንባት አገር (በሻም) መካከልም ተከታታይ መንደሮችን (ቅጥልጥል ከተሞች) አደረግን:: በእርሷም ጉዞን ወሰንን። «በሌሊቶችም ሆነ በቀኖች ዉስጥ ጸጥተኞች ሆናችሁ ተጓዙ» (አልን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 19, '19. «ጌታችን ሆይ! በጉዞዎቻችን መካከል አራርቅልን» አሉም:: ነፍሶቻቸውንም በደሉ:: መገረሚያ ወሬዎችም አደረግናቸው:: መበታተንንም ሁሉ በታተንናቸው:: በዚህ ውስጥ በጣም ታጋሽና አመስጋኝ ለሆነ ሁሉ ብዙ መገለጫዎች አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 20, '20. ዲያብሎስም በእነርሱ ላይ ምኞቱን በእርግጥ ፈጸመ:: እናም ከአመኑት የሆኑት ቡድኖች በስተቀር ተከተሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 21, '21. በመጨረሻይቱም ዓለም የሚያምነውን ከዚያ እርሱ ከእርሷ በመጠራጠር ውስጥ ከሆነው ሰው ለይተን እንድናውቅ እንጂ በእነርሱ ላይ ለእርሱ ምንም ስልጣን አልነበረዉም:: ጌታህም በነገሩ ሁሉ ላይ ተጠባባቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 22, '22. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያን ከአላህ ሌላ አማልክት ብላችሁ የምታስቧቸውን ጥሩ:: በሰማያትም ሆነ በምድር ውስጥ የብናኝ ክብደት ያህል እንኳ ምንም አይችሉም:: ለእነርሱም በሁለቱም ውስጥ ምንም ሽርክና የላቸዉም:: ከእነርሱም ለእርሱ ምንም አጋዥ የለዉም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 23, '23. ምልጃም እርሱ ለፈቀደለት ሰው ብቻ ቢሆን እንጂ እሱ ዘንድ ምንም አትጠቅምም:: ከልቦቻቸው ላይ ድንጋጤው በተገለጠ ጊዜ ተማላጆቹ «ጌታችሁ ምን አለ?» ይላሉ:: አማላጆቹም: «እውነትን አለ። እርሱም ከፍተኛውና ታላቁ ጌታ ነው።» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ)፤ «ከሰማያትና ከምድር ሲሳይን የሚሰጣችሁ ማነው?» በላቸው። «አላህ ነው እኛ ወይም እናንተ በትክክለኛው መንገድ ላይ ወይም በግልጽ መሳሳት ውስጥ ነን።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ !)«ካጠፋነው ጥፋት አትጠየቁም:: ከምትሰሩትም ስራ አንጠየቅም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 26, '26.(መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታችን በመካከላችን ይሰበስባል። ከዚያም በመካከላችን በእውነት ይፈርዳል:: እርሱም በትክክል ፈራጁና አዋቂው ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 27, '27.(መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያን ተጋሪዎች አድርጋችሁ በእሱ ያስጠጋችኋቸውን ጣዖታት እስቲ አሳዩኝ:: ተው አታጋሩ:: በእውነት እርሱ አሸናፊዉና ጥበበኛው አላህ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 28, '28. አንተንም ለሰዎች ሁሉ በመላ አብሳሪና አስፈራሪ አድርገን ቢሆን እንጂ አልላክንህም:: ግን አብዛኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 29, '29. «እውነተኞችም እንደ ሆናችሁ ይህ ቀጠሮ መቼ ነው?» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) «ለእናንተ ከእርሱ አንዳችንም ሰዓት የማትዘገዩበት የማትቀድሙበትም የቀጠሮ ቀን አላችሁ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 31, '31. እነዚያም የካዱት «በዚህ ቁርኣንና በዚያ ከበፊቱ ባለዉም መጽሐፍ በጭራሽ አናምንም።» አሉ:: በዳዮችም ከፊላቸው ወደ ከፊሉ ንግግርን የሚመላላሱ ሆነው በጌታቸው ዘንድ በሚቆሙ ጊዜ ብታይ ኖሮ አስደናቂን ነገር ታይ ነበር:: እነዚያ የተዋረዱት ለእነዚያ ለኮሩት «እናንተ ባልነበራችሁ ኖሮ ትክክለኛ አማኞች በሆንን ነበር።» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 32, '32. እነዚያ የኮሩት ለእነዚያ ለተዋረዱት «ትክክለኛው እምነት ከመጣላችሁ በኋላ እኛ ከለከልናችሁን? አይደለም:: እናንተው ከሓዲያን ነበራችሁ።» ይሏቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 33, '33. እነዚያም የተዋረዱት ለእነዚያ ለኮሩት «አይደለም። በአላህ እንድንክድና ለእርሱ ባላንጣዎችን እንድናደርግ ስታዙን (የከለከለን) የሌሊትና የቀን ዱለታችሁ ነው።» ይላሉ:: ቅጣትንም ባዩ ጊዜ ጸጸትን ይደብቃሉ:: በእነዚያም በካዱት አንገቶች ላይ እንዛዝሎችን እናደርጋለን:: ይሰሩት የነበሩትን እንጂ ሌላን ይመነዳሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 34, '34. በየትኛዋም ከተማ አስፈራሪን አላክንም ነዋሪዎችዋ «እኛ በተላካችሁት ከሓዲያን ነን።» ያሉ ቢሆኑ እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 35, '35. «እኛም በገንዘቦችና በልጆች ይበልጥ የበዛን ነን:: እኛም የምንቀጣ አይደለንም» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 36, '36. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታዬ ሲሳይን ለሚሻው ሰው ሁሉ ያሰፋል:: ለሚሻው ሰዉም ሁሉ ያጠባል:: ግን አብዛኛዎቹ ሰዎች ይህን አያውቁም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 37, '37. ገንዘቦቻችሁና ልጆቻችሁም ያች እኛ ዘንድ መቅረብን የምታቀርባችሁ አይደለችም:: ያ በትክክል ያመነና መልካምን የሰራ ብቻ ሲቀር:: እነዚያ ለእነርሱ በሰሩት መልካም ስራ እጥፍ ምንዳ አለላቸው:: እነርሱም በገነት ሰገነቶች ውስጥ ጸጥተኞች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 38, '38. እነዚያም የሚያቅቱ መስሏቸው አናቅጻችንን ለማበላሸት የሚጥሩ ሁሉ እነዚያ በቅጣት ውስጥ የሚጣዱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 39, '39. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታዬ ሲሳይን ከባሮቹ ለሚሻው ሰው ያሰፋል:: ለእርሱም ያጠባል:: ከማንኛዉም ነገር የምትለግሱትን እርሱ ይተካዋል:: እርሱም ከሲሳይ ሰጪዎች ሁሉ በላጭ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) ሁሉንም በሚሰበስባቸውና ከዚያም ለመላእክቶቹ «እነዚህ እናንተን ይገዙ ነበሩን?» በሚላቸው ቀን የሚሆነውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 41, '41. መላእክቶቹም «ጥራት ይገባህ ረዳታችን ከእነርሱ ሌላ የሆንከው አንተው ብቻ ነህ:: እንደሚሉት አይደለም:: ይልቁንም አጋንንትን ይገዙ ነበሩ:: አብዛኞቻቸው በእነርሱ አማኞች ናቸው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 42, '42. ዛሬም ከፊላችሁ ለከፊሉ መጥቀምንም ሆነ መጉዳትን አይችሉም:: ለእነዚያም ለበደሉት ሰዎች «ያችን በእርሷ ታስተባብሉባት የነበራችሁትን የእሳት ቅጣት ቅመሱ» እንላቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 43, '43. በእነርሱም ላይ አናቅጻችን ግልጽ ሆነው በተነበቡላቸው ጊዜ «ይህ አባቶቻችሁ ይገዙት ከነበሩት ነገር ሊከለክላችሁ የሚፈልግ ሰው እንጂ ሌላ አይደለም።» አሉ:: «ይህም ቁርዓን የተቀጣጠፈ ውሸት ነው እንጂ ሌላ አይደለም።» አሉም። እነዚያም በአላህ የካዱት እውነትን በመጣላቸው ጊዜ «ግልጥ ድግምት ነው እንጂ ሌላ አይደለም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 44, '44. የሚያጠኗቸው የሆኑ መጽሐፎችንም ምንም አልሰጠናቸዉም:: ካንተ በፊትም አስፈራሪ ነብይን ወደ እነርሱ አልላክንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 45, '45. እነዚያም ከእነርሱ በፊት የነበሩት አስተባብለዋል:: የሰጠናቸውንም ከአስር አንዱን እንኳን እነዚህ አልደረሱም:: እናም መልዕክተኞቼን አስተባበሉ:: ነቀፍኳቸዉም:: መንቀፌም እንዴት ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) «የምገስጻችሁ በአንዲት ነገር ብቻ ነው:: እርሷም ሁለት ሁለት፤ አንድ አንድም ሆናችሁ ለአላህ እንድትነሱና ከዚያም በጓደኛችሁ (በሙሐመድ) ምንም እብደት የሌለበት መሆኑን መርምራችሁ እንድትረዱ ነው:: እርሱ ለእናንተ ከብርቱ ቅጣት በስተፊት አስጠንቃቂ ነው እንጂ ሌላ አይደለም።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 47, '47. (መልዕክተኛችን ሙሐመድ ሆይ!) «ከዋጋ ማንኛውንም የጠየቅኋችሁ ቢኖር እርሱ ለእናንተው ነው:: ዋጋዬ በአላህ ላይ እንጂ በሌላ ላይ አይደለም:: እርሱም በነገሩ ሁሉ ላይ አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታዬ እውነትን ብቻ ያወርዳል:: ሩቅ የሆኑትን ምስጢሮች ሁሉ አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) «እውነቱ መጣ ውሸት መነሻም መድረሻም የለዉምና ተወገደ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 50, '50. (መልዕክተኛችን ሙሐመድ ሆይ!) «ብሳሳትም የምሳሳተው በራሴ ላይ ብቻ ነው:: ብመራም ጌታዬ ወደ እኔ በሚያወርደው መመሪያ መሰረት ነው:: እርሱ ሁሉ ሰሚና ለሁሉም ቅርብ ነውና።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) በደነገጡና ማምለጫ በሌላቸው ጊዜ ከቅርብ ስፍራም በተያዙ ጊዜ ሁኔታቸውን ብታይ ኖሮ (አስደናቂን ነገር ባየህ ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 52, '52. «በእርሱም አሁን አመንን።» ይላሉ:: ለእነርሱም ከሩቅ ስፍራ እምነትን በቀላሉ ማግኘት ከየታቸው ይታደሉና?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 53, '53. በፊትም በእርሱ በእርግጥ ክደዋል:: ከሩቅ ስፍራም በግምት ንግግርን ይጥላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (34, 54, '54. ከዚህ ቀደም በመሰሎቻቸው እንደተሰራዉም ብጤ በእነርሱና በሚፈልጉት መካከል ተጋረደ:: እነርሱ በእርግጥ በአወላዋይ ጥርጣሬ ውስጥ ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 1, '1. ምስጋና ሁሉ ሰማያትንና ምድርን ፈጣሪ፤ መላእክትንም ባለ ሁለት ሁለት፤ ባለ ሶስት ሶስትና ባለ አራት አራት ክንፎች የሆኑ መላዕክተኞች አድራጊ ለሆነው አላህ ይገባው:: በፍጥረቱ ውስጥ የሚሻውን ይጨምራል:: አላህ በሁሉ ነገር ላይ ቻይ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 2, '2. አላህ ለሰዎች ከችሮታ የሚከፍታትን ለእርሷ ምንም አጋጅ የላትም:: የሚያግደዉም ከእርሱ በኋላ ለእርሱ ምንም ለቃቂ የለዉም:: እርሱ ብቸኛ አሸናፊና ጥበበኛ ው ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 3, '3. እናንተ ሰዎች ሆይ! በእናንተ ላይ (ያለውን) የአላህን ጸጋ አስታውሱ፡፡ ከአላህ ሌላ ፈጣሪ አለን? ከሰማይና ከምድርም ሲሳይን የሚሰጣችሁ አለን? ከእርሱ በስተቀር አምላክ (ሰጪም) የለም፡፡ ታዲያ ወዴት ትዞራላችሁ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 4, '4. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢያስተባብሉህም ካንተ በፊት የነበሩ ነብያትም ህዝቦቻቸው አስተባብለዋቸዋል:: የሁሉ ነገር መመለሻ ወደ አላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 5, '5. (እናንተ ሰዎች ሆይ!) የአላህ ቀጠሮ እውነት ነው:: እናም የቅርቢቱም ህይወት አታታላችሁ:: አታላዩም (ሰይጣን) በአላህ ላይ አያታላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 6, '6. ሰይጣን ለእናንተ የለየለት ጠላት ነውና ስለዚህ እሱን ጠላት አድርጋችሁ ያዙት:: ሰይጣን ተከታዮቹን የሚጠራው ከእሳት ጓዶች እንዲሆኑ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 7, '7. እነዚያ በአላህ የካዱት ለእነርሱ ብርቱ ቅጣት አለባቸው:: እነዚያም በአላህ ያመኑትና በጎ ስራዎችንም የሰሩት ሁሉ ለእነርሱ በአላህ ዘንድ ምህረትና ታላቅ ምንዳ አለላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 8, '8. መጥፎ ሥራው የተሸለመለትና መልካም አድርጎ ያየው ሰው (አላህ እንዳቀናው ሰው ነውን?) አላህም የሚሻውን ሰው ያጠምማል፡፡ የሚሻውንም ያቀናል፡፡ ስለዚህ በእነርሱ ላይ (ባለመቅናታቸው) ስለመቆላጨት ነፍስህ አትጥፋ፡፡ አላህ የሚሠሩትን ሁሉ ዐዋቂ ነውና፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 9, '9. አላህም ያ ንፋሶችን የላከ ነው:: ከዚያም ዳመናዎችን ትቀሰቅሳለች። ወደ ሙት (ድርቅ) አገርም እንነዳዋለን:: በእርሱም ምድርን ከሞተች በኋላ ህያው እናደርጋታለን:: ሙታንንም መቀስቀስ ልክ እነደዚሁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 10, '10. ማሸነፍን የሚፈልግ ሰው አሸናፊነት ለአላህ ብቻ ነው። (እርሱን በመገዛት ይፈልገው):: መልካም ንግግር ወደ እርሱ (ወደ አላህ) ይወጣል:: በጎ ስራም ከፍ ያደርገዋል:: እነዚያ መጥፎ ስራዎችን የሚዶልቱ ለእነርሱ ብርቱ ቅጣት አለባቸው :: የእነዚያም ተንኮል እርሱ ይጠፋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 11, '11. አላህም ከአፈር ከዚያም ከፍትወት ጠብታ ፈጠራችሁ:: ከዚያም ዓይነቶች አደረጋችሁ:: የትኛዋም ሴት አታረግዝም አትወልድምም በእውቀቱ ቢሆን አንጂ:: እድሜው ከሚረዝምለትም አንድም አይረዘምለትም ከእድሜዉም አይጎድልበትም በመጽሀፉ ውስጥ ያለ ቢሆን እንጂ:: ይህ በአላህ ላይ ገር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 12, '12. ሁለቱ ባህሮች አይስተካከሉም ይህ ጣፋጭ፤ ጥምን ቆራጭ መጠጡ በገር ተዋጭ ነው:: ይህኛው ደግሞ ጨው መርጋጋ ነው:: ከሁሉም እርጥብ ስጋን ትበላላችሁ:: የምትለብሷትንም ጌጥ ታወጣላችሁ። ከችሮታው ልትፈልጉና ልታመሰግኑትም መርከቦችን በእርሱ ውስጥ ውሃውን ቀዳጆች ሆነው ሲንሻለሉ ታያለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 13, '13. ሌሊትን በቀን ውስጥ ያስገባል:: ቀንንም በሌሊት ውስጥ ያስገባል:: ጸሀይንና ጨረቃንም ገራ:: ሁሉም እስከ ተወሰነለት ጊዜ ድረስ ይሮጣል :: ይህን የሚያደርገው ጌታችሁ አላህ ብቻ ነው :: ንግስናው የእሱ ብቻ ነው:: እነዚያም ከእርሱ ሌላ የምትገዟቸው የተምር ፍሬ ሽፋን ያህል እንኳን አይኖራቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 14, '14. ብትጠሩዋቸው ጥሪያችሁን አይሰሙም:: ቢሰሙም ኖሮ ለእናንተ አይመልሱላችሁም:: በትንሳኤም ቀን እነርሱን በአላህ ማጋራታችሁን ይክዳሉ። እንደ ውስጠ አዋቂው አላህ ማንም አይነግርህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 15, '15. እናንተ ሰዎች ሆይ! እናንተ ሁል ጊዜ ወደ አላህ ከጃዮች ናችሁ:: አላህም እርሱ ተብቃቂውና ምስጉኑ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 16, '16. (አላህ) ቢሻ ያስወግዳችሁና አዲስን ፍጡር ያመጣል (ይፈጥራል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 17, '17. ይህም በአላህ ላይ ምንም አስቸጋሪ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 18, '18. ኃጢአትን ተሸካሚም ነፍስ የሌላውን ሸክም አትሸከምም:: የራሷ ወንጀል የከበዳትም ነፍስ እርዳታ እንዲደረግላት ብትጠራ ተጠሪው የቅርብ ዝምድና ባለቤት ቢሆንም እንኳን ከእርሷ አንድን ነገር የሚሸከምላት አታገኝም:: (መልዕክተኛችን ሙሐመድ ሆይ!) የምታስጠነቅቀው እነዚያን ጌታቸውን፤ በሩቅ የሚፈሩትን ሶላትንም አስተካክለው የሚሰገዱትን ብቻ ነው:: ከወንጀልም የተጥራራ ሁሉ የሚጥራራው ለራሱ ብቻ ነው:: መመለሻዉም ወደ አላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 19, '19. እውርና የሚያይ አይሰተካከሉም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 20, '20. ጨለማዎችና ብርሃንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 21, '21. ጥላና ሐሩርም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 22, '22. ህያውና ሙታንም አይስተካከሉም:: አላህ የሚሻውን ሰው ያሰማል:: (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ ግን በመቃብር ውስጥ ያሉትን አሰሚ አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 23, '23. አንተ አስጠንቃቂ እንጂ ሌላ አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 24, '24. እኛ አብሳሪና አስፈራሪ አድርገን በእውነቱ መምሪያ ላክንህ:: ማንኛይቱም ህዝብ በውስጧ አስፈራሪ ያላለፈባት የለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢያስተባብሉህም ከእነዚህ ከበፊታቸው የነበሩትም ህዝቦች በእርግጥ ነብያትን አስተባብለዋል:: መልዕክተኞቻቸው በግልጽ ማስረጃዎች፣ በጹሁፎችም አብራሪ በሆነ መጽሐፍም መጥተዋቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 26, '26. ከዚያም እነዚያን የካዱትን ቀጣኋቸው:: ቅጣቴም እንዴት ነበር! (በስፍራው ነው ተገቢ ነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 27, '27. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ከሰማይ ውሃን ማውረዱን አላየህምን? በእርሱም ዓይነቶቻቸው የተለያዩ ፍሬዎችን አወጣን:: ከጋራዎችም መልካቸው የተለያዩ ነጮችም፤ ቀዮችም፤ በጣም ጥቁሮችም የሆኑ መንገዶች አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 28, '28. ከሰዎችም፤ ከተንቀሳቃሾችም፤ ከቤት እንስሳዎችም እንደዚሁ መልኮቻቸው የተለያዩ አሉ:: አላህን ከባሮቹ ውስጥ የሚፈሩት አዋቂዎቹ ብቻ ናቸው:: አላህ አሸናፊና መሃሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 29, '29. እነዚያ የአላህን መጽሐፍ የሚያነቡ፣ ሶላትን አስተካክለው የሰገዱ፤ ከሰጠናቸዉም ሲሳይ በምስጢርም ሆነ በግልጽ የለገሱ የማትከስርን ንግድ ተስፋ ያደርጋሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 30, '30. ምንዳዎቻቸውን ሊሞላላቸው ከችሮታዉም ሊጨምርላቸው ተስፋ ያደርጋሉ:: እርሱ በጣም መሃሪና አመስጋኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 31, '31. (መልዕክተኛችን ሙሐመድ ሆይ!) ያ ከመጽሐፉ ወደ አንተ ያወረድነው ከበፊቱ ላለው አረጋጋጭ ሲሆን እርሱ እውነት ነው:: አላህ በእርግጥ በባሮቹ ውስጥ አዋቂና ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 32, '32. ከዚያ እነዚያ ከባሮቻችን የመረጥናቸውን መጽሐፉን አወረስናቸው :: ከእነርሱም ነፍሱን በዳይ አለ:: ከእነርሱም መካከለኛ አለ:: ከእነርሱም በአላህ ፈቃድ በበጎ ስራዎች ቀዳሚ አለ:: ያንኑ ማውረስ እርሱ ታላቅ ችሮታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 33, '33. የመኖሪያ ገነቶችን በውስጧ የወርቅ አንባሮችን ሉልንም የሚሸለሙ ሆነው ይገቡበታል:: በእርሷ ውስጥ አልባሳታቸዉም ሀር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 34, '34. ይላሉም «ምስጋና ሁሉ ለዚያ ከእኛ ላይ ሐዘንን ላስወገደልን ይገባው። ጌታችን በጣም መሃሪና አመስጋኝ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 35, '35. እርሱም ያ ከችሮታው የዘላለም መኖሪያን አገር ያሰፈረን ነው:: በእርሷም ውስጥ መከራ አይነካንም:: በእርሷም ውስጥ ድካም አይነካንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 36, '36. እነዚያ በአላህ የካዱት ለእነርሱ የገሀነም እሳት አለላቸው:: ይሞቱ ዘንድም በእነርሱ ላይ ሞት አይፈረድም:: ከቅጣቷም ከእነርሱ አይቀለልላቸዉም:: ልክ እንደዚሁ ከሓዲያንን ሁሉ እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 37, '37. እነርሱም በእርሷ ውስጥ እርዳታን በመፈለግ በኃይል ይጮሃሉ:: «ጌታችን ሆይ! ከእዚያ እንሠራው ከነበርነው ሌላ በጎ ሥራን እንሠራ ዘንድ አውጣን» (ይላሉ)፡፡ «በእርሱ ውስጥ ያስታወሰ ሰው የሚገሰጽበትን እድሜ አላቆየናችሁምን? አስጠንቃቂዉም መጥቶላችኋል:: አስተባብላችኋልም:: ስለዚህ ቅመሱ:: ለበደለኞችም ምንም ረዳት የላቸዉም» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 38, '38. አላህ የሰማያትንና የምድርን ምስጢር በእርግጥ አዋቂ ነው:: እርሱ በልቦች ውስጥ ያለን ሁሉ እንኳ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 39, '39. (ሰዎች ሆይ!) እርሱ ያ በምድር ውስጥ ምትኮች ያደረጋችሁ ነው:: የካደም ክህደቱ በእርሱው ላይ ብቻ ነው:: ከሓዲያንም ክህደታቸው ከጌታቸው ዘንድ መጠላትን እንጂ ሌላ አይጨምርላቸዉም:: ከሓዲያንም ክህደታቸው ክስረትን እንጂ ሌላ አይጨምርላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) «እነዚያን ከአላህ ሌላ የምትገዟቸውን ተጋሪዎቻችሁ አያችሁን? ከምድር ምንን እንደ ፈጠሩ አሳዩኝ? ወይስ ለእነርሱ በሰማያት ውስጥ ሽርክና አላቸውን? ወይስ ለእነርሱ መፅሀፍ ሰጠናቸውና ከእርሱ በግልፅ አስረጂ ላይ ናቸውን? አይደለም በደለኞች ከፊላቸው ከፊሉን ማታለልን እንጂ አይቀጥሩም» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 41, '41. አላህ ሰማያትንና ምድርን እንዳይወገዱ ይይዛቸዋል:: ቢወገዱም ከእርሱ ሌላ አንድም የሚይዛቸው የለም:: እነሆ እርሱ ታጋሽና መሃሪ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 42, '42. አስፈራሪም ቢመጣላቸው ከህዝቦች ሁሉ ከአንደኛዋ ይበልጥ የተመሩ ሊሆኑ የመሃላቸውን ዲካ አድርሰው በአላህ ማሉ:: አስፈራሪም በመጣላቸው ጊዜ መበርገግን እንጂ ሌላ አልጨመረላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 43, '43. በምድር ላይ ኩራትንና በክፉ ተንኮል መዶለትንም እንጂ አልጨመረላቸዉም:: ክፉ ተንኮልም በባለቤቱ ላይ እንጂ በሌላ ላይ አይሰፍርም:: የቀድሞዎቹን ደንብ እንጂ ይጠብቃሉን? በመሆኑም ለአላህ ደንብ መለወጥን አታገኝም፤ ለአላህ ደንብም መዛወርን (መቀየር) አታገኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 44, '44. በምድር ላይ አይሄዱምና የእነዚያን ከእነርሱ በፊት የነበሩትን ሰዎች መጨረሻ እንዴት እንደ ነበረ አይመለከቱምን? ከእነርሱም በኃይል የበረቱ ነበሩ:: አላህም በሰማያትም ሆነ በምድር ውስጥ ምንም ነገር የሚያቅተው አይደለም:: እርሱ ሁሉን አዋቂና በሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (35, 45, '45. አላህ ሰዎችን በሰሩት ኃጢአት ሁሉ ቢቀጣ ኖሮ በምድር ወለል ላይ ምንንም ተንቀሳቃሽ ባልተወ ነበር:: ግን እስከ ተወሰነ ጊዜ ድረስ ያቆያቸዋል:: ጊዜያቸዉም በመጣ ወቅት በኃጢአታቸው ይቀጣቸዋል:: አላህ በባሮቹ ሁኔታ ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 1, '1. ያሲን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 2, '2-ጥበብ በተሞላበት ቁርኣን እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 3, '3.(መልዕክተኛችን ሙሐመድ ሆይ!) ከመልዕክተኞቹ መካከል አንዱ ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 4, '4. አንተ በእርግጥ በቀጥታው መንገድ ላይ ነህ ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 5, '5.ቁርኣን አሸናፊውና አዛኙ ከሆነው አምላክ ከአላህ ተወረደ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) አባቶቻቸው ያልተስፈራሩትን ህዝቦች ልታስጠነቅቅበት ቁርኣን ተወረደ። እነርሱ ዘንጊዎች ናቸውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 7, '7. በአብዛኞቻቸቸው ላይ ቃሉ በእውነት ተረጋገጠ:: ስለዚህ እነርሱ አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 8, '8. እኛ በአንገቶቻቸው ላይ እንዛዝላዎችን አደረግን። (እንዛዝላይቱም) ወደ አገጮቻቸው ደራሽ ናት። እናም ከዚያም እነርሱ ራሶቻቸውን ያንጋጠጡ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 9, '9. ከበስተፊታቸዉም ግርዶን ከበስተኋላቸዉም ግርዶን አደረግንና ሸፈንናቸው:: ስለዚህ እነርሱ አያዩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 10, '10. ብታስጠነቅቃቸዉም ባታስጠነቅቃቸዉም ለእነርሱ ሁሉም እኩል ነው:: (ምንም ለውጥ አያመጣም) አያምኑምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ!) የምታስጠነቅቀው ግሳጼን የተከተለንና አር-ረህማንን በሩቅ የፈራን ሰው ብቻ ነው:: እናም በምህረትና በመልካም ምንዳ አብስረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 12, '12. እኛ ሙታንን በእርግጥ ህያው እናደርጋለን:: ያስቀደሙትንም ስራ ፈለጎቻቸውንም እንጽፋለን:: ሁሉን ነገርም ገላጭና መሪ በሆነ መጽሐፍ ውስጥ አጠቃለልነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነርሱም የከተማይቱን (የአንጾኪያን) ሰዎች ምሳሌ መልዕክተኞች በመጧት ጊዜ የሆነውን ግለጽላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 14, '14. ወደ እነርሱ ሁለትን ሰዎች በላክንና ባስተባበሉዋቸውም ጊዜ፤ በሶስተኛም ባበረታናቸውና «እኛ ወደ እናንተ መልክተኞች ነን» ባሏቸው ጊዜ የሆነውን ምሳሌ ግለጽላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 15, '15. «እናንተ መሰላችን ሰዎች እንጂ ሌላ አይደላችሁም:: አር-ረህማንም ምንንም ነገር አላወረደም:: እናንተ የምትዋሹ እንጂ ሌላ አይደላችሁም» አሏቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 16, '16. መልዕክተኞቹም አሉ: «ጌታችን ያውቃል። እኛ ወደ እናንተ በእርግጥ መልክተኞች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 17, '17. «በእኛ ላይም ግልጽ የሆነ ማድረስ እንጂ ሌላ የለብንም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 18, '18. ህዝቦቹም «እኛ በእናንተ ገደ ቢሶች ሆንን። ከዚህ ጥሪያችሁ ባትከለክሉም በእርግጥ እንወግራችኋለን:: ከእኛም አሳማሚ ቅጣት በእርግጥ ያገኛችኋል» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 19, '19. «ገደ ቢስነታችሁ ከናንተው ጋር ነው:: ብትገሰጹ (ትዝታላችሁን?) በእውነቱ እናንተ ወሰን አላፊ ህዝቦች ናችሁ» አሏቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 20, '20. ከከተማይቱም ሩቅ ዳርቻ የሚሮጥ ሰው መጣና (እንዲህ) አለ: «ወገኖቼ ሆይ! መልዕክተኞቹን ተከተሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 21, '21. «እነርሱም ቅኑን መንገድ የተመሩ ሲሆኑ ክፍያን የማይጠይቋችሁን ሰዎች ተከተሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 22, '22. «ያንንም የፈጠረኝንና ወደ እርሱም የምትመለሱበትን ጌታ የማልገዛበት ምን ምክንያት አለኝ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 23, '23. «ከእርሱ ሌላ አማልክትን እይዛለሁን? አልራህማን ሊጎዳኝ ቢፈልግ ምልጃቸው ከእኔ (ለመመለስ) ምንም አትጠቅመኝም አያድኑኝምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 24, '24. «እኔ ያን ጊዜ በግልጽ ስህተት ውስጥ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 25, '25. «እኔ በጌታችሁ አመንኩ። ስሙኝም።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 26, '26. {1} «ገነትን ግባ» ተባለም። እርሱም አለ: «ወገኖቼ ቢያውቁ እመኛለሁ።', '{1} ደብድበው ገደሉት ከሞተ በኋላ ጀነት ግባ ተባለ');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 27, '27. «ጌታዬ ለእኔ ምህረት ያደረገልኝና ከተከበሩትም ያደረገኝ መሆኑን።» (ቢያውቁ ተመኘሁ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 28, '28. ከእርሱም በኋላ በህዝቦቹ ላይ ልናጠፋቸው ሰራዊትን ከሰማይ አላወረድንም (በማንም) ላይ አውራጆችም አልነበርንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 29, '29. ቅጣታቸው አንዲት ጩኸት እንጂ ሌላ አልነበረችም:: ወዲያውኑም እነርሱ ጠፊዎች ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 30, '30. በባሮች ላይ ዋ ቁጭት! ከመልዕክተኛ አንድም አልመጣላቸዉም በእርሱ ያፌዙበት ቢሆን እንጂ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 31, '31. ከእነርሱ በፊት ከክፍለ ዘመናት ህዝቦች ብዙዎችን ማጥፋታችንንና እነርሱ የማይመለሱ መሆናቸውን አላወቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 32, '32. ሁሉም እኛ ዘንድ (የሚሰበሰቡ) የሚቀረቡ እንጂ ሌላ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 33, '33. የሞተችዉም ምድር ለእነርሱ ምልክት ናት:: ህያው አደረግናት:: ከእርሷ ፍሬን አወጣን፤ ከእሱም ይበላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 34, '34. በእርሷ ውስጥ ከዘምባባዎችና ከወይኖች የሆነ አትክልቶችን አደረግን:: በእርሷም ውስጥ ምንጮችን አፈለቅን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 35, '35. ከፍሬዉና እጆቻቸው ከሰሩትም ይበሉ ዘንድ ይህን አደረግን:: አያመሰግኑምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 36, '36. ያ! ምድር ከምታበቅለው፤ ወንዴንና ሴቴን ከነፍሶቻቸዉም ከማያውቁትም ነገር (ዓይነቶችን) ሁሏንም የፈጠረ (አምላክ) ጥራት ይገባው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 37, '37. ሌሊቱም ለእነርሱ ምልክት ነው:: ከእርሱ ላይ ቀንን አንገፋለን:: ወዲያውኑም እነርሱ በጨለማ ውስጥ ይገባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 38, '38. ጸሐይም ለእርሷ ወደ ሆነው መርጊያ ትሮጣለች:: ይህ የአሸናፊውና የአዋቂው አምላክ የአላህ ውሳኔ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 39, '39. ጨረቃንም የመስፈሪያዎች ባለቤት ሲሆን እንደ አሮጌ ዘንባባ ቀንዘል እስኪሆን ድረስ መሄዱን ለካነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 40, '40. ጸሐይ ጨረቃን ልትደርስበት አይገባትም:: ሌሊትም ቀንን ያለ ጊዜው ቀዳሚ አይሆንም:: ሁሉም በየመዞሪያቸው (በፈለክ) ውስጥ ይዋኛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 41, '41. እኛም የቀድሞ ትውልዳቸውን (አባቶቻቸውን) በተሞላች መርከብ ውስጥ የጫን መሆናችን ለእነርሱ ምልክት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 42, '42. ከመሰሉም በእርሱ የሚሳፈሩበትን ለእነርሱ ፈጠርንላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 43, '43. ስንፈልግ እናሰምጣቸዋለን:: ለእነርሱም ነፃ የሚያደርጋቸው ረዳት የላቸዉም:: እንዲድኑ የሚደረጉም አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 44, '44. እኛ ግን በችሮታችንና እስከ ጊዜ ሞታቸው ለማጣቀም አዳንናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 45, '45. ለእነርሱም «በስተፊታችሁና በኋላችሁ ያለውን ነገር ተጠንቀቁ፤ ይታዘንላችኋልና» በተባለ ጊዜ ፊታቸውን ያዞራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 46, '46. ከጌታቸውም ተዓምራት አንዲትም ተዓምር አትመጣላቸዉም ከእርሷ የሚሸሹ ቢሆኑ እንጅ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 47, '47. ለእነርሱም «አላህ ከሰጣችሁ ሲሳይ ለግሱ» በተባሉ ጊዜ እነዚያ በአላህ የካዱት ለእነዚያ በአላህ ላመኑት «አላህ ቢሻ ኖሮ የሚያበላውን እናበላለን? እናንተ በግልጽ ስህተት ውስጥ እንጂ በሌላ ላይ አይደላችሁም።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 48, '48. «እውነተኞችም እንደ ሆናችሁ ይህ ቀጠሮ መቼ ነው?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 49, '49. እነርሱ የሚከራከሩ ሲሆኑ በድንገት የምትይዛቸው የሆነችን አንዲትን ጩኸት እንጂ ሌላን አይጠባበቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 50, '50. ያን ጊዜ መናዘዝን እንኳን አይችሉም:: ወደ ቤተሰቦቻቸዉም አይመለሱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 51, '51. በቀንዱም ይነፋል:: ወዲያውኑም እነርሱ ከየመቃብሮቻቸው ወደ ጌታቸው በፍጥነት ይገሰግሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 52, '52. «ወይ ጥፋታችን! ከመኝታችን ማን ቀሰቀሰን? ይህ ያ አዛኙ ጌታ በእርሱ የቀጠረን መልዕክተኞቹም እውነቱን የነገሩን ነው።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 53, '53. እርሷ አንዲት ጩኸት እንጂ ሌላ አይደለችም:: ወዲያውኑም እነርሱ እኛ ዘንድ የሚሰበሰቡ የሚቀርቡ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 54, '54. ዛሬም ማንኛይቱም ነፍስ ምንንም አትበደልም:: ትሰሩትም የነበራችሁትን እንጂ ሌላን አትመነዱም (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 55, '55. የገነት ሰዎች ዛሬ በእርግጥ በስራዎች ውስጥ ተደሳቾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 56, '56. እነርሱም ሆኑ ሚስቶቻቸው በጥላዎች ውስጥ ናቸው:: ባለ አጎበር አልጋዎች ላይም ተደጋፊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 57, '57. በውስጧ ለእነርሱ ፍራፍሬዎች አሏቸው:: ለእነርሱም የሚፈልጉት ሁሉ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 58, '58. ለእነርሱም አዛኝ ከሆነው ጌታ በቃል ሰላምታ አለላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 59, '59. (አላህም ይላል): «እናንተ አመጸኞች ሆይ! ዛሬ ከትክክለኛ አማኞች ተለዩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 60, '60. «የአደም ልጆች ሆይ! ሰይጣንን አትገዙ እርሱ ለእናንተ ግልጽ ጠላት ነውና በማለት ወደ እናንተ አላዘዝኩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 61, '61. «ተገዙኝም ይህ ቀጥተኛ መንገድ ነው በማለትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 62, '62. «ከናንተም ብዙን ፍጡር በእርግጥ አሳስቷል:: የምታውቁም አልነበራችሁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 63, '63. «ይህቺ ያቺ ትቀጠሯት የነበረችው ገሀነም ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 64, '64. «ትክዱ በነበራችሁት ምክንያት ዛሬዉኑ ግቧት።» (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 65, '65. ዛሬ በአፎቻቸው ላይ እናትምና እጆቻቸው ያነጋግሩናል:: እግሮቻቸዉም ይሰሩት በነበሩት ሁሉ ይመሰክራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 66, '66. ብንፈልግ ኖሮ በዓይኖቻቸው ላይ በአበስን ነበር:: መንገድንም እንደ ልማዳቸው በተሸቀዳደሙ ነበር:: እንዴትስ ያያሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 67, '67. ብንፈልግ ኖሮ በስፍራቸው ላይ እንዳሉ ወደ ሌላ ፍጥረት በለወጥናቸው ነበር:: ከዚያም መሄድንም ሆነ መመለስን ባልቻሉም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 68, '68. እድሜውንም የምናረዝመውን በፍጥረቱ ወደ ደካማነት እንመልሰዋለን:: አያውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 69, '69. (ሙሐመድን) ቅኔንም አላስተማርነዉም:: ለእርሱም አይገባዉም:: እርሱ (መጽሐፉ) መገሰጫና ገላጭ ቁርኣን አንጅ (ቅኔ አይደለም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 70, '70. ግሳጼነቱም ልቡ ህያው የሆነን ሰው ሊያስፈራራበትና ቃሉም በከሓዲያን ላይ ይፈጸም ዘንድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 71, '71. እኛ እጆቻችን ከሰሩት ለእነርሱ እንሰሳዎችን መፍጠራችንን አያውቁምን? እነርሱም ለእርሷ ባለ መብቶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 72, '72. ለእነርሱም ገራናት:: ስለዚህ ከእርሷ ውስጥ የሚጋልቡት አለ:: ከእርሷም ይመገባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 73, '73. ለእነርሱም በእርሷ ውስጥ ሌሎች ጥቅሞችና መጠጦችም አሏቸው። ታዲያ አያመሰግኑምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 74, '74. መረዳትንም በመከጀል ከአላህ ሌላ አመለኩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 75, '75. ሊረዷቸውም አይችሉም። እነርሱም ለእርሳቸው ወደ እሳት የተቀረቡ ሰራዊት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 76, '76. (መልዕክተኛችን ሙሐመድ ሆይ!) ንግግራቸዉም አያሳዝንህ:: እኛ የሚደብቁትንም የሚገልፁትንም እናውቃለንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 77, '77. ሰው እኛ ከፍትወት ጠብታ የፈጠርነው መሆናችንን አላወቀምን? ወዲያዉም እርሱ ትንሳኤን በመካድ ግልጽ ተከራካሪ ይሆናልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 78, '78. ለእኛም ምሳሌን አደረገልን:: መፈጠሩንም ረሳ:: «አጥንቶችን እነርሱ የበሰበሱ ሲሆኑ ህያው የሚያደርጋቸው ማነው?» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 79, '79. «ያ! በመጀመሪያ ጊዜ (ከኢምንት) ያስገኛት ጌታ እንደገና ህያው ያደረጋታል:: እርሱም በፍጡሩ ሁሉ ሁኔታ አዋቂ ነው።» በለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 80, '80. ያ! ለእናንተ ከእርጥብ ዛፍ እሳትን የፈጠረላችሁ ነው:: ወዲያውኑም እናንተ ከእርሱ ታቀጣጥላላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 81, '81. ያ! ሰማያትንና ምድርን የፈጠረ ብጤያቸውን በመፍጠር ላይ ቻይ አይደለምን? እንዴታ ቻይ ነው እንጂ:: እርሱም በብዙ ፈጣሪውና እጅግ አዋቂው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 82, '82. ነገሩ አንድን ነገር በሻ ጊዜ ሁን ማለት ብቻ ነው:: ከዚያ ወዲያው ይሆናልም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (36, 83, '83. እናም ያ የነገሩ ሁሉ ስልጣን በእጁ የሆነው ጌታ ጥራት ይገባው:: ወደ እርሱም ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 1, '1. መሰለፍን በሚሰለፉት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 2, '2. (ደመና) መንዳትን በሚነዱት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 3, '3. ቁርኣንንም በሚያነቡት እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 4, '4. አምላካችሁ በእርግጥ አንድ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 5, '5. እርሱ ያ በሰማያትና በምድር በመካካለቸው ያለውም ፍጡር ሁሉ ጌታ ነው:: የምስራቆችም ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 6, '6. እኛ ቅርቢቱን ሰማይ በከዋክብት ጌጥ አጌጥናት (አስዋብናት)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 7, '7. አመጸኛ ከሆነ ሰይጣንም ሁሉ መጠበቅን ጠበቅናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 8, '8. ወደ ላይኛው ሰራዊት አያደምጡም፤ ከየአቅጣጫውም ሁሉ ችቦ ይጣልባቸዋል፤ (ይቀጠቀጣሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 9, '9. የሚባረሩ ሲሆኑ (ይጣልባቸዋል)፤ ለእነርሱም ዘውታሪ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 10, '10. ንጥቂያን የነጠቀ ወዲያውኑም አብሪ ኮከብ የተከተለው ሲቀር (እርሱ ይሰማዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ!) ጠይቃቸውም፤ እነርሱ በአፈጣጠር ይበልጥ የበረቱ ናቸውን? ወይስ እኛ ከእነርሱ በፊት የፈጠረነው ፍጡር? እኛ ከሚጣበቅ ጭቃ ፈጠርናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 12, '12. ይልቁንም ማስተባበላቸው አስደነቀህ፤ በመደነቅህም ይሳለቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 13, '13. በተገሰጹም ጊዜ አይገሰጹም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 14, '14. ተዓምርንም ባዩ ጊዜ ለመሳለቅ ይጣጣራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 15, '15. አሉም: «ይህ ግልጽ ድግምት እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 16, '16. «በሞትንና ዐፈርና አጥንቶችም በሆን ጊዜ የምንቀስቀስ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 17, '17. «የቀድሞዎቹ አባቶቻችንም እንደዚሁ ይቀሰቀሳሉን?» (ይላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 18, '18. (መልዕክተኛችን ሙሐመድ ሆይ!) «አዎን! እናንተ ወራዶች ሆናችሁ (ትነሳላችሁ)።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 19, '19. እርሷም አንዲት ጩኸት ብቻ ናት:: እነርሱም ወዲያውኑ ምን እንደሚፈጸምባቸው ያያሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 20, '20. «ዋ ጥፋታችን! ይህ የፍርዱ ቀን ነው።» (ይላሉም)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 21, '21. «ይህ ያ በእርሱ ታስተባብሉት የነበራችት መለያው ቀን ነው።» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 22, '22. (ለመላዕክቶችም) «እነዚያን ነፍሶቻቸውን የበደሉትን ሰዎች ጓደኞቻቸውንም ከአላህ ሌላ ይገዟቸው የነበሩትንም ጣዖታት በአንድ ሰብስቡ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 23, '23. ከአላህ ውጭ (ይገዟቸው የነበሩትን ሰብስቡ)። ከዚያም ወደ ገሀነም መንገድ ምሯቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 24, '24. «እነርሱ ተጠያቂዎች ናቸውና አቁሟቸዉም።» (ይባላል።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 25, '25. ለነርሱም «ምን ሆናችሁ ነው የማትረዳዱት?» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 26, '26. በእርግጥ እነርሱ ዛሬ እጃቸውን የሰጡ ማምለጫ የሌላቸው ወራዳዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 27, '27. እርስ በራሳቸውም የሚወቃቀሱም ሆነው ይመጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 28, '28. (ተከታዮቹ ለአስከታዮቻቸው) «እናንተ በጉልበት ትመጡብን ነበር» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 29, '29. (አስከታዮቹም) ይላሉ፡- «አይደለም ፈጽሞ አማኞች አልነበራችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 30, '30. «ለእኛም በናንተ ላይ ምንም ስልጣን አልነበረንም። በእርግጥ እናንተ ጠማሞች ህዝቦች ነበራችሁና ነው እንጂ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 31, '31. «በእኛም ላይ የጌታችን ቃል የተረጋገጠብንና ሁላችንም ቅጣቱን ቀማሽ ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 32, '32. «እኛ ጠማሞች ስለ ነበርን ወደ ጥመት ጠራናችሁም።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 33, '33. ስለዚህ እነርሱ በዚያ ቀን በቅጣቱ ተጋሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 34, '34. እኛ በአመጸኞች ሁሉ እንደዚሁ እንሰራለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 35, '35. እነርሱ «ከአላህ ሌላ ትክክለኛ አምላክ የለም» በተባሉ ጊዜ ይኮሩ ነበሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 36, '36. «እኛ ለዕብድ ባለቅኔ ብለን አማልክቶቻችንን የምንተው ነን እንዴ?» ይሉ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 37, '37. አይደለም እውነቱን ሃይማኖት አመጣ፤ መልዕክተኞቹንም እውነተኝነታቸውን አረጋገጠ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 38, '38. እናንተ አሳማሚውን ቅጣት እርግጥ ቀማሾች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 39, '39. ትሰሩትም የነበራችሁትን እንጂ ሌላን አትመነዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 40, '40. ግን ምርጥ የሆኑት የአላህ ባሮች ቅጣትን አይቀምሱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 41, '41. እነዚያ ለእነርሱ የታወቀ ሲሳይ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 42, '42. ፍራፋሬዎች (አሉላቸው) እነርሱም የተከበሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 43, '43. በድሎት ገነቶች ውስጥ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 44, '44. ፊት ለፊት የሚተያዩ ሲሆኑ በአልጋዎች ላይ ይንፈላሰሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 45, '45. ከሚመነጭ ወይን ጠጅ በያዙ ብርጭቆ በእነርሱ ላይ ይዞርባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 46, '46. ነጭ ለጠጪዎች ጣፋጭ ከሆነች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 47, '47. በእርሷ ውስጥም የራስ ምታት የለባትም:: እነርሱም ከእርሷ የሚሰክሩ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 48, '48. እነርሱ ዘንድ ዓይናቸውን በባሎቻቸው ላይ ብቻ አሳጣሪዎች የሆኑ ዓይናማ ሴቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 49, '49. እነርሱ ልክ የተሸፈነ (የሰጎን) እንቁላል ይመስላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 50, '50. የሚጠያያቁም ሆነው ከፊላቸው ወደ ከፊሉ ይመጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 51, '51. ከእነርሱ የሆነ ተናጋሪ (እንዲህ) ይላል: «እኔ ጓደኛ ነበረኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 52, '52. (እንዲህ) የሚል: ‹በእርግጥ አንተ ከሚያምኑት ነህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 53, '53. ‹በሞትንና ዐፈር አጥንቶችም በሆነ ጊዜ እኛ በእርግጥ እኛ እንመረመራለን?› የሚልም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 54, '54. እናንተ ተመልካቾች ናችሁን? ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 55, '55. ይመለከታልም በገሀነም መካከልም ጓደኛውን ያየዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 56, '56. ይላል «በአላህ እምላለሁ በእርግጥ ልታጠፋኝ ቀርበህ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 57, '57. «የጌታየም ጸጋ ባልነበረ ኖሮ ወደ እሳት ከሚቀርቡት እሆን ነበር።» (ይላል)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 58, '58. (የገነት ሰዎች ይላሉ)፡ «እኛ የምንሞት ሰዎች አይደለንምን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 59, '59. «የመጀመሪያይቱ መሞታችን ብቻ ስትቀር እኛም የምንቀጣ አይደለንም» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 60, '60.ይህ ለገነት ሰዎች የተወሳው እርሱ በእርግጥ ታላቅ እድል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 61, '61. ለዚህ ብጤ ሰሪዎች ሁሉ ይስሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 62, '62. በመስተንግዶነት ይህ ይበልጣልን? ወይስ የዘቁም ዛፍ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 63, '63. እኛ ለበዳዮች ፈተና አድርገናታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 64, '64. እርሷ ከገሀነም አዘቅት ውስጥ የምትወጣ ዛፍ ናት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 65, '65. እንቡጧ ልክ የሰይጣናት ራሶች ይመስላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 66, '66. እነርሱ ከእርሷ በይዎች ናቸው:: ሆዶችንም ከእርሷ ሞይዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 67, '67. ከዚያ ለእነርሱ በእርሷ ላይ ከተኳሳ ውሃ ቅልቅልን መጠጥ አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 68, '68. ከዚያም መመለሻቸው ወደ ተጋጋመች እሳት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 69, '69. እነርሱ አባቶቻቸውን የተሳሳቱ ሆነው አግኝተዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 70, '70. እነርሱም በፈለጎቻቸው ላይ ይገሰግሳሉና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 71, '71. ከእነርሱም በፊት የነበሩት የቀድሞዎቹ ህዝቦች አብዛሀኞቻቸው በእርግጥ ተሳስተዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 72, '72. በውስጣቸዉም አስፈራሪዎችን በእርግጥ ልከናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 73, '73. (መልዕክተኛችን ሙሐመድ ሆይ!) የተስፈራሪዎቹም መጨረሻ እንዴት እንደነበረ ተመልከት!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 74, '74. ምርጥ የሆኑት የአላህ ባሮች ብቻ ሲቀሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 75, '75. ኑህም በእርግጥ ጠራን:: ምንኛ ያማርን ምላሽ ሰጪ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 76, '76. እርሱንም ቤተሰቦቹንም ከከባድ ጭንቅ አዳንን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 77, '77. ዘሮቹንም እነርሱን ብቻ ቀሪዎች አደረግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 78, '78. በእርሱም ላይ በኋለኞቹ ህዝቦች ውስጥ መልካምን ዝና ተውን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 79, '79. «በዓለማት ውስጥ ሰላም በኑህ ላይ ይሁን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 80, '80. እኛ ልክ እንደዚሁ መልካም ሰሪዎችን እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 81, '81. እርሱ ከአማኞች ባሮቻችን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 82, '82. ከዚያም ሌሎችን አሰመጥን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ! ) ኢብራሂምም በእርግጥ ከወገኖቹ አንዱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 84, '84. ወደ ጌታው በቅን ልብ በመጣ ጊዜ የሆነውን (አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 85, '85. ለአባቱና ለህዝቦቹ ባለ ጊዜ: «ምንን ትገዛላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 86, '86. «ለቅጥፈት ብላችሁ ከአላህ ሌላ አማልክትን ትሻላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 87, '87. «በዓለማቱ ጌታስ ሀሳባችሁ ምንድ ነው?።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 88, '88. በከዋክብት መመልከትን ተመለከተ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 89, '89. እኔ «በሽተኛ ነኝ» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 90, '90. እነርሱም ከእርሱ የሸሹ ሆነው ሄዱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 91, '91. ከዚያ እሱ ወደ አማልዕክቶቻቸው ተዘነበለ፤ (እንዲህ) አለም፡- «አትበሉም እንዴ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 92, '92. «ምንም የማትናገሩበትስ ምን ምክኒያት አላችሁ?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 93, '93. በቀኝ (እጁ) የሚመታቸዉም ሆኖ በእነርሱ ላይ በድብቅ ተዘነበለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 94, '94. ወደ እርሱም ሰዎቹ እየሮጡ መጡ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 95, '95. አለ: «የምትጠርቡትን ትገዛላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 96, '96. «አላህ እናንተንም ሆነ የምትሰሩትን ሁሉ የፈጠረ ሲሆን» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 97, '97. «ለእርሱም ግንብን ገንቡ በእሳት ነበልባል ውስጥ ጣሉትም።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 98, '98. ለእርሱ ተንኮልን አስቡ ወራዶችም አደረግናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 99, '99. አለም፡- «እኔ ወደ ጌታየ ሂያጅ ነኝ፤ በእርግጥ ይመራኛልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 100, '100. «ጌታየ ሆይ! ከመልካሞቹ የሆነን (ልጅ) ስጠኝ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 101, '101. ታጋሽም በሆነ ልጅም አበሰርነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 102, '102. ከእርሱ ጋርም (ለስራ) በደረሰ ጊዜ «ልጄ ሆይ! እኔ በህልሜ እኔ የማርድህ ሆኜ አያለሁ፤ ተመልከትም፤ ምን ትላለህ?» አለው። «አባቴ ሆይ! የታዘዝከውን ስራ፤ አላህ ቢሻ ከታጋሾች ሆኜ ታገኘኛለህ።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 103, '103. ሁለቱም ትዕዛዙን በተቀበሉና በግንባሩም ጎን ላይ በጣለው ጊዜ (የሆነው ሆነ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 104, '104. ጠራነዉም: «ኢብራሂም ሆይ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 105, '105. «ራዕዩን በርግጥ እውን አደረግክ።» እኛ ልክ እንደዚሁ መልካም ሰሪዎችን እንመነዳለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 106, '106. ይህ እርሱ በእውነት ግልጽ ፈተና ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 107, '107. በታላቅ እርድም መስዕዋት ቤዛ አደረግንለት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 108, '108. በእርሱም ላይ በኋለኞቹ ህዝቦች ውስጥ መልካም ዝናን አስቀረንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 109, '109. ሰላም በኢብራሂም ላይ ይሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 110, '110. ልክ እንደዚሁ መልካም ሰሪዎችን ሁሉ እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 111, '111. እርሱ በእርግጥ ካመኑት ባሮቻችን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 112, '112. በኢስሐቅም አበሰርነው። ከመልካሞች የሆነ ነብይ ሲሆን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 113, '113. በእርሱና በኢስሐቅ ላይም ባረክን። ከሁለቱም ዘሮች በጎ ሰሪ አለ:: ነፍሱን በግልጽ በዳይም አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 114, '114. በሙሳና በሀሩን ላይ በእርግጥ ለገስን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 115, '115. እነርሱንም ሆነ ህዝቦቻቸውንም ከታላቅ ጭንቅ አዳንን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 116, '116. ረዳናቸውናም እነርሱ አሸናፊዎቹ ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 117, '117. በጣም የተብራራውንም መጽሐፍ ሰጠናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 118, '118. ቀጥተኛውንም መንገድ መራናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 119, '119. በሁለቱም ላይ በኋለኞቹ ህዝቦች ውስጥ መልካምን ዝናን ተውንላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 120, '120. ሰላም በሙሳና በሀሩን ላይ ይሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 121, '121. እኛ ልክ እንደዚሁ በጎ አድራጊዎችን ሁሉ እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 122, '122. ሁለቱም በትክክል በአላህ ካመኑት ባሮቻችን ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 123, '123. ኢልያስም በእርግጥ ከመልዕክተኞቹ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 124, '124. ለህዝቦቹም ባለ ጊዜ (አስታውስ) «አላህን አትፈሩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 125, '125. «ስዕልን ትገዛላችሁ? ከስዓሊዎቹ ሁሉ ይበልጥ በጣም አሳማሪ የሆነዉም አምላክ ትተዋላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 126, '126. «አላህ ጌታችሁና የቀድሞዎቹ አባቶቻችሁንም ጌታ ትተዋላችሁን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 127, '127. አስተባበሉትም ስለዚህ እነርሱ ለቅጣት የሚጣዱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 128, '128. ንጹህ የተደረጉት የአላህ ባሮች ብቻ ሲቀሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 129, '129. በእነርሱ ላይም በኋለኞቹ ህዝቦች ውስጥ መልካም ዝናን ተውንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 130, '130. ሰላም በኢልያስ ላይ ይሁን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 131, '131. እኛ ልክ እንደዚሁ መልካም ሰሪዎችን እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 132, '132. እርሱ በእርግጥ ከምዕመናን ባሮቻችን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 133, '133. ሉጥም በእርግጥ ከመልዕክተኞቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 134, '134. እርሱንና ቤተሰቦቹን ሁሉንም በአዳናቸው ጊዜ (የሆነዉን አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 135, '135. በቅጣቱ ውስጥ ከቀሪዎቹ የሆነችው አሮጊት ብቻ ስትቀር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 136, '136. ከዚያም ሌሎቹን አጠፋን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 137, '137. (መኮች ሆይ)፤ እናንተም በእነርሱ መኖሪያዎች ላይ ያነጋችሁ ስትሆኑ ታልፋላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 138, '138. በሌሊትም ታልፋላችሁ:: ልብ አታደርጉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 139, '139. ዩኑስም በእርግጥ ከመልዕክተኞቹ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 140, '140. ወደ ተሞላው መርከብ በኮበለለ ጊዜ አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 141, '141. እጣም ተጣጣለ፤ ከተሸነፉትም ሆነ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 142, '142. እርሱም ተወቃሽ ሲሆን ዐሳ ነባሪው ዋጠው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 143, '143. እርሱ ለጌታው ከአወዳሾቹ ባልሆነ ኖሮ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 144, '144. እስከሚቀሰቀሱበት ቀን ድረስ በሆዱ ውስጥ በቆየ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 145, '145. እርሱ በሽተኛ ሆኖ በቃይ በሌለው ባህር ዳርቻ ላይ ጣልነዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 146, '146. በእርሱም ላይ በአጠገቡ ከቅል የሆነችን ዛፍ አበቀልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 147, '147. ወደ መቶ ሺህ ሰዎችም ላክነው፤ ከቶውንም ይጨምራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 148, '148. አመኑም። እስከ ጊዜው ድረስም አጣቀምናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 149, '149. (መልዕክተኛችን ሙሐመድ ሆይ!) የመካን ሰዎች ጠይቃቸዉም: «ለጌታህ ሴት ልጆች ለእነርሱም ወንዶች ልጆች ይኖራሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 150, '150. «ወይስ እኛ እነርሱ የተጣዱ ሆነው መላዕክትን ሴቶች አድርገን ፈጠርን?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 151, '151. አስተውሉ! እነርሱ ከቅጥፈታቸው የተነሳ ይላሉ:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 152, '152.፡- «አላህ መላዕክትን ወለደ።» እነርሱም በእርግጥ ውሸታሞች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 153, '153. በወንዶች ልጆች ላይ ይልቅ ሴቶችን ልጆች መረጠን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 154, '154. ለእናንተ ምን አስረጂ አላችሁ? እንዴት ትፈርዳላችሁ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 155, '155. አትገነዘቡምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 156, '156. ወይስ ለእናንተ ግልጽ አስረጂ አላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 157, '157. «እውነተኞች እንደሆናችሁ መጽሐፋችሁን አምጡ» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 158, '158. በአላህና በአጋንንት መካከልም ዝምድናን አደረጉ:: አጋንንትም ሆኑ ይህን ባዩች በእሳት የሚጣዱ መሆናቸውን በእርግጥ አውቀዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 159, '159. አላህ ከሚመጥኑት ሁሉ ጠራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 160, '160. ግን የተመረጡት የአላህ ባሮች በአላህ ላይ አይዋሹም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 161, '161. (ካሐዲያን ሆይ!) እናንተም የምትገዟቸዉም ሁሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 162, '162. በእርሱ በአላህ ላይ አንድንም አጥማሚዎች አይደላችሁም', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 163, '163. ያንን እርሱ ገሀነም ገቢ የሆነውን ቢሆን እንጂ (አጥማሚዎች አይደላችሁም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 164, '164. (መላእክቶችም አሉ)? «ከእኛ አንድም የለም፤ ለእርሱ የታወቀ ደረጃ ያለው ቢሆን እንጅ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 165, '165. «እኛም ጌታን ለመገዛት ተሰላፊዎቹ እኛ ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 166, '166. «እኛም አላህን አጥሪዎቹ እኛው ነን።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 167, '167. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱ (ከሓዲያን) በእርግጥ ይሉ ነበር:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 168, '168. «ከቀድሞዎቹ መጽሐፍ ገሳጭ መጽሐፍ እኛ ዘንድ በነበረ ኖሮ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 169, '169. «የአላህ ምርጦች ባሮች በሆን ነበር።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 170, '170. ግን ቁርኣኑ በመጣላቸው ጊዜ በእርሱ ላይ ካዱ። ወደ ፊትም በእርግጥ ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 171, '171. የእርዳታ ቃላችንም መልዕክተኞች ለሆኑት ባሮቻችን በእውነት አልፋለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 172, '172. እነርሱ ተረጂዎቹ እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 173, '173. ሰራዊቶቻችንም በእርግጥ አሸናፊዎቹ እነርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 174, '174. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም ከመካ ከሓዲያን እስከ ጥቂት ጊዜ ድረስ ዙር ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 175, '175. ተመልከታቸዉም ወደፊትም የሚደርስባቸውን ያያሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 176, '176. በቅጣታችንም ያቻኩሉናልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 177, '177. በቀያቸዉም በወረደ ጊዜ የተስፈራሪዎቹ ንጋት ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 178, '178. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱን እስከ ጥቂት ጊዜ ድረስ ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 179, '179. ተመልከትም በእርግጥም ያያሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 180, '180. (መልዕክተኛችን ሙሐመድ ሆይ!) የማሸነፍ ጌታ የሆነው ጌታህ ከሚሉት ሁሉ ጠራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 181, '181. በመልዕክተኞቹም ላይ ሰላም ይሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (37, 182, '182. ምስጋና ሁሉም ለዓለማት ጌታ ለሆነው ለአላህ ብቻ ይገባው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 1, '1. ሷድ፤ የግሳፄ ባለቤት በሆነው ቁርኣን እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 2, '2. ይልቁንም እነዚያ በአላህ የካዱ ሰዎች በከባድ ትዕቢትና በአጓጉል ክርክር ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 3, '3. ከእነርሱ በፊት ከክፍለ ዘመናት ህዝቦች ብዙን አጥፍተናል:: ጊዜው የመሸሻና የማምለጫ ጊዜ ሳይሆንም (ለእርዳታ) ተጣሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 4, '4. ከእነርሱ መካከል የሆነ አስፈራሪ ስለመጣላቸውም ተደነቁ:: ከሓዲያንም አሉ: «ይህ ድግምተኛ ጠንቋይ ውሸታም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 5, '5. «አማልዕክቶችን አንድ አምላክ አደረጋቸውን? ይህ አስደናቂ ነገር ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 6, '6. ከእነርሱም መካከል ባላባቶቹ (እንዲህ) እያሉ አዘገሙ: «ሂዱ በአማልክቶቻችሁም መገዛት ላይ ጽኑ:: ይህ ከእኛ የሚፈለግ ነገር ነውና', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 7, '7. «ይህንንም አስተምህሮት ከኋለኛይቱ (ከመጨረሻይቱ) ሃይማኖት አልሰማንም:: ይህ ውሸትን መፍጠር እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 8, '8. «ከመካከላችን በእርሱ ላይ ብቻ ቁርኣን ተወረደን?» (እያሉ አዘገሙ።) ይልቁን እነርሱ ከግሳጼየ በመጠራጠር ውስጥ ናቸው:: በእርግጥም ቅጣትን ገና አልቀመሱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 9, '9. ወይስ የአሸናፊውና የለጋሹ ጌታህ የአላህ የችሮታው መካዚኖች እነርሱ ዘንድ ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 10, '10. ወይስ የሰማይ የምድር እና የመካከላቸዉም ንግስና የእነርሱ ነውን? (ነው ካሉ) እስቲ በመሰላሎች ወደ ላይ ይውጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 11, '11. እነርሱም እዚያ ዘንድ ከአህዛብ ሁሉ ተሸናፊ የሆነ ሰራዊት ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 12, '12. ከእነርሱም በፊት የኑህ ህዝቦች፤ ዓድ እና የችካሎች ባለቤት የሆነው ፈርዖንም አስተባብለዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 13, '13. ሰሙድም፤ የሉጥ ሰዎችም፤ የአይካ ሰዎችም፤ አስተባበሉ:: እነዚህ አህዛቦቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 14, '14. ሁሉም መልዕክተኞችን ያስዋሹ እንጂ ሌላ አይደሉም:: ከዚያ ቅጣቴ ተረጋገጠባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚህ ያችን ለእርሷ መመለስ የሌላትን አንዲት ጩኸት ብቻ እንጂ ሌላን አይጠባበቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 16, '16. (በመሳለቅም) «ጌታችን ሆይ! ከምርመራው ቀን በፊት ቅጣታችንን አጣድፍልን» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) በሚሉት ነገር ላይ ታገስ:: የሃኃይል ባለቤት የሆነውን ባሪያችንንም ዳውድን አውሳው:: እርሱ በጣም መላሳ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 18, '18. እኛ ተራራዎችን ከቀትር በኋላና በረፋዱም ከእርሱ ጋር የሚያወድሱ ሲሆን እንዲታዘዙት አገራንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 19, '19. በራሪዎችንም (አእዋፍን) የሚሰበሰቡ ሆነው አገራንለት:: ሁሉም ለእርሱ ማወደስ የሚመላለስ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 20, '20. ንግስናውንም አበረታንለት ጥበብንና ንግግርን መለየትንም ሰጠነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) የተከራካሪዎቹ ወሬ መጥቶልሃልን? እልፍኙን (ምኩራቡን) በተንጠላጠሉ ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 22, '22. በዳውድ ላይም በገቡ ጊዜ ከእነርሱም ሁኔታ በደነገጠ ጊዜ (እንዲህ) አሉት: «አትፍራ። እኛ ከፊላችን በከፊሉ ላይ ወሰን ያለፈ ሁለት ተከራካሪዎች ነን። በመካከላችንም በእውነት ፍረድ። አታዳላም። ወደ ትክክለኛው መንገድም ምራን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 23, '23. «ይህ ወንድሜ ነው:: ለእርሱ ዘጠና ዘጠኝ ሴት በጎች አሉት ለእኔም አንዲት ሴት በግ አለችኝ ‹እርሷንም ለእኔ አድርጋት› አለኝ:: በንግግርም አሸነፈኝ።» አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 24, '24. «ሴት በግህን ወደ በጎቹ ለመቀላቀል በመጠየቁ በእርግጥ በደለህ። ከተጋሪዎች ብዙዎቹ ከፊላቸው በከፊሉ ላይ ወሰን ያልፋሉ:: እነዚያ ያመኑትና መልካሞችን የሰሩት ብቻ ሲቀሩ፤ እነርሱም በጣም ጥቂቶች ናቸው።» አለ:: ዳውድም የፈተንነው መሆኑን ወዲያዉኑ አወቀ:: ከጌታዉም ምህረትን ለመነና ሰጋጅ ሆኖም ወደቀ። በመጸጸትም ተመለሰ:: {1}', '{1} እዚህ አንድ ሱጁድ ይደረጋል');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 25, '25. ያንንም ማርነው። ለእርሱም እኛ ዘንድ የመቅረብ ክብር መልካም መመለሻም አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 26, '26. (እኛም አልነው) «ዳውድ ሆይ! እኛ በምድር ላይ ምትክ አድርገንሀልና በሰዎች መካከል በእውነት ፍረድ:: የግል ዝንባሌህንም አትከተል:: ከአላህ መንገድ ያሳስተሃልና።» እነዚያ ከአላህ መንገድ የሚሳሳቱ ሁሉ የምርመራውን ቀን በመርሳታቸው ለእነርሱ ብርቱ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 27, '27. ሰማይን ምድርና በመካከላቸዉም ያለውን ሁሉ ለከንቱ አልፈጠርንም:: ይህ የእነዚያ የካዱት ሰዎች ጥርጣሬ ነው:: ለእነዚያም ለካዱት ሰዎች ሁሉ ከእሳት ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 28, '28. በእውነቱ እነዚያ ያመኑትና መልካም ተግባሮችን የሰሩትን ልክ በምድር ውስጥ እንደሚያጠፉት እናደርጋለንን? ወይስ አላህን ፈሪዎችን ልክ እንደ ከሓዲያን እናደርጋለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 29, '29. ይህ መጽሀፍ ወደ አንተ ያወረድነው ብሩክ መጽሀፍ ነው:: አናቅጽን እንዲያስተነትኑና የአእምሮ ባላቤቶችም እንዲገሰጹበት አወረድነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 30, '30. ለዳውድም ሱለይማንን ሰጠነው:: ሱለይማን ምን ያምር ባሪያ ነው:: እርሱ ወደ ጌታው መላሳ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 31, '31. በእርሱ ላይ ከቀትር በኋላ በሶስት እግሮችና በአራተኛው እግር ኮቴ ጫፍ የሚቆሙ ጮሌ ፈረሶች በተቀረቡለት ጊዜ (የሆነዉን አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 32, '32. (እንዲህም) አለ: «ጸሀይ በግርዶ እስከተደበቀች ድረስ ጌታየን ከማስታወስ ፈንታ ፈረስን መውደድን መረጥኩ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 33, '33. «በሉ ፈረሶችን ወደ እኔ መልሷቸው።» (አለ)። ከዚያም እግሮቻቸዉንና አንገቶቻቸዉን መቁረጥ ያዘ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 34, '34. ሱለይማንንም በእርግጥ ፈተንነው። በመንበሩም ላይ የሆነ አካልን ጣልን:: ከዚያም በመጸጸት ተመለሰ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 35, '35. «ጌታዬ ሆይ! ማረኝ ከእኔ በኋላ ለአንድም የማይገባን ንግስናንም ስጠኝ:: ለጋሹ አንተ ብቻ ነህና» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 36, '36. ንፋስንም በትዕዛዙ ወደ ፈለገበት ስፍራ ልዝብ ሆና የምትነፍስ ስትሆን ገራንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 37, '37. ሰይጣናትንም ገንቢዎችንና ሰማጮችን ሁሉ ገራንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 38, '38. ሌሎችንም በሰንሰለቶች ተቆራኞችን ገራንለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 39, '39. ይህ ስጦታችን ነው ያለ ግምት ለግስ:: ወይም ጨብጥ (አልነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 40, '40. ለእርሱም እኛ ዘንድ መቅረብ መልካም መመለሻም በእርግጥ አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) ባሪያችን አዩብንም: «እኔ ሰይጣን በጉዳትና በስቃይ ነካኝ» ሲል ጌታውን በተጣራ ጊዜ።የሆነውን አስታውስ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 42, '42. በእግርህ ምድርን ምታ:: ይህ ቀዝቃዛ መታጠቢያ መጠጥም ነው (ተባለ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 43, '43. ለእርሱ ከእኛ ዘንድ በሆነ ችሮታ ባለ አእምሮዎችንም ለመገሰጽ ቤተሰቦቹንም ከእነርሱ ጋር መሰላቸውን ሰጠነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 44, '44. «በእጅህ ጭብጥ አርጩሜን ያዝ በእርሱም (ሚስትህን) ምታ። ማላህንም አታፍርስ።» (አልነው) እነሆ ታጋሽ ሆኖ አገኘነው:: ምን ያምር ባሪያ ነው:: እርሱም በጣም መላሳ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) እንዚያን የኅይልና የማስተዋል ባለቤቶች የሆኑትን ባሮቻችንም ኢብራሂምን ኢስሐቅንና ያዕቆብንም ለህዝቦችህ አውሳላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 46, '46. እኛ ጥሩ በሆነች ጠባይ መረጥናቸው፤ እርሷም የመጨረሻይቱን አገር ማስታወስ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 47, '47. እነርሱም እኛ ዘንድ ከመልካሞቹ ምርጦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢስማኢልንም፤ ኢልያስንም፤ ዙልኪፍልንም አውሳ፤ ሁሉም ከበላጮቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ መልካም ዝና ነው:: አላህን ለሚፈሩም በእርግጥ ውብ የሆነ መመለሻ አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 50, '50. በሮቻቸው ለእነርሱ የተከፈቱ ሲሆኑ የመኖሪያ ገነቶች አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 51, '51. በእርሷ ውስጥ የተደገፉ ሆነው በውስጧ በብዙ እሸቶችና በመጠጥም ያዝዛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 52, '52. እነርሱ ዘንድም ዓይኖቻቸውን በባሎቻቸው ላይ አሳጣሪዎች እኩያዎች ሴቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 53, '53. ይህ ለምርመራው ቀን የምትቀጠሩት ተስፋ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 54, '54. ይህ ሲሳያችን ነው:: ለእርሱ ምንም ማለቅ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 55, '55. ይህ (ለትክክለኛ አማኞች ሲሆን።) ለጠማሞችም በጣም የከፋ መመለሻ አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 56, '56. የሚገቧት ስትሆን ገሀነም አለቻቸው:: ምንጣፊቱም ምንኛ ከፋች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 57, '57. ይህ ለከሓዲያን ነው:: ይቅመሱትም የፈላ ውሃና እዥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 58, '58. ሌላም እነርሱን ከመሰሉ ብዙ አይነቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 59, '59. ይህ ከናንተ ጋር በመጋፈጥ ገቢ ቡድን ነው (ይባላሉ):: ለእነርሱ አይስፋቸዉም:: እነርሱ እሳትን ገቢዎች ናቸውና (ይላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 60, '60. ተከታዮቹም ይላሉ፡- «ይልቁን እናንተ አይስፋችሁ። እናንተ ክህደቱን ለእኛ አቀረባችሁት መርጊያይቱም ገሀነም ከፋች።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 61, '61. «ጌታችን ሆይ! ይህንን ያቀረበልንን ሰው በእሳት ውስጥ ድርብ ቅጣትን ጨምርለት» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 62, '62. ይላሉም «ለእኛ ምን አለን? ከመጥፎዎች እንቆጥራቸው የነበሩትን ሰዎች እዚህ አናይምሳ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 63, '63. «(ሳይገባቸው) መቀለጃ አድርገን ይዘናቸው ነውን? ወይስ ዓይኖቻችን ከእነርሱ ዋለሉ?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 64, '64. ይህ በእርግጥ እውነት ነው:: እርሱም የእሳት ሰዎች የእርስ በርስ የመካሰስ ወሬ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) በል: «እኔ አስፈራሪ ብቻ ነኝ። ኃያልና አንድ ከሆነ አላህ በስተቀር ምንም አምላክ የለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 66, '66. «የሰማያትና የምድር በመካከላቸዉም ያለው ሁሉ ጌታ አሸናፊና መሐሪ ነው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 67, '67. (መልዕክተኛችን ሙሐመድ ሆይ!) በል: «እርሱ (ቁርኣን) ታላቅ ዜና ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 68, '68. «እናንተ ከእርሱ ዘንጊዎች ናችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 69, '69. «በሚከራከሩ ጊዜ በላይኛዋ ሰራዊት ለእኔ ምንም እውቀት አልነበረኝም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 70, '70. «ወደ እኔም አስፈራሪ ገላጭ በመሆኔ እንጂ በሌላ አይወርድልኝም።» በል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 71, '71. (መልዕክተኛችን ሙሐመድ ሆይ!) «ጌታህ ለመላዕክት እኔ ሰውን ከጭቃ ፈጣሪ ነኝ ባለ ጊዜ (የነበረዉን አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 72, '72. «ፍጥረቱንም ባስተካከልኩና ከመንፈሴ በነፋሁበትም ጊዜ ሁላችሁም ለእርሱ ሰጋጆች ሆናችሁ ውደቁ።» (አልኩ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 73, '73. መላው መላዕክትም በአንድነት ሰገዱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 74, '74. ዲያብሎስ ብቻ ሲቀር። ኮራም። ከከሓዲያንም ሆነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 75, '75. አላህ «ዲያብሎስ ሆይ! በሁለት እጆቼ ለፈጠርኩት ለአደም ከመስገድ ምን ከለከለህ? ኮርተህ ነው? ወይስ ፊቱኑ ከትዕቢተኞች ነበርክ?» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 76, '76. ዲያብሎስም «እኔ ከእርሱ የተሻልኩ ነኝ። እኔን ከእሳት የፈጠርከኝ ስትሆን እሱን ግን ከጭቃ ነው የፈጠርከው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 77, '77. (አላህም) አለ፡- «ከእርሷ ውጣ። አንተ የተባረርክ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 78, '78. «እርግማኔም እስከ ፍርዱ ቀን ድረስ ባንተ ላይ ይሁን።» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 79, '79. (ዲያብሎስም) «ጌታየ ሆይ! እስከሚቀሰቀሱበት ቀን ድረስ እባክህ አቆየኝ።» አለ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 80, '80. (አላህም) አለ፡- «አንተ ከሚቆዩት ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 81, '81. «እስከ ታወቀው ወቅት ቀን ድረስ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 82, '82. (እርሱም) አለ: «በአሸናፊነትህ ይሁንብኝ ሁላቸዉንም አሳስታቸዋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 83, '83. «ከእነርሱ መካከል ምርጥ ባሮችህ ብቻ ሲቀሩ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 84, '84. (አላህም) አለ: «እውነቱም ከእኔ ነው:: እውነትንም እላለሁ(እናገራለሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 85, '85. «በአንተና ከእነርሱ መካከል በተከተሉህም ባንድ ላይ ገሀነምን በእርግጥ እሞላታለሁ» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 86, '86.(መልዕክተኛችን ሙሐመድ ሆይ!) በል: «በእርሱ ላይ ምንም ዋጋ አል ጠይቃችሁም:: እኔም ከተግደርዳሪዎቹ አይደለሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 87, '87. «እርሱ (ቁርኣን) ለዓለማት መገሰጫ እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (38, 88, '88. «የትንቢቱን እውነትነት ከጊዜ በኋላም ቢሆን በእርግጥ ታውቁታላችሁ።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 1, '1. የመጽሐፉ መወረድ አሸናፊና ጥበበኛ ከሆነው ከአላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ ወደ አንተ መጽሐፉን በእውነት የተሞላ ሲሆን አወረድነው:: አላህንም ሃይማኖትን ለእርሱ ብቻ ያጠራህ ሆነህ ተገዛው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 3, '3. (ሙስሊሞች ሆይ!) አስተውሉ ፍጹም ጥሩ የሆነው ሃይማኖት ለአላህ ብቻ ነው:: እነዚያ ከእርሱ ሌላ ጣዖታትን ረዳቶች አድረገው የያዙት ሁሉ «ወደ አላህ ማቃረብን እንዲያቃርቡን በማሰብ እንጂ ለሌላ አንገዛቸዉም።» ይላሉ:: አላህ በዚያ እነርሱ በሚለያዩበት ነገር በመካከላቸው ይፈርዳል:: አላህም ውሸታምንና ከሓዲ የሆነን ሰው አያቀናም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 4, '4. አላህ ልጅን መያዝ በፈለገ ኖሮ ከሚፈጥረው ውስጥ የሚሻውን ይመርጥ ነበር:: ጥራት ተገባው:: እርሱ አሸናፊውና ብቸኛው አንዱ አላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 5, '5. አላህ ሰማያትንና ምድርን በእውነት ፈጠረ:: ሌሊቱንም በቀን ላይ ይጠቀልላል:: ቀኑንም በሌሊት ላይ እንዲሁ ይጠቀልላል:: ጸሐይንና ጨረቃንም ገራ:: ሁሉም ለተወሰነ ጊዜ ይሮጣሉ:: (ሙስሊሞች ሆይ!) አስተውሉ! እርሱ አሸናፊዉና መሀሪው ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 6, '6. (ሰዎች ሆይ!) ከአንዲት ነፍስ ፈጠራችሁ:: ከዚያም ከእርሷ መቀናጆዋን ፈጠረ:: ለእናንተም ከግመልና ከዳልጋ ከብት፤ ከፍየልና ከበግ ስምንት አይነቶችን (ጥንዶችን) አወረደ:: በእናቶቻችሁ ሆዶች ውስጥ በሶስት ጨለማዎች ውስጥ ከመፍጠር በኋላ ሙሉ መፍጠርን ይፈጥራችኋል፤ ይህን ያደረገው ጌታችሁ አላህ ነው:: ስልጣኑም የእርሱ ብቻ ነው:: ከእርሱ ሌላ ትክክለኛ አምላክ የለም:: ታዲያ ወዴት ትዞራላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 7, '7. በአላህ ብትክዱ አላህ ከናንተ የተብቃቃ ነው:: ለባሪያዎቹም ክህደትን አይወድም፤ ብታመሰግኑም እርሱን ይወድላችኋል:: ማንኛይቱም ኃጢአትን ተሸካሚ ነፍስ የሌላይቱን ኃጢአት አትሸከምም:: ከዚያም የሁላችሁም መመለሻችሁ ወደ ጌታችሁ ብቻ ነው:: ትሰሩት የነበራችሁትንም ሁሉ ይነግራችኋል:: እርሱ በልቦች ውስጥ ያሉትን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 8, '8. የሰውን ልጅ ጉዳት ባገኘው ጊዜ ወደ እርሱ ተመላሽ ሆኖ ጌታወን ይጠራል:: ከዚያም ከእርሱ ዘንድ ጸጋን በሰጠው ጊዜ ያንን ከዚያ በፊት ወደ እርሱ ይጸልይበት የነበረውን መከራ ይረሳል:: ከመንገዱ ለማሳሳትም ለአላህ ባላንጣዎችን ያደርጋል:: ለእንዲህ አይነቱ ሰው «በክህደት ጥቂትን ተጣቀም፤ አንተ በእርግጥ ከእሳት ጓዶች ነህ።» በለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 9, '9. (መልዕክተኛችን ሙሐመድ ሆይ!) ያ የመጨረሻይቱን ዓለም ቅጣት የሚፈራ የጌታውንም ችሮታ የሚከጅል ሲሆን በሌሊት ሰዓቶችም ሰጋጅና ቋሚ ሆኖ ለጌታው የሚገዛ ሰው (እንደ ተስፋ ቢሱ ከሓዲ ነውን? በለው።) «እነዚያ የሚያውቁና እነዚያ የማያውቁ ይስተካከላሉን?» በላቸው:: የሚገሰፁት ባለ አእምሮዎች ብቻ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) (ጌታችሁ) «እናንተ ያመናችሁ ባሮቼ ሆይ! ጌታችሁን ፍሩ፡፡ ለነዚያ በዚህች በቅርቢቱ ዓለም መልካም ለሠሩት መልካም ምንዳ አላቸው፡፡ የአላህ ምድርም ሰፊ ናት፤ (ብትቸገሩ ተሰደዱ)፡፡ ታጋሾቹ ምንዳቸውን የሚሰጡት ያለግምት ነው» (ይላል) በላቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) በል: «እኔ አላህን ሃይማኖትን ለእርሱ ያጠራሁ ሆኜ እንድገዛው ታዘዝኩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 12, '12. «የሙስሊሞች መጀመሪያ እንድሆን ታዘዝኩ» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ ከጌታዬ ባምጽ የታላቁን ቀን ቅጣት እፈራለሁ» በል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 14, '14. (መልዕክተኛችን ሙሐመድ ሆይ!) (እንዲህ) በል: «አላህን ሃይማኖቴን ለእርሱ ያጠራሁ ሆኜ እገዛዋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 15, '15. «ከእርሱ ሌላ የሻችሁትን ተገዙ:: ከሳሪዎች ማለት እነዚያ በትንሳኤ ቀን ነፍሶቻቸውንና ቤተሰቦቻቸውን ያከሰሩ ናቸው። ሰዎች ሆይ! አስተዉሉ:: ግልጽ ከሳራ ማለት ይህ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 16, '16. ለእነርሱ ከበላያቸው ከእሳት የሆኑ ድርብርብ ጥላዎች አሏቸው:: ከስራቸዉም እንዲሁ:: ይህ አላህ ባሮቹን እንዲጠነቀቁ በእርሱ ያስፈራራበታል:: ባሮቼ ሆይ! ስለዚህ ፍሩኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም ጣዖታትን ከመገዛት የራቁ እና ወደ አላህ የዞሩ ሁሉ ለእነርሱ ታላቅ ብስራት አላቸው። ስለዚህ ባሮቼን አብስር፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 18, '18. እነዚያን ንግግርን የሚያዳምጡትንና መልካምን የሚከተሉትን (ባሮቼን አብስር)፤ እነዚያ አላህ ወደ ቀናው መንገድ የመራቸው ናቸው። እነዚያም እነርሱ ባለ አእምሮዎቹ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 19, '19. በእርሱ ላይ የቅጣት ቃል የተረጋገጠችበትን (ትመራዋለህን?) አንተ በእሳት ውስጥ ያለን ታድናለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 20, '20. ግን እነዚያ ጌታቸውን የፈሩ፤ ለእነርሱም ከበላያቸው የታነጹ ሰገነቶች ያሏቸው ሰገነቶች ከስሮቻቸውም ወንዞች የሚፈሱባቸው የሆኑ አሏቸው:: (ይህንን) አላህ ቃል ገባላቸው፤ አላህም ቃሉን አያፈርስም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ከሰማይ ውሃን እንዳወረደና በምድር ውስጥ ምንጮች አድርጎ እንዳስገባው አላየህምን? ከዚያም በእርሱ ብዙ አይነቶች የሆኑ የተለያዩ አዝመራዎችን ያወጣበታል:: ከዚያም ይደርቃል:: ገርጥቶም ታየዋለህ:: ከዚያ ስብርብር ያደርገዋል፤ በዚህ ውስጥ ለባለ አእምሮዎች ግሳፄ አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 22, '22. አላህ ደረቱን ለእስልምና ያሰፋለትና እርሱም ከጌታው ዘንድ በብርሃን ላይ የሆነ ሰው (ልቡ እንደ ደረቀ ሰው ነውን?) ልቦቻቸዉም ከአላህ መወሳት ለደረቁ ሰዎች ወየውላቸው፤ እነዚያ በግልጽ መሳሳት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 23, '23. አላህ ከዜና ሁሉ መልካምን ተመሳሳይ ተደጋጋሚ የሆነን መጽሐፍ (ቁርኣንን) አወረደ:: ከእርሱ ግሳፄ የእነዚያ ጌታቸውን የሚፈሩት ሰዎች ቆዳዎች ይኮማተራሉ:: ከዚያም ቆዳዎቻቸውና ልቦቻቸው ወደ አላህ ተስፋ ማስታወስ ይለዝባሉ:: ይህ የአላህ መምሪያ ነው፤ በእርሱ የሚሻዉን ሰው ይመራበታል። አላህም የሚያጠመውን ሰው ለእርሱ ምንም አቅኝ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 24, '24. በትንሳኤ ቀን ክፉን ቅጣት በፊቱ የሚመክት ሰው (ከቅጣቱ እንደዳነው ነውን?) ለበዳዮችም «ትሰሩት የነበራችሁን ቅጣትን ቅመሱ» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 25, '25. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱ በፊት የነበሩት አስተባበሉ:: ቅጣቱም ከማያውቁት በኩል መጣባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 26, '26. አላህም በቅርቢቱ ሕይወት ውርደትን አቀመሳቸው:: የመጨረሻይቱም ዓለም ቅጣት በጣም ትልቅ ነው:: የሚያውቁ ቢሆኑ ኖሮ አያስተባብሉም ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 27, '27. በዚህም ቁርኣን ውስጥ ለሰዎች ይገሰጹ ዘንድ ከየምሳሌው ሁሉ በእርግጥ አብራራን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 28, '28. መዛባት የሌለበት ዐረብኛ ቁርኣን ሲሆን (አብራራነው):: ሊጠነቀቁ ይከጀላልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 29, '29. አላህ በእርሱ ተጨቃጫቂዎች የሆኑ ተጋሪዎች ያሉትን ባሪያና ለአንድ ሰው ብቻ ንጹህ የሆነን ባሪያ ለሚያጋራና በአንድነት ለሚያምን ሰው ምሳሌ አደረገ። በምሳሌ ይስተካካላሉን? ምስጋና ሁሉ ለአላህ ይገባው:: በእውነቱ አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተም ሟች ነህ፤ እነርሱም ሟቾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 31, '31 ከዚያም እናንተ በትንሳኤ ቀን እጌታችሁ ዘንድ ትከራከራላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 32, '32. በአላህ ላይም ከዋሸ እውነቱንም በመጣለት ጊዜ ካስተባበለ ሰው ይበልጥ በዳይ ማን ነው? በገሀነም ውስጥ ለከሓዲያን መኖሪያ የለምን? (አለ እንጂ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 33, '33. ያም በእውነት የመጣውና በእርሱ ያመነዉም እነዚያ እነርሱ አላህን ፈሪዎቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 34, '34. ለእነርሱም በጌታቸው ዘንድ የሚሹት (የሚፈልጉት) ሁሉ አላቸው:: ይህ የበጎ አድራጊዎች ምንዳ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 35, '35. አላህ ያንን በስህተት የሰሩትን መጥፎ ስራ ከእነርሱ ሊሰርዝላቸውና በዚያም ይሰሩት በነበሩት መልካም ስራ ምንዳቸውን ሊመነዳቸው ይህንን አደረገ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 36, '36. (መልዕክተኛችን ሙሐመድ ሆይ!) በእነዚያ ከእርሱ ሌላ በሆኑትም ጣኦታት ያስፈራሩሀል፤ አላህ ለባሪያው በቂ አይደለምን? አላህ የሚያጠመውን ለእርሱ ምንም አቅኝ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 37, '37. አላህ የሚያቀናውንም ለእርሱ ምንም አጥማሚ የለዉም:: አላህ አሸናፊውና የመበቀል ባለቤት አይደለምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 38, '38. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰማያትንና ምድርን የፈጠረ ማን እንደሆነ ብትጠይቃቸው «አላህ ነው» ይሉሃል:: «ከአላህ ሌላ የምትገዟቸውን ጣዖታት አያችሁን? እስቲ ንገሩኝ:: አላህ በጉዳት ቢፈልገኝ እነርሱ ጉዳቱን ገላጮች ናቸውን? ወይስ በችሮታው ቢፈልገኝ እነርሱም ችሮታውን አጋጆች ናቸውን?» በላቸው:: «አላህ በቂዬ ነው:: በእርሱ ላይ ተመኪዎች ይመካሉ» በል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 39, '39. (መልዕክተኛችን ሙሐመድ ሆይ!) በላቸውም: «ህዝቦቼ ሆይ! ባላችሁበት ሁኔታ ላይ ሁናችሁ ስሩ:: እኔም ባለሁበት ሁኔታ ላይ ሁኜ ሰሪ ነኝና:: ወደ ፊትም ትክክለኛው የቱ እንደነበር ታውቃላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 40, '40. «ያንን የሚያሳፍረው ቅጣት የሚመጣበትንና በእርሱ ላይ ዘውታሪ ቅጣት የሚሰፍርበትን ማንነት ታውቃላቸሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ መጽሐፉን ባንተ ላይ ለሰዎች ጥቅም በእውነት አወረድነው:: እናም በሱ የተመራ ሰው ሁሉ ፋይዳው ለነፍሱ ነው:: የጠመመም ሰው ጉዳቱ ለራሱ ነው የሚጠመው:: አንተም ታስገድዳቸው ዘንድ በእነርሱ ላይ ጠባቂ አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 42, '42. አላህ ነፍሶችን በሞታቸው ጊዜ ይወስዳል:: ያችንም ያልሞተችውን ነፍስ በእንቅልፈ ጊዜ ይወስዳታል:: ከዚያም ያችን ሞትን የፈረደባትን ነፍስ ይይዛታል:: ሌላይቱን ደግሞ እስከተወሰነ ጊዜ ድረስ ይለቃታል:: በዚህ ውስጥ ለሚያስተነትኑ ህዝቦች ሁሉ አያሌ ተአምራት አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቁንም ቁረይሾች ከአላህ ሌላ አማላጆችን ያዙ። «እነርሱ ምንም የማይችሉና ምንም የማያውቁ ቢሆኑም ታመልኳቸዋላችሁን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 44, '44. «ምልጃ ሁሉም የአላህ ብቻ ነው:: የሰማያትና የምድር ስልጣንም የእርሱ ብቻ ነው:: ከዚያም ወደ እርሱ ትመለሳላችሁ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 45, '45. አላህ ብቻዉን በተወሳ ጊዜ የእነዚያ በመጨረሻይቱ ዓለም የማያምኑት ሰዎች ልቦች ይሸማቀቃሉ (ይደነብራሉ) እነዚያ ከእርሱ ሌላ የሆኑት ጣዖታት በተወሱ ጊዜ ደግሞ እነርሱ ወዲያውኑ ይደሰታሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰማያትንና ምድርን የፈጠርክ ሩቁንም ቅርቡንም አዋቂ የሆንከው አላህ ሆይ! አንተ በባሮችህ መካከል በዚያም ይለያዩበት በነበሩት ነገር ትፈርዳለህ» በል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 47, '47. ለነዚያም ለበደሉት በምድር ያለው ሁሉ መላዉም ከእርሱ ጋር መሰሉም ቢኖራቸው ኖሮ በትንሳኤ ቀን ከቅጣቱ ክፋት የተነሳ በእርሱ ነፍሶቻቸውን በተበዡበት ነበር:: ለእነርሱም ከአላህ ዘንድ ያስቡት ያልነበሩት ሁሉ ይገለጽላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 48, '48. ለእነርሱም የሰሯቸው መጥፎዎቹ ይገልጹላቸዋል:: በእነርሱም ላይ በእርሱ ያላግጡበት የነበሩት ቅጣት ይሰፍርባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 49, '49. ሰውም ጉዳት ባገኘው ጊዜ ይጠራናል:: ከዚያም ከእኛ የሆነውን ጸጋ በሰጠነው ጊዜ «እርሱን የተሰጠሁት በእውቀቴ ብቻ ነው።» ይላል:: ይልቁንም እርሷ (ጸጋይቱ) መፈተኛ ናት:: ግን አብዛሀኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 50, '50. እነዚያ ከእነርሱ በፊት የነበሩት ህዝቦች ይችኑ ቃል በእርግጥ ብለዋታል:: ይሰሩት የነበሩትም ነገር ከእነርሱ አልጠቀማቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 51, '51. የሰሯቸዉም መጥፎዎች ቅጣት አገኛቸው:: ከእነዚህም እነዚያ የበደሉት የሰሯቸውን መጥፎዎች ፍዳ በእርግጥ ይነካቸዋል:: እነርሱም አምላጮች አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 52, '52. አላህ ሲሳዩን ለሚሻው ሰው የሚያሰፋ፤ ለሚሻው ሰው የሚያጠብም መሆኑን አያውቁምን? በዚህ ውስጥ ለሚያምኑት ህዝቦች ሁሉ አያሌ ግሳጼዎች አሉበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 53, '53. (መልዕክተኛችን ሙሐመድ ሆይ!) በላቸው «እናንተ በነፍሶቻችሁ ላይ ድንበር ያለፋችሁ ባሮቼ ሆይ! ከአላህ እዝነት ተስፋ አትቁረጡ:: አላህ ኃጢአቶችን ሁሉ ይምራልና:: እነሆ እርሱ መሀሪዉና አዛኙ ነውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 54, '54. (ሰዎች ሆይ!) ቅጣቱ ወደ እናንተ ከመምጣቱና ከዚያም የማትረዱ ከመሆናችሁ በፊት ወደ ጌታችሁ (በመጸጸት) ተመለሱ:: ለእርሱም ታዘዙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 55, '55. እናንተ የማታውቁ ስትሆኑ ቅጣቱ በድንገት ሳይመጣባችሁ በፊት ከጌታችሁ ወደ እናንተ የተወረደውን መልካሙን መጽሐፍ ተከተሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 56, '56. የካደች ነፍስ ሁሉ «እኔ ከሚሳለቁት የነበርኩ ስሆን በአላህ በኩል ባጓደልኩት ዋ! ጸጸቴ!» የምትል እንዳትሆን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 57, '57. ወይም «አላህ በመራኝ ኖሮ ከሚጠነቀቁት ሰዎች እሆን ነበር።» የምትል እንዳትሆን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 58, '58. ወይም ቅጣቱን በምታይ ጊዜ «ለእኔ ወደ ምድረ አለም አንድ ጊዜ የመመለስ ዕድል በኖረኝና ከበጎ አድራጊዎች በሆንኩ።» የምትል ከመሆኗ በፊት መልካሙን ተከተሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 59, '59. የለም ተመርተሃል:: አንቀፆቼ በእርግጥ መጥተውሃል:: በእነርሱም አስተባብለሃል፤ ኮርተሃልም:: ከከሓዲያንም ሆነሃል (ይባላል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 60, '60. (መልዕክተኛችን ሙሐመድ ሆይ!) በትንሳኤ ቀንም እነዚያን በአላህ ላይ የዋሹትን ፊቶቻቸው የጠቆሩ ሆነው ታያቸዋለህ:: በገሀነም ውስጥ ለትዕቢተኞች መኖሪያ የለምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 61, '61. እነዚያም የተጠነቀቁትን በማግኛቸው ስፍራ ሆነው አላህ ያድናቸዋል፤ ክፉ ነገር አይነካቸዉም:: እነርሱም አያዝኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 62, '62. አላህ የነገሩ ሁሉ ፈጣሪ ነው:: እርሱም በነገሩ ሁሉ ላይ አስተናባሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 63, '63. የሰማያትና የምድር (ድልብ) መከፈቻዎች የእርሱ ብቻ ናቸው:: እነዚያም በአላህ አናቅጽ የካዱት እነዚያ እነርሱ ከሳሪዎቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 64, '64. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ መሃይማን ሆይ! ከአላህ ሌላን እንድንገዛ ታዙኛላቸሁን?» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 65, '65. (መልዕክተኛችን ሙሐመድ ሆይ!) ብታጋራ ስራህ በእርግጥ ይታበሳል:: በእርግጥም ከከሓዲያን ትሆናለህ በማለት ወደ አንተና እነዚያ ካንተ በፊት ወደ ነበሩት ሰዎች በእርግጥ ተወርዷል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 66, '66. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቅ አላህን ብቻ ተገዛም:: ከአመስጋኞችም ሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 67, '67. አላህንም በትንሳኤው ቀን ምድርን በመላ ጭብጡ ስትሆንና ሰማያትም በቀኝ እጁ የሚጠቀለሉ ሲሆኑ ከእርሱ ጋር ሌላን በማጋራታቸው ተገቢ ክብሩን አላከበሩትም:: ከሚያጋሩት ሁሉ ጠራ። ላቀም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 68, '68. በቀንዱም ይነፋል:: በሰማያት ውስጥ ያለው ፍጡርና በምድርም ውስጥ ያለው ፍጡር ሁሉ አላህ የሻው ሲቀር በድንጋጤ ይሞታል:: ከዚያም በእርሱ ሌላ መነፋት ይነፋል:: ወዲያውኑም እነርሱ የሚሰራባቸውን የሚጠባበቁ ሆነው ቋሚዎች ይሆናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 69, '69. ምድርም በጌታዋ ብርሃን ታበራለች፤ መጽሐፉም ይቀርባል:: ነብያትና ምስክሮችም ይመጣሉ:: በመካከላቸዉም በእውነት ይፈረዳል:: እነርሱም አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 70, '70. ነፍስም ሁሉ የሰራቸውን ስራ ትሞላለች (ትሰፍራለች):: እርሱም የሚሰሩትን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 71, '71. እነዚያ በአላህ የካዱትም የተከፋፈሉ ቡድኖች ሆነው ወደ ገሀነም ይነዳሉ፤ በመጧትም ጊዜ በሮቿ ይከፈታሉ:: ወደሷ በመጡም ጊዜ ዘበኞቿ «ከእናንተ የሆኑ የጌታችሁን አናቅጽ በእናንተ ላይ የሚያነቡላችሁ የዚህንም ቀን መገናኘት የሚያስጠነቅቋችሁ መልዕክተኞች አልመጧችሁምን ነበርን?» ይሏቸዋል፤ «የለም መጥተውልናል። ግን የቅጣቲቱ ቃል በከሓዲያን ላይ ተረጋገጠች።» (ይላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 72, '72. «የገሀነምን በሮች በውስጧ ዘወታሪዎች ስትሆኑ ግቡ የትዕቢተኞችም መኖሪያ ምን ትከፋ!» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 73, '73. እነዚያም ጌታቸውን የፈሩት የተከፋፈሉ ቡድኖች ሆነው ወደ ገነት ይነዳሉ:: በመጧትም ጊዜ ደጃፎቿ የተከፈቱ ሲሆኑ ዘበኞቿም ለእነርሱ «ሰላም በእናንተ ላይ ይሁን ተዋባችሁ፤ ዘወታሪዎች ሆናችሁ ግቧት።» ይሏቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 74, '74. «ምስጋና ሁሉ ለአላህ ለዚያ የተስፋ ቃሉን ለሞላልን፤ የገነትንም ምድር በምንሻው ስፍራ የምንሰፍር ስንሆን ላወረሰን ይገባው።» ይላሉ። የሰሪዎችም ምንዳ ምን ያምር!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (39, 75, '75. (መልዕክተኛችን ሙሐመድ ሆይ!) መላዕክትንም በጌታቸው ምስጋና ቀላቅለው የሚያጠሩ ሲሆኑ በአርሹ ዙሪያ ከባቢዎች ሆነው ታያለህ፡፡ በመካከላቸውም እውነት ይፈረዳል። ይባላልም፤ «ምስጋና ሁሉ ለዓለማት ጌታ ለሆነው ለአላህ ብቻ ይገባው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 1, '1. ሓ፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 2, '2. የመጽሐፉን መውረድ አሸናፊው አዋቂው ከሆነው ከአላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 3, '3. ኃጢአት መሀሪና ጸጸትን ተቀባይ፤ ቅጣተ ብርቱ፤ የልግስና ባለቤት ከሆነው አላህ ብቻ የተወረደ ነው:: ከእርሱ በስተቀር (እውነተኛ) አምላክ የለም:: መመለሻዉም ወደ እርሱ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 4, '4. በአላህ አንቀጾች እነዚያ የካዱት ቢኾኑ እንጅ ማንም (በመዝለፍ) አይከራከርም፡፡ በያገሮችም ውስጥ መዘዋወራቸው አይሸንግልህ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 5, '5. ከእነርሱ በፊት የኑህ ህዝቦች ከኋላቸዉም አህዛቦች አስተባበሉ:: ህዝቦችም ሁሉ መልዕክተኛቸውን ሊይዙ አሰቡ፤ በውሸትም በእርሱ እውነትን ሊያጠፉበት ተከራከሩ:: ያዝኳቸዉም። ታዲያ ቅጣቴ እንዴት ነበር?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 6, '6. ልክ እንደዚሁም የጌታህ ቃል በእነዚያ በአላህ በካዱት ላይ እነርሱ የእሳት ጓዶች ናቸው ማለት ተረጋገጠች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ዐርሹን የሚሸከሙት እነዚያም በዙሪያው ያሉት በጌታቸው ምስጋና ያወድሳሉ፤ በእርሱም ያምናሉ። ለነዚያ ላመኑትም (እንዲህ እያሉ) ምህረትን ይለምኑላቸዋል: «ጌታችን ሆይ! ነገሩን ሁሉ በእዝነትና በእውቀት ከበሃል፤ ስለዚህ ለእነዚያ ለተጸጸቱት መንገድህንም ለተከተሉት ምህረት አድርግላቸው፤ የእሳትንም ቅጣት ጠብቃቸው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 8, '8. «ጌታችን ሆይ! እነርሱም ከአባቶቻቸውና ከሚስቶቻቸዉም ከዝርዮቻቸዉም የበጀውን ሁሉ እነዚያንም ቃል የገባህላቸውን የመኖሪያ ገነቶች አስገባቸው፤ አንተ አሸናፊው ጥበበኛው ነህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 9, '9. «ከቅጣቶችም ጠብቃቸው፤ በዚያ ቀንም የምትጠብቀውን በእርግጥ አዘንክለት:: ይህም እርሱ ታላቅ ማግኘት ነው::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 10, '10. እነዚያ በአላህ የካዱት ሰዎች «ወደ እምነት በምትጠሩና በምትክዱ ጊዜ አላህ (እናንተን) መጥላቱ ነፍሶቻችሁን (ዛሬ) ከመጥላታችሁ የበለጠ ነው።» በማለት ይጠራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 11, '11. «ጌታችን ሆይ! ሁለትን ሞት አሞትከን:: ሁለትንም ሕይወት ህያው አደረግከን:: በኃጢአቶቻችንም መሰከርን። ታዲያ (ከእሳት) ወደ መውጣት መንገድ አለን?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 12, '12. (ከሀዲያን ሆይ!) «ይሃችሁ እነሆ አላህ ብቻውን በተጠራ ጊዜ ስለ ካዳችሁ በእርሱም ተጋሪ ቢደረግ የምታምኑ ስለሆናችሁ ነው:: ስለዚህ ፍርዱ ከፍተኛ ታላቅ ለሆነው አላህ ብቻ ነው::» (ይባላሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 13, '13. (ሰዎች ሆይ!) እርሱ ያ ለአምላክነቱ ምልክቶችን የሚያሳያችሁ፤ ለእናንተም ከሰማይ ሲሳይን የሚያወርድላችሁ ነው:: ወደርሱም የሚመለስ ሰው ቢሆን እንጂ ሌላው አይገሰጽም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 14, '14. አላህንም ከሓዲያን ቢጠሉም (እንኳ) ሃይማኖትን ለእርሱ አጥሪዎች ሆናችሁ ተገዙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 15, '15. እርሱ ደረጃዎችን ከፍ አድራጊ የዐርሹ ባለቤት ነው:: የመገናኛውን ቀን ያስፈራራ ዘንድ ከባሮቹ በሚሻው ሰው ላይ ከትዕዛዙ ራዕይን ያወርዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 16, '16. እነርሱ ከመቃብር በሚወጡበት ቀን ከእነርሱ ምንም ነገር በአላህ ላይ አይደበቅም:: «ንግስናው ዛሬ ለማን ነው?» ይባላል:: «ለአሸናፊው ለአንዱ አላህ ብቻ ነው» ይባላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 17, '17. «ዛሬ ነፍስ ሁሉ በሰራችው ስራ ትመነዳለች፤ ዛሬ በደል የለም:: አላህ በእርግጥ ምርመራው ፈጣን ነው።» ይባላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 18, '18. (መልዕክተኛችን ሙሐመድ ሆይ!) ቅርቢቱንም የትንሳኤ ቀን ልቦች ጭንቀትን የተሞሉ ሆነው ላንቃዎች ዘንድ የሚደርሱበትን ጊዜ አስጠንቅቃቸው:: ለበዳዮች ምንም ወዳጅና ተሰሚ አማላጅ የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 19, '19. አላህ የዓይኖችን ክዳት ልቦችም የሚደብቁትን ሁሉ ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 20, '20. አላህም በእውነት ይፈርዳል:: እነዚያም ከእርሱ ሌላ የሚገዟቸው በምንም አይፈርዱም:: አላህ እርሱ ሰሚው ተመልካቹ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 21, '21. የእነዚያን ከእነርሱ በፊት የነበሩትን ህዝቦች ፍፃሜ እንዴት እንደነበረ ይመለከቱ ዘንድ በምድር ላይ አይሄዱምን? በሀይልና በምድር ላይ በተዋቸው ምልክቶች ከእነርሱም ይበልጥ የበረቱ ነበሩ:: አላህም በኃጢአቶቻቸው ያዛቸው። ለእነርሱም ከአላህ ቅጣት ምንም ጠባቂ አልነበራቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 22, '22. ይህ (መያዝ) እነርሱ መልዕክተኞቻቸው በተዓምራት ይመጡባቸው ስለ ነበሩና ስለካዱ ነው:: አላህም ያዛቸው። እርሱ ኃያል፤ ቅጣተ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 23, '23. ሙሳንም በተዓምራቶቻችንና በግልጽ ማስረጃ በእርግጥ ላክነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 24, '24. ወደ ፈርዖን ወደ ሃማን እና ወደ ቃሩንም ላክነው:: «ድግምተኛ እና ውሸታም ነው» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 25, '25. ከእኛ ዘንድ እውነትን ይዞ በመጣላቸውም ጊዜ: «የእነዚያን ከእርሱ ጋር ያመኑት ሰዎች ወንድ ልጆች ግደሉ፤ ሴቶቻቸውንም አስቀሩ።» አሉ፤ የከሓዲያንም ተንኮል በጥፋት ውስጥ እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 26, '26. ፈርዖንም «ተዉኝ፤ ሙሳን ልግደል:: (ያድነው እንደሆነም) ጌታውን ይጥራ:: እኔ ሃይማኖታችሁን ሊለውጥ ወይም በምድር ውስጥ ጥፋትን ሊያሰራጭ እፈራለሁና።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 27, '27. ሙሳም «እኔ በምርመራው ቀን ከማያምን ትዕቢተኛ ሁሉ በጌታየና በጌታችሁ ተጠበቅሁ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 28, '28. ከፈርዖን ቤተሰቦች አንድ እምነቱን የሚደብቅ ምዕመን ሰውም አለ: «ሰውዬው ከጌታችሁ በታዐምራቶች በእርግጥ የመጣላችሁ ሲሆን ''ጌታየ አላህ ነው'' ስለሚል ትገድሉታላችሁን? ውሸታምም ቢሆን ውሸቱ በእርሱ ላይ ነው:: እውነተኛ ቢሆን ግን የእዚያ የሚያስፈራራችሁ ከፊሉ ያገኛችኋል:: አላህ እርሱ ያንን ድንበር አላፊና ውሸታም የሆነውን አይመራምና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 29, '29. «ወገኖቼ ሆይ! በምድር ላይ አሸናፊዎች ስትሆኑ ዛሬ መንግስትነት የእናንተ ነው:: ታዲያ ከአላህ ቅጣት ቢመጣብን የሚያድነን ማን ነው?» አለ:: ፈርዖንም «የማየውን እንጂ አላመላክታችሁም፤ ቅኑን መንገድ እንጂ አልመራችሁም።» አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 30, '30. ያ ያመነው ሰውም አለ፡- «እኔ በእናንተ ላይ የአህዛብን ቀን ብጤ እፈራላችኋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 31, '31. «የ(ነብዩ) ኑህን ህዝቦች የዓድንና የሰሙድም የእነዚያን ከኋላቸው የነበሩትንም ህዝቦች ልማድ ብጤ እፈራላችኋለሁ:: አላህም ለባሮቹ መበደል የሚሻ ጌታ (ሆኖ) አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 32, '32. «ወገኖቼ ሆይ! እኔ በእናንተ ላይ የመጠራሪያን ቀን እፈራለሁ::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 33, '33. ወደ ኋላ ዞራችሁ በምትሸሹበት ቀን፤ ለእናንተ ከአላህ ቅጣት ምንም ጠባቂ የላችሁም፤ አላህም የሚያጠመው ሰው ለእርሱ ምንም አቅኚ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 34, '34. ዩሱፍም ከዚህ በፊት ግልጽ ማስረጃዎችን በእርግጥ አመጣላችሁ:: ከዚያ እርሱ ካመጣላችሁ ነገር ከመጠራጠር አልተወገዳችሁም:: በጠፋም ጊዜ «አላህ ከእርሱ በኋላ መልዕክተኛን በጭራሽ አይልክም» አላችሁ፤ አላህ እንደዚሁ ድንበር አላፊ ተጠራጣሪ የሆነን ሰው ያሳስታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 35, '35. እነዚያ የመጣላቸው አስረጅ ሳይኖር በአላህ ታዓምራቶች የሚከራከሩ (ክርክራቸው) አላህ ዘንድና እነዚያም ያመኑት ዘንድ መጠላቱ በጣም ተለቀ:: እንደዚሁ አላህ በኩሩ ጨካኝ ልብ ሁሉ ላይ ያትማል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 36, '36. ፈርዖንም አለ፡- «ሃማን ሆይ! መንገዶችን እደርስ ዘንድ ረዥም ህንፃን ካብልኝ። የሰማያትን መንገዶች እደርስ ዘንድ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 37, '37. «የሰማያትን መንገዶች እደርስ ዘንድ። ከዚያ ወደ ሙሳ አምላክ እመለከት ዘንድ። እኔም ውሸታም ነው ብዬ እጠረጥረዋለሁ።» አለ:: ልክ እንደዚሁ ለፈርዖን መጥፎ ስራው ተሸለመለት:: ከቅኑ መንገድም ታገደ:: የፈርዖንም ተንኮል በከሳራ ውስጥ እንጂ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 38, '38. ያ ያመነውም አለ፡- «ወገኖቼ ሆይ! ተከተሉኝ ቀጥታውን መንገድ እመራችኋለሁና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 39, '39. «ወገኖቼ ሆይ! ይህች ቅርቢቱ ሕይወት የጥቂት ቀናት መጣቀሚያ ብቻ ናት፤ መጨረሻይቱ ዓለም ግን እርሷ ትክክለኛ መርጊያ አገር ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 40, '40. «መጥፎን የሰራ ሰው ብጤዋን እንጅ አይመነዳም:: እርሱ ምዕመን ሆኖ ከወንድ ወይም ከሴት በጎ የሰራም እነዚያ ገነትን ይገባሉ:: በእርሷ ውስጥም ያለ ቁጥር ይለገሳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 41, '41. «ወገኖቼ ሆይ! ወደ መዳን የምጠራችሁ ስሆን ወደ እሳትም የምትጠሩኝ ስትሆኑ ለእኔ ምን አለኝ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 42, '42. « (እናንተ) በአላህ ልክድና በእርሱም ለእኔ እውቀቱ የሌለኝ ነገር በእርሱ እንዳጋራ ትጠሩኛላችሁ! እኔ አሸናፊና መሀሪ ወደ ሆነው አላህ እጠራችኋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 43, '43. «በእርግጥ ወደ እርሱ የምትጠሩኝ ጣዖት ለእርሱ በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም ተሰሚ ጥሪ የለዉም። መመለሻችንም እርግጥ ወደ አላህ ብቻ ነው:: ወሰን አላፊዎችም እነርሱ የእሳት ጓዶች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 44, '44. «ወደ ፊትም ለእናንተ የምላችሁን ምክር (ቅጣትን በምታዩ ጊዜ) ታስታውሱታላችሁ:: ነገሬንም ሁሉ ወደ አላህ አስጠጋለሁ:: አላህ ባሮቹን ተመልካች ነውና።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 45, '45. ካሴሯቸዉም መጥፎዎች አላህ ጠበቀው፡፡ በፈርዖን ቤተሰቦችም ላይ ክፉ ቅጣት ሰፈረባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 46, '46. እሳት በጧትና በማታ በእርሷ ላይ ይቀርባሉ፡፡ ሰዓቲቱም በምትሆንበት ቀን «የፈርዖንን ቤተሰቦች ብርቱን ቅጣት ገሀነምን አስገቧቸው» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 47, '47. በእሳት ውስጥ የሚከራከሩበትን ጊዜ አስታውስ: ደካማዎቹም ለነዚያ ለኮሩት «እኛ ለእናንተ ተከታዮች ነበርንና እናንተ አሁን ከእሳት ከፊሉን ከእኛ ላይ ገፍታሪዎች ናችሁን?» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 48, '48. እነዚያም የኮሩት «እኛ ሁላችንም በውስጧ ነን አላህ በባሮቹ መካከል በእርግጥ ፈርዷል» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 49, '49. እነዚያም በእሳት ውስጥ ያሉት ለገሀነም ዘበኞች «ጌታችሁን ለምኑልን፤ ከእኛ ላይ ከቅጣቱ ለአንድም ቀን ያቃልልን።» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 50, '50. ዘበኞቹም «መልዕክተኞቻችሁ በታዐምራቶች ይመጡላችሁ አልነበሩምን?» ይላሉ ከሓዲያንም «እንዴታ መጥተውልናል እንጅ፤ ግን አሰተባበልናቸው።» ይላሉ። «እንግዲያውስ ጸልዩ የከሓዲያንም ጸሎት በከንቱ እንጂ አይደለም።» ይሏቸዋል፡:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 51, '51. እኛ መልክተኞቻችንን እነዚያንም ያመኑትን በቅርቢቱ ሕይወትም ምስክሮች በሚቆሙበት ቀንም በእርግጥ እንረዳለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 52, '52. በደለኞችን ምክንያታቸው በማይጠቅማቸው ቀን እንረዳለን። ለነርሱም ርግማን አላቸው:: ለነርሱም መጥፎ አገር አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 53, '53. ሙሳንም መምሪያ በእርግጥ ሰጠነው:: የኢስራኢልንም ልጆች መጽሐፍን አወረስናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 54, '54. ለባለ አእምሮዎች መሪና ገሳጭ ሲሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 55, '55. (መልዕክተኛችን ሙሐመድ ሆይ!) ታገስም የአላህ ተስፋ እውነት ነውና፤ ለስህተትህም ምህረትን ለምን፤ ከቀትር በኋላም በማለዳም ጌታህን ከማመስገን ጋር አጥራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 56, '56. እነዚያ የመጣላቸው አስረጅ ሳይኖር በአላህ አናቅጽ የሚከራከሩ በልቦቻቸው ውስጥ እነርሱ ደራሾች ያልሆኑት ኩራት ብቻ እንጂ ምንም የለም:: በአላህም ብቻ ተጠበቅ፤ እነሆ እርሱ ሁሉን ሰሚና ሁሉን ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 57, '57. ሰማያትንና ምድርን መፍጠር ሰዎችን ከመፍጠር ይልቅ ታላቅ ነው:: ግን አብዛሀኞቹ ሰዎች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 58, '58. ዐይነ ስዉርና የሚያይ እነዚያም አምነው መልካሞችን የሰሩትና መጥፎ ሰሪው አይስተካከሉም። በጣም ጥቂትን ብቻ ትገስፃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 59, '59. ሰዓቲቱ በእርግጥ መጪ ናት:: በእርሷ ጥርጥር የለም:: ግን አብዛሀኞቹ ሰዎች አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 60, '60. (ባሮቼ ሆይ!) ጌታችሁም አለ: «ለምኑኝ እቀበላችኋለሁና። እነዚያ እኔን ከመገዛት የሚኮሩት ተዋራጆች ሆነው ገሀነም በእርግጥ ይገባሉ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 61, '61. አላህ ያ ለእናንተ ሌሊትን በውስጡ ልታርፉበት ጨለማ፤ ቀንኑ ደግሞ ልትሰሩበት የሚያሳይ ብርሃን ያደረገላችሁ ነው:: አላህ በሰዎች ላይ በእርግጥ የታላቅ ችሮታ ባለቤት ነውና:: ግን አብዛሀኞቹ ሰዎች አያመሰግኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 62, '62. ይሃችሁ ጌታችሁ አላህ ነው:: የነገሩ ሁሉ ፈጣሪ ነው:: ከእርሱ ሌላ አምላክ የለም:: ታዲያ ከእምነት ወዴት ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 63, '63. ልክ እንደዚሁ እነዚያ በአላህ አናቅጽ ይክዱ የነበሩት ከእምነት ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 64, '64. (ሰዎች ሆይ)! አላህ ያ ምድርን መርጊያ ሰማይንም ጣሪያ ያደረገላችሁ ነው፡፡ የቀረፃችሁም ቅርፃችሁንም ያሳመረ፤ ከጣፋጭ ሲሳዮችም የሰጣችሁ ነው:: ይሃችሁ ጌታችሁ አላህ ነው። የዓለማትም ጌታ አላህ ላቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 65, '65. እርሱ ብቻ ሁል ጊዜ ህያው ነው:: ከእርሱ ሌላ አምላክ የለም:: ሃይማኖትንም ለርሱ ያጠራችሁ ስትሆኑ «ምስጋና ሁሉ ለዓለማት ጌታ ለሆነው ለአላህ ብቻ ይገባው›› የምትሉ ሆናችሁ ተገዙት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 66, '66. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ ከጌታዬ አስረጂዎች በመጡልኝ ጊዜ እነዚያን ከአላህ ሌላ የምትገዙዋቸውን እንዳልገዛ ተከልክያለሁ፤ ለዓለማትም ጌታ ብቻም እንድገዛ ታዝዣለሁ።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 67, '67. (ሰዎች ሆይ!) እርሱ (አላህ) ያ ከዐፈር ከዚያም ከፍትወት ጠብታ ከዚያም ከረጋ ደም የፈጠራችሁ ነው:: ከዚያም ህፃን አድርጎ ያወጣችኋል:: ከዚያም ጥንካሬያችሁን ትደርሱ ዘንድ፤ ከዚያም ሽማግሌዎች ትሆኑ ዘንድ ያቆያችኋል:: ከናንተም ውስጥ ከዚህ በፊት የሚሞት አለ:: ይህንንም ያደረገው ኑራችሁ የተወሰነ ጊዜም ልትደርሱ ታውቁም ዘንድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 68, '68. እርሱ (አላህ) ያ ህያው የሚያደርግና የሚያሞትም ነው:: አንዳችን ነገር በሻም ጊዜ ለእርሱ የሚለው ሁን ነው ወዲያዉም ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 69, '69.(መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ በአላህ አናቅጽ ወደሚከራከሩት ከእምነት እንዴት እንደሚመለሱ አታይምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 70, '70. ወደ እነዚያ በመጽሐፉ በዚያም መልዕክተኞቻችንን በእርሱ በላክንበት ወዳስተባበሉበት አታይምን? ወደፊትም ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 71, '71. እንዘዝላዎቹና ሰንሰለቶቹ በአንገቶቻቸው ላይ በተደረጉ ጊዜ (በእርሷ) ይጎተታሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 72, '72. በገሀነም ውስጥ ይጎተታሉ፤ ከዚያም በእሳት ውስጥ ይማገዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 73, '73. ከዚያም ለእነርሱ ይባላሉ፡- «(በአላህ) ታጋሯቸው የነበራችሁት የታሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 74, '74. ከአላህ ሌላ የምታጋሩዋቸው (የት አሉ)?» «ከእኛ ተሰወሩብን፤ ከቶ ከዚህ በፊት ምንም የምንገዛ አልነበርንም» ይላሉ:: ልክ እንደዚሁ አላህ ካሐዲያንን ያሳስታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 75, '75. «ይህ (ቅጣታችሁ) ያላአግባብ በምድር ውስጥ ትደሰቱ በነበራችሁትና ትንበጣረሩ በነበራችሁት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 76, '76. የገሀነምን በሮች ውስጧ ዘወታሪዎች ስትሆኑ ግቡ።» (ይባላሉ)። የትዕቢተኞችም መኖሪያ (ገሀነም) ምን ትከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 77, '77. (መልዕክተኛችን ሙሐመድ ሆይ!) ታገስም:: የአላህ ቀጠሮ እውነት ነውና፤ የዚያንም የምናስፈራራቸውን ከፊሉን በህይወትህ ብናሳይህ መልካም ነው:: ወይም ሳናሳይህ ብንገድልህ ወደ እኛ ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 78, '78. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊትም መልዕክተኞችን በእርግጥ ልከናል። ከእነርሱ ባንተ ላይ የተረክንልህ አለ:: ከእነርሱም ባንተ ላይ ያልተረክነውም አለ:: ለማንኛዉም መልዕክተኛ በአላህ ፈቃድ ካልሆነ በስተቀር ተዓምርን ሊያመጣ አይገባዉም:: የአላህም ትዕዛዝ በመጣ ጊዜ በእውነት ይፈረዳል:: እዚያ ዘንድም አጥፊዎች ይከስራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 79, '79. አላህ ያ ለእናንተ ግመልን ከብትንና ፍየልን ከእርሷ ከፊሏን ልትጋልቡ የፈጠረላችሁ ነውና:: ከእርሷም ትበላላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 80, '80. ለእናተም በርሷ ውስጥ ጥቅሞች አሏችሁ:: በእርሷም ላይ ዕቃን በመጫን በልቦቻችሁ ያሰባችሁትን ጉዳይ ትደርሱ ዘንድ ፈጠረላችሁ። በእርሷም ላይ በመርከቦችም ላይ ትሳፈራላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 81, '81. ተዓምራትንም ያሳያችኋል:: ታዲያ ከአላህ ተዓምራት መካከል የትኛውን ትክዳላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 82, '82. የእነዚያም ከእነርሱ በፊት የነበሩትን ህዝቦች ፍፃሜ እንዴት እንደነበር ይመለከቱ ዘንድ በምድር ላይ አይሄዱምን ? ከእነርሱ ይበልጥ ብዙዎች በኃይልና በምድር ላይ በተዋቸው ምልክቶችም በጣም ብርቱዎች ነበሩ:: ያም ይሰሩት የነበሩት ለእነርሱ ምንም አልጠቀማቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 83, '83. መልዕክተኞቻቸዉም ተዓምራትን ባመጡላችሁ ጊዜ እነርሱ ዘንድ ባለው ዕውቀት ተደሰቱ:: በእርሱ ይሳለቁበት የነበሩት ቅጣትም በእነርሱ ላይ ሰፈረባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 84, '84. ብርቱ ቅጣታችንንም ባዩ ጊዜ «በአላህ አንድነት አምነናል በእርሱም እናጋራ በነበርነው ጣዖታት ክደናል» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (40, 85, '85. ብርቱ ቅጣታችንን ባዩ ጊዜ ማመናቸዉም የሚጠቅማቸው አልነበረም:: የአላህን ደንብ ያችን በባሮቹ ውስጥ ያለፈችውን ተጠንቀቁ:: በዚያ ጊዜም ከሓዲያን ከሰሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 1, '1. ሓ፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 2, '2. ይህ ቁርኣን እጅግ በጣም ሩህሩህና በጣም አዛኝ ከሆነው ጌታ ከአላህ የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 3, '3. አናቅጾቹ የተብራሩ የሆነ መጽሐፍ ነው:: ዐረበኛ ቁርኣን ሲሆን ለሚያውቁ ሕዝቦች የተብራራ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 4, '4. አብሳሪና አስፈራሪ ሲሆን ተወረደ። አብዛኞቻቸዉም ተውት:: እነርሱም አይሰሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 5, '5. አሉም፡- «ልቦቻችን ከዚያ ወደርሱ ከምትጠራን እምነት በመሸፈኛዎች ውስጥ ናቸው:: በጆሮቻችንም ላይ ድንቁርና አለ:: በእኛና በአንተ መካከል ግርዶሽ አለ:: በሃይማኖትህ ስራ እኛም ሰሪዎች ነንና::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) እንዲህ በላቸው «እኔ አምላካችሁ አንድ አምላክ ብቻ ነው:: ወደ እርሱም ቀጥ በሉ:: ምህረትንም ለምኑት በማለት ወደ እኔ ይወርድልኛል እንጂ መሰላችሁ ሰው ብቻ ነኝ።» ለአጋሪዎችም ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 7, '7. ለእነዚያ ዘካን ለማይሰጡ እነርሱም በመጨረሻይቱ ዓለም እነርሱ ከሓዲያን ለሆኑት (ወዮላቸው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 8, '8. እነዚያ ያመኑትና በጎ ስራዎችንም የሰሩት ሁሉ ለእነርሱ የማይቋረጥ ምንዳ አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 9, '9. (መልዕክተኛችን ሙሐመድ ሆይ !) «እናንተ በዚያ ምድርን በሁለት ቀናት ውስጥ በፈጠረው አምላክ በእርግጥ ትክዳላችሁን? ለእርሱም ባላንጣዎች ታደርጋላችሁን? ያ (ይህንን የሰራው) የዓለማቱ ጌታ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 10, '10. በእርሷም ከበላይዋ የረጉ ጋራዎችን አደረገ:: በእርሷም በረከትን አደረገ:: በውስጧም ምግቦችዋን (ካለፉት ሁለት ቀኖች ጋር) በአራት ቀናት ውስጥ ለጠያቂዎች ትክክል ሲሆን ወሰነ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 11, '11. ከዚያም እርሷ ጭስ ሆና ሳለች ወደ ሰማይ አሰበ:: ለእርሷም ለምድርም «ወዳችሁም ሆነ ጠልታችሁ ኑ» አላቸው:: «ታዛዦች ሆነን መጣን» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 12, '12. በሁለት ቀናትም ውስጥ ሰባት ሰማያት አደረጋቸው:: በሰማያትም ሁሉ ነገሯን አዘጋጀ:: ቅርቢቱንም ሰማይ በመብራቶች አጌጥን:: ከሰይጣናት መጠበቅንም ጠበቅናት:: ይህ የአሸናፊውና የአዋቂው ጌታ ውሳኔ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 13, '13. ከእምነት እምቢ ቢሉም (እንዲህ) በላቸው: «እንደ ዓድና ሰሙድ መቅሰፍት ብጤ የሆነን መቅሰፍት አስጠነቅቄያችኋለሁ።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 14, '14. መልዕክተኞቹ «አላህን እንጂ ሌላን አትገዙ» በማለት ከስተፊታቸዉም ከበስተኋላቸዉም በመጡባቸው ጊዜ «ጌታችን በሻ ኖሮ መላዕክትን ባወረደ ነበር:: ስለዚህ እኛ በዚህ በእርሱ በተላካችሁት ከሓዲያን ነን።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 15, '15. የዓድም ነገዶችም በምድር ላይ ያለ አግባብ ኮሩ፤ ከእኛ ይበልጥ በኃይል ብርቱ ማን ነው ? አሉም ያ የፈጠራቸው አላህ እርሱ በኃይል ከእነርሱ ይበልጥ የበረታ መሆኑን አያምኑምን? በታዐምራታችንም ይክዱ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 16, '16. በቅርቢቱ ሕይወት የውርደትን ቅጣት ልናቀምሳቸዉም በእነርሱ ላይ የሚንሻሻ ብርቱ ነፋስ መናጢዎች በሆኑ ቀናት ውስጥ ላክንባቸው:: የመጨረሻይቱም ዓለም ስቃይ በጣም አዋራጅ ነው:: እነርሱም አይረዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 17, '17. ሰሙዶችማ ወደ ቀናው መንገድ መራናቸው:: እነርሱ ግን እውርነትን ከቅንነት ይልቅ መረጡ:: ይሰሩትም በነበሩት ኃጢአት አዋራጅ የሆነችው የመብረቅ ቅጣት ያዘቻቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 18, '18. እነዚያንም ያመኑትንና ይጠነቀቁ የነበሩትንም አዳንናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 19, '19. የአላህም ጠላቶች ወደ እሳት የሚሰበሰቡበትን ቀን አስታውሱ:: የሚከመከሙ ሆነውም ይነዳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 20, '20. በመጧትም ጊዜ ጀሮዎቻቸው፤ ዓይኖቻቸውና ቆዳዎቻቸዉም ይሰሩት በነበረ ነገር በእነርሱ ላይ ይመሰክሩባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 21, '21. ለቆዳዎቻቸዉም «በእኛ ላይ ለምን መሰከራችሁብን?» ይላሉ። «ያ ሁሉን ነገር ያናገረው አላህ አናገረን:: እርሱም (ነው) በመጀመሪያ ጊዜ የፈጠራችሁ። ወደ እርሱም ብቻ ትመለሳላችሁ» ይሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 22, '22. ጆሮዎቻችሁ ዓይኖቻችሁና ቆዳዎቻችሁ በእናንተ ላይ እንዳይመሰክሩባችሁ የምትደበቁባቸው አልነበራችሁም:: ግን አላህ ከምትሰሩት ብዙውን አያውቅም ብላችሁ ጠረጠራችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 23, '23. ይህም ለጌታችሁ የጠረጣችሁት ጥርጣሬያችሁ አጠፋችሁ:: ከከሳሪዎችም ሆናችሁ ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 24, '24. ቢታገሱም እሳት ለእነርሱ መኖሪያቸው ናት:: ወደ ሚወዱት መመለስንም ቢጠይቁ እነርሱ ተቀባይ የሚያገኙ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 25, '25. ለእነርሱም ቁራኛዎችን አዘጋጀንላቸው:: በፊታቸውን ያለውንና በኋላቸው ያለውንም ሁሉ ለእነርሱ ሸለሙላቸው:: ከአጋንንትና ከሰዉም ከእነርሱ በፊት በእርግጥ ካለፉት ህዝቦች ጋር ሆነው ቃሉ በእነርሱ ላይ ተረጋገጠባቸው:: እነርሱ በእርግጥ ከሳሪዎች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 26, '26. እነዚያም «በአላህ የካዱት ሰዎች ይህንን ቁርኣን አታዳምጡ ታሸንፉም ዘንድ ሲነበብም ተንጫጩበት።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 27, '27. እነዚያንም በአላህ የካዱትን ብርቱ ቅጣት እናቀምሳቸዋለን:: የእነዚያንም ይሰሩት የነበሩትን መጥፎውን ፍዳ እንመነዳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 28, '28. ይህ የአላህ ጠላቶች ፍዳ እሳት ነው:: በውስጧም ለእነርሱ የዘላለም መኖሪያ አገር አላቸው:: በአንቀፆቻቸን ይክዱ በነበሩት ምንዳ ይመነዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 29, '29. እነዚያም በአላህ የካዱት በእሳት ውስጥ ሆነው «ጌታችን ሆይ! እነዚያ ከአጋንንትና ከሰው ያሳሳቱንን አሳየን። ከታችኞች ይሆኑ ዘንድ ከጫማዎቻችን ስር እናደርጋቸዋለንና» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 30, '30. እነዚያ «ጌታችን አላህ ነው» ያሉና ከዚያም ቀጥ ያሉ። እንዲህ እያሉ መላዕክቱ በነርሱ ላይ ይወርዳሉ: «አትፍሩ አትዘኑ:: በዚያችም ተስፋ ቃል ትደረግላቸሁ:: በነበራችሁት ገነት ተበሰሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 31, '31. «እኛ በቅርቢቱም ሕይወት በመጨረሻይቱም ረዳቶቻችሁ ነን! ለእናተም በእርሷ ውስጥ ነፍሶቻችሁ የሚሹት ሁሉ አላችሁ:: ለእናንተም በእርሷ ውስጥ የምታዙት ሁሉ አለላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 32, '32. «መሀሪና አዛኝ ከሆነው አላህ መስተንግዶ ሲሆን» ይባላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 33, '33. ወደ አላህ ከጠራንና መልካምንም ከሰራ፤ «እኔ ከሙስሊሞች ነኝ» ካለው ሰው ይበልጥ ቃሉ ያማረ ማን ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 34, '34. መልካሚቱና ክፉይቱም ጸባይ አይስተካሉም በዚያች እርሷ መልካም በሆነችው ጸባይ መጥፎይቱን ገፍትር፤ ያን ጊዜ ባንተና በእርሱ መካከል ጠብ ያለው ሰው እርሱ ልክ እንደ ወዳጅ ዘመድ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 35, '35. ይህችንም ጸባይ እነዚያን የታገሱት እንጂ ሌላው አያገኛትም:: የትልቅም እድል ባለቤት እንጂ ማንም አያገኛትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 36, '36. ከሰይጣን ጉትጎታ ቢያገኝህ (ከመልካም ጸባይ ቢመልስህ) በአላህ ተጠበቅ እነሆ እርሱ ሁሉን ሰሚና ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 37, '37. ሌሊትና ቀንም ጸሀይና ጨረቃም ከምልክቶቹ ናቸው። ለጸሐይና ለጨረቃ አትስገዱ፤ ለዚያም ለፈጠራቸው አላህ ስገዱ:: እርሱን ብቻ የምትገዙ እንደሆናችሁ (ለሌላ አትስገዱ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 38, '38. ቢኮሩም እነዚያ በጌታህ ዘንድ ያሉት መላዕክት በቀንም በሌሊትም ለእርሱ ያወድሳሉ:: እነርሱም አይሰለቹም:: {1}', '{1} እዚህ የቲላዋ ሱጁድ ይደረጋል።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 39, '39. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ ምድርን ደረቅ ሆና ማየትህም ከምልክቶቹ ነው:: በእርሷም ላይ ውሃን ባወረድን ጊዜ በቡቃያዎችዋ ትላወሳለች፤ ትነፋለችም። ያ ህያው ያደረጋት ጌታ በእርግጥ ሙታንንም ህያው አድራጊ ነው:: እርሱ በነገሩ ሁሉ ቻይ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 40, '40. እነዚያ አናቅጻችንን የሚያጣምሙ በእኛ ላይ አይደበቁም:: (የሚያጣምም) በእሳት ውስጥ የሚጣለው ይበልጣልን? ወይስ በትንሳኤ ቀን ደህነኛ ሆኖ የሚመጣው? የሻችሁትን ስሩ:: ዋጋችሁን ታገላችሁ:: እርሱም (አላህ) የምትሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 41, '41. እነዚያ በቁርኣን እርሱ አሸናፊው መጽሐፍ ሲሆን በመጣላቸው ጊዜ የካዱ ሁሉ ጠፊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 42, '42. ከኋላዉም ከፊቱም ውሸት አይመጣበትም:: ጥበበኛ ምስጉን ከሆነው ጌታ የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) ካንተ በፊት ለነበሩት መልዕክተኞች የተባለው ቢጤ እንጂ ላንተ ሌላ አይባልም:: ጌታህ የምህረት ባለቤትና የአሳማሚ ቅጣትም ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) በአዕጀምኛ የሆነ ቁርኣን ባረግነው ኖሮ «አናቅጹ በምናውቀው ቋንቋ አይብራሩም ኖሯልን? (ቁርኣኑ) አዕጀምኛና (መልዕክተኛው) አረባዊ ይሆናልን?» ባሉ ነበር:: እርሱ ለእነዚያ በአላህ ላመኑት ሰዎች መመሪያና መፈወሻ ነው:: እነዚያም የማያምኑት በጆሮዎቻቸው ውስጥ ድንቁርና ነው (አይሰሙትም):: እርሱ በእነርሱ ላይ እውርነት ነው:: እነዚያ ከሩቅ ስፍራ እንደሚጠሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳንም መጽሐፍን በእርግጥ ሰጠነው። በእርሱም ተለያዩበት። ከጌታህም ያለፈች ቃል ባልነበረች ኖሮ በመካከላቸው በተፈረደ ነበር፤ እነርሱም በእርሱ አወላዋይ በሆነ ጥርጣሬ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) መልካምን የሰራ ለነፍሱ ነው:: ያጠፋም በእርሷው ላይ ነው:: ጌታህም ለባሮቹ በዳይ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 47, '47. የትንሳኤ መከሰቻ ሰዐቱን ማወቅ ወደ እርሱ ብቻ ይመለሳል:: ከፍሬዎችም ከሽፋኖቻቸው አይወጡም ከሴትም አንዲትም አታረግዝም፤ አትወልድምም በእውቀቱ ቢሆን እንጂ:: «ተጋሪዎቼ የት ናቸው?» በማለት በሚጠራቸው ቀንም ከእኛ ውስጥ («ተጋሪ አለህ» ብሎ) ምንም መስካሪ አለመኖሩን አምነናል» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 48, '48. ያም በፊት ይገዙት የነበሩት ጣዖት ከእነርሱ ይጠፋቸዋል:: ለእነርሱም ምንም መሸሻ የሌላቸው መሆኑን ያረጋግጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 49, '49. ሰው በጎ ነገርን ከመለመን አይሰለችም:: ክፋት ቢያገኘው (ግን) ወዲያውኑ በጣም ተስፋ ቆራጭ ተበሳጭ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 50, '50. ካገኘችዉም መከራ በኋላ ከእኛ የሆነን እዝነት ብናቀምሰው «ይህ ለእኔ በስራየ የተገባኝ ነው፤ ሰዓቲቱም መጪ ናት ብየ አላስብም። ወደ ጌታየ ብመለስ (እንኳ) ለእኔ እርሱ ዘንድ መልካሚቱ ገነት በእርግጥ አለችኝ» ይላል:: እነዚህም የካዱትን ስራዎቻቸውን በእርግጥ እንነግራቸዋለን:: ከበረታዉም ስቃይም በእርግጥ እናቀምሳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 51, '51. በሰዉም ላይ ጸጋችንን በለገስን ጊዜ ከማመስገን ይዞራል በጎኑም ይርቃል:: መከራም ባገኘው ጊዜ የብዙ ልመና ባለቤት ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) በላቸው: «እስቲ ንገሩኝ ቁርኣን ከአላህ ዘንድ ቢሆንና ከዚያም በእርሱ ብትክዱ፤ ከእውነት በራቀ ጭቅጭቅ ላይ ከሆነ ሰው ይበልጥ የተሳሳተ ማን ነው?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 53, '53. እርሱም (ቁርኣን) እውነት መሆኑ ለእነርሱ እስከሚገለጽላቸው ድረስ በአጽናፎችና በነፍሶቻቸዉም ውስጥ ያሉትን ታዐምራቶቻችንን በእርግጥ እናሳያቸዋለን:: ጌታህም እርሱ በነገሩ ሁሉ አዋቂ መሆኑ አይበቃቸዉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (41, 54, '54. (ሙስሊሞች ሆይ!) አስተውሉ! እነርሱ ከጌታቸው ጋር መገናኘትን በመጠራጠር ውስጥ ናቸው:: (ሙስሊሞች ሆይ!) አስተውሉ! እርሱ በነገሩ ሁሉ በእውቀቱ ከባቢ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 1, '1. ሓ፤ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 2, '2. ዐይን፤ ሲን፤ ቃፍ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁ በዚህ ምዕራፍ ውስጥ እንዳለው አሸናፊውና ጥበበኛው አላህ ወደ አንተ ያወርዳል:: ወደ እነዚያም ካንተ በፊት ወደ ነበሩት ህዝቦችም አውርዷል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 4, '4. በሰማያትና በምድር ዉስጥ ያለው ሁሉ የእርሱ ብቻ ነው:: እርሱም የበላዩ ታላቁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 5, '5. ከአላህ ፍራቻ የተነሳ ሰማያት ከበላያቸው ሊቀደዱ ይቀርባሉ፤ መላእክትም ጌታቸውን እያመሰገኑ ያጠራሉ:: በምድር ላለው ፍጡርም ምህረትን ይለምናሉ:: (ሙስሊሞች ሆይ!) አስተዉሉ:: መሀሪውና አዛኙ አላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 6, '6. እነዚያም ከእርሱ ሌላ ጣዖታትን ረዳቶች አድርገው የያዙ ሁሉ አላህ በእነርሱ ላይ ተጠባባቂ ነው:: አንተም በእነርሱ ላይ ሀላፊ አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁም የከተሞች እናት የሆነችውን የመካን ሰዎችና በአካባቢዋ ያሉትን ህዝቦች ልታስፈራራ የመሰብሰቢያውንም ቀን በእርሱ ጥርጣሬ የሌለበት ሲሆን ልታስጠነቅቅ በዐረበኛ ቋንቋ የሆነን ቁርኣንን ወደ አንተ አወረድን:: ከእነርሱም ከፊሉ በገነት ውስጥ ከፊሉም ደግሞ በእሳት ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 8, '8. አላህ በፈለገ ኖሮ ሰዎችን በአንድ ሃይማኖት ላይ የሆኑ አንድ ህዝብ ባደረጋቸው ነበር:: ግን የሚፈልገውን ሰው በእዝነቱ ውስጥ ያስገባዋል:: በዳዮች ሁሉ ምንም ወዳጅና ረዳት የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 9, '9. ከእርሱ ሌላ ረዳቶች ያዙን? (እነርሱ ረዳቶች አይደሉም) ትክክለኛ ረዳት አላህ ብቻ ነው:: እርሱ ሙታንን ህያው ያደርጋል:: እርሱም በሁሉም ነገር ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 10, '10. (ሰዎች ሆይ!) «ያ የተለያያችሁበት ነገር ሁሉ ፍርዱ ወደ አላህ ብቻ ነው:: እርሱ (አላህ) ጌታዬ ነው:: በእርሱ ላይ ተመካሁ:: ወደ እርሱም ብቻ እመለሳለሁ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 11, '11. ሰማያትንና ምድርን የፈጠረው አላህ ከነፍሶቻችሁ ሴቶችን ከቤት እንሰሳዎችም አይነቶችን (ወንዶችና ሴቶችን) ለእናንተ ፈጠረላችሁ:: በዚህ ድርጊቱም ያባዛችኋል:: የሚመስለው ምንም ነገር የለም:: እርሱ ሁሉን ነገር ሰሚና ሁሉን ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 12, '12. የሰማያትና የምድር (ድልቦች) መክፈቻዎች የእርሱ ብቻ ናቸው:: ሲሳይን ለሚፈልገው ሰው ያሰፋል:: ለሚፈልገዉም ያጠባል:: እርሱ ሁሉን ነገር አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 13, '13. (ሰዎች ሆይ!) ለእናንተ ከሃይማኖት ያንን በእርሱ ኑህን ያዘዘበትን ያንንም ወደ አንተ ያወረድነውን ያንንም ኢብራሂምን፤ ሙሳንና ዒሳንም በእርሱ ያዘዝንበት የሆነውን ሃይማኖትን በትክክል አቋቁሙ በእርሱም ላይ አትለያዩ በማለት ደነገገላችሁ::(መልዕክተኛችን ሙሐመድ ሆይ!) በአላህ አጋሪዎች ያ ወደ እርሱ የምትጠራቸው ነገር (ኢስላም) ከበዳቸው:: አላህ የሚፈልገውን ሰው ወደ እርሱ እምነት ይመርጣል:: የሚመለስንም ሰው ወደ እርሱ ይመራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 14, '14. (መልዕክተኛችን ሙሐመድ ሆይ!) የሃይማኖት ሰዎች እውቀት ከመጣላቸው በኋላ በመካከላቸው ባለ ወሰን አላፊነት እንጂ በሌላ አልተለያዩም:: እስከተወሰነ ጊዜ በማቆየት ከጌታህ ያለፈች ቃል ባልነበረች ኖሮ በእነርሱ መካከል አሁኑኑ በተፈረደ ነበር:: እነዚያም ከኋላቸው መጽሐፍን እንዲወርሱ የተደረጉት ከእርሱ በእርግጥ ባወላዋይ ጥርጣሬ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እዚህ መንገድም ጋኔንንና ሰዎችን ጥራ:: ልክ እንደታዘዝከዉም ቀጥ በል:: ዝንባሌያቸውን አትከተል:: «ከመጽሐፍም አላህ ባወረደው ሁሉ አመንኩ:: በመካከላችሁ በፍርድ ላስተካክልም ታዘዝኩ:: አላህ ጌታችን ጌታችሁም ነው:: ለእኛ ስራዎቻችን አሉን:: ለእናንተም እንዲሁ ስራዎቻችሁ አሏችሁ:: በእኛና በእናንተ መካከል ክርክር የለም:: አላህ በመካከላችን ይሰበስባል:: መመለሻው ወደ እርሱ ብቻ ነው።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 16, '16. እነዚያም በአላህ ሃይማኖት ተቀባይነት ካገኘ በኋላ የሚከራከሩት ሰዎች ማስረጃዎቻቸው በጌታቸው ዘንድ ብልሹ (ዉድቅ) ናቸው:: በእነርሱም ላይ የአላህ ቁጣ አለባቸው (ወደቀባቸው):: ለእነርሱም ብርቱ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 17, '17. አላህ ያ መጽሐፉን በእውነት ያወረደ ነው:: ሚዛንንም ልክ እንደዚሁ ያወረደ ነው:: ሰዓቲቱ ምን አልባት ቅርብ ብትሆንስ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 18, '18. እነዚያ በእርሷ የማያምኑት በእርሷ ያቻኩላሉ:: እነዚያ በአላህ ያመኑት ግን ከእርሷ ፈሪዎች ናቸው:: እርሷ እውነት መሆኗንም በትክክል ያውቃሉ:: (ሙስሊሞች ሆይ!) አስተውሉ:: እነዚያ በሰዓቲቱ የሚከራከሩ ሰዎች ሁሉ በእርግጥ ከእውነት በራቀ ስህተት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 19, '19. አላህ ለባሮቹ በጣም ሩህሩህ ነው:: ለሚፈልገው ሰውም ሁሉ በሰፊው ሲሳይን ይሰጣል:: እርሱም ብርቱዉ እና አሸናፊው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 20, '20. በስራው የኋለኛይቱን ዓለም አዝመራ የሚፈልግ ሰው ሁሉ ለእርሱ በአዝመራው ላይ ሌላን እንጨምርለታለን:: የቅርቢቱን ዓለም አዝመራ የሚፈልግ ሰው ግን በእርሷ የተወሰነለትን ብቻ እንሰጠዋለን:: ለእርሱም በኋለኛይቱ ዓለም ምንም ድርሻ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 21, '21. ከሓዲያን ከአላህ ያልተፈቀደውን ሃይማኖት የደነገጉ ተጋሪዎች ለእነርሱ አሏቸውን? የፍርዱ ቃል ባልነበረ ኖሮ በመካከላቸው ወዲያውኑ በተፈረደ ነበር:: በደለኞችም አሳማሚ ቅጣት በእርግጥ አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 22, '22. (መልዕክተኛችን ሙሐመድ ሆይ!) በደለኞችን በሰሩት ስራ ዋጋ በትንሳኤ ቀን ፈሪዎች ሆነው ታያቸዋለህ:: እርሱም በእነርሱ ላይ የማይቀር ወዳቂ ነው:: (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያም በአላህ ያመኑና መልካም ስራን የሰሩ ሁሉ በገነት ጨፌዎች ዉስጥ ናቸው:: ለእነርሱም በጌታቸው ዘንድ የሚፈልጉት ሁሉ አለላቸው:: ይህ ታላቅ ችሮታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 23, '23. (ይህ ታላቅ ችሮታ) ያ አላህ እነዚያን በትክክል ያመኑትንና መልካሞችን የሰሩት ባሮቹን የሚያበስርበት ነው::(መልዕክተኛችን ሙሐመድ ሆይ!) መልዕክቴን በማድረሴ ላይ የዝምድና ውዴታየን እንጂ ሌላ ዋጋ አልጠይቃችሁም በላቸው:: መልካም ስራ የሚሰራ ሰው ሁሉ ለእርሱ በእርሷ ላይ መልካምን ነገርን እንጨምርለታለን:: አላህ መሀሪ እና አመስጋኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቁንም «በአላህ ላይ ውሸትን ቀጠፈ» ይላሉን? አላህም ቢፈልግ በልብህ ላይ ያትማል:: አላህ ውሸትን ያብሳል:: እውነትንም በቃላቱ ያረጋግጣል:: እርሱ በይፋ የተነገሩት ቀርቶ በልቦች ውስጥ ያለውን ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 25, '25. እርሱም አላህ ያ ሁልጊዜም ከባሮቹ ንስሀን የሚቀበል ኃጢአቶችንም ይቅር የሚል የምትሰሩትንም ሁሉ የሚያውቅ ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 26, '26. እነዚያም በአላህ ያመኑትና መልካም ተግባሮችን የሰሩትን ልመናቸውን ይቀበላል:: ከችሮታዉም ይጨምርላቸዋል:: ከሓዲያንም ለእነርሱ ብርቱ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 27, '27. አላህም ለባሮቹ ሁሉ ሲሳይን በዘረጋ ኖሮ በምድር ውስጥ ሁሉም ወሰን ባለፉ ነበር:: ግን የሚፈልገውን በልክ ያወርዳል:: እርሱ በባሮቹ ውስጠ አዋቂ፤ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 28, '28. አላህ ያ ተስፋ ከቆረጡ በኋላ ዝናብን የሚያወርድ ችሮታውንም የሚዘረጋ ነው:: እርሱም ረዳቱና ምስጉኑ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 29, '29. ሰማያትንና ምድርን መፍጠሩ ከተንቀሳቃሽም በሁለቱ ውስጥ የበተነውን ፍጡር መፍጠሩ ከአስደናቂ ምልክቶቹ ከፊሎቹ ናቸው:: እርሱም በሚፈልግ ጊዜ እነርሱን በመሰብሰብ ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 30, '30. (ሰዎች ሆይ!) ማንኛዉም መከራ (ያገኛችሁ ነገር) እጆቻችሁ በሰሩት ኃጢአት ምክንያት ብቻ ነው:: ብዙውንም ይቅር ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 31, '31. (ሰዎች ሆይ!) እናንተ በምድር ውስጥ የምትሳኑን (አምላጮች) አይደላችሁም:: ለእናንተም ከአላህ ሌላ ወዳጅም ሆነ ረዳት ምንም የላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 32, '32. በባህር ላይ እንደ ጋራዎች ሆነው ተንሻላዮቹ መርከቦችም ከአስደናቂ ምልክቶቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 33, '33. ቢፈልግ ንፋሱን የረጋ ያደርገዋል:: ከዚያም መርከቦች በባህሩ ጀርባ ላይ የረጉ ይሆናሉ:: በዚህ ውስጥ በጣም ታጋሽ፤ አመስጋኝ ለሆኑ ሁሉ በእርግጥም ብዙ ተዓምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 34, '34. ወይም ተሳፋሪዎች በሰሩት ኃጢአት ምክንያት እነርሱን በባህሩ በማስመጥ ያጠፋቸዋል:: ከብዙ ጥፋቶችም ይቅርታ ያደርጋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 35, '35. ከእነርሱ መካከል እነዚያን በአናቅጻችን የሚከራከሩትን ሰዎች ለማወቅ (ያጠፋቸዋል):: ለእነርሱም ከእርሱ ሌላ ምንም መሸሻ የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 36, '36. (ሰዎች ሆይ!) የተሰጣችሁት ነገር ሁሉ የቅርቢቱ ሕይወት መጠቃቀሚያ ብቻ ነው:: በአላህ ዘንድ ያለው ምንዳ ግን ለእነዚያ በትክክል በእሱ ላመኑትና በጌታቸው ላይ ብቻ ለሚመኩት ሁሉ በላጭና ሁልጊዜ ነዋሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 37, '37. ለእነዚያም ታላላቅ ሃጢያቶችንና ዝሙትን የሚርቁ፤ በተቆጡም ጊዜ የሚምሩ ለሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 38, '38. ለእነዚያም የጌታቸውን ጥሪ ለተቀበሉት፤ ሶላትንም ላዘወተሩት፤ በነገራቸው ላይም በመካከላቸው መመካከር ልምዳቸው ለሆነው፤ ከሰጠናቸዉም ሲሳይ ለሚለግሱት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 39, '39. ለእነዚያም በደል በደረሰባቸው ጊዜ በመሰሉ የሚመልሱ ለሆኑት (በላጭና ነዋሪ ነው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 40, '40. የመጥፎ ነገሮች ሁሉ ዋጋው ተመሳሳዩ መጥፎ ነው:: ይቅር ያለና ያሳመረ ሰው ደግሞ ምንዳው በአላህ ላይ ብቻ ነው:: እርሱ በደለኞችን አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 41, '41. እነዚያ ከተበደሉ በኋላ በመሰሉ የተበቀሉ በእነርሱ ላይ ምንም የወቀሳ መንገድ የለባቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 42, '42. የወቀሳ መንገዱ በእነዚያ ሰዎችን በሚበድሉት እና በምድር ውስጥም ያለ ህግ ወሰንን በሚያልፉት ሰዎች ላይ ብቻ ነው:: እነዚያ ለእነርሱ አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 43, '43. የታገሰና ምህረት ያደረገ፤ ይህ ተግባር በእጅጉን ተፈላጊ ከሆኑ ነገሮች አንዱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ የሚያጠመውን ሰው ከእርሱ ማጥመም በኋላ ለእርሱ ምንም ወዳጅ የለዉም:: በደለኞችም ቅጣትን ባዩ ጊዜ «ለመመለስ መንገድ አለን?» የሚሉ ሲሆኑ ታያቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ከውርደት የተነሳ ፈሪዎች ሆነው በዓይን ስርቆት ወደ እሳት እያስተዋሉ በእርሷ ላይ የሚቀርቡ ሁነው ታያቸዋለህ:: እነዚያም በአላህ ያመኑት፡- «በእርግጥ ከሳሪዎች ማለት እነዚያ ነፍሶቻቸውንና ቤተሰቦቻቸውን በትንሳኤ ቀን የከሰሩት ናቸው» ይላሉ:: (ሙስሊሞች ሆይ!) አስተዉሉ:: በደለኞች በእርግጥ ዘወታሪ ስቃይ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 46, '46. ለእነርሱም ከአላህ ሌላ የሚረዷቸው ረዳቶች ምንም አልነበሯቸዉም:: አላህ የሚያጠመው ሰው ሁሉ ለእርሱ ወደ እውነት የሚመለስበት ምንም መንገድ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 47, '47. ያ ከአላህ ከመጣ መላሽ የሌለለው ቀን ከመምጣቱ በፊት ለጌታችሁ ታዘዙ:: በዚያ ቀን ለእናንተ ምንም መጠጊያም ሆነ መቃወም የላችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) ቢዞሩም (ወቀሳ የለብህም::) በእነርሱ ላይ ጠባቂ አድረገን አላክንህምና:: ባንተ ላይ ማድረስ እንጂ ሌላ የለብህም:: እኛም ሰውን ከእኛ የሆነን ጸጋ ባቀመስነው ጊዜ በእርሷ ይደሰታል:: እጆቻቸው ባስቀደሙት ኃጢአት ምክንያት መከራ ብትደርስባቸው ደግሞ ተስፋ ይቆርጣሉ:: ሰው በጣም ውለታን ከሓዲ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 49, '49. የሰማያትና የምድር ንግስና የአላህ ብቻ ነው:: የሚፈልገውን ይፈጥራል:: ለሚፈልገው ሴቶችን ልጆች ይሰጣል:: ለሚፈልገዉም ወንዶችን ይሰጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 50, '50. ወይም ወንዶችንና ሴቶችን አድርጎ ያጠናዳቸዋል:: የሚፈልገውንም መካን ያደርገዋል:: እርሱ ሁሉን አዋቂና ሁሉን ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 51, '51. ሰውን አላህ በራዕይ ወይም ከግርዶሹ ወዲያ ወይም መልዕከተኛን በመላክና በፈቃዱ የሚፈልገውን ነገር የሚያወርድለት ቢሆን እንጂ በገሀድ ሊያናግረው ተገቢው አይደለም:: እርሱ የበላይና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 52, '52. (መልዕክተኛችን ሙሐመድ ሆይ!) ልክ እንደዚሁ ወደ አንተ ከትዕዛዛችን ሲሆን ሂወት የሆነውን (ቁርአን) አወረድነው:: መጽሐፉም ሆነ እምነቱ ምን እንደሆነ የምታውቅ አልነበርክም:: ግን ቁርኣንን ከባሮቻችን የምንሻውን ሰው በእርሱ የምንመራበት ብርሃን አደረግነው:: አንተም ወደ ቀጥተኛው መንገድ በእርግጥ ትመራለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (42, 53, '53. ወደዚያ በሰማያትና በምድር ያለው ሁሉ የእርሱ ወደ ሆነው ወደ አላህ መንገድ (ትመራለህ):: ሙስሊሞች ሆይ! አስተውሉ:: ነገሮች ሁሉ ወደ አላህ ብቻ ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 1, '1. ሓ፤ሚም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 2, '2. ገላጭ በሆነው መጽሐፍ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 3, '3. እኛ ታውቁ ዘንድ ቁርኣንን በዐረብኛ ቋንቋ አደረግነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 4, '4. እርሱም እኛ ዘንድ በመጽሐፎቹ እናት (መሰረት) ውስጥ ያለ፤ እርግጥ ከፍተኛ ማዕረግ ያለውና በጥበብ የተሞላ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 5, '5. ድንበር አላፊዎች ህዝቦች በመሆናችሁ ምክኒያት ቁርኣኑን ከማውረድ ከናንተ ማገድን እናግዳለንን? (አናግድም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 6, '6. በፊተኞቹም ህዝቦች ውስጥ ከነብያት መካከል ብዙን ልከናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 7, '7. ከነብይም አንድንም የሚመጣላቸው አልነበረም በእርሱ ይቀልዱበት (ያፌዙበት) የነበሩ ቢሆን እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 8, '8. ከእነርሱም በሀይል ይበልጥ የበረቱትን አጥፍተናል:: የፊተኞቹም አጠፋፍ ምሳሌ አልፏል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 9, '9. (መልዕክተኛችን ሙሐመድ ሆይ!) «ሰማያትንና ምድርን ማን ፈጠራቸው?» ብለህ ብትጠይቃቸው «ያ ሁሉን አሸናፊዉና ሁሉን አዋቂው ጌታ ነው የፈጠራቸው» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 10, '10. አላህ ያ ምድርን ለእናንተ ምንጣፍ ያደረገላችሁ በእርሷም ውስጥ ትመሩ ዘንድ ለእናንተ መንገዶችን ያደረገላችሁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 11, '11. ያም ከሰማይ ውሃን በልክ ያወረደላችሁ ነው። በእርሱም (በውሀው) የሞተችውን አገር ህያው አደረግን:: (ሰዎች ሆይ!) ልክ እንደዚሁ ከየመቃብሮቻችሁ ትወጣለችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 12, '12. ያም የፍጡር ዓይነቶችን ሁሉ (ጥንድ) አድርጎ የፈጠረ ለእናንተም ከመርከቦችና ከቤት እንሰሳዎች መካከል የምትጋልቧቸውን ያደረገላችሁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 13, '13. በጀርባዎቻቸው ላይ እንድትደላደሉ ከዚያም በእርሱ ላይ በተደላደላችሁ ጊዜ የጌታችሁን ጸጋ እንድታስታውሱ፤ እንድትሉም «ይህንን የማንችለው ስንሆን ለእኛ ያገራልን ጌታ ጥራት ተገባው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 14, '14. እኛም በእርግጥ ወደ ጌታችን አላህ ተመላሾች ነን» እንድትሉ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 15, '15. ከባሮቹም መካከል ለእርሱ ክፋይን (የተወሰነን) ብቻ አደረጉለት:: ሰው በእርግጥ ግልጽ ከሓዲ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 16, '16. አላህ ከሚፈጥረው ፍጡር መካከል ሴቶች ልጆችን ብቻ ለይቶ የራሱ ልጅ አድርጎ ያዘን? (ከዚያም) እናንተን በወንዶች ልጆች መረጣችሁን? (አይደለም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 17, '17. አንዳቸዉም ለአር-ረህማን ምሳሌ ባደረገው ነገር (በሴት ልጅ) በተበሰረ ጊዜ በቁጭት የተሞላ ሆኖ ፊቱ ጥቁር ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 18, '18. በጌጣጌጥ ተከልሶ እንዲያድግ የሚደረገውን ክፍል እርሱም ከደካማነቱ የተነሳ በክርክር የማያብራራውን ፍጡር ለይተው ለአላህ ያደርጋሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 19, '19. እነዚያን የአር-ረሕማን ቅን ባሮች የሆኑትን መላእክትንም ሴቶች አደረጓቸው። ለመሆኑ እነርሱ መላእክት ሲፈጠሩ አብረው ነበሩን? መመስከራቸው በእርግጥ ትፃፋለች:: ስለ እርሷም ይጠየቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 20, '20. «አር-ረሕማንም በፈለገ ኖሮ ባልተገዛናቸው ነበር» አሉ። ለእነርሱም በዚህ ምንም እውቀት የላቸዉም፤ እነርሱ የሚዋሹ ህዝቦች እንጂ ሌላ አይደሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 21, '21. ከእርሱ (ቁርኣን) በፊት መጽሐፍን ሰጠናቸውና እሱን አጥብቀው የያዙ ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 22, '22. ከቶውንም «እኛ አባቶቻችንን (በዚሁ) ሃይማኖት ላይ አገኘናቸው:: እኛም በፈለጎቻቸው ላይ ተመሪዎች ነን» አሉ እንጂ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 23, '23. (መልዕክተኛችን ሙሐመድ ሆይ!) ነገሩ ልክ እንደዚህ ነው:: ከበፊትም በማንኛይቱም ከተማ ውስጥ አስፈራሪን አላክንም ቅምጥሎቿ «እኛ አባቶቻችንን (በዚሁ) ሃይማኖት ላይ አገኘን:: እኛም ፈለጎቻቸውን ተከታዩች ነን» ያሉ ቢሆኑ እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 24, '24. አስፈራሪው «አባቶቻችሁን በእርሱ ላይ ካገኛችሁበት ይበልጥ ቀጥተኛው ሃይማኖት ባመጣላችሁም?» ቢላቸው «እኛ በተላካችሁበት ነገር (ሀይማኖት) ከሓዲያን ነን» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 25, '25. ከእነርሱም ተበቀልን:: (መልዕክተኛችን ሙሐመድ ሆይ!) ያስተባባዮች መጨረሻ እንዴት እንደነበር ተመልከት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 26, '26. (መልዕክተኛችን ሙሐመድ ሆይ!) ኢብራሂምም ለአባቱና ለህዝቦቹ «እኔ ከምትገዙት ጣኦታት ሁሉ ንጹህ ነኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 27, '27. «ከዚያ ከፈጠረኝ በስተቀር ማንንም አልገዛም:: አላህንማ በእርግጥ ይመራኛልና ብቻውን አመልከዋለሁ» ባለ ጊዜ የነበረውን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 28, '28. በዝርዮቹም ውስጥ ወደ አላህ ይመለሱ ዘንድ (በአንድ አምላክ) ማመንን ቀሪ ቃል አደረጋት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቁን እነዚህን ቁረይሾችንም አባቶቻቸውንም ቁርኣንንና ገላጭ መልዕክተኛ እስካመጣላቸው ድረስ አጣቀምኳቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 30, '30. እውነት በመጣላቸው ጊዜም «ይህ ያመጣሀው ድግምት ነው። እኛም በእርሱ ከሓዲያን ነን።» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 31, '31. ይህም «ቁርኣን በሁለቱ ከተሞች በአንዱ በሚኖር ታላቅ ሰው ላይ አይወርድም ኖሯልን?» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 32, '32. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱ የጌታህን ስጦታ ያከፋፍላሉን? እኛ በቅርቢቱ ሕይወት እንኳን ኑሯቸውን በመካከላቸው አከፋፍለናል:: ከፊላቸዉም ከፊሉን አገልጋይ አድርጎ ይይዝ ዘንድ ከፊላቸውን ከከፊሉ በላይ (በሀብት) አበለጥን:: (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህም ጸጋ ገነት ከሚሰበስቡት ሀብት በላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 33, '33. ሰዎችም (በክህደት) ላይ አንድ ህዝብ የሚሆኑ ባልነበሩ ኖሮ በአል-ረህማን ለሚክዱ ሰዎች ሁሉ (በዚህች ዓለም) ለቤቶቻቸው የብር ጣራዎች፤ የሚወጣጡባቸውም የብር መሰላሎች፤ ባደረግንላቸው ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 34, '34. ለቤቶቻቸው የብር በሮች፤ ለሚደገፉባቸዉም የብር አልጋዎች፤(ባደረግንላቸው ነበር)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 35, '35. የወርቅ ጌጥንም ባደረግንላቸው ነበር። ይህም ሁሉ የቅርቢቱ ሕይወት መጣቀሚያ እንጂ ሌላ አይደለም:: ጠፊ ነው:: መጨረሻይቱም አገር በጌታህ ዘንድ ለጥንቁቆች ብቻ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 36, '36. (በቁርኣን ከተወሳው) ከአል-ረሕማን ግሳጼ የሚደናበርም ሰው ለእርሱ ሰይጣንን እናስጠጋለን። ስለዚህ እርሱ ለእርሱ የሁልግዜ ቁራኛው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 37, '37. እነርሱም (ተደናባሪዎቹ) ሁሉ ወደ ትክክለኛው መንገድ ተመሪዎች መሆናቸውን የሚያስቡ ሲሆኑ እነርሱ (ሰይጣናት) ከቀጥተኛው መንገድ በእርግጥ ያግዷቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 38, '38. (በትንሳኤ) ወደ እኛ በመጣ ጊዜ «(ቁራኛዬ ሆይ) በእኔና ባንተ መካከል የምስራቅና የምዕራብ ርቀት በኖረ ዋ ምኞቴ! ምን የከፋ ቁራኛ ነህ።» ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 39, '39. (ከሓዲያን ሆይ!) ስለ በደላችሁም ዛሬ እናንተ በቅጣት ተጋሪዎች መሆናችሁ አይጠቅማችሁም (ይባላሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 40, '40. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ ደንቆሮዎችን ታሰማለህን? ወይስ እውሮችንና በግልጽ ጥመት ውስጥ የሆኑ ሰዎችን ትመራለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተም ቅጣታቸውን ሳታይ ብንወስድህ እኛ ከእነርሱ ተበቃዮች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 42, '42. ወይም ያንን የቀጠርናቸውን ብናሳይህ እኛ በእነርሱ ቅጣት ላይ ቻይዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 43, '43. (መልዕክተኛችን ሙሐመድ ሆይ!) ያንንም ወደ አንተ የተወረደልህን አጥብቀህ ያዝ:: አንተ በቀጥተኛው መንገድ ላይ ነህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱ (ቁርኣን) ላንተም ሆነ ለህዝቦችህ ታላቅ ክብር ነው:: ወደፊተም ከርሱ በእርግጥ ትጠየቃላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመልዕክተኞችም ካንተ በፊት የላክናቸው ከአር-ረሕማን ሌላ የሚገዙዋቸው የሆነን አማልክት አድርገን እንደሆነ (ተከታዮቻቸውን) ጠይቃቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳንም በተዓምራታችን ወደ ፈርዖንና ወደ ሹማምንቶቹ በእርግጥ ላክን:: «እኔ የዓለማቱ ጌታ መልዕክተኛ ነኝ» አላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 47, '47. በተዓምራታችን በመጣላቸው ጊዜም ወዲያውኑ እነርሱ በእርሷ ይስቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 48, '48. ከተዓምራት አንዲትንም እናሳያቸዉም እርሷ ከብጤዋ በጣም የበለጠች ብትሆን እንጅ። ከክህደታቸው ይመለሱም ዘንድ በቅጣት ያዝናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 49, '49. አንተ ድግምተኛ ሆይ! «ጌታህን አንተ ዘንድ ቃል በገባልህ ለእኛ ለምንልን እኛ (ቅጣቱን ቢያነሳልን) ተመሪዎች ነን» አሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 50, '50. ስቃዩን ከእነርሱ ላይ በገለጥንም ጊዜ ወዲያውኑ ቃልኪዳናቸውን ያፈርሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 51, '51. ፈርዖንም በህዝቦቹ ውስጥ ተጣራ። (እንዲህ) አለም: «ህዝቦቼ ሆይ! የሚስር (ግብጽ) ግዛት የእኔ አይደለምን? እነዚህም ጅረቶች ከስሬ የሚፈሱ ሲሆኑ የእኔ አይደሉምን? አትመለከቱምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 52, '52. «በእውነት እኔ ከዚያ ያ እርሱ ወራዳ ጉዳዩንም በደንብ ሊገልጽ የማይችል ከሆነው ሰው በላጭ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 53, '53. «እርሱ ላይ የወርቅ አንባሮች ለምን አልተጣሉበትም? ወይም መላዕክት ከእርሱ ጋር ተቆራኝተው ለምን አልመጡም?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 54, '54. ህዝቦቹንም አቄላቸው:: ታዘዙትም:: እነርሱ አመጸኞች ህዝቦች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 55, '55. ባስቆጡንም ጊዜ ከእነርሱ ተበቀልን:: ሁሉንም አሰመጥናቸውም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 56, '56. በጥፋት ቀዳሚዎችና ለኋለኞች መቀጣጫ ምሳሌም አደረግናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 57, '57. የመርየም ልጅ ዒሳ ምሳሌ በተደረገ ጊዜ ህዝቦችህ (ከሀዲያኑ) ወዲያውኑ ከእርሱ ሌሎችን ያግዳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 58, '58. «አማልክቶቻችን ይበልጣሉን? ወይስ እርሱ ይበልጣል?» አሉም:: ለክርክር እንጅ ላንተ (እርሱን) ምሳሌ አላደረጉትም:: በእውነት እነርሱ ክርክረ ብርቱ ህዝቦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 59, '59. እርሱ (ዒሳ) በእርሱ ላይ የለገስንለት ለኢስራኢል ልጆችም ተዐምር ያደረግነው አገልጋይ ባሪያችን እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 60, '60. ብንፈልግም ኖሮ በምድር ላይ በእናንተ ምትክ መላዕክትን ባደረግን ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 61, '61. (መልዕክተኛችን ሙሐመድ ሆይ!) «እርሱም (ዒሳ) ለስዓቲቱ ማወቂያ በእርግጥ ምልክት ነው:: በእርሷም አትጠራጠሩ:: ተከተሉኝም:: ይህ ቀጥተኛ መንገድ ነው» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 62, '62. ሰይጣንም አያግዳችሁ:: እርሱ ለእናንተ ግልጽ ጠላት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 63, '63. ዒሳ ግልፅ ተዓምራታችንን ይዞ በመጣ ጊዜ «በእርግጥ በጥበብ መጣሁላችሁ:: የዚያንም የምትለያዩበትን ጉዳይ ከፊሉን ለእናንተ ላብራራላችሁ መጣሁ:: እናም አላህን ፍሩ:: ታዘዙኝም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 64, '64. «አላህ ጌታዬ ጌታችሁም ነውና በብቸኝነት ተገዙት:: ይህ ቀጥተኛ መንገድ ነው::» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 65, '65. ከመካከላቸዉም አህዛቦቹ ተለያዩ:: ለእነዚያም ለበደሉት ህዝቦች ከአሳማሚ ቀን ቅጣት ወዮላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 66, '66. ሰዓቲቱን እነርሱ የማያውቁ ሆነው በድንገት ልትመጣባቸው እንጂ (ሌላ) ይጠባበቃሉን?::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 67, '67. አላህን የሚፈሩ ሰዎች ብቻ ሲቀሩ ወዳጆች በዚያ ቀን ከፊላቸው ለከፊሉ ጠላት ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 68, '68. (አላህም ለነርሱ) «ባሮቼ ሆይ! ዛሬ ቀን በእናንተ ላይ ምንም ፍርሀት የለባችሁም:: እናንተም የምታዝኑ አይደላችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 69, '69. «እነዚያ በአናቅጻችን ያመኑና ፍጹም ታዛዦች የነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 70, '70. (ባሮቼ ሆይ!) « እናንተም ሚስቶቻችሁም ገነትን ግቡ ትደሰታላችሁ (ትከበራላችሁ)።» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 71, '71. ከወርቅ የሆኑ ሰፋፊ ዝርግ ሳህኖችና ኩባያዎች በእነርሱ ላይ እንዲዞሩ ይደረጋሉ። በእርሷም ውስጥ ነፍሶች የሚከጅሉት ዓይኖችም የሚደስቱበት ሁሉ አለ:: እናንተም በውስጧ ዘላለም ዘውታሪዎች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 72, '72. ይህም ያ ስትሰሩት በነበራችሁት ዋጋ የተሰጣችኋት ገነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 73, '73. ለእናንተ በውስጧ ብዙ ፍራፍሬዎች አሏችሁና ከእርሷም እንደልባችሁ ትበላላችሁ ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 74, '74. አመጸኞች በገሀነም ስቃይ ውስጥ በእርግጥ ዘወታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 75, '75. ከእነርሱም ቅጣት በፍጹም አይቀለልላቸዉም:: እነርሱም በእርሱ ውስጥ ተስፋ ቆራጮች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 76, '76. አልበደልናቸዉም:: በዳዮቹ ግን እነርሱው ብቻ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 77, '77. «ማሊክ ሆይ! ጌታህ በእኛ ላይ (በሞት) ይፍረድ።» እያሉ ይጣራሉም:: ይላቸዋልም: «እናንተ (በቅጣት ውስጥ) ለዘላለም ነዋሪዎች ናችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 78, '78. «እውነተኛውን መንገድ በእርግጥ አመጣንላችሁ:: ግን አብዛኞቻችሁ እውነትን ጠይዎች ነበራችሁ» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 79, '79. ይልቁንም (በነብዩ ላይ) በማደም ነገርን አጠነከሩን? እኛም ተንኮላቸውን ወደ እነርሱ በመመለስ አጠንካሪዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 80, '80. ወይም እኛ ሚስጥራቸውንና ውይይታቸውን የማንሰማ መሆናችንን ያስባሉን? ነገሩ እነርሱ እንደሚሉት አይደለም:: መልዕክተኞቻችን እነርሱ ዘንድ ናቸው:: የሚሉትን ሁሉ ይጽፋሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 81, '81. (መልዕክተኛችን ሙሐመድ ሆይ!) «ለአር-ረሕማን ልጅ (የለዉም እንጂ) ቢኖረው እኔ ለልጁ የተገዢዎች መጀመሪያ ነኝ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 82, '82. የሰማያት፤ የምድርና የዙፋኑ ጌታ ከሓዲያን ስለ እሱ ከሚሉት ነገር ሁሉ ጠራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 83, '83. (መልዕክተኛችን ሙሐመድ ሆይ!) ያንን ይስፈራሩበት የነበሩትን ቀናቸውን እስከሚገናኙ ድረስ በስህተታቸው ውስጥ ይዋኙ ተዋቸው :: ይጫዎቱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 84, '84. እርሱም ያ በሰማይ ውስጥ ሊገዙት የሚገባው በምድርም ውስጥ ሊገዙት የሚገባው ብቸኛ አምላክ ነው:: እርሱም ጥበበኛውና ሁሉን አዋቂው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 85, '85. ያም የሰማያት፤ የምድርና በመካከላቸው ያለው ሁሉ ንግስና ለእርሱ ብቻ የሆነው አምላክ ላቀ:: የሰዓቲቱም የመምጫዋ ዘመን ዕውቀት በእርሱ ዘንድ ብቻ ነው:: ወደ እርሱም ብቻ ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 86, '86. እነዚያም ከአላህ ሌላ የሚገዟቸው አማልክት ሁሉ እነርሱ ትክክለኛውን የሚያውቁ ሆነው በእውነት ከመሰከሩት ክፍሎች በስተቀር ምልጃ አይችሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 87, '87. (መልዕክተኛችን ሙሐመድ ሆይ!) ማን እንደ ፈጠራቸው ብትጠይቃቸው በእርግጥ አላህ ነው ይላሉ:: ታዲያ (ከትክክለኛው እምነት) ወዴት ይዞራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 88, '88. (ነብዩ) ጌታዬ ሆይ! እነዚህ የማያምኑ ህዝቦች ናቸው የማለቱም እውቀቱ አላህ ዘንድ ብቻ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (43, 89, '89. (መልዕክተኛችን ሙሐመድ ሆይ!) እነርሱን ተዋቸው:: «ነገሬ ስላም ነው» በልም:: ወደፊትም የሚመጣባቸውን ሲደርስ ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 1, '1. ሓ፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 2, '2. ሁሉን ነገር አብራሪ በሆነው መጽሐፍ እንምላለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 3, '3. እኛ ቁርኣኑን በዚያች በተባረከችው ሌሊት ውስጥ አወረድነው:: እኛ አስፈራሪዎች ነበርንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 4, '4. በውስጧ የተወሰነው ነገር ሁሉ ይለያል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 5, '5. ከእኛ ዘንድ የሆነ ትዕዛዝ ሲሆን አወረድነው:: እኛ መልዕክተኞችን ላኪዎች ነበርንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 6, '6. (መልዕክተኞች) ከጌታህ በሆነው ችሮታ (ተላኩ)። እነሆ እርሱ(አላህ) የሚባለዉን ሁሉ ሰሚና ሁሉን አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 7, '7. የሰማያት፤ የምድር እና በመካከላቸው ያሉ ነገሮች ሁሉ ጌታ ከሆነው (ተላኩ)። የምታረጋግጡ እንደሆናችሁ (ነገሩ እንዳልነው መሆኑን እወቁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 8, '8. ከእርሱም ሌላ አምላክ የለም። ህያው ያደርጋል። ህይወትም ይነሳል። ጌታችሁ የመጀመሪያዎቹ አባቶቻችሁም ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 9, '9. በእውነቱ እነርሱ የሚጫወቱ ሲሆኑ በመጠራጠር ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) ( ሰዎችን) የሚሸፍን በሆነ ግልጽ ጭስ ሰማይ የምትመጣበትን ቀን ተጠባበቅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 11, '11.ሰዎችን ይሸፍናል ይህ አሳማሚ ቅጣት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 12, '12. ጌታችን ሆይ! ክእኛ ላይ ቅጣቱን ግለጥልን:: እኛ ትክክለኛ አማኞች ነንና (ይላሉ::)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 13, '13. አስረጂ መልዕክተኛ የመጣላቸው እና በአላህ የካዱ ሲሆኑ (ቅጣቱ በወረደ ጊዜ) ለእነርሱ መገሰጽ እንዴት ይኖራቸዋል?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 14, '14. ከዚያም «ከሰው የተስተማረ እብድ ነው» ያሉ ሲሆኑ ከእርሱ ዞሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 15, '15. እኛ ቅጣትን ለጥቂት ጊዜ ገላጮች ነን። እናንተ ግን ወደ ክህደታችሁ በእርግጥ አንደገና ተመላሾች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 16, '16. ታላቂቱን ብርቱ አያያዝ በምንይዝበት ቀን እኛ ተበቃዮች ነን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 17, '17. ከእነርሱ በፊት የፈርዖንን ህዝቦች በእርግጥ ሞከርን:: ክቡር መልዕክተኛም መጣላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 18, '18. «የአላህን ባሮች ወደ እኔ አድርሱ (ለኔ ስጡኝ):: እኔ ለእናንተ ታማኝ መልዕክተኛ ነኝና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 19, '19. «በአላህም ላይ ላትኮሩ። እኔ ግልጽ የሆነን አስረጂ ያመጣሁላችሁ ነኝና በማለት መጣላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 20, '20. «እኔ እንዳትወግሩኝ በጌታዬና በጌታችሁ ተጠብቂያለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 21, '21. «በእኔም ባታምኑ ራቁኝ። ተውኝ።» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 22, '22. «ቀጥሎም እነዚህ አመጸኞች ህዝቦች ናቸው (አጥፋቸው)።» ሲል ጌታውን ለመነ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 23, '23. (ጌታዉም አለ) «ባሮቼንም ይዘህ በሌሊት ሂድ። እናንተ የሚከተሉዋችሁ ናችሁና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 24, '24. «ባህሩንም የተከፈተ ሆኖ ተወው፤ እነርሱ የሚሰምጡ ሰራዊት ናቸውና» አለው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 25, '25. ከአትክልቶችና ከምንጮች ብዙ ነገሮችን ትተው ሄዱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 26, '26. ከአዝመራዎችም ከመልካም መቀመጫም', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 27, '27. በእርሷ ተደሳቾች ከነበሩባትም ድሎት (ብዙን ነገር ትተው ሞቱ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 28, '28. ነገሩ ልክ እንደዚህ ሆነ፤ ለሌሎች ህዝቦች አወረስናትም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 29, '29. ሰማይና ምድር በእነርሱ ላይ አላለቀሱም:: የሚቆዩም አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 30, '30. የኢስራኢል ልጆችን ከዚያ አዋራጅ ከሆነው ስቃይ በእርግጥ አዳንናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 31, '31. ከፈርዖን እርሱ (ፈርዖውን) የኮራ ከወሰን አላፊዎችም አንዱ ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 32, '32. ከማወቅም ጋር ከዓለም ህዝቦች መካከል በእርግጥ መረጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 33, '33. ከተአምራቶችም በውስጡ ግልጽ የሆነ ፈተና ያለበትን ሰጠናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 34, '34. እነዚህ (የመካ ካሓዲያን) በእርግጥ ይላሉ:', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 35, '35. «እርሷ የፊተኛይቱ ሞታችን እንጅ (ሌላ) አይደለችም። እኛም የምንቀሰቀስ አይደለንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 36, '36. «እውነተኞችም እንደሆናችሁ አባቶቻችንን እስቲ አምጡልን።» (ይላሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 37, '37. እነርሱ በላጮች ናቸውን? ወይስ የቱበዕ ህዝቦችና እነዚያ ከእነርሱ በፊት የነበሩት? እነርሱን አጠፋናቸው። እነርሱ አመጸኞች ነበሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 38, '38. ሰማያትና ምድርን በሁለቱ መካከል ያለውንም ሁሉ ቀላጆች ሆነን አልፈጠርንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 39, '39. ሁለቱንም በቁምነገር እንጂ አልፈጠርናቸዉም:: ግን አብዛሀኞቻቸው አያውቀዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 40, '40. የመለያው ቀን ለሁሉም ቀጠሯቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 41, '41. ዘመድ ከዘመዱ ምንንም የማይጠቅምበት እነርሱም የማይረዱበት ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 42, '42. አላህ ያዘነለትና ያመነ ብቻ ሲቀር:: (እርሱ ይረዳል) እርሱ (አላህ) ሁሉን አሸናፊና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 43, '43. የዘቁም ዛፍ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 44, '44. የኃጢአተኞች ምግብ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 45, '45. እሱም ልክ እንደ ዘይት አተላ በሆዶች ውስጥ ይፈላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 46, '46. እንደገነፈለ ውሃ አፈላል የሚፈላ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 47, '47. ያዙትና ወደ ገሀነም መካከል (ውስጥ) በሀይል ጎትቱት (ገፍትሩት)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 48, '48. ከዚያም በራሱ ላይ ከፈላ ውሃ ስቃይ አንቧቡበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 49, '49. (ይባላልም) «ቅመስ አንተ አሸናፊው፤ ክቡር የነበርክ ነህና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 50, '50. «ይህ ያ በእርሱ ትጠራጠሩበት የነበራችሁት ነው» (ይባላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 51, '51. ጥንቁቆች በእርግጥ በደህናማ መኖሪያ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 52, '52. በአትክልቶችና በምንጮች ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 53, '53. ፊት ለፊት የተቅጣጩ ሆነው ከስስ ሐርና ከወፍራም ሐር ይለብሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 54, '54. ነገሩ ልክ እንደዚህ ነው። ዓይናማዎች የሆኑን ሴቶችም እናጠናዳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 55, '55. በእርሷ ውስጥም የተማመኑ ሆነው ከፍራፍሬ ሁሉ ያዛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 56, '56. የፊተኛይቱን ሞት እንጂ ዳግመኛ በእርሷ ውስጥ ሞትን አይቀምሱም:: የገሀነምንም ቅጣት አላህ ጠብቋቸዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 57, '57. (መልዕክተኛችን ሙሐመድ ሆይ!) (ይህም ) ከጌታህ (አላህ) የሆነ ትሩፋት ሲሆን ይህም እርሱ ታላቁ እድል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 58, '58. (መልዕክተኛችን ሙሐመድ ሆይ!) ቁርኣኑንም በቋንቋህ ያገራነው ህዝቦች ይገነዘቡት ዘንድ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (44, 59, '59. ተጠባበቅ:: እነርሱም ተጠባባቂዎች ናቸውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 1, '1. ሓ፤ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 2, '2. የመጽሐፉ መወረድ ሁሉን አሸናፊና ጥበበኛ ከሆነው ከአላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 3, '3. በሰማያትና በምድር ውስጥ ለአማኞች ሁሉ እርግጠኛ ምልክቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 4, '4. (ሰዎች ሆይ!) እናንተን በመፍጠር እና ከተንቀሳቃሽ ነገሮች በምድር ላይ የሚበተነውን ሁሉ በመፍጠሩ ለሚያረጋግጡ ህዝቦች ሁሉ አያሌ ተአምራት አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 5, '5. በሌሊትና በቀን መተካካትም፤ አላህ ከሰማይ ባወረደው ሲሳይ (ዝናብ) በእርሱም ምድርን ከሞተች በኋላ ህያው በማድረጉ፤ ንፋሶችንም (በየ አቅጣጫው) በማዘዋወሩ ለሚያውቁ ህዝቦች ሁሉ በቂ ማስረጃዎች አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 6, '6. እነዚህ ባንተ ላይ በእውነት የምናነባቸው የሆኑ የአላህ ማስረጃዎች ናቸው:: ከአላህና ከማስረጃዎቹ በኋላ በየትኛው ንግግር ያምናሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) ውሸታም፤ ኃጢአተኛ ለሆነ ሁሉ ወዮለት (ጥፋት ተገባው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 8, '8. የአላህን አናቅጽ በእርሱ ላይ የሚነበቡለት ሲሆኑ ይሰማል:: ከዚያም የኮራ ሲሆን እንዳልሰማ ሆኖ በክህደቱ ላይ ይዘወትራል:: እናም እርሱን በአሳማሚ ቅጣት አብስረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 9, '9. ከአናቅጻችንም አንዲትን ነገር ባወቀ ጊዜ መሳለቂያ ያደርጋታል:: እነዚያ ለእነርሱ አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 10, '10. ከፊታቸዉም ገሀነም አለች:: የሰበሰቡት ሀብትም ከእነርሱ ላይ ምንንም አይመልስላቸዉም:: ከአላህ ሌላም ረዳቶች ያደረጓቸው ሁሉ ምንንም አይጠቅሟቸዉም:: ለእነርሱም ታላቅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 11, '11. ይህ ቁርኣን መሪ ነው:: እነዚያም በጌታቸው አናቅጽ የካዱት ሁሉ ለእነርሱ ከብርቱ ቅጣት ድርሻቸው አለባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 12, '12. አላህ ያ ባህርን በውስጡ ታንኳዎች በፈቃዱ እንዲንሻለሉበት ከችሮታዉም እንድትፈልጉበት እንድታመሰግኑትም ለእናንተ የገራላችሁ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 13, '13. ለእናንተ በሰማያትና በምድር ያለው ሁሉ በመላ ከእርሱ ሲሆን ያገራላችሁ ነው። በዚህ ለሚያስተነትኑ ህዝቦች ሁሉ አያሌ ተዐምራት አሉበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 14, '14. (መልዕክተኛችን ሙሐመድ ሆይ!) ለእነዚያ በአላህ ላመኑት «ለእነዚያ የአላህን ቀናት ለማይፈሩት ሰዎች ምህረት (ይቅርታ) አድርጉ» በላቸው:: (አላህ) ህዝቦችን ይሰሩት በነበሩት ነገር ይመነዳልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 15, '15. መልካምን የሰራ ሁሉ ጥቅሙ ለነፍሱ ነው:: ክፉንም ተግባር የሰራ ሁሉ ክፋቱ በእርሱው ላይ ነው:: ከዚያም ሁላችሁም ወደ ጌታችሁ ትመለሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 16, '16. ለኢስራኢል ልጆችም መጽሐፍን፤ ሕግን እና ነብይነትን በእርግጥ ሰጠናቸው:: ከመልካም ሲሳዮችም ለገስንላቸው:: (በዘመናቸው ከነበሩት) የዓለማት ህዝብ ላይም አበለጥናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 17, '17. ከትዕዛዝም ግልጽ ነገሮችን ሰጠናቸው:: እውቀቱም ከመጣላቸው በኋላ በመካከላቸው ለምቀኝነት እንጅ ለሌላ አልተለያዩም:: (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ በትንሳኤ ቀን በዚያ በእርሱ ይለያዩበት በነበሩት ነገር ሁሉ በመካከላቸው በትክክል ይፈርዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 18, '18. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዚያም ከሃይማኖት በትክክለኛው ሕግ ላይ አደረግንህ:: ስለዚህ ተከተለው:: የነዚያን የማያውቁትን ህዝቦች ዝንባሌዎች አትከተል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 19, '19. እነርሱ ከአላህ ቅጣት ምንንም ካንተ አይገፈትሩልህምና። በደለኞችም ከፊላቸው ለከፊሉ ረዳቶች ናቸው:: አላህ የጥንቁቆቹ ወዳጅ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 20, '20. ይህ (ቁርኣን) ለሰዎች የልብ ብርሃኖች ነው:: ለሚያረጋግጡትም ህዝቦች ሁሉ መሪና እዝነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 21, '21. እነዚያ ኃጢአቶችን የሰሩ ሕይወታቸዉንም ሞታቸዉንም ልክ እንደነዚያ እንዳመኑት መልካሞችንም እንደሰሩት ልናደርጋቸው ያስባሉን? (አይስቡ):: ይህ ከሆነ ፍርዱ ምንኛ ከፋ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 22, '22. አላህም ሰማያትንና ምድርን በትክክል ፈጠረ:: እነርሱ የማይበደሉ ሲሆኑ ነፍስ ሁሉ በሰራችው ስራ ትመነዳ ዘንድ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 23, '23. (መልዕክተኛችን ሙሐመድ ሆይ!) ዝንባሌውን አምላኩ ያደረገውን አላህም ከእውቀት ጋር ያጠመመውን በጆሮውና በልቡም ላይ ያተመበትን በዓይኑም ላይ ሺፋን ያደረገበትን ሰው አየህን? ታዲያ ከአላህ በኋላ የሚያቀናው ማነው? አትገሰጹምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 24, '24. (ከሓዲያን) «እርሷም(ሕይወት) የቅርቢቱ ሕይወታችን ብቻ እንጂ ሌላ አይደለችም:: እንሞታለን:: ህያዉም እንሆናለን:: ከጊዜም (ማለፍ) በሰተቀር ሌላ አያጠፋንም» አሉ:: ለእነርሱም በዚህ በሚሉት ምንም እውቀት የላቸዉም:: እነርሱ የሚጠራጠሩ እንጂ ሌላ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 25, '25. አናቅጻችንም ግልፆች ሆነው በእነርሱ ላይ በተነበቡላቸው ጊዜ የክርክራቸው ማስረጃ «እውነተኞች እንደሆናችሁ እስቲ የቀድሞ አባቶቻችንን አምጡ» ማለት እንጂ ሌላ አልነበረም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 26, '26. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ ህያው ያደርጋችኋል ከዚያም ያሞታችኋልም:: ከዚያም በትንሳኤ ቀን ይሰበስባችኋል:: ይህም ጥርጥር የለበትም:: ግን አብዛኛዎቹ ሰዎች አያውቁም።» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 27, '27. የሰማያትና የምድር ግዛት የአላህ ብቻ ነው:: ሰዓቲቱም በምትከሰትበት ቀን ያን ጊዜ አጥፊዎች ሁሉ ይከስራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) ህዝቦችን ሁሉ ተንበርካኪ ሆነው ታያቸዋለህ:: ህዝብም ሁሉ ወደ ግል መጽሐፋቸው ይጠራሉ:: ይባላሉም: «ዛሬ ቀደም ሲል ትሰሩት የነበራችሁትን ነገር ትመነዳላችሁ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 29, '29. «ይህ መጽሐፋችን ነው:: በእናንተ ላይ በእውነት ይናገራል:: እኛ ያንን ትሰሩት የነበራችሁትን ሁሉ እናስገለብጥ ነበርንና» (ይባላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 30, '30. እነዚያ ያመኑትና መልካሞችን የሰሩትማ ጌታቸው በእዝነቱ ውስጥ ያስገባቸዋል:: ይህ እርሱ ግልጽ የሆነ እድልን ማግኘት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 31, '31. እነዚያም የካዱትማ ለእነርሱ ይባላሉ: «አናቅጾቼ በእናንተ ላይ ይነበቡ አልነበሩምን? ኮራችሁም :: ከሓዲያን ህዝቦችም ነበራችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 32, '32. «የአላህ ቀጠሮ እውነት ነው:: በእርሷ መምጣት (ጥርጥር) የለም:: በተባለ ጊዜም ''ሰዓቲቱ ምን እንደሆነች አናውቅም መጠራጠርን የምንጠራጠር እንጂ ሌላ አይደለንም:: እኛም አረጋጋጮች አይደለንም'' አላችሁ::» (ይባላሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 33, '33. የሰሩዋቸው ኃጢአቶችም ለእነርሱ ይገለጹላቸዋል:: ያም በእርሱ ይሳለቁበት የነበሩት ቅጣት በእነርሱ ላይ ይወርድባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 34, '34. «በዱንያ የዚህንም ቀናችሁን መገናኘት እንደረሳችሁ ሁሉ ዛሬ እኛም እንተዋችኋለን:: መኖሪያችሁም እሳት ናት:: ለእናንተም ከረዳቶች ምንም የላችሁም» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 35, '35. «ይህ እናንተ የአላህን አናቅጽ መቀላጃ በማድረጋችሁና ቅርቢቱ ሕይወት ስለ አታለለቻችሁ ነው» ይባላሉ:: ዛሬ ከእርሷ አይወጡም:: እነርሱም በወቀሳ አይታለፉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 36, '36. ምስጋና ሁሉ ለሰማያት፤ ለምድርና ለዓለማት ጌታ ለሆነው ለአላህ ብቻ የተገባው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (45, 37, '37. ኩራትም በሰማያትም ሆነ በምድር ለእርሱ ብቻ ነው:: እርሱ ሁሉን አሸናፊና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 1, '1. ሓ፤ ሚይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 2, '2. የመጽሐፉ መወረድ አሸናፊ፤ ጥበበኛ ከሆነው አላህ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 3, '3. ሰማያትን፤ ምድርን እና በመካከላቸው ያለውንም ሁሉ በምር እና በተወሰነ ጊዜንም በመለካት እንጂ ለቀልድ አልፈጠርናቸዉም። እነዚያ በአላህ የካዱት የተስፈራሩትን ነገር ደንታ አይሰጡትም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 4, '4. (መልዕክተኛችንሙሐመድ ሆይ!) «ከአላህ ሌላ የምትገዟቸውን አላያችሁምን? ከምድር ምንን እንደፈጠሩ እስቲ አሳዩኝ:: ወይስ በሰማያት መፍጠር ለእነርሱ ከአላህ ጋር መጋራት አላቸውን? (ያማልዱናል በማለታችሁ) እውነተኞች እንደሆናችሁ ይህንን ጉዳይ ከዚህ በፊት የሆነን መጽሐፍ ወይም ከእውቀት ቅሪት እስቲ አምጡልኝ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 5, '5. እስከ ትንሳኤ ቀን ድረስም ለእርሱ የማይመልሱለትን ጣዖታት ከአላህ ሌላ ከሚጠራ ሰው ይበልጥ የተሳሳተ ማንነው? እነርሱም ከጥሪያቸው ዘንጊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 6, '6. ሰዎችም በተሰበሰቡ ጊዜ ጣኦቶቹ ለእነርሱ ጠላቶች ይሆናሉ:: እነርሱን መገዛታቸውንም ይክዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 7, '7. በእነርሱም ላይ አንቀፆቻችን ግልፆች ሆነው በተነበቡ ጊዜ እነዚያ እውነቱ በመጣላቸው ጊዜ የካዱት ክፍሎች «ይህ ግልጽ ድግምት ነው» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 8, '8. (መልዕክተኛችን ሙሐመድ ሆይ!) ይልቁንም «(ሙሐመድ ራሱ) ቀጠፈው» ይላሉን? «ብቀጥፈው ኖሮ እኔን ከአላህ ቅጣት ለማዳን በምንም አትችሉም:: እርሱ ያንን የምትቀባዥሩበትን ነገር ሁሉ አዋቂ ነው:: በእኔና በእናንተ መካከል መስካሪነት እሱው በቃ:: እርሱ መሀሪ እና አዛኝ ነውና» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 9, '9. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመልዕክተኞች የተለየሁ ብጤ የሌለኝ አይደለሁም:: በእኔም በእናንተም ላይ ምን እንደሚሰራብንም አላውቅም:: ወደ እኔ የሚወረደውን እንጂ ሌላን መመሪያ አልከተልም:: እኔም ግልጽ አስፈራሪ እንጂ ሌላ አይደለሁም» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 10, '10. «(መልዕክተኛችን ሙሐመድ ሆይ!) እስቲ ንገሩኝ ቁርኣኑ ከአላህ ዘንድ ቢሆንና በእርሱ ብትክዱ ከኢስራኢል ልጆች የሆነ መስካሪ ደግሞ በቢጤው ቢያምንና በእርሱ ላይ ቢመሰክር እናንተ (ግን) ብትኮሩ (በዳይ አትሆኑምን)? አላህ በእርግጥ በደለኛ ህዝቦችን ሁሉ አያቀናም» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 11, '11. እነዚያም የካዱት ሰዎች ስላመኑት ሰዎች «እምነቱ መልካም ነገር በሆነ ኖሮ ወደ እርሱ ባልቀደሙን ነበር» አሉ:: በእርሱም ባልተቀኑ ጊዜ «ይህ ቁርኣን ጥንታዊ ቅጥፈት ነው» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 12, '12. ከፊቱም የሙሳን መጽሐፍ ለሰዎች መሪና የአላህ ጸጋ ሲሆን እንዳወረድን አላየህምን? ይህ ቁርኣን እነዚያን የበደሉትን ሊያስፈራራ በዐረብኛ ቋንቋ የወረደ ሲሆን የፊቶቹንም መጽሐፍት አረጋጋጭ እና ለበጎ አድራጊዎችም ሁሉ የብስራት መጽሐፍ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 13, '13. «እነዚያ ጌታችን አላህ ነው» ያሉና ከዚያም በዚሁ ቃላቸው ላይ ቀጥ ያሉ ሰዎች ሁሉ በእነርሱ ላይ ምንም (ይደርስብናል ብለው) ፍርሀት የለባቸዉም:: ምንም (ነገር ያመልጠናል ብለው) አያዝኑምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 14, '14. እነዚያ የገነት ጓዶች ናቸው:: በእርሷ ውስጥ ዘወታሪዎች ሲሆኑ በዚያ በዱንያ ይሰሩት በነበሩት መልካም ተግባር ምክንያት ያገኙት ምንዳ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 15, '15. የሰውን ልጅ ለወላጆቹ በጎ መዋል እንዳለበት በጥብቅ አዘዝነው:: እናቱ በችግር ላይ ሆና አረገዘችው:: በችግርም ላይ ሆና ወለደችው:: እርግዝናውና (ከጡት) መለያው ሙሉ ሰላሳ ወር ነው:: ከዚያም የጥንካሬውን ወቅት በደረሰ ጊዜ አርባ ዓመት በደረሰ ጊዜ «ጌታዬ ሆይ! ያን በእኔ ላይና በወላጆቼ ላይ የለገስከዉን ጸጋህን እንዳመሰግንህና የምትወደውን መልካም ስራም እንድሰራ ወደ ቀናው መንገድ ምራኝ:: ዘሮቼንም ለእኔ አብጅልኝ:: እኔ ወደ አንተ ብቻ ተመለስኩ:: እኔ ከሙስሊሞች አንዱ ነኝ» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 16, '16. እነዚያ (ይህንን ባዩች ሁሉ) ከገነት ጓዶች መካከል ሲሆኑ እነዚያ ከሰሩት ስራ መልካሙን የምንቀበላቸውና ከኃጢአቶቻቸዉም የምናልፋቸው ሰዎች ናቸው:: ያንን ተስፋ ይሰጡት የነበሩትን እውነተኛ ቀጠሮ እንሞላላቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 17, '17. ያንንም ለሁለቱ ወላጆቹ አላህን የሚለምኑ ሲሆኑ «በአላህ እመን፤ የአላህ ቀጠሮ እርግጠኛ ነው፤» ሲሉት «ኡፍ! ከእኔ በፊት የብዙ ክፈለ ዘመናት ሰዎች ሳይወጡ በእርግጥ ያለፉ ሲሆኑ ከመቃብር እንደምወጣ ታስፈራሩኛላችሁን?» ይላልም: "ይህ የቀደምቶች ተረት እንጅ ሌላ አይደለም" ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 18, '18. እነዚህ እነዚያ ከአጋንንትም ከሰዉም ከእነርሱ በፊት ካለፉት ህዝቦች ጋር የአላህ ቃሉ በእነርሱ ላይ የተረጋገጠባቸው ናቸው:: እነርሱ ከሳሪዎች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 19, '19. ለሁሉም በሰሩት ስራ ልክ ተገቢ የሆኑ ደረጃዎች አሏቸው:: ስራዎቻቸውንም ይሞላላቸው ዘንድ ይህንን መነዳቸው:: እነርሱም አይበደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 20, '20. እነዚያም የካዱት በእሳት ላይ በሚጋፈጡበት ቀን ጣፋጮቻችሁን በአነስተኛይቱ ሕይወታችሁ አሳለፋችሁ:: በእርሷም ተጣቀማችሁ። ስለዚህ በምድር ላይ ያለ አግባብ ትኮሩ በነበራችሁትና ታምጹ በነበራችሁት ምክኒያት ዛሬ የውርደትን ቅጣት ትመነዳላችሁ ይባላሉ፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) በአል አሕቃፍ የነበረው የዓድ ወንድም የሆነው ሁድ ከእርሱ በፊትም ሆነ ከእርሱ በኋላም አስፈራሪዎች ባለፉት መልኩ «ከአላህ ውጪ ሌሎች አማልክትን አታምልኩ:: የታላቁን ቀን ቅጣት እፈራላችኋለሁ።» በሚል ሲያስጠነቅቃቸው (የነበረውን አስታውስ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 22, '22. «ከአማልክቶቻችን ልታሸሸን መጣህን? እውነተኛ ከሆንክ ያንን የምታስፈራራን ቅጣት አሁን እንዲከሰት አድርግ» አሉት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 23, '23. «የቅጣቱ መከሰቻ ትክከለኛ ወቅት እውቀት ያለው ከአላህ ዘንድ ብቻ ነው:: የተላኩበትን መልዕክት ብቻ አደርስላችኋለሁ:: ግና እንደማያችሁ መሀይማን ህዝቦች ናችሁ።» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 24, '24. ለቅጣት የተላከባቸውን (ዳመና) ወደ ሸለቆዎቻቸው አቅጣጫ ሲጓዝ ባዩ ጊዜ «ይህ ዝናብ የሚያወርድልን ዳመና ነው» አሉ:: አይደለም። ይልቁንም ያ በፍጥነት ይከሰት ዘንድ የጠየቃችሁት ቅጣት ነው:: አሳማሚ ቅጣት ያዘለ ንፋስ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 25, '25. በጌታዋ ትዕዛዝ ሁሉን ነገር ታጠፋለች» (አላቸው)፡፡ ባዶ ቤቶቻቸው እንጂ ሌላ ነገር የማይታይ ሆነው አነጉ:: አመጸኞች ህዝቦችን በዚህ መልኩ እንቀጣለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 26, '26. ለእናንተ ያልሰጠነውን ኃይልና ምቾት ለእነርሱ ሰጥተናል:: መሰሚያ ጆሮዎችን፤ መመልከቻ ዓይኖችን እና ማሰቢያ አእምሮንም ለግሰናቸዋል:: ግና ጆሮዎቻቸዉም፤ ዓይኖቻቸዉም፤ አእምሮዎቻቸዉም የፈየዷቸው ነገር አልነበረም:: የአላህን አናቅጽ ያስተባብሉ ነበርና:: በመሆኑም በእነርሱ ላይ ያ ያፌዙበት በነበረው ቅጣት ወረደባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 27, '27. በዙሪያችሁ የነበሩ ከተሞችንም አጠፋን:: ይመለሱ ዘንድም ተደጋጋሚ ታዐምራትን አሳይተናቸው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 28, '28. እነዚያ መቃረቢያ ይሆናቸው ዘንድ ከአላህ ሌላ በረዳትነት የያዟቸው አማልክት በመከራቸው ወቅት ለምን አልረዷቸዉም? ይልቁንም ከእነርሱ ራቁ:: ይህ ሀሰታቸውና ይቀጥፉት የነበረው ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) ከአጋንንት የሆኑ ቡድኖች ቁርኣንን የሚያደምጡ ሁነው በላክንልህ ጊዜ የሆነውን አስታውስ:: ሲነበብ በደረሱ ጊዜ «ዝም በሉ» ተባባሉ:: ንባቡ ሲጠናቀቅም ወገኖቻቸውን ለማስጠንቀቅ ወደ ህዝቦቻቸው ተመለሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 30, '30. አሉም ለወገኖቻቸው: «ወገኖቻችን ሆይ! ከሙሳ ተውራት በኋላ የተወረደንና ከእርሱ በፊት የወረዱትን መጽሐፍት አጽዳቂ ወደ እውነትና ወደ ቀጥተኛው ጎዳና መሪም የሆነን መጽሐፍ አደመጥን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 31, '31. «ወገኖቻችን ሆይ! ለዚህ ወደ አላህ ለሚጠራችሁ ሰው በጎ ምላሽ ስጡ:: በእርሱ እመኑም:: ይህን ካረጋችሁ (አላህ) ከኀጢአቶቻችሁ ለእናንተ ይምራልና፡፡ ከአሳማሚ ቅጣትም ይጠብቃችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 32, '32. ወደ አላህ ለሚጠራ ሰው ሁሉ በጎ ምላሽ ያልሰጠ በምድር ላይ ከአላህ ቅጣት አያመልጥም:: ከእርሱ ሌላም ረዳት አይኖረዉም:: እንዲህ አይነት ሰዎች ግልጽ ጥመት ውስጥ ናቸው::» (አሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 33, '33. ያ ሰማያትንና ምድርን የፈጠረው እርሱም በመፍጠሩም ድካም ያልተሰማው አላህ ሙታንን ህያው ማድረግ እንደሚችል አላዩምን ? በእርግጥም ይህን ማድረግ የሚሳነው አይደለም :: እርሱ ሁሉንም ነገር ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 34, '34. እነዚያም የካዱት ሰዎች ሁሉ ወደ እሳት እንዲቀርቡ በሚደረጉ ጊዜ የሚሆነውን አስታውስ። «ይህ እውነት አይደለምን ?» ይባላሉ :: «አዎ እውነት መሆኑን በጌታችን በመማል እናረጋግጣለን» ይላሉ:: እርሱም «ታስተባብሉት በነበራችሁት ሰበብ ቅጣትን ቅመሱ» ይላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (46, 35, '35. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመልዕክተኞች መካከል የጽናት ባለቤቶች እንደታገሱት ሁሉ አንተም ታገስ::(በህዝቦችህ ላይ) ቅጣቱ ይፋጠንባቸው ዘንድም አትጠይቅ:: ያን ቃል የተገባላቸውን ቅጣት በሚያዩ ጊዜ ምድር ላይ ከቀን ውስጥ የተወሰነ ወቅት ብቻ እንጂ እንዳልቆዩ ይሰማቸዋል:: ይህ የማስጠንቀቂያ መልዕክት ነው:: ከአመጸኞች ህዝቦች ውጪ ሌሎች እንዲጠፉ ይደረጋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 1, '1. እነዚያ የካዱ እና ከአላህ መንገድ ሌሎችን የከለከሉ አላህ ስራዎቻቸውን አጠፋባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 2, '2. እነዚያም ያመኑ በጎዎችንም ተግባራት የሰሩ በሙሐመድ ላይም የተወረደው እርሱ ከጌታቸው ሲሆን እውነት ስለሆነ ያመኑ ከእነርሱ ላይ ኃጢአቶቻቸውን ያብሳል:: ሁኔታቸውንም ሁሉ ያበጃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 3, '3.ይህ እነዚያ የካዱት ውሸትን የተከተሉ በመሆናቸውና እነዚያም ያመኑት ከጌታቸው የሆነን እውነት ስለተከተሉ ነው:: ልክ እንደዚሁ አላህ ለሰዎች ምሳሌዎቻቸውን ያብራራል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 4, '4. አማኞች ሆይ! እነዚያንም የካዱትን ሰዎች በጦር ላይ ባገኛችኋቸው ጊዜ ጫንቃዎችን በሀይል ምቱ:: ባደከማችኋቸው ጊዜም አትግደሏቸው፤ ማርኳቸው:: መሳሪያውንም አጥብቁ:: በኋላም በነጻ ትለቋቸዋላችሁ:: ወይም ፊዳ ታስከፍሏቸዋላችሁ:: ይህም ጦሩ መሳሪያዉን እስከሚጥል ድረስ ነው:: ነገሩ ይህ ነው:: አላህም ቢፈልግ ከእነርሱ ያለ ጦር በተበቀለ ነበር ግን ከፊላችሁን በከፊሉ ሊሞክር (በዚህ አዘዛችሁ)። እነዚያንም በአላህ መንገድ ላይ የተገደሉት ሰዎች ስራዎቻቸውን ፈጽሞ አያጠፋባቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 5, '5. በእርግጥ ይመራቸዋል:: ሁኔታቸውንም ሁሉ ያበጃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 6, '6. ገነትንም ያገባቸዋል፡፡ ለእነርሱ አስታውቋታል፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 7, '7. እናንተ ያመናችሁ ሆይ! የአላህን ሃይማኖት ብትረዱ ይረዳችኋል:: ጫማዎቻችሁንም ያደላድላል።ያጸናላችኋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 8, '8. እነዚያም የካዱት ለእነርሱ ጥፋት ተገባቸው:: ስራዎቻቸውንም አጠፋባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 9, '9. ይህ እነርሱ አላህ ያወረደውን ስለጠሉ ነው:: ስለዚህ ስራዎቻቸውን አበላሸባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 10, '10. የእነዚያ ከእነርሱ በፊት የነበሩ ከሓዲያን ሁሉ መጨረሻ እንዴት እንደነበር ያዩ ዘንድ በምድር ላይ አልሄዱምን? አላህ ያላቸውን ሁሉ አጠፋባቸው። ለካሓዲያንም ሁሉ የዚሁ ተመሳሳይ አለባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 11, '11. ይህ አላህ የእነዚያ ያመኑት ረዳት ስለሆነና ከሓዲያንም ለእነርሱ ረዳት ስሌላቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 12, '12. አላህ እነዚያን በእሱ ያመኑትንና መልካሞችን ተግባራት የሰሩትን ሁሉ ከስሮቻቸው ወንዞች ወደ ሚፈሱባቸው ገነቶች ያስገባቸዋል:: እነዚያም በአላህ የካዱት በቅርቢቱ ዓለም ብቻ ይጣቀማሉ። እንሰሳዎች እንደሚበሉም ይበላሉ:: የገሀነም እሳትም ለእነርሱ (የሁል ጊዜ) መኖሪያቸው ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዚያች አንተን ካወጣችህ ከተማህ ይበልጥ በሀይል ጠንካራ የሆኑ ባለቤቶቻቸዉን ያጠፋናቸው ብዙ ናቸው:: ለእነርሱም ረዳት አልነበራቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 14, '14. ከጌታው በሆነች አስረጅ ላይ የሆነ ምዕመን ክፉ ስራቸው ለእነርሱ እንደተሸለመላቸውና ዝንባሌዎቻቸውን እንደ ተከተሉ ክፍሎች ነውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 15, '15. ያች አላህን ለሚፈሩ ሰዎች ቃል የተገባችው ገነት (ይህን ትመስላለች)፤ በውስጧ ሽታው ከማይለወጥ የውሃ ወንዞች፤ ጣዕሙ የማይለወጥ የወተት ወንዞች፤ ለጠጪዎች ሁሉ እጅግ ጣፋጭ የሆኑ የወይን ጠጅ ወንዞችና የንጹህ(የተነጠረ) ማር ወንዞች አሉባት:: በውስጧ ሁሉም የፍራፍሬ አይነቶች ከጌታቸዉም ምህረት ተዘጋጅተውላቸዋል:: በእነዚህ ገነቶች የሆነ እንደነዚያ እሳት ውስጥ ዘወትር እንደሚኖሩ የፈላ ውሃም እንዲጠጡ እንደሚደረጉትና ውሃዉም የሆድ ዕቃቸውን እንደሚበጣጥስባቸው ነውን? አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 16, '16. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም መካከል ወደ አንተ የሚያዳምጡ አሉ:: ካንተ ዘንድ በወጡ ጊዜ ለእነዚያ እውቀት ለተሰጡት «አሁን ምን አለ?» ይላሉ:: እነዚያ እነዚህ በልቦቻቸው ላይ አላህ ያተማቸው ዝንባሌዎቻቸውን የተከተሉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 17, '17. እነዚያም ወደ ቀናው መንገድ የተመሩት አላህ መመራትን ጨመረላቸው:: (ከእሳት) መጠበቂያቸውንም ሰጣቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 18, '18. የሰዓቲቱንም በድንገት መምጣት እንጂ ሌላን ይጠባበቃሉን? ምልክቶቿም በእርግጥ መጥተዋል:: በመጣችባቸዉም ጊዜ ማስታወሳቸው ለእነርሱ እንዴት ይጠቅማቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 19, '19. (መልዕክተኛችን ሙሐመድ ሆይ!) እነሆ ከአላህ ሌላ ትክክለኛ አምላክ አለመኖሩንም እወቅ:: ስለ ስህተትህም ሆነ ለወንድም ለሴትም አማኞች ስህተት ምህረትን ለምን:: አላህም መዘዋወሪያችሁንም ሆነ መርጊያችሁን ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ያመኑት ሰዎች (ለዲን ለመታገል ግፊት ያለበት)« የቁርኣን ምዕራፍ አይወረድም ኖሯልን?» ይላሉ:: የጠነከረም ምዕራፍ በወረደና በውስጡም መጋደል በተወሳ ጊዜ እነዚያን በልቦቻቸው ውስጥ የንፍቅና በሽታ ያለባቸውን ሰዎች ከሞት የሆነ መከራ በእርሱ ላይ እንደወደቀበት ሰው አስተያያት ወደ አንተ ሲመለከቱ ታያቸዋለህ:: ለእነርሱው ተገባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 21, '21. ታዛዥነትና መልካም ንግግር ይሻላቸዋል:: ትዕዛዙም ቁርጥ በሆነ ጊዜ ለአላህ ትእዛዝ እውነተኞች በሆኑ ኖሮ ለእነርሱ የተሻለ በሆነ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 22, '22. ብትሾሙም በምድር ላይ ማበላሸትን ዝምድናችሁንም መቁረጥን ከጀላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 23, '23. እነዚህ እነዚያ አላህ የረገማቸው ያደነቆራቸዉም ዓይኖቻቸውንም ያወራቸው ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 24, '24. ቁርኣንንም አያስተነትኑምን? በእውነቱ በልቦቻቸው ላይ ቁልፎቿ አሉባቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 25, '25. እነዚያ ለእነርሱ ቅኑው መንገድ ከተብራራላቸው በኋላ ወደ ኋላቸው የተመለሱት ሰይጣን መቀልበሳቸውን ለእነርሱ ሸለመላቸው:: ለእነርሱም አዘናጋቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 26, '26. ይህ እነርሱ ለእነዚያ አላህ ያወረደውን ለጠሉት «በነገሩ ከፊሉን እንታዘዛችኃለን» ያሉ በመሆናቸው ነው:: አላህም መደበቂያቸውንም ያውቃል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 27, '27. መላዕክት ፊቶቻቸውንና ጀርባዎቻቸውን የሚመቱ ሲሆኑ በገደሏቸው ጊዜ (ሁኔታቸው እንዴት ይሆናል?)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 28, '28. ይህ እነርሱ አላህን ያስቆጣውን ነገር ሁሉ ስለተከተሉ ውዴታውንም ስለጠሉ ነው:: ስለዚህ ስራዎቻቸውን አበላሸባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 29, '29. እነዚያ በልቦቻቸው ውስጥ በሽታ ያለባቸው ሰዎች በሙስሊሞች ላይ የነበራቸዉን ቂሞቻቸውን አላህ አለማውጣቱን ጠረጠሩን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 30, '30. (ሙሐመድ ሆይ!) ብንፈልግ ኖሮ እነርሱን ባሳየንህና በምልክታቸዉም በእርግጥ ባወቅካቸው ነበር:: ንግግርንም በማሸሞራቸው በእርግጥ ታውቃቸዋለህ:: አላህም ስራዎቻችሁን ሁሉ ያውቃልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 31, '31. (አማኞች ሆይ!) ከናንተ መካከል ተዋጊዎችንና ታጋሾቹን እስከምንገልጽ ድረስ በእርግጥ እንሞክራችኋለን:: ወሬዎቻችሁንም (እስከምንገልጽ ድረስ) እንሞክራችኋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 32, '32. እነዚያ የካዱና ከአላህም መንገድ ሰዎችን ያገዱ ለእነርሱም ቅኑ መንገድ ከተገለጸላቸው በኋላ መልዕክተኛውን የተከራከሩ ሁሉ አላህን በምንም አይጎዱትም:: ስራዎቻቸውንም በእርግጥ ያበላሻል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 33, '33. እናንተ ያመናችሁ ሆይ! አላህን ተገዙ:: መልዕክተኛውንም ታዘዙ:: ስራዎቻችሁንም አታበላሹ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 34, '34. እነዚያ የካዱ ከአላህ መንገድ ሌሎችን ያገዱና ከዚያም እነርሱ ከሓዲያን ሆነው የሞቱ አላህ ለእነርሱ በፍጹም አይምርም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 35, '35. እናንተ አሸናፊዎች ስትሆኑና አላህም ከናንተ ጋር ሲሆን አትድከሙ:: ወደ እርቅም አትጥሩ:: ስራዎቻችሁን ፈጽሞ አያጎድልባችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 36, '36. ቅርቢቱ ሕይወት ጫወታና ዛዛታ ብቻ ናት:: ብታምኑና ቅጣቱንም ብትጠነቀቁ ምንዳዎቻችሁን ይሰጣችኋል:: ገንዘቦቻችሁንም ሁሉ አይጠይቃችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 37, '37. እርሷን ቢጠይቃችሁና ችክ ቢልባችሁ ትሰስታላችሁ:: ቂሞቻችሁንም ያወጣል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (47, 38, '38. (አማኞች ሆይ!) አስተውሉ:: እናንተ እነዚያ በአላህ መንገድ ትለግሱ ዘንድ የምትጠሩ ናችሁ:: ከናንተም መካከልም የሚሰስት ሰው አለ:: የሚሰስት ሰው ሁሉ የሚሰስተው በራሱ ላይ ብቻ ነው:: አላህ በራሱ ተብቃቂ ነውና:: እናንተ ግን ድሆች ናችሁ:: ብትሸሹም ሌሎችን ሀዝቦች በቦታችሁ ይለውጣል:: ከዚያም ባለመታዘዝ እንደናንተ ብጤዎቻችሁ አይሆኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ ላንተ (መካን) በመክፈት ግልጽ የሆነን ድል ለገስንህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 2, '2. አላህ ያለፈውንና የሚመጣውን ኃጢአትክን ሊምርህ፤ ፀጋውንም ባንተ ላይ ሊሞላና ቀጥተኛዉን መንገድ ሊመራህ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 3, '3. አላህም ብርቱን እርዳታ ሊረዳህ መካን ከፈተልህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 4, '4. አላህ ያ በአማኞች ልቦች ውስጥ ከእምነታቸው ጋር እምነትን ይጨምሩ ዘንድ እርጋታን ያወረደ ነው:: አላህ የሰማይና የምድር ስራዊት ሁሉ የሱ ብቻ ነው:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 5, '5. ወንድ አማኞችና ሴት ምዕመናትን በስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘወታሪዎች ሲሆኑ ሊያስገባቸው፤ ከነርሱም ሐጢያቶቻቸዉን ሊያብስላቸው (መካን ከፈተልህ):: ይህም ከአላህ ዘንድ የሆነ ታላቅ መታደል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 6, '6. በአላህም ክፉ ጥርጣሬን ወንድ ተጣራጣሪ አስመሳዮችንና ሴት አስመሳዮችን ወንድ አጋሪዎችና ሴት አጋሪዎችን ያሰቃይም ዘንድ (በትግል አዘዘ):: በእነርሱ ላይ ክፉ ከባቢ አለባቸው:: በእነርሱ ላይ አላህ ተቆጣባቸው ረገማቸዉም:: ለእነርሱ ገሀነምን አዘጋጀላቸው:: ገሀነም መመለሻነቷም ከፋች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 7, '7. ለአላህ የሰማያትና የምድር ሰራዊቶች አሉት:: አላህ ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 8, '8. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ መስካሪ፤ አብሳሪና አስፈራሪ አድርገን በእርግጥ ላክንህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 9, '9. በአላህ ልታምኑ። በመልዕክተኛዉም ልታምኑ፤ ልትረዱትና ልታከብሩት፤ አላህንም በጠዋትና ከቀትር በኋላ ልታወድሱት (ላክንህ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ቃል ኪዳን የሚጋቡህ ቃል ኪዳን የሚጋቡት አላህን ብቻ ነው:: የአላህ እጅ ከእጆቻቸው በላይ ነው:: ያፈረሰም ሰው የሚያፈርሰው በነፍሱ ላይ ብቻ ነው:: በእርሱ ላይ አላህን ቃል ኪዳን የተጋባበትን የሞላ ሰው ታላቅ ምንዳ በእርግጥ ይሰጠዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ!) ከዐረብ ዘላኖች መካከል እነዚያ ከዘመቻ ወደ ኋላ የቀሩት «ገንዘቦቻችንና ቤተሰቦቻችን አስቸግረዉን ስለነበር ነውና (የቀረነው) ምህረትን ለምንልን» ይሉሃል:: በልቦቻቸው ውስጥ የሌለውን ነገር በምላሶቻቸው ይናገራሉ:: «አላህ እናንተን መጉዳትም ሆነ መጥቀም ቢፈልግ ከአላህ ለእናተ አንዳችን ለመከላከል የሚችል ማን ነው? በእውነቱ አላህ ለምትሰሩት ነገር ሁሉ ውስጠ አዋቂ ነው።» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 12, '12. ይልቁንም መልዕክተኛውና ምዕመናኖቹ ወደየቤተሰቦቻቸው ፈጽሞ አለመመለሳቸውን እርግጠኞች (ተጠራጣሪዎች) ስለነበራችሁ ነው። ይህም በልቦቻችሁ ውስጥ ተሸለመላችሁ:: መጥፎንም መጠርጠር ጠረጠራችሁ ጠፊዎች ህዝቦችም ሆናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 13, '13. በአላህና በመልዕክተኛው ላለመነ ሰው እኛ ለከሓዲያን እሳትን አዘጋጅተናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 14, '14. የሰማያትና የምድር ንግስና የአላህ ብቻ ነው:: የሚፈልገውን ወደ ቀናው ይመራል:: የሚፈልገውንም ሰው ይቀጣል:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 15, '15. ከጠላት የተማረኩትን ገንዘቦች ልትይዙ በሄዳችሁ ጊዜ እነዚያ ወደ ኋላ የቀሩት ሰዎች «ተውን እንከተላችሁ» ይሏችኋል:: በዚህም የአላህን ቃል ሊለውጡ ይፈልጋሉ:: «ፈጽሞ አትከተሉንም:: ልክ እንደዚሃችሁ ቃል የመሰለ ከዚህ በፊት አላህም ብሏል» በሏቸው:: «ይልቁንም ትመቀኙናላችሁ» ይላሉም:: በእውነት እነርሱም ጥቂትን እንጂ የማያውቁ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 16, '16. ዘላኖች (ከአዕራቦች) ወደ ኋላ ለቀሩት (እንዲህ) በላቸው: «የብርቱ ጭካኔ ባለቤት ወደ ሆኑ ህዝቦች ውጊያ ወደ ፊት ትጠራላችሁ፤ ትጋደሏቸዋላችሁ:: ወይም ይሰልማሉ ብትታዘዙም አላህ መልካም ምንዳን ይሰጣችኋል:: ከአሁን በፊት እንደ ሸሻችሁ ብትሸሹ ደግሞ አሳማሚ ቅጣት ይቀጣችኋል::»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 17, '17. (ሰዎች ሆይ!) በአይነስውር ላይ (ከዘመቻ በመቅረቱ) ኃጢአት የለበትም:: በአንካሳ ላይም ኃጢአት የለበትም:: በበሽተኛም ላይ ኃጢአት የለበትም:: አላህንና መልዕክተኛውን የሚታዘዝ ሁሉ ከስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች ያስገባዋል:: የሚያፈገፍገዉንም ሁሉ አሳማሚ ቅጣት ይቀጣዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 18, '18. (መልዕክተኛችን ሙሐመድ ሆይ!) ከምዕመናኖቹ በዛፊቱ ስር ቃል ኪዳን በሚጋቡህ ጊዜ አላህ በእርግጥ ስራቸዉን ወደደላቸው:: በልቦቻቸዉም ውስጥ ያለውን ዐወቀ:: በነሱም ላይ እርጋታን አወረደ:: ቅርብ የሆነንም መክፈት መነዳቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 19, '19. ብዙዎች የተማረኩትን ገንዘቦች የሚወስዷቸው የሆኑን መነዳቸው:: አላህም ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 20, '20. (አማኞች ሆይ!) አላህ ብዙዎቹን ምርኮዎች የምትወስዷቸው የሆኑን አላህ ቃል ገባላችሁ። ይህንንም ለእናንተ አስቸኮለላቻችሁ:: ከናንተም የሰዎችን እጆች ሠበሰበላችሁ። ብታመሰግኑና ለአማኞችም መልዕክት እንድትሆን ቀጥተኛውን መንገድ ይመራችሁም ዘንድ ይህን አደረግንላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 21, '21. ሌላይቱንም በእርሷ ላይ ገና ያልቻላችኋትን አላህ ያወቃትን ለእናንተ አዘጋጅቷል:: አላህ በነገሩ ሁሉ ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 22, '22. እነዚያም የካዱት (የመካ ሰዎች) በተዋጓችሁ ኖሮ ለሽሽት ጀርባዎችን ባዞሩ ነበር:: ከዚያ ዘመድም ረዳትም አያገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 23, '23. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ ያችን ከዚህ በፊት በእርግጥ ያለችፈውን ልማድ ደነገገ:: ለአላህ ልማድ መቸም ለውጥን አታገኝም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 24, '24. እርሱ(አላህ) ያ በመካ ውስጥ በእነርሱ ላይ ካስቻላችሁ በኋላ እጆቻቸዉን ከእናንተ ላይ እጆቻችሁንም ከእነርሱ ላይ የከለከለ ነው:: አላህም የምትሰሩትን ነገር ሁሉ ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 25, '25. እነርሱ ማለት እነዚያ በአላህ የካዱ፤ ከተከበረው መስጊድም የከለከሏችሁ መስዋዕትንም የታሰረ ሲሆን ወደ ስፍራው እንዳይደርስ የከለከሉ ናቸው:: የማታውቋቸው ወንድ አማኞችና ሴት ምዕመናት ከከሓዲያኑ ጋር ባልነበሩ ኖሮና እናንተም ያለ እውቀት እነርሱን ረግጣችሁ ከእነርሱ (በኩል) መከፋት የሚነካችሁ ባይሆን ኖሮ እጆቻችሁን ባላገድን ነበር:: አላህም የሚፈልገውን ሰው በእዝነቱ ውስጥ ያስገባ ዘንድ (እጆቻችሁን አገደ):: በተለዩ ኖሮ እነዚያን ከእርሱ ውስጥ በአላህ የካዱትን አሳማሚን ቅጣት በቀጣናቸው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 26, '26. እነዚያን በአላህ የካዱት ደራይቱን (እልህን) የመሀይምነቲቱን ደራ (እልህ) በልቦቻቸው ውስጥ ባደረጉ ጊዜ በቀጣናቸው ነበር:: አላህም በመልዕክተኛው ላይ እና በምዕመናኖቹ ላይ እርጋታውን አወረደ:: መጠበቂያይቱንም ቃል አስያዛቸው:: በእርሷም ተገቢዎች ባለቤቶቿም ነበሩ:: አላህም በነገሩ ሁሉ አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 27, '27. ህልሙ እውነተኛ ሲሆን አላህ የፈለገ አንደሆነ ጸጥተኞች ሆናችሁ ራሳችሁን ላጭታችሁ አሳጥራችሁ የማትፈሩ ስትሆኑ የተከበረውን መስጊድ በእርግጥ ትገባላችሁ ያለውን ህልም አሏህ ለመልዕክተኛው(ለሙሀመድ) እውነት አደረገለት:: አላህ (ከእርቁ) ከመመለሳችሁ ሂደት ያላወቃችሁትንም ነገር አወቀ:: እናም ከዚህ በፊት ቅርብን የመክፈት እርቅ አደረገ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 28, '28. እርሱ (አላህ) ያ መልዕክተኛውን (ነብዩ ሙሐመድን) በመሪ መጽሐፍና በእውነተኛ ሀይማኖት በሁሉ ላይ ሊያልቀው (የበላይ ሊያደርገው) የላከ ነው:: መስካሪነትም አላህ በቃ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (48, 29, '29. የአላህ መልዕክተኛ (ነብዩ) ሙሐመድ እና እነዚያም የእርሱ ጓደኞች በከሓዲያን ላይ ብርቱዎች በመካከላቸው ተዛዛኞች ናቸው:: አጎንባሾች፤ ሰጋጆች፤ ሆነው ታያቸዋልህ:: ችሮታንና ውዴታን ሁልጊዜም ከአላህ ይፈልጋሉ:: ምልክታቸው ከስግደታቸው ፈለግ ስትሆን በፊታቸው ላይ ናት:: ይህ በተውራት (የተነገረላቸው) ጸባያቸው ነው:: በኢንጅል ውስጥ የተጠቀሰው ምሳሌያቸው ደግሞ ቀንዘሉን እንደ አወጣ አዝመራና (ቀንዘሉን) እንዳበረታው እንደ ወፍራምና ገበሬዎቹን የሚያስደነቅ ሆኖ አገዳዎቹ ላይ ተስተካክሎ እንደቆመ (አዝመራ) ነው:: ያበረታቸውና ከሓዲያን በእርሱ ሊያሰቆጭ ነው:: አላህ እነዚያን በእሱ ያመኑትንና ከእነርሱ በጎዎችን ተግባራት የሰሩትን ሁሉ ምህረትንና ታላቅ ምንዳን ቃል ገበቶላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 1, '1. እናንተ ያመናችሁ ሆይ! በአላህና በመልዕክተኛው ፊት ነፍሶቻችሁን አታስቀድሙ:: አላህንም ፍሩ:: አላህ ለሚባለው ሁሉ ሰሚ ለሚፈጸመው ነገር ሁሉ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 2, '2. እናንተ ያመናችሁ ሆይ! ድምፆቻችሁን ከነብዩ ድምጽ በላይ ከፍ አታድርጉ:: ከፊላችሁ ለከፊሉ እንደሚጮህም ሁሉ በንግግር ለርሱ ስትናገሩ አትጩሁ:: እናንተ የማታውቁ ስትሆኑ ስራዎቻችሁ እንዳይበላሹ (ከዚህ ተከልከሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 3, '3. እነዚያ በአላህ መልዕክተኛ ዘንድ ድምፆቻቸውን ዝቅ የሚያደርጉ እነዚህ እነዚያ አላህ ልቦቻቸውን ለፍርሃት የፈተናቸው ናቸው:: ለእነርሱም ምህረትና ታላቅ ምንዳ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 4, '4. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ ከመኖሪያ ክፍሎቹ ውጭ ሆነው የሚጠሩህ አብዛሀኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 5, '5. ወደ እነርሱም እስክትወጣ ድረስ ዝምብለው በታገሱ ኖሮ ለእነርሱ በላጭ በሆነ ነበር:: አላህም እጅግ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 6, '6. እናንተ ያመናችሁ ሆይ! ነገረኛ ወሬ ቢያመጣላችሁ በስህተት ላይ ሆናችሁ ህዝባችሁን እንዳትጎዱና ከዚያም በሰራችሁት ነገር ላይ ተጸፃቾች እንዳትሆኑ አረጋግጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 7, '7. በውስጣችሁም የአላህ መልዕክተኛ መኖሩን እወቁ:: ከነገሩ በብዙው ነገሮች ቢከተላችሁ ኖሮ በእርግጥ በተቸገራችሁ ነበር:: ግን አላህ እምነትን ወደ እናንተ አስወደደ :: በልቦቻችሁም ውስጥ አስዋበው። ክህደትን፣ አመፅንና እምቢተኝነትንም ለናንተ የተጠላ አደረገ። እነዚያ እምነትን የወደዱና ክሕደትን የጠሉ ሰዎች እነርሱ ትክክለኛ ቅኖቹ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 8, '8. ከአላህ በሆነው ችሮታና ጸጋ ሲሆን ቅኖች ናቸው። አላህ ሁሉን አዋቂና ጥበበኛ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 9, '9. ሁለት የምዕምናን ቡድኖች እርስ በእርስ ቢጋደሉ በመካከላቸው አስታርቁ:: ከሁለት አንደኛይቱ በሌላኛይቱ ላይ ወሰን ብታልፍ ያችን ወሰን የምታልፈውን ወደ አላህ ትዕዛዝ እስከምትመጣ ድረስ ተጋደሏት፤ ብትመለስ ግን በመካከላቸው በትክክል አስታርቁ:: በነገሩ ሁሉ አስተካክሉ:: አላህ አስተካካዮችን ይወዳልና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 10, '10.(አማኞች ሆይ!) ምዕመናኖች ወንድማማቾች ናቸውና በሁለት ወንድሞቻችሁ መካከል አስታርቁ:: ይታዘንላችሁም ዘንድ አላህን ፍሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 11, '11.እናንተ ያመናችሁ ሆይ! ወንዶች በወንዶች አይሳለቁ:: ከእነርሱ የበለጡ ሊሆኑ ይከጀላልና:: ሴቶችም በሴቶች አይሳለቁ:: ከእነርሱ የበለጡ ሊሆኑ ይከጀላልና:: ነፍሶቻችሁንም አታነዉሩ በመጥፎ ሰሞችም አትጠራሩ:: ከእምነት በኋላ መጥፎ ስም ከፋ:: ያልተጸጸተ ሰው በእውነት እነርሱ በዳዮቹ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 12, '12. እናንተ ያመናችሁ ሆይ! ከጥርጣሬ ብዙን ራቁ:: ከጥርጣሬ ከፊሉ ኃጢአት ነውና:: ነውርንም አትከታተሉ። ከፊላችሁም ከፊሉን አይማው። አንደኛችሁ የወንድሙን ስጋ የሞተ ሆኖ ሊበላ ይወዳልን? (መብላቱን) ጠላችሁት (ሀሜቱንም ጥሉት):: አላህንም ፍሩ:: አላህ ጸጸትን ተቀባይና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 13, '13. እናንተ ሰዎች ሆይ! እኛ ከወንድና ከሴት ፈጠርናችሁ:: እንድትተዋወቁም ጎሳዎችና ነገዶች አደረግናችሁ:: አላህ ዘንድ በላጫችሁ በጣም አላህን ፈሪያችሁ ብቻ ነው:: አላህ ግልጽን አዋቂ ውስጥንም አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 14, '14. (መልዕክተኛችን ሙሐመድ ሆይ!) የዐረብ ዘላኖች አምነናል አሉ:: «አላመናችሁም ግን ሰልመናል በሉ እምነቱም በልቦቻችሁ ውስጥ ገና ጠልቆ አልገባም:: አላህንና መልዕክተኛውን ብትታዘዙ ከስራዎቻችሁ ምንም አይጎድልባችሁም:: አላህ መሀሪና አዛኝ ነውና» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 15, '15. አማኞች እነዚያ በአላህና በመልዕክተኛው ያመኑትና ከዚያም ያልተጠራጠሩት በገንዘቦቻቸውና በነፍሶቻቸዉም በአላህ መንገድ ላይ የታገሉት ሰዎች ብቻ ናቸው:: እነዚያ እነርሱ እውነተኞቹ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 16, '16. (መልዕክተኛችን ሙሐመድ ሆይ!) «አላህ በሰማያት ውስጥ ያለውንና በምድር ውስጥ ያለውን ሁሉ የሚያውቅ ሲሆን አላህን በሃይማኖታችሁ ታስታውቁታላችሁን?» በላቸው:: አላህም በነገሩ ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) በመስለማቸው ባንተ ላይ ይመፃደቃሉ። «በእስልምናችሁ በእኔ ላይ አትመጻደቁ:: ይልቁንም አላህ ወደ ትክክለኛው እምነት ስለመራችሁ ፀጋውን ውሎላችኋል:: እውነተኞች ብትሆኑ (መመፃደቅ የሚገባው ለአላህ) ብቻ ነው» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (49, 18, '18. አላህ የሰማያትንና የምድርን ሩቅ ሚስጥር ሁሉ ያውቃል:: አላህ የምትሰሩትን ሁሉ ተመልካችም ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 1, '1. ቃፍ ፤ በተከበረው ቁርኣን እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 2, '2. ይልቁንም ከእነርሱ መካከል የሆነ አስፈራሪ ስለ መጣላቸው ተደነቁ:: ከሓዲያንም አሉ: «ይህ አስደናቂ ነገር ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 3, '3. «በሞትንና አፈር በሆንን ጊዜ እንመለሳለንን? ይህ ሩቅ የሆነ መመለስ ነው።» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 4, '4. ከእነርሱ አካል ምድር የምታጎድለውን በእርግጥ አውቀናል:: እኛም ዘንድ ጠባቂ መጽሐፍ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 5, '5. ይልቁንም ቁርኣን በመጣላቸው ጊዜ አስተባበሉ። እነርሱም በተምታታ ነገር ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 6, '6. ወደ ሰማይም ከበላያቸው ስትሆን ለእርሷ ምንም ቀዳዳዎች የሌሏቸው ሆነው እንዴት እንደገነባናትና በከዋክብት እንዳጌጥናት አልተመለከቱምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 7, '7. ምድርም ዘረጋናት በእርሷም ውስጥ ጋራዎችን ጣልንባት :: በውስጧም ከሚያስደስት አይነት ሁሉ አበቀልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 8, '8. ይህንን ያደረግነው ተመላሽ ለሆነ ባሪያ ሁሉ ለማሳየትና ለማስገንዘብ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 9, '9. ከሰማይም ብሩክን ውሃ አወረድን በእርሱም አትክልቶችንና የሚታጨድን አዝመራ ፍሬ አበቀልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 10, '10. ዘንባባንም ረዣዥም ለእርሷ የተደራረበ እንቡጥ ያላት ስትሆን አበቀልን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 11, '11. ለባሮቹ ሲሳይ ትሆን ዘንድ (አዘጋጀናት):: በእርሱም የሞተችን ሀገር ሕያው አደረግንበት:: ከመቃብር መውጣትም ልክ እንደዚሁ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 12, '12. ከእነርሱ በፊት የኑህ ህዝቦችና የረስስ ሰዎችም ሰሙድም አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 13, '13. ዓድም ፈርዖንም የሉጥ ወንድሞችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 14, '14. የጫካው ባለቤቶችም የቱብበዕ ህዝቦችም ሁሉ መልዕክተኞችን አስተባበሉ:: ዛቻየም ተረጋገጠባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 15, '15. በመጀመሪያው መፍጠር ደከምን? በእውነቱ እነርሱ ከአዲስ መፍጠር በመጠራጠር ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 16, '16. ሰውንም ነፍሱ በሀሳቡ የምታጫውተውን የምናውቅ ስንሆን ፈጠርነው:: እኛም ከደም ጋኑ ጅማት ይበልጥ ወደ እርሱ ቅርብ ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 17, '17-ሁለት ቃል ተቀባዮች መላዕክት ከቀኝና ከግራ ተቀማጮች ሆነው በሚቀበሉ ጊዜ አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 18, '18. ከቃል ምንም አይናገርም ከአጠገቡ ተጠባባቂ እና ዝግጁ የሆኑ መላዕክት ያሉበት ቢሆን እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 19, '19. የሞትም መከራ እውነቱን ነገር ታመጣለች። «(ሰው ሆይ!) ይህ ያ ከእርሱ ትሸሸው የነበርከው ነው» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 20, '20. በቀንዱም ውስጥ ይነፋል። ያ ቀን የዛቻው መፈጸሚያ ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 21, '21. ነፍስም ሁሉ ከእርሷ ጋር ነጅና መስካሪ ያለባት ሆና ትመጣለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 22, '22. «ከዚህ ነገር በእርግጥ የዘነጋህ ነበርክ። ሽፋንህንም ካንተ ላይ ገለጥንልህ:: ስለዚህ ዛሬ ዓይንህ ስለታም ነው» (ይባላል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 23, '23. ቁራኛዉም (መልዓክ) «ይህ ያ እኔ ዘንድ ያለው ቀራቢ ነው።» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 24, '24. (አላህም ይላል): «ሞገደኛ ከሓዲን ሁሉ በገሀነም ውስጥ ጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 25, '25. «ለበጎ ስራ ከልካይ በዳይ ተጠራጣሪ የሆነን ሁሉ ጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 26, '26. «ያንን ከአላህ ጋር ሌላን አምላክ ያደረገውን በብርቱ ቅጣት ውስጥ ጣሉት» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 27, '27. «ቁራኛው (ሰይጣን) ጌታችን ሆይ! እኔ አላሳሳትኩትም ግን ራሱ በሩቅ ስህተት ውስጥ ነበር» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 28, '28. (አላህም) ይላል: «ወደ እናተ ዛቻን በእርግጥ ያስቀደምኩ ስሆን እኔ ዘንድ አትጨቃጨቁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 29, '29. «ቃሉ እኔ ዘንድ አይለወጥም እኔም ለባሮቼ ፈጽሞ በዳይ አይደለሁም» (ይላቸዋል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) ለገሀነም «ሞላሽን?» የምንልበትንና (ገሀነምም) «ጭማሪ አለን?» የምትልበትን ቀን አስጠንቅቃቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 31, '31. ገነትም አላህን ለፈሩት ሁሉ ሩቅ ባልሆነ ስፍራ ትቀረባለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 32, '32. (ይባላሉም) «ይህ ወደ አላህ ተመላሽና ህግጋቱን ጠባቂ ለሆነ ሁሉ የተቀጠራችሁት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 33, '33. «አር-ረህማንን በሩቅ ሆኖ ለፈራና በተመላሽ ልብ ለመጣ ትቅቀረባለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 34, '34. «በሰላም ግቧታ ይህ የመዘውተሪያ ቀን ነው» (ይባላሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 35, '35. ለእነርሱ በውስጧ ሲሆኑ የሚሹት ሁሉ አላቸው እኛም ዘንድ ጭማሪ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 36, '36. ከእነርሱም (ከቁረይሾች) በፊት ከክፍለ ዘመናት ህዝቦች በሀያልነት ከእነርሱ ይበልጥ የበረቱ ሆነው ማምለጫ ፍለጋ በየሀገሮቹ የመረመሩ ብዙዎችንም አጥፍተናል። ማምለጫ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 37, '37. በዚሁ ውስጥ ልብ ላለው ወይም እርሱ በህሊናው ጆሮውን የሰጠ ሆኖ ወደ ሚነበብለት ጆሮውን ለጣለ ሰው ሁሉ ግሳጼ አለበት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 38, '38. ሰማያትንና ምድርን በመካከላቸው ያለውንም ሁሉ በስድስት ቀናት ውስጥ በእርግጥ ፈጠርን። ድካምም ምንም አልነካንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 39, '39. (መልዕክተኛችን ሙሐመድ ሆይ!) በሚሉትም ላይ ታገስ ጌታህንም ከማመስገን ጋር ጸሐይ ከመውጣቷ በፊትና ከመገባቷም በፊት አጥራው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 40, '40. ከሌሊትም አጥራው፤ ከስግደቶችም በኋላዎች አጥራው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 41, '41. (መልዕክተኛችን ሙሐመድ ሆይ!) (የሚነገርህን) አዳምጥም፤ ጠሪው ከቅርብ ስፍራ በሚጠራበት ቀን ከመቃብራቸው ይወጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 42, '42. ጩኸቲቱን በእውነቱ የሚሰሙበት ቀን፤ ያ ከመቃብር የመውጫው ቀን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 43, '43. እኛው ሕያው እናደርጋለን:: እንገድላለንም:: በመጨረሻም ጊዜ መመለሻው ወደ እኛ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 44, '44. የሚፈጥኑ ሆነው ምድር ከእነርሱ ላይ የምትሰነጣጠቅበት ቀን (የመውጫ ቀን ነው):: ይህ በእኛ ላይ ገር የሆነ መሰብሰብ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (50, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ የሚሉትን ሁሉ አዋቂ ነን:: አንተም በእነርሱ ላይ አሰገዳጅ አይደለህም:: ስለዚህ ዛቻየን የሚፈራን ሰው ሁሉ በቁርኣን አስታውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 1, '1. መበተንን በታኝ በሆኑት (ንፋሶች) እምላለሁ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 2, '2. ከባድ ዝናብን ተሸካሚዎች በሆኑትም (ዳመናዎች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 3, '3. ገር መንሻለልን ተንሻላዩች በሆኑትም (መርከቦች) እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 4, '4. ጉዳይን ሁሉ አከፋፋዮች በሆኑትም (መላዕክት) እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 5, '5. የምተቀጠሩት ትንሳኤ እውነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 6, '6. (እንደየስራው) ዋጋን ማግኘትም የማይቀር ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 7, '7.የ(ከዋክብት) መንገዶች ባለቤት በሆነችው ሰማይ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 8, '8. እናንተ በተለያየ ቃል ውስጥ ናችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 9, '9. ከእርሱ የሚዝዞር ሰው ይዝዞራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 10, '10. በግምት የሚናገሩ ውሸታሞች ተረገሙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 11, '11. እነዚያ እነርሱ በሚሸፍን ስህተት ውስጥ ዘንጊዎች የሆኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 12, '12. የዋጋ መስጫው ቀን መቼ እንደሆነ ይጠይቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 13, '13. (እነርሱ) በእሳት ላይ በሚፈተኑበት ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 14, '14. «መከራችሁን ቅመሱ ይህ ያ በእርሱ ትቻኮሉበት የነበራችሁት ነው» (ይባላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 15, '15. አላህን ፈሪዎቹ በአትክልቶችና በምንጮች ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 16, '16. ያንን ጌታቸው የሰጣቸውን ተቀባዮች ሆነው በገነት ውስጥ ይሆናሉ:: እነርሱ ከዚህ በፊት መልካም ሰሪዎች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 17, '17. ከሌሊቱ ጥቂቱን ብቻ ይተኙ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 18, '18. በሌሊቱ መጨረሻዎችም እነርሱ ምህረትን ይለምናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 19, '19. በገንዘቦቻቸዉም ውስጥ ለለማኝና ከልመና ለተከለከለም (በችሮታቸው) መብት አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 20, '20. በምድርም ውስጥ ለሚያረጋግጡ ሰዎች አያሌ ምልክቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 21, '21. (ሰዎች ሆይ!) በነፍሶቻችሁም ውስጥ አያሌ ምልክቶች አሉ:: ታዲያ አትመለከቱምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 22, '22. ሲሳያችሁም የምትቀጠሩት (ፍዳና ምንዳ) በሰማይ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 23, '23. በሰማይና በምድር ጌታም እምላለሁ። እርሱ እናንተ እንደምትናገሩት ብጤ እርግጠኛ (እውነት) ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) የተከበሩት የኢብራሂም እንግዶች ወሬ መጥቶሃልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 25, '25. በእርሱም ላይ በገቡና «ሰላም» ባሉት ጊዜ ምን እንደሆነ አስታውስ። ሰላም ግና ያልታወቃችሁ ህዝቦች ናችሁ አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 26, '26. ወደ ቤተሰቡም ተዘነበለና ወዲያውም የሰባ ወይፈን አመጣ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 27, '27. ከዚያ ወደ እነርሱ (አዘጋጅቶ) አቀረበውና «አትበሉም ወይ? አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 28, '28. ከእነርሱ መፍራትን በልቡ አሳደረ። «አትፍራ» አሉትም በአዋቂ ልጅም አበስሩት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 29, '29. ሚስቱም (በደስታ) እየጮኸች መጣች፤ ፊቷንም መታች «መካን አሮጊት (ነኝ)» አለችም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 30, '30. እነርሱም «ጌታሽ ''እንዲሁ (ይሁን)'' ብሏል። እነሆ እርሱ ጥበበኛና ሁሉን አዋቂ ነው» አሏት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 31, '31. «እናንተ መልዕክተኞች ሆይ! ታዲያ ነገራችሁ ምንድን ነው?» አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 32, '32. እነርሱም አሉ: «እኛ ወደ አመጸኖች ህዝቦች ተልከናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 33, '33. «በእነርሱ ላይ ከጭቃ የሆኑ ድንጋዮችን ልንለቅባቸው ተላክን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 34, '34. «በጌታህ ዘንድ ለድንበር አላፊዎቹ በየስማቸው ምልክት የተደረገባት ስትሆን።» አሉ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 35, '35. ከምዕመናም በእርሷ በከተማቸው ውስጥ የነበሩትን አወጣን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 36, '36. በውስጧም ከአንድ ቤት ቤተሰቦች በስተቀር ሙስሊሞችን አላገኘንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 37, '37. በውስጧም ለእነዚያ አሳማሚውን ቅጣት ለሚፈሩት ምልክትን አስቀረን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 38, '38. በሙሳ ወሬ ውስጥም ወደ ፈርዖን በግልጽ ማስረጃ በላክነው ጊዜ (ምልክትን አደረግን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 39, '39. ከድጋፉ (ከሰራዊቱ) ጋርም ከእምነት ዞረ:: «እርሱ ድግምተኛ ወይም እብድ ነው» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 40, '40. እርሱንም ሰራዊቱንም ያዝናቸው እርሱ ተወቃሽ ሲሆን በባህር ውስጥ ጣልናቸውም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 41, '41. በዓድም በእነርሱ ላይ መካን (የሆነች) ንፋስን በላክን ጊዜ ምልክት አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 42, '42. በላዩ ላይ የመጣችበትን ማንኛዉንም ነገር እንደበሰበሰ አጥነት ያደረገችው ብትሆን እንጂ አትተወዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 43, '43. በሰሙድም ለእነርሱ «እስከ ጊዜ (ሞታችሁ) ድረስ ተጣቀሙ።» በተባሉ ጊዜ (ምልክት አለ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 44, '44. ከጌታቸው ትዕዘዝም ኮሩ:: እነርሱም እያዩ ጩኸቷ ያዘቻቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 45, '45. መቆምንም አልቻሉም:: እርዳታ የሚደረግላቸውም አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 46, '46. የኑህንም ህዝቦች (ከዚህ በፊት አጠፋን) እነርሱ አመጸኞች ህዝቦች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 47, '47. ሰማይንም በሀይል ገነባናት:: እኛም በእርግጥ የምናስፋት ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 48, '48. ምድርንም ዘረጋናት ምን ያማርንም ዘርጊዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 49, '49. ትገነዘቡም ዘንድ ከነገሩ ሁሉ ሁለት ተቃራኒ አይነትን ፈጠርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 50, '50. ወደ አላህም ሽሹ እኔ ለእናንተ ከእርሱ ግልጽ አስጠንቃቂ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 51, '51. ከአላህም ጋር ሌላን አምላክ አታድርጉ:: እኔ ለእናንተ ከእርሱ የተላኩ:: ግልጽ አስፈራሪ ነኝና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 52, '52. ልክ እንደዚሁ እነዚያ ከእነርሱ በፊት የነበሩትን ከመልዕክተኛ ማንም አልመጣቸዉም:: «እርሱ ድግምተኛ ወይም እብድ ነው» ያሉ ቢሆን እንጂ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 53, '53. በእርሱ (በዚህ ቃል) አደራ ተባብለዋልን? ይልቁን እነርሱ ጥጋበኞች ህዝቦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 54, '54. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም ዘወር በል (ተዋቸው)፤ አንተ ምንም ተወቃሽ አይደለህምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 55, '55. (መልዕክተኛችን ሙሐመድ ሆይ!) ገስጽም ግሳጼ አማኞችን ትጠቅማለችና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 56, '56. ጋኔንና ሰዉን ሊገዙኝ እንጂ ለሌላ አልፈጠርኳቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 57, '57. ከእነርሱም ምንም ሲሳይን አልፈልግም:: እንዲመግቡኝም አልፈልግም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 58, '58. አላህ ሰጪና የብርቱ ሀይል ባለቤት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 59, '59. ለእነዚያም ለበደሉት እንደ ጓደኞቻቸው ፋንታ ብጤ የቅጣት ፋንታ አለላቸው:: ስለዚህ አያስቸኩሉኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (51, 60, '60. ለእነዚያም ለካዱት ሰዎች ከዚያ ከሚቀጠሩት ቀናቸው ወዩላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 1, '1. በጡር (ጋራ)፤ እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 2, '2. በተጻፈው መጽሓፍም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 3, '3. በተዘረጋው ብራና ላይ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 4, '4. በደመቀው ቤትም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 5, '5. ከፍ በተደረገው ጣራም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 6, '6. በእሳት በተሞላው ባህርም እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህ ቅጣት በእርግጥ ወዳቂ ነው (የማይቀር ነው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 8, '8. ለእርሱ ምንም ገፍታሪ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 9, '9. ሰማይ ብርቱ መዞርን በምትዞርበት ቀን (ይሆናል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 10, '10. ተራራዎችም መሄድን በሚሄዱበት ቀን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 11, '11. ላስተባባዮችም ሁሉ ያን ጊዜ ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 12, '12. ለነዚያ ለእነርሱ በውሸት ውስጥ የሚጫወቱ ለሆኑት ሰዎች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 13, '13. ወደ ገሀነም እሳት በሀይል መገፍተርን በሚገፈተሩበት ቀን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 14, '14. «ይህች ያቺ በእርሷ ታስተባብሉባት የነበራችሁት እሳት ናት ይባላሉ»።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 15, '15. «ይህ (ፊት ትሉን እንደነበራችሁት) ድግምት ነውን? ወይስ እናንተ አታዩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 16, '16. «ግቧት ታገሱም ወይም አትታገሱ በእናንተ ላይ እኩል ነው:: የምትመነዱት ትሰሩት የነበራችሁትን ፍዳ ብቻ ነው» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 17, '17. አላህን ፈሪዎቹ በእርግጥ በገነቶችና በጸጋ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 18, '18. ጌታቸው በሰጣቸው ጸጋ ተደሳቾች ሆነው በገነት ውስጥ ናቸው:: የገሀነምንም ስቃይ ጌታቸው ጠበቃቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 19, '19. «ትሰሩት በነበራችሁት ምክንያት ተደሳቾች ሆናችሁ ብሉ ጠጡም» (ይባላሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 20, '20. በተደረደሩ አልጋዎች ላይ ተደጋፊዎች ሆነው በገነት ይኖራሉ:: አይናማዎች በሆኑ ነጫጭ ሴቶችም እናጠናዳቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 21, '21. እነዚያም በአላህ ያመኑና ዝርያቸዉም በእውነት የተከተለቻቸው ዝርያቸውን ከእነርሱ ጋር እናስጠጋቸዋለን:: ከስራዎቻቸዉም ምንንም አናጎድልባቸዉም:: ሰው ሁሉ በሰራው ስራ ተጠያቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 22, '22. ከሚሹትም ሁሉ እሸትንና ስጋን እንጨምርላቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 23, '23. በውስጧ መጠጥን ይሰጣጣሉ:: በውስጧ ውድቅ ንግግርና መወንጀልም የለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 24, '24. ለእነርሱም የሆኑ ወጣቶች ልክ የተሸፈነ ሉል መስለው በእነርሱ ላይ ለማሰላፍ ይዘዋወራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 25, '25. የሚጠያየቁ ሆነዉም ከፊላቸው በከፊሉ ላይ ይዞራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 26, '26. ይላሉም: «እኛ ፊት በቤተሰቦቻችን ውስጥ ከቅጣት ፈሪዎች ነበርን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 27, '27. «አላህ በእኛ ላይ ለገሰ:: የመርዛም እሳት ቅጣትንም ጠበቀን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 28, '28. «እኛ ከዚህ በፊት እንለምነው ነበርን:: እነሆ እርሱ በጎ ዋይ አዛኝ ነውና» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) (ሰዎችን) አስታውስ አንተም በጌታህ ጸጋ ምክንያት ጠንቋይም እብድም አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 30, '30. «ይልቁንም የሞትን አደጋ በእርሱ የምንጠባበቅበት የሆነ ባለ ቅኔ ነው» ይላሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 31, '31. (መልዕክተኛችን ሙሐመድ ሆይ!) «ተጠባበቁ እኔም ከናንተ ጋር ከሚጠባበቁት ነኝ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 32, '32. አእምሮዎቻቸው በዚህ ተግባር ያዟቸዋልን? ወይስ በእውነቱ እነርሱ ወሰን አላፊ ህዝቦች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 33, '33. ወይም «ቀጠፈው» ይላሉን? አይደለም። ይልቁንም አያምኑም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 34, '34. እውነተኞችም ከሆኑ መሰሉ የሆነን ንግግር ያምጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 35, '35. ወይስ ያለ አንዳች ፈጣሪ ተፈጠሩን? ወይስ እነርሱ ፈጣሪዎች ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 36, '36. ወይስ ሰማያትንና ምድርን ፈጠሩን? አይደለም፤ አያረጋግጡም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 37, '37. ወይስ የጌታህ ግምጃ ቤቶች እነርሱ ዘንድ ናቸውን? ወይስ እነርሱ አሸናፊዎች ናቸው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 38, '38. ወይስ ለእነርሱ በእርሱ ላይ ከሰማይ የሚያዳምጡበት መሰላል አላቸውን? (እንግዲያውስ) አድማጫቸዉ ሰማሁ የሚለውን ግልጽ አስረጂ ያምጣ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 39, '39. ወይስ ለእናንተ ወንዶች ልጆች እያሏችሁ ለእርሱ ሴቶች ልጆች አሉትን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 40, '40. ወይስ ዋጋን ትጠይቃቸዋለህን? በዚህም እነርሱ በእዳው የተከበዱ ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 41, '41. ወይስ ሩቁ ሚስጢር እነርሱ ዘንድ በመሆኑ እነርሱ ይጽፋሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 42, '42. ወይስ ተንኮልን (ባንተ) ይሻሉን? እነዚያም የካዱት የተተነኮለባቸው ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 43, '43. ወይስ ለእነርሱ ከአላህ ሌላ አምላክ አላቸውን? አላህ ከሚያጋሩት ሁሉ ጠራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 44, '44. ከሰማይም ቁራጭን በእነርሱ ላይ ወዳቂ ሆኖ ቢያዩ ኖሮ «ይህ የተደራረበ ደመና ነው» ይሉ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 45, '45. (መልዕክተኛችን ሙሐመድ ሆይ!)ያንንም በእርሱ የሚገደሉበትን ቀናቸውን እስከሚገናኙ ድረስ ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 46, '46. ተንኮላቸው ከእነርሱ ምንም የማይጠቅማቸውንና እነርሱም የማይረዱበትን ቀን እስከሚያገኙ ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 47, '47. ለእነዚያም ለበደሉትም ከዚህ ሌላ ቅርብ ቅጣት አለባቸው:: ግን አብዛኞቻቸው አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ!) ለጌታህ ፍርድም ታገስ:: አንተ በጥበቃችን ስር ነህና:: ጌታህንም በምትቆም ጊዜ ከማመስገን ጋር አጥራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (52, 49, '49. ከሌሊቱና በከዋክብት መደበቂያም ጊዜ (ንጋት ላይም) አጥራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 1, '1. በኮከብ እምላለሁ በገባ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 2, '2. (እናንተ የመካ ሰዎች ሆይ)፤ ባልደረባችሁ ሙሐመድ ከሐቅ አልተሳሳተም። አላፈነገጠም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 3, '3. ከልብ ወለድ ስሜቱም አይናገርም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 4, '4. እርሱ (ንግግሩ) ከአላህ የተወረደ እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 5, '5. ሀይለ ብርቱ የሆነው አስተማረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 6, '6. የእውቀት ባለቤት የሆነው:: ከዚያም ላይ ሆኖ ተመቻቸ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 7, '7. በላይኛው አድማስ ላይ ሆኖ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 8, '8. ከዚያም (ነቢዩን) ቀረበው፤ በጣም ተጠጋውም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 9, '9. ከዚያም የሁለት ደጋን ጫፎች ያህል ወይም ከዚያም ባነሰ ርቀት ላይ ሆነም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 10, '10. እናም (አላህ) ለአገልጋዩ (ለሙሐመድ) ማውረድ የሻውን አወረደ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 11, '11. ያየውን ነገር ሁሉ ልቦናው አላስተባበለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 12, '12. ታዲያ (ከሓዲያን ሆይ!) በሚያየው ጉዳይ ላይ ትከራከሩታላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 13, '13. እርግጥ በሌላይቱም መውረድ (ነቢዩ ሙሐመድ መልዐኩ ጂብሪልን) አይቶታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 14, '14. ይኸዉም ሲድረቱ አል-ሙንተሃ (የመጨረሻቱ ቁርቁራ) በተባለው ዓለም ላይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 15, '15. እርሷ ዘንድ መኖርያ የሆነችው ገነት አለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 16, '16. (ቁርቁራይቱን) ሸፋኝ ነገር በሸፈናት ጊዜ (አየው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 17, '17. አይኑ አልተዘነበለም:: ወሰንም አላለፈም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 18, '18. ከጌታው ታላላቅ ተዐምራት በእርግጥ ተመለከተ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 19, '19. (ቁርይሾች ሆይ!) ላትንና ዑዛን አያችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 20, '20. ስለ ሶስተኛዋ መናትም የምታውቁትን እስቲ ንገሩኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 21, '21. ለእናንተ ወንድ ወንድ ለእሱ ግን ሴት ሴት ታደርጋላችሁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 22, '22. ይህ ተግባር አድሏዊ ክፍፍል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 23, '23. እነዚያ ጣዖታት እናንተና አባቶቻችሁ የሰየማችኋቸው ስሞች ብቻ እንጂ ሌላ አይደሉም::አላህ በእርሷ (መገዛት) ምንም ማስረጃ አላወረደም፡፡ ጣኡት አምላኪዎች ሁሉ ከጌታቸው የተላከላቸው ቅኑ መመሪያ እያለ የሚከተሉት ግን ጥርጣሬንና ስሜትን ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 24, '24. የሰው ልጅ የፈለገውን ሁሉ ያገኛልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 25, '25. መጪውን ዓለምም ሆነ የመጀመሪያው ዓለም የአላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 26, '26. በሰማያት ውስጥ ካሉ መላዕክት አላህ የሚሻውንና የሚወደውን ለሰው ያማልዱ ዘንድ ከፈቀደላቸው በኋላ እንጂ ምልጃቸው የማይፈይድ አያሌዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 27, '27. እነዚያ በመጪው ዓለም የማያምኑት መላዕክትን በእንስት ስም ይሰይማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 28, '28. ለእነርሱም በእርሱ እውቀት የላቸውም። እነርሱ የሚከተሉት ጥርጣሬን ብቻ ነው:: ጥርጣሬ ደግሞ ሀቅን አይተካም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) ከቁርኣን አፈንግጦና የዚችን ዓለም ኑሮ እንጂ ሌላ ከማይመኝ ሰው እራስህን አሽሽ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 30, '30. ይህ የእውቀታቸው ጣሪያ (መጨረሻ) ነው:: ጌታህ ግን መንገዱን የሳተውን ሁሉ አዋቂ ነው:: የተቀናውንም እንዲሁ አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 31, '31. በሰማያትና በምድር ውስጥ ያለው ሁሉ የአላህ ነው:: እነዚያን ያጠፉትን በተግባራቸው ለመመንዳትና እነዚያን መልካም የሰሩትንም በመልካሟ (በገነት) ሊመነዳ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 32, '32. እነርሱም ከጥቃቅን ጥፋቶች በቀር ከባባድ ወንጀሎችንና አጸያፊ ተግባሮችን የራቁ ናቸው:: ጌታህ ምህረተ ሰፊ ነው:: እርሱ ከምድር በፈጠራችሁ ጊዜም ሆነ በእናቶቻችሁ ማሕጸን ውስጥ ጽንሶች በሁናችሁበት ጊዜ ያውቃችኋል:: ስለዚህ እራሳችሁን አታሞግሱ:: እርሱ በትክክል የሚፈራውን ሰው ከሁሉም ይበልጥ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 33, '33. ያን ከእምነት የሸሸውን አየህን (እስቲ ንገረኝ)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 34, '34. ጥቂትን ብቻ ሰጥቶ ያቋረጠውን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 35, '35, ለመሆኑ የሚያውቀው የሩቅ ሚስጢር አለውና እርሱንም ያያልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 36, '36. ወይስ በሙሳ ፅሁፍ ያለው አልተነገረውም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 37, '37. በኢብራሂም (ትእዛዛቱን) በፈፀመው ያለውስ አልተነገረዉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 38, '38. ይኸዉም ወንጀለኛ ነፍስ የሌላውን ነፍስ ወንጀል በፍጹም አትሸከምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 39, '39. የሰው ልጅም የለፋበትን ብቻ እንጂ ሌላ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 40, '40. የሰራውም ሁሉ ወደ ፊት ይታያል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 41, '41. ከዚያም ጌታው ሙሉ ምንዳውን ይመነዳዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) የሁሉም መጨረሻው ወደ ጌታህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 43, '43. እርሱ ያ ያሳቀና ያስለቀሰ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 44, '44. እርሱ ያ የገደለና ሕያው ያደረገም ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 45, '45. እርሱ ያ ጥንድን፤ ወንድንና ሴትን የፈጠረ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 46, '46. ይኸዉም ከፍትወት ጠብታ በማሕጸን ውስጥ በምትፈሰስ ጊዜ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 47, '47. ሌላውን ማስገኘትም በእርሱ ላይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 48, '48. እርሱ ያ ሀብትን የሰጠና ያብቃቃ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 49, '49. እርሱ የሺዕራ ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 50, '50. እርሱ የቀድሞ ሰዎችን የአድ ሕዝቦችንም አጠፋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 51, '51. ሰሙድንም አጠፋ:: አንድንም አላስቀረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 52, '52. በፊትም የኑህን ህዝቦች አጥፍቷል:: እነርሱ እጅግ በዳዮችና በጣም አመጸኞች ነበሩና ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 53, '53.የተገለበጡትንም ደፋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 54, '54. ባሸፈናት ሸፈናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 55, '55. (የሰው ልጅ ሆይ)፤ ከጌታህ ጸጋዎች በየትኛው ነው የምትጠራጠረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 56, '56. (መልዕክተኛችን ሙሐመድ ሆይ!) ይህ ከቀድሞዎቹ አስጠንቃቂዎች አንዱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 57, '57. ቀራቢቱም ቀረበች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 58, '58. ከአላህ በስተቀር ገላጭ የላትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 59, '59. በዚህ ዘገባ ትደነቃላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 60, '60 ትስቃላችሁን? አታለቅሱምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 61, '61. እናንተ ዘወትር ዘንጊዎች ናችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (53, 62, '62. ለአላህ ስገዱ በብቸኝነትም አምልኩትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 1, '1. የትንሳኤ ቀን ተቃረበ:: ጨረቃም ተገመሰ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 2, '2. ከሓዲያን ተዐምርን ቢያዩም እንቢ ብለው ይዞራሉ:: «ይህ ዘውታሪ ድግምት ነው» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 3, '3.አስተባበሉም :: ዝንባሌዎቻቸውንም ተከተሉ:: ነገርም ሁሉ (ወሰን አለው) ረጊ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 4, '4. ከዜናዎቹ በእርሱ ውስጥ መገሰጫ የሚሆን ነገር ያለበት በእርግጥ መጣላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 5, '5. ሙሉ ከሆነ ጥበብ (መጣላቸው):: ግን አስፈራሪዎች (ለማያምኑት) አይፈይዱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) ከእነርሱም ተውና ዙር። (ይልቁንስ) ጠሪው መልዓክ ወደ አስደንጋጭ ነገር የሚጠራበትን ቀን አስታውስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 7, '7. ዓይኖቻቸው ያቀረቀሩ ሆነውና ፍጹም የተበተኑ አንበጣ መስለው ከየመቃብሮቻቸው ይወጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 8, '8. ወደ ጠሪው አንገቶቻቸውን ሳቢዎችና ቸኳዩች ሆነው ይወጣሉ:: ከሓዲያን ያን ጊዜ «ይህ ብርቱ ቀን ነው» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 9, '9. ከእነርሱ በፊት የ(ነብዩ) ኑህ ህዝቦች አስተባበሉ:: ባሪያችንንም ኑህን አስተባበሉ:: «ዕብድ ነዉም» አሉት:: ተገላመጠም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 10, '10. «ጌታውንም እኔ የተሸነፍኩ ነኝና እርዳኝ» ሲል ተጣራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 11, '11. ወዲያውም የሰማይን ደጃፎች በሚንቧቧ ውሃ ከፈትን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 12, '12. የምድርንም ምንጮች በሃይል አፈነዳን:: የሰማዩና የምድሩ ውሃዉም ቀድሞ በተወሰነ ሁኔታ ላይ ተገናኘ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 13, '13. ባለ ብዙ ሳንቃዎችና ባለ ብዙ ሚስማሮች በሆነቸው ታንኳ ላይም ጫንነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 14, '14. በጥበቃችን ስር ሆና ትንሻለላለች፡፡ ተክዶ ለነበረ ሰው ምንዳ ይህን ሰራን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 15, '15. ተዓምር አድርገንም በእርግጥ ተውናት:: ተገሳጭ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 16, '16. ቅጣቴና ማስጠንቀቂያዎቼስ እንዴት ነበሩ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 17, '17. ቁርኣንን ለመገንዘብ በእርግጥ አገራነው:: ተገንዛቢ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 18, '18. የዓድ ህዝቦች አስተባበሉ:: ቅጣቴና ማስጠንቀቂያዎቼስ እንዴት ነበሩ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 19, '19. እኛ በእነርሱ ላይ ዘወትር መናጢ በሆነ ቀን በኃይል የምንትሻሻ ነፋስን ላክንባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 20, '20. ሰዎችንም ልክ ከስሮቻቸው እንደተጎለሰሱ የዘንባባ ግንዶች መስለው ከየተደበቁበት ትነቅላቸዋለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 21, '21. ቅጣቴና ማስጠንቀቂያዎቼስ እንዴት ነበሩ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 22, '22. ቁርኣንንም ለማስታወስ በእርግጥ አገራነው:: ተገሳጭ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 23, '23. የሰሙድ ህዝቦች በአስፈራሪዎቹ አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 24, '24. (እንዲህም) አሉ: «ከእኛ የሆነን አንድን ሰው እንከተለዋለን? እኛ ያ! ጊዜ በስህተትና በእብደት ውስጥ ነን አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 25, '25. «ከእኛ መካከል በእርሱ ላይ ብቻ ማስገንዘቢያ ራዕይ ተጣለለትን? አይደለም እርሱ ውሸታም ኩሩ ነው» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 26, '26. ውሸታሙ ኩሩው ማን እንደሆነ ነገ በእርግጥ ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 27, '27. እኛ ሴት ግመልን ለእነርሱ መፈተኛ ትሆን ዘንድ ላኪዎች ነን:: ተጠባበቃቸዉም ታገስም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 28, '28. ውሃዉም በመካከላቸው የተከፈለ መሆኑን ንገራቸው:: ከውሃ የሆነ ፈንታ ሁሉ በየተራ የሚጣዱት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 29, '29. ጓደኛቸውንም ጠሩት:: ወዲያዉም (ሰይፉን) ተቀበለ:: ወጋትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 30, '30. ቅጣቴና ማስጠንቀቂያዎቼስ እንዴት ነበሩ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 31, '31. እኛ በእነርሱ ላይ አንዲትን ጩኸት ላክንባቸው። ወዲያዉም ከበረት አጣሪ (አጥር) እንደ ተሰባበረ እርጋፊ ሆኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 32, '32. ቁርኣንን ለመገንዘብ አገራነው:: ተገሳጭ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 33, '33. የ(ነብዩ) ሉጥ ህዝብ በአስፈራሪዎቹ አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 34, '34. እኛ በእነርሱ ላይ ጠጠርን ያዘለች ነፋስ ላክን:: የሉጥ ቤተሰቦች ብቻ ሲቀሩ እነርሱንስ በሌሊት መጨረሻ ላይ አዳንናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 35, '35. ከእኛ በሆነ ጸጋ አዳናቸው:: ልክ እንደዚሁ ያመሰገነን ሰው እንመነዳለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 36, '36. ብርቱ አያያዛችንን በእርግጥ አስጠነቀቅናቸው:: በማስጠንቀቂያዎቹም ተከራከሩ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 37, '37. ከእንግዶቹም እንዲያስመቻቸው ደጋግመው ፈለጉት። ወዲያዉም ዓይኖቻቸውን አበስን። ቅጣቱንና ማስጠንቀቂያዎቹን ቅመሱ አልናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 38, '38. በማለዳም ዘወታሪ የሆነ ቅጣት በእርግጥ ማለደባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 39, '39. ቅጣቱንና ማስጠንቀቂያዎችም ቅመሱ ተባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 40, '40 ቁርኣንንም ለመገንዘብ በእርግጥ አገራነው:: ተገሳጭ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 41, '41.የፈርዖንን ቤተሰቦችም ማስጠንቀቂያዎች በእርግጥ መጧቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 42, '42. በተዓምራታችንም በሁሏም አስተባበሉ:: የብርቱ ቻይንም አቀጣጥ ቀጣናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 43, '43. የእናንተ ከሓዲያኖቻችሁ ከእነዚያችሁ በላጮች ናቸውን? ወይስ ለእናንተ በመጽሐፎች ውስጥ በተለየ የተነገረ ነፃነት አላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 44, '44. ወይስ «እኛ የተረዳን ክምቹዎች ነን» ይላሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 45, '45. ክምቹዎቹ በእርግጥ ድል ይመታሉ:: ጀርባዎቻቸውንም ያዞራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 46, '46. ይልቁንም ሰዓቲቱ ትንሳኤ ቀጠሯቸው ናት:: ሰዓቲቱም በጣም የከበደችና የመረረች ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 47, '47. አመጸኞች በስህተትና በእሳቶች ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 48, '48. በእሳት ውስጥ በፊታቸው በሚጎተቱበት ቀን የሰቀርን (የገሀነምን) ቅጣት መንካትን ቅመሱ ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 49, '49. እኛ ሁሉን ነገር በልክ ፈጠርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 50, '50. ትዕዛዛችንም እንደ ዓይን ቅጽበት የሆነች አንዲት ቃል እንጂ ሌላ አይደለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 51, '51. ብጤዎቻችሁንም በእርግጥ አጠፋን፤ ተገሳጭ አለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 52, '52. የሰሩትም ነገር ሁሉ በመጽሐፎች ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 53, '53. ትንሹም ትልቁም ሁሉ የተፃፈ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 54, '54. አላህን ፈሪ የሆኑ ሰዎች ሁሉ በአትክልቶችና በወንዞች ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (54, 55, '55. እነርሱም (ውድቅ ቃልና መውወንጀል በሌለበት) በእውነት መቀመጫ ውስጥ ላይ ከሆነው ንጉስ አላህ ዘንድ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 1, '1. አር-ረህማን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 2, '2. ቁርኣንን አስተማረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 3, '3. ሰውን ፈጠረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 4, '4. መግለፅንም አስተማረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 5, '5. ጸሐይና ጨረቃ በተወሰነ (በየሂሳባቸው) ልክ ይሄዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 6, '6. የሰማይ ከዋክብትና የምድር ዛፎችም ለእርሱ ይሰግዳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 7, '7. ሰማይንም ከፍ አደረጋት:: የትክክለኛነትን ሚዛንንም አስቀመጠ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 8, '8. በሚዛን ስትመዝኑም እንዳትበድሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 9, '9. መመዘንንም በትክክል መዝኑ:: ስትመዝኑም አታጉድሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 10, '10. ምድርንም ለፍጡር አደላደላት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 11, '11. በውስጧ እሸትም ባለ ሽፍን የሆኑ ዘንባባዎችም ያሉባት ስትሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 12, '12. ባለቅርፊት ቅንጣትና ባለ መልካም መዓዛ ቅጠሎችም ያሉባት ስትሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 13, '13. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች መካከል በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 14, '14. ሰውን እንደ ሸክላ ከሚቅጨለጨል ደረቅ ጭቃ ፈጠረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 15, '15. ጂንንም ከጭስ አልባ የእሳት ነበልባል ፈጠረው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 16, '16. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 17, '17. የሁለቱ ምስራቆችና የሁለቱ ምዕራቦች ጌታ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 18, '18. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 19, '19. ሁለቱም ባህሮች የሚገናኙ ሲሆኑ ለቀቃቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 20, '20. እንዳይዋሀዱ በመካከላቸው የማይታይ መጋረጃ አለ:: አንዱ በሌላው ላይ ወሰን አያልፉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 21, '21. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 22, '22. ሉልና መርጃን የተባሉት ማዕድናት ከሁለቱ (ባህሮች) ይወጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 23, '23. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 24, '24. እንደ ጋራዎች ሆነው በባህር ውስጥ የተሰሩት ተንሻላዮችም (ታንኳዎች) የእርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 25, '25. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 26, '26. በእርሷ (በምድር) ላይ ያለው ሁሉ ጠፊ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 27, '27. የልቅና እና የልግስና ባለቤት የሆነው የጌታህ ፊት ብቻ ይቀራል (አይጠፋም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 28, '28. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 29, '29.በሰማያትና በምድር ውስጥ ያሉት ሁሉ ይለምኑታል። በየቀኑ ሁሉ እርሱ በስራ ላይ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 30, '30. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 31, '31. እናንተ ሁለት ከባዶች (ሰዎችና ጋኔኖች) ሆይ! ለእናንተ መቆጣጠር በእርግጥ እንገኛለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 32, '32. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 33, '33. የአጋንንትና የሰው ስብስቦች ሆይ! ከሰማያትና ከምድር ቀበሌዎች መውጣትን ከቻላችሁ ውጡ:: በአላህ ስልጣን እንጂ አትወጡም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 34, '34. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 35, '35. በሁለታችሁም ላይ ከእሳት ነበላባልና ጭስን ይላክባችኋል:: ሁለታችሁም ድል አታደርጉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 36, '36. (ሰዎችና ጋኔኖች ሆይ !) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 37, '37. ሰማይ በተሰነጠቀችና እንደጽጌረዳ እንደታረበ ቆዳ በሆነች ጊዜ (ጭንቁን ምን አበረታው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 38, '38. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 39, '39. በዚያ ቀን ሰዉም ጂንም ከሐጢአት አይጠየቅም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 40, '40. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 41, '41. ከሓዲያን በምልክታቸው ይታወቃሉ:: ከዚያ አናቶቻቸውንና እግሮቻቸውን ይያዛሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 42, '42. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 43, '43. "ይህች ያቺ አመጸኞች በእርሷ ያስተባብሉባት የነበረችው ገሀነም ናት" (ይባላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 44, '44. በእርሷና በጣም ሞቃት በሆነ ፍል ውሃ መካከል ይመላለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 45, '45. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 46, '46. (ሰዎችና ጋኔኖች ሆይ!) ከጌታዉም ፊት መቆምን ለፈራ ሰው ሁሉ ሁለት ገነቶች አሉት፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 47, '47. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 48, '48. የቀንዘሎች ባለቤቶች የሆኑ ገነቶች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 49, '49. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 50, '50. በሁለቱ ውስጥ የሚፈሱ ሁለት ምንጮች አሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 51, '51. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 52, '52. በሁለቱ ውስጥ ከየፍራፍሬው ሁለት ዓይነቶች (እርጥብና ደረቅ) አሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 53, '53. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 54, '54. የውስጥ ጉዝጉዛቸው ከወፍራም ሀር በሆኑ ምንጣፎች ላይ የተመቻቸ ሲሆን ይንፈላሰሳሉ፤ የሁለቱም ገነቶች ፍሬ ለለቃሚ ቅርብ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 55, '55. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 56, '56. በውስጣቸው ከባሎቻቸው በፊት ሰዉም ጂንም ያልዳሰሳቸው (ያልገሰሳቸው) ዓይኖቻቸውን (በባሎቻቸው ላይ ብቻ) አሳጣሪዎች ሴቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 57, '57. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 58, '58. ልክ የያቁትንና የመርጃንን ማዕድናት ይመስላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 59, '59. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 60, '60. የበጎ ስራ ዋጋ በጎ እንጂ ሌላ ነውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 61, '61. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 62, '62. ከሁለት ገነቶች ሌላም ሁለት ገነቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 63, '63. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 64, '64. ከልምላሜዎቻቸው የተነሳ ወደ ጥቁረት ያዘነበሉ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 65, '65. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 66, '66. በውስጣቸው ሁለት የሚንፏፉ ምንጮች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 67, '67. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 68, '68. በውስጣቸው ፍራፍሬ ዘንባባና ሩማን አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 69, '69. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 70, '70. በውስጣቸው ጸባየ መልካሞችና መልከ ውብ ሴቶች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 71, '71. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 72, '72. በድንኳኖች ውስጥ የተጨጎሉ የዓይኖቸቻቸው ጥቁረትና ንጣት ደማቅ የሆኑ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 73, '73. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 74, '74. ከእነርሱ በፊት ሰዉም ሆነ ጃን አልዳሰሳቸዉም (አልገሰሳቸዉም) ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 75, '75. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 76, '76. በሚያረገርጉ አረንጓዴ ምንጣፎችና በሚያማምሩ ስጋጃዎች ላይ የተደላደሉ ሲሆኑ ይቀመጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 77, '77. (ሰዎችና ጋኔኖች ሆይ!) ከጌታችሁ ጸጋዎች በየትኛው ታስተባብላላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (55, 78, '78. የግርማ የመከበር ባለቤት የሆነው ጌታህ ስም ላቀ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 1, '1. ተጨባጪቱ (ቂያማ) እውን በሆነች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 2, '2. (ቂያማ) እውን ለመሆኗ አንዲትም አስተባባይ ነፍስ የለችም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 3, '3. እርሷ (ገሚሱን) ዝቅ አድራጊና (ገሚሱን) ደግሞ ከፍ አድራጊ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 4, '4. ምድር መናወጥን በተናወጠች ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 5, '5. ተራራዎች (እንደተፈጨ ዱቄት) መፈርፈርን በተፈረፈሩ ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 6, '6. የተበተነ ብናኝ በሆኑም ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 7, '7. እናንተ (ሰዎች) ሶስት ዓይነቶችም በሆናችሁ ጊዜ (ገሚሱን ዝቅ እና ገሚሱን ከፍ ታደርጋለች)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 8, '8. እናም በዚያ ቀን የቀኝ ጓዶች ለመሆን የበቁ ሁሉ ምን (የተከበሩ) የቀኝ ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 9, '9. የግራ ጓዶች ምን (የተዋረዱ) የግራ ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 10, '10. እነዚያ (ለበጎ ስራ) ቀዳሚዎች የሆኑ ሁሉ (ለገነትም) ቀዳሚዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 11, '11. እነዚያ (በአላህ ዘንድም) ባለሟሎች ናቸው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 12, '12. በመደሰቻ ገነቶች ውስጥ ሲሆኑ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 13, '13. (የዚህ እድል ባለ ቤቶች) ከፊተኞቹ ብዙ ቡድኖች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 14, '14. ከኋለኞቹ ግን ጥቂቶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 15, '15. በተሸሞኑ አልጋዎች ላይ ይሆናሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 16, '16. በእርሷ ላይ የተመቻቹና ፊት ለፊት የተቅጣጩ ሲሆኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 17, '17. እነርሱን (ለማገለገል) በእነርሱ ዙሪያ ሁልጊዜ የማያረጁ ወጣት ልጆች ይዘዋወራሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 18, '18. ከ(ጠጅ) ምንጭ በብርጨቆዎች፣ በኩስኩስቶችና (እብሪቆች) በጽዋም በእነርሱ ዙሪያ እንዲዞሩ ይደረጋሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 19, '19. ከእርሷ የራስ ምታት እንኳን አያገኛቸዉም:: አይሰክሩምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 20, '20. ከእሸቶች ከሚመርጡት ዓይነት', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 21, '21. ከሚፈልጉት የበራሪ ስጋ ይዘው ይዞሩላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 22, '22. ዓይናማዎች የሆኑ ነጫጭ ቆንጆ ሴቶችም አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 23, '23. ልክ እንደተሸፈነ ሉል የሚመስሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 24, '24. ለዚያ ይሰሩት በነበሩት መልካም ተግባር ምክንያት ዋጋ ይሆን ዘንድ ይህንን አደረግንላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 25, '25. በውስጧ ውድቅ ንግግርንና መወንጀልንም አይሰሙም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 26, '26. ሰላም ሰላም መባባልን ግን ይሰማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 27, '27. የቀኝ ጓዶች ምንኛ የከበሩ የቀኝ ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 28, '28. በተቀፈቀፈ (እሾህ በሌለው) ቁርቁራ ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 29, '29. ፍሬው በተነባበረ ሙዝ ዛፍም ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 30, '30. በተዘረጋ ጥላ ስርም ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 31, '31. በሚንቧቡ ውሃ አጠገብም ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 32, '32. በብዙ ዓይነት ፍራፍሬዎችም ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 33, '33. ምንጊዜም የማትቋረጥ የማትከለከልም የሆነች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 34, '34. ከፍ በተደረጉ ምንጣፎች ላይም ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 35, '35. እኛ (የገነት ሴቶችን) አዲስ ፍጥረት አድርገን ፈጠርናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 36, '36. እናም ደናግሎችም አደረግናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 37, '37. ለባሎቻቸው ተሽሞርሟሪዎችና እኩያዎች አደረግናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 38, '38. ለቀኝ ጓዶች አዘጋጀናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 39, '39. ከፊተኞቹ ብዙ ቡድኖች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 40, '40. ከኋለኞቹም ብዙ ቡድኖች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 41, '41. የግራ ጓዶችም ምንኛ የተዋረዱ የግራ ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 42, '42. በመርዛም ንፋስና በጣም በፈላ ውሃም ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 43, '43. ከጥቁር ጭስም በሆነ ጥላ ውስጥ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 44, '44. ቀዝቃዛም መልካምም ያልሆነ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 45, '45. እነርሱ ከዚህ በፊት የነብያትን አስተምህሮት ወደ ጎን የተው የዱንያ ቅምጥሎች ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 46, '46. በከባድ ኃጢአትም ላይ ይዘወትሩ ነበሩና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 47, '47. (እንዲህ) ይሉ ነበርም፡ "ሞተን አፈር፣ አጥንቶችም በሆን ጊዜ እኛ የምንቀሰቀስ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 48, '48. "የፊተኞቹ አባቶቻችንንም (ይቀሰቀሳሉን)?" (ይሉ ነበር)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 49, '49. (መልዕክተኛችን ሙሐመድ ሆይ!) "ፊተኞቹም ሆኑ ኋለኞቹ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 50, '50. "በተወሰነ ቀን ቀጠሮ በእርግጥ ተሰብሳቢዎች ናቸው" በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 51, '51. ከዚያም እናንተ ጠማሞችና አስተባባዩች ሆይ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 52, '52. ከዘቁም ዛፍ በእርግጥ በይዎች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 53, '53. ከእርሷም ሆዶቻችሁን ሞይዎች ናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 54, '54. በእርሱ ላይም ከፈላ ውሃ ጠጪዎች ናችው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 55, '55. የተጠሙንም ግመሎች አጠጣጥ ብጤ ጠጪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 56, '56. ይህ የፍርዱ ቀን መስተንግዷቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 57, '57. (ሰዎች ሆይ!) እኛ ፈጠርናችሁ አታምኑምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 58, '58. በሴቶች ማህጸኖች የምታፈሱትን (የምትረጩትን ፍትወት) አያችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 59, '59. እናንተ ትፈጥሩታላችሁን! ወይስ እኛ ነን ፈጣሪዎቹ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 60, '60. እኛ ሞትን (ጊዜውን) በመካከላችሁ ወሰንን እኛም ተሸናፊዎች አይደለንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 61, '61. ብጤዎቻችሁን በመለወጥና በዚያ በማታውቁትም ቅርጽ እናንተኑ በመፍጠር ላይ (አንሸነፍም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 62, '62. የፊተኛይቱን አፈጣጠር በእርግጥ አውቃችኋል አትገነዘቡምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 63, '63. የምትዘሩትን (አዝርአት) አያችሁን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 64, '64. እናንተ ታበቅሉታላችሁን? ወይስ እኛ አብቃዮቹ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 65, '65. ብንሻ ኖሮ ደረቅ ስብርብር ባረደግነው እና የምትደነቁም በሆናችሁ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 66, '66. "እኛ በእዳ ተያዥዎች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 67, '67. "በእርግጥም እኛ (ከመጠቀም) የተከለክልን ነን" ትሉ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 68, '68. ያንን ምትጠጡትን ውሃ አያችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 69, '69. እናንተ ከደመናው አወረዳችሁትን? ወይስ እኛ አውራጆቹ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 70, '70. ብንፈልግ ኖሮ መርጋጋ ባደረግነው ነበር:: አታመሰግኑምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 71, '71. ያችንም የምትሰብቋትን እሳት አያችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 72, '72. እናንተ ዛፏን ፈጠራችሁን? ወይስ እኛ ፈጣሪዎቹ ነን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 73, '73. እኛ ለገሀነም ማስታወሻ ለመንገደኞችም መጠቀሚያ አደረግናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 74, '74. የታላቁን ጌታህንም ስም አጥራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 75, '75. በከዋክብትም መጥለቂያዎች እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 76, '76. እርሱም ብታውቁ ታላቅ መሀላ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 77, '77. እርሱ የተከበረ ቁርኣን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 78, '78. በተጠበቀ መጽሐፍ ውስጥም ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 79, '79. የተጥራሩት እንጂ ሌላ አይነካዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 80, '80. ከዓለማት ጌታ የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 81, '81. በዚህ ንግግር እናንተ ቸልተኞች ናችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 82, '82. ሲሳያችሁንም (ዝናብን) እናንተ የምታስተባበሉት ታደርጋላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 83, '83. ነፍስ ጉሮሮንም በደረሰች ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 84, '84. እናንተ ያን ጊዜ የምታዩ ስትሆኑ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 85, '85. እኛም ግን እናንተ አታዩም እንጂ ከናንተ ይልቅ ወደ እርሱ የቀረብን ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 86, '86. የማትዳኙም ከሆናችሁ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 87, '87. እውነተኞች እንደሆናችሁ ነፍሲቱን ወደ አካል ለምን አትመልሷትም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 88, '88. እናም ሟቹ ከባለሟሎቹ ከሆነም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 89, '89. ለእርሱ እረፍት መልካም ሲሳይና የመጠቀሚያ ገነት አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 90, '90. ሟቹ ከቀኝ ጓዶችም ከሆነ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 91, '91."ከቀኝ ጓዶች ስለሆንክ ላንተ ሰላም ነው የሚገባህ" ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 92, '92. ሟች ከእነዚያ ከሚያስተባብሉት ጠማማዎች ከሆነ ደግሞ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 93, '93. ከፈላ ውሃ የሆነ መስተንግዶ አለለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 94, '94. በገሀነም መቃጠልም አለለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 95, '95. ይህ እርሱ እርግጠኛው እውነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (56, 96, '96. (መልዕክተኛችን ሙሐመድ ሆይ!) የታላቁ ጌታህን ስም አጥራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 1, '1. በሰማያትና በምድር ውስጥ ያሉ ሁሉ አላህን አጠሩ። እርሱም ኃያሉና ጥበበኛው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 2, '2. የሰማያትና የምድር ንግስና የእርሱው ብቻ ነው:: ሕይወትን የሚሰጥና ሕይወትን የሚነሳ እሱው ብቻ ነው:: እርሱ ሁሉንም ነገር ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 3, '3. እርሱ ( ከበፊቱ ምንም ያልቀደመው) የመጀመሪያ! (ፊት ያለ) (ከኋላው ምንም የሌለ የመጨረሻ) ብቻዉን ቀሪ፤ ከበላዩ ማንም የሌለ (ግልጽና የበላይ) ስውርም (ድብቅ) ነው:: እርሱ (በምድርም ሆነ በሰማይ ያለን) ሁሉ ነገር አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 4, '4. እርሱ ያ ሰማያትንና ምድርን በስድስት ቀናት ብቻ የፈጠረ ነው:: ከዚያ በዐርሹ ላይ ከፍ አለ። ወደ ምድር የሚገባውንና ከእርሷ የሚወጣውን ያውቃል:: ከሰማይ የሚወረደውንና ወደ እርሷ የሚወጣውን ያውቃል:: እርሱ የትም ብትሆኑ (በእውቀቱ) ከናንተው ጋር ነው:: አላህ የምትሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 5, '5. የሰማያትና የምድር ንግስና የእርሱ ብቻ ነው:: ነገሮች ሁሉ ወደ አላህ ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 6, '6. ሌሊትን በቀን ውስጥ ያስገባል:: ቀንንም በሌሊት ውስጥ ያስገባል:: እርሱም በልቦች ውስጥ የተደበቁትን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 7, '7. (ሰዎች ሆይ!) በአላህና በመልዕክተኛው እመኑ:: አላህ በእርሱ ላይ ተተካኪዎች ካደረጋችሁ ገንዘብ ዉስጥም ለግሱ:: እነዚያ ከእናንተ መካከል በአላህ ያመኑትና የለገሱት ሁሉ ለእነርሱ ታላቅ ምንዳ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 8, '8. (ሰዎች ሆይ!) ጌታችሁም ቃልኪዳናችሁን የያዘባችሁ ሲሆን መልዕክተኛውም በጌታችሁ እንድታምኑ የሚጠራችሁ ሲሆን በአላህ የማታምኑበት ምን ምክኒያት አላችሁ? እናንተ በትክክል የምታምኑ ከሆናችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 9, '9. እርሱ ከጨለማዎች ወደ ብርሀን ሊያወጣችሁ ግልፆች የሆኑን አናቅጽ በባሪያው ላይ የሚያወርድ ነው:: አላህ ለእናንተ በእርግጥ ሩህሩህ አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 10, '10. የሰማያትና የምድር ውርስ ለአላህ ብቻ ሲሆን በአላህ መንገድ የማትለግሱበት ምን ምክንያት አላችሁ? ከናንተ መካከል ከመካ መከፈት በፊት የለገሰና የተጋደለ ሰው ከተከፈተ በኋላ ከለገሰና ከተጋደለ ሰው ጋር አይስተከከልም:: ከእነዚያ በኋላ ከለገሱትና ከተጋደሉት እነዚህ በደረጃ በጣም የላቁ ናቸውና:: ሁሉንም አላህ የመልካሚቱን ተስፋ ቃል ገብቶላቸዋል:: አላህ በምትሰሩት ሁሉ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 11, '11. ያ ለአላህ መልካም ብድርን የሚያበድርና ለእርሱ አላህ ምንዳውን የሚያነባብርለት ሰው ማን ነው? ለእርሱም መልካም ምንዳ አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 12, '12. ወንድ ትክክለኛ አማኞችንና ሴት ትክክለኛ አማኞችን በስተፊቶቻቸው በቀኞቻቸዉም ብርሀናቸው የሚሮጥ ሲሆን በምታያቸው ቀን (ታላቅ ምንዳ አለላቸው።) "ዛሬ ብስራታችሁ በውስጦቻቸው ዘውታሪዎች ስትኾኑ ከሥሮቻቸው ወንዞች የሚፈስሱባቸው ገነቶች ናቸው (ይባላሉ)፡፡ ይህ እርሱ ታላቅ እድል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 13, '13. (መልዕክተኛችን ሙሐመድ ሆይ!) የወንድ አስመሳዮችና የሴት አስመሳዮች ለእነዚያ በአላህ ላመኑት "ጠብቁን ከብርሀናችሁ እናበራለንና" የሚሉበትን ቀን አስታውስ:: "ወደ ኋላችሁ ተመለሱ:: ብርሀንንም እዚያው ፈልጉ" ይባላሉ:: በመካከላቸዉም ለእርሱ ደጃፍ ባለው አጥር ይከለላል:: ግቢው በውስጡ ገነት ያለበት ከውጪዉም በኩሉ ደግሞ የእሳት (ስቃይ) ያለበት የሆነ (ደጃፍ ባለው አጥር ይከለላል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 14, '14. "ከናንተ ጋር አልነበርንምን?" በማለት ይጠሯቸዋል:: "እውነት ነው እኛ ጋር ነበራችሁ:: ግን እናንተ ነፍሶቻችሁን አጠፋችሁ:: በነብዩ አደጋዎችን ተጠባበቃችሁ ትጠራጠራላችሁም:: የአላህ ትዕዛዝ እስከ መጣ ድረስ ከንቱ ምኞቶች አታለሏችሁ። አታላዩም ሰይጣን በአላህ መታገስ ሸነገላችሁ ይሏቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 15, '15. በመሆኑም ዛሬ ከናንተም ሆነ በአላህ ከካዱት ሰዎች የገንዘብ ክፍያ (ቤዛ) አይወሰድም:: መኖሪያችሁ የገሀነም እሳት ብቻ ናት:: እርሷ ተገቢያችሁ ናትና:: የገሀነም እሳት መመለሻነቷ ምን ትከፋም" (ይሏቸዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 16, '16. ለእነዚያ (በአላህ) ላመኑት ለአላህ ተግሳጽና ከቁርኣንም ለወረደው እውነታ ልቦቻቸው ሊፈሩ፤ እንደነዚያ በፊት መጽሐፍን እንደ ተሰጡትና በእነርሱ ላይ ጊዜ ስለ ረዘመባቸው ልቦቻቸውም እንደ ደረቁባቸው ህዝቦች የማይሆኑበት ጊዜ አልቀረበምን? ከእነርሱም ብዙዎቹ አመጸኞች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 17, '17. (ሰዎች ሆይ!) አላህ ምድርን ከሞተች በኋላ ህያው የሚደርጋት መሆኑን እወቁ። ታውቁም ዘንድ አናቅጽን ለእናንተ በእርግጥ አብራራንላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 18, '18. የመጸወቱ ወንዶችና የመጸወቱ ሴቶች ለአላህ መልካምን ብድር ያበደሩ ሁሉ ለእነርሱም ምንዳ ይደራረብላቸዋል:: ለእነርሱም መልካም የተከበረ ምንዳ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 19, '19. እነዚያ በአላህና በመልዕክተኞቹ ያመኑ ሰዎች እነዚያ እነርሱ በጣም እውነቶኞች በጌታቸዉም ዘንድ መስካሪዎች ናቸው:: ለእነርሱ ምንዳቸውም ብርሀናቸዉም አለላቸው:: እነዚያ (በአላህ) የካዱትና በአናቅጻችን ያስተባበሉ ሰዎች ደግሞ የእሳት ጓዶች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 20, '20. (ሰዎች ሆይ!) ቅርቢቱን ሕይወት ጨዋታና ዛዛታ፤ ማጌጫም፤ በመካከችሁም መፎካከሪያ፤ በገንዘቦችና በልጆችም ብዛት መበላለጫ ብቻ መሆኗን እወቁ:: እርሷ በቃዩ ገበሬዎችን ቡቃያው እንደሚያስደስት ዝናብና ከዚያ በቃዩ እንደሚደርቅና ገርጥቶ እንደሚታየው ከዚም የተሰባበረ እንደሚሆን ብጤ ነው:: በመጨረሻይቱም ዓለም ለአጥፊዎች ብርቱ ቅጣት፤ ለትክክለኛ አማኞች ከአላህ ምህረትና ውዴታ አለ:: የቅርቢቱ ሕይወት እኮ የመታለያ ጥቅም እንጂ ሌላ አይደለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 21, '21. (እናንተ ያመናችሁ ሆይ!) በአላህና በመልዕክተኞች ላመኑት ወደ ተዘጋጀችውና የወርዷ ስፋት እንደ ሰማይና ምድር ወደ ሆነችም ገነት ተሸቀዳደሙ:: ይህ የአላህ ችሮታ ነው:: ለሚፈልገው ሰው ብቻ ይሰጠዋል:: አላህ የታላቅ ችሮታ ባለቤት ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 22, '22. በምድርም ሆነ በነፍሶቻችሁ መከራ ማንንም አታጋጥምም ሳንፈጥራት በፊት በመጽሐፍ የተመዘገበች ብትሆን እንጂ:: ይህ በአላህ ላይ ቀላል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 23, '23. (ይህን ማሳወቃችን) ባመለጣችሁ ጸጋ ላይ እንዳታዝኑና አላህ በሰጣችሁ ነገር (በትዕቢት) እንዳትደሰቱ ነው:: አላህ ኩራተኛንና ጉረኛን ሁሉ አይወድምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 24, '24. እነርሱም እነዚያ የሚሰስቱና ሰዎችንም በስስት ላይ የሚያዙ ናቸው:: ከእውነት የሚሸሽ (ሰው) ሁሉ ጉዳቱ ለራሱ ብቻ ነው:: አላህ ተብቃቂ ና ምስጉን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 25, '25. መልዕክተኞቻችንን በግልጽ ማስረጃዎች አጠናክረን በእርግጥ ላክን:: ሰዎችም በትክክል ቀጥ እንዲሉ መጽሐፎችንና ሚዛንን ወደ እነርሱ አወረድን:: ብረትንም ከውስጡ ብርቱ ኃይልና ለሰዎችም መጠቃቀሚያዎች ያሉበት ሲሆን አወረድን:: አላህ ሃይማኖትንና መልዕክተኞችን በሩቁ ሆኖ የሚረዳውን (ሰው) ሊያውቅ (ሊገልጽ) አወረደው:: አላህ ብርቱና አሸናፊ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 26, '26. ኑህንና ኢብራሂምን በእርግጥ ላክን:: በዘሮቻቸዉም ውስጥ ነብይነትንና መጽሐፍትን አደረግን:: ከእነርሱም መካከል ቅን ሰው አለ:: ከእነርሱም መካከል ብዙዎቹ ግን አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 27, '27. ከዚያም በእነርሱ ፈለጋቸው ላይ መልዕክተኞችን አከታተልን:: የመርየም ልጅን ዒሳንም አስከተልን:: ኢንጂልንም ሰጠነው:: በእነዚያም በተከተሉት ሰዎች ልቦች ውስጥ መለዘብንና እዝነትን አደረግን፤ አዲስ የፈጠሯትንም ምንኩስና በእነርሱ ላይ አልደነገግንም:: ግን የአላህን ውዴታ ለመፈለግ ሲሉ ከራሳቸው ፈጠሯት:: ተገቢ አጠባበቅንም አልጠበቋትም:: ከእነርሱም መካከል በአላህ ላመኑት ምንዳቸውን ሰጠናቸው:: ከእነርሱ ብዙዎቹ ግን አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 28, '28. እናንተ ያመናችሁ ሆይ! አላህን ፍሩ:: በመልክተኛዉም እመኑ:: ከችሮታው ሁለትን ክፍሎች ይሰጣችኋልና:: ለእናተም የምትሄዱበትን ብርሃን ያደርግላችኋል:: ለእናንተም ወንጀላችሁን ይምራል:: አላህ መሀሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (57, 29, '29. (ይህም) የመጽሐፍ ሰዎች ከአላህ ችሮታ በምንም ላይ የማይችሉ መሆናቸውንና ችሮታዉም አላህ ለሚሻው ሰው ብቻ የሚሰጠው በእርሱ እጅ ብቻ መሆኑን እንዲያውቁ ነው:: አላህ የታላቅ ችሮታ ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ የዚያችን በባሏ ጉዳይ ላይ የምትከራከርህንና ወደ አላህ ስሞታን የምታሰማውን ሴትዮ ቃል ሰማ:: አላህ በንግግር መመላለሳችሁን (መወያየታችሁን) ይሰማል:: አላህ (ለሚባለው) ሁሉ ሰሚ (ለሚፈጸመው ሁሉ ነገር) አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 2, '2. እነዚያ ከናንተ መካከል ሚስቶቻቸውን እንደእናቶቻቸው ጀርባዎች ይሁኑብን በማለት የሚምሉ ሰዎች እነርሱ እናቶቻቸው አይደሉም:: ትክክለኛ እናቶቻቸው እነዚያ የወለዷቸው ሴቶች ብቻ ናቸው:: እነርሱ በዚህ ቃል የተጠላ ንግግርንና ውሸትን በእርግጥ ይናገራሉ:: አላህ ለሚጸጸት ሰው ሁሉ ይቅር ባይና መሀሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 3, '3. እነዚያ ሚስቶቻቸውን እንደእናቶቻቸው ጀርባዎች ይሁኑብን በማለት የሚምሉና ከዚያ ወደ ተናገሩት የሚመለሱ ሳይነካኩ በፊት በባርነት የተያዘችዋን ጫንቃ ነፃ ማውጣት ግዴታ አለባቸው:: ይህ ህግ (የተጠቀሰው ህግ) በእርሱ ትገሰጹበታላችሁ:: አላህ በምትሰሩት ነገር ሁሉ ውስጠ አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 4, '4. ይህን ላላገኘም ሰው ከመነካካታቸው በፊት ሁለት ተከታታይ ወሮችን መፆም አለበት:: ይህን ላልቻለም ሰው ስልሳ ድሆችን ማብላት አለበት:: ይህ በአላህና በመልዕክተኛው እንድታምኑ ነው:: እነኚህ ህግጋት የአላህ ህግጋት ናቸው:: (እናም አትተላለፏቸው::) ለከሓዲያንም ሁሉ አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 5, '5. ግልጽ ማስረጃዎችን ያወረድን ስንሆን እነዚያ አላህንና መልዕክተኛውን የሚከራከሩ ሰዎች እነዚያ ከእነርሱ በፊት የነበሩ ሰዎች እንደተዋረዱት ሁሉ ተዋርደዋል:: ለከሓዲያን አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 6, '6. አላህ ሁላቸውንም በአንድ አድርጎ (አንድም ሳይቀር በአንድ ዓይነት) በሚቀሰቅሳቸው ቀን (ይቀጣቸዋል):: ከዚያም በዚህ ዓለም የሰሩትን ነገር ሁሉ ይነግራቸዋል:: እነርሱ የረሱት ሲሆን (መዝገባቸው ተመዝግቦ ያገኙታል) አላህ ግን አንድም ሳይቀር አውቆታል:: አላህ ሁሉንም ነገር ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) አላህ በሰማያትና በምድር ውስጥ ያለውን ሁሉ የሚያውቅ መሆኑን አታውቅምን? (በእውነቱ ሁሉንም አካቧል::) የሶስት ሰዎች መንሾካሾክ አይከሰትም፤ አላህ አራተኛው ቢሆን እንጂ፤ የአምስትም ሰዎች መንሾካሾክ አይከሰትም እርሱ ስድስተኛ ቢሆን እንጂ፤ ከዚያ ያነሰም ይሁን የበዛ ሰው መሾካሾክ አይከሰትም እርሱ ባሉበት ቦታ አብሯቸው ቢሆን እንጂ:: ከዚያ በትንሳኤ ቀን የሰሩትን ሁሉ ይነግራቸዋል:: አላህ ሁሉን ነገር አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 8, '8. (መልዕክተኛችን ሙሐመድ ሆይ!) ወደ እነዚያ በመጥፎ ነገር ከመመሳጠር ወደ ተከለከሉት፤ ከዚያ ከእርሱ ወደ ተከለከሉት ነገር የሚመለሱትንና በኃጢአት፣ በጠላትነትና መልዕክተኛውን በመቃወም ወደ ሚመሳጠሩ አላየህምን? (ሰላም ሊሉ) ወደ አንተ በመጡ ጊዜ አላህ ባላናገረህ ቃል ያናግሩሃል:: ውስጣቸው ይህ ሰው ነብይ ከሆነ በምንለው ነገር አላህ አይቀጣንም ኖሯልን? (ነብይ ከሆነስ) የለመነውን ነገር አላህ ተቀብሎት በሞትን ነበር ይላሉ:: ገሀነም የሚገቡባት ሲሆኑ ከአሁኑ ሞት ይልቅ በቂያቸው ናት:: ገሀነምም መመለሻነቷ ከፋች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 9, '9. እናንተ ያመናችሁ ሆይ! በተመሳጠራችሁ ጊዜ በኃጢአት ወሰንን በማለፍና መልዕክተኛውንም በመቃወም አትሾካሾኩ ግን በበጎ ስራና አላህን በመፍራት ተወያዩ:: ያንንም ወደ እርሱ የምትሰበሰቡበትን አላህን ፍሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 10, '10. በመጥፎ መመሳጠር ከሰይጣን ማስዋብና ማሳመር የሚመጣ ብቻ ነው:: እነዚያ ያመኑ ሙስሊሞች ያዝኑ ዘንድ ይቀሰቅሰዋል:: ከአላህ ፈቃድ ካልሆነ በስተቀር የሰይጣንም መመሳጠር በምንም ነገር አይጎዳቸዉም:: እናም ትክክለኛ አማኞች በአላህ ብቻ ይመኩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 11, '11. እናንተ ያመናችሁ ሆይ! ለእናንተ በመቀመጫዎች ስፍራ ተስፋፉ በተባላችሁ ጊዜ ስፍራን አስፉ:: አላህ በገነት ያሰፋላችኃልና:: ተነሱ በተባለም ጊዜ ተነሱ:: አላህ ከናንተ መካከል እነዚያን በትክክል ያመኑትንና እነዚያንም እውቀትን የተሰጡትን በደረጃዎች (በዚች ዓለምም ሆነ በአኼራ) ከፍ ያደርጋል:: አላህ በምትሰሩት ነገር ሁሉ ውስጠ አወቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 12, '12. እናንተ ያመናችሁ ሆይ! ከመልዕክተኛው ጋር በተወያያችሁ ጊዜ ከመወያየታችሁ በፊት ምጽዋትን አስቀድሙ:: (ሰደቃ ስጡ):: ይህ (ምጸዋትን አስቀድሞ መስጠት) ለእናንተ መልካምና አጥሪ ነው:: ባታገኙም ምንንም (ሳትከፈሉ) ሳትሰጡ ብትወያዩ ችግር የለባችሁም:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 13, '13. ከውይይታችሁ በፊት ምጽዋቶችን በማስቀደም ድህነትን ፈራችሁን? የታዘዛችሁትን ባልሰራችሁ ጊዜ አላህ ከናንተ ጸጸትን የተቀበለ ሲሆን ሶላትን ስገዱ፤ ዘካንም ስጡ፤ አላህንና መልዕክተኛውንም ታዘዙ:: አላህ በምትሰሩት ነገር ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 14, '14. ወደ እነዚያ አላህ በእነርሱ ላይ የተቆጣባቸውን ህዝቦች (አይሁዶች) ወደ ተወዳጁት አስመሳዮች አላየህምን? እነርሱ ከናንተ አይደሉም:: ከእነርሱም አይደሉም። እያወቁ በውሸት ይምላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 15, '15. አላህ ለእነርሱ (በዚህ መወዳጃና የሀሰት መሀላ) ብርቱ ቅጣትን አዘጋጀ:: እነርሱ ይሰሩት የነበሩት መጥፎ ስራ ምንኛ ከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 16, '16. መሓሎቻቸውን ጋሻ አድርገው ያዙ:: ሰዎችንም ከአላህ መንገድ አገዱ:: ስለዚህ ለእነርሱ አዋራጅ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 17, '17. ገንዘቦቻቸውና ልጆቻቸውም ከአላህ (ቅጣት) ምንም አያድኗቸዉም:: እነዚያ የእሳት ጓዶች ናቸው:: እነርሱ በእርሷ ውስጥ ዘወታሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 18, '18. አላህ የተሰበሰቡ ሆነው በሚያስነሳቸውም ቂያማ ቀን ለእናንተ እንደ ሚምሉላችሁ በሚጠቅም ነገር ላይ መሆናቸውን የሚያስቡ ሆነው ለእርሱም (ለአላህም) ይምላሉ:: ሙስሊሞች አስተዉሉ:: ውሸታሞች እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 19, '19. በእነርሱም ላይ ሰይጣን ተሾመባቸው (ተመቻቸባቸው) እናም አላህን ማስታወስን አስረሳቸው( ትዕዛዛቱን ተው):: እነዚያ የሰይጣን ቡድኖች ( ሰራዊቶች) ናቸው:: ሙስሊሞች አስተዉሉ:: የሰይጣን ቡድኖች ከሳሪዎች እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 20, '20. እነዚያ አላህንና መልዕክተኛውን የሚከራከሩ ሁሉ እነዚያ በዱንያም ሆነ በአኺራ በጣም ከተዋረዱ ወገኖች ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 21, '21. አላህ እኔ አሸንፋለሁ መልዕክተኞቼም እንዲሁ ያሸንፋሉ ሲል ድሮውኑ ጽፏል:: አላህ ብርቱና አሸናፊ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (58, 22, '22. በአላህና በመጨረሻው ቀን የሚያምኑትን ህዝቦች አላህንና መልዕክተኛውን የሚከራከሩት ሰዎች አባቶቻቸው ወይም ልጆቻቸው ወይም ወንድሞቻቸው ወይም ዘመዶቻቸው ቢሆኑም እንኳ የሚወዳጁ ሆነው አታገኛቸዉም:: እነዚያ አላህ በልቦቻቸው ውስጥ እምነትን ጽፏል:: ከእርሱም በሆነ መንፈስ ደግፏቸዋል:: ከስሮቻቸዉም ወንዞች የሚፈሱባቸው ገነቶች በውስጣቸው ዘወታሪዎች ሲሆኑ ያስገባቸዋል:: አላህ ተግባራቸውን ወዷል:: እነርሱም የእርሱን ችሮታ ወደዋል:: እነዚያ የአላህ ህዝቦች ናቸው:: ንቁ! የአላህ ህዝቦች ምኞታቸውን የሚያገኙ እነርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 1, '1. በሰማያትና በምድር ውስጥ ያለው ሁሉ አላህን አጠራ:: እርሱም ሁሉንም አሸናፊና ጥበበኛው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 2, '2. እርሱ ያ! ከመጽሐፍ ሰዎች መካከል እነዚያን በአላህ የካዱትን ወገኖች ከቤቶቻቸው የመጀመሪያውን ማስወጣት ያስወጣቸው ነው:: (ሙስሊሞች ሆይ!) መውጣታቸውንም አላሰባችሁትም ነበር:: እነርሱም ምሽጎቻቸው ከአላህ ኃይል የሚከላከሉላቸው መሆናቸውን አሰቡ:: አላህ ግን ካላሰቡት በኩል መጣባቸው:: እናም በልቦቻቸው ውስጥ መርበድበድን (ፍርሃትን) ጣለባቸው:: ቤቶቻቸውን በገዛ እጆቻቸውና በትክክለኛ አማኞች እጅ ያፈርሳሉ (አፈረሱ):: እናንተ የአእምሮ ባለቤቶች ሆይ! አስተውሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 3, '3. በእነርሱም ላይ አላህ ከአገር መውጣትን ባልፈረደ ኖሮ በቅርቢቱ ዓለም በቀጣቸው ነበር:: ለእነርሱም በመጨረሻይቱ ዓለም የእሳት ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 4, '4. ይህ እነርሱ አላህንና መልዕክተኛውን በመከራከራቸው ምክንያት ነው:: አላህን የሚከራከር ሰው ሁሉ (ይቀጣዋል።) አላህ ቅጣተ ብርቱ ነውና ይቀጣቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 5, '5. ከዘንባባ (ከተምር ዛፍ) ማንኛዋም የቆረጣችኋት ወይም በግንዶቿ ላይ የቆመች ሆና የተዋችኋት ሁሉ በአላህ ፈቃድ ነው:: አመጸኞችንም ያዋርድ ዘንድ (መቁረጥን ፈቀደ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 6, '6. ከእነርሱም ገንዘብ ወደ መልዕክተኛው አላህ የመለሰውን በእርሱ ላይ ፈረሶችንና ግመሎችን አላስጋልባችሁበትም:: ግን አላህ መልዕክተኞቹን በሚሻው ላይ ይሾማል:: አላህ በሁሉ ነገር ላይ ቻይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 7, '7. አላህ ከከተሞች ሰዎች ሀብት መካከል በመልዕክተኛው ላይ የመለሰው ሀብት ከናንተ ውስጥ በሀብታሞች መካከል ብቻ ተዘዋዋሪ እንዳይሆን ለአላህና ለመልዕክተኛው፤ ለዝምድና ባለቤትም፤ አባት ለሌላቸው የቲም ልጆችም፤ ለድሆችና፤ ለመንገደኛ፤ የሚሰጥ ነው:: መልዕክተኛው የሰጣችሁን ሁሉ ማንኛዉም ነገር ያዙት:: የከለከላችሁን ነገር ሁሉም ተከልከሉ:: አላህን ፍሩ። አላህ ቅጣተ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 8, '8. ለእነዚያ የአላህን ችሮታና ውዴታውን የሚፈልጉና አላህንና መልዕክተኛውን የሚረዱ ሆነው ከአገሮቻቸውና ከገንዘቦቻቸው ለተወጡ (ለተባረሩ) ስደተኞች ድሆች ይሰጣል:: እነዚያ እነርሱ እውነተኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 9, '9..እነዚያ ከበፊታቸው ሀገሪቱን መዲና መኖሪያ ያደረጓትና እምነት በልባቸው የሰረጸባቸው ወደ እነርሱ የተሰደዱትን ሰዎች ይወዳሉ:: ስደተኞችም ከተሰጡት ነገር ላይ በልቦቻቸው ውስጥ እንኳን ምንም ቅሬታን አያሳድሩም:: በእነርሱ ላይ ችግር ቢኖርባቸዉም እንኳ በነፍሶቻቸው ላይ ሌላውን ያስቀድማሉ:: ከነፍሶቻቸው ንፉግነት የሚጠበቁ ሰዎች ሁሉ እነዚያ የተሳካለቸውና ምኞታቸውን አግኚዎች ማለት እነርሱ ብቻ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 10, '10. እነዚያ ከበኋላቸው የመጡት «ጌታችን ሆይ! ለእኛም ለእነዚያም በእምነት ለቀደሙን ወንድሞቻችንም ምህረት አድርግ:: በልቦቻችንም ውስጥ ለእነዚያ ለአመኑት ሰዎች ሁሉ ጥላቻን አታድርግ:: ጌታችን ሆይ! አንተ ሩህሩህ፤ አዛኝ ነህና» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 11, '11. እነዚያን ወደ ንፍቅና የገቡትን አላወክምን? ከመጽሐፍ ሰዎች መካከል ለእነዚያ ለካዱት ወንድሞቻቸው «ከአገር ብትባርሩ አብረናችሁ እንወጣለን:: በእናንተ ጉዳይ አንድንም ሰው በፍጹም ሁልጊዜም አንታዘዝም:: ጦርነት ቢታወጅባችሁም በእርግጥ እንረዳችኋለን» ይሏቸዋል:: አላህም እነርሱ ውሸታሞች መሆናቸውን ይመሰክራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 12, '12. ቢባረሩም አብረዋቸው አይባረሩም:: ቢገደሉም (ቢወጉም) ቢዘመትባቸዉም አይረዱዋቸዉም:: ቢረዷቸዉም ለሽሽት ጀርባዎችን ያዞራሉ:: ከዚያም እርዳታን አያገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 13, '13. (እናንተ ያመናችሁ ሆይ!) እናንተ በልቦቻቸው ውስጥ በማስፈራራት ከአላህ ይልቅ የበረታችሁ (የከበዳችሁ) ናችሁ:: ይህም የሆነው እነርሱ የማይገነዘቡ ህዝቦች በመሆናቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 14, '14. በተመሸጉ ከተሞች ውስጥ ወይም ከአጥሮች በስተጀርባ ሆነው እንጂ የተሰበሰቡ ሆነው አይዋጓችሁም:: ኃይላቸው በመካከላቸው ብርቱ ነው:: ልቦቻቸው የተበታተኑ ሲሆን የተሰበሰቡ ናቸው ብለህ ትጠራጠራቸዋለህ (አንድ ይመስሉሃል):: ይህ እነርሱ አእምሮ የሌላቸው ህዝቦች በመሆናቸው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 15, '15. ብጤያቸው ልክ እንደነዚያ ከእነርሱ በፊት በቅርብ ጊዜ የተግባራቸውን ቅጣት እንደቀመሱት ወገኖች ብጤ ነው:: ለእነርሱም አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 16, '16. ምሳሌያቸው ልክ እንደዚያ ሰውን «በአላህ ካድ ብሎ ሰውየው በካደ ጊዜ እኔ ካንተ ንጹህ ነኝ እኔ የዓለማትን ጌታ አላህን እፈራለሁ» እንዳለው ሰይጣን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 17, '17. የሁለቱም መጨረሻቸው እነርሱ በውስጡ ዘወታሪዎች ሲሆኑ በእሳት ውስጥ መሆን ነው:: ይህም ቅጣት የበዳዩች ሁሉ ዋጋ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 18, '18. እናንተ ያመናችሁ ሆይ! አላህን በትክክል ፍሩ:: ማንኛይቱም ነፍስ ለነገ ያስቀደመችውን ትመልከት፤ አላህን በትክክል ፍሩ:: አላህ በምትሰሩት ነገር ሁሉ ውስጠ አዋቂ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 19, '19. እንደ እነዚያ አላህን እንደረሱትና ነፍሶቻቸውን እንዳስረሳቸው ሰዎች አትሁኑ:: እነዚያ እነርሱ አመጸኞች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 20, '20. የእሳት ጓዶችና የገነት ጓዶች እኩል አይሆኑም:: የገነት ጓዶች ምኞታቸውን አግኝዎች ናቸውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 21, '21. (ሙሐመድ ሆይ)፤ ይህንን ቁርኣን በተራራ ላይ ባወረድነው ኖሮ ከአላህ ፍራቻ የተነሳ ተዋራጅና ተሰንጣቂ ሆኖ ባየኸው ነበር:: እነዚህን ምሳሌዎች ለሰዎች ያስተነትኑ ዘንድ እንገልፃቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 22, '22. እርሱ ያ አላህ ነው:: ከእርሱ በስተቀር ሌላ አምላክ የሌለ፤ ሩቁንና ቅርቡን አዋቂ የሆነ ነው:: እርሱ እጅግ በጣም ሩህሩህ፤ በጣም አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 23, '23. እርሱ ያ አላህ ነው:: ከእርሱ በስተቀር ሌላ አምላክ የሌለ፤ ንጉሱ፤ ከጎደሎ ሁሉ የጠራ፤ የሰላም ባለቤት፤ ጸጥታን ሰጪ፤ ባሮቹን ጠባቂ፤ አሸናፊ፤ ኃያልና ኩሩ ነው። አላህ ከሚያጋሩት ሁሉ የጠራ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (59, 24, '24. እርሱ አላህ ፈጣሪዉ፤ ከኢምንት አስገኚዉና ቅርጽን አሳማሪው ነው:: ለእርሱ መልካሞች ስሞች አሉት:: በሰማያትና በምድር ያለው ሁሉ እርሱን ያሞግሳል:: እርሱም ሁሉን አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 1, '1. እናንተ ያመናችሁ ሆይ! ጠላቶቼንና ጠላቶቻችሁን ወዳጆች አድርጋችሁ አትያዙ:: የመጣላችሁን ትክክለኛ ሃይማኖት የካዱ ሲሆኑ ውዴታን ለእነርሱ ታደርጋላችሁ:: እነርሱ መልዕክተኛውና እናንተን በጌታችሁ በአላህ ስላመናችሁ ብቻ ከሀገራችሁ አስወጧችሁ። በመንገዴ ለመታገልና ውዴታየን ለመፈለግ የወጣችሁ እንደሆናችሁ እነርሱን ወዳጆች አድርጋችሁ አትያዟቸው:: እኔ የምትደብቁትንና የምትገልጹትን የማውቅ ስሆን ከእነርሱ ጋር ፍቅር ትመሳጠራላችሁ:: ከናንተ መካከልም ይህንን ሚፈጽም ሰው ቀጥተኛውን መንገድ በእርግጥ ስቷል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 2, '2. ቢያሸንፏችሁ (ቢያገኟችሁ) ለእናንተ ጠላቶች ይሆናሉ:: እጆቻቸውና ምላሶቻቸውንም ወደ እናንተ በክፉ ይዘረጋሉ:: ብትክዱም ተመኙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 3, '3. ዘመዶቻችሁም ሆኑ ልጆቻችሁ በትንሳኤ ቀን አይጠቅሟችሁም:: አላህ በትንሳኤ ቀን በመካከላችሁ (ብይን በመስጠት) ይለያል:: አላህ የምትሰሩትን ሁሉ ተመልካች ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 4, '4. ኢብራሂምና እነዚያ ከእርሱ ጋር አብረው የነበሩት አማኞች ለእናንተ መልካም አርአያ ናቸው:: ይኸዉም ለህዝቦቻቸው «እኛ ከናንተና ከዚያ ከአላህ ሌላ ከምትገዙት ጣዖታት ሁሉ ንጹሆች ነን:: በእናንተም ካድን:: በአላህ አንድነት እስከምታምኑ ድረስ በእኛና በእናንተ መካከል ጠብና ጥላቻ ዘወትር ተገለጸ::» ባሉ ጊዜ ኢብራሂም ለአባቱ፡- «ላንተ ከአላህ ቅጣት ምንም የማልጠቅምህ (የማላድንህ) ስሆን ላንተ በእርግጥ ምህረትን እለምንልሃለሁ::» ማለቱ ብቻ ሲቀር «ጌታችን ሆይ ባንተ ላይ ተመካን ወደ አንተም ተመለስን መመለሻም ወደ አንተ ብቻ ነው::» (ባለው ተከተሉ።)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 5, '5. ጌታችን ሆይ! ለእነዚያ ለካዱት ሰዎች መሞከሪያ አታድረገን:: ለእኛ ምህረት አድርግልን:: ጌታችን ሆይ! አንተ አሸናፊና ጥበበኛው ነህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 6, '6. ከናንተ መካከል አላህንና የመጨረሻውን ቀን ተስፋ ለሚያደርግ ሰው ሁሉ እነርሱ መልካም አርአያዎች አሉላችሁ:: ፊቱን የሚያዞር ሰው (ራሱን ብቻ ይጎዳል።) አላህ ብቸኛ፤ ተብቃቂና ምስጉን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 7, '7. አላህ በእናንተና በእነዚያ ከእነርሱ ጋር በተጣላችሁት ሰዎች መካከል መፋቀርን ሊያደርግ ይከጀላል:: አላህ ሁሉን ማድረግ ቻይ ነው:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 8, '8. ለእነዚያ በሃይማኖት ላልተዋጓችሁ ከአገሮቻችሁም ላላስወጧችሁ ከሓዲያን መልካም ብትውሉላቸውና ወደ እነርሱ ፍትህ ልትውሉላቸው አላህ አይከለክላችሁም:: አላህ ትክክለኞችን (ፍትሃዊያን ትክክለኛ አማኞች) ይወዳልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 9, '9. አላህ የሚከለክላችሁማ ከእነዚያ በሃይማኖት ሰበብ ከተዋጓችሁና ከቤቶቻችሁም ያስወጧችሁ እናንተንም ከሀገር በማስውጣት ላይ የረዱትን እንዳትወዳጇቸው ብቻ ነው:: እነርሱን ወጃጅ የሚያደርጓቸው ሰዎች ሁሉ እነዚያ እነርሱ (ራሳቸዉን) በዳዩች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 10, '10. እናንተ ያመናችሁ ሆይ! ሴት ምዕመናት ስደተኞች ሆነው ወደ እናንተ በሚመጡበት ጊዜ (ለሀይማኖት ሲሉ መሰደዳቸውን) ፈትኗቸው:: አላህ በእምነታቸው ከናንተ ይልቅ አዋቂ ነው:: ትክክለኛ አማኞችም መሆናቸውን ብታውቁ ወደ ከሓዲያን ባሎቻቸው አትመልሷቸው:: እነርሱ ሙስሊም ሴቶች ለከሓዲ ወንዶች አይፈቀዱምና:: ከሓዲያን ወንዶችም ለአማኝ ሴቶች የተፈቀዱ አይደሉምና:: ያወጡትንም ገንዘብ መህሩን ስጧቸው:: መህራቸውንም ከሰጣችኋቸው ብታገቧቸው ኃጢአት የለባችሁም :: የከሓዲያንንም ሴቶች የጋብቻ ቃል ኪዳኖች አትያዙ:: ሆኖም እናንተ ያወጣችሁትን ገንዘብ ጠይቁ :: እነርሱም ያወጡትን ይጠይቁ:: ይህ የአላህ ፍርድ ነውና:: በመካከላችሁም ይፈርዳል:: አላህ ሁሉን አዋቂና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 11, '11. ከሚስቶቻችሁም አንዳቸው ወደ ከሓዲያን ቢያመልጧችሁ ቀጥሎም ብትዘምቱባቸው ለእነዚያ ሚስቶቻቸው ለሄዱባቸው ሰዎች ያወጡትን ወጪ ያክል ስጧቸው። ያንንም እናንተ በእርሱ ያመናችሁበትን አላህን ፍሩት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 12, '12. አንተ ነብይ ሆይ! ምዕመናቶቹ በአላህ ምንም ላያጋሩ፤ ላይሰርቁ፤ ላያመነዝሩ፤ ልጆቻቸውን ላይገድሉ፤ በእጆቻቸውና በእግሮቻቸው መካከል ኃጢአትን ላያመጡ (ላይሰሩ)፤ በበጎም ስራም ትዕዛዝን ላይጥሱ ቃል ኪዳን ሊገቡልህ ወደ አንተ በመጡ ጊዜ ቃል ኪዳን ተጋባቸው:: ለእነርሱም አላህን ምህረት ለምንላቸው:: አላህ በጣም መሀሪና እጂግ በጣም አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (60, 13, '13. እናንተ ያመናችሁ ሆይ! አላህ በእነርሱ ላይ የተቆጣባቸውን ህዝቦች አትወዳጁ:: ከሓዲያን ከመቃብር ሰዎች ተስፋ እንደቆረጡ ሁሉ በመጨረሻይቱም ዓለም (ምንዳ መኖር) በእርግጥ ተስፋ ቆርጠዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 1, '1. በሰማያትና በምድር ውስጥ ያሉ ሁሉ አላህን አጠሩ:: እርሱ አሸናፊና ጥበበኛው ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 2, '2. እናንተ ያመናችሁ ሆይ! የማትሰሩትን ነገር ለምን ታወራላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 3, '3. የማትሰሩትን ነገር መናገራችሁ በአላህ ዘንድ በመጠላት እጅግ ከበደ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 4, '4. አላህ እነዚያን ልክ እንደተለሰነ ግንብ የተሰለፉ ሆነው በሃይማኖቱ የሚፋለሙትን ይወዳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 5, '5. (መልዕክተኛችን ሙሐመድ ሆይ!) ሙሳም ለህዝቦቹ፡- «ህዝቦቼ ሆይ! እኔ ወደ እናንተ የአላህ መልዕክተኛ መሆኔን እያወቃችሁ ለምን ታሰቃዩኛላችሁ?» ባለ ጊዜ የሆነውን አስታውስ:: ከእውነት በተዘነበሉ ጊዜ አላህም ልቦቻቸውን አዘነበለባቸው:: አላህ አመጸኞችን ህዝቦች አያቀናምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) የመርየም ልጅ ዒሳም፡- «የኢስራኢል ልጆች ሆይ! እኔ ከተውራት በፊት ያለውን የማረጋግጥና ከእኔ በኋላ በሚመጣው መልዕክተኛ ስሙ አህመድ በሆነውም የማበስር ስሆን ወደ እናንተ የተላኩ የአላህ መልዕክተኛ ነኝ» ባለ ጊዜ የሆነውን አስታውስ:: ግልጽ ታዐምራቶችን ባመጣላቸው ጊዜ «ይህ ግልጽ ድግምት ነው» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 7, '7. እርሱ ወደ ኢስላም የሚጠራ ሲሆን በአላህ ላይ ውሸትን ከቀጣጠፈ ይበልጥ በደለኛ ማን ነው? አላህ በዳዮችን ህዝቦች አይመራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 8, '8. የአላህን ብርሃን በአፎቻቸው ሊያጠፉ ይሻሉ:: ከሓዲያን ቢጠሉም እንኳ አላህ ብርሀኑን ገላጭ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 9, '9. አላህ ያ አጋሪዎቹ ቢጠሉም መልዕክተኛውን በመምሪያ መጽሐፍና በእውነተኛ ሃይማኖት (በኢስላም) ከሃይማኖት ሁሉ በላይ ይፋ ሊያደርገው የላከ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ ያመናችሁ ሆይ! ከአሳማሚ ቅጣት የሚያድናችሁን ትርፋማ ንግድ ላመላክታችሁን?» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 11, '11. እርሱም በአላህና በመልዕክተኛው ታምናላችሁ:: በአላህ መንገድ በገንዘቦቻችሁና በነፍሶቻችሁ ትታገላለችሁ:: ይህ ተግባር የምታውቁ ከሆናችሁ ለእናንተ የተሻለ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 12, '12. ኃጢአቶቻችሁን ይምራል:: ከስሮቻቸው ወንዞች የሚፈሱባቸዉም ገነቶች ያስገባችኋል:: በመኖሪያ ገነቶችም በሚያምሩ ቤቶች ውስጥ ያስቀምጣችኋል:: ይህ ታላቅ እድል ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 13, '13. ሌላይቱንም የምትወዷትን ጸጋ ይሰጣችኋል:: እርሷም ከአላህ የሆነ እርዳታና ቅርብ የሆነ አገር መክፈት ነው:: አማኞችንም አብስር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (61, 14, '14. እናንተ ያመናችሁ ሆይ! የመርየም ልጅ ዒሳ ለሐዋሪያቱ፡- «ወደ አላህ ረዳቴ ማን ነው» እንዳለና ሐዋርያቶቹም፡- «እኛ የአላህ ረዳት ነን» እንዳሉት ሁሉ እናንተም የአላህ ረዳቶች ሁኑ፤ ከኢስራኢል ልጆችም አንደኛዋ ቡድን አመነች:: ሌላይቱም ቡድን ካደች:: እነዚያን ያመኑትንም በጠላታቸው ላይ አበረታናቸው:: ከዚያ እነርሱም አሸናፊዎች ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 1, '1. በሰማይና በምድር ውስጥ ያለው ሁሉ ንጉስ፤ ፍፁም (ከጉድለት ንጹህ)፤ አሸናፊና ጥበበኛ የሆነውን አላህን ያሞግሳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 2, '2. እርሱ ያ ለመሃይማን ዐረቦች የቁርአን አናቅጽን በእነርሱ ላይ የሚያነብላቸው፤ የሚያጠራቸዉም፤ መጽሐፍንና ጥበብን የሚያስተምራቸዉም የሆነን መልዕክተኛ ሙሐመድን ከእነርሱ መካከል የላከ ነው:: እነርሱም ከእርሱ በፊት በግልጽ ስህተት ውስጥ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 3, '3.ከነሱም ሌሎችም ገና ያልተከተሏቸው በሆኑት ላይ የላከው ነው:: እርሱም አሸናፊና ጥበበኛ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 4, '4. ይህ የአላህ ችሮታ ነው:: ለሚሻው ሰው ይሰጠዋል:: አላህ የታላቅ ችሮታ ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 5, '5. የእነዚያ ተውራትን የተጫኑትና ከዚያ ያልተሸከሟት (ያልሰሩባት) ሰዎች ምሳሌ ልክ መጽሐፎችን እንደሚሸከም አህያ ብጤ ነው:: የእነዚያ በአላህ አናቅጽ ያስተባበሉት ህዝቦች ምሳሌ ከፋ:: አላህም በዳዮችን ህዝቦች አይመራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) «እናንተ አይሁዳውያን ሆይ! ከሰው ሁሉ በተለየ እናንተ ብቻ ለአላህ ወዳጆች ነን ብትሉና በዚያ አባባላችሁ እውነተኞች እንደሆናችሁ እስቲ ሞትን ተመኙ» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 7, '7. እጆቻቸው ባስቀደሙት ኃጢአት ምክንያት በፍጹም አይመኙትም:: አላህ በዳዮችን አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 8, '8. (መልዕክተኛችን ሙሐመድ ሆይ!) «ያ ከእርሱ የምትሸሹት ሞት እርሱ በእርግጥ አግኛችሁ ነው:: ከዚያም ሩቁንና ቅርቡን አዋቂ ወደ ሆነው ጌታ በቂያማ ዕለት ተመላሾች ናችሁ:: ትሰሩትም የነበራችሁትን ሁሉ ይነግራችኋል» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 9, '9. እናንተ ያመናችሁ ሆይ! በአርብ (በጁሙዓ) ቀን ለስግደት ጥሪ በተደረገ ጊዜ ወደ አላህ ማውሳት (ኹጥባ፣ ሶላት) ተጣደፉ:: መሸጥንም ተው:: የምታውቁ ብትሆኑ ይህ ለእናንተ በጣም የተሻለ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 10, '10. ሶላቷ በተፈጸመችም ጊዜ በምድር ላይ ተበተኑና የአላህን ችሮታ ፈልጉ:: ልትድኑ ይከጀላልና አላህንም በብዙው አውሱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (62, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ!) ንግድን ወይም ዛዛታን ባዩ ጊዜም ቆመህ የተውህ ሲሆኑ ወደ እርሷ ይበተናሉ:: «አላህ ዘንድ ያለው ከዛዛታም ከንግድም በላጭ ነው:: አላህም ከሰጭዎች ሁሉ ይበልጥ ሲሳይን ሰጪ ነው» በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 1, '1. አስመሳዮች በመጡህ (ወደ አንተ በመጡ) ጊዜ «አንተ የአላህ መልዕክተኛ መሆንህን በእርግጥ (ምለን) እንመሰክራለን» ይላሉ:: አላህም አንተ በእርግጥ መልዕክተኛው መሆንህን ያውቃል:: አላህም አስመሳዮችን ውሸታሞች መሆናቸውን ይመሰክራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 2, '2. መሓላዎቻቸውን ጋሻ አድርገው ያዙ:: ከአላህም መንገድ ከለከሉ:: እነርሱ ይሰሩት የነበሩት ነገር ሁሉ ከፋ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 3, '3. ይህ እነርሱ (በምላስ) አምነው ከዚያም (በልብ) የካዱ በመሆናቸው በልቦቻቸዉም ላይ ታተመባቸው:: ስለዚህ እነርሱ አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 4, '4. ባየሃቸው ጊዜ አካሎቻቸው ያስደንቁሃል:: ቢናገሩም ንግግራቸውን ታዳምጣለህ:: እነርሱ ልክ ወደ ግድግዳ የተጠጉ ግንዶችን ይመስላሉ:: ጩኸትን ሁሉ በእነርሱ ላይ ነው ብለው ያስባሉ:: እነርሱ ጠላቶች ናቸውና ተጠንቀቃቸው:: አላህ ይጋደላቸው:: (ከእምነት) እንዴት ይመለሳሉ (ያፈገፍጋሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 5, '5. ለእነርሱም፡- «ኑ የአላህ መልዕክተኛ ለእናንተ ምህረትን ይለምንላችኋል» በተባሉ ጊዜ በማፌዝ ራሶቻቸውን ያዞራሉ:: እነርሱም ትዕቢተኞች ሆነው ሲሸሹ ታያቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 6, '6. ምህረትን ብትለምንላቸውም ባትለምንላቸዉም በእነርሱ ላይ ሁሉም እኩል ነው:: አላህ ለእነርሱ በፍጹም አይምርም:: አላህ አመጸኛ ህዝቦችን አይመራምና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 7, '7. እነርሱ፡- «እነዚያ ከአላህ መልዕክተኛ ዘንድ ያሉት ሰዎች እስከ ሚበታተኑ ድረስ ምጽዋት አትስጡ» የሚሉ ናቸው:: የሰማያትና የምድር ድልቦች የአላህ ብቻ ናቸው:: ግን አስመሳዮች አይገነዘቡም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 8, '8. «ወደ መዲና ብንመለስ አሸናፊው ወራዳውን በእርግጥ ከእርሷ ያስወጣል» ይላሉ:: አሸናፊነትም ለአላህ ለመልዕክተኛው እና ለምዕምና ብቻ ነው:: ግን አስመሳዮች አያውቁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 9, '9. እናንተ ያመናችሁ ሆይ! ገንዘቦቻችሁና ልጆቻችሁ አላህን ከማስታወስ አያታልሏችሁ (አያዘናጓችሁ):: ይህንንም የሚሰሩ ሰዎች እነዚያ እነርሱ ከሳሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 10, '10. አንዳችሁም ሞት ሳይመጣበትና «ጌታየ ሆይ! እንድመጸውትና ከደጋጎችም ሰዎች እንድሆን ጥቂት ጊዜ ብታቆየኝ ኖሮ እመኛለሁ» ከማለቱ በፊት ከሰጠናችሁ ሲሳይ ለግሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (63, 11, '11. ማንኛይቱም ነፍስ የሞት ጊዜዋ በመጣባት ጊዜ አላህ በፍጹም አያቆያትም:: አላህም በምትሰሩት ሁሉ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 1, '1. በሰማያት ውስጥም ሆነ በምድር ውስጥ ያለው ሁሉ አላህን ያሞግሳል:: ንግስናው የእርሱ ብቻ ነው:: ምስጋናም ለእርሱ ብቻ ነው:: እርሱም በነገሩ ሁሉ ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 2, '2. እርሱ ያ የፈጠራችሁ ነው:: ከእናንተም መካከል ከሓዲ አለ:: ከእናተም መካከል አማኝ አለ:: አላህ የምትሰሩትን ሁሉ ተመልካች ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 3, '3. (እርሱ) ሰማያትንና ምድርን በእውነት ፈጠረ:: ቀረጻችሁም ቅርጻችሁንም አሳመረ፡፡ መመለሻችሁም ወደ እርሱ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 4, '4. በሰማያትና በምድር ውስጥ ያለውን ሁሉ ያውቃል:: የምትደብቋትንም ሆነ የምትገልጡትን ያውቃል:: አላህም በልቦች ውስጥ ያለውን ሁሉ ዐዋቂ ነው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 5, '5. የእነዚያ ከአሁን በፊት የካዱትና የክህደታቸውን ቅጣት የቀመሱ ህዝቦች ወሬ አልመጣላችሁምን? ለእነርሱ አሳማሚ ቅጣት አለባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 6, '6. ይህ (ቅጣት) እነርሱ መልዕክተኞቻቸው አስረጂዎችን ይዘው ሲመጡላቸው «ሰዎች ይመሩናልን?» ስላሉና ስለ ካዱ፤ ከእምነትም ስለ ዞሩ ነው:: አላህ ከእነርሱ እምነት ተብቃቃ:: አላህ ተብቃቂና ምስጉን ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 7, '7. (መልዕክተኛችን ሙሐመድ ሆይ!) እነዚያ በአላህ የካዱት ሰዎች በፍጹም የማይቀሰቀሱ መሆናቸውን አሰቡ። «(እንዴት አትቀሰቀሱም?) በጌታየ ይሁንብኝ ትቀሰቀሳላችሁ:: ከዚያ ትፈጽሙት የነበረውን ተግባራችሁን ትናገራላችሁ:: ይህ ተግባር ለአላህ ቀላል ነው» በላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 8, '8. በአላህ በመልዕክተኛውና በዚያም ባወረድነው ብርሃን እመኑም:: አላህ የምትሰሩትን ሁሉ ውስጠ አዋቂ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 9, '9. (ይኸዉም) ለመሰብሰቢያው ቀን የሚሰበስባችሁ እለት አስታውሱ:: ይህ ቀን የቁጭት ቀን ነው:: በአላህም የሚያምን ሰው መልካምንም የሚሠራ ከርሱ ኃጢአቶቹን ይሰርይለታል፤ (ይፍቅለታል)፤ ከስሮቿ ወንዞች የሚፈሱባት ገነቶች ለዘላለም ያስገባዋል:: ይህ ታላቅ እደለኝነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 10, '10. እነዚያም የካዱትና በአንቀፆቻችንም ያስተባበሉት የዝንታለም እሳት ባለቤቶች ማለት እነርሱ ናቸው:: (ጀሀነም) መመለሻነቷ ምን ይከፋ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 11, '11. ከመከራም በአላህ ፈቃድ ቢሆን እንጂ ማንንም አይነካም:: በአላህ የሚያምን ሰው አላህ ልቡን ለትግስት ይመራዋል:: አላህም በሁሉም ነገር አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 12, '12. አላህን ታዘዙ መልዕክተኛውንም ታዘዙ:: ብትዞሩም (መልዕክተኛውን አትጎዱም::) በመልዕክተኛችንም ላይ ያለበት በግልጽ ማድረስ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 13, '13. አላህ ከእርሱ በስተቀር ትክክለኛ አምላክ የለም:: ትክክለኛ አማኞች በአላህ ብቻ ይመኩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 14, '14. እናንተ ያመናችሁ ሆይ! ከሚስቶቻችሁና ከልጆቻችሁ (ከአላህ መንገድ በማስተጓጎል) ለእናንተ ጠላቶች የሆኑ አሉ:: ስለዚህ ተጠንቀቋቸው:: ይቅርታ ብታደርጉ፤ ብታልፏቸዉም፤ ብትምሩዋቸዉም፤ አላህ በጣም መሀሪ፤ አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 15, '15. ገንዘቦቻችሁና ልጆቻችሁ ለእናንተ መፈተኛ ብቻ ናቸው:: አላህም ከእርሱ ዘንድ ታላቅ ምንዳ አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 16, '16. አላህንም የቻላችሁትን ያህል ፍሩት:: ትዕዛዙን ስሙም፤ ታዘዙም፤ ለግሱም፤ ለነፍሶቻችሁ መልካምን ይሰጣችኋልና:: የነፍሶቻቸዉን ንፍገት የሚጠበቁ ሰዎች ሁሉ እነዚያ እነርሱ ፍላጎታቸውን የሚያገኙ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 17, '17. ለአላህ መልካም ብድርን ብታበድሩት (ምንዳውን) ለእናንተ ይደራርበዋል:: ለእናንተም ይምራል:: አላህ አመስጋኝና ታጋሽ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (64, 18, '18. (እርሱ) ስውሩንም ይፋዉንም ሁሉን አዋቂ ኃያልና ጥበበኛ ነዉና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 1, '1. አንተ ነብይ ሆይ! ሴቶችን መፍታት ባሰባችሁ ጊዜ፤ ለዒዳቸው ፍቷቸው፤ ዒዳንም ቁጠሩ፤ ጌታችሁን አላህን ፍሩ፤ ግልጽ የሆነችን ጠያፍ ካልሰሩ በስተቀር ከቤቶቻቸው አታውጧቸው:: አይውጡም፤ ይህችም የአላህ ህግጋት ናት:: የአላህንም ህግጋት የተላለፈ ሰው በእርግጥ ነፍሱን በደለ፤ ከዚህ (ፍች) በኋላ አላህ (የመማለስ) ነገርን ምናልባት ያመጣ እንደኾነ አታውቅም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 2, '2. ጊዜያቸውንም ለመዳረስ በተቃረቡ ጊዜ በመልካም ያዟቸው፤ ወይም በመልካም ተለያዩዋቸው፤ ከናንተም ውስጥ ሁለት የትክክለኛነት ባለቤቶችን አስመስክሩ፤ ምስክርነትንም ለአላህ አስተካክሉ፤ ይሃችሁ በአላህና በመጨረሻ ቀን የሚያምን የሆነ ሰው ሁሉ በእርሱ ይገሰጽበታል፤ አላህንም የሚፈራ ሰው ለእርሱ መውጫን ያደርግለታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 3, '3. ከማያስበዉም በኩል ሲሳይን ይሰጠዋል፤ በአላህም ላይ የሚጠጋ ሰው እርሱ በቂው ነው:: አላህ ፈቃዱን አድራሽ ነው:: አላህ ለነገሩ ሁሉ የተወሰነ ጊዜን በእርግጥ አድርጓል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 4, '4. እነዚያም ከሴቶቻችሁ ከአደፍ (ከወር አበባ) ያቋረጡት በዒዳቸው ህግ ብትጠራጠሩ ዒዳቸው ሶስት ወር ነው:: እነዚያም ገና አደፍን ያላዩ ሴቶችም ዒዳቸው እንደዚሁ ነው:: የእርግዝና ባለቤቶችም ጊዜያቸው እርጉዛቸውን መውለድ ነው፤ አላህንም የሚፈራ ሰው ከነገሩ ሁሉ ለእርሱ መግራትን ያደርግለታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 5, '5. ይህ የአላህ ፍርድ ነው:: ወደ እናንተ አወረደው፤ አላህንም የሚፈራ ሰው ሁሉ ኃጢአቶችን ከርሱ ይሰርዝለታል:: ምንዳንም ለእርሱ ያተልቅለታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 6, '6. ከችሎታችሁ ከተቀመጣችሁበት ስፍራ አስቀምጧቸው:: በእነርሱም ላይ ልታጣብቡ አትጉዷቸው:: የእርግዝና ባለቤቶችም ቢሆኑ እርጉዛቸውን እስኪወልዱ ድረስ በእነርሱ ላይ ቀልቡ። ለእናንተም ልጆቻችሁን ቢያጠቡላችሁ የልፋት ዋጋቸውን ስጧቸው:: በመካከላችሁም በመልካም ነገር ተመካከሩ፤ ብትቸጋገሩም ለእርሱ ሌላ (ሴት) ታጠባለታለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 7, '7. የችሎታ ባለቤት በችሎታው ልክ ይቀልብ፤ በእርሱም ላይ ሲሳዩ የተጠበበበት ሰው አላህ ከሰጠው ይስጥ ነፍስን የሰጣትን ያህል እንጂ አያስገድድም:: አላህ ከችግር በኋላ ምቾትን በእርግጥ ያደርጋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 8, '8. ከከተማም መካከል ከጌታቸው እና ከመልዕክተኞች ትዕዛዝ ያመጹ በመሆናቸው፤ ብርቱን ቁጥጥር የተቆጣጠርናቸዉና መጥፎንም ቅጣት የቀጣናቸው ብዙ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 9, '9. የነገራቸዉንም ቅጣት ቀመሱ:: የነገራቸዉም መጨረሻ ኪሳራ ሆነ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 10, '10. አላህ ለእነርሱ ብርቱ ቅጣትን አዘጋጀ:: እናንተም በአላህ ያመናችሁ የአእምሮ ባለ ቤቶች ሆይ! አላህን ፍሩ፤ አላህ ወደ እናንተ ግሳጼን በእርግጥ አወረደ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 11, '11. እነዚያን ያመኑትንና መልካሞችን የሰሩትን ከጨለማዎች ወደ ብርሃን ያወጣ ዘንድ የአላህን አንቀጾች ገላጮች ሲኾኑ በእናንተ ላይ የሚያነብላችሁን መልዕክተኛን ላከ:: በአላህም አናቅጽ የሚያምን መልካምን ስራ የሚሰራም ከስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶች በውስጣቸው ዘለዓለም ዘውታሪዎች ሲሆኑ ያገባዋል አላህ ለርሱ ሲሳይን በእርግጥ አሳመረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (65, 12, '12. አላህ ያ ሰባትን ሰማያት የፈጠረ ነው:: ከምድርም መሰላቸውን (ፈጥሮአል)፤ በመካከላቸዉም ትዕዛዙ ይወርዳል:: አላህ በነገሩ ሁሉ ላይ ቻይ መሆኑን አላህም በነገሩ ሁሉ በእውቀት ያካበበ መሆኑን ታውቁ ዘንድ (ይህንን አሳወቃችሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 1, '1. አንተ ነብይ ሆይ! አላህ ላንተ የፈቀደልህን ነገር ሚሰቶችህን ማስወደድን የምትፈልግ ስትሆን (ባንተ ላይ) ለምን እርም ታደርጋለህ? አላህ እጅግ መሀሪና አዛኝ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 2, '2. አላህ ለእናንተ የመሐሎቻችሁን መፍቻ ደነገገላችሁ፤ አላህ ረዳታችሁ ነው:: እርሱም ሁሉን አዋቂና እጅግ ጥበበኛ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 3, '3. ነብዩ ከሚስቶቹ ወደ አንዷ ወሬን በመሰጠረ ጊዜ (አስታውስ):: እርሱንም በነገረችና አላህ እርሱን ማውራቷን ባሳወቀው ጊዜ ከፊሉን አሳወቀ፤ ከፊሉንም ተወ፤ በእርሱም ባወራት ጊዜ «ይህን ማን ነገረህ?» አለች፤ «ሁሉን አዋቂው እና ውስጠ አዋቂው ነገረኝ» አላት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 4, '4. (ሁለታችሁም) ወደ አላህ ብትመለሱ ልቦቻችሁ በእርግጥ ተዘንብለዋልና (ትስማማላችሁ):: በእርሱ (ጥቃት) ላይ ብትረዳዱ ግን ረዳቱ አላህ ነው። ጂብሪልም ከምእምናንም መልካሙ ከዚህም በኋላ መላእክቱ ረዳቶቹ ናቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 5, '5. ሁላችሁንም ቢፈታችሁ ከናንተ የበለጡ ሚስቶች ሙስሊሞች፤ ትክክለኛ አማኞች፤ ታዛዦች፤ ተጸፃቾች፤ ለአላህ ተገዢዎች፤ ጿሚዎች፤ ፈቴዎችም ደናግልም የሆኑትን ጌታው ሊለውጠው ይከጅላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 6, '6. እናንተ ያመናችሁ ሆይ! መቀጣጠያዋ ሰዎችና ደንጋዮች ከሆነች እሳት ነፍሶቻችሁንም ቤተሰቦቻችሁንም ጠብቁ፤ በእርሷ ላይ ጨካኝና ኃይለኛ የሆኑ መላዕክት አሉ:: አላህን ያዘዛቸውን ነገር በመጣስ አያምጹም፤ የሚታዘዙትንም ሁሉ ይሰራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 7, '7. እናንተ በአላህ የካዳችሁ ሰዎች ሆይ! ዛሬ አታመካኙ፤ የምትመነዱት ያንን ትሰሩት የነበራችሁትን ብቻ ነው (ይባላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 8, '8. እናንተ ያመናችሁ ሆይ! አላህ ነብዩን እነዚያንም ከእርሱ ጋር ያመኑትን በማያሳፍርበት፤ ብርሃናቸው በፊቶቻቸውና በቀኞቻቸው የሚሮጥ ሲሆን፡- «ጌታችን ሆይ! ብርሃናችንን ሙላልን፤ ለእኛ ምህረትንም አድርግልን፤ አንተ በነገሩ ሁሉ ላይ ቻይ ነህና» በሚሉበት ቀን ጌታችሁ ከናንተ ኃጢአቶቻችሁን ሊሰርዝላችሁ፤ ከስሮቻቸው ወንዞች የሚፈሱባቸውን ገነቶችም ሊያስገባችሁ ይከጅላልና ንጹህ የሆነችን ጸጸት በመጸጸት ወደ አላህ ተመለሱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 9, '9. አንተ ነብይ ሆይ! ከሓዲያን እና አስመሳዮችን ታገል፤ በእነርሱም ላይ በርታ፤ መኖሪያቸዉም ገሀነም ናት:: ምን ትከፋም መመለሻ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 10, '10. አላህ ለእነዚያ ለካዱት ሰዎች የኑህን ሚስት እና የሉጥን ሚስት ምሳሌ አደረገ፤ ባሮቻችን ከሆኑ ሁለት መልካም ባሪያዎች ስር ነበሩ ከዷቸዉም፤ ኑሕም ሉጥም ከሚስቶቻቸው ምንም የአላህን ቅጣት አልገፈተሩላቸዉም፤ «ከገቢዎችም ጋር እሳትን ግቡ» ተባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 11, '11. ለእነዚያ ለአመኑትም አላህ የፈርዖንን ሚስት ምሳሌ አደረገ:: «ጌታየ ሆይ! አንተ ዘንድ በገነት ውስጥ ለእኔ ቤት ገንባልኝ፤ ከፈርዖንና ከስራዉም አድነኝ፤ ከበደለኞች ህዝቦችም አድነኝ» ባለች ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (66, 12, '12. የዒምራን ልጅ መርየምንም ያችን ብልቷን የጠበቀችውን ምሳሌ አደረገ:: በእርሷም ውስጥ ከመንፈሳችን ነፋን:: በጌታዋ ቃላትና በመጽሐፍቱም አረጋገጠች፤ ከታዛዦችም ነበረች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 1, '1. ያ ንግስና በእጁ የሆነው አምላክ ችሮታው በዛ:: እርሱም በሁሉም ነገር ላይ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 2, '2. ያ የየትኛችሁ ስራ ይበልጥ ያማረ መሆኑን ሊሞክራችሁ ሞትንና ህይወትን የፈጠረ ነው:: እርሱም አሸናፊና መሀሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 3, '3. ያ ሰባቱን ሰማያት የተነባበሩ ሆነው የፈጠረ ነው:: በአል ረህማን አፈጣጠርም ውስጥ ምንም ቅንጣት ያህል መዛነፍን (መቃረንና መበላሸት) አይታይም:: ዓይንህንም መልስ:: ከስንጥቆች አንዳችን ታያለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 4, '4. ከዚያም ዓይንህን መላልስ:: ዓይንህ ተዋርዶ (ተናንሶ)፤ እርሱም የደከመ ሆኖ ወደ አንተ ይመለሳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 5, '5. ቅርቢቱን ሰማይም በእርግጥ በመብራቶች (በከዋክብት) አጌጥናት:: ለሰይጣናትም መቀጥቀጫዎች አደረግናት፤ ለእነርሱም ተንቀልቃይ የእሳትን ቅጣት አዘጋጀንላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 6, '6. ለእነዚያም በጌታቸው ለካዱት የገሀነም ቅጣት አላቸው:: መመላሻይቱም ገሀነም ከፋች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 7, '7. በውስጧ በተጣሉ ጊዜ እርሷ የምትፈላ ስትሆን ከእርሷ እንደ (አህያ) ማናፋትን ይሰማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 8, '8. ከቁጭቷ የተነሳ ልትቆራረጥ ትቀርባለች:: በውስጧ ቡድኖች በተጣሉ ቁጥር «ዘበኞቿ (ስለዚህ ቀን) አስፈራሪ (ነብይ) አልመጣላችሁም ነበርን?» በማለት ይጠይቋቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 9, '9. «አይደለም በእርግጥ አስፈራሪ መጥቶልናል:: አስተባበልንም:: አላህም ምንንም አላወረደም:: እናንተ አውርዷል ስትሉ፤ በትልቅ ስህተት ውስጥ እንጂ አይደላችሁም አልን» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 10, '10. «የምንሰማ ወይም የምናስብ በነበርን ኖሮ የእሳት ጓዶች ባልሆን ነበር» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 11, '11. በኃጢአታቸዉም ያምናሉ:: ለእሳት ጓዶችም (ከእዝነት) መራቅ ተገባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 12, '12. እነዚያ ጌታቸውን በሩቁ የሚፈሩ ለእነርሱ ምህረትንና ታላቅ ምንዳ አለላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 13, '13. (ሰዎች ሆይ!) ቃላችሁንም መስጥሩ:: ወይም በእርሱ ጩሁ:: እርሱ በልቦች ውስጥ ያለን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 14, '14. የፈጠረን አምላክ እርሱ እውቀተ ረቂቁ ውስጠ አዋቂው ሲሆን (ሚስጢርን) ሁሉ አያውቅምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 15, '15. እርሱ ያ ምድርን ለእናንተ የተገራች ያደረገላችሁ ነው:: በጋራዎቿና በመንገዶቿም ሂዱ:: ከሲሳዮም ብሉ:: (ኋላ) መመለሻችሁም ወደ እርሱ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 16, '16. በሰማይ ያለው ጌታ በእናንተ ምድርን እንደማያሰምጥባችሁ ወዲያዉም እርሷም (እናንተኑ ውጣ) የምታረገርግ እንደማትሆን ትተማመናላችሁን? (አትፈሩምን?)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 17, '17. ወይስ በሰማይ ያለው ጌታ በእናንተ ላይ ጠጠርን ያዘለች ንፋስን እንደማልክባችሁ ትተማመናላችሁ? (አትፈሩም?) ማስጠንቀቄም እንዴት እንደሆነ ወደ ፊት ታውቃላችሁ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 18, '18. እነዚያ ከእነርሱ በስተፊት የነበሩትም አስተባበሉ:: ጥላቻየም እንዴት ነበር (አስተዉል)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 19, '19. ከበላያቸው ሰልፍ ሰርተው ወዳሉ ወፎች አይመለከቱምን? ክንፎቻቸውን ያጥፋሉ:: ከአር-ረህማን ሌላ የሚይዛቸው የለም:: እርሱ ሁሉን ነገር አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 20, '20. በእውነት ያ እርሱ ከአር-ረህማን ሌላ የሚረዳችሁ ለእናንተ የሆነ ሰራዊት ማነው? ከሓዲያን በመታለል ውስጥ እንጂ በሌላ ላይ አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 21, '21. ወይም ሲሳዮን ቢይዝባችሁ ያ ሲሳይን የሚሰጣችሁ ማነው? በእውነት እነርሱ በሞገድና በመደንበር ውስጥ ጸኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 22, '22. በፊቱ ላይ ተደፍቶ የሚሄድ ሰው ይበልጥ የተቀና ነውን? ወይስ በቀጥተኛው መንገድ ላይ ተስተካክሎ የሚሄድ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 23, '23. እርሱ! ያ አላህ የፈጠራችሁ፤ ለእናተም መስሚያና ማያዎች፤ ልቦችንም ያደረገላችሁ ነው:: ጥቂትንም አታመሰግኑምን በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 24, '24. እርሱ ያ በምድር ላይ የበተናችሁ ነው:: ወደ እርሱም ትሰበሰባላችሁ በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 25, '25. «እውነተኞችም እንደሆናችሁ ይህ ቀጠሮ መቼ ነው ተፈፃሚ የሚሆነው?» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 26, '26. እውቀቱ ከአላህ ዘንድ ብቻ ነው:: እኔ ግልጽ አስፈራሪ እንጂ ሌላ አይደለሁም በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 27, '27. (ቅጣቱ) ቅርብ ሆኖ ባዩትም ጊዜ የእነዚያ የካዱት ሰዎች ፊቶች ይከፋሉ:: ይህ ያ በእርሱ ትከራከሩበት የነበራችሁት ነው ይባላሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 28, '28. (መልዕክተኛችን ሙሐመድ ሆይ!) አያችሁን? እስኪ ንገሩኝ? አላህ ቢገድለኝ ከእኔ ጋር ያሉትንም (እንደዚሁ) ወይም በማቆየት ቢያዝንልን ከሓዲያንን ከአሳማሚ ቅጣት የሚያድን ማን ነው? በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 29, '29. (መልዕክተኛችን ሙሐመድ ሆይ!) እርሱ ያ (እመኑበት የምላችሁ) አር-ረህማን ነው:: እኛ በእርሱ አመንን:: በእርሱም ላይ ተጠጋን:: ወደ ፊትም በግልጽ መሳሳት ውስጥ የሆነው እርሱ ማን እንደሆነ በእርግጥ ታውቃላችሁ በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (67, 30, '30. (መልዕክተኛችን ሙሐመድ ሆይ!) አያችሁ (እስኪንገሩኝ?) ውሃችሁ ሰራጊ ቢሆን (ወደ መሬት ቢሰርግ) ፈሳሽን (ምንጭን) ውሃ የሚያመጣላችሁ ማን ነው? በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 1, '1. ኑን፤ በብዕር እና በዚያም በሱ በሚጽፉት ሁሉ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ በጌታህ ጸጋ ምክኒያት ዕብድ አይደለህም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 3, '3. ላንተም ከጌታህ የማይቋረጥ ምንዳ (የልፋት ዋጋ) በእርግጥ አለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 4, '4. አንተም በታላቅ ጸባይ ላይ ነህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 5, '5. ወደ ፊት አንተም ታያለህ፤ እነርሱም ያያሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 6, '6. ዕብደት በማንኛችሁ እንዳለ (እብዱ ማን እንደሆነ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 7, '7. ጌታህ ከመንገዱ የተሳሳተውን ሰው አዋቂ ነው። ወደ ቀናው መንገድ ተመሪዎችንም አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 8, '8. ስለዚህ ለአስተባባዩች (ሁሉ) አትታዘዝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 9, '9. (አስተባባዩች) ብትመሳሰላቸውና እነርሱም ቢመሳሰሉህ ተመኙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 10, '10. መሓለኛን ወራዳን ሁሉ አትታዘዝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 11, '11. ሰውን አነዋሪን፤ ነገር አሳባቂን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 12, '12.ለበጎ ነገር በጣም ከልካይን፤ ወሰን አላፊን፤ ኃጢአተኛንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 13, '13. ልበ ደረቅን ከዚህ ሁሉ በተጨማሪ የዝሙት ልጅ ዲቃላን (አትታዘዝ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 14, '14. የገንዘብና የልጆች ባለቤት በመሆኑ (ያስተባብላል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 15, '15. በእርሱ ላይ እንቀፆቻችን በሚነበቡ ጊዜ «የመጀመሪያዎቹ ሰዎች ተረቶች ናቸው» ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 16, '16. በአፍንጫው ላይ በእርግጥ (የሚነወርበት) ምልክትን እናደርግበታለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 17, '17. እኛ እነዚያን የአትክልቲቱን ባለቤቶች ማልደው ፍሬዋን ሊለቅሟት (አላህ ቢሻ ሳይሉ) በማሉ ጊዜ እንደሞከርን ሁሉ የመካ ሰዎችንም ሞከርናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 18, '18. (በመሓላቸው) አያስቀሩምም፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 19, '19.እነርሱ የተኙ ሆነዉም ሳሉ ከጌታህ የሆነ ዟሪ በእርሷ ላይ ዞረባት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 20, '20. እንደ ሌሊት ጨለማ የከሰለች ሆና አነጋች (አደረች)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 21, '21.ያነጉም ሆነው ተጠራሩ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 22, '22. "ቆራጮች እንደ ሆናችሁ ወደ እርሻችሁ ለመሄድ ማልዱ በማለት" (ተጠራሩ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 23, '23. እነርሱ የሚያሾካሾኩ ሆነው ሄዱም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 24, '24. ዛሬ በእናንተ ላይ አንድም ድሃ እንዳይገባት በማለትና', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 25, '25. ድሆችን በመከልከልም ላይ በሀሳባቸው ቻዮች ሆነው ማለዱ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 26, '26. ከዚያ ተቃጥላ ባዩዋት ጊዜ (እንዲህ) አሉ: «እኛ በእርግጥ ተሳሳቾች ነን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 27, '27. «ይልቁንም እኛ ከአላህ የተከለከልን እደለ ቢሶች ነን» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 28, '28. (ከመካከላቸው) ትክክለኛቸው (አስተዋያቸው)፡- «እናንተ አላህን ለምን አታጠሩም (አታወሱም) አላልኳችሁም ነበርን?» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 29, '29. «(ሁላቸዉም) ጌታችን ጥራት ይገባው፤ እኛ በዳዩች ነበርን» አሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 30, '30. እርስ በራሳቸው የሚወቃቀሱም ሆነው ከፊሎቻቸው በከፊሉ ላይ መጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 31, '31. «ዋ፤ጥፋታችን፤ እኛ ድንበር አላፊዎች ነበርን» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 32, '32. «ጌታችን ከእርሷ የተሻለን (አትክልት) ሊለውጠን ይከጀላል:: እኛ ወደ ጌታችን ከጃዩች ነን» አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 33, '33. (የአላህ) ቅጣቱ ልክ እንደዚሁ ነው:: የመጨረሻይቱም ዓለም ቅጣት ከዚህ የበለጠ ከባድ ነው:: የሚያውቁ ቢሆኑ ኖሮ (ከዚህ ቅጣት በተጠነቀቁ ነበር)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 34, '34. ለጥንቁቆች በጌታቸው ዘንድ መጠቀሚያ ገነቶች አሏቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 35, '35. ሙስሊሞችን እንደ ከሓዲያን እናደርጋለን? (አናደርግም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 36, '36. ለእናንተ ምን (አስረጂ) አላችሁ? እንዴት ትፈርዳላችሁ( ምን ነካችሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 37, '37. በእውነቱ ለእናንተ በእርሱ የምታጠኑበት መጽሐፍ አላችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 38, '38. በውስጡ ለእናንተ የምትመርጡት አላችሁን? (የሚል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 39, '39. ወይስ «ለእናንተ የምትፈርዱት አላችሁ» በማለት (ቃል ኪዳን የገባንላችሁ) እስከ ትንሳኤ ቀን ደራሽ የሆኑ መሐላዎች ለእናንተ በእኛ ላይ አሏችሁን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 40, '40. በዚህ ማንኛቸው ተያያዥ እንደ ኾነ ጠይቃቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 41, '41. ወይስ ለእነርሱ (በፍርዳቸው ተስማሚ) ተጋሪዎች አሏቸውን? እውነተኞችም እንደሆኑ ተጋሪዎቻቸውን ያምጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 42, '42. (መልዕክተኛችን ሙሐመድ ሆይ!) ያን ባት የሚገለጥበትን፤ (ከሓዲያን) ወደ መስገድ የሚጠሩበትና የማይችሉበትን ቀን (አስታውስ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 43, '43. ዓይኖቻቸው የፈሩ፤ ውርደት የምትሸፍናቸው ሲሆኑ (ወደ ስግደት የሚጠሩበትን):: እነርሱ (በምድረ ዓለም) ደህና ሆነው ሳሉ ወደ ስግድት በእርግጥ ይጠሩ ነበሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 44, '44. (መልዕክተኛችን ሙሐመድ ሆይ!) በመሆኑም እኔን በዚህ ንግግር ከሚያስተባብሉት ሰዎች ጋር ተወኝ፤ (ለእነርሱ እኔ እበቃሃለሁ):: ከማያውቁት ስፍራ አዘናግተን እንይዛቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 45, '45. እነርሱንም አዘገያቸዋለሁ:: (ዘዴዬ) ብቀላየ ብርቱ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 46, '46. (መልዕክተኛችን ሙሐመድ ሆይ!) ወይንስ በእውነቱ (በማስተማርህ) ዋጋን እንዲከፍሉህ ትጠይቃቸዋለህን? ስለዚህ እነርሱ ከዕዳ የተከበዱ ናቸውን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 47, '47. ወይስ ከእነርሱ ዘንድ የሩቁ ምስጢር እውቀት አለን? ስለዚህ እነርሱ ይጽፋሉን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 48, '48. (መልዕክተኛችን ሙሐመድ ሆይ)፤ ለጌታህ (ዉሳኔ) ፍርድ ታገስ:: (በመበሳጨትና ባለ መታገስ) እንደ ዓሳው ባለቤት እንደ (ነብዩ ዩኑስ) አትሁን:: እርሱ በጭንቀት የተሞላ ሆኖ (ጌታውን) በተጣራ ጊዜ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 49, '49. ከጌታው የሆነ ጸጋ ባላገኘው ኖሮ በምድረ በዳ ተወቃሽ ሆኖ በተጣለ ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 50, '50. ጌታዉም (በነብይነት) መረጠው:: ከደጋጎችም አደረገው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 51, '51. (መልዕክተኛችን ሙሐመድ ሆይ!) እነሆ እነዚያ በአላህ የካዱት ሰዎች ቁርኣኑን በሰሙ ጊዜ በዓይኖቻቸው (ሊያጠፉህ) ይቃረባሉ፤ «እርሱም በእርግጥ እብድ ነዉም» ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (68, 52, '52.እርሱ ግን ለዓለማት መገሰጫ (ገሳጭ) እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 1, '1. እውነትን አረጋጋጪቱ (ትንሳኤ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 2, '2. አረጋጋጪቱ (እርሷ) ምንድን ናት!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) አረጋግጪቱም ምን እንደሆነች ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 4, '4. የሰሙድና የዓድ ህዝቦች በቆርቋሪይቱ (ትንሳኤ) ቀን አስተባበሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 5, '5. የሰሙድ ህዝቦችማ ወሰን በሌላት ነፋስ ጩኸት ተጠፉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 6, '6. የዓድ ህዝቦችማ በኃይል በምትንሻሻ ብርቱ ነፋስ ተጠፉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 7, '7. ተከታታይ በሆነ ሰባት ሌሊቶችና ስምንት ቀናቶች ውስጥ በእነርሱ ላይ ለቀቃት:: ህዝቦችንም፤ በውስጧ የተጣሉ ሆነው ልክ ክፍት እደሆኑ የበሰበሱ የዘንባባ ግንዶች ታያቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 8, '8. ከእነርሱ መካከል ቀሪን ታያለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 9, '9. ፈርዖን፤ ከበፊቱ የነበሩትን ሰዎችም፤ ተገልባጮችም (የሉጥ ሰዎች ከተሞች) ኃጢአት ፈጸሙ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 10, '10. የጌታቸውንም መልዕክተኛ ትዕዛዝ ጣሱ፤ የበረታችንም ቅጣት ቀጣቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 11, '11. እኛ ውሃው ባየለ ጊዜ በተንሳፋፊይቱ ታንኳ ውስጥ ጫንናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 12, '12. ይህንም ያደረግነው ለእናንተ መገሰጫ ልናደርጋትና አጥኚ የሆነችም ጆሮ ታጠናት ዘንድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 13, '13. በቀንዱ አንዲት መነፋት በተነፋች ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 14, '14. ምድርና ጋራዎች (ከየስፍራቸው) በተነሱና አንዲትን መሰባበር በተሰባበሩ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 15, '15. በዚያ ቀን (ትንሳኤ) ትከሰታለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 16, '16. ሰማይም ትቀደዳለች:: በመሆኑም እርሷ በዚያ ቀን ደካማ ናት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 17, '17. መላዕክትም በየጫፎቿ ላይ ይሆናሉ:: የጌታህንም ዓርሽ በዚያ ቀን ስምንት መላዕክት ከበላያቸው ይሸከማሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 18, '18. በዚያ ቀን ከናንተ ተደባቂ (ነገሮች) የማይደበቁ ሲሆኑ ትቀረባላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 19, '19. ያ መጽሀፉን በቀኝ እጁ የተሰጠ ሰውማ (ለጓደኞቹ እንዲህ) ይላል: «እንኩ መጽሐፌን አንብቡ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 20, '20. «እኔ ምርመራየን የምገናኝ መሆኔን አረጋገጥኩ።» (ይላል)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 21, '21. እርሱም በተወደደች ኑሮ ውስጥ ይሆናል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 22, '22. በከፍተኛይቱ ገነት ውስጥ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 23, '23. ፍሬዎቿ ቅርቦች የሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 24, '24. በአለፉት ቀናት ውስጥ (በምድረ ዓለም) ባስቀደማችሁት ምክንያት ብሉ፤ ጠጡም ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 25, '25. ያ መጽሐፉን በግራው የተሰጠ ሰው ደግሞ (እንዲህ) ይላል: «ዋ ጥፋቴ ምነው መጽሐፌን ባልተሰጠሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 26, '26. «ምርመራዬም ምን እንደሆነ ባላወቅሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 27, '27. «ሞት ምነው የህይወቴ የመጨረሻ ፍፃሜ በሆነች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 28, '28. «ገንዘቤ ከእኔ ምንንም አልጠቀመኝም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 29, '29. «ስልጣኔ ከእኔ ላይ ጠፋ» ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 30, '30. ያዙት ከዚያ እጁን ከአንገቱ ጋር እሰሩት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 31, '31. ከዚያ በእሳት ውስጥ አስገቡት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 32, '32. ከዚም እርዝመቷ ሰባ ክንድ በሆነች ሰንሰለት ውስጥ አስገቡት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 33, '33. እርሱ ታላቅ በሆነው አላህ አያምንም ነበርና፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 34, '34. ድሆችንም በማብላት ላይ አያነሳሳም ነበርና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 35, '35. ለእርሱ ዛሬ እዚህ ቦታ ዘመድ ማንም የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 36, '36. ምግብም ከእሳት ሰዎች ቁስል እጣቢ እዥ በስተቀር የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 37, '37. ይህን ምግብ ኃጢአተኞች እንጂ ሌላ አይበላዉም ይባላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 38, '38. በምታዩት ነገር ሁሉ እምላለሁ ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 39, '39. በማታዩትም ነገር ሁሉ እምላለሁ ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 40, '40. ቁርኣን የተከበረው መልዕክተኛ ቃል ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 41, '41. እርሱም የባለ ቅኔ ገጣሚ ቃል አይደለም:: ጥቂትን ብቻ ታምናላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 42, '42. የጠንቋይም ቃል አይደለም:: ጥቂትን ብቻ ታስታውሳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 43, '43. ከዓለማት ጌታ የተወረደ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 44, '44. በእኛ ላይም ከፊልን ቃላት እንኳን (ያላልነው) በቀጠፈ ኖሮ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 45, '45. በኃይል በቀጣነው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 46, '46. ከዚያ ከእርሱ የልቡን ስር የተንጠላጠለበትን (ጅማት) በቆረጥን ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 47, '47. ከናንተም ውስጥ ከእርሱ ላይ ከልካዮች ምንም አይኖሩም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 48, '48. እርሱ (ቁርኣን) ለጥንቅቆቹ ብቻ መገሰጫ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 49, '49. እኛም ከናንተ ውስጥ አስተባባዩች መኖራቸውን በእርግጥ እናውቃለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 50, '50. እርሱ (ቁርኣንም) በከሓዲያን ላይ ጸጸት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 51, '51. እርሱም የተረጋገጠ እውነት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (69, 52, '52. እናም የታላቁን ጌታህን ስም (ታላቁን ጌታህን) አጥራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 1, '1. ወዳቂ (ተከሳች) ከሆነው ቅጣት ጠያቂ ጠየቀ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 2, '2. ከሓዲያን ላይ (ወዳቂ ከሆነው) ለእርሱ መላሽ የለዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 3, '3. የ (ሰማያት) መሰላሎች ባለቤት ከሆነው አላህ (መላሽ የለዉም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 4, '4. መላዕክትና መንፈሱም ልኩ ሀምሳ ሺህ ዓመት በሆነ ቀን ውስጥ ወደ እርሱ (ይወጣሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 5, '5. መልካምን ትዕግስት ታገስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 6, '6. እነርሱ ያንን ቀን ሩቅ አድርገው ያዩታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 7, '7. እኛም ቅርብ ሆኖ እናየዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 8, '8. ሰማይ እንደ ዘይት አተላ በምትሆንበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 9, '9. ጋራዎችም በተለያዩ ቀለማት እንደ ተነከረ ሱፍ (ንፋስ) እንደበተነውና እንደሚያበረው በሚሆኑበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 10, '10. ዘመድም ዘመድን በማይጠይቅበት ቀን መላሽ የለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 11, '11. (ዘመዶቻቸውን) ያዩዋቸዋል፤ አመጸኛው ከዚያ ቀን ስቃይ (ነፍሱን) በልጆቹ ቤዛ ሊያደርግ ይመኛል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 12, '12. በሚስቱም በወንድሙም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 13, '13. በዚያች በምታስጠጋው ጎሳውም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 14, '14. በምድርም ላይ ባለው ሁሉ (ሊበዥ) ከዚያ ሊያድነው (ይመኛል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 15, '15. ይተው፤እርሷ (እሳቲቱ) ነዲድ እሳት ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 16, '16. የራስን ቅል ቆዳ የምትሞሽልቅ ስትሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 17, '17. (ከእምነት) የዞረንና የሸሸን ሰው (ወደ እርሷ) ትጠራለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 18, '18. ገንዘብን የሰበሰበንና ዘካውን ሳይሰጥ የቆጠረንም (ትጠራለች)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 19, '19. ሰው ቅጠ ቢስ ሆኖ ተፈጠረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 20, '20. ክፉ ነገር ባገኘው ጊዜ ብስጭተኛ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 21, '21. መልካምም ነገር (ድሎት) ባገኘው ጊዜ ከልካይ ሆኖ ተፈጠረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 22, '22. ሰጋጆች ብቻ ሲቀሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 23, '23. እነዚያ እነርሱ በስግደታቸው ላይ ዘወታሪዎች የሆኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 24, '24. እነዚያም በገንዘቦቻቸው ላይ የታወቀ መብት ያለባቸው የሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 25, '25. ለለማኝ እና ከልመና ለሚቆጠብም መብት (ያለባቸው የሆኑ)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 26, '26. እነዚያም በፍርዱ ቀን እውነት የሚሉት የሚያረጋግጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 27, '27. እነዚያም እነርሱ ከጌታቸው ቅጣት ፈሪዎች የሆኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 28, '28. የጌታቸው ቅጣት የማያስተማምን ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 29, '29. እነዚያም እነርሱ ብልቶቻቸውን ጠባቂዎች የሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 30, '30. በሚስቶቻቸው ወይም እጆቻቸው በያዙዋቸው ባሮች ላይ ሲቀር:: እነርሱ በነዚህ የማይወቀሱ ናቸውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 31, '31. ከዚያ ወዲያ የፈለገ እነዚያ እነርሱ ድንበር አላፊዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 32, '32. እነዚያም እነርሱ አደራዎቻቸውና ቃል ኪዳናቸውን ጠባቂዎች የሆኑት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 33, '33. እነዚያም እነርሱ በምስክሮቻቸው ላይ ቀጥ ያሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 34, '34. እነዚያም እነርሱ በሶላቶቻቸው ላይ የሚጠባበቁት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 35, '35. እነዚያ (ከዚህ በላይ የተወሱት ሁሉ) በገነቶች ውስጥ የሚከበሩ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 36, '36. እነዚያ (በአላህ) የካዱት ወደ አንተ በኩል አንገቶቻቸውን መዘው የሚያተኩሩት ምን አላቸው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 37, '37. ከቀኝና ከግራ ክፍልፍል ቡድኖች ሲሆኑ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 38, '38. ከእነርሱ እያንዳንዱ ሰው የጸጋይቱን ገነት መግባትን ይከጅላልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 39, '39. ይከልከል፤ በፍጹም እኛ ከሚያውቁት ነገር (ከፍተወት ጠብታ) ፈጠርናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 40, '40. (እናም ጉዳዩ ከሓዲያን እንደሚሉት አይደለም):: በምስራቆችና በምዕራቦች ጌታ እምላለሁ፤ እኛ በእርግጥ ቻዮች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 41, '41. ከእነርሱ የተሻለን በመለወጥ ላይ እኛም ተሸናፊዎች አይደለንም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 42, '42. ያንንም የሚሰፈራሩበትን ቀናቸውን እስከሚያገኙ ድረስ ተዋቸው፤ በአሉባልታዎችም ዉስጥ ይዋኙ፤ ይጫወቱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 43, '43. ያ ቀን ወደ ጣዖት እንደሚሽቀዳደሙ ሆነው ከመቃብሮቻቸው ፈጥነው የሚወጡበትን ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (70, 44, '44. ዓይኖቻቸው ያፈሩ ሆነው፤ ውርደት ትሸፍናቸዋለች:: ይህ ቀን ያ ይስፈራሩበት የነበሩት ቀን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 1, '1. እኛ ኑህን ህዝቦችህን አሳማሚ ቅጣት ሳይመጣባቸው በፊት አስጠንቅቅ በማለት ወደ ወገኖቹ ላክነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 2, '2. እርሱም አለ፡- «ሀዝቦቼ ሆይ! እኔ ለእናንተ (የቸገራችሁን) ገላጭ የሆንኩ አስጠንቃቂ ነኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 3, '3. «አላህን ተገዙት፡-ፍሩት፤ እኔንም ታዘዙኝ በማለት አስጠንቃቂ ነኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 4, '4. «ለእናንተ ኃጢአታችሁን ይምራል እስከ ተወሰነ ጊዜም ያቆያችኋል:: አላህ የወሰነው ጊዜ በመጣ ወቅት ግን ለአፍታም አይቆይም:: በትክክል የምታውቁት ብትሆኑ ኖሮ በታዘዛችሁ ነበር።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 5, '5. ስለተቃወሙትም «ጌታየ ሆይ! እኔ በሌሊትም ሆነ በቀን ህዝቦቼን ጠራሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 6, '6. «ጥሪየም ይበልጥ መሸሽን እንጂ ሌላ አልጨመረላቸዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 7, '7. «እኔም ለእነርሱ ትምራቸው ዘንድ ወደ እምነት በጠራኋቸው ቁጥር ጣቶቻቸውን በጆሮዎቻቸው ውስጥ አደረጉ:: ልብሶቻቸውንም ተከናነቡ:: በመጥፎ ስራቸው ላይ ዘወተሩም:: ያለ ልክ መኩራትንም ኮሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 8, '8. «ከዚያ እኔ በግልጽ ጠራኋቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 9, '9. «ከዚያ እኔ ለእነርሱ ጥሪየን ይፋ አደረኩ:: ለእነርሱ መመስጠርን መሰጠርኩም» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 10, '10. «እንዲህም አልኩ: ጌታችሁን ምህረትን ለምኑት:: እርሱም በጣም መሀሪ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 11, '11. «በእናንተ ላይ ዝናምን ተከታታይ አድርጎ ይልካል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 12, '12. «ገንዘቦችና ልጆችንም ይለግሳችኋል:: ለእናንተ አትክልቶችን ያደርግላችኋል:: ለእናተም ወንዞችን ያደርግላችኋል አልኳቸው።»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 13, '13. ለአላህ ተገቢውን ልቅና የማትሰጡበት ምክንያት ለእናንተ ምን አላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 14, '14. በልዩ ልዩ (በተለያዩ) እርከኖች (ሁኔታዎች) በእርግጥ የፈጠራችሁ ሲሆን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 15, '15. አላህ ሰባት ሰማያትን አንዱ በአንዱ ላይ የተነባበረ ሲሆን እንዴት እንደፈጠረ አታዩምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 16, '16. በውስጣቸዉም ጨረቃን አብሪ አደረገ:: ጸሐይንም ብርሃን አደረገ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 17, '17. አላህም ከምድር ማብቀልን አበቀላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 18, '18. ከዚያም በውስጧ ይመልሳችኋል:: ማውጣትንም ያወጣችኋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 19, '19. አላህም ምድርን ለእናንተ ምንጣፍ አደረጋት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 20, '20. ከእርሷ ሰፋፊዎችን መንገዶች ትገቡ ዘንድ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 21, '21. ኑሕም አለ፡- «ጌታየ ሆይ! እነርሱም አመጹብኝ ገንዘቡና ልጁም ከጥፋት በስተቀር ያልጨመረለትን ሰው ተከተሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 22, '22. «ከባድንም ተንኮል ያሴሩትን ሰዎች ተከተሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 23, '23. መሪዎችም አሉ፡- <አማልክቶቻችሁን፤ ወድንም፤ ሰዋዕንም፤ የጉስንም፤ የዑቅንና ነስርንም አትተው።>', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 24, '24. «በእርግጥ (እነዚህ መሪዎች ወይም ጣኦቶች) ብዙዎችን ሰዎች አሳሳቱ:: ከሓዲያንንም ጥመትን እንጂ ሌላን አትጨምርላቸው» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 25, '25. በኃጢአቶቻቸው ምክንያት ተሰመጡ:: እሳትንም እንዲገቡ ተደረጉ:: ለእነርሱም ከአላህ ሌላ የሆኑ ረዳቶችን አላገኙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 26, '26. ኑህም አለ፡- «ጌታየ ሆይ! ከከሓዲያን በምድር ላይ (በዓለም ላይ) የሚኖርን አንድንም አትተው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 27, '27. «አንተ ብትተዋቸው ባሮችህን ያሳስታሉና:: ኃጢአተኛ ከሓዲንም እንጂ ሌላን አይወልዱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (71, 28, '28. «ጌታየ ሆይ! ለእኔም ለወላጆቼም ትክክለኛ አማኝ ሆኖ በቤቴ ለገባ ሁሉ ለአማኞችና ለምዕመናትም ምህረት አድርግ:: ከሓዲያንንም ከጥፋት በስተቀር አትጨምርላቸው።» አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) ከአጋንንት የሆኑ ቡድኖች ቁርኣንን አዳመጠው እንዲህ ማለታቸው ተወረደልኝ በል: «እኛ አስደናቂ የሆነን ቁርአን ሰማን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 2, '2. «ወደ ቀጥታ መንገድ የሚመራን (ቁርኣን ሰማን) በእርሱም አመንን:: በጌታችን አንድንም አናጋራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 3, '3. «እነሆ የጌታችን ክብር ላቀ:: ሚስትንም ልጅንም አልያዘም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 4, '4. «እነሆ ቂላችን በአላህ ላይ ወሰን ያለፈን ውሸት ይናገር ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 5, '5. «እኛም ሰዎችና ጋኔኖች በአላህ ላይ ውሸትን ቃል አይናገሩም ማለትን ጠረጠርን» አሉ በማለት ወደእኔ ተወረደ በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 6, '6. እነሆ ከሰዎች የሆኑ ወንዶች ከአጋንንት በሆኑ ወንዶች ይጠበቁ ነበር። ኩራትንም (ጥመትን) ጨመሯቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 7, '7. አላህ አንድንም አይቀሰቅስም ማለትን እንደጠረጠራችሁ እነርሱም ጠረጠሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 8, '8. እኛም ሰማይን ለመድረስ ፈለግን ብርቱ ጠባቂዎችንና ችቦዎችንም ተሞልታ አገኘናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 9, '9. እኛም ከእርሷ ወሬን ለማዳመጥ በመቀመጫዎች እንቀመጥ ነበር:: አሁን (ግን) የሚያዳምጥ (ሁሉ) ተጠባባቂ የእሳት ችቦ ያገኘዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 10, '10. እኛም በምድር ውስጥ ባሉት ክፉ ተሽቷል? ወይስ በእነርሱ (በኩል) ጌታቸው ደግን ነገር ሽቷል? ማለትን አናውቅም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 11, '11. ከእኛም ውስጥ ደጋጎች አሉ:: ከእኛም ውስጥ ከዚህ ሌላ የሆኑ አሉ:: የተለያዩ መንገዶች ባለቤቶች ነበርን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 12, '12. እኛም አላህን በምድር ውስጥ ፈጽሞ የማናቅተው ሸሽተንም ፈጽሞ የማናመልጠው መሆናችንን አረጋገጥን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 13, '13. እኛም መሪውን በሰማን ጊዜ በእርሱ አመንን:: ያ! በጌታው የሚያምን ሰው ሁሉ መጎደልንም ሆነ መጨመርን አይፈራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 14, '14. ከእኛም ውስጥ ሙስሊሞች አሉ:: ከእኛም ውስጥ በዳዩች አሉ:: እነዚያ የሰለሙ ሰዎች ቅንን መንገድ መረጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 15, '15. እነዚያ በዳዩችማ ለገሀነም ማገዶ ሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 16, '16. (ሰዎች ሁሉ በአላህ) በመንገድ ላይ ቀጥ ባሉ ኖሮ ብዙ ዝናብን ባጠጣናቸው ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 17, '17. በእርሱ ልንፈትናቸው (ባጠጣናቸው ነበር)። ያ ጌታውን ከማስታወስ የሚያፈገፍግ ሰው አስቸጋሪ ቅጣት ውስጥ ያስገባዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 18, '18. መስጊዶች ሁሉ የአላህ ብቻ ናቸው:: እናም በውስጣቸው ከአላህ ጋር አንድንም አትገዙ ማለትን ተወረደልኝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 19, '19. እነሆ የአላህ ባሪያ (ሙሐመድ) አላህን የሚጠራው ሆኖ በተነሳ ጊዜ ጋኒኖቹ በእርሱ ላይ ድርብርቦች ሊሆኑ ቀረቡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) «እኔ የማመልከው ጌታየን ብቻ ነው:: በእርሱ አንድንም አላጋራም» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 21, '21. «እኔ ለእናንተ ጉዳትንም ሆነ ማቅናትን አልችልም» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 22, '22. «እኔን ከአላህ ቅጣት አንድም (አካል) አያድነኝም:: ከእርሱ ሌላ መጠጊያም አላገኝም» በል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 23, '23. ከአላህ የሆኑ መልዕክቶችን ከማድረስ በስተቀር አልችልም:: አላህንና መልዕክተኛውን የሚያምጽ ሁሉ ለእርሱ የገሀነም እሳት አለው:: በውስጧም ዘላለም ዘውታሪዎች ሲሆኑ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 24, '24. የሚስፈራሩበትንም ባዩ ጊዜ ረዳተ ደካማ ቁጥሩም አነስተኛ የሆነው ማን እንደሆነ በእርግጥ ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 25, '25. «ያ! የምትስፈራሩበት ነገር ቅርብ ወይም ጌታየ ለእርሱ የተወሰነ ጊዜን የሚያደርግለት እሩቅ መሆኑን አላውቅም።» በላቸው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 26, '26. እርሱም እሩቁን ሚስጢር አዋቂ ነው::በምስጢሩም ላይ አንድንም አያሳውቅም፡፡»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 27, '27. (በሚስጢሩም ላይ) ከመልዕክተኛው ለወደደው ቢሆን እንጂ (ለሌላ አንድንም አያሳውቅም):: አይገልጽም:: ለእርሱም ከበስተፊቱም ከበስተኋላዉም ጠባቂዎቸን ያደርግለታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (72, 28, '28. ከእነርሱ ዘንድ ባለው ነገር እውቀት የከበበና ነገሩንም ሁሉ በቁጥር ያጠቃለለ ሲሆን የጌታቸውን መልዕክቶች ያደረሱ መሆናቸውን ያውቅ (ዘንድ ጠባቂ ያደርጋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 1, '1. አንተ ተከናናቢው ሆይ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 2, '2. ሌሊቱን (ሁሉ) ጥቂት ሲቀር ቁም (ስገድ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 3, '3. ግማሹን (ቁም) ወይም ከእርሱ ጥቂትን ቀንስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 4, '4. ወይም በእርሱ ላይ ጨምር:: ቁርኣንንም በዝግታ አንብብ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 5, '5. እኛ ባንተ ላይ ከባድ ቃልን እናወርዳለንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 6, '6. ሌሊት መነሳት (ህዋሳትንና ልብን) ለማስማማት በጣም ብርቱ ነው:: ለማንበብም ትክክለኛ ሰዓት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 7, '7. ላንተ በቀን ውስጥ ረዥም የመዘዋወርያ ሰዓት አለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 8, '8. የጌታህን ስም አውሳ:: ወደ እርሱም (አምልኮ) መቋረጥን ተቋረጥ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 9, '9. (እርሱም) የምስራቅና የምዕራብ ጌታ ነው:: ከእርሱ ሌላ ትክክለኛ አምላክ የለም:: መጠጊያ አድርገህም ያዘው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 10, '10. (ከሓዲያንም) በሚሉት ላይ ታገስ:: መልካምንም መተው ተዋቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 11, '11. የድሎት ባለቤቶችም ከሆኑት አስተባባዮች ጋር ተወኝ:: ጥቂትንም ጊዜ አቆያቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 12, '12. ከእኛ ዘንድ ከባድ ማሰሪያዎችና እሳት አሉንና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 13, '13. (ጉሮሮን) የሚያንቅ ምግብና አሳማሚ ቅጣትም አለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 14, '14. በዚያ ምድርና ጋራዎች በሚርገፈገፉበት፤ ጋራዎችም ፈሳሽ የአሸዋ ክምር በሚሆኑበት ቀን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 15, '15. እኛ ወደ ፊርዖን መልዕክተኛን እንደላክን ሁሉ በእናንተ ላይ መስካሪ መልዕክተኛንም ወደ እናንተ ላክን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 16, '16. ፊርዓውንም መልዕክተኛውን አመጸ:: ብርቱ መያዝንም ያዝነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 17, '17. (በአላህ) ከካዳችሁ ያን ልጆችን ሸበቶዎች የሚያደርገውን ቀን ቅጣት እንዴት ትጠነቀቃላችሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 18, '18. ሰማዩ በቀኑ ተሰንጣቂ ነው:: ቀጠሮዉም ተፈፃሚ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 19, '19. ይህች መገሰጫ ናት። መዳንንም የሻ (የፈለገ) ሰው ወደ ጌታው (የሚያደርሰዉን) መንገድ ይይዛል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (73, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) አንተ ከሌሊቱ ሁለት እጅ ያነሰን፤ ግማሹንም ሲሶውንም የምትቆም መሆንህን ጌታህ ያውቃል:: (ሙስሊሞች) ከእነዚያም አብረውህ ካሉ ከፊሎች የሚቆሙ መሆናቸውንም ያውቃል:: አላህ ሌሊትና ቀንን ይለካል:: ሌሊቱን በሙሉ የማትቆሙት መሆናችሁን አወቀ:: እናም በእናንተ ላይ ህጉን ወደ ማቃለል ተመለሰላችሁ:: ስለዚህ ከቁርኣን (በስግደት) የተቻላችሁን ያህል አንብቡ:: ከናንተ ውስጥ ሌሎችም በሽተኞች ከአላህ ችሮታ ለመፈለግ በምድር ላይ የሚጓዙ ሌሎችም፤ በአላህ መንገድ ሃይማኖት ላይ የሚጋደሉ እንደሚኖሩ አወቀ:: አቃለለላቸዉም ከቁርኣን የቻላችሁትን አንብቡ:: ሶላትንም ስገዱ:: ዘካንም ስጡ:: ለአላህ መልካም ብድርንም አበድሩ:: ከመልካም ስራም ለነፍሶቻችሁ የምታስቀድሙትን ሁሉ የተሻለና በምንዳም ታላቅ ሆኖ በአላህ ዘንድ ታገኙታላችሁ:: አላህን ምህረት ለምኑት:: አላህ መሀሪና አዛኝ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 1, '1. አንተ (ልብስ) ደራቢው ሆይ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 2, '2. ተነሳና (ህዝቦችህን) አስጠንቅቅ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 3, '3. ጌታህንም አክብር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 4, '4. ልብስህንም አጥራ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 5, '5. ጣዖትንም ራቅ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 6, '6. ማብዛትንም የምትፈልግ ሆነህ አትለግስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 7, '7. (ብዙ ዒባዳን ከመስራት አትድከም):: ለጌታህም (ትዕዘዛዝ) ታገስ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 8, '8. በቀንዱም በተነፋ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 9, '9. ይህን ጊዜ ያ ቀን አስቸጋሪ ቀን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 10, '10. (በተለይ) በከሓዲያን ላይ ገር ያልሆነ ቀን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 11, '11. (መልዕክተኛችን ሙሐመድ ሆይ!) በብቸኝነት ከፈጠርኩት ጋር ተወኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 12, '12. ለእርሱም የተዘረጋን ገንዘብ (በዓይነቱ) አደረግኩለት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 13, '13. በየአደባባዩ ተገኝ የሆኑ ወንዶች ልጆችንም ሰጠሁት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 14, '14. ለእርሱም ኑሮውን መዘርጋትን ዘረጋሁለት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 15, '15. ከዚያ ልጨምርለት ይከጅላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 16, '16. ሰው ይከልከል! እርሱ ለአናቅጻችን በእርግጥ ተቃዋሚ ነበርና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 17, '17. በእርግጥ (ገሀነም ውስጥ) ችግርን አስገድደዋለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 18, '18. እርሱ (በቁርኣን ጉዳይ) አሰበ፤ ገመተም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 19, '19. እናም ተረገመ:: እንዴት ገመተ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 20, '20. ከዚያ ተረገመ። እንዴትስ ገመተ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 21, '21. ከዚያም እንደገና (በቁርኣን ጉዳይ) ተመለከተ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 22, '22. ከዚያ ፊቱን አጨፈገገ አኮማተረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 23, '23. ከዚያ (በአላህ ከማመን) ዞረ:: ኮራም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 24, '24. «ይህ ከሌላ (ሰው) የሚቀዳ ድግምት እንጂ ሌላ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 25, '25. «ይህ የሰው ቃል እንጂ ሌላ አይደለም» አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 26, '26. ሰቀር (በተባለ የገሀነም ዋሻ ውስጥ) በእርግጥ አስገባዋለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 27, '27. (መልዕክተኛችን ሙሐመድ ሆይ!) ሰቀር ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 28, '28. (ያገኘችውን ሁሉ) አታስቀርም:: አትተዉምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 29, '29. የሰዎችን ቆዳ በጣም አክሳይ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 30, '30. በእርሷም ላይ አስራ ዘጠኝ (ዘበኞች) አሉባት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 31, '31. የእሳትን ዘበኞች መላዕክት እንጂ ሌላ አላደረግንም:: ቁጥራቸውንም ለእነዚያ በአላህ ለካዱት ሰዎች መፈተኛ እንጂ ለሌላ አላደረግንም:: እነዚያ መጽሐፍን የተሰጡት ሰዎች እንዲያረጋግጡ፤ እነዚያም በትክክል ያመኑት እምነትን እንዲጨምሩ፤ እነዚያም መጽሐፍን የተሰጡትና ምዕመናኖቹ እንዳይጠራጠሩ፤ እነዚያም በልቦቻቸው ውስጥ በሽታ ያለባቸው አስመሳዮችና ከሓዲያን «አላህ በዚህ (ቁጥር) ምን ምሳሌ ሽቷል?» እንዲሉ እንጂ (አላደረግንም):: ልክ እንደዚሁ አላህ የሚፈልገውን ያጠማል:: የሚፈልገውንም ያቀናል:: (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህንም ሰራዊት ልክ ከእርሱ በስተቀር ማንም አያውቅም:: የሰቀር እሳት ለሰዎች መገሰጫ እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 32, '32. (ከክህደት) ይከልከሉ:: በጨረቃ (እምላለሁ)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 33, '33. በሌሊቱም በሄደ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 34, '34. በንጋቱም ባበራ ጊዜ እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 35, '35. (ሰቀር) ከታላላቆች አደጋዎች አንዱ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 36, '36. ለሰዎች አስፈራሪ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 37, '37. ከናንተ መካከል ወደ በጎ ነገር መቅደምን ወይም ወደ ኋላ መቅረትን ለፈለገ (ሰው) ሁሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 38, '38. ነፍስ ሁሉ በሰራችው ስራ ተያዥ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 39, '39. እነዚያ መዝገባቸውን በቀኝ እጃቸው የሚሰጡት ብቻ ሲቀሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 40, '40. (እነርሱማ) በገነቶች ውስጥ ሁነው እርስ በራሳቸው ይጠያየቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 41, '41. ከአመጸኞች ሁኔታ (ይጠያየቃሉ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 42, '42. (ከዚያ ለእነርሱ እንዲህ ይሏቸዋል።) «በሰቀር ውስጥ ምን አገባችሁ?»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 43, '43. «ከሰጋጆች አልነበርንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 44, '44. «ለድሆችም የምናበላም አልነበርንም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 45, '45. «ከዘባራቂዎችም ጋር እንዘባርቅ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 46, '46. «በፍርዱ ቀንም እናስተባብል ነበር፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 47, '47. «እርግጠኛው ነገር ሞት እስከመጣብን ድረስ።» ይላሉ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 48, '48. እናም በዚያ ቀን የአማላጆች (ሁሉ) ምልጃ አትጠቅማቸዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 49, '49. ከ(ቁርኣን) ከግሳጼም የሚያፈገፍጉበት ምን ምክኒያት አላቸው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 50, '50. እነርሱ ልክ ደንባሪዎች የሜዳ አህዩች ይመስላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 51, '51. ከአንበሳ የሸሹ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 52, '52. ይልቁንም ከእነርሱ መካከል ለእያንዳንዱ ሰው የተዘረጉ ጹሑፎችን በእጁ እንዲሰጥ ይፈልጋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 53, '53. ከዚህ መሰል ተግባራቸው ይከልከሉ:: ይልቁንም የመጨረሻይቱን ዓለም ቅጣት አይፈሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 54, '54. ይከልከሉ፤እርሱ(ቁርአን) መገሰጫ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 55, '55. ስለዚህ የፈለገ ሰው ቁርኣንን ይገሰጽበታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (74, 56, '56. ሆኖም (ሰዎች) አላህ ካልፈለገ በስተቀር አይገሰጹም:: አላህ የመፈራት ባለቤት ነው:: (ለፈሩትም) የምህረት ባለቤት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 1, '1. (ሁኔታው ከሓዲያን እንደሚሉት አይደለም):: በትንሳኤ ቀን እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 2, '2. (ሁኔታው ከሓዲያን እንደሚሉት አይደለም):: ራሷን ወቃሽ በሆነች ነፍስም እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 3, '3. (በእርግጥ ትቀሰቀሳላችሁ።) ሰው አጥንቶችን ለመሰብሰባችን ይጠራጠራልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 4, '4. እንዴታ ጣቶቹንም ፊት እንደነበሩት በማስተካከል ላይ ቻዮች ስንሆን (እንሰበስባቸዋለን)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 5, '5. ይልቁን ሰው በፊቱ ባለ ነገር በትንሳኤ ቀን ሊያስተባብል ይፈልጋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 6, '6. «የትንሳኤው ቀን መቼ ነው?» ሲል ይጠይቃል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 7, '7. ዓይንም በዋለለ ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 8, '8. ጨረቃም በጨለመ ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 9, '9. ጸሐይና ጨረቃም በተሰበሰቡ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 10, '10. ሰው በዚያን ቀን «መሸሻው የት ነው?» ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 11, '11. «ይከልከል፤ ምንም መጠጊያ የለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 12, '12. በዚያ ቀን መርጊያው ወደ ጌታህ ብቻ ነው።» ይባላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 13, '13. ሰው በዚያን ቀን ያስቀደመውም ያስቆየውም ሁሉ ይነገረዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 14, '14. በእርግጥ ሰው በነፍሱ ላይ አስረጅ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 15, '15. ምክንያቶቹን ሁሉ ቢያመጣ እንኳን (አይሰማም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 16, '16. በቁርኣን ንባብ ልትቸኩል ብለህ ምላስህን አታላውስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 17, '17. በልብህ ውስጥ መሰብሰቡና ማስነበቡ በኛ ላይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 18, '18. ባነበብነው ጊዜ (ካለቀ በኋላ) ንባቡን ተከተል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 19, '19. ከዚያም (ላንተ) ማብራራቱ በእኛ ላይ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 20, '20. (መልዕክተኛችን ሙሐመድ ሆይ!) ከመጣደፍ ተከልከል፤ ይልቁንም (ሰዎች ስትባሉ) ፈጣኒቱን ዓለም ትወዳላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 21, '21. የመጨረሻይቱን ዓለም (ግን) ትተዋላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 22, '22. (የተወሰኑ) ፊቶች በዚያ ቀን አብሪዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 23, '23. ወደ ጌታቸው ተመልካቾችም ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 24, '24. (ሌሎች) ፊቶች ደግሞ በዚያ ቀን አጨፍጋጊዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 25, '25. በእነርሱም ላይ አደጋ እንደሚሰራባቸው ያረጋገጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 26, '26. (ሙስሊሞች አስተውሉ።) (ነፍስ) ወደ ጉሮሮ በደረሰች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 27, '27. «አሻሪው ማነው?» በተባለም ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 28, '28. (የሰፈረበት ነገር ከዚህ ዓለም) መለየት መሆኑን ባረጋገጠ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 29, '29. ባትም ከባት በተጣበቀች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 30, '30. በዚያ ቀን መነዳት ወደ ጌታህ (ፍርድ) ብቻ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 31, '31. እናም (ከሀዲው) አላመነምም፤ አልሰገደምም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 32, '32. ግን በአላህ አስተባበለ፤ ከእምነት ዞረም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 33, '33. ከዚያም እየተንጎማለለ ወደ ቤተሰቡ ሄደ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 34, '34. (የምትጠላውን ነገር) ላንተው ይሁን፤ ላንተ ተገቢህም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 35, '35. ከዚያም ጥፋት ይጠጋህ ላንተ የተገባህም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 36, '36. ሰው እንደፈለገ እንዲኖር ልቅ ሆኖ የሚተው ይመስለዋልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 37, '37. የሚፈስ ከሆነ የፍትወት ጠብታ አልነበረምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 38, '38. ከዚያ የረጋ ደም ሆነ:: ከዚያ አላህ ሰው አድርጎ ፈጠረው፤ አስተካከለዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 39, '39. ከእርሱም ሁለት ዓይነቶች ወንድና ሴትን አደረገ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (75, 40, '40. (ታዲያ) ይህ ሀያል (ጌታ) ሙታንን ሕያው በማድረግ ላይ ቻይ አይደለምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 1, '1. በሰው ላይ የሚታወስ ነገር (እንኳ) ሳይሆን ከዘመናት የተወሰነ ጊዜ አላለፈም ነበርን? (በእርግጥ አልፏል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 2, '2. እኛ ሰውን (በሕግጋት ግዳጅ) የምንሞክረው ስንሆን ከወንድና ከሴት ፈሳሽ ቅልቅሎች ከሆነች የፍትወት ጠብታ ፈጠርነው:: ሰሚና ተመልካችም አደረግነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 3, '3. እኛ አመስጋኝ ወይም ከሓዲ ሲሆን መንገዱን መራነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 4, '4. እኛ ለከሓዲያን ሰንሰሎቶችንና እንዛዝላዎችን፣ እሳትንም (አዘጋጅተናል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 5, '5. እነዚያ (ትክክለኛ) በጎ አድራጊዎች መበረዣዋ ካፉር ከሆነች ጠጅ ይጠጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 6, '6. ከእርሷ እነዚያ የአላህ ባሮች የሚጠጡላት ና ወደ ፈለጉበት ማንቧቧትን የሚያንቧቧት ከሆነች የጠጅ ምንጭ (ይጠጣሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 7, '7. (ዛሬ በዚህ ዓለም እያሉ) በስለታቸው ይሞላሉ:: መከራው ተሰራጪ የሆነንም ቀን ይፈራሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 8, '8. ምግብንም ከመውደዳቸው ጋር ለድሃ፤ ለየቲምና ለምርኮኛ ያበላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 9, '9. «የምናበላችሁ ለአላህ ውዴታ ብቻ ነው:: ከናንተ ክፍያንም ሆነ ማመስገንን አንፈልግም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 10, '10. እኛ ያንን (ፊትን) የሚያጨፈግግን ብርቱ ቀን ከጌታችን እንፈራለንና» (ይላሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 11, '11. አላህም የዚያን ቀን ክፋት ጠበቃቸው። (ፊታቸው) ማማርንና መደሰትንም ገጠማቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 12, '12. በመታገሳቸዉም (ምክንያት) ገነትንና የሀር ልብስን መነዳቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 13, '13. በውስጧ በባለ አጎበር አልጋዎች ላይ ተደጋፊዎች፤ በውስጧ የጸሀይን ሐሩርንም ሆነ ብርድንም የማያዩ ሲሆኑ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 14, '14. ዛፎቿም ለእነርሱ የቀረበች፤ ፍራፍሬዎችዋም ለለቃሚዎች መገራትን የተገራች ስትሆን ገነትን መነዳቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 15, '15. በእነርሱም ላይ ከብር በተሰሩ ዕቃዎች (ሳህኖች)፤ ብርጭቆዎች እና በኩባያዎችም ይዝዞርባቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 16, '16. መለካትን የለኳቸው በሆኑ የብር ብርጭቆዎች (ይዝዞርባቸዋል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 17, '17. በእርሷም መበረዣዋ ዝንጂብል የሆነች ወይን ጠጅ ይጥጠጣሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 18, '18. በውስጧ ያለችውን ሰልሰቢል ተብላ የምትጠራውን ምንጭ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 19, '19. በእነርሱም ላይ ባሉበት ሁኔታ የሚዘወትሩ ወጣት ልጆች ይዘዋወራሉ:: ባየሃቸው ጊዜ የተበተነ ሉል ናቸው ብለህ ታስባቸዋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 20, '20. እዚያንም በተመለከትክ ጊዜ ጸጋንና ታላቅ ንግስናን ታያለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 21, '21. አረንጓዴዎች የሆኑ ቀጭን ሀር ልብሶችና ወፍራም ሀርም በላያቸው ላይ አለ። ከብር የሆኑ አንባሮችንም ይሸለማሉ:: ጌታቸዉም (ከራሱ አልፎ) ሌላን አጥሪ የሆነን መጠጥ ያጠጣቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 22, '22. «ይህ ለእናንተ ዋጋ ሆነ:: ስራችሁም ምስጉን ሆነ» ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 23, '23. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ (ይህንን) ቁርኣን ባንተ ላይ ማውረድን አወረድነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 24, '24. ለጌታህ ፍርድም ታገስ:: ከእነርሱም መካከል ኃጢአተኛን ወይም ከሓዲን አትታዘዝ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 25, '25. የጌታህን ስም በጠዋትና ከቀትር በኋላ አውሳ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 26, '26 ከሌሊቱም ለእርሱ ብቻ ስገድ፤ በረዢም ሌሊትም አወድሰው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 27, '27. እነዚያ ይህችን ፈጣኒቱን ዓለም ይወዳሉ። ከባድና (አስቸጋሪ) ቀንም በስተፊታቸው ሆኖ ችላ ይላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 28, '28. እኛ ፈጠርናቸው:: የአካሎቻቸዉንም መለያያቸውን አጠነከርን:: በፈለግን ጊዜ መሰሎቻቸውን መለወጥን እንለውጣለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 29, '29. ይህ መገሰጫ ነው:: የፈለገ ሰውም ወደ ጌታው መንገድ ይይዛል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 30, '30. አላህም ካልሻ በስተቀር አትሹም፤ አላህ አዋቂና ጥበበኛ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (76, 31, '31. (አላህ) የሚፈልገውን ሰው በእዝነቱ ውስጥ ያስገባዋል:: በዳዩችንም (ዝቶባቸዋል) ለእነርሱ አሳማሚ ቅጣትን አዘጋጅቶላቸዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 1, '1. ተከታታይ ሆነው በተላኩት ፤ (እምላለሁ)፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 2, '2. በኃይል መንፈስን ነፋሾች በሆኑትም (ንፋሶች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 3, '3. መበተንን በታኝ በሆኑትም (ንፋሶች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 4, '4. መለየትን ለይዎች በሆኑትም (መላዕክት)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 5, '5. መገሰጫን (ወደ ነብያት ጣይዎች) አምጪዎች በሆኑትም (መላዕክት)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 6, '6. ማሳበቢያን ለማስወገድ ወይም ለማስጠንቀቅ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 7, '7. ያ! የምትስፈራሩበት (ትንሳኤ) በእርግጥ ኋኝ ነው ብየ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 8, '8. ከዋክብትም (ብርሃኗ) በታበሰች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 9, '9. ሰማይም በተከፈተች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 10, '10. ጋራዎችም በተንኮታኮቱ ጊዜ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 11, '11. መልዕክተኞቹም ወቅት በተደረገላቸው ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 12, '12. ለየትኛው ቀን ተቀጠሩ የሚባል ሲሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 13, '13. ለዚያ ለመለያው ቀን ተቀጠሩ በተባለ ጊዜ (በፍጡሮች መካከል በትክክል ይፈርዳል)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 14, '14. (መልዕክተኛችን ሙሐመድ ሆይ!) የመለያው ቀን ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 15, '15. ለአስተባባዮች (ሁሉ) በዚያን ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 16, '16. የፊተኞቹን (ህዝቦች) አላጠፋንምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 17, '17. ከዚያ ኋለኞቹን እናስከትላቸዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 18, '18. በአመጸኞች ሁሉ ላይ ልክ እንደዚሁ (ያለ) እንሰራለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 19, '19. ለአስተባባዩች (ሁሉ) በዚያን ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 20, '20. (ሰዎች ሆይ!) ከደካማ ውሃ አልፈጠርናችሁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 21, '21. በተጠበቀ መርጊያ ውስጥም (በእናቶች ማህጸን) ውስጥ አደረግነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 22, '22. እስከታወቀ ጊዜ ድረስ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 23, '23.መጠንነዉም ምን ያማርንም መጣኞች ነን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 24, '24. ለአስተባባዮች (ሁሉ) በዚያን ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 25, '25. (ሰዎች ሆይ!) ምድርን ሰብሳቢ አላደረግናትምን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 26, '26. ህያው ሆናችሁም ሙታን ሆናችሁም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 27, '27. በውስጧም ከፍተኛዎችን (ትላልቅ) ተራራዎች አደረግን፤ ጣፋጭ ውሃንም አጠጣናችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 28, '28. ለአስተባባዮች በዚያ ቀን ወዮላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 29, '29. «ወደዚያ በእርሱ ታስተባብሉ ወደ ነበራችሁት ቅጣት ሂዱ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 30, '30. ባለ ሶስት ቅርንጫፎች ወደ ሆነው ጥላ ሂዱ።» (ይባላሉም)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 31, '31. ጥላም ያልሆነ ከእሳቱም ላንቃ የማያድን ወደ ሆነው (ሂዱ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 32, '32. እርሷ እንደ ታላላቅ ህንፃ የሆኑን ቃንቄዎች (የእሳት ፍንጣሪዎች) ትወረውራለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 33, '33. (ቃንቄዉም) ልክ ዳለቻዎች ግመሎችን ይመስላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 34, '34. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 35, '35. ይህ የማይናገሩበት ቀን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 36, '36. ይቅርታም ይጠይቁ ዘንድ አይፈቀድላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 37, '37. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮውላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 38, '38. ይህ የመለያው ቀን ነው። እናንተንም የፊተኞችንም ሰበሰብናችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 39, '39. ለእናንተም (ለማምለጥ) ብልሃት እንዳላችሁ ተተናኮሉኝ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 40, '40. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 41, '41. ጥንቅቆች በጥላዎችና በምንጮች፤ውስጥ ናቸው፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 42, '42. በሚፈልጉትም የፍራፍሬ (አይነቶች) ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 43, '43. «ትሰሩትም በነበራችሁት ዋጋ የምትደሰቱ ሆናችሁ ብሉ፤ ጠጡም» ይባላሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 44, '44. እኛ መልካም ሰሪዎችን (ሁሉ) እንደዚሁ እንመነዳለን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 45, '45. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 46, '46. አስትባባዮች ሆይ! ብሉ ጥቂትንም ጊዜ ተጠቀሙ እናንተ አመጸኞች ናችሁና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 47, '47. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 48, '48. ለእነርሱ «ስገዱ» በተባሉም ጊዜ አይሰግዱም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 49, '49. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (77, 50, '50. ከእርሱም ሌላ በየትኛው ንግግር ያምናሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 1, '1. ከምን ነገር ይጠያየቃሉ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 2, '2. ከታላቁ ዜና (ቁርኣን) ይጠያየቃሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 3, '3. ስለዚያ እነርሱ በእርሱ ላይ ስለተለያዩበት (ስለተወዛገቡበት)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 4, '4. ጉዳዩ እነርሱ እንደሚሉት አይደለም:: (ትክክለኛውን) ወደ ፊት ያውቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 5, '5. ከዚያም ይከልከሉ፤ (ትክክለኛውን) ወደ ፊት ያውቃሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 6, '6. ምድርን ምንጣፍ አላደርግንምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 7, '7. ጋራዎችንም ችካሎች (አላደረግንምን)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 8, '8. ጥንዶች አድርገንም ፈጠርናችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 9, '9. እንቅልፋችሁንም እረፍት አደረግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 10, '10. ሌሊቱንም ልባስ አደረግን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 11, '11. ቀኑንም ለኑሮ መስሪያ (ለጉዳይ መከወኛ) አደረግን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 12, '12. ከበላያቸሁም ሰባት ብርቱዎችን (ሰማያት) ገነባን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 13, '13. አንጸባራቂ ብርሃንንም አደርግንላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 14, '14. ከአረገዙት ደመናዎችም የሚንቧቧ ውሃን አወረድን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 15, '15.በእርሱ እህልንና ቅጠላ ቅጠልን፤ እናወጣ ዘንድ(አወረድን)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 16, '16. የተቆላለፉ አትክልቶችንም ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 17, '17. (በህዝቦች መካከልም) የመለያው ቀን የተወሰነ ጊዜ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 18, '18. (ይሀዉም) በቀንዱ በሚነፋበትና በቡድን በቡድን ሆናችሁም በምትመጡበት ቀን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 19, '19. ሰማይም በምትከፈትና ባለ ብዙ ደጃፎችም በምትሆንበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 20, '20. ጋራዎችም በሚናዱበትና እንደ ሲሪብዶም በሚሆንበትም ቀን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 21, '21. ገሀነም (ለከሓዲያን) መጠባበቂያ ኬላ (ስፍራ) ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 22, '22. ለህግ ተላላፊዎች መመላለሻ ስትሆን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 23, '23. በውስጧ ብዙ ዘመናትን ነዋሪዎች ሲሆኑ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 24, '24. በውስጧ ቅዝቃዜንም መጠጠንም አይቀምሱም (አያገኙም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 25, '25. ሙቅ የፈላ ውሃንና እዥን እንጂ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 26, '26. ተመጣጣኝን ምንዳ ይመነዳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 27, '27. ምርመራ (እንዳለባቸው) ቅንጣት አይጠብቁም ነበርና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 28, '28. በአናቅጻችንም ማስተባበልን አስተባበሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 29, '29. ነገሩን ሁሉ የተፃፈ ሲሆን አጠቃለልነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 30, '30. «(የጃችሁን) ቅመሱም፤ ቅጣትን እንጂ ሌላን አንጨምርላችሁም» (ይባላሉም)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 31, '31. ለጥንቅቆቹ (አላህን ለሚፈሩ) ስኬት አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 32, '32. አትክልቶችና ወይኖችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 33, '33. በእድሜ እኩያዎች የሆኑ ጡተ ጉችማዎችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 34, '34. የተሞሉ ብርጭቆዎችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 35, '35. በውስጧ ትርፍ ቃልንም፤ ማስዋሸትንም አይሰሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 36, '36. ከጌታህ የሆነን ምንዳ፤ በቂ ስጦታን ተሰጡ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 37, '37. የሰማያትና የምድር በመካከላቸዉም ላለው ሁሉ ጌታ ከሆነውና በጣም አዛኝ ከሆነው ተመነዱ፤ ከእርሱ ጋር መነጋገርን አይችሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 38, '38. መልአኩ (ጅብሪል) እና ሌሎች መላዕክትም የተሰለፉ ሆነው በሚቆሙበት ቀን አረህማን ለእርሱ የፈቀደለትና ትክክለኛን ቃል ያለ ብቻ ቢሆን እንጂ መነጋገርን አይችሉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 39, '39. ያ! የእውነት ቀን ነው። የፈለገ ሰው ወደ ጌታው በመልካም ተግባር መመለስን ተግባሩ አድርጎ ይይዛል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (78, 40, '40. እኛ ቅርብ የሆነን ቅጣት አስጠነቀቅናችሁ። ሰዎች ሁሉ በሁለት እጆቻቸው ያስቀደሙትን በግልጽ የሚያይበትና ከሓዲያን ሁሉ «ዋ ምኞቴ! ምንነው አፈር በሆንኩ ባልተቀሰቀስኩኝ» የሚሉበት ቀን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 1, '1. (ነፍስን (ሩህን)) በኃይል መንጫቂዎች በሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 2, '2. በቀስታ መምዘዝን መዛዦች በሆኑትም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 3, '3. መዋኘትንም ዋኚዎች በሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 4, '4. መቅደምንም ቀዳሚዎች በሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 5, '5. ጉዳይንም አስተናባሪዎች በሆኑት መላዕክት እምላለሁ (በእርግጥ ትቀሰቀሳላችሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 6, '6. (ይህም የሚሆነው) ተርገፍጋፊይቱ (ምድር) በምትርገፈገፍበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 7, '7. ተከታይቱም በምትከተላት ቀን (ትቀሰቀሳላችሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 8, '8. በዚያ ቀን ልቦች ተሸባሪዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 9, '9. ዓይኖቻቸው ተዋራጆች (አቀርቃሪዎች) ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 10, '10. «እኛ ወደ መጀመሪያይቱ ሁኔታ ተመላሾች ነን እንዴ?» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 11, '11. የበሰበሱ አጥንቶች በሆንን ጊዜ እንደገና እንቀሰቀሳለን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 12, '12. «እንዲያማ ከሆነ ያች የኪሳራ መመለስ ናታ!» ይላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 13, '13. እርሷን (እውን የምታደርጋት) አንዲት ጩኸት ብቻ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 14, '14. ወዲያውኑ በንቃት ላይ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 15, '15. (መልዕክተኛችን ሙሐመድ ሆይ!) የሙሳ ወሬ መጣልህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 16, '16. ጌታው በተቀደሰው ጡዋ ሸለቆ በጠራው ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 17, '17. ወደ ፈርዖን ሂድ፤ ወሰን አልፏልና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 18, '18. (እንዲህም) በለው: «እራስህን ለማጥራት ታስባለህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 19, '19. ጌታህንም ትፈራ ዘንድ መንገዱን ልመራህ፤ (ታስባለህን?)»', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 20, '20. (ሙሳ ለፈርዖን) ታላቁንም ተዐምር አሳየው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 21, '21. አስተባበለም፤ አመጸም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 22, '22. ከዚያ ለመጥፋት የሚተጋ ሆኖ ዞረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 23, '23. (ህዝቡን) ሰበሰበም ተጣራም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 24, '24. እኔ «ታላቁ ጌታችሁ ነኝ» አለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 25, '25. አላህም በኋለኛይቱና በፊተኛይቱ ቃል ቅጣት ያዘው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 26, '26. በዚህ ውስጥ አላህን ለሚፈሩ በእርግጥ ማስጠንቀቂያ አለበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 27, '27. በአፈጣጠር እናንተ ይበልጥ የበረታችሁ ናችሁን? ወይስ ሰማይ? (አላህ) ገነባት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 28, '28. ከፍታዋን አጓነ አስተካከላትም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 29, '29. ሌሊቷንም ሸፈነ፤ ቀኗንም ግልጽ አደረገ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 30, '30. ምድርንም ከዚያ በኋላ ዘረጋት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 31, '31. ውሃዋንና ግጦሿን ከእርሷ አወጣ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 32, '32. ጋራዎችንም አደላደላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 33, '33. ለእናንተም ለእንስሶቻችሁም መጣቀሚያ ይሆን ዘንድ (ይሄን አደረገ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 34, '34. ታላቂቱም መዓት በመጣች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 35, '35. ሰው ሁሉ የሰራውን የሚያስታውስበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 36, '36. ገሀነምም ለሚያይ ሰው በተገለጠች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 37, '37. የካደ ሰውማ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 38, '38. ቅርቢቱንም ሕይወት የመረጠ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 39, '39. በእርግጥ መኖሪያው ጀሀነም ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 40, '40. በጌታው ፊት መቆምን የፈራና ነፍሱንም ከዝንባሌዋ የከለከለማ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 41, '41. በእርግጥ መኖሪያው ገነት ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 42, '42. ስለሰዓቲቱም መነሻዋ መቼ እንደሆነ ይጠይቁሃል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 43, '43. (ለመሆኑ አንተ ስለዚያች እለት) በመወሳቷ ምን ላይ አለህበትና?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 44, '44. የእርሷ ጉዳይ የሚመለሰው ወደ ጌታህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 45, '45. አንተ ያለብህ ለሚፈራት ሰው ሁሉ ስለ እርሷ (ከወዲሁ) ማስጠንቀቅ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (79, 46, '46. እነርሱ የሚያይዋት ቀን የአንዲትን ቀን ምሽት ወይም ረፋዷን እንጂ ያልቆዩ ይመስላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 1, '1. ፊቱን አጨፈገገ፤ ዞረም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 2, '2. ዓይነስውሩ ወደ እርሱ ስለመጣ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) ምን ያሳውቅሃል? ምን አልባትም (ይህ አይነስውር ሰው ካንተ በሚሰማው ምክር ከኃጢአቶቹ) ሊጥራራ ይከጀላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 4, '4. ወይም ሊገሰጽና ግሳጼይቱም ልትጠቅመው ይከጀላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 5, '5. ያ! ከአላህ የተብቃቃውን ሰውማ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 6, '6. አንተ ለእርሱ ትዘጋጃለህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 7, '7. ባይጥራራ (ባያምን)፤ ባንተ ላይ ምንም የሌለብህ ስትሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 8, '8. ያ! እየገሰገሰ የመጣህ ሰውማ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 9, '9. እርሱ አላህን የሚፈራ ሲሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 10, '10. አንተ ከእርሱ ትዘናጋለህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 11, '11. ተከልከል፤ (ቁርኣን) ማስገንዘቢያ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 12, '12. የፈለገ ሰው ሁሉ (ቁርኣኑን) ያስታውሰዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 13, '13. በተከበሩት ጹሑፎች ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 14, '14. ከፍ በተደረገች፤ ንጹህም በተደረገች (ጹሑፍ ውስጥ ነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 15, '15. በጸሐፊዎች መላዕክት እጆች (ንጹህ የተደረገ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 16, '16. የተከበሩና ታዛዦች በሆኑት ጸሐፊዎች (እጆች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 17, '17. ሰው ተረገመ። ምን ከሓዲ አደረገው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 18, '18. (ጌታው) ከምን ነገር ፈጠረው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 19, '19. (አያስብምን?) ከፍትወት ጠብታ ፈጠረው፤ መጠነዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 20, '20. ከዚያም (መውጫ) መንገዱን አገራው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 21, '21. ከዚያም ገደለው:: እንዲቀበርም አደረገው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 22, '22. ከዚያ ማንሳቱን በፈለገ ጊዜ ያስነሳዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 23, '23. በእውነት ያንን ጌታው ያዘዘውን ገና አልፈጸመም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 24, '24. ሰው ወደ ምግቡ ይመልከት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 25, '25. እኛ ውሃን ማንቧቧትን ያንቧቧን መሆናችንን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 26, '26. ከዚያ ምድርን በደካማ ቡቃያ መሰንጠቅን የሰነጠቅን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 27, '27. በውስጧም እህልን ያበቀልን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 28, '28. ወይንም እርጥብ ሳርንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 29, '29. የዘይት ወይራንም ዘንባባንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 30, '30. ጭፍቆች አትክልቶችንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 31, '31. ፍራፍሬንና፤ ገለባንም (ያበቀልን መሆናችንን ይመልከት)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 32, '32. ለእናንተም ለእንሰሶቻችሁም መጠቀሚያ ይሆን ዘንድ (ይህን ሰራን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 33, '33. አደንቋሪይቱ (መከራ) በመጣች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 34, '34. ሰው ከወንድሙ በሚሸሽበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 35, '35. ከእናቱም፤ ከአባቱም፤ (በሚሸሽበት ቀን)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 36, '36. ከሚስቱና ከልጁም፤ (በሚሸሽበት ቀን)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 37, '37. ከእነርሱ ለየሰው ሁሉ በዚያ ቀን ከሌላው የሚያብቃቃው ሁኔታ አለው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 38, '38. ፊቶች በዚያ ቀን አብሪዎች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 39, '39. ሳቂዎችና ተደሳቾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 40, '40. ፊቶች ደግሞ በዚያ ቀን በላያቸው ላይ ትብያ አለባቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 41, '41. ጥቁረት ትሸፍናቸዋለች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (80, 42, '42. እነዚያ እነርሱ በአላህ ከሓዲያን እና በትዕዛዙ ላይ አመጸኞቹ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 1, '1. ጸሐይ በተጠቀለለች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 2, '2. ከዋክብትም በረገፉ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 3, '3. ተራራዎች በተናዱ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 4, '4. የአስር ወር እርጉዝ ግመሎች ያለጠባቂ በተተው ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 5, '5. አራዊቶችም በተሰበሰቡ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 6, '6. ባህሮችም በተቀጣጠሉ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 7, '7. ነፍሶች በተቆራኙ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 8, '8. ከነሕይወቷ የተቀበረችው ሴት ልጅም በተጠየቀች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 9, '9. በምን ወንጀል እንደተገደለች፤ በተጠየቀች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 10, '10. ጹሑፎችም በተዘረጉ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 11, '11. ሰማይም በተገሸለጠች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 12, '12. ገሀነምም በተነደደች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 13, '13 ገነትም በተቀረበች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 14, '14. ነፍስ (ሁሉ ከስራ) ያቀረበችውን ታውቃለች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 15, '15. (ሁኔታው ከሓዲያን እንደሚሉት አይደለም):: ተመላሾች በሆኑት (ከዋክብት) እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 16, '16. አንዳንድ ጊዜ ሂያጆች በሌላ ጊዜ ገቢዎች በሆኑት', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 17, '17. በሌሊቱም (ጨለማውን) በጠነሰሰ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 18, '18. በንጋትም (በብርሃን) በተነፈሰ ጊዜ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 19, '19. እርሱ (ቁርኣን) የተከበረው መልዕክተኛ ጅብሪል ቃል ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 20, '20. የኃይል ባለቤት የሆነ፤ ከዙፋኑ ባለቤት ዘንድም ባለሟል የሆነ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 21, '21. በዚያ ስፍራ ትዕዛዙ ተሰሚ፤ ታማኝም የሆነው (መልዕክተኛ ቃል ነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 22, '22. ነብያችሁም በፍጹም እብድ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 23, '23. በግልጹ አድማስ ላይ ሆኖ (ጅብሪልን) በእርግጥ አይቶታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 24, '24. እርሱም በሩቁ ወሬ ላይ ሰሳች (ንፉግ) አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 25, '25. (ቁርኣን) የርጉም ሰይጣን ቃልም አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 26, '26. ታዲያ (ይህንን በተመለከተ) ወዴት ትሄዳላቸሁ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 27, '27. እርሱ የዓለማት መገሰጫ እንጂ ሌላ አይደለም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 28, '28. ከናንተ መካከል ቀጥተኛ መሆንን ለፈለገ (ሁሉ መገሰጫ) ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (81, 29, '29. (ሰዎች ሆይ!) የዓለማት ጌታ የሆነው አላህ ካልሻ በስተቀር እናንተ አንድም ነገር አትሹም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 1, '1. ሰማይ በተሰነጠቀች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 2, '2. ከዋክብትም ተበታትነው በወደቁ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 3, '3. ባህሮችም በተከፈቱና በተደባለቁ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 4, '4. መቃብሮችም በተገለባበጡና ሙታን በተነሱ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 5, '5. (ያኔ) ማንኛይቱም ነፍስ ያስቀደመችውንና ያዘገየችውን ታውቃለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 6, '6. አንተ ሰው ሆይ! በቸሩ ጌታህ ምን አታለለህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 7, '7. በዚያ በፈጠረህ፤ አካለ ሙሉም ባደረገህ፤ ባስተካከለህም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 8, '8. በማንኛውም (እርሱ) በፈለገው ቅርጽ በገጣጠመህ ጌታህ ምን አታለለህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 9, '9 (ሰዎች ሆይ!) ተከልከሉ፤ በእውነት በፍርዱ ቀን ታስተባብላላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 10, '10. በእናንተ ላይ ጠባቂዎች ያሉባችሁ ስትሆኑ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 11, '11. የተከበሩ ጸሐፊዎች የሆኑ (ተጠባባቂዎች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 12, '12. የምትሰሩትን (ሁሉ) ያውቃሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 13, '13. (እውነተኞቹ) ደጋጎች በእርግጥም በገነት ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 14, '14.ከሓዲያንም በእርግጥ በገሀነም ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 15, '15.በፍርዱ ቀን ይገቧታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 16, '16.እነርሱም (ምን ጊዜም) ከእርሷ ራቂዎች አይደሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) የፍርዱ ቀን ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 18, '18. ከዚያም የፍርዱ ቀን ምን እንደሆነ ምን አሳወቅህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (82, 19, '19. (እርሱ) ማንኛይቱም ነፍስ ለሌላይቱ ነፍስ ምንም ማድረግ የማትችልበት ቀን ነው:: ነገሩም ሁሉ በዚያ ቀን ለአላህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 1, '1. ለቀሻቢዎች ወዮላቸው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 2, '2. ለእነዚያ ከሰዎች ለመግዛት ባስሰፈሩ ጊዜ የሚያስሞሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 3, '3. እነርሱም (ለሰዎች) በሰፈሩ ወይም በመዘኑላቸው ጊዜ የሚያጎሉ (ለሆኑት)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 4, '4. እነዚያ እነርሱ ተቀስቃሾች መሆናቸውን (በትክክል) አያውቁምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 5, '5. ለታላቁ ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 6, '6. ሰዎች ሁሉ ለዓለማት ጌታ (ፍርድ) በሚቆሙበት ቀን (ተቀስቃሾች መሆናቸውን)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 7, '7. በእውነት የከሓዲያን መዝገብ በእርግጥ በ"ሲጂን" ውስጥ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 8, '8. (መልዕክተኛችን ሙሐመድ ሆይ!) "ሲጂን" ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 9, '9. የታተመ (የተጠናቀቀ) መጽሐፍ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 10, '10. ለአስተባባዮች (ሁሉ) በዚያ ቀን ወዮላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 11, '11. ለእነዚያ በፍርድ ቀን ለሚያስተባብሉት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 12, '12. በእርሱም ወሰን አላፊ ኃጢአተኛ ሁሉ እንጂ ሌላ አያስተባብልም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 13, '13. አናቅጻችን በእርሱ ላይ በተነበቡ ጊዜ እኒህ የመጀመሪያዎቹ ሰዎች ተረቶች ናቸው ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 14, '14. ይከልከሉ፤ ይልቁንም በልቦቻቸው ላይ ይሰሩት የነበሩት ኃጢአት ደገደገባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 15, '15. ይከልከሉ:: እነርሱ በዚያ ቀን ጌታቸውን ከማየት ተጋራጆች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 16, '16. ከዚያ እነርሱ በእርግጥ ገሀነም ገቢዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 17, '17. ከዚያ ይህ ያ በእርሱ ታስተባብሉበት የነበራችሁት ነው ይባላሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 18, '18. የ(እውነተኞቹ) ደጋጎች መጽሐፍ በ"ዒሊዩን" ውስጥ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 19, '19. (መልዕክተኛችን ሙሐመድ ሆይ!) "ዒሊዩን"ም ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 20, '20. የታተመ (የተጠናቀቀ) መጽሐፍ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 21, '21. (የአላህ) ባለሟሎቹ ይጠብቁታል (ይጣዱታል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 22, '22. (እውነተኞቹ) ደጋጎች በእርግጥም በገነት ውስጥ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 23, '23. በተዋቡ ዙፋኖች ላይ የተደገፉ ሆነው ይመለከታሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 24, '24. ከፊቶቻቸው ላይ የድሎትን ውበት ትረዳለህ (ታውቃለህ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 25, '25. ተጣርቶ ከታተመ ወይን ጠጅ ይጠጣሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 26, '26. መደምደሚያው ሚስክ ከሆነ (መጠጥ ይጠጣሉ)። ተሽቀዳዳሚዎች በዚህ ይሽቀዳደሙ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 27, '27. መበረዣዉም ከተስኒም ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 28, '28. (የአላህ) ባለሟሎቹ ከእርሷ የሚጠጡላት ምንጭ ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 29, '29. እነዚያ (በአላህ ላይ) ያመጹት በእነዚያ (በአላህ) ባመኑት በእርግጥ ይስቁ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 30, '30. በእነርሱም አጠገብ ባለፉ ጊዜ ይጠቋቆሙባቸው (ይጠቃቀሱባቸው) ነበር::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 31, '31. ወደ ቤተሰቦቻቸዉም በተመለሱ ጊዜ (በመሳለቃቸው) ተደሳቾች ሆነው ይመለሱ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 32, '32. ባዩዋቸዉም ጊዜ፡- "እነዚህ በእርግጥ ተሳሳቾች ናቸው።" ይሉ ነበር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 33, '33. በእነርሱ ላይ ተጠባባቂዎች ተደርገው ያልተላኩ ሲሆኑ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 34, '34. ዛሬ (በትንሳኤ ቀን) ግን እነዚያ በትክክል በአላህ ያመኑት ሰዎች በከሓዲያን ላይ ይስቃሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 35, '35. በተዋበ ዙፋን ላይ ሆነው የሚመለከቱ ሲሆኑ (ይስቃሉ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (83, 36, '36. ከሓዲያን ይሰሩት የነበሩትን (ዋጋ) ተመነዱን? (ይላሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 1, '1. ሰማይ በተቀደደች (በተሰነጠቀች) ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 2, '2. የጌታዋንም ትዕዛዝ በሰማች ጊዜ፤ (ልትሰማ) ተገባትም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 3, '3. ምድርም በተለጠጠች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 4, '4. በውስጧ ያለውንም ሁሉ በጣለችና ባዶ በሆነች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 5, '5. ለጌታዋም በሰማች ጊዜ፤ (ልትስማ) ተገባትም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 6, '6. አንተ ሰው ሆይ! አንተ ጌታህን በሞት እስከምትገናኝ ድረስ ልፋትን ለፊ ነህ። ተገናኚዉም ነህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 7, '7. ያ! መጽሐፉን በቀኝ እጅ የተሰጠውማ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 8, '8. በእርግጥ ቀላልን ምርመራ ይመረመራል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 9, '9. ወደ ቤተሰቦቹም ተደሳች ሆኖ (በደስታ) ይመለሳል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 10, '10. ያ ! መጽሐፉን በጀርባው በኩል የተሰጠው ግን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 11, '11. (ዋ! ጥፋቴ በማለት) ጥፋትን በእርግጥ ይጠራል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 12, '12. የተጋጋመች እሳትንም ይገባል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 13, '13. እርሱ በቤተሰቡ ውስጥ ተደሳች ነበርና፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 14, '14. እርሱም ወደ አላህ እንደማይመለስ አሰበ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 15, '15. አይደለም (ይመለሳል)፤ ጌታው በእርሱ (መመለስ) አዋቂ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 16, '16. ስለሆነም በወጋገኑ እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 17, '17. በሌሊቱና በሰበሰበዉም ሁሉ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 18, '18. በጨረቃውም በሞላ ጊዜ (እምላለሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 19, '19. ከአንድ እርከን ወደ ሌላ እርከን ትሸጋገራላችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 20, '20. የማያምኑት ለእነርሱ ምን አላቸው ( ምን ሆነው ነው)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 21, '21. በእነርሱ ላይ ቁርኣን በተነበበ ጊዜ የማይሰግዱትስ ለእነርሱ ምን አላቸውና ነው?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 22, '22. በእርግጥ እነዚያ የካዱት ያስተባብላሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 23, '23. አላህ በልቦቻቸው የሚቋጥሩትን ሁሉ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 24, '24. (መልዕክተኛችን ሙሐመድ ሆይ!) በአሳማሚ ቅጣት አብስራቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (84, 25, '25.እነዚያ በአላህ አምነው መልካም ተግባራትን የሰሩት ሲቀሩ፤ ለእነርሱማ የማይቋረጥ ምንዳ አላቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 1, '1. የህብረ ከዋክብት ባለቤት በሆነችው ሰማይ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 2, '2. በተቀጠረዉም ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 3, '3. በመስካሪና በሚመሰከርበትም እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 4, '4. የጉድቡ ባለቤቶች ተረገሙ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 5, '5. የባለማገዶዋ እሳት ባለቤቶች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 6, '6. እነርሱ በርሷ (አፋፍ) ላይ ተቀማጮች በሆኑ ጊዜ (ተረገሙ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 7, '7. እነርሱም በምዕመኖች ላይ ለሚሰሩት (ማሰቃየት) መስካሪዎች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 8, '8. ከእነርሱም በአሸናፊውና በምስጉኑ ጌታ ማመናቸውን እንጂ ሌላን ምንንም አልጠሉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 9, '9. ያ የሰማይና የምድር ንግስና ለእርሱ ብቻ የሆነውን (ነው ያመኑበት)። አላህም በነገሩ ሁሉ ላይ መስካሪ ነው (አዋቂ ነው)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 10, '10. እነዚያ አማኞችና ምዕመናትን ያሰቃዩና ከዚያ ያልተጸጸቱ ሁሉ ለእነርሱ የገሀነም ቅጣት አለላቸው:: ለእነርሱም የመቃጠሉ ስቃይ አልላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 11, '11. እነዚያ በአላህ አምነው መልካም ስራዎችን የሰሩ ሁሉ ለእነርሱ ከስሮቻቸው ወንዞች የሚፈሱባቸው ገነቶች አሏቸው:: ይህ ታላቅ ስኬት ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 12, '12. (መልዕክተኛችን ሙሐመድ ሆይ!) የጌታህ በኃይል መያዝ ብርቱ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 13, '13. እነሆ እርሱ መፍጠርን ይጀምራል፤ ይመልሳልም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 14, '14. እርሱም ምህረቱ የበዛ ወዳድ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 15, '15. የላቀው የዙፋኑ ባለቤት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 16, '16. የሚሻውን ሁሉ ሰሪ (ፈፃሚ) ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ! የእነዚያ ነብያትን ያስተባበሉ) ሰራዊቶች ወሬ መጣልህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 18, '18. የፊርዓውንና የሰሙድ (ወሬ ደርሶሃልን)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 19, '19. በእውነት እነዚያ (በአላህ) የካዱት (ሰዎች ሁሉ) እውነትን በማስተባበል ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 20, '20. አላህም በዙሪያቸው (በዕውቀቱ) ከባቢ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 21, '21. ይልቁንም እርሱ የተከበረ ቁርኣን ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (85, 22, '22. የተጠበቀ በሆነ ሰሌዳ (ሎህ) ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 1, '1. በሰማዩ እና ሌሊት በሚመጣውም እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) የሌሊት መጪው ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 3, '3. ጨለማውን ሰንጣቂ ኮከብ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 4, '4. ነፍስ ሁሉ በእርሷ ላይ ጠባቂ ያለባት እንጂ ሌላ አይደለችም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 5, '5. የሰው ልጅ ከምን እንደተፈጠረ ይመልከት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 6, '6. ከተስፈንጣሪ ውሃ (የዘር ፈሳሽ) ተፈጠረ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 7, '7. ከጀርባና ከእርግብግቢቶች መካከል የሚወጣ ከሆነ የዘር ፈሳሽ ውሃ (ተፈጠረ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 8, '8. አላህ እርሱን በመመለሱ ላይ በእርግጥ ቻይ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 9, '9. ሚስጥሮች በሚገለጹበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 10, '10. (ለሰው) ምንም ኃይልና ረዳት አይኖረዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 11, '11. የመመለስ ባለቤት (ዝናባማ) በሆነችው ሰማይ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 12, '12. (በበቃይ) የመሰንጠቅ ባለቤት በሆነችው ምድርም እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 13, '13. እርሱ (ቁርኣን)፤ (እውነትን ከውሸት) የሚለይ (የአላህ) ቃል ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 14, '14. እርሱም ቀልድ አይደለም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 15, '15. እነርሱ በእርግጥ ተንኮልን ያሴራሉ (ይሸርባሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 16, '16. እኔ ተንኮልንም እመልሳለሁ (አመክናለሁ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (86, 17, '17. (መልዕክተኛችን ሙሐመድ ሆይ!) ከሓዲያንን ቀን ሰጣቸው:: ጥቂትን ጊዜ አቆያቸው (ታገሳቸው)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) የዚያን ከሁሉ በላይ የሆነውን ጌታህን ስም አጥራ (አሞግስ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 2, '2. ያ ሁሉን ነገር የፈጠረውንና ያስተካከለውን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 3, '3. ያን የወሰነውን ነገርንም ሁሉ ለተፈጠረለት የመራውን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 4, '4. ያም ግጦሽን ለምለም አርጎ ያወጣውን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 5, '5.(ከዚያ) ደረቅ ጥቁር ያደረገውንም (አምላክ ስም አሞግስ)፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 6, '6. (መልዕክተኛችን ሙሐመድ ሆይ!) ቁርኣንን በእርግጥ እናስነብብሃለን፤ አትረሳምም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 7, '7. አላህ ከፈለገው ነገር በስተቀር፤ እናም እርሱ ግልጹንም የሚሸሽገውንም ሁሉ ያውቃልና፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 8, '8. ለገሪቱም (ሕይወት እስላምን ትከተል ዘንድ) እናገራሃለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 9, '9. (ሰዎችንም) ገስፅ፤ ግሳፄይቱ ብትጠቅም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 10, '10. (አላህን) የሚፈራ በእርግጥ ይገሰፃል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 11, '11. መናጢዉም ይርቃታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 12, '12. ያ! ታላቂቱን እሳት የሚገባው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 13, '13. ከዚያም በእርሷ ውስጥ የማይሞትና ህያዉም የማይሆነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 14, '14. (አላህን ከማመፅ) የተጥራራ ሰው በእርግጥ ዳነ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 15, '15. የጌታውንም ስም ያወሳና የሰገደ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 16, '16. ይልቁንም ቅርቢቱን ሕይወት ታስቀድማላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 17, '17. (ሰዎች ሆይ!) መጨረሻይቱ ሕይወት በላጭና፤ ዘወታሪ ሆና ሳለ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 18, '18. ይህ በቀደምቶቹም መጻሕፍት ውስጥ ያለ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (87, 19, '19. በኢብራሂምና በሙሳ መጽሐፍት ውስጥ የሰፈረ እውነታ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) የሸፋኝቱ ትንሳኤ ወሬ መጣልህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 2, '2. በዚያ ቀን የከሓዲያን ፊቶች ተዋራጆች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 3, '3. ሰሪዎች ለፊዎች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 4, '4. የምታቃጥልን እሳት ይገባሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 5, '5. በጣም ከፈላች ምንጭም ይጋታሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 6, '6. ዶሪዕ ከሚባል (እሾሃማ) ዛፍ እንጂ ሌላ ምግብ የላቸዉም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 7, '7. አካልን አያሰባ፤ ከረኃብም አያብቃቃ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 8, '8. (የአማንያን) ፊቶች በዚያ ቀን ተቀማጣዮች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 9, '9. በስራቸውም ተደሳቾች ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 10, '10. በከፍተኛ ገነት ውስጥ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 11, '11. በውስጧ ውድቅን ነገር አይሰሙም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 12, '12. በውስጧ ፈሳሾች ምንጮች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 13, '13. በውስጧ ከፍ የተደረጉ አልጋዎች አሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 14, '14. በተርታ የተኖሩ ኩባያዎችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 15, '15. የተደረደሩ መከዳዎችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 16, '16. የተነጠፉ ስጋጃዎችም (አሉ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 17, '17. (ከሓዲያን) ግመል እንዴት እንደተፈጠረች አይመለከቱምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 18, '18. ሰማይም እንዴት ከፍ እንደተደረገች!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 19, '19. ተራራዎችም እንዴት እንደ ተቸከሉ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 20, '20. ምድርም እንዴት እንደተዘረጋች አይመለከቱምን?!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 21, '21. (መልዕክተኛችን ሙሐመድ ሆይ!) አስታውስም:: አንተ አስታዋሽ ብቻ ነህና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 22, '22. በእነርሱ ላይ አስገዳጅ (ተሿሚ) አይደለህም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 23, '23. ግን ከእውነት የዞረና የካደ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 24, '24. አላህም ከባዱን ቅጣት ይቀጣዋል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 25, '25. መመለሻቸው ወደ እኛ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (88, 26, '26. ምርመራቸዉም በእኛ ላይ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 1, '1. በጎህ፤ እምላለሁ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 2, '2. በአስሩ ሌሊቶችም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 3, '3. በጥንዱም በነጠላዉም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 4, '4. በሌሊቱም በሚጓዝበት ጊዜ እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 5, '5. በዚህ መሀላ ለባለ አእምሮ ታላቅ መሀላ የለበትምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 6, '6. ጌታህ በዓድ ህዝቦች ላይ እንዴት እንደሰራ አላወክምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 7, '7. በባለ ረዣዥሚቱ አዕማድ ኢረም ላይም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 8, '8. በዚያች ብጤዋ በአገሮች ውስጥ ያልተፈጠረ በሆነችው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 9, '9. በእነዚያ (በሸለቆዎች) ቋጥኝን የቦረቦሩ በሆኑት ሰሙድም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 10, '10. ባለ ችካሎች በሆነው ፈርዖንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 11, '11. በእነዚያ በአገሮች ላይ ግፍ የሰሩ (በሆኑትም ላይ)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 12, '12. በእርሷም ውስጥ ጥፋትን ያበዙ በሆኑት (እንዴት እንደሰራ አታውቅምን?)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 13, '13. በእነርሱ ላይም ጌታህ የቅጣትን አለንጋ አወረደባቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 14, '14. ጌታህ በመጠባበቂያ ላይ ነውና::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 15, '15. የሰው ልጅ ጌታው በሞከረው ጊዜ ባከበረውና ባጣቀመው ጊዜ ጌታየ አከበረኝ (አበለጠኝ) ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 16, '16. በሞከረውና በእርሱ ላይ ሲሳዩን ባጠበበበት (ጊዜ) እንዲሁ ጌታየ አሳነሰኝ ይላል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 17, '17. በፍፁም! ይልቁንም የቲምን አታከብሩም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 18, '18. ድሃንም በማብላት ላይ አትበረታቱም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 19, '19. የውርስንም ገንዘብ የመሰብሰብን አበላል (ያለአግባብ) ትበላላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 20, '20. ገንዘብንም አብዝታችሁ (አለቅጥ) ትወዳላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 21, '21. (ሰዎች ሆይ! ተዉ):: ታቀቡ:: ምድር ደጋግማ በተንኮታኮተች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 22, '22. ጌታህ በመጣና መላዕክትም በሰልፍ በሰልፍ ሆነው በመጡ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 23, '23. ገሀነምም በዚያ ቀን በተመጣች ጊዜ በዚያ ቀን ሰው ሁሉ ጥፋቱን በትክክል ይገነዘባል። መገንዘቡ በየት በኩል (ይጥቀመው)?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 24, '24. "ወይ እኔ! ምነው በሕይወቴ (መልካምን ስራ) ባስቀደምኩ ኖሮ" ይላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 25, '25. በዚያ ቀንም የእርሱን አቀጣጥ የመሰለ አንድም አካል አይቀጣም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 26, '26. የእርሱንም፤አሰተሳሰር አንድም አካል አያስርም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 27, '27. (ለአመነች ነፍስም እንዲህ ትባላለች)፡- አንቺ በአላህ የረካሺው ነፍስ ሆይ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 28, '28. (ከእርሱም) የወደድሽ፤ (እርሱ ዘንድም) የተወደደሽ ሆነሽ ወደ ጌታሽ ተመለሺ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 29, '29. ከዉድ ባሮቼም ጋር ተቀላቀይ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (89, 30, '30. ወደ ገነቴም ግቢ ትባላለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 1, '1. በዚህ ሀገር (በመካ) እምላለሁ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 2, '2.(መልዕክተኛችን ሙሐመድ ሆይ!) አንተ በዚህ አገር ሰፋሪ ስትሆን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 3, '3.በወላጂና በወለዳቸውም (በአደምና በዘሮቹ) ሁሉ (እምላለሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 4, '4. ሰውን ሁሉ በእርግጥ በልፋት ውስጥ ሆኖ ፈጠርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 5, '5. በእርሱ ላይ አንድም አካል የማይችል መሆኑን ይጠረጥራልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 6, '6. "ብዙን ገንዘብ አጠፋሁ" ይላል፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 7, '7. አንድም ያላየው መሆኑን ያስባልን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 8, '8. ለእርሱ ሁለት አይኖችን አላደረግንለትንምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 9, '9. አንድ ምላስንና ሁለት ከንፈሮችንም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 10, '10.ሁለትን መንገዶችስ አልመራነዉምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 11, '11.ዐቀበቱን አልወጣም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 12, '12.ዐቀበቱን መውጣት ምን እንደሆነ ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 13, '13.ያ ጫንቃን መልቀቅ ነው። {1}', '{1} ባሪያን ነጻ ማውጣት ማለት ነው');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 14, '14. ወይም የረሀብ ባለቤት በሆነ ቀን (ረሀብተኛን) ማብላት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 15, '15. የዝምድና ባለቤት የሆነን የቲም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 16, '16.ወይም የአፈር ባለቤት የሆነን (ችግረኛ) ማብላት ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 17, '17.ከዚያም ከእነዚያ በአላህ ካመኑትና በመታገስ ላይ አደራ ከተባባሉት ሰዎች ጋር መሆን ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 18, '18. እነዚያ (ይህንን የፈጸሙ) የቀኝ ጓዶች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 19, '19. እነዚያ በአናቅጻችን የካዱ ሁሉ እነርሱ የግራ ጓዶች ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (90, 20, '20. ለእነርሱ የምትዘጋባቸው እሳትም አለች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 1, '1. በጸሐይና በብርሀኗ፤ (እምላለሁ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 2, '2. በጨረቃም ጸሐይን በተከተላት ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 3, '3. በቀንም ጸሐይን በገለፃት ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 4, '4. በሌሊቱም ጸሐይን በሸፈናት ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 5, '5. በሰማይ እና በገነባትም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 6, '6. በምድር እና በዘረጋትም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 7, '7. በነፍስም ባስተካከላትም', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 8, '8. አመጽዋንና ፍርሃቷንም ባሳወቃት (አምላክም በአላህ እምላለሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 9, '9. (ነፍስን) ከኃጢአት ያጠራ ሰው ሁሉ በእርግጥ ተሳካለት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 10, '10. በኃጢአትም የሸፈናት ሰው ሁሉ በእውነት አፈረ (ከሰረ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 11, '11. ሰሙድ ወሰን በማለፍዋ ምክንያት አስተባበለች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 12, '12. ጠማማዋ በተነሳ ጊዜ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 13, '13. ለእነርሱም የአላህ መልዕክተኛ (ሷሊህ)፡-የአላህን ግመልና የመጠጥ ተራዋን (ጠብቁላት) አላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 14, '14. እነርሱ አስተባበሉትም፤ ከዚያ ወጓት፤ በኃጢአታቸዉም ምክንያት ጌታቸው (ቅጣትን) በእነርሱ ላይ ደመደመባቸው፤ አስተካከላትም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (91, 15, '15. (የምታስተካክለውን) ፍፃሜዋንም አይፈራም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 1, '1. በሌሊቱ (ጨለማውን) በሚሸፍነው ጊዜ፤ (እምላለሁ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 2, '2. በቀኑም በተገለጸ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 3, '3. ወንድንና ሴትን በፈጠረዉም (አምላክ) እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 4, '4. ስራችሁ በእርግጥ የተለያየ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 5, '5. ያ! የሰጠና ጌታውንም የፈራማ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 6, '6. በመልካሚቱ እምነትም ያረጋገጠ ሰው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 7, '7. ለገሪቱ እናገራዋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 8, '8. ያ! የሰሰተ በራሱም የተብቃቃ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 9, '9. በመልካሚቱም ያስተባበለውማ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 10, '10. ለክፋት እናዘጋጀዋለን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 11, '11. ገሀነም በወደቀ ጊዜ ያ! ገንዘቡ ከእርሱ ምንም አይጠቅመዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 12, '12. ቅኑን መንገድ መግለጽ በእኛ ላይ አለብን።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 13, '13. መጨረሻይቱም መጀመሪያይቱም ዓለም የእኛው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 14, '14. የምትንቀለቀል እሳት አስጠነቀቅኳችሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 15, '15. ከጠማማ በስተቀር የማይገባባትን', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 16, '16. ያ ያስተባበለና ከትዕዛዝም የሸሸ እድለ ቢስ (ነው የሚገባባት)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 17, '17. አላህን በጣም ፈሪ የሆነ በእርግጥ ይርቃታል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 18, '18. ያ (ከወንጀል) የሚጥራራ ሲሆን ገንዘቡን የሚለግስ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 19, '19. ለአንድም ሰው በእርሱ ዘንድ ተመላሽ የሚሆን ውለታ ሳይኖርበት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 20, '20. የታላቁን ጌታውን የአላህን ውዴታ በመፈለግ ብቻ (ይህንን የሰራ) ሲቀር።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (92, 21, '21. እርሱማ ወደ ፊት (በሚሰጠው) በእርግጥ ይደሰታል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 1, 'በረፋዱም፤ (እምላለሁ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 2, '2. በሌሊትም ጸጥ ባለ ጊዜ እምላለሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ አላሰናበተህም፤ አልጠላህምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 4, 'የመጨረሻይቱ ዓለም ከመጀመሪያይቱም ይልቅ ላንተ በላጭ ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 5, 'ጌታህም ወደ ፊት ብዙ ስጦታ በእርግጥ ይሰጥሃል። ትደሰታለህም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 6, '6. የቲም ሆነህ አላገኘህምና አላስጠጋህምን? (አስጠግቶሃል)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 7, '7. የሳትክም ሆነህ አገኘህና መራህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 8, '8. ደሃም ሆነህ አገኘህና አከበረህ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 9, '9. እናም የቲምን አትጨቁን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 10, '10. ለማኝንም አትገላምጥ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (93, 11, '11. የጌታህንም ጸጋ ግለጽ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) ልብህን ላንተ አላሰፋንልህም?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 2, '2. ሸክምህንም አወረድንልህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 3, '3. ያንን ጀርባህን ያከበደውን (ሸክም)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 4, '4. መወሳትህንም ከፍ አላደረግንልህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 5, '5. እናም ከችግር ጋር በእርግጥ ምቾት አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 6, '6. ከችግር ጋር በእርግጥ ምቾት አለ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 7, '7. (የጀመርከውን ጥሩ ስራ) በጨረስክ ጊዜ ወደ ሌላ ጥሩ ስራ ቀጥል (አስከትል)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (94, 8, '8. ክጃሎትህንም ወደ ጌታህ ብቻ አድርግ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 1, '1. በበለስና፤ በወይራ ዛፍ እምላለሁ፣', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 2, '2. በሲና ተራራም፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 3, '3. በዚህ በጸጥተኛው (ጸጥታ በነገሰበት) አገር መካም እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 4, '4. በርግጥ ሰውን በጣም በአማረ አቋም ላይ ፈጠርነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 5, '5. ከዚያም (ከፊሉን) ከበታቾች ሁሉ በታች አድርገን መለስነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 6, '6. እነዚያ በአላህ ያመኑትና መልካም ተግባራት የሰሩት ሲቀሩ ለእነርሱማ የማይቋረጥ
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 7, '7. (የሰው ልጅ ሆይ) ታዲያ ከዚህ (እውነታ) በኋላ በፍርዱ ምን አስተባባይ አደረገህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (95, 8, '8. አላህ ከፈራጆች ሁሉ ይበልጥ ፈራጅ አይደለምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) በዚያ (ሁሉንም ነገር) በፈጠረ ጌታህ ስም (ጀምርና) አንብብ! {1}', '{1} ይህ አንቀጽና ቀጥሎ ያሉት ከቁርአን መጀመሪያ የወረዱ አንቀጾች ናቸው። በኑር ተራራ ላይ በምገኘው የሂራእ ዋሻ ውስጥ ነቢዩ ሰ/ዐ/ወ/ ኸልዋ ወጥተው እያሉ ነው የወረደባቸው። (ቡኻሪና ሙስሊም፤ የወህይ አጀማመር ምእራፍ)');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 2, '2. ሰውን ከረጋ ደም በፈጠረው (ጌታህ ስም)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) አንብብ! ጌታህም በጣም ቸር ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 4, '4. ያ በብዕር ያስተማረ (ጌታ)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 5, '5. የሰውን ልጅ ያላወቀውን ሁሉ ያሳወቀ (ጌታ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 6, '6. በእውነቱ የሰው ልጅ ወሰንን ያልፋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 7, '7. ራሱን የተብቃቃ ሆኖ በማየቱ ምክንያት', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 8, '8. መመለሻው ወደ ጌታህ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 9, '9. ያንን የሚከለክለውን አየህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 10, '10. ባሪያን በሰገደ ጊዜ (የሚከለክለውን):', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 11, '11. እስቲ ንገረኝ (ተከልካዩ ባሪያየ) በትክክል መንገድ ላይ ቢሆን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 12, '12. ወይም (ፈጣሪውን) በመፍራት ቢያዝ ምን እንደሚሆን አየህን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 13, '13. እስቲ ንገረኝ (ከልካዩ) ቢያስተባብልና ከእምነት ቢሸሽ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 14, '14. አላህ የሚያይ መሆኑን አያውቅምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 15, '15. ይታቀብ፤ የማይከለከል ከሆነ አናቱን ይዘን አንጎትተዋለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 16, '16. ያቺን ውሸታምና ስህተተኛ የሆነችውን አናቱን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 17, '17. ሸንጎውንም ይጥራ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 18, '18. እኛም ዘበኞቻችንን እንጠራለን::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (96, 19, '19. በጭራሽ፤ (መልዕክተኛችን ሙሐመድ ሆይ!) ይህን ለሚል ከሓዲ አትታዘዘው፤ ስገድ፤ ወደ አላህም ተቃረብ። {1}', '{1} እዚህ የንባብ ሱጁድ አለ። ይህ የመጨረሻ ሱጁድ ነው።');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (97, 1, '1. እኛ (ቁርኣንን) በመወሰኛይቱ ሌሊት ውስጥ አወረድነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (97, 2, '2. (መልዕክተኛችን ሙሐመድ ሆይ!) የመወሰኛይቱ ሌሊት ምን እንደሆነች ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (97, 3, '3. የመወሰኛይቱ ሌሊት ከሺህ ወር የምትበልጥ ነች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (97, 4, '4. በእርሷ ውስጥ መላዕክትና ሩሕም (ጂብሪል) በጌታቸው ፈቃድ በሁሉም ጉዳዮች ይዘው ይወርዳሉ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (97, 5, '5. እርሷም ጎህ እስኪወጣ ድረስ ሰላም ነች።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 1, '1. ከመጽሐፍ ባለቤቶችና ከአጋሪዎች እነዚያ በአላህ የካዱት ሰዎች ግልጽ አስረጂ እስኪመጣላቸው ድረስ (ከነበሩበት አቋም) ተወጋጆች አልነበሩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 2, '2. (አስረጂውም) የተጥራሩ (መጽሐፎችን) የሚያነብ ከአላህ የሆነ መልዕክተኛ ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 3, '3. በውስጧም ቀጥተኛ የሆኑ ጹሁፎች ያሉባት የሆነችን (አስረጂ)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 4, '4. እነዚያ መጽሐፉን የተሰጡ ሰዎችም ግልጽ አስረጂ ከመጣላቸው በኋላ እንጂ አልተለያዩም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 5, '5. ሃይማኖትን ለአላህ ብቻ አጥሪዎችና ቀጥተኞች ሆነው አላህን ሊገዙት፤ ሶላትንም አስተካክለው ሊሰግዱ፤ ዘካንም በትክክል ሊሰጡ እንጂ ያልታዘዙ ሲሆን ተለያዩ:: የቀጥተኛይቱ ሃይማኖት ድንጋጌም ይሀው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 6, '6. ከመጽሐፉ ባለቤቶችና ከአጋሪዎች እነዚያ የካዱት በውስጧ ዘውታሪዎች በሚሆኑባት የገሀነም እሳት ውስጥ ናቸው:: እነዚያ ከፍጥረቱ ሁሉ መጥፎዎቹ እነርሱ ናቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 7, '7. እነዚያ በትክክል አምነው በጎ ተግባራትንም የሰሩት እነዚያ ከፍጥረት ሁሉ በላጭ (ምርጦች) የሆኑት እነርሱ ናቸው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (98, 8, '8. ምንዳቸውም በስሮቻቸው ወንዞች የሚፈሱባቸው ከጌታቸው ዘንድ የሚቸሯቸው የመኖሪያ ገነቶች ናቸው። በውስጣቸው ለዘልዓለም ዘወታሪዎች ሲሆኑ ይገቡባቸዋል:: አላህ ከእነርሱ ስራቸውን ወደደላቸው:: እነርሱም ከእርሱ ምንዳውን ወደዱ:: ይህ እድል ጌታውን ለፈራ ሁሉ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) ምድር በኃይል መንቀጥቀጧን በተንቀጠቀች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 2, '2. ምድርም ሸክሞቿን ባወጣች ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 3, '3. ሰዉም "ምን ሆነች?" ባለ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 4, '4. በዚያ ቀን ወሬዎቿን ትናገራለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 5, '5. ጌታህ ለእርሷ አሳውቋታልና፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 6, '6. በዚያ ቀን ሰዎች ሁሉ ስራዎቻቸውን እንዲያዩ ይደረጉ ዘንድ እንደየስራቸው የተበታተኑ ሆነው ከየመቃብራቸው ወደ መቆሚያው ስፍራ ይመለሳሉ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 7, '7. የብናኝን ክብደት ያህል መልካም የሰራ ሰው ያገኘዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (99, 8, '8. የብናኝን ክብደት ያህል ክፋት የሰራ ሰውም ያገኘዋል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 1, '1. እያለከለኩ ሩዋጮች በሆኑ (ፈረሶች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 2, '2. ምድርን በሸሆናቸው እያጋጩ የእሳት ብልጭታን አውጪዎች በሆኑትም (ፈረሶች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 3, '3. በማለዳ (በጧት) ወራሪዎች በሆኑትም ፈረሶች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 4, '4. በእርሱም አቧራን በቀሰቀሱት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 5, '5.በፈረሰኞቻቸው በኩል (የጠላት) ስብስብ መሀልን በተጋፈጡትም (ፈረሶች) እምላለሁ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 6, '6. የሰው ልጅ ለጌታው ብርቱ ከሓዲ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 7, '7. እርሱም በዚያ ክህደቱ ላይ መስካሪ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 8, '8. እርሱም ገንዘብን በመውደድ ላይ በጣም ብርቱ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 9, '9. የሰው ልጅ በመቃብሮች ዉስጥ ያሉት ሙታን ሁሉ በተቀሰቀሱ ጊዜ ምን እንደሚከሰት አያውቅምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 10, '10. በልቦች ውስጥ ያለዉም ሁሉ በተገለጸ ጊዜ እንዴት እንደሚሆን አያውቅምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (100, 11, '11. ጌታቸው በዚያ ቀን በእነርሱ ነገር በእርግጥ ውስጠ አዋቂ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 1, '1. ቆርቋሪይቱ (ጩኸት)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 2, '2. ቆርቋሪይቱ (ጩኸት) ምንድን ናት!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 3, '3. (መልዕክተኛችን ሙሐመድ ሆይ!) ቆርቋሪይቱ ምን እንደሆነች ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 4, '4. ሰዎች እንደተበታተነ ቢራቢሮ (ኩብኩባ) የሚሆኑበት ቀን፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 5, '5. ጋራዎችም እንደ ተነደፈ ሱፍ የሚሆኑበት (አስደንጋጭ ቀን) ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 6, '6. በዚያ ዕለት ያ ሚዛኖቹ የከበዱለት ሰውማ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 7, '7. እርሱ ኑሮው በአሰደሳቿ ጀነት ውስጥ ይሆናል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 8, '8. ያ ሚዛኖቹ የቀለሉበት ሰው ደግሞ', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 9, '9. መኖሪያው ሃዊያህ (የምትባል የገሀነም እሳት) ናት።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 10, '10. (መልዕክተኛችን ሙሐመድ ሆይ!) እርሷ ምን እንደሆነች ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (101, 11, '11. (እርሷ) በጣም ተኳሳ እሳት ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 1, '1. (በዚህች ዓለም ጸጋዎች) ብዛት መፎካከር (ጌታችሁን ከመገዛት) አዘናጋችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 2, '2. መቃብሮችን እስከጎበኛችሁ ድረስ:: (በዚሁ ላይ ቀጠላችሁ)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 3, '3. ከዚህ ተግባራችሁ ተከልከሉ (ታቀቡ):: ወደፊት (ውጤቱን) ታውቃላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 4, '4. ከዚያም ከዚህ ተግባራችሁ ተከልከሉ። ወደ ፊትም ታውቃላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 5, '5. በእውነቱ (የሚጠብቃችሁን) በእርግጠኝነት ብታውቁ ኖሮ (ይህን ያክል ባልተዘናጋችሁ ነበር)።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 6, '6. ገሀነምን በእርግጥ ታያላችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 7, '7. ከዚያም እርግጠኛን ማየት ታዩዋታላችሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (102, 8, '8. ከዚያም በድሎታችሁ ጉዳይ ሁሉ በዚያ ቀን ትጠየቃለችሁ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (103, 1, '1. በጊዜ እምላለሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (103, 2, '2. ሰው ሁሉ በእርግጥ በኪሳራ ውስጥ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (103, 3, '3. እነዚያ በአላህ በትክክል ያመኑትና መልካሞችን የሰሩ፤ በእውነትም ላይ አደራ የተባባሉ፤ በመታገስም ላይ አደራ የተባባሉ ብቻ ሲቀሩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 1, '1. ለሐሜተኛ፤ ለዘላፊ፤ (ለአሽሟጣጭ ሁሉ) ወዮለት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 2, '2. ለዚያ ገንዘብን የሰበሰበና የቆጣጠረው (ያደለበዉም) ለሆነ ሁሉ፡፡', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 3, '3. ገንዘቡ በዚህች ዓለም ዘውታሪ እንደሚያደርገው ያስባል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 4, '4. በጭራሽ፤ አውዳሚና የምትፈጭ በሆነችው እሳት ውስጥ በእርግጥ ይጣላል።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 5, '5. (መልዕክተኛችን ሙሐመድ ሆይ!) የምትፈጨዋም ምን እንደሆነች ምን አሳወቀህ?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 6, '6. የተቀጣጠለችው የአላህ እሳት ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 7, '7. ያቺ በልቦች ላይ እንኳን ሳይቀር የምትዘልቅ የሆነች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 8, '8. እርሷ በእርግጥ በእነርሱ ላይ የተዘጋች ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (104, 9, '9. በተዘረጋች አዕማድ ውስጥ የተዘጋች ናት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (105, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) ጌታህ አላህ በዝሆኑ ባለቤቶች ላይ እንዴት እንደሰራ አላወቅክምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (105, 2, '2. ተንኮላቸውን በጥፋት ውስጥ ከንቱ አላደረገምን?', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (105, 3, '3. በእነርሱ ላይ መንጎች የሆኑን ወፎችንም ላከ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (105, 4, '4. ከተጠበሰ ጭቃ የሆነን ጠጠር የምትወረውርባቸውን የሆነችን (አእዋፍ)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (105, 5, '5. እና ቅጠሉ እንደ ተበላ አዝመራ አደረጋቸው', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (106, 1, '1. ቁረይሽን ለማላመድ (ባለ ዝሆኖቹን አጠፋ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (106, 2, '2. የክረምትንና የበጋን ወራት ጉዞዎች ሊያላምዳቸው ይህንን ሰራ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (106, 3, '3. ስለዚህም የዚህን ቤት (የካዕባን) ጌታ ብቻ ያምልኩ::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (106, 4, '4. ያንን ከርኃብ ያበላቸውን፤ ከፍርሃትም ያዳናቸውን (ጌታ ብቻ ያምልኩ)::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) ያንን በምርመራው ቀን የሚያስተባብለውን ሰው አየህን? (አወከውን?)', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 2, '2. ይሀውም ያ የቲምን በኃይል የሚገፈትረው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 3, '3. ድሃን በማብላት ላይም የማያነሳሳው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 4, '4. ወዮላቸው ለሰጋጆች፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 5, '5. ለእነዚያ እነርሱ ከስግደታቸው ዘንጊዎች ለሆኑት (ሰጋጆች)፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 6, '6. ለእነዚያ እነርሱ ይዩልኝ ባዮች ለሆኑት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (107, 7, '7. የዕቃ ትውስትንም ሰዎችን የሚከለክሉ ለሆኑት ሁሉ ወዮላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (108, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) እኛ በጣም ብዙ በጎ ነገሮችን ሰጠንህ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (108, 2, '2. ስለዚህ ለጌታህ ብቻ ስገድ:: በስሙም ብቻ ሰዋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (108, 3, '3. የሚጠላህ ሁሉ እርሱ በእርግጥ ዘሩ የተቆረጠው ነው።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (109, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!)- (ለካሓዲያን እንዲህ) በላቸው፡- እናንተ ከሓዲያን ሆይ!', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (109, 2, '2.ያንን የምትገዙትን (ጣዖት አሁን) አልገዛም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (109, 3, '3.እናንተም እኔ የምገዛውን (አምላክ አሁን) ተገዢዎች አይደላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (109, 4, '4. እኔም ያንን የተገዛችሁትን (ወደ ፊት) ተገዢ አይደለሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (109, 5, '5. እናንተም እኔ የምገዛውን (ወደ ፊት) ተገዢዎች አይደላችሁም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (109, 6, '6. እናንተ የራሳችሁ ሃይማኖት አላችሁ:: እኔም የራሴ ሃይማኖት አለኝ -በላቸው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (110, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ!) የአላህ እርዳታና (የመካ) መከፈት በመጣ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (110, 2, '2. ሰዎችም ቡድን ቡድን እየሆኑ ወደ አላህ ሃይማኖት ሲገቡ ባየህ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (110, 3, '3. ጌታህን ከማመስገን ጋር አጥራው። ምህረትንም ለምነው፤ እርሱ ጸጸትን በጣም ተቀባይ ነውና።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (111, 1, '1. የአቡ ለሀብ ሁለት እጆች ከሰሩ፤ (ጠፉ)፤ እርሱም ጠፋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (111, 2, '2.ገንዘቡም ያም ያፈራው ሁሉ ምንም አልጠቀመዉም', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (111, 3, '3.የመንቀልቀል ባለቤት የሆነችን እሳት በእርግጥ ይገባል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (111, 4, '4.ሚስቱም ትገባለች፤ እንጨት ተሸካሚዋ።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (111, 5, '5.በአንገቷ ላይ የጭረት ገመድ ያለባት ስትሆን ትገባለች::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (112, 1, '1. (መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) በል፡ -እርሱ አላህ አንድ ብቻ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (112, 2, '2.አላህ የሁሉ ነገር መጠጊያ ነው::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (112, 3, '3.አልወለደም፤ አልተወለደምም::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (112, 4, '4. ለእርሱም አንድም ብጤ የለዉም።', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (113, 1, '1.(መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) በል፡ -በተፈልቃቂው ጎህ (በአል-ፈለቅ) ጌታ እጠበቃለሁ፤-', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (113, 2, '2.ከፈጠረው ፍጡር ሁሉ ክፋት::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (113, 3, '3.ከሌሊትም ክፋት በጨለመ ጊዜ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (113, 4, '4. በቋጠሮዎች ላይ ተፊዎች ከሆኑት ደጋሚ ሴቶችም ክፋት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (113, 5, '5. ከምቀኛም ክፋት፤ በተመቀኘ ጊዜ (በአሏህ) -እጠበቃለሁ- በል::', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (114, 1, '1.(መልዕክተኛችን ሙሐመድ ሆይ! እንዲህ) በል፡ -የሰዎች ሁሉ ፈጣሪ በሆነው ጌታ እጠበቃለሁ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (114, 2, '2.የሰዎች ሁሉ ንጉስ በሆነው ጌታ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (114, 3, '3.የሰዎች ሁሉ አምላክ በሆነው ጌታ፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (114, 4, '4. ከዚያ ብቅ እልም ባይ ከሆነው ጎትጓች ክፋት፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (114, 5, '5. ከዚያ በሰዎች ልቦች ውስጥ የሚጎተጉት ከሆነው፤', '');
INSERT INTO `amharic_zain` (sura, aya, text, footnotes) VALUES (114, 6, '6. ከጂንም ይሁን ከሰው ሰይጣን ክፋት (እጠበቃለሁ)።', '');
